/* =========================================================
   DETOXBLANC — Brand Stylesheet
   Palette : champagne gold, ivory cream, charcoal, blush
   Type    : Cormorant Garamond (display) · Inter (body)
   ========================================================= */

:root{
  --ivory:       #F8F5F0;
  --cream:       #F1EBE2;
  --blush:       #F4E8E1;
  --sand:        #E6DBCB;
  --gold:        #C9A961;
  --gold-dark:   #A8883F;
  --charcoal:    #1C1C1C;
  --ink:         #2A2A2A;
  --muted:       #6E6A63;
  --line:        #E6DFD3;
  --sage:        #8B9D83;
  --white:       #ffffff;
  --radius:      18px;
  --radius-sm:   10px;
  --shadow-sm:   0 2px 10px rgba(28,28,28,.06);
  --shadow:      0 12px 40px rgba(28,28,28,.08);
  --shadow-lg:   0 24px 60px rgba(28,28,28,.14);
  --ease:        cubic-bezier(.2,.7,.2,1);
  --container:   1240px;
}

*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  font-family:'Inter', system-ui, -apple-system, sans-serif;
  color:var(--ink);
  background:var(--ivory);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer}

.container{max-width:var(--container);margin:0 auto;padding:0 28px}
.center{text-align:center}
.mt-24{margin-top:24px}
.mt-40{margin-top:40px}

/* ---------- Typography ---------- */
h1,h2,h3,h4{font-family:'Cormorant Garamond', serif;font-weight:500;color:var(--charcoal);margin:0;letter-spacing:-.01em}
h1{font-size:clamp(2.4rem,5vw,4.4rem);line-height:1.05;font-weight:500}
h2{font-size:clamp(2rem,3.6vw,3.2rem);line-height:1.1}
h3{font-size:1.35rem;line-height:1.25;font-weight:600}
h4{font-size:1.05rem;color:var(--charcoal)}
em{font-style:italic;color:var(--gold-dark);font-weight:500}

.eyebrow{
  font-family:'Inter',sans-serif;
  font-size:.72rem;
  font-weight:600;
  letter-spacing:.22em;
  color:var(--gold-dark);
  text-transform:uppercase;
  display:inline-block;
  margin-bottom:14px;
}
.eyebrow.light{color:var(--gold)}

.underline{background:linear-gradient(transparent 62%, rgba(201,169,97,.35) 62%);padding:0 2px}

.section-head{margin-bottom:56px;text-align:center}
.section-head.between{
  display:flex;justify-content:space-between;align-items:flex-end;
  text-align:left;flex-wrap:wrap;gap:24px;
}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:14px 26px;border-radius:999px;border:1px solid transparent;
  font-weight:600;font-size:.9rem;letter-spacing:.02em;
  transition:all .25s var(--ease);
}
.btn i{font-size:.85em}
.btn-primary{background:var(--charcoal);color:var(--ivory)}
.btn-primary:hover{background:var(--gold-dark);transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-dark{background:var(--charcoal);color:var(--ivory)}
.btn-dark:hover{background:var(--gold-dark)}
.btn-outline{background:transparent;border-color:var(--charcoal);color:var(--charcoal)}
.btn-outline:hover{background:var(--charcoal);color:var(--ivory)}
.btn-ghost{background:transparent;color:var(--charcoal);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--charcoal)}
.btn-block{display:flex;width:100%;justify-content:center}

.link-arrow{
  display:inline-flex;align-items:center;gap:8px;
  font-weight:600;font-size:.9rem;color:var(--charcoal);
  border-bottom:1px solid var(--charcoal);padding-bottom:3px;
  transition:all .25s var(--ease);
}
.link-arrow:hover{color:var(--gold-dark);border-color:var(--gold-dark);gap:14px}

/* ---------- Topbar ---------- */
.topbar{
  background:var(--charcoal);color:#d9d4c7;font-size:.8rem;
  padding:9px 0;letter-spacing:.02em;
}
.topbar-inner{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.topbar i{color:var(--gold);margin-right:6px}
.topbar-right{display:flex;gap:22px;flex-wrap:wrap}
.topbar-right a:hover{color:var(--gold)}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:40;background:rgba(248,245,240,.92);
  backdrop-filter:blur(14px);border-bottom:1px solid var(--line);
}
.header-inner{
  display:grid;grid-template-columns:auto 1fr auto;
  align-items:center;gap:40px;padding:18px 28px;
}
.logo{display:flex;align-items:center;gap:12px}
.logo-mark{
  width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  color:var(--ivory);display:grid;place-items:center;
  font-family:'Cormorant Garamond',serif;font-size:1.6rem;font-weight:600;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.25);
}
.logo-text{display:flex;flex-direction:column;line-height:1}
.logo-text strong{font-family:'Cormorant Garamond',serif;font-size:1.5rem;font-weight:600;letter-spacing:.18em;color:var(--charcoal)}
.logo-text em{font-size:.62rem;letter-spacing:.35em;color:var(--gold-dark);margin-top:4px;text-transform:uppercase;font-style:normal}

.main-nav{display:flex;justify-content:center;gap:30px}
.main-nav a{
  font-size:.86rem;font-weight:500;letter-spacing:.04em;
  color:var(--ink);padding:8px 2px;position:relative;
  transition:color .25s var(--ease);
}
.main-nav a:hover{color:var(--gold-dark)}
.main-nav a.active{color:var(--charcoal)}
.main-nav a.active::after{
  content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;
  background:var(--gold);
}

.header-actions{display:flex;align-items:center;gap:10px}
.icon-btn{
  width:42px;height:42px;border-radius:50%;border:1px solid var(--line);
  background:var(--white);color:var(--charcoal);position:relative;
  transition:all .25s var(--ease);
}
.icon-btn:hover{border-color:var(--charcoal);transform:translateY(-2px)}
.badge{
  position:absolute;top:-4px;right:-4px;background:var(--gold);color:var(--white);
  font-size:.65rem;font-weight:700;min-width:18px;height:18px;border-radius:50%;
  display:grid;place-items:center;padding:0 4px;
}
.burger{display:none;background:none;border:0;font-size:1.3rem;color:var(--charcoal)}

/* ---------- Hero ---------- */
.hero{
  position:relative;overflow:hidden;
  background:radial-gradient(circle at 80% 20%, var(--blush) 0%, var(--ivory) 55%, var(--cream) 100%);
  padding:80px 0 100px;
}
.hero::before{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 15% 85%, rgba(201,169,97,.18), transparent 40%),
    radial-gradient(circle at 85% 15%, rgba(244,232,225,.9), transparent 45%);
  pointer-events:none;
}
.hero-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:center;position:relative;z-index:1}
.hero-copy h1 em{display:inline-block}
.lead{font-size:1.05rem;color:var(--muted);max-width:540px;margin:22px 0 32px}
.lead strong{color:var(--charcoal)}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:44px}
.hero-trust{list-style:none;padding:0;margin:0;display:flex;gap:28px;flex-wrap:wrap;color:var(--muted);font-size:.88rem}
.hero-trust i{color:var(--gold-dark);margin-right:8px}

/* Hero visual – bottle mock */
.hero-visual{position:relative;display:grid;place-items:center;min-height:520px}
.hero-card{
  background:var(--white);border-radius:var(--radius);
  padding:44px 36px 30px;width:340px;text-align:center;
  box-shadow:var(--shadow-lg);position:relative;
  border:1px solid var(--line);
}
.badge-new{
  position:absolute;top:18px;right:18px;background:var(--gold);color:var(--white);
  font-size:.68rem;font-weight:700;letter-spacing:.2em;
  padding:5px 10px;border-radius:4px;
}
.hero-card-name{margin:24px 0 6px;font-size:.95rem;color:var(--charcoal);font-weight:500}
.hero-card-price{margin:0;font-size:1.25rem;font-weight:700;color:var(--gold-dark);font-family:'Cormorant Garamond',serif}

/* Decorative bottle */
.bottle{
  width:140px;height:240px;margin:0 auto;position:relative;
  display:flex;flex-direction:column;align-items:center;
}
.bottle-cap{
  width:58px;height:40px;
  background:linear-gradient(180deg,#2a2a2a,#0c0c0c);
  border-radius:8px 8px 4px 4px;position:relative;z-index:2;
  box-shadow:inset 0 3px 0 rgba(255,255,255,.08);
}
.bottle-cap::after{
  content:"";position:absolute;left:50%;bottom:-6px;transform:translateX(-50%);
  width:48px;height:10px;background:#1c1c1c;border-radius:4px;
}
.bottle-body{
  width:140px;height:200px;margin-top:-4px;
  background:linear-gradient(180deg,#f5efe2,#e8dcc4 70%,#d4c29e);
  border-radius:10px 10px 18px 18px;position:relative;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.05), inset 12px 0 24px rgba(201,169,97,.25);
  display:flex;flex-direction:column;justify-content:center;align-items:center;
  padding:0 10px;text-align:center;
}
.bottle-body::before{
  content:"";position:absolute;top:10px;left:10px;width:14px;height:60%;
  background:linear-gradient(180deg,rgba(255,255,255,.75),rgba(255,255,255,0));
  border-radius:10px;filter:blur(1px);
}
.bottle-label{font-family:'Cormorant Garamond',serif;font-size:.78rem;letter-spacing:.25em;color:var(--charcoal);font-weight:600}
.bottle-sub{font-size:.7rem;color:var(--gold-dark);margin-top:6px;letter-spacing:.1em;text-transform:uppercase;font-weight:600}
.bottle-vol{font-size:.65rem;color:var(--muted);margin-top:10px;letter-spacing:.2em}

.bottle.alt-1 .bottle-body{background:linear-gradient(180deg,#f3e8e2,#e7ccc0 70%,#cca898)}
.bottle.alt-2 .bottle-body{background:linear-gradient(180deg,#ecf0ea,#cdd8c9 70%,#a5b5a0)}
.bottle.alt-3 .bottle-body{background:linear-gradient(180deg,#eee7de,#d8c5a9 70%,#b49868)}

.float-chip{
  position:absolute;background:var(--white);border-radius:999px;
  padding:10px 18px;font-size:.82rem;font-weight:500;
  box-shadow:var(--shadow);border:1px solid var(--line);
  display:flex;align-items:center;gap:8px;
}
.float-chip i{color:var(--gold)}
.chip-1{top:18%;left:4%}
.chip-2{bottom:14%;right:2%}

/* ---------- Marquee ---------- */
.marquee{background:var(--charcoal);color:var(--cream);overflow:hidden;border-top:1px solid #000;border-bottom:1px solid #000}
.marquee-track{
  display:flex;gap:48px;white-space:nowrap;
  padding:14px 0;animation:marquee 30s linear infinite;
  font-family:'Cormorant Garamond',serif;font-size:1.15rem;letter-spacing:.12em;
}
.marquee-track span{color:var(--cream)}
.marquee-track span:nth-child(even){color:var(--gold)}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Categories ---------- */
.categories{padding:110px 0}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.cat-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  padding:40px 32px;transition:all .35s var(--ease);
  display:flex;flex-direction:column;gap:12px;position:relative;overflow:hidden;
}
.cat-card::after{
  content:"";position:absolute;inset:auto 0 0 0;height:3px;background:var(--gold);
  transform:scaleX(0);transform-origin:left;transition:transform .4s var(--ease);
}
.cat-card:hover{transform:translateY(-8px);box-shadow:var(--shadow)}
.cat-card:hover::after{transform:scaleX(1)}
.cat-icon{
  width:64px;height:64px;border-radius:50%;
  background:linear-gradient(135deg,var(--blush),var(--cream));
  display:grid;place-items:center;color:var(--gold-dark);font-size:1.5rem;
  margin-bottom:10px;
}
.cat-card h3{margin-top:4px}
.cat-card p{color:var(--muted);font-size:.92rem;margin:0}
.cat-cta{
  margin-top:14px;font-size:.82rem;font-weight:600;color:var(--charcoal);
  letter-spacing:.06em;display:inline-flex;align-items:center;gap:6px;
  transition:gap .25s var(--ease),color .25s var(--ease);
}
.cat-card:hover .cat-cta{color:var(--gold-dark);gap:12px}

/* ---------- Products ---------- */
.products{padding:110px 0;background:linear-gradient(180deg,var(--ivory),var(--white))}
.product-tabs{display:flex;gap:8px;flex-wrap:wrap}
.tab{
  padding:10px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-size:.82rem;font-weight:600;color:var(--ink);
  transition:all .25s var(--ease);
}
.tab:hover{border-color:var(--charcoal)}
.tab.active{background:var(--charcoal);color:var(--ivory);border-color:var(--charcoal)}

.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
  display:flex;flex-direction:column;
}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold)}
.product-media{
  position:relative;background:linear-gradient(135deg,var(--cream),var(--blush));
  padding:38px 20px;display:grid;place-items:center;min-height:280px;
}
.bottle-sm{width:100px;height:170px}
.bottle-sm .bottle-cap{width:42px;height:30px}
.bottle-sm .bottle-body{width:100px;height:140px;padding:0 6px}
.bottle-sm .bottle-label{font-size:.62rem}
.bottle-sm .bottle-sub{font-size:.58rem}
.tag{
  position:absolute;top:14px;left:14px;font-size:.66rem;font-weight:700;
  letter-spacing:.15em;padding:5px 10px;border-radius:4px;color:var(--white);
}
.tag-sale{background:#C9A961}
.tag-hot{background:#b44646}
.tag-new{background:#3b7a57}
.quick{
  position:absolute;bottom:14px;left:50%;transform:translate(-50%,8px);
  opacity:0;background:var(--charcoal);color:var(--ivory);border:0;
  padding:10px 18px;border-radius:999px;font-size:.78rem;font-weight:600;letter-spacing:.08em;
  transition:all .3s var(--ease);
}
.product-card:hover .quick{opacity:1;transform:translate(-50%,0)}

.product-body{padding:22px 20px 24px;display:flex;flex-direction:column;gap:10px;flex:1}
.product-body .cat{font-size:.7rem;letter-spacing:.18em;color:var(--gold-dark);font-weight:600;text-transform:uppercase}
.product-body h3{font-size:1.05rem;font-weight:600;font-family:'Inter',sans-serif;color:var(--charcoal);line-height:1.35;min-height:48px}
.stars{color:var(--gold);font-size:.78rem;display:flex;align-items:center;gap:2px}
.stars small{color:var(--muted);margin-left:6px;font-size:.75rem}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:auto}
.price{font-size:1.2rem;font-weight:700;color:var(--charcoal);font-family:'Cormorant Garamond',serif}
.price-old{font-size:.85rem;color:var(--muted);text-decoration:line-through}

/* ---------- Story ---------- */
.story{padding:120px 0;background:var(--white)}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.story-visual{position:relative;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:14px;height:540px}
.story-img{border-radius:var(--radius);background-size:cover;background-position:center}
.img-1{
  grid-row:1/3;
  background:linear-gradient(180deg,var(--sand) 0%,var(--blush) 100%);
  position:relative;overflow:hidden;
}
.img-1::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 30% 30%,rgba(255,255,255,.8),transparent 50%),
             radial-gradient(circle at 70% 70%,rgba(201,169,97,.4),transparent 50%);
}
.img-1::after{
  content:"";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:120px;height:180px;background:linear-gradient(180deg,#f5efe2,#d4c29e);
  border-radius:10px 10px 18px 18px;box-shadow:0 20px 40px rgba(28,28,28,.18);
}
.img-2{background:linear-gradient(135deg,var(--sage),#b8c7b0)}
.img-3{background:linear-gradient(135deg,var(--cream),var(--gold))}
.story-badge{
  position:absolute;bottom:-28px;left:-28px;background:var(--charcoal);
  color:var(--ivory);padding:22px 26px;border-radius:var(--radius);
  display:flex;align-items:center;gap:14px;box-shadow:var(--shadow-lg);
}
.story-badge strong{font-family:'Cormorant Garamond',serif;font-size:2.4rem;color:var(--gold);line-height:1}
.story-badge span{font-size:.78rem;line-height:1.4;letter-spacing:.05em}

.story-copy p{color:var(--muted);margin:18px 0}
.story-copy p strong{color:var(--charcoal)}
.story-points{list-style:none;padding:0;margin:24px 0 32px}
.story-points li{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);font-size:.92rem}
.story-points li:last-child{border-bottom:0}
.story-points i{color:var(--gold);width:20px}

/* ---------- Auth / QR ---------- */
.auth{padding:100px 0}
.auth-card{
  background:linear-gradient(135deg,var(--charcoal) 0%,#2a2520 100%);
  color:var(--ivory);border-radius:calc(var(--radius) + 8px);
  padding:80px 70px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;
  position:relative;overflow:hidden;
}
.auth-card::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 80% 20%,rgba(201,169,97,.2),transparent 50%);
  pointer-events:none;
}
.auth-copy h2{color:var(--ivory);position:relative}
.auth-copy h2 em{color:var(--gold)}
.auth-copy p{color:#c9c3b6;margin:16px 0 28px;max-width:480px}
.auth-copy p strong{color:var(--gold)}
.store-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px;position:relative}
.store-btn{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--ivory);color:var(--charcoal);padding:10px 18px;border-radius:12px;
  transition:all .25s var(--ease);
}
.store-btn:hover{transform:translateY(-2px)}
.store-btn i{font-size:1.6rem}
.store-btn span{display:flex;flex-direction:column;line-height:1.1;font-size:.95rem;font-weight:600}
.store-btn small{font-size:.62rem;font-weight:500;color:var(--muted);letter-spacing:.05em}

.store-btns.sm .store-btn{padding:8px 14px;background:transparent;color:var(--ivory);border:1px solid rgba(255,255,255,.2)}
.store-btns.sm .store-btn small{color:rgba(255,255,255,.6)}

.auth-copy .link-arrow{color:var(--gold);border-color:var(--gold)}
.auth-copy .link-arrow:hover{color:var(--ivory);border-color:var(--ivory)}

.auth-visual{position:relative;display:grid;place-items:center}
.qr-frame{text-align:center;color:var(--ivory)}
.qr-mock{
  width:220px;height:220px;background:var(--ivory);border-radius:20px;
  padding:24px;position:relative;margin:0 auto 16px;
  box-shadow:0 30px 60px rgba(0,0,0,.4);
}
.qr-dot{position:absolute;width:44px;height:44px;border:7px solid var(--charcoal);border-radius:8px}
.qr-dot.tl{top:20px;left:20px}
.qr-dot.tr{top:20px;right:20px}
.qr-dot.bl{bottom:20px;left:20px}
.qr-inner{
  position:absolute;inset:28px;
  background-image:
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal));
  background-size:
    12px 12px, 18px 18px, 24px 12px, 12px 24px,
    15px 15px, 20px 14px, 14px 20px, 22px 22px;
  background-position:
    70px 20px, 20px 80px, 90px 70px, 150px 90px,
    60px 130px, 130px 140px, 100px 170px, 30px 150px;
  background-repeat:no-repeat;
}
.qr-frame p{font-size:.82rem;letter-spacing:.15em;color:var(--gold);text-transform:uppercase;font-weight:600}

/* ---------- Testimonials ---------- */
.testimonials{padding:110px 0;background:var(--cream)}
.tm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.tm-card{
  background:var(--white);border-radius:var(--radius);padding:36px 30px;
  margin:0;box-shadow:var(--shadow-sm);position:relative;
  display:flex;flex-direction:column;gap:18px;
}
.tm-card::before{
  content:"\201C";position:absolute;top:10px;right:24px;
  font-family:'Cormorant Garamond',serif;font-size:5rem;color:var(--gold);line-height:1;opacity:.4;
}
.tm-card p{font-family:'Cormorant Garamond',serif;font-size:1.2rem;line-height:1.4;color:var(--charcoal);margin:0;font-style:italic}
.tm-card footer{display:flex;align-items:center;gap:12px;margin-top:auto;border-top:1px solid var(--line);padding-top:18px}
.avatar{
  width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  display:grid;place-items:center;color:var(--ivory);font-weight:600;font-size:.9rem;
}
.tm-card footer strong{display:block;font-size:.9rem;color:var(--charcoal)}
.tm-card footer span{font-size:.78rem;color:var(--muted)}

/* ---------- Dealer ---------- */
.dealer{padding:120px 0;background:var(--charcoal);color:var(--ivory);position:relative;overflow:hidden}
.dealer::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 15% 85%,rgba(201,169,97,.15),transparent 50%);
  pointer-events:none;
}
.dealer-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;position:relative}
.dealer h2{color:var(--ivory)}
.dealer h2 em{color:var(--gold)}
.dealer p{color:#c9c3b6;margin:18px 0 36px;max-width:480px}
.dealer-points{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.dealer-points li{
  background:rgba(255,255,255,.05);padding:22px 20px;border-radius:12px;
  border:1px solid rgba(201,169,97,.2);
}
.dealer-points strong{display:block;font-family:'Cormorant Garamond',serif;font-size:2rem;color:var(--gold);line-height:1}
.dealer-points span{font-size:.78rem;color:#c9c3b6;margin-top:6px;display:block}

.dealer-form{
  background:var(--ivory);color:var(--charcoal);
  padding:40px 36px;border-radius:var(--radius);box-shadow:var(--shadow-lg);
}
.dealer-form h3{font-family:'Cormorant Garamond',serif;font-size:1.8rem;margin-bottom:20px;font-weight:600}
.dealer-form label{display:block;font-size:.82rem;font-weight:600;color:var(--charcoal);margin-bottom:14px}
.dealer-form input,
.dealer-form textarea{
  width:100%;padding:12px 14px;margin-top:6px;
  border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.92rem;background:var(--white);
  transition:border-color .25s var(--ease);
}
.dealer-form input:focus,
.dealer-form textarea:focus{outline:0;border-color:var(--gold)}
.dealer-form textarea{resize:vertical}

/* ---------- News ---------- */
.news{padding:110px 0}
.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.news-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
}
.news-card:hover{transform:translateY(-6px);box-shadow:var(--shadow)}
.news-thumb{height:220px;background-size:cover;background-position:center}
.thumb-1{background:linear-gradient(135deg,#f4d3ac,#e7a873)}
.thumb-2{background:linear-gradient(135deg,#cfe1d6,#8ab39c)}
.thumb-3{background:linear-gradient(135deg,#e8d4cc,#c69b8a)}
.news-body{padding:24px 26px 28px}
.news-meta{font-size:.72rem;color:var(--gold-dark);font-weight:600;letter-spacing:.12em;text-transform:uppercase}
.news-card h3{font-family:'Cormorant Garamond',serif;font-size:1.4rem;font-weight:600;margin:10px 0 10px;line-height:1.25}
.news-card p{color:var(--muted);font-size:.9rem;margin:0}

/* ---------- Newsletter ---------- */
.newsletter{background:linear-gradient(135deg,var(--blush),var(--cream));padding:60px 0}
.news-inner{display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}
.news-inner h3{font-family:'Cormorant Garamond',serif;font-size:1.8rem;font-weight:600}
.news-inner p{color:var(--muted);margin:6px 0 0}
.news-inner form{display:flex;gap:10px;flex:1;max-width:460px}
.news-inner input{
  flex:1;padding:14px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-family:inherit;font-size:.9rem;
}
.news-inner input:focus{outline:0;border-color:var(--gold)}

/* ---------- Footer ---------- */
.site-footer{background:#121212;color:#c9c3b6;padding:80px 0 0}
.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:50px}
.logo-light .logo-text strong{color:var(--ivory)}
.logo-light .logo-text em{color:var(--gold)}
.footer-about{font-size:.88rem;line-height:1.7;margin:20px 0}
.footer-contact{list-style:none;padding:0;margin:0}
.footer-contact li{padding:6px 0;font-size:.88rem}
.footer-contact i{color:var(--gold);width:20px}
.footer-contact a:hover{color:var(--gold)}
.site-footer h4{color:var(--ivory);font-family:'Inter',sans-serif;font-size:.82rem;letter-spacing:.2em;text-transform:uppercase;font-weight:700;margin-bottom:20px}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer ul li{padding:6px 0;font-size:.88rem}
.site-footer ul a{transition:color .2s var(--ease)}
.site-footer ul a:hover{color:var(--gold)}
.socials{display:flex;gap:10px;margin-bottom:28px}
.socials a{
  width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.1);display:grid;place-items:center;
  color:var(--ivory);font-size:.9rem;transition:all .25s var(--ease);
}
.socials a:hover{background:var(--gold);border-color:var(--gold);color:var(--charcoal)}

.copyright{margin-top:70px;border-top:1px solid rgba(255,255,255,.06);padding:22px 0;font-size:.8rem}
.copyright-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}
.copyright i{color:var(--gold)}

/* ---------- Floating actions ---------- */
.floating{position:fixed;right:20px;bottom:24px;display:flex;flex-direction:column;gap:10px;z-index:50}
.fab{
  width:52px;height:52px;border-radius:50%;display:grid;place-items:center;
  color:var(--ivory);box-shadow:var(--shadow);position:relative;
  transition:all .25s var(--ease);
}
.fab:hover{transform:translateY(-3px)}
.fab-call{background:var(--gold);animation:pulse 2.2s infinite}
.fab-call span{
  position:absolute;right:60px;background:var(--charcoal);color:var(--ivory);
  padding:6px 12px;border-radius:999px;font-size:.78rem;white-space:nowrap;
}
.fab-zalo{background:#0084ff}
.fab-fb{background:#0078ff}
@keyframes pulse{
  0%{box-shadow:0 0 0 0 rgba(201,169,97,.55)}
  70%{box-shadow:0 0 0 18px rgba(201,169,97,0)}
  100%{box-shadow:0 0 0 0 rgba(201,169,97,0)}
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px){
  .main-nav{display:none}
  .burger{display:inline-block}
  .header-inner{grid-template-columns:auto 1fr auto}
  .hero-grid,.story-grid,.auth-card,.dealer-grid{grid-template-columns:1fr;gap:40px}
  .auth-card{padding:50px 30px}
  .cat-grid,.product-grid,.news-grid,.tm-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:1fr 1fr;gap:36px}
  .story-visual{height:420px}
  .story-badge{bottom:-18px;left:16px}
  .float-chip{display:none}
}
@media (max-width: 640px){
  .topbar-right{display:none}
  .header-actions .btn{display:none}
  .cat-grid,.product-grid,.news-grid,.tm-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .section-head.between{flex-direction:column;align-items:flex-start}
  .dealer-points{grid-template-columns:1fr}
  h1{font-size:2.4rem}
  h2{font-size:1.9rem}
  .auth-card{padding:40px 24px}
  .copyright-inner{flex-direction:column;text-align:center}
}

toolUseResult.content:
/* =========================================================
   DETOXBLANC — Brand Stylesheet
   Palette : champagne gold, ivory cream, charcoal, blush
   Type    : Cormorant Garamond (display) · Inter (body)
   ========================================================= */

:root{
  --ivory:       #F8F5F0;
  --cream:       #F1EBE2;
  --blush:       #F4E8E1;
  --sand:        #E6DBCB;
  --gold:        #C9A961;
  --gold-dark:   #A8883F;
  --charcoal:    #1C1C1C;
  --ink:         #2A2A2A;
  --muted:       #6E6A63;
  --line:        #E6DFD3;
  --sage:        #8B9D83;
  --white:       #ffffff;
  --radius:      18px;
  --radius-sm:   10px;
  --shadow-sm:   0 2px 10px rgba(28,28,28,.06);
  --shadow:      0 12px 40px rgba(28,28,28,.08);
  --shadow-lg:   0 24px 60px rgba(28,28,28,.14);
  --ease:        cubic-bezier(.2,.7,.2,1);
  --container:   1240px;
}

*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  font-family:'Inter', system-ui, -apple-system, sans-serif;
  color:var(--ink);
  background:var(--ivory);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer}

.container{max-width:var(--container);margin:0 auto;padding:0 28px}
.center{text-align:center}
.mt-24{margin-top:24px}
.mt-40{margin-top:40px}

/* ---------- Typography ---------- */
h1,h2,h3,h4{font-family:'Cormorant Garamond', serif;font-weight:500;color:var(--charcoal);margin:0;letter-spacing:-.01em}
h1{font-size:clamp(2.4rem,5vw,4.4rem);line-height:1.05;font-weight:500}
h2{font-size:clamp(2rem,3.6vw,3.2rem);line-height:1.1}
h3{font-size:1.35rem;line-height:1.25;font-weight:600}
h4{font-size:1.05rem;color:var(--charcoal)}
em{font-style:italic;color:var(--gold-dark);font-weight:500}

.eyebrow{
  font-family:'Inter',sans-serif;
  font-size:.72rem;
  font-weight:600;
  letter-spacing:.22em;
  color:var(--gold-dark);
  text-transform:uppercase;
  display:inline-block;
  margin-bottom:14px;
}
.eyebrow.light{color:var(--gold)}

.underline{background:linear-gradient(transparent 62%, rgba(201,169,97,.35) 62%);padding:0 2px}

.section-head{margin-bottom:56px;text-align:center}
.section-head.between{
  display:flex;justify-content:space-between;align-items:flex-end;
  text-align:left;flex-wrap:wrap;gap:24px;
}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:14px 26px;border-radius:999px;border:1px solid transparent;
  font-weight:600;font-size:.9rem;letter-spacing:.02em;
  transition:all .25s var(--ease);
}
.btn i{font-size:.85em}
.btn-primary{background:var(--charcoal);color:var(--ivory)}
.btn-primary:hover{background:var(--gold-dark);transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-dark{background:var(--charcoal);color:var(--ivory)}
.btn-dark:hover{background:var(--gold-dark)}
.btn-outline{background:transparent;border-color:var(--charcoal);color:var(--charcoal)}
.btn-outline:hover{background:var(--charcoal);color:var(--ivory)}
.btn-ghost{background:transparent;color:var(--charcoal);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--charcoal)}
.btn-block{display:flex;width:100%;justify-content:center}

.link-arrow{
  display:inline-flex;align-items:center;gap:8px;
  font-weight:600;font-size:.9rem;color:var(--charcoal);
  border-bottom:1px solid var(--charcoal);padding-bottom:3px;
  transition:all .25s var(--ease);
}
.link-arrow:hover{color:var(--gold-dark);border-color:var(--gold-dark);gap:14px}

/* ---------- Topbar ---------- */
.topbar{
  background:var(--charcoal);color:#d9d4c7;font-size:.8rem;
  padding:9px 0;letter-spacing:.02em;
}
.topbar-inner{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.topbar i{color:var(--gold);margin-right:6px}
.topbar-right{display:flex;gap:22px;flex-wrap:wrap}
.topbar-right a:hover{color:var(--gold)}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:40;background:rgba(248,245,240,.92);
  backdrop-filter:blur(14px);border-bottom:1px solid var(--line);
}
.header-inner{
  display:grid;grid-template-columns:auto 1fr auto;
  align-items:center;gap:40px;padding:18px 28px;
}
.logo{display:flex;align-items:center;gap:12px}
.logo-mark{
  width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  color:var(--ivory);display:grid;place-items:center;
  font-family:'Cormorant Garamond',serif;font-size:1.6rem;font-weight:600;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.25);
}
.logo-text{display:flex;flex-direction:column;line-height:1}
.logo-text strong{font-family:'Cormorant Garamond',serif;font-size:1.5rem;font-weight:600;letter-spacing:.18em;color:var(--charcoal)}
.logo-text em{font-size:.62rem;letter-spacing:.35em;color:var(--gold-dark);margin-top:4px;text-transform:uppercase;font-style:normal}

.main-nav{display:flex;justify-content:center;gap:30px}
.main-nav a{
  font-size:.86rem;font-weight:500;letter-spacing:.04em;
  color:var(--ink);padding:8px 2px;position:relative;
  transition:color .25s var(--ease);
}
.main-nav a:hover{color:var(--gold-dark)}
.main-nav a.active{color:var(--charcoal)}
.main-nav a.active::after{
  content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;
  background:var(--gold);
}

.header-actions{display:flex;align-items:center;gap:10px}
.icon-btn{
  width:42px;height:42px;border-radius:50%;border:1px solid var(--line);
  background:var(--white);color:var(--charcoal);position:relative;
  transition:all .25s var(--ease);
}
.icon-btn:hover{border-color:var(--charcoal);transform:translateY(-2px)}
.badge{
  position:absolute;top:-4px;right:-4px;background:var(--gold);color:var(--white);
  font-size:.65rem;font-weight:700;min-width:18px;height:18px;border-radius:50%;
  display:grid;place-items:center;padding:0 4px;
}
.burger{display:none;background:none;border:0;font-size:1.3rem;color:var(--charcoal)}

/* ---------- Hero ---------- */
.hero{
  position:relative;overflow:hidden;
  background:radial-gradient(circle at 80% 20%, var(--blush) 0%, var(--ivory) 55%, var(--cream) 100%);
  padding:80px 0 100px;
}
.hero::before{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 15% 85%, rgba(201,169,97,.18), transparent 40%),
    radial-gradient(circle at 85% 15%, rgba(244,232,225,.9), transparent 45%);
  pointer-events:none;
}
.hero-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:center;position:relative;z-index:1}
.hero-copy h1 em{display:inline-block}
.lead{font-size:1.05rem;color:var(--muted);max-width:540px;margin:22px 0 32px}
.lead strong{color:var(--charcoal)}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:44px}
.hero-trust{list-style:none;padding:0;margin:0;display:flex;gap:28px;flex-wrap:wrap;color:var(--muted);font-size:.88rem}
.hero-trust i{color:var(--gold-dark);margin-right:8px}

/* Hero visual – bottle mock */
.hero-visual{position:relative;display:grid;place-items:center;min-height:520px}
.hero-card{
  background:var(--white);border-radius:var(--radius);
  padding:44px 36px 30px;width:340px;text-align:center;
  box-shadow:var(--shadow-lg);position:relative;
  border:1px solid var(--line);
}
.badge-new{
  position:absolute;top:18px;right:18px;background:var(--gold);color:var(--white);
  font-size:.68rem;font-weight:700;letter-spacing:.2em;
  padding:5px 10px;border-radius:4px;
}
.hero-card-name{margin:24px 0 6px;font-size:.95rem;color:var(--charcoal);font-weight:500}
.hero-card-price{margin:0;font-size:1.25rem;font-weight:700;color:var(--gold-dark);font-family:'Cormorant Garamond',serif}

/* Decorative bottle */
.bottle{
  width:140px;height:240px;margin:0 auto;position:relative;
  display:flex;flex-direction:column;align-items:center;
}
.bottle-cap{
  width:58px;height:40px;
  background:linear-gradient(180deg,#2a2a2a,#0c0c0c);
  border-radius:8px 8px 4px 4px;position:relative;z-index:2;
  box-shadow:inset 0 3px 0 rgba(255,255,255,.08);
}
.bottle-cap::after{
  content:"";position:absolute;left:50%;bottom:-6px;transform:translateX(-50%);
  width:48px;height:10px;background:#1c1c1c;border-radius:4px;
}
.bottle-body{
  width:140px;height:200px;margin-top:-4px;
  background:linear-gradient(180deg,#f5efe2,#e8dcc4 70%,#d4c29e);
  border-radius:10px 10px 18px 18px;position:relative;
  box-shadow:inset 0 0 0 1px rgba(0,0,0,.05), inset 12px 0 24px rgba(201,169,97,.25);
  display:flex;flex-direction:column;justify-content:center;align-items:center;
  padding:0 10px;text-align:center;
}
.bottle-body::before{
  content:"";position:absolute;top:10px;left:10px;width:14px;height:60%;
  background:linear-gradient(180deg,rgba(255,255,255,.75),rgba(255,255,255,0));
  border-radius:10px;filter:blur(1px);
}
.bottle-label{font-family:'Cormorant Garamond',serif;font-size:.78rem;letter-spacing:.25em;color:var(--charcoal);font-weight:600}
.bottle-sub{font-size:.7rem;color:var(--gold-dark);margin-top:6px;letter-spacing:.1em;text-transform:uppercase;font-weight:600}
.bottle-vol{font-size:.65rem;color:var(--muted);margin-top:10px;letter-spacing:.2em}

.bottle.alt-1 .bottle-body{background:linear-gradient(180deg,#f3e8e2,#e7ccc0 70%,#cca898)}
.bottle.alt-2 .bottle-body{background:linear-gradient(180deg,#ecf0ea,#cdd8c9 70%,#a5b5a0)}
.bottle.alt-3 .bottle-body{background:linear-gradient(180deg,#eee7de,#d8c5a9 70%,#b49868)}

.float-chip{
  position:absolute;background:var(--white);border-radius:999px;
  padding:10px 18px;font-size:.82rem;font-weight:500;
  box-shadow:var(--shadow);border:1px solid var(--line);
  display:flex;align-items:center;gap:8px;
}
.float-chip i{color:var(--gold)}
.chip-1{top:18%;left:4%}
.chip-2{bottom:14%;right:2%}

/* ---------- Marquee ---------- */
.marquee{background:var(--charcoal);color:var(--cream);overflow:hidden;border-top:1px solid #000;border-bottom:1px solid #000}
.marquee-track{
  display:flex;gap:48px;white-space:nowrap;
  padding:14px 0;animation:marquee 30s linear infinite;
  font-family:'Cormorant Garamond',serif;font-size:1.15rem;letter-spacing:.12em;
}
.marquee-track span{color:var(--cream)}
.marquee-track span:nth-child(even){color:var(--gold)}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Categories ---------- */
.categories{padding:110px 0}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.cat-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  padding:40px 32px;transition:all .35s var(--ease);
  display:flex;flex-direction:column;gap:12px;position:relative;overflow:hidden;
}
.cat-card::after{
  content:"";position:absolute;inset:auto 0 0 0;height:3px;background:var(--gold);
  transform:scaleX(0);transform-origin:left;transition:transform .4s var(--ease);
}
.cat-card:hover{transform:translateY(-8px);box-shadow:var(--shadow)}
.cat-card:hover::after{transform:scaleX(1)}
.cat-icon{
  width:64px;height:64px;border-radius:50%;
  background:linear-gradient(135deg,var(--blush),var(--cream));
  display:grid;place-items:center;color:var(--gold-dark);font-size:1.5rem;
  margin-bottom:10px;
}
.cat-card h3{margin-top:4px}
.cat-card p{color:var(--muted);font-size:.92rem;margin:0}
.cat-cta{
  margin-top:14px;font-size:.82rem;font-weight:600;color:var(--charcoal);
  letter-spacing:.06em;display:inline-flex;align-items:center;gap:6px;
  transition:gap .25s var(--ease),color .25s var(--ease);
}
.cat-card:hover .cat-cta{color:var(--gold-dark);gap:12px}

/* ---------- Products ---------- */
.products{padding:110px 0;background:linear-gradient(180deg,var(--ivory),var(--white))}
.product-tabs{display:flex;gap:8px;flex-wrap:wrap}
.tab{
  padding:10px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-size:.82rem;font-weight:600;color:var(--ink);
  transition:all .25s var(--ease);
}
.tab:hover{border-color:var(--charcoal)}
.tab.active{background:var(--charcoal);color:var(--ivory);border-color:var(--charcoal)}

.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
  display:flex;flex-direction:column;
}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold)}
.product-media{
  position:relative;background:linear-gradient(135deg,var(--cream),var(--blush));
  padding:38px 20px;display:grid;place-items:center;min-height:280px;
}
.bottle-sm{width:100px;height:170px}
.bottle-sm .bottle-cap{width:42px;height:30px}
.bottle-sm .bottle-body{width:100px;height:140px;padding:0 6px}
.bottle-sm .bottle-label{font-size:.62rem}
.bottle-sm .bottle-sub{font-size:.58rem}
.tag{
  position:absolute;top:14px;left:14px;font-size:.66rem;font-weight:700;
  letter-spacing:.15em;padding:5px 10px;border-radius:4px;color:var(--white);
}
.tag-sale{background:#C9A961}
.tag-hot{background:#b44646}
.tag-new{background:#3b7a57}
.quick{
  position:absolute;bottom:14px;left:50%;transform:translate(-50%,8px);
  opacity:0;background:var(--charcoal);color:var(--ivory);border:0;
  padding:10px 18px;border-radius:999px;font-size:.78rem;font-weight:600;letter-spacing:.08em;
  transition:all .3s var(--ease);
}
.product-card:hover .quick{opacity:1;transform:translate(-50%,0)}

.product-body{padding:22px 20px 24px;display:flex;flex-direction:column;gap:10px;flex:1}
.product-body .cat{font-size:.7rem;letter-spacing:.18em;color:var(--gold-dark);font-weight:600;text-transform:uppercase}
.product-body h3{font-size:1.05rem;font-weight:600;font-family:'Inter',sans-serif;color:var(--charcoal);line-height:1.35;min-height:48px}
.stars{color:var(--gold);font-size:.78rem;display:flex;align-items:center;gap:2px}
.stars small{color:var(--muted);margin-left:6px;font-size:.75rem}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:auto}
.price{font-size:1.2rem;font-weight:700;color:var(--charcoal);font-family:'Cormorant Garamond',serif}
.price-old{font-size:.85rem;color:var(--muted);text-decoration:line-through}

/* ---------- Story ---------- */
.story{padding:120px 0;background:var(--white)}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.story-visual{position:relative;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:14px;height:540px}
.story-img{border-radius:var(--radius);background-size:cover;background-position:center}
.img-1{
  grid-row:1/3;
  background:linear-gradient(180deg,var(--sand) 0%,var(--blush) 100%);
  position:relative;overflow:hidden;
}
.img-1::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 30% 30%,rgba(255,255,255,.8),transparent 50%),
             radial-gradient(circle at 70% 70%,rgba(201,169,97,.4),transparent 50%);
}
.img-1::after{
  content:"";position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:120px;height:180px;background:linear-gradient(180deg,#f5efe2,#d4c29e);
  border-radius:10px 10px 18px 18px;box-shadow:0 20px 40px rgba(28,28,28,.18);
}
.img-2{background:linear-gradient(135deg,var(--sage),#b8c7b0)}
.img-3{background:linear-gradient(135deg,var(--cream),var(--gold))}
.story-badge{
  position:absolute;bottom:-28px;left:-28px;background:var(--charcoal);
  color:var(--ivory);padding:22px 26px;border-radius:var(--radius);
  display:flex;align-items:center;gap:14px;box-shadow:var(--shadow-lg);
}
.story-badge strong{font-family:'Cormorant Garamond',serif;font-size:2.4rem;color:var(--gold);line-height:1}
.story-badge span{font-size:.78rem;line-height:1.4;letter-spacing:.05em}

.story-copy p{color:var(--muted);margin:18px 0}
.story-copy p strong{color:var(--charcoal)}
.story-points{list-style:none;padding:0;margin:24px 0 32px}
.story-points li{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--line);font-size:.92rem}
.story-points li:last-child{border-bottom:0}
.story-points i{color:var(--gold);width:20px}

/* ---------- Auth / QR ---------- */
.auth{padding:100px 0}
.auth-card{
  background:linear-gradient(135deg,var(--charcoal) 0%,#2a2520 100%);
  color:var(--ivory);border-radius:calc(var(--radius) + 8px);
  padding:80px 70px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;
  position:relative;overflow:hidden;
}
.auth-card::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 80% 20%,rgba(201,169,97,.2),transparent 50%);
  pointer-events:none;
}
.auth-copy h2{color:var(--ivory);position:relative}
.auth-copy h2 em{color:var(--gold)}
.auth-copy p{color:#c9c3b6;margin:16px 0 28px;max-width:480px}
.auth-copy p strong{color:var(--gold)}
.store-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px;position:relative}
.store-btn{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--ivory);color:var(--charcoal);padding:10px 18px;border-radius:12px;
  transition:all .25s var(--ease);
}
.store-btn:hover{transform:translateY(-2px)}
.store-btn i{font-size:1.6rem}
.store-btn span{display:flex;flex-direction:column;line-height:1.1;font-size:.95rem;font-weight:600}
.store-btn small{font-size:.62rem;font-weight:500;color:var(--muted);letter-spacing:.05em}

.store-btns.sm .store-btn{padding:8px 14px;background:transparent;color:var(--ivory);border:1px solid rgba(255,255,255,.2)}
.store-btns.sm .store-btn small{color:rgba(255,255,255,.6)}

.auth-copy .link-arrow{color:var(--gold);border-color:var(--gold)}
.auth-copy .link-arrow:hover{color:var(--ivory);border-color:var(--ivory)}

.auth-visual{position:relative;display:grid;place-items:center}
.qr-frame{text-align:center;color:var(--ivory)}
.qr-mock{
  width:220px;height:220px;background:var(--ivory);border-radius:20px;
  padding:24px;position:relative;margin:0 auto 16px;
  box-shadow:0 30px 60px rgba(0,0,0,.4);
}
.qr-dot{position:absolute;width:44px;height:44px;border:7px solid var(--charcoal);border-radius:8px}
.qr-dot.tl{top:20px;left:20px}
.qr-dot.tr{top:20px;right:20px}
.qr-dot.bl{bottom:20px;left:20px}
.qr-inner{
  position:absolute;inset:28px;
  background-image:
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal));
  background-size:
    12px 12px, 18px 18px, 24px 12px, 12px 24px,
    15px 15px, 20px 14px, 14px 20px, 22px 22px;
  background-position:
    70px 20px, 20px 80px, 90px 70px, 150px 90px,
    60px 130px, 130px 140px, 100px 170px, 30px 150px;
  background-repeat:no-repeat;
}
.qr-frame p{font-size:.82rem;letter-spacing:.15em;color:var(--gold);text-transform:uppercase;font-weight:600}

/* ---------- Testimonials ---------- */
.testimonials{padding:110px 0;background:var(--cream)}
.tm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.tm-card{
  background:var(--white);border-radius:var(--radius);padding:36px 30px;
  margin:0;box-shadow:var(--shadow-sm);position:relative;
  display:flex;flex-direction:column;gap:18px;
}
.tm-card::before{
  content:"\201C";position:absolute;top:10px;right:24px;
  font-family:'Cormorant Garamond',serif;font-size:5rem;color:var(--gold);line-height:1;opacity:.4;
}
.tm-card p{font-family:'Cormorant Garamond',serif;font-size:1.2rem;line-height:1.4;color:var(--charcoal);margin:0;font-style:italic}
.tm-card footer{display:flex;align-items:center;gap:12px;margin-top:auto;border-top:1px solid var(--line);padding-top:18px}
.avatar{
  width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  display:grid;place-items:center;color:var(--ivory);font-weight:600;font-size:.9rem;
}
.tm-card footer strong{display:block;font-size:.9rem;color:var(--charcoal)}
.tm-card footer span{font-size:.78rem;color:var(--muted)}

/* ---------- Dealer ---------- */
.dealer{padding:120px 0;background:var(--charcoal);color:var(--ivory);position:relative;overflow:hidden}
.dealer::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 15% 85%,rgba(201,169,97,.15),transparent 50%);
  pointer-events:none;
}
.dealer-grid{display:grid;grid-template-columns:1fr 1fr;gap:70px;align-items:center;position:relative}
.dealer h2{color:var(--ivory)}
.dealer h2 em{color:var(--gold)}
.dealer p{color:#c9c3b6;margin:18px 0 36px;max-width:480px}
.dealer-points{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.dealer-points li{
  background:rgba(255,255,255,.05);padding:22px 20px;border-radius:12px;
  border:1px solid rgba(201,169,97,.2);
}
.dealer-points strong{display:block;font-family:'Cormorant Garamond',serif;font-size:2rem;color:var(--gold);line-height:1}
.dealer-points span{font-size:.78rem;color:#c9c3b6;margin-top:6px;display:block}

.dealer-form{
  background:var(--ivory);color:var(--charcoal);
  padding:40px 36px;border-radius:var(--radius);box-shadow:var(--shadow-lg);
}
.dealer-form h3{font-family:'Cormorant Garamond',serif;font-size:1.8rem;margin-bottom:20px;font-weight:600}
.dealer-form label{display:block;font-size:.82rem;font-weight:600;color:var(--charcoal);margin-bottom:14px}
.dealer-form input,
.dealer-form textarea{
  width:100%;padding:12px 14px;margin-top:6px;
  border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.92rem;background:var(--white);
  transition:border-color .25s var(--ease);
}
.dealer-form input:focus,
.dealer-form textarea:focus{outline:0;border-color:var(--gold)}
.dealer-form textarea{resize:vertical}

/* ---------- News ---------- */
.news{padding:110px 0}
.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.news-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
}
.news-card:hover{transform:translateY(-6px);box-shadow:var(--shadow)}
.news-thumb{height:220px;background-size:cover;background-position:center}
.thumb-1{background:linear-gradient(135deg,#f4d3ac,#e7a873)}
.thumb-2{background:linear-gradient(135deg,#cfe1d6,#8ab39c)}
.thumb-3{background:linear-gradient(135deg,#e8d4cc,#c69b8a)}
.news-body{padding:24px 26px 28px}
.news-meta{font-size:.72rem;color:var(--gold-dark);font-weight:600;letter-spacing:.12em;text-transform:uppercase}
.news-card h3{font-family:'Cormorant Garamond',serif;font-size:1.4rem;font-weight:600;margin:10px 0 10px;line-height:1.25}
.news-card p{color:var(--muted);font-size:.9rem;margin:0}

/* ---------- Newsletter ---------- */
.newsletter{background:linear-gradient(135deg,var(--blush),var(--cream));padding:60px 0}
.news-inner{display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap}
.news-inner h3{font-family:'Cormorant Garamond',serif;font-size:1.8rem;font-weight:600}
.news-inner p{color:var(--muted);margin:6px 0 0}
.news-inner form{display:flex;gap:10px;flex:1;max-width:460px}
.news-inner input{
  flex:1;padding:14px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-family:inherit;font-size:.9rem;
}
.news-inner input:focus{outline:0;border-color:var(--gold)}

/* ---------- Footer ---------- */
.site-footer{background:#121212;color:#c9c3b6;padding:80px 0 0}
.footer-grid{display:grid;grid-template-columns:1.4fr 1fr 1fr 1.2fr;gap:50px}
.logo-light .logo-text strong{color:var(--ivory)}
.logo-light .logo-text em{color:var(--gold)}
.footer-about{font-size:.88rem;line-height:1.7;margin:20px 0}
.footer-contact{list-style:none;padding:0;margin:0}
.footer-contact li{padding:6px 0;font-size:.88rem}
.footer-contact i{color:var(--gold);width:20px}
.footer-contact a:hover{color:var(--gold)}
.site-footer h4{color:var(--ivory);font-family:'Inter',sans-serif;font-size:.82rem;letter-spacing:.2em;text-transform:uppercase;font-weight:700;margin-bottom:20px}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer ul li{padding:6px 0;font-size:.88rem}
.site-footer ul a{transition:color .2s var(--ease)}
.site-footer ul a:hover{color:var(--gold)}
.socials{display:flex;gap:10px;margin-bottom:28px}
.socials a{
  width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.1);display:grid;place-items:center;
  color:var(--ivory);font-size:.9rem;transition:all .25s var(--ease);
}
.socials a:hover{background:var(--gold);border-color:var(--gold);color:var(--charcoal)}

.copyright{margin-top:70px;border-top:1px solid rgba(255,255,255,.06);padding:22px 0;font-size:.8rem}
.copyright-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}
.copyright i{color:var(--gold)}

/* ---------- Floating actions ---------- */
.floating{position:fixed;right:20px;bottom:24px;display:flex;flex-direction:column;gap:10px;z-index:50}
.fab{
  width:52px;height:52px;border-radius:50%;display:grid;place-items:center;
  color:var(--ivory);box-shadow:var(--shadow);position:relative;
  transition:all .25s var(--ease);
}
.fab:hover{transform:translateY(-3px)}
.fab-call{background:var(--gold);animation:pulse 2.2s infinite}
.fab-call span{
  position:absolute;right:60px;background:var(--charcoal);color:var(--ivory);
  padding:6px 12px;border-radius:999px;font-size:.78rem;white-space:nowrap;
}
.fab-zalo{background:#0084ff}
.fab-fb{background:#0078ff}
@keyframes pulse{
  0%{box-shadow:0 0 0 0 rgba(201,169,97,.55)}
  70%{box-shadow:0 0 0 18px rgba(201,169,97,0)}
  100%{box-shadow:0 0 0 0 rgba(201,169,97,0)}
}

/* ---------- Responsive ---------- */
@media (max-width: 1080px){
  .main-nav{display:none}
  .burger{display:inline-block}
  .header-inner{grid-template-columns:auto 1fr auto}
  .hero-grid,.story-grid,.auth-card,.dealer-grid{grid-template-columns:1fr;gap:40px}
  .auth-card{padding:50px 30px}
  .cat-grid,.product-grid,.news-grid,.tm-grid{grid-template-columns:repeat(2,1fr)}
  .footer-grid{grid-template-columns:1fr 1fr;gap:36px}
  .story-visual{height:420px}
  .story-badge{bottom:-18px;left:16px}
  .float-chip{display:none}
}
@media (max-width: 640px){
  .topbar-right{display:none}
  .header-actions .btn{display:none}
  .cat-grid,.product-grid,.news-grid,.tm-grid{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .section-head.between{flex-direction:column;align-items:flex-start}
  .dealer-points{grid-template-columns:1fr}
  h1{font-size:2.4rem}
  h2{font-size:1.9rem}
  .auth-card{padding:40px 24px}
  .copyright-inner{flex-direction:column;text-align:center}
}

