// Detoxblanc — small interactions

// Product tabs
document.querySelectorAll('.product-tabs .tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.product-tabs .tab').forEach(t => t.classList.remove('active'));
    tab.classList.add('active');
  });
});

// Nav scroll-active
const sections = document.querySelectorAll('section[id]');
const navLinks = document.querySelectorAll('.main-nav a');
const onScroll = () => {
  const y = window.scrollY + 140;
  let current = 'home';
  sections.forEach(s => { if (s.offsetTop <= y) current = s.id; });
  navLinks.forEach(l => {
    l.classList.toggle('active', l.getAttribute('href') === '#' + current);
  });
};
window.addEventListener('scroll', onScroll, { passive: true });

// Smooth anchor scroll
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const id = a.getAttribute('href');
    if (id.length > 1) {
      const el = document.querySelector(id);
      if (el) { e.preventDefault(); el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
    }
  });
});

// Mobile burger (basic — toggles a class)
document.querySelector('.burger')?.addEventListener('click', () => {
  document.querySelector('.main-nav')?.classList.toggle('open');
});

// Reveal on scroll
const io = new IntersectionObserver((entries) => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('in'); });
}, { threshold: 0.12 });
document.querySelectorAll('.cat-card, .product-card, .tm-card, .news-card, .hero-copy, .hero-visual, .story-copy, .story-visual')
  .forEach(el => { el.classList.add('reveal'); io.observe(el); });

