input.content:
/* =========================================================
   DETOXBLANC — Maison de Soin
   Brand Stylesheet · international luxury cosmetics
   Palette : champagne gold · ivory · charcoal · blush · sage
   Type    : Italiana (display) · Cormorant Garamond (editorial) · Inter (body)
   ========================================================= */

:root{
  --ivory:      #F8F5F0;
  --cream:      #F1EBE2;
  --blush:      #F4E8E1;
  --sand:       #E6DBCB;
  --gold:       #C9A961;
  --gold-soft:  #E2CB95;
  --gold-dark:  #A8883F;
  --charcoal:   #141414;
  --ink:        #2A2A2A;
  --muted:      #6E6A63;
  --line:       #E6DFD3;
  --line-dark:  #DBD3C2;
  --sage:       #8B9D83;
  --rose:       #C99A8C;
  --white:      #ffffff;
  --black:      #000000;
  --radius:     16px;
  --radius-sm:  10px;
  --shadow-sm:  0 2px 10px rgba(20,20,20,.06);
  --shadow:     0 12px 40px rgba(20,20,20,.08);
  --shadow-lg:  0 24px 60px rgba(20,20,20,.14);
  --ease:       cubic-bezier(.2,.7,.2,1);
  --container:  1280px;
}

*,*::before,*::after{box-sizing:border-box}
html,body{margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:'Inter', system-ui, -apple-system, sans-serif;
  color:var(--ink);
  background:var(--ivory);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:0;background:transparent}

.container{max-width:var(--container);margin:0 auto;padding:0 32px}
.center{text-align:center}
.mt-24{margin-top:24px}
.mt-40{margin-top:40px}
sup{font-size:.5em;vertical-align:super}

/* ---------- Typography ---------- */
h1,h2,h3,h4,h5{color:var(--charcoal);margin:0;letter-spacing:-.01em;font-weight:400}
h1{
  font-family:'Italiana','Cormorant Garamond',serif;
  font-size:clamp(3rem,6.5vw,6rem);
  line-height:1;letter-spacing:.02em;font-weight:400;
}
h1 em{font-family:'Cormorant Garamond',serif;font-weight:500;font-style:italic;letter-spacing:0;color:var(--gold-dark)}
h2{
  font-family:'Italiana','Cormorant Garamond',serif;
  font-size:clamp(2.2rem,4vw,3.8rem);
  line-height:1.1;letter-spacing:.02em;
}
h2 em{font-family:'Cormorant Garamond',serif;font-style:italic;font-weight:500;color:var(--gold-dark);letter-spacing:0}
h3{font-family:'Cormorant Garamond',serif;font-size:1.45rem;line-height:1.25;font-weight:600}
h4{font-size:.82rem;color:var(--charcoal);letter-spacing:.2em;text-transform:uppercase;font-weight:700;font-family:'Inter',sans-serif}
h5{font-size:.72rem;color:var(--charcoal);letter-spacing:.22em;text-transform:uppercase;font-weight:700;font-family:'Inter',sans-serif}
em{font-style:italic;color:var(--gold-dark);font-weight:500}

.eyebrow{
  font-family:'Inter',sans-serif;
  font-size:.7rem;font-weight:600;
  letter-spacing:.25em;color:var(--gold-dark);
  text-transform:uppercase;display:inline-block;margin-bottom:16px;
}
.eyebrow.light{color:var(--gold-soft)}
.center-eyebrow{display:block;text-align:center}

.underline{background:linear-gradient(transparent 62%, rgba(201,169,97,.35) 62%);padding:0 2px}

.section-head{margin-bottom:64px}
.section-head.center{text-align:center;max-width:680px;margin-inline:auto}
.section-head.between{
  display:flex;justify-content:space-between;align-items:flex-end;
  text-align:left;flex-wrap:wrap;gap:24px;
}
.section-sub{color:var(--muted);margin-top:18px;font-size:1rem}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:15px 30px;border-radius:999px;border:1px solid transparent;
  font-weight:600;font-size:.82rem;letter-spacing:.1em;text-transform:uppercase;
  transition:all .3s var(--ease);
  font-family:'Inter',sans-serif;
}
.btn i{font-size:.9em;letter-spacing:0}
.btn-primary{background:var(--charcoal);color:var(--ivory)}
.btn-primary:hover{background:var(--gold-dark);transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-dark{background:var(--charcoal);color:var(--ivory);padding:12px 20px;font-size:.74rem}
.btn-dark:hover{background:var(--gold-dark)}
.btn-outline{background:transparent;border-color:var(--charcoal);color:var(--charcoal)}
.btn-outline:hover{background:var(--charcoal);color:var(--ivory)}
.btn-ghost{background:transparent;color:var(--charcoal);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--charcoal)}
.btn-gold{background:linear-gradient(135deg,var(--gold) 0%,var(--gold-dark) 100%);color:var(--white);border:0}
.btn-gold:hover{filter:brightness(1.1);transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-block{display:flex;width:100%;justify-content:center}

.link-arrow{
  display:inline-flex;align-items:center;gap:8px;
  font-weight:600;font-size:.8rem;color:var(--charcoal);
  border-bottom:1px solid var(--charcoal);padding-bottom:3px;
  transition:all .25s var(--ease);text-transform:uppercase;letter-spacing:.12em;
}
.link-arrow:hover{color:var(--gold-dark);border-color:var(--gold-dark);gap:14px}
.link-arrow.sm{font-size:.7rem;letter-spacing:.15em}

/* ---------- Announcement bar ---------- */
.announce{background:var(--charcoal);color:var(--ivory);overflow:hidden;border-bottom:1px solid rgba(255,255,255,.04)}
.announce-track{
  display:flex;gap:80px;white-space:nowrap;padding:10px 0;
  animation:marquee 40s linear infinite;
  font-size:.72rem;letter-spacing:.2em;text-transform:uppercase;font-weight:500;
}
.announce-track span{position:relative}
.announce-track span::after{
  content:"";position:absolute;right:-40px;top:50%;transform:translateY(-50%);
  width:4px;height:4px;background:var(--gold);border-radius:50%;
}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Topbar ---------- */
.topbar{background:#fff;color:var(--ink);font-size:.78rem;padding:8px 0;border-bottom:1px solid var(--line)}
.topbar-inner{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.topbar-left,.topbar-right{display:flex;gap:28px;align-items:center;flex-wrap:wrap}
.topbar i{color:var(--gold-dark);margin-right:6px}
.topbar-right a:hover{color:var(--gold-dark)}

.locale{position:relative}
.locale-btn{display:inline-flex;align-items:center;gap:6px;font-size:.78rem;color:var(--ink)}
.locale-btn .flag{font-size:1rem}
.locale-btn i{font-size:.7em;color:var(--muted)}
.locale-menu{
  position:absolute;top:calc(100% + 8px);right:0;min-width:180px;
  background:#fff;border:1px solid var(--line);border-radius:12px;
  padding:6px;box-shadow:var(--shadow);
  opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .25s var(--ease);z-index:60;
}
.locale:hover .locale-menu{opacity:1;visibility:visible;transform:translateY(0)}
.locale-menu a{display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;font-size:.82rem}
.locale-menu a:hover{background:var(--cream)}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:50;background:rgba(248,245,240,.96);
  backdrop-filter:blur(16px);border-bottom:1px solid var(--line);
  transition:padding .3s var(--ease);
}
.site-header.scrolled{padding:0}
.header-inner{
  display:grid;grid-template-columns:auto 1fr auto;
  align-items:center;gap:24px;padding:18px 32px;
}
.logo{display:flex;align-items:center;gap:14px;justify-self:center;grid-column:2}
.logo-mark{
  width:48px;height:48px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold) 0%,var(--gold-dark) 100%);
  color:var(--ivory);display:grid;place-items:center;
  font-family:'Italiana',serif;font-size:1.8rem;font-weight:400;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.3),0 4px 12px rgba(201,169,97,.25);
}
.logo-text{display:flex;flex-direction:column;line-height:1}
.logo-text strong{font-family:'Italiana',serif;font-size:1.6rem;font-weight:400;letter-spacing:.2em;color:var(--charcoal)}
.logo-text em{font-size:.6rem;letter-spacing:.3em;color:var(--gold-dark);margin-top:4px;text-transform:uppercase;font-style:normal;font-family:'Inter',sans-serif}

.main-nav{display:flex;justify-content:center;gap:32px;grid-column:1 / span 3;grid-row:2;padding-top:14px;border-top:1px solid var(--line);margin:0 -32px;padding-left:32px;padding-right:32px}
.main-nav > a,.nav-item > a{
  font-size:.78rem;font-weight:500;letter-spacing:.18em;text-transform:uppercase;
  color:var(--ink);padding:8px 2px;position:relative;display:inline-flex;align-items:center;gap:6px;
  transition:color .25s var(--ease);
}
.main-nav > a:hover,.nav-item:hover > a{color:var(--gold-dark)}
.main-nav > a.active{color:var(--charcoal)}
.main-nav > a.active::after{
  content:"";position:absolute;left:50%;right:0;bottom:-2px;height:2px;
  width:24px;margin-left:-12px;background:var(--gold);
}
.nav-item{position:static}
.nav-item > a i{font-size:.55rem;opacity:.6}

/* Mega-menu */
.mega{
  position:absolute;left:0;right:0;top:100%;background:#fff;
  border-top:1px solid var(--line);box-shadow:var(--shadow);
  padding:40px 32px;opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .3s var(--ease);z-index:40;
}
.nav-item:hover .mega{opacity:1;visibility:visible;transform:translateY(0)}
.mega-grid{max-width:var(--container);margin:0 auto;display:grid;grid-template-columns:repeat(3,1fr) 1.3fr;gap:50px}
.mega h5{margin-bottom:18px}
.mega ul{list-style:none;padding:0;margin:0}
.mega ul li{padding:6px 0}
.mega ul a{font-size:.88rem;color:var(--ink);transition:color .2s var(--ease)}
.mega ul a:hover{color:var(--gold-dark)}
.mega-feature{
  background:linear-gradient(135deg,var(--cream),var(--blush));
  border-radius:var(--radius);padding:24px;
  display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center;position:relative;
  transition:all .3s var(--ease);
}
.mega-feature:hover{transform:translateY(-3px);box-shadow:var(--shadow)}
.mega-feature .tag-gold{
  position:absolute;top:12px;right:12px;font-size:.58rem;font-weight:700;letter-spacing:.2em;
  color:var(--white);background:var(--gold);padding:4px 8px;border-radius:3px;
}
.mega-visual{width:80px}
.mega-feature strong{display:block;font-family:'Cormorant Garamond',serif;font-size:1.2rem;color:var(--charcoal)}
.mega-feature span{font-size:.78rem;color:var(--muted);margin-top:2px;display:block}

.header-actions{display:flex;align-items:center;gap:8px}
.icon-btn{
  width:42px;height:42px;border-radius:50%;
  color:var(--charcoal);position:relative;
  transition:all .25s var(--ease);
}
.icon-btn:hover{background:var(--cream)}
.badge{
  position:absolute;top:2px;right:2px;background:var(--gold);color:var(--white);
  font-size:.62rem;font-weight:700;min-width:17px;height:17px;border-radius:50%;
  display:grid;place-items:center;padding:0 4px;
}
.burger{display:none;font-size:1.3rem;color:var(--charcoal);grid-column:1}

/* ---------- HERO ---------- */
.hero{
  position:relative;overflow:hidden;
  background:var(--ivory);
  padding:90px 0 110px;min-height:88vh;
}
.hero-bg{position:absolute;inset:0;z-index:0;pointer-events:none}
.bg-blur{position:absolute;border-radius:50%;filter:blur(80px);opacity:.7}
.b1{width:600px;height:600px;background:var(--blush);top:-100px;right:-150px}
.b2{width:500px;height:500px;background:var(--cream);bottom:-150px;left:-100px}
.b3{width:400px;height:400px;background:rgba(201,169,97,.15);top:30%;left:40%}
.bg-grain{
  position:absolute;inset:0;opacity:.04;pointer-events:none;
  background-image:radial-gradient(circle at 1px 1px,var(--charcoal) 1px, transparent 0);
  background-size:3px 3px;
}

.hero-side{
  position:absolute;left:32px;top:50%;transform:translateY(-50%) rotate(-90deg);transform-origin:left center;
  display:flex;gap:14px;font-size:.7rem;letter-spacing:.35em;color:var(--muted);text-transform:uppercase;z-index:2;
}
.hero-side .dot{color:var(--gold);font-size:.5rem}

.hero-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:60px;align-items:center;position:relative;z-index:2}
.h1-line{display:block}
.h1-line--italic{font-family:'Cormorant Garamond',serif;font-style:italic;padding-left:80px;color:var(--gold-dark);font-weight:500}
.lead{font-size:1.05rem;color:var(--muted);max-width:540px;margin:28px 0 36px;line-height:1.75}
.lead strong{color:var(--charcoal);font-weight:600}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:56px}

.hero-meta{display:flex;gap:44px;border-top:1px solid var(--line-dark);padding-top:24px;max-width:540px;flex-wrap:wrap}
.hero-meta > div strong{font-family:'Italiana',serif;font-size:2rem;color:var(--charcoal);display:block;line-height:1}
.hero-meta > div span{font-size:.7rem;letter-spacing:.15em;color:var(--muted);text-transform:uppercase;margin-top:4px;display:block}

/* Hero visual frame */
.hero-visual{position:relative;display:grid;place-items:center;min-height:580px}
.hero-frame{
  position:relative;width:100%;max-width:440px;aspect-ratio:3/4;
  border-radius:calc(var(--radius) + 8px);overflow:hidden;
  box-shadow:var(--shadow-lg);background:#fff;
}
.hero-gradient{
  position:absolute;inset:0;
  background:
    radial-gradient(circle at 30% 20%,var(--blush),transparent 60%),
    radial-gradient(circle at 70% 80%,rgba(201,169,97,.25),transparent 55%),
    linear-gradient(180deg,#fdfaf3,var(--cream));
}
.bottle-hero{position:absolute;top:50%;left:50%;transform:translate(-50%,-52%);width:62%;filter:drop-shadow(0 30px 40px rgba(20,20,20,.25))}
.price-tag{
  position:absolute;bottom:22px;left:22px;right:22px;background:rgba(255,255,255,.92);backdrop-filter:blur(10px);
  border-radius:12px;padding:14px 18px;display:flex;align-items:center;gap:14px;justify-content:space-between;
  border:1px solid var(--line);
}
.price-tag .small{font-size:.65rem;letter-spacing:.2em;color:var(--gold-dark);text-transform:uppercase;font-weight:600;display:block}
.price-tag strong{font-family:'Cormorant Garamond',serif;font-size:1.4rem;color:var(--charcoal);display:block;margin-top:2px}
.price-tag a{font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;color:var(--charcoal);font-weight:600;border-bottom:1px solid var(--charcoal);padding-bottom:2px}
.price-tag a:hover{color:var(--gold-dark);border-color:var(--gold-dark)}

.float-chip{
  position:absolute;background:var(--white);border-radius:999px;
  padding:10px 18px;font-size:.78rem;font-weight:500;
  box-shadow:var(--shadow);border:1px solid var(--line);
  display:flex;align-items:center;gap:8px;
}
.float-chip i{color:var(--gold-dark)}
.chip-1{top:8%;left:-6%}
.chip-2{bottom:12%;right:-4%}

.hero-scroll{
  position:absolute;bottom:30px;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:6px;
  font-size:.66rem;letter-spacing:.3em;color:var(--muted);text-transform:uppercase;z-index:3;
  animation:bob 2.2s ease-in-out infinite;
}
.hero-scroll i{color:var(--gold-dark)}
@keyframes bob{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(6px)}}

/* ---------- PRESS ---------- */
.press{background:#fff;padding:50px 0;border-bottom:1px solid var(--line)}
.press-label{text-align:center;font-size:.7rem;letter-spacing:.3em;color:var(--muted);text-transform:uppercase;margin:0 0 24px}
.press-logos{display:flex;justify-content:space-around;align-items:center;gap:32px;flex-wrap:wrap}
.press-item{color:#555;opacity:.5;transition:opacity .3s var(--ease)}
.press-item:hover{opacity:1}

/* ---------- STATEMENT ---------- */
.statement{padding:120px 0;background:var(--ivory);text-align:center}
.statement-head{
  font-family:'Cormorant Garamond',serif;font-size:clamp(1.8rem,3vw,2.8rem);
  max-width:960px;margin:0 auto;line-height:1.35;color:var(--charcoal);font-weight:400;
  font-style:italic;
}
.statement-head em{font-style:italic}
.statement-sign{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:36px;color:var(--muted);font-size:.82rem}
.sig-line{width:40px;height:1px;background:var(--gold-dark)}

/* ---------- CATEGORIES ---------- */
.categories{padding:120px 0;background:var(--white)}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.cat-card{
  background:var(--white);border-radius:var(--radius);overflow:hidden;
  transition:all .4s var(--ease);display:flex;flex-direction:column;
  border:1px solid transparent;
}
.cat-card:hover{transform:translateY(-6px);border-color:var(--gold);box-shadow:var(--shadow)}
.cat-visual{
  aspect-ratio:4/5;position:relative;display:grid;place-items:center;
  color:rgba(20,20,20,.15);font-size:5rem;
}
.cat-visual::after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 60%,rgba(0,0,0,.06));
}
.cat-v1{background:linear-gradient(135deg,#fbeacd,#f1c985)}
.cat-v2{background:linear-gradient(135deg,#fadad2,#e3a294)}
.cat-v3{background:linear-gradient(135deg,#e7ede2,#a7bfa3)}
.cat-v4{background:linear-gradient(135deg,#efe5d7,#d5bb95)}
.cat-n{
  position:absolute;top:18px;left:18px;font-family:'Italiana',serif;font-size:1.2rem;letter-spacing:.15em;
  color:var(--charcoal);opacity:.8;
}
.cat-visual i{position:relative;z-index:1}
.cat-body{padding:26px 24px 28px}
.cat-body h3{font-size:1.5rem;margin-bottom:6px}
.cat-body p{color:var(--muted);font-size:.9rem;margin:0 0 14px}
.cat-cta{
  font-size:.72rem;font-weight:600;color:var(--charcoal);letter-spacing:.15em;text-transform:uppercase;
  display:inline-flex;align-items:center;gap:6px;
  transition:gap .25s var(--ease),color .25s var(--ease);
}
.cat-card:hover .cat-cta{color:var(--gold-dark);gap:12px}

/* ---------- PRODUCTS ---------- */
.products{padding:120px 0;background:linear-gradient(180deg,var(--ivory),var(--white))}
.product-tabs{display:flex;gap:8px;flex-wrap:wrap}
.tab{
  padding:10px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-size:.74rem;font-weight:600;color:var(--ink);letter-spacing:.1em;text-transform:uppercase;
  transition:all .25s var(--ease);
}
.tab:hover{border-color:var(--charcoal)}
.tab.active{background:var(--charcoal);color:var(--ivory);border-color:var(--charcoal)}

.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);display:flex;flex-direction:column;
}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold-soft)}
.product-media{
  position:relative;padding:40px 20px 22px;display:grid;place-items:center;min-height:320px;
}
.gradient-sun{background:linear-gradient(135deg,#fbeacd,#f3d294)}
.gradient-rose{background:linear-gradient(135deg,#fadad2,#e8b3a5)}
.gradient-sage{background:linear-gradient(135deg,#e7ede2,#b3c8ae)}
.gradient-cream{background:linear-gradient(135deg,#efe5d7,#dcc5a1)}
.bottle-svg{width:140px;height:auto;filter:drop-shadow(0 16px 20px rgba(20,20,20,.15))}

.tag{
  position:absolute;top:14px;left:14px;font-size:.62rem;font-weight:700;
  letter-spacing:.22em;padding:5px 10px;border-radius:3px;color:var(--white);text-transform:uppercase;
}
.tag-sale{background:var(--charcoal)}
.tag-hot{background:#b44646}
.tag-new{background:#3b7a57}
.wish{
  position:absolute;top:10px;right:10px;width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.8);color:var(--charcoal);
  backdrop-filter:blur(6px);transition:all .25s var(--ease);display:grid;place-items:center;font-size:.9rem;
}
.wish:hover{background:var(--charcoal);color:var(--gold-soft)}
.quick{
  position:absolute;bottom:16px;left:50%;transform:translate(-50%,8px);
  opacity:0;background:var(--charcoal);color:var(--ivory);
  padding:10px 20px;border-radius:999px;font-size:.68rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;
  transition:all .3s var(--ease);
}
.product-card:hover .quick{opacity:1;transform:translate(-50%,0)}

.product-body{padding:22px 22px 26px;display:flex;flex-direction:column;gap:10px;flex:1}
.product-body .cat{font-size:.68rem;letter-spacing:.22em;color:var(--gold-dark);font-weight:600;text-transform:uppercase}
.product-body h3{font-family:'Cormorant Garamond',serif;font-size:1.2rem;font-weight:600;color:var(--charcoal);line-height:1.3;min-height:54px}
.variants{display:flex;gap:6px}
.dot-swatch{
  width:16px;height:16px;border-radius:50%;border:1px solid rgba(0,0,0,.08);
  cursor:pointer;transition:transform .2s var(--ease);
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.6);
}
.dot-swatch:hover{transform:scale(1.2)}
.stars{color:var(--gold);font-size:.78rem;display:flex;align-items:center;gap:2px}
.stars small{color:var(--muted);margin-left:6px;font-size:.74rem}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:auto}
.price{font-size:1.2rem;font-weight:700;color:var(--charcoal);font-family:'Cormorant Garamond',serif}
.price-old{font-size:.84rem;color:var(--muted);text-decoration:line-through}

/* ---------- INGREDIENT SPOTLIGHT ---------- */
.ingredient{padding:120px 0;background:linear-gradient(180deg,var(--white) 0%,var(--cream) 100%)}
.ing-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:80px;align-items:center}
.ing-visual{position:relative;aspect-ratio:1/1;display:grid;place-items:center}
.ing-orb{
  width:78%;aspect-ratio:1;border-radius:50%;position:relative;
  background:
    radial-gradient(circle at 30% 30%,#fff6e0,#f1c985 40%,#b4812d 80%);
  box-shadow:
    inset -30px -30px 80px rgba(0,0,0,.25),
    inset 30px 30px 80px rgba(255,255,255,.35),
    0 30px 70px rgba(201,169,97,.35);
  animation:orbSpin 20s linear infinite;
}
.orb-core{
  position:absolute;top:20%;left:22%;width:26%;height:22%;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#fff,rgba(255,255,255,0));
  filter:blur(2px);
}
@keyframes orbSpin{to{transform:rotate(360deg)}}
.particle{
  position:absolute;width:14px;height:14px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#fff6e0,#d9b36b);
  box-shadow:0 6px 14px rgba(201,169,97,.35);
  animation:floatP 6s ease-in-out infinite;
}
.p1{top:5%;left:10%;animation-delay:0s}
.p2{top:20%;right:8%;width:10px;height:10px;animation-delay:1s}
.p3{bottom:15%;right:15%;width:16px;height:16px;animation-delay:2s}
.p4{bottom:8%;left:20%;width:8px;height:8px;animation-delay:3s}
.p5{top:50%;left:-2%;width:12px;height:12px;animation-delay:1.5s}
@keyframes floatP{0%,100%{transform:translateY(0)}50%{transform:translateY(-16px)}}

.ing-callout{
  position:absolute;right:4%;bottom:6%;background:var(--charcoal);color:var(--ivory);
  padding:16px 22px;border-radius:12px;box-shadow:var(--shadow-lg);
}
.ing-callout strong{display:block;font-family:'Cormorant Garamond',serif;font-size:1.25rem;color:var(--gold-soft)}
.ing-callout span{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.7)}

.ing-lede{color:var(--muted);font-size:1.02rem;margin:16px 0 36px;max-width:540px;line-height:1.75}
.ing-list{display:grid;grid-template-columns:1fr 1fr;gap:28px 40px}
.ing-item{display:flex;gap:18px;align-items:flex-start}
.ing-num{
  font-family:'Italiana',serif;font-size:1.4rem;color:var(--gold-dark);
  letter-spacing:.05em;padding-top:2px;min-width:28px;
}
.ing-item strong{display:block;color:var(--charcoal);font-weight:600;margin-bottom:4px}
.ing-item p{font-size:.86rem;color:var(--muted);margin:0;line-height:1.6}

/* ---------- SCIENCE ---------- */
.science{padding:120px 0;background:var(--white)}
.sci-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-bottom:56px}
.sci-stat{
  background:var(--ivory);border:1px solid var(--line);border-radius:var(--radius);
  padding:40px 28px;text-align:center;position:relative;overflow:hidden;
  transition:all .35s var(--ease);
}
.sci-stat::before{
  content:"";position:absolute;top:0;left:0;right:0;height:2px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
}
.sci-stat:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.sci-num{font-family:'Italiana',serif;font-size:4.5rem;color:var(--charcoal);line-height:1;letter-spacing:0}
.sci-pct{font-family:'Italiana',serif;font-size:2rem;color:var(--gold-dark);margin-left:4px;vertical-align:top}
.sci-stat p{margin:12px 0 0;font-size:.88rem;color:var(--muted);line-height:1.5}
.sci-stat p strong{color:var(--charcoal);font-weight:600}

.cert-list{
  list-style:none;padding:0;margin:0;display:flex;justify-content:center;gap:40px;flex-wrap:wrap;
  padding-top:32px;border-top:1px solid var(--line);
}
.cert-list li{display:flex;align-items:center;gap:8px;font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600}
.cert-list i{color:var(--gold-dark);font-size:1rem}

/* ---------- RITUAL ---------- */
.ritual{padding:120px 0;background:var(--ivory)}
.ritual-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;position:relative}
.ritual-steps::before{
  content:"";position:absolute;top:80px;left:12%;right:12%;height:1px;
  background:linear-gradient(90deg,transparent,var(--gold-soft) 15%,var(--gold-soft) 85%,transparent);
  z-index:0;
}
.ritual-step{
  background:var(--white);border-radius:var(--radius);padding:40px 28px 32px;
  text-align:center;border:1px solid var(--line);transition:all .35s var(--ease);position:relative;z-index:1;
}
.ritual-step:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold-soft)}
.step-num{
  font-family:'Italiana',serif;font-size:1.3rem;color:var(--gold-dark);
  letter-spacing:.1em;display:block;margin-bottom:4px;
}
.step-icon{
  width:72px;height:72px;border-radius:50%;
  background:linear-gradient(135deg,var(--cream),var(--blush));
  display:grid;place-items:center;color:var(--gold-dark);font-size:1.5rem;
  margin:14px auto 22px;
}
.ritual-step h3{font-size:1.4rem;margin-bottom:8px}
.ritual-step p{color:var(--muted);font-size:.88rem;margin:0 0 18px;line-height:1.6}

/* ---------- BEFORE / AFTER ---------- */
.ba{padding:120px 0;background:var(--white)}
.ba-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:70px;align-items:center}
.ba-points{list-style:none;padding:0;margin:20px 0 32px}
.ba-points li{padding:10px 0;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;font-size:.9rem}
.ba-points i{color:var(--gold-dark)}
.ba-slider{
  position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;
  box-shadow:var(--shadow-lg);cursor:ew-resize;user-select:none;
}
.ba-img{position:absolute;inset:0;background-size:cover;background-position:center}
.ba-before{
  background:
    radial-gradient(circle at 50% 55%,#e2b8a5 0%,#b78878 35%,#8c5f52 70%),
    linear-gradient(180deg,#d4a190,#936651);
  background-blend-mode:multiply;
  clip-path:inset(0 50% 0 0);transition:none;
}
.ba-before::after{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 42% 48%,rgba(100,60,40,.4) 2%, transparent 8%),
    radial-gradient(circle at 55% 52%,rgba(100,60,40,.4) 2%, transparent 7%),
    radial-gradient(circle at 48% 60%,rgba(100,60,40,.35) 2%, transparent 6%),
    radial-gradient(circle at 60% 45%,rgba(100,60,40,.3) 2%, transparent 5%);
  mix-blend-mode:multiply;
}
.ba-after{
  background:
    radial-gradient(circle at 50% 55%,#fadcc8 0%,#e8bfa4 40%,#b38870 80%);
}
.ba-label{
  position:absolute;top:18px;padding:6px 14px;background:rgba(255,255,255,.85);backdrop-filter:blur(6px);
  font-size:.68rem;letter-spacing:.22em;text-transform:uppercase;font-weight:600;color:var(--charcoal);border-radius:4px;
  z-index:3;pointer-events:none;
}
.ba-label-before{left:18px}
.ba-label-after{right:18px}
.ba-handle{
  position:absolute;top:0;bottom:0;left:50%;width:2px;background:var(--ivory);z-index:4;
  cursor:ew-resize;
}
.ba-knob{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:48px;height:48px;border-radius:50%;background:var(--ivory);color:var(--charcoal);
  display:grid;grid-template-columns:1fr 1fr;place-items:center;gap:4px;padding:0 6px;
  box-shadow:0 6px 18px rgba(0,0,0,.25);font-size:.7rem;
}

/* ---------- STORY ---------- */
.story{padding:130px 0;background:var(--ivory)}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:90px;align-items:center}
.story-visual{position:relative;display:grid;grid-template-columns:1.2fr 1fr;grid-template-rows:1fr 1fr;gap:16px;aspect-ratio:1/1.05}
.story-img{border-radius:var(--radius);overflow:hidden;background-size:cover;background-position:center}
.img-1{grid-row:1/3;position:relative}
.img-1 svg{width:100%;height:100%;object-fit:cover}
.img-2{background:
  radial-gradient(circle at 70% 30%,rgba(255,255,255,.6),transparent 50%),
  linear-gradient(135deg,var(--sage),#b8c7b0)}
.img-3{background:
  radial-gradient(circle at 30% 70%,rgba(255,255,255,.5),transparent 50%),
  linear-gradient(135deg,var(--rose),#eccfc3)}
.story-badge{
  position:absolute;bottom:-30px;left:-30px;background:var(--charcoal);
  color:var(--ivory);padding:24px 28px;border-radius:var(--radius);
  display:flex;align-items:center;gap:14px;box-shadow:var(--shadow-lg);
}
.story-badge strong{font-family:'Italiana',serif;font-size:2.6rem;color:var(--gold-soft);line-height:1;letter-spacing:.08em}
.story-badge span{font-size:.74rem;line-height:1.4;letter-spacing:.08em}

.story-copy p{color:var(--muted);margin:18px 0;line-height:1.8}
.story-copy p strong{color:var(--charcoal)}
.story-quote{
  margin:28px 0;padding:24px 28px;border-left:2px solid var(--gold);
  background:var(--white);border-radius:0 12px 12px 0;
  font-family:'Cormorant Garamond',serif;font-style:italic;font-size:1.2rem;color:var(--charcoal);
}

/* ---------- VALUES / Sustainability ---------- */
.values{padding:120px 0;background:var(--white)}
.values-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.value-card{
  padding:36px 28px;text-align:center;border-radius:var(--radius);
  background:var(--ivory);border:1px solid var(--line);transition:all .35s var(--ease);
}
.value-card:hover{transform:translateY(-4px);border-color:var(--gold);box-shadow:var(--shadow)}
.value-icon{
  width:60px;height:60px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold-soft),var(--gold));color:var(--white);
  display:grid;place-items:center;font-size:1.3rem;margin:0 auto 20px;
  box-shadow:0 10px 24px rgba(201,169,97,.3);
}
.value-card h3{font-size:1.25rem;margin-bottom:8px}
.value-card p{font-size:.88rem;color:var(--muted);margin:0;line-height:1.6}

/* ---------- AUTH / QR ---------- */
.auth{padding:100px 0;background:var(--ivory)}
.auth-card{
  background:linear-gradient(135deg,var(--charcoal) 0%,#252018 100%);
  color:var(--ivory);border-radius:calc(var(--radius) + 8px);
  padding:80px 70px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;
  position:relative;overflow:hidden;
}
.auth-card::before{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 80% 20%,rgba(201,169,97,.2),transparent 50%),
    radial-gradient(circle at 10% 90%,rgba(201,169,97,.1),transparent 45%);
  pointer-events:none;
}
.auth-copy h2{color:var(--ivory);position:relative}
.auth-copy h2 em{color:var(--gold-soft)}
.auth-copy p{color:#c9c3b6;margin:18px 0 30px;max-width:480px;line-height:1.75}
.auth-copy p strong{color:var(--gold-soft)}
.store-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px;position:relative}
.store-btn{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--ivory);color:var(--charcoal);padding:10px 18px;border-radius:12px;
  transition:all .25s var(--ease);
}
.store-btn:hover{transform:translateY(-2px)}
.store-btn i{font-size:1.7rem}
.store-btn span{display:flex;flex-direction:column;line-height:1.1;font-size:.95rem;font-weight:600}
.store-btn small{font-size:.6rem;font-weight:500;color:var(--muted);letter-spacing:.08em}
.store-btns.sm .store-btn{padding:8px 14px;background:transparent;color:var(--ivory);border:1px solid rgba(255,255,255,.18)}
.store-btns.sm .store-btn small{color:rgba(255,255,255,.55)}
.auth-copy .link-arrow{color:var(--gold-soft);border-color:var(--gold-soft)}
.auth-copy .link-arrow:hover{color:var(--ivory);border-color:var(--ivory)}

.auth-visual{position:relative;display:grid;place-items:center}
.qr-frame{text-align:center;color:var(--ivory)}
.qr-mock{
  width:240px;height:240px;background:var(--ivory);border-radius:22px;
  padding:24px;position:relative;margin:0 auto 16px;
  box-shadow:0 30px 60px rgba(0,0,0,.4);
}
.qr-dot{position:absolute;width:46px;height:46px;border:7px solid var(--charcoal);border-radius:8px}
.qr-dot.tl{top:20px;left:20px}
.qr-dot.tr{top:20px;right:20px}
.qr-dot.bl{bottom:20px;left:20px}
.qr-inner{
  position:absolute;inset:28px;
  background-image:
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal));
  background-size:12px 12px,18px 18px,24px 12px,12px 24px,15px 15px,20px 14px,14px 20px,22px 22px;
  background-position:80px 26px,28px 92px,100px 80px,160px 100px,70px 140px,140px 150px,108px 180px,34px 160px;
  background-repeat:no-repeat;
}
.qr-logo{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:56px;height:56px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  display:grid;place-items:center;color:var(--ivory);
  font-family:'Italiana',serif;font-size:2rem;
  box-shadow:inset 0 0 0 3px var(--ivory),0 4px 10px rgba(0,0,0,.3);
}
.qr-frame p{font-size:.74rem;letter-spacing:.22em;color:var(--gold-soft);text-transform:uppercase;font-weight:600}

/* ---------- TESTIMONIALS ---------- */
.testimonials{padding:120px 0;background:var(--cream)}
.tm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.tm-card{
  background:var(--white);border-radius:var(--radius);padding:40px 32px;
  margin:0;box-shadow:var(--shadow-sm);position:relative;display:flex;flex-direction:column;gap:20px;
}
.tm-card::before{
  content:"\201C";position:absolute;top:10px;right:28px;
  font-family:'Italiana',serif;font-size:5rem;color:var(--gold);line-height:1;opacity:.35;
}
.tm-card p{font-family:'Cormorant Garamond',serif;font-size:1.2rem;line-height:1.45;color:var(--charcoal);margin:0;font-style:italic}
.tm-card footer{display:flex;align-items:center;gap:12px;margin-top:auto;border-top:1px solid var(--line);padding-top:18px}
.avatar{
  width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  display:grid;place-items:center;color:var(--ivory);font-weight:600;font-size:.88rem;
}
.tm-card footer strong{display:block;font-size:.92rem;color:var(--charcoal)}
.tm-card footer span{font-size:.76rem;color:var(--muted)}

/* ---------- CLUB ---------- */
.club{padding:120px 0;background:
  radial-gradient(circle at 20% 30%,rgba(201,169,97,.1),transparent 50%),
  linear-gradient(135deg,var(--charcoal) 0%,#1d1a16 100%);
  color:var(--ivory)}
.club-grid{display:grid;grid-template-columns:1fr;justify-items:center;text-align:center;max-width:980px;margin:0 auto}
.club h2{color:var(--ivory)}
.club h2 em{color:var(--gold-soft)}
.club-copy p{color:#c9c3b6;max-width:640px;margin:18px 0 40px;line-height:1.75}
.tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;width:100%;margin-bottom:40px}
.tier{
  background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:var(--radius);
  padding:30px 24px;text-align:center;
}
.tier-gold{
  background:linear-gradient(180deg,rgba(201,169,97,.15),rgba(201,169,97,.02));
  border-color:var(--gold);transform:scale(1.04);
}
.tier-level{font-family:'Italiana',serif;font-size:1.3rem;color:var(--gold-soft);letter-spacing:.15em;display:block;margin-bottom:8px}
.tier strong{font-family:'Cormorant Garamond',serif;font-size:1.6rem;color:var(--ivory);display:block;margin-bottom:16px}
.tier ul{list-style:none;padding:0;margin:0;color:#bfb8aa;font-size:.86rem}
.tier ul li{padding:6px 0;border-top:1px solid rgba(255,255,255,.06)}
.tier ul li:first-child{border-top:0}

/* ---------- DEALER ---------- */
.dealer{padding:120px 0;background:var(--ivory);position:relative;overflow:hidden}
.dealer::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 85% 15%,rgba(201,169,97,.1),transparent 50%);
  pointer-events:none;
}
.dealer-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;position:relative}
.dealer p{color:var(--muted);margin:18px 0 36px;max-width:480px;line-height:1.75}
.dealer-points{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.dealer-points li{
  background:var(--white);padding:24px 20px;border-radius:12px;border:1px solid var(--line);
}
.dealer-points strong{display:block;font-family:'Italiana',serif;font-size:2.2rem;color:var(--gold-dark);line-height:1;letter-spacing:.02em}
.dealer-points span{font-size:.74rem;letter-spacing:.1em;color:var(--muted);margin-top:8px;display:block;text-transform:uppercase}

.dealer-form{
  background:var(--white);color:var(--charcoal);
  padding:42px 38px;border-radius:var(--radius);box-shadow:var(--shadow);border:1px solid var(--line);
}
.dealer-form h3{font-family:'Cormorant Garamond',serif;font-size:1.7rem;margin-bottom:22px;font-weight:600}
.dealer-form label{display:block;font-size:.76rem;font-weight:600;color:var(--charcoal);margin-bottom:16px;letter-spacing:.08em;text-transform:uppercase}
.dealer-form input,.dealer-form textarea,.dealer-form select{
  width:100%;padding:13px 14px;margin-top:8px;
  border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.92rem;background:var(--ivory);
  transition:border-color .25s var(--ease);
  color:var(--charcoal);text-transform:none;letter-spacing:0;font-weight:400;
}
.dealer-form input:focus,.dealer-form textarea:focus,.dealer-form select:focus{outline:0;border-color:var(--gold);background:var(--white)}
.form-note{display:block;margin-top:12px;font-size:.74rem;color:var(--muted);text-align:center}

/* ---------- JOURNAL ---------- */
.news{padding:120px 0;background:var(--white)}
.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.news-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
}
.news-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold-soft)}
.news-thumb{height:240px;background-size:cover;background-position:center;position:relative}
.news-thumb::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 60%,rgba(0,0,0,.1))}
.thumb-1{background:
  radial-gradient(circle at 30% 30%,rgba(255,255,255,.5),transparent 50%),
  linear-gradient(135deg,#f4d3ac,#e7a873)}
.thumb-2{background:
  radial-gradient(circle at 70% 40%,rgba(255,255,255,.4),transparent 50%),
  linear-gradient(135deg,#cfe1d6,#8ab39c)}
.thumb-3{background:
  radial-gradient(circle at 40% 60%,rgba(255,255,255,.4),transparent 50%),
  linear-gradient(135deg,#e8d4cc,#c69b8a)}
.news-body{padding:26px 28px 30px}
.news-meta{font-size:.68rem;color:var(--gold-dark);font-weight:600;letter-spacing:.18em;text-transform:uppercase}
.news-card h3{font-family:'Cormorant Garamond',serif;font-size:1.5rem;font-weight:600;margin:12px 0 12px;line-height:1.25}
.news-card p{color:var(--muted);font-size:.9rem;margin:0 0 16px;line-height:1.65}

/* ---------- INSTAGRAM ---------- */
.insta{padding:120px 0;background:var(--cream)}
.insta-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:4px}
.ig{
  aspect-ratio:1;display:grid;place-items:center;color:rgba(255,255,255,0);
  font-size:2rem;transition:all .3s var(--ease);position:relative;overflow:hidden;
}
.ig::after{content:"";position:absolute;inset:0;background:rgba(20,20,20,.35);opacity:0;transition:opacity .3s var(--ease)}
.ig:hover{color:var(--ivory)}
.ig:hover::after{opacity:1}
.ig i{position:relative;z-index:1}
.ig-1{background:linear-gradient(135deg,#fbeacd,#d9a770)}
.ig-2{background:linear-gradient(135deg,#e7ede2,#8fa78a)}
.ig-3{background:linear-gradient(135deg,#f7dfd6,#c99a8c)}
.ig-4{background:linear-gradient(135deg,#efe5d7,#bf9a6c)}
.ig-5{background:linear-gradient(135deg,#d6d1c4,#938573)}
.ig-6{background:linear-gradient(135deg,#fadad2,#d6927e)}

/* ---------- NEWSLETTER ---------- */
.newsletter{background:linear-gradient(135deg,var(--blush),var(--cream));padding:80px 0}
.news-inner{display:flex;justify-content:space-between;align-items:center;gap:40px;flex-wrap:wrap}
.news-inner h3{font-family:'Italiana',serif;font-size:2.2rem;font-weight:400;letter-spacing:.04em}
.news-inner p{color:var(--muted);margin:6px 0 0;max-width:440px}
.news-inner form{display:flex;gap:10px;flex:1;max-width:460px}
.news-inner input{
  flex:1;padding:15px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-family:inherit;font-size:.9rem;
}
.news-inner input:focus{outline:0;border-color:var(--gold)}

/* ---------- FOOTER ---------- */
.site-footer{background:#0f0f0f;color:#c9c3b6;padding:90px 0 0}
.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1.2fr;gap:40px}
.logo-light .logo-text strong{color:var(--ivory)}
.logo-light .logo-text em{color:var(--gold-soft)}
.footer-about{font-size:.86rem;line-height:1.75;margin:22px 0}
.footer-contact{list-style:none;padding:0;margin:0 0 22px}
.footer-contact li{padding:6px 0;font-size:.86rem}
.footer-contact i{color:var(--gold);width:20px}
.footer-contact a:hover{color:var(--gold-soft)}
.footer-app{font-size:.82rem;color:#a8a094;margin:0 0 14px;line-height:1.6}
.site-footer h4{color:var(--ivory);font-size:.74rem;letter-spacing:.22em;margin-bottom:20px}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer ul li{padding:6px 0;font-size:.86rem}
.site-footer ul a{transition:color .2s var(--ease)}
.site-footer ul a:hover{color:var(--gold-soft)}
.socials{display:flex;gap:8px}
.socials a{
  width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.08);display:grid;place-items:center;
  color:var(--ivory);font-size:.88rem;transition:all .25s var(--ease);
}
.socials a:hover{background:var(--gold);border-color:var(--gold);color:var(--charcoal)}

.pay-row{display:flex;gap:6px;flex-wrap:wrap}
.pay{
  background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:#e1d9c8;
  padding:4px 10px;border-radius:6px;font-size:.68rem;letter-spacing:.15em;font-weight:700;
}

.copyright{margin-top:70px;border-top:1px solid rgba(255,255,255,.06);padding:22px 0;font-size:.78rem}
.copyright-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
.copyright .legal{display:flex;gap:22px}
.copyright .legal a{color:#a8a094}
.copyright .legal a:hover{color:var(--gold-soft)}

/* ---------- Floating actions ---------- */
.floating{position:fixed;right:20px;bottom:24px;display:flex;flex-direction:column;gap:10px;z-index:60}
.fab{
  width:52px;height:52px;border-radius:50%;display:grid;place-items:center;
  color:var(--ivory);box-shadow:var(--shadow);position:relative;
  transition:all .25s var(--ease);
}
.fab:hover{transform:translateY(-3px)}
.fab-call{background:var(--gold);animation:pulse 2.2s infinite}
.tip{
  position:absolute;right:60px;background:var(--charcoal);color:var(--ivory);
  padding:5px 12px;border-radius:999px;font-size:.72rem;white-space:nowrap;
  opacity:0;transform:translateX(8px);transition:all .25s var(--ease);pointer-events:none;
}
.fab:hover .tip{opacity:1;transform:translateX(0)}
.fab-zalo{background:#0084ff}
.fab-label{font-weight:700;font-size:.68rem;letter-spacing:.02em}
.fab-fb{background:#0078ff}
.fab-top{background:var(--charcoal);opacity:0;pointer-events:none;transform:translateY(12px);transition:all .25s var(--ease)}
.fab-top.show{opacity:1;pointer-events:auto;transform:none}
@keyframes pulse{
  0%{box-shadow:0 0 0 0 rgba(201,169,97,.55)}
  70%{box-shadow:0 0 0 18px rgba(201,169,97,0)}
  100%{box-shadow:0 0 0 0 rgba(201,169,97,0)}
}

/* ---------- Reveal ---------- */
.reveal{opacity:0;transform:translateY(24px);transition:opacity .8s var(--ease),transform .8s var(--ease)}
.reveal.in{opacity:1;transform:none}

/* ---------- Responsive ---------- */
@media (max-width: 1200px){
  .product-grid,.cat-grid,.values-grid,.ritual-steps,.sci-grid{grid-template-columns:repeat(2,1fr)}
  .ritual-steps::before{display:none}
  .footer-grid{grid-template-columns:1fr 1fr 1fr;gap:40px}
  .footer-grid > *:nth-child(1){grid-column:1/-1}
}
@media (max-width: 1080px){
  .main-nav{display:none}
  .burger{display:inline-block}
  .header-inner{grid-template-columns:auto 1fr auto;gap:16px}
  .logo{justify-self:flex-start;grid-column:2}
  .topbar-left,.topbar-right{gap:18px}
  .topbar-left span:first-child{display:none}
  .hero-grid,.story-grid,.auth-card,.dealer-grid,.ing-grid,.ba-grid{grid-template-columns:1fr;gap:50px}
  .auth-card{padding:50px 30px}
  .hero-side{display:none}
  .h1-line--italic{padding-left:40px}
  .story-visual,.ing-visual{max-width:480px;margin:0 auto}
  .float-chip{display:none}
  .insta-grid{grid-template-columns:repeat(3,1fr)}
  .tiers{grid-template-columns:1fr}
  .tier-gold{transform:none}
}
@media (max-width: 640px){
  .topbar-left,.topbar-right{display:none}
  .topbar{padding:6px 0}
  .announce-track{font-size:.65rem;gap:50px}
  .hero{padding:60px 0 80px}
  .product-grid,.cat-grid,.news-grid,.tm-grid,.values-grid,.ritual-steps,.sci-grid{grid-template-columns:1fr}
  .ing-list{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .section-head.between{flex-direction:column;align-items:flex-start}
  .dealer-points{grid-template-columns:1fr}
  .hero-meta{gap:24px}
  .auth-card{padding:40px 24px}
  .copyright-inner{flex-direction:column;text-align:center}
  .h1-line--italic{padding-left:0}
  .press-logos{gap:20px}
  .press-item{font-size:1.2rem !important}
  .cert-list{gap:16px 28px}
  .cert-list li{font-size:.7rem}
  .container{padding:0 20px}
}

toolUseResult.content:
/* =========================================================
   DETOXBLANC — Maison de Soin
   Brand Stylesheet · international luxury cosmetics
   Palette : champagne gold · ivory · charcoal · blush · sage
   Type    : Italiana (display) · Cormorant Garamond (editorial) · Inter (body)
   ========================================================= */

:root{
  --ivory:      #F8F5F0;
  --cream:      #F1EBE2;
  --blush:      #F4E8E1;
  --sand:       #E6DBCB;
  --gold:       #C9A961;
  --gold-soft:  #E2CB95;
  --gold-dark:  #A8883F;
  --charcoal:   #141414;
  --ink:        #2A2A2A;
  --muted:      #6E6A63;
  --line:       #E6DFD3;
  --line-dark:  #DBD3C2;
  --sage:       #8B9D83;
  --rose:       #C99A8C;
  --white:      #ffffff;
  --black:      #000000;
  --radius:     16px;
  --radius-sm:  10px;
  --shadow-sm:  0 2px 10px rgba(20,20,20,.06);
  --shadow:     0 12px 40px rgba(20,20,20,.08);
  --shadow-lg:  0 24px 60px rgba(20,20,20,.14);
  --ease:       cubic-bezier(.2,.7,.2,1);
  --container:  1280px;
}

*,*::before,*::after{box-sizing:border-box}
html,body{margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:'Inter', system-ui, -apple-system, sans-serif;
  color:var(--ink);
  background:var(--ivory);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:0;background:transparent}

.container{max-width:var(--container);margin:0 auto;padding:0 32px}
.center{text-align:center}
.mt-24{margin-top:24px}
.mt-40{margin-top:40px}
sup{font-size:.5em;vertical-align:super}

/* ---------- Typography ---------- */
h1,h2,h3,h4,h5{color:var(--charcoal);margin:0;letter-spacing:-.01em;font-weight:400}
h1{
  font-family:'Italiana','Cormorant Garamond',serif;
  font-size:clamp(3rem,6.5vw,6rem);
  line-height:1;letter-spacing:.02em;font-weight:400;
}
h1 em{font-family:'Cormorant Garamond',serif;font-weight:500;font-style:italic;letter-spacing:0;color:var(--gold-dark)}
h2{
  font-family:'Italiana','Cormorant Garamond',serif;
  font-size:clamp(2.2rem,4vw,3.8rem);
  line-height:1.1;letter-spacing:.02em;
}
h2 em{font-family:'Cormorant Garamond',serif;font-style:italic;font-weight:500;color:var(--gold-dark);letter-spacing:0}
h3{font-family:'Cormorant Garamond',serif;font-size:1.45rem;line-height:1.25;font-weight:600}
h4{font-size:.82rem;color:var(--charcoal);letter-spacing:.2em;text-transform:uppercase;font-weight:700;font-family:'Inter',sans-serif}
h5{font-size:.72rem;color:var(--charcoal);letter-spacing:.22em;text-transform:uppercase;font-weight:700;font-family:'Inter',sans-serif}
em{font-style:italic;color:var(--gold-dark);font-weight:500}

.eyebrow{
  font-family:'Inter',sans-serif;
  font-size:.7rem;font-weight:600;
  letter-spacing:.25em;color:var(--gold-dark);
  text-transform:uppercase;display:inline-block;margin-bottom:16px;
}
.eyebrow.light{color:var(--gold-soft)}
.center-eyebrow{display:block;text-align:center}

.underline{background:linear-gradient(transparent 62%, rgba(201,169,97,.35) 62%);padding:0 2px}

.section-head{margin-bottom:64px}
.section-head.center{text-align:center;max-width:680px;margin-inline:auto}
.section-head.between{
  display:flex;justify-content:space-between;align-items:flex-end;
  text-align:left;flex-wrap:wrap;gap:24px;
}
.section-sub{color:var(--muted);margin-top:18px;font-size:1rem}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:15px 30px;border-radius:999px;border:1px solid transparent;
  font-weight:600;font-size:.82rem;letter-spacing:.1em;text-transform:uppercase;
  transition:all .3s var(--ease);
  font-family:'Inter',sans-serif;
}
.btn i{font-size:.9em;letter-spacing:0}
.btn-primary{background:var(--charcoal);color:var(--ivory)}
.btn-primary:hover{background:var(--gold-dark);transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-dark{background:var(--charcoal);color:var(--ivory);padding:12px 20px;font-size:.74rem}
.btn-dark:hover{background:var(--gold-dark)}
.btn-outline{background:transparent;border-color:var(--charcoal);color:var(--charcoal)}
.btn-outline:hover{background:var(--charcoal);color:var(--ivory)}
.btn-ghost{background:transparent;color:var(--charcoal);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--charcoal)}
.btn-gold{background:linear-gradient(135deg,var(--gold) 0%,var(--gold-dark) 100%);color:var(--white);border:0}
.btn-gold:hover{filter:brightness(1.1);transform:translateY(-2px);box-shadow:var(--shadow)}
.btn-block{display:flex;width:100%;justify-content:center}

.link-arrow{
  display:inline-flex;align-items:center;gap:8px;
  font-weight:600;font-size:.8rem;color:var(--charcoal);
  border-bottom:1px solid var(--charcoal);padding-bottom:3px;
  transition:all .25s var(--ease);text-transform:uppercase;letter-spacing:.12em;
}
.link-arrow:hover{color:var(--gold-dark);border-color:var(--gold-dark);gap:14px}
.link-arrow.sm{font-size:.7rem;letter-spacing:.15em}

/* ---------- Announcement bar ---------- */
.announce{background:var(--charcoal);color:var(--ivory);overflow:hidden;border-bottom:1px solid rgba(255,255,255,.04)}
.announce-track{
  display:flex;gap:80px;white-space:nowrap;padding:10px 0;
  animation:marquee 40s linear infinite;
  font-size:.72rem;letter-spacing:.2em;text-transform:uppercase;font-weight:500;
}
.announce-track span{position:relative}
.announce-track span::after{
  content:"";position:absolute;right:-40px;top:50%;transform:translateY(-50%);
  width:4px;height:4px;background:var(--gold);border-radius:50%;
}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Topbar ---------- */
.topbar{background:#fff;color:var(--ink);font-size:.78rem;padding:8px 0;border-bottom:1px solid var(--line)}
.topbar-inner{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.topbar-left,.topbar-right{display:flex;gap:28px;align-items:center;flex-wrap:wrap}
.topbar i{color:var(--gold-dark);margin-right:6px}
.topbar-right a:hover{color:var(--gold-dark)}

.locale{position:relative}
.locale-btn{display:inline-flex;align-items:center;gap:6px;font-size:.78rem;color:var(--ink)}
.locale-btn .flag{font-size:1rem}
.locale-btn i{font-size:.7em;color:var(--muted)}
.locale-menu{
  position:absolute;top:calc(100% + 8px);right:0;min-width:180px;
  background:#fff;border:1px solid var(--line);border-radius:12px;
  padding:6px;box-shadow:var(--shadow);
  opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .25s var(--ease);z-index:60;
}
.locale:hover .locale-menu{opacity:1;visibility:visible;transform:translateY(0)}
.locale-menu a{display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;font-size:.82rem}
.locale-menu a:hover{background:var(--cream)}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:50;background:rgba(248,245,240,.96);
  backdrop-filter:blur(16px);border-bottom:1px solid var(--line);
  transition:padding .3s var(--ease);
}
.site-header.scrolled{padding:0}
.header-inner{
  display:grid;grid-template-columns:auto 1fr auto;
  align-items:center;gap:24px;padding:18px 32px;
}
.logo{display:flex;align-items:center;gap:14px;justify-self:center;grid-column:2}
.logo-mark{
  width:48px;height:48px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold) 0%,var(--gold-dark) 100%);
  color:var(--ivory);display:grid;place-items:center;
  font-family:'Italiana',serif;font-size:1.8rem;font-weight:400;
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.3),0 4px 12px rgba(201,169,97,.25);
}
.logo-text{display:flex;flex-direction:column;line-height:1}
.logo-text strong{font-family:'Italiana',serif;font-size:1.6rem;font-weight:400;letter-spacing:.2em;color:var(--charcoal)}
.logo-text em{font-size:.6rem;letter-spacing:.3em;color:var(--gold-dark);margin-top:4px;text-transform:uppercase;font-style:normal;font-family:'Inter',sans-serif}

.main-nav{display:flex;justify-content:center;gap:32px;grid-column:1 / span 3;grid-row:2;padding-top:14px;border-top:1px solid var(--line);margin:0 -32px;padding-left:32px;padding-right:32px}
.main-nav > a,.nav-item > a{
  font-size:.78rem;font-weight:500;letter-spacing:.18em;text-transform:uppercase;
  color:var(--ink);padding:8px 2px;position:relative;display:inline-flex;align-items:center;gap:6px;
  transition:color .25s var(--ease);
}
.main-nav > a:hover,.nav-item:hover > a{color:var(--gold-dark)}
.main-nav > a.active{color:var(--charcoal)}
.main-nav > a.active::after{
  content:"";position:absolute;left:50%;right:0;bottom:-2px;height:2px;
  width:24px;margin-left:-12px;background:var(--gold);
}
.nav-item{position:static}
.nav-item > a i{font-size:.55rem;opacity:.6}

/* Mega-menu */
.mega{
  position:absolute;left:0;right:0;top:100%;background:#fff;
  border-top:1px solid var(--line);box-shadow:var(--shadow);
  padding:40px 32px;opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .3s var(--ease);z-index:40;
}
.nav-item:hover .mega{opacity:1;visibility:visible;transform:translateY(0)}
.mega-grid{max-width:var(--container);margin:0 auto;display:grid;grid-template-columns:repeat(3,1fr) 1.3fr;gap:50px}
.mega h5{margin-bottom:18px}
.mega ul{list-style:none;padding:0;margin:0}
.mega ul li{padding:6px 0}
.mega ul a{font-size:.88rem;color:var(--ink);transition:color .2s var(--ease)}
.mega ul a:hover{color:var(--gold-dark)}
.mega-feature{
  background:linear-gradient(135deg,var(--cream),var(--blush));
  border-radius:var(--radius);padding:24px;
  display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center;position:relative;
  transition:all .3s var(--ease);
}
.mega-feature:hover{transform:translateY(-3px);box-shadow:var(--shadow)}
.mega-feature .tag-gold{
  position:absolute;top:12px;right:12px;font-size:.58rem;font-weight:700;letter-spacing:.2em;
  color:var(--white);background:var(--gold);padding:4px 8px;border-radius:3px;
}
.mega-visual{width:80px}
.mega-feature strong{display:block;font-family:'Cormorant Garamond',serif;font-size:1.2rem;color:var(--charcoal)}
.mega-feature span{font-size:.78rem;color:var(--muted);margin-top:2px;display:block}

.header-actions{display:flex;align-items:center;gap:8px}
.icon-btn{
  width:42px;height:42px;border-radius:50%;
  color:var(--charcoal);position:relative;
  transition:all .25s var(--ease);
}
.icon-btn:hover{background:var(--cream)}
.badge{
  position:absolute;top:2px;right:2px;background:var(--gold);color:var(--white);
  font-size:.62rem;font-weight:700;min-width:17px;height:17px;border-radius:50%;
  display:grid;place-items:center;padding:0 4px;
}
.burger{display:none;font-size:1.3rem;color:var(--charcoal);grid-column:1}

/* ---------- HERO ---------- */
.hero{
  position:relative;overflow:hidden;
  background:var(--ivory);
  padding:90px 0 110px;min-height:88vh;
}
.hero-bg{position:absolute;inset:0;z-index:0;pointer-events:none}
.bg-blur{position:absolute;border-radius:50%;filter:blur(80px);opacity:.7}
.b1{width:600px;height:600px;background:var(--blush);top:-100px;right:-150px}
.b2{width:500px;height:500px;background:var(--cream);bottom:-150px;left:-100px}
.b3{width:400px;height:400px;background:rgba(201,169,97,.15);top:30%;left:40%}
.bg-grain{
  position:absolute;inset:0;opacity:.04;pointer-events:none;
  background-image:radial-gradient(circle at 1px 1px,var(--charcoal) 1px, transparent 0);
  background-size:3px 3px;
}

.hero-side{
  position:absolute;left:32px;top:50%;transform:translateY(-50%) rotate(-90deg);transform-origin:left center;
  display:flex;gap:14px;font-size:.7rem;letter-spacing:.35em;color:var(--muted);text-transform:uppercase;z-index:2;
}
.hero-side .dot{color:var(--gold);font-size:.5rem}

.hero-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:60px;align-items:center;position:relative;z-index:2}
.h1-line{display:block}
.h1-line--italic{font-family:'Cormorant Garamond',serif;font-style:italic;padding-left:80px;color:var(--gold-dark);font-weight:500}
.lead{font-size:1.05rem;color:var(--muted);max-width:540px;margin:28px 0 36px;line-height:1.75}
.lead strong{color:var(--charcoal);font-weight:600}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:56px}

.hero-meta{display:flex;gap:44px;border-top:1px solid var(--line-dark);padding-top:24px;max-width:540px;flex-wrap:wrap}
.hero-meta > div strong{font-family:'Italiana',serif;font-size:2rem;color:var(--charcoal);display:block;line-height:1}
.hero-meta > div span{font-size:.7rem;letter-spacing:.15em;color:var(--muted);text-transform:uppercase;margin-top:4px;display:block}

/* Hero visual frame */
.hero-visual{position:relative;display:grid;place-items:center;min-height:580px}
.hero-frame{
  position:relative;width:100%;max-width:440px;aspect-ratio:3/4;
  border-radius:calc(var(--radius) + 8px);overflow:hidden;
  box-shadow:var(--shadow-lg);background:#fff;
}
.hero-gradient{
  position:absolute;inset:0;
  background:
    radial-gradient(circle at 30% 20%,var(--blush),transparent 60%),
    radial-gradient(circle at 70% 80%,rgba(201,169,97,.25),transparent 55%),
    linear-gradient(180deg,#fdfaf3,var(--cream));
}
.bottle-hero{position:absolute;top:50%;left:50%;transform:translate(-50%,-52%);width:62%;filter:drop-shadow(0 30px 40px rgba(20,20,20,.25))}
.price-tag{
  position:absolute;bottom:22px;left:22px;right:22px;background:rgba(255,255,255,.92);backdrop-filter:blur(10px);
  border-radius:12px;padding:14px 18px;display:flex;align-items:center;gap:14px;justify-content:space-between;
  border:1px solid var(--line);
}
.price-tag .small{font-size:.65rem;letter-spacing:.2em;color:var(--gold-dark);text-transform:uppercase;font-weight:600;display:block}
.price-tag strong{font-family:'Cormorant Garamond',serif;font-size:1.4rem;color:var(--charcoal);display:block;margin-top:2px}
.price-tag a{font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;color:var(--charcoal);font-weight:600;border-bottom:1px solid var(--charcoal);padding-bottom:2px}
.price-tag a:hover{color:var(--gold-dark);border-color:var(--gold-dark)}

.float-chip{
  position:absolute;background:var(--white);border-radius:999px;
  padding:10px 18px;font-size:.78rem;font-weight:500;
  box-shadow:var(--shadow);border:1px solid var(--line);
  display:flex;align-items:center;gap:8px;
}
.float-chip i{color:var(--gold-dark)}
.chip-1{top:8%;left:-6%}
.chip-2{bottom:12%;right:-4%}

.hero-scroll{
  position:absolute;bottom:30px;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:6px;
  font-size:.66rem;letter-spacing:.3em;color:var(--muted);text-transform:uppercase;z-index:3;
  animation:bob 2.2s ease-in-out infinite;
}
.hero-scroll i{color:var(--gold-dark)}
@keyframes bob{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(6px)}}

/* ---------- PRESS ---------- */
.press{background:#fff;padding:50px 0;border-bottom:1px solid var(--line)}
.press-label{text-align:center;font-size:.7rem;letter-spacing:.3em;color:var(--muted);text-transform:uppercase;margin:0 0 24px}
.press-logos{display:flex;justify-content:space-around;align-items:center;gap:32px;flex-wrap:wrap}
.press-item{color:#555;opacity:.5;transition:opacity .3s var(--ease)}
.press-item:hover{opacity:1}

/* ---------- STATEMENT ---------- */
.statement{padding:120px 0;background:var(--ivory);text-align:center}
.statement-head{
  font-family:'Cormorant Garamond',serif;font-size:clamp(1.8rem,3vw,2.8rem);
  max-width:960px;margin:0 auto;line-height:1.35;color:var(--charcoal);font-weight:400;
  font-style:italic;
}
.statement-head em{font-style:italic}
.statement-sign{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:36px;color:var(--muted);font-size:.82rem}
.sig-line{width:40px;height:1px;background:var(--gold-dark)}

/* ---------- CATEGORIES ---------- */
.categories{padding:120px 0;background:var(--white)}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.cat-card{
  background:var(--white);border-radius:var(--radius);overflow:hidden;
  transition:all .4s var(--ease);display:flex;flex-direction:column;
  border:1px solid transparent;
}
.cat-card:hover{transform:translateY(-6px);border-color:var(--gold);box-shadow:var(--shadow)}
.cat-visual{
  aspect-ratio:4/5;position:relative;display:grid;place-items:center;
  color:rgba(20,20,20,.15);font-size:5rem;
}
.cat-visual::after{
  content:"";position:absolute;inset:0;
  background:linear-gradient(180deg,transparent 60%,rgba(0,0,0,.06));
}
.cat-v1{background:linear-gradient(135deg,#fbeacd,#f1c985)}
.cat-v2{background:linear-gradient(135deg,#fadad2,#e3a294)}
.cat-v3{background:linear-gradient(135deg,#e7ede2,#a7bfa3)}
.cat-v4{background:linear-gradient(135deg,#efe5d7,#d5bb95)}
.cat-n{
  position:absolute;top:18px;left:18px;font-family:'Italiana',serif;font-size:1.2rem;letter-spacing:.15em;
  color:var(--charcoal);opacity:.8;
}
.cat-visual i{position:relative;z-index:1}
.cat-body{padding:26px 24px 28px}
.cat-body h3{font-size:1.5rem;margin-bottom:6px}
.cat-body p{color:var(--muted);font-size:.9rem;margin:0 0 14px}
.cat-cta{
  font-size:.72rem;font-weight:600;color:var(--charcoal);letter-spacing:.15em;text-transform:uppercase;
  display:inline-flex;align-items:center;gap:6px;
  transition:gap .25s var(--ease),color .25s var(--ease);
}
.cat-card:hover .cat-cta{color:var(--gold-dark);gap:12px}

/* ---------- PRODUCTS ---------- */
.products{padding:120px 0;background:linear-gradient(180deg,var(--ivory),var(--white))}
.product-tabs{display:flex;gap:8px;flex-wrap:wrap}
.tab{
  padding:10px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-size:.74rem;font-weight:600;color:var(--ink);letter-spacing:.1em;text-transform:uppercase;
  transition:all .25s var(--ease);
}
.tab:hover{border-color:var(--charcoal)}
.tab.active{background:var(--charcoal);color:var(--ivory);border-color:var(--charcoal)}

.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);display:flex;flex-direction:column;
}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold-soft)}
.product-media{
  position:relative;padding:40px 20px 22px;display:grid;place-items:center;min-height:320px;
}
.gradient-sun{background:linear-gradient(135deg,#fbeacd,#f3d294)}
.gradient-rose{background:linear-gradient(135deg,#fadad2,#e8b3a5)}
.gradient-sage{background:linear-gradient(135deg,#e7ede2,#b3c8ae)}
.gradient-cream{background:linear-gradient(135deg,#efe5d7,#dcc5a1)}
.bottle-svg{width:140px;height:auto;filter:drop-shadow(0 16px 20px rgba(20,20,20,.15))}

.tag{
  position:absolute;top:14px;left:14px;font-size:.62rem;font-weight:700;
  letter-spacing:.22em;padding:5px 10px;border-radius:3px;color:var(--white);text-transform:uppercase;
}
.tag-sale{background:var(--charcoal)}
.tag-hot{background:#b44646}
.tag-new{background:#3b7a57}
.wish{
  position:absolute;top:10px;right:10px;width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,.8);color:var(--charcoal);
  backdrop-filter:blur(6px);transition:all .25s var(--ease);display:grid;place-items:center;font-size:.9rem;
}
.wish:hover{background:var(--charcoal);color:var(--gold-soft)}
.quick{
  position:absolute;bottom:16px;left:50%;transform:translate(-50%,8px);
  opacity:0;background:var(--charcoal);color:var(--ivory);
  padding:10px 20px;border-radius:999px;font-size:.68rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;
  transition:all .3s var(--ease);
}
.product-card:hover .quick{opacity:1;transform:translate(-50%,0)}

.product-body{padding:22px 22px 26px;display:flex;flex-direction:column;gap:10px;flex:1}
.product-body .cat{font-size:.68rem;letter-spacing:.22em;color:var(--gold-dark);font-weight:600;text-transform:uppercase}
.product-body h3{font-family:'Cormorant Garamond',serif;font-size:1.2rem;font-weight:600;color:var(--charcoal);line-height:1.3;min-height:54px}
.variants{display:flex;gap:6px}
.dot-swatch{
  width:16px;height:16px;border-radius:50%;border:1px solid rgba(0,0,0,.08);
  cursor:pointer;transition:transform .2s var(--ease);
  box-shadow:inset 0 0 0 2px rgba(255,255,255,.6);
}
.dot-swatch:hover{transform:scale(1.2)}
.stars{color:var(--gold);font-size:.78rem;display:flex;align-items:center;gap:2px}
.stars small{color:var(--muted);margin-left:6px;font-size:.74rem}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:auto}
.price{font-size:1.2rem;font-weight:700;color:var(--charcoal);font-family:'Cormorant Garamond',serif}
.price-old{font-size:.84rem;color:var(--muted);text-decoration:line-through}

/* ---------- INGREDIENT SPOTLIGHT ---------- */
.ingredient{padding:120px 0;background:linear-gradient(180deg,var(--white) 0%,var(--cream) 100%)}
.ing-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:80px;align-items:center}
.ing-visual{position:relative;aspect-ratio:1/1;display:grid;place-items:center}
.ing-orb{
  width:78%;aspect-ratio:1;border-radius:50%;position:relative;
  background:
    radial-gradient(circle at 30% 30%,#fff6e0,#f1c985 40%,#b4812d 80%);
  box-shadow:
    inset -30px -30px 80px rgba(0,0,0,.25),
    inset 30px 30px 80px rgba(255,255,255,.35),
    0 30px 70px rgba(201,169,97,.35);
  animation:orbSpin 20s linear infinite;
}
.orb-core{
  position:absolute;top:20%;left:22%;width:26%;height:22%;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#fff,rgba(255,255,255,0));
  filter:blur(2px);
}
@keyframes orbSpin{to{transform:rotate(360deg)}}
.particle{
  position:absolute;width:14px;height:14px;border-radius:50%;
  background:radial-gradient(circle at 30% 30%,#fff6e0,#d9b36b);
  box-shadow:0 6px 14px rgba(201,169,97,.35);
  animation:floatP 6s ease-in-out infinite;
}
.p1{top:5%;left:10%;animation-delay:0s}
.p2{top:20%;right:8%;width:10px;height:10px;animation-delay:1s}
.p3{bottom:15%;right:15%;width:16px;height:16px;animation-delay:2s}
.p4{bottom:8%;left:20%;width:8px;height:8px;animation-delay:3s}
.p5{top:50%;left:-2%;width:12px;height:12px;animation-delay:1.5s}
@keyframes floatP{0%,100%{transform:translateY(0)}50%{transform:translateY(-16px)}}

.ing-callout{
  position:absolute;right:4%;bottom:6%;background:var(--charcoal);color:var(--ivory);
  padding:16px 22px;border-radius:12px;box-shadow:var(--shadow-lg);
}
.ing-callout strong{display:block;font-family:'Cormorant Garamond',serif;font-size:1.25rem;color:var(--gold-soft)}
.ing-callout span{font-size:.72rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.7)}

.ing-lede{color:var(--muted);font-size:1.02rem;margin:16px 0 36px;max-width:540px;line-height:1.75}
.ing-list{display:grid;grid-template-columns:1fr 1fr;gap:28px 40px}
.ing-item{display:flex;gap:18px;align-items:flex-start}
.ing-num{
  font-family:'Italiana',serif;font-size:1.4rem;color:var(--gold-dark);
  letter-spacing:.05em;padding-top:2px;min-width:28px;
}
.ing-item strong{display:block;color:var(--charcoal);font-weight:600;margin-bottom:4px}
.ing-item p{font-size:.86rem;color:var(--muted);margin:0;line-height:1.6}

/* ---------- SCIENCE ---------- */
.science{padding:120px 0;background:var(--white)}
.sci-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-bottom:56px}
.sci-stat{
  background:var(--ivory);border:1px solid var(--line);border-radius:var(--radius);
  padding:40px 28px;text-align:center;position:relative;overflow:hidden;
  transition:all .35s var(--ease);
}
.sci-stat::before{
  content:"";position:absolute;top:0;left:0;right:0;height:2px;
  background:linear-gradient(90deg,transparent,var(--gold),transparent);
}
.sci-stat:hover{transform:translateY(-4px);box-shadow:var(--shadow)}
.sci-num{font-family:'Italiana',serif;font-size:4.5rem;color:var(--charcoal);line-height:1;letter-spacing:0}
.sci-pct{font-family:'Italiana',serif;font-size:2rem;color:var(--gold-dark);margin-left:4px;vertical-align:top}
.sci-stat p{margin:12px 0 0;font-size:.88rem;color:var(--muted);line-height:1.5}
.sci-stat p strong{color:var(--charcoal);font-weight:600}

.cert-list{
  list-style:none;padding:0;margin:0;display:flex;justify-content:center;gap:40px;flex-wrap:wrap;
  padding-top:32px;border-top:1px solid var(--line);
}
.cert-list li{display:flex;align-items:center;gap:8px;font-size:.78rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);font-weight:600}
.cert-list i{color:var(--gold-dark);font-size:1rem}

/* ---------- RITUAL ---------- */
.ritual{padding:120px 0;background:var(--ivory)}
.ritual-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;position:relative}
.ritual-steps::before{
  content:"";position:absolute;top:80px;left:12%;right:12%;height:1px;
  background:linear-gradient(90deg,transparent,var(--gold-soft) 15%,var(--gold-soft) 85%,transparent);
  z-index:0;
}
.ritual-step{
  background:var(--white);border-radius:var(--radius);padding:40px 28px 32px;
  text-align:center;border:1px solid var(--line);transition:all .35s var(--ease);position:relative;z-index:1;
}
.ritual-step:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold-soft)}
.step-num{
  font-family:'Italiana',serif;font-size:1.3rem;color:var(--gold-dark);
  letter-spacing:.1em;display:block;margin-bottom:4px;
}
.step-icon{
  width:72px;height:72px;border-radius:50%;
  background:linear-gradient(135deg,var(--cream),var(--blush));
  display:grid;place-items:center;color:var(--gold-dark);font-size:1.5rem;
  margin:14px auto 22px;
}
.ritual-step h3{font-size:1.4rem;margin-bottom:8px}
.ritual-step p{color:var(--muted);font-size:.88rem;margin:0 0 18px;line-height:1.6}

/* ---------- BEFORE / AFTER ---------- */
.ba{padding:120px 0;background:var(--white)}
.ba-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:70px;align-items:center}
.ba-points{list-style:none;padding:0;margin:20px 0 32px}
.ba-points li{padding:10px 0;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;font-size:.9rem}
.ba-points i{color:var(--gold-dark)}
.ba-slider{
  position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;
  box-shadow:var(--shadow-lg);cursor:ew-resize;user-select:none;
}
.ba-img{position:absolute;inset:0;background-size:cover;background-position:center}
.ba-before{
  background:
    radial-gradient(circle at 50% 55%,#e2b8a5 0%,#b78878 35%,#8c5f52 70%),
    linear-gradient(180deg,#d4a190,#936651);
  background-blend-mode:multiply;
  clip-path:inset(0 50% 0 0);transition:none;
}
.ba-before::after{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 42% 48%,rgba(100,60,40,.4) 2%, transparent 8%),
    radial-gradient(circle at 55% 52%,rgba(100,60,40,.4) 2%, transparent 7%),
    radial-gradient(circle at 48% 60%,rgba(100,60,40,.35) 2%, transparent 6%),
    radial-gradient(circle at 60% 45%,rgba(100,60,40,.3) 2%, transparent 5%);
  mix-blend-mode:multiply;
}
.ba-after{
  background:
    radial-gradient(circle at 50% 55%,#fadcc8 0%,#e8bfa4 40%,#b38870 80%);
}
.ba-label{
  position:absolute;top:18px;padding:6px 14px;background:rgba(255,255,255,.85);backdrop-filter:blur(6px);
  font-size:.68rem;letter-spacing:.22em;text-transform:uppercase;font-weight:600;color:var(--charcoal);border-radius:4px;
  z-index:3;pointer-events:none;
}
.ba-label-before{left:18px}
.ba-label-after{right:18px}
.ba-handle{
  position:absolute;top:0;bottom:0;left:50%;width:2px;background:var(--ivory);z-index:4;
  cursor:ew-resize;
}
.ba-knob{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:48px;height:48px;border-radius:50%;background:var(--ivory);color:var(--charcoal);
  display:grid;grid-template-columns:1fr 1fr;place-items:center;gap:4px;padding:0 6px;
  box-shadow:0 6px 18px rgba(0,0,0,.25);font-size:.7rem;
}

/* ---------- STORY ---------- */
.story{padding:130px 0;background:var(--ivory)}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:90px;align-items:center}
.story-visual{position:relative;display:grid;grid-template-columns:1.2fr 1fr;grid-template-rows:1fr 1fr;gap:16px;aspect-ratio:1/1.05}
.story-img{border-radius:var(--radius);overflow:hidden;background-size:cover;background-position:center}
.img-1{grid-row:1/3;position:relative}
.img-1 svg{width:100%;height:100%;object-fit:cover}
.img-2{background:
  radial-gradient(circle at 70% 30%,rgba(255,255,255,.6),transparent 50%),
  linear-gradient(135deg,var(--sage),#b8c7b0)}
.img-3{background:
  radial-gradient(circle at 30% 70%,rgba(255,255,255,.5),transparent 50%),
  linear-gradient(135deg,var(--rose),#eccfc3)}
.story-badge{
  position:absolute;bottom:-30px;left:-30px;background:var(--charcoal);
  color:var(--ivory);padding:24px 28px;border-radius:var(--radius);
  display:flex;align-items:center;gap:14px;box-shadow:var(--shadow-lg);
}
.story-badge strong{font-family:'Italiana',serif;font-size:2.6rem;color:var(--gold-soft);line-height:1;letter-spacing:.08em}
.story-badge span{font-size:.74rem;line-height:1.4;letter-spacing:.08em}

.story-copy p{color:var(--muted);margin:18px 0;line-height:1.8}
.story-copy p strong{color:var(--charcoal)}
.story-quote{
  margin:28px 0;padding:24px 28px;border-left:2px solid var(--gold);
  background:var(--white);border-radius:0 12px 12px 0;
  font-family:'Cormorant Garamond',serif;font-style:italic;font-size:1.2rem;color:var(--charcoal);
}

/* ---------- VALUES / Sustainability ---------- */
.values{padding:120px 0;background:var(--white)}
.values-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.value-card{
  padding:36px 28px;text-align:center;border-radius:var(--radius);
  background:var(--ivory);border:1px solid var(--line);transition:all .35s var(--ease);
}
.value-card:hover{transform:translateY(-4px);border-color:var(--gold);box-shadow:var(--shadow)}
.value-icon{
  width:60px;height:60px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold-soft),var(--gold));color:var(--white);
  display:grid;place-items:center;font-size:1.3rem;margin:0 auto 20px;
  box-shadow:0 10px 24px rgba(201,169,97,.3);
}
.value-card h3{font-size:1.25rem;margin-bottom:8px}
.value-card p{font-size:.88rem;color:var(--muted);margin:0;line-height:1.6}

/* ---------- AUTH / QR ---------- */
.auth{padding:100px 0;background:var(--ivory)}
.auth-card{
  background:linear-gradient(135deg,var(--charcoal) 0%,#252018 100%);
  color:var(--ivory);border-radius:calc(var(--radius) + 8px);
  padding:80px 70px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;
  position:relative;overflow:hidden;
}
.auth-card::before{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 80% 20%,rgba(201,169,97,.2),transparent 50%),
    radial-gradient(circle at 10% 90%,rgba(201,169,97,.1),transparent 45%);
  pointer-events:none;
}
.auth-copy h2{color:var(--ivory);position:relative}
.auth-copy h2 em{color:var(--gold-soft)}
.auth-copy p{color:#c9c3b6;margin:18px 0 30px;max-width:480px;line-height:1.75}
.auth-copy p strong{color:var(--gold-soft)}
.store-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px;position:relative}
.store-btn{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--ivory);color:var(--charcoal);padding:10px 18px;border-radius:12px;
  transition:all .25s var(--ease);
}
.store-btn:hover{transform:translateY(-2px)}
.store-btn i{font-size:1.7rem}
.store-btn span{display:flex;flex-direction:column;line-height:1.1;font-size:.95rem;font-weight:600}
.store-btn small{font-size:.6rem;font-weight:500;color:var(--muted);letter-spacing:.08em}
.store-btns.sm .store-btn{padding:8px 14px;background:transparent;color:var(--ivory);border:1px solid rgba(255,255,255,.18)}
.store-btns.sm .store-btn small{color:rgba(255,255,255,.55)}
.auth-copy .link-arrow{color:var(--gold-soft);border-color:var(--gold-soft)}
.auth-copy .link-arrow:hover{color:var(--ivory);border-color:var(--ivory)}

.auth-visual{position:relative;display:grid;place-items:center}
.qr-frame{text-align:center;color:var(--ivory)}
.qr-mock{
  width:240px;height:240px;background:var(--ivory);border-radius:22px;
  padding:24px;position:relative;margin:0 auto 16px;
  box-shadow:0 30px 60px rgba(0,0,0,.4);
}
.qr-dot{position:absolute;width:46px;height:46px;border:7px solid var(--charcoal);border-radius:8px}
.qr-dot.tl{top:20px;left:20px}
.qr-dot.tr{top:20px;right:20px}
.qr-dot.bl{bottom:20px;left:20px}
.qr-inner{
  position:absolute;inset:28px;
  background-image:
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal)),
    linear-gradient(var(--charcoal),var(--charcoal));
  background-size:12px 12px,18px 18px,24px 12px,12px 24px,15px 15px,20px 14px,14px 20px,22px 22px;
  background-position:80px 26px,28px 92px,100px 80px,160px 100px,70px 140px,140px 150px,108px 180px,34px 160px;
  background-repeat:no-repeat;
}
.qr-logo{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:56px;height:56px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  display:grid;place-items:center;color:var(--ivory);
  font-family:'Italiana',serif;font-size:2rem;
  box-shadow:inset 0 0 0 3px var(--ivory),0 4px 10px rgba(0,0,0,.3);
}
.qr-frame p{font-size:.74rem;letter-spacing:.22em;color:var(--gold-soft);text-transform:uppercase;font-weight:600}

/* ---------- TESTIMONIALS ---------- */
.testimonials{padding:120px 0;background:var(--cream)}
.tm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.tm-card{
  background:var(--white);border-radius:var(--radius);padding:40px 32px;
  margin:0;box-shadow:var(--shadow-sm);position:relative;display:flex;flex-direction:column;gap:20px;
}
.tm-card::before{
  content:"\201C";position:absolute;top:10px;right:28px;
  font-family:'Italiana',serif;font-size:5rem;color:var(--gold);line-height:1;opacity:.35;
}
.tm-card p{font-family:'Cormorant Garamond',serif;font-size:1.2rem;line-height:1.45;color:var(--charcoal);margin:0;font-style:italic}
.tm-card footer{display:flex;align-items:center;gap:12px;margin-top:auto;border-top:1px solid var(--line);padding-top:18px}
.avatar{
  width:44px;height:44px;border-radius:50%;
  background:linear-gradient(135deg,var(--gold),var(--gold-dark));
  display:grid;place-items:center;color:var(--ivory);font-weight:600;font-size:.88rem;
}
.tm-card footer strong{display:block;font-size:.92rem;color:var(--charcoal)}
.tm-card footer span{font-size:.76rem;color:var(--muted)}

/* ---------- CLUB ---------- */
.club{padding:120px 0;background:
  radial-gradient(circle at 20% 30%,rgba(201,169,97,.1),transparent 50%),
  linear-gradient(135deg,var(--charcoal) 0%,#1d1a16 100%);
  color:var(--ivory)}
.club-grid{display:grid;grid-template-columns:1fr;justify-items:center;text-align:center;max-width:980px;margin:0 auto}
.club h2{color:var(--ivory)}
.club h2 em{color:var(--gold-soft)}
.club-copy p{color:#c9c3b6;max-width:640px;margin:18px 0 40px;line-height:1.75}
.tiers{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;width:100%;margin-bottom:40px}
.tier{
  background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.08);border-radius:var(--radius);
  padding:30px 24px;text-align:center;
}
.tier-gold{
  background:linear-gradient(180deg,rgba(201,169,97,.15),rgba(201,169,97,.02));
  border-color:var(--gold);transform:scale(1.04);
}
.tier-level{font-family:'Italiana',serif;font-size:1.3rem;color:var(--gold-soft);letter-spacing:.15em;display:block;margin-bottom:8px}
.tier strong{font-family:'Cormorant Garamond',serif;font-size:1.6rem;color:var(--ivory);display:block;margin-bottom:16px}
.tier ul{list-style:none;padding:0;margin:0;color:#bfb8aa;font-size:.86rem}
.tier ul li{padding:6px 0;border-top:1px solid rgba(255,255,255,.06)}
.tier ul li:first-child{border-top:0}

/* ---------- DEALER ---------- */
.dealer{padding:120px 0;background:var(--ivory);position:relative;overflow:hidden}
.dealer::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 85% 15%,rgba(201,169,97,.1),transparent 50%);
  pointer-events:none;
}
.dealer-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;position:relative}
.dealer p{color:var(--muted);margin:18px 0 36px;max-width:480px;line-height:1.75}
.dealer-points{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.dealer-points li{
  background:var(--white);padding:24px 20px;border-radius:12px;border:1px solid var(--line);
}
.dealer-points strong{display:block;font-family:'Italiana',serif;font-size:2.2rem;color:var(--gold-dark);line-height:1;letter-spacing:.02em}
.dealer-points span{font-size:.74rem;letter-spacing:.1em;color:var(--muted);margin-top:8px;display:block;text-transform:uppercase}

.dealer-form{
  background:var(--white);color:var(--charcoal);
  padding:42px 38px;border-radius:var(--radius);box-shadow:var(--shadow);border:1px solid var(--line);
}
.dealer-form h3{font-family:'Cormorant Garamond',serif;font-size:1.7rem;margin-bottom:22px;font-weight:600}
.dealer-form label{display:block;font-size:.76rem;font-weight:600;color:var(--charcoal);margin-bottom:16px;letter-spacing:.08em;text-transform:uppercase}
.dealer-form input,.dealer-form textarea,.dealer-form select{
  width:100%;padding:13px 14px;margin-top:8px;
  border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.92rem;background:var(--ivory);
  transition:border-color .25s var(--ease);
  color:var(--charcoal);text-transform:none;letter-spacing:0;font-weight:400;
}
.dealer-form input:focus,.dealer-form textarea:focus,.dealer-form select:focus{outline:0;border-color:var(--gold);background:var(--white)}
.form-note{display:block;margin-top:12px;font-size:.74rem;color:var(--muted);text-align:center}

/* ---------- JOURNAL ---------- */
.news{padding:120px 0;background:var(--white)}
.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}
.news-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
}
.news-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--gold-soft)}
.news-thumb{height:240px;background-size:cover;background-position:center;position:relative}
.news-thumb::after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 60%,rgba(0,0,0,.1))}
.thumb-1{background:
  radial-gradient(circle at 30% 30%,rgba(255,255,255,.5),transparent 50%),
  linear-gradient(135deg,#f4d3ac,#e7a873)}
.thumb-2{background:
  radial-gradient(circle at 70% 40%,rgba(255,255,255,.4),transparent 50%),
  linear-gradient(135deg,#cfe1d6,#8ab39c)}
.thumb-3{background:
  radial-gradient(circle at 40% 60%,rgba(255,255,255,.4),transparent 50%),
  linear-gradient(135deg,#e8d4cc,#c69b8a)}
.news-body{padding:26px 28px 30px}
.news-meta{font-size:.68rem;color:var(--gold-dark);font-weight:600;letter-spacing:.18em;text-transform:uppercase}
.news-card h3{font-family:'Cormorant Garamond',serif;font-size:1.5rem;font-weight:600;margin:12px 0 12px;line-height:1.25}
.news-card p{color:var(--muted);font-size:.9rem;margin:0 0 16px;line-height:1.65}

/* ---------- INSTAGRAM ---------- */
.insta{padding:120px 0;background:var(--cream)}
.insta-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:4px}
.ig{
  aspect-ratio:1;display:grid;place-items:center;color:rgba(255,255,255,0);
  font-size:2rem;transition:all .3s var(--ease);position:relative;overflow:hidden;
}
.ig::after{content:"";position:absolute;inset:0;background:rgba(20,20,20,.35);opacity:0;transition:opacity .3s var(--ease)}
.ig:hover{color:var(--ivory)}
.ig:hover::after{opacity:1}
.ig i{position:relative;z-index:1}
.ig-1{background:linear-gradient(135deg,#fbeacd,#d9a770)}
.ig-2{background:linear-gradient(135deg,#e7ede2,#8fa78a)}
.ig-3{background:linear-gradient(135deg,#f7dfd6,#c99a8c)}
.ig-4{background:linear-gradient(135deg,#efe5d7,#bf9a6c)}
.ig-5{background:linear-gradient(135deg,#d6d1c4,#938573)}
.ig-6{background:linear-gradient(135deg,#fadad2,#d6927e)}

/* ---------- NEWSLETTER ---------- */
.newsletter{background:linear-gradient(135deg,var(--blush),var(--cream));padding:80px 0}
.news-inner{display:flex;justify-content:space-between;align-items:center;gap:40px;flex-wrap:wrap}
.news-inner h3{font-family:'Italiana',serif;font-size:2.2rem;font-weight:400;letter-spacing:.04em}
.news-inner p{color:var(--muted);margin:6px 0 0;max-width:440px}
.news-inner form{display:flex;gap:10px;flex:1;max-width:460px}
.news-inner input{
  flex:1;padding:15px 18px;border-radius:999px;border:1px solid var(--line);
  background:var(--white);font-family:inherit;font-size:.9rem;
}
.news-inner input:focus{outline:0;border-color:var(--gold)}

/* ---------- FOOTER ---------- */
.site-footer{background:#0f0f0f;color:#c9c3b6;padding:90px 0 0}
.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1.2fr;gap:40px}
.logo-light .logo-text strong{color:var(--ivory)}
.logo-light .logo-text em{color:var(--gold-soft)}
.footer-about{font-size:.86rem;line-height:1.75;margin:22px 0}
.footer-contact{list-style:none;padding:0;margin:0 0 22px}
.footer-contact li{padding:6px 0;font-size:.86rem}
.footer-contact i{color:var(--gold);width:20px}
.footer-contact a:hover{color:var(--gold-soft)}
.footer-app{font-size:.82rem;color:#a8a094;margin:0 0 14px;line-height:1.6}
.site-footer h4{color:var(--ivory);font-size:.74rem;letter-spacing:.22em;margin-bottom:20px}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer ul li{padding:6px 0;font-size:.86rem}
.site-footer ul a{transition:color .2s var(--ease)}
.site-footer ul a:hover{color:var(--gold-soft)}
.socials{display:flex;gap:8px}
.socials a{
  width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.08);display:grid;place-items:center;
  color:var(--ivory);font-size:.88rem;transition:all .25s var(--ease);
}
.socials a:hover{background:var(--gold);border-color:var(--gold);color:var(--charcoal)}

.pay-row{display:flex;gap:6px;flex-wrap:wrap}
.pay{
  background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:#e1d9c8;
  padding:4px 10px;border-radius:6px;font-size:.68rem;letter-spacing:.15em;font-weight:700;
}

.copyright{margin-top:70px;border-top:1px solid rgba(255,255,255,.06);padding:22px 0;font-size:.78rem}
.copyright-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
.copyright .legal{display:flex;gap:22px}
.copyright .legal a{color:#a8a094}
.copyright .legal a:hover{color:var(--gold-soft)}

/* ---------- Floating actions ---------- */
.floating{position:fixed;right:20px;bottom:24px;display:flex;flex-direction:column;gap:10px;z-index:60}
.fab{
  width:52px;height:52px;border-radius:50%;display:grid;place-items:center;
  color:var(--ivory);box-shadow:var(--shadow);position:relative;
  transition:all .25s var(--ease);
}
.fab:hover{transform:translateY(-3px)}
.fab-call{background:var(--gold);animation:pulse 2.2s infinite}
.tip{
  position:absolute;right:60px;background:var(--charcoal);color:var(--ivory);
  padding:5px 12px;border-radius:999px;font-size:.72rem;white-space:nowrap;
  opacity:0;transform:translateX(8px);transition:all .25s var(--ease);pointer-events:none;
}
.fab:hover .tip{opacity:1;transform:translateX(0)}
.fab-zalo{background:#0084ff}
.fab-label{font-weight:700;font-size:.68rem;letter-spacing:.02em}
.fab-fb{background:#0078ff}
.fab-top{background:var(--charcoal);opacity:0;pointer-events:none;transform:translateY(12px);transition:all .25s var(--ease)}
.fab-top.show{opacity:1;pointer-events:auto;transform:none}
@keyframes pulse{
  0%{box-shadow:0 0 0 0 rgba(201,169,97,.55)}
  70%{box-shadow:0 0 0 18px rgba(201,169,97,0)}
  100%{box-shadow:0 0 0 0 rgba(201,169,97,0)}
}

/* ---------- Reveal ---------- */
.reveal{opacity:0;transform:translateY(24px);transition:opacity .8s var(--ease),transform .8s var(--ease)}
.reveal.in{opacity:1;transform:none}

/* ---------- Responsive ---------- */
@media (max-width: 1200px){
  .product-grid,.cat-grid,.values-grid,.ritual-steps,.sci-grid{grid-template-columns:repeat(2,1fr)}
  .ritual-steps::before{display:none}
  .footer-grid{grid-template-columns:1fr 1fr 1fr;gap:40px}
  .footer-grid > *:nth-child(1){grid-column:1/-1}
}
@media (max-width: 1080px){
  .main-nav{display:none}
  .burger{display:inline-block}
  .header-inner{grid-template-columns:auto 1fr auto;gap:16px}
  .logo{justify-self:flex-start;grid-column:2}
  .topbar-left,.topbar-right{gap:18px}
  .topbar-left span:first-child{display:none}
  .hero-grid,.story-grid,.auth-card,.dealer-grid,.ing-grid,.ba-grid{grid-template-columns:1fr;gap:50px}
  .auth-card{padding:50px 30px}
  .hero-side{display:none}
  .h1-line--italic{padding-left:40px}
  .story-visual,.ing-visual{max-width:480px;margin:0 auto}
  .float-chip{display:none}
  .insta-grid{grid-template-columns:repeat(3,1fr)}
  .tiers{grid-template-columns:1fr}
  .tier-gold{transform:none}
}
@media (max-width: 640px){
  .topbar-left,.topbar-right{display:none}
  .topbar{padding:6px 0}
  .announce-track{font-size:.65rem;gap:50px}
  .hero{padding:60px 0 80px}
  .product-grid,.cat-grid,.news-grid,.tm-grid,.values-grid,.ritual-steps,.sci-grid{grid-template-columns:1fr}
  .ing-list{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .section-head.between{flex-direction:column;align-items:flex-start}
  .dealer-points{grid-template-columns:1fr}
  .hero-meta{gap:24px}
  .auth-card{padding:40px 24px}
  .copyright-inner{flex-direction:column;text-align:center}
  .h1-line--italic{padding-left:0}
  .press-logos{gap:20px}
  .press-item{font-size:1.2rem !important}
  .cert-list{gap:16px 28px}
  .cert-list li{font-size:.7rem}
  .container{padding:0 20px}
}

