/* =========================================================
   DETOXBLANC — Dermatological Skincare
   Clinical tone: Green · Gray · White
   Type: Manrope (body) + Space Grotesk (display/numbers)
   ========================================================= */

:root{
  /* greens */
  --g-50:       #F2F8F5;
  --g-100:      #E2EFE8;
  --g-200:      #C8DFD2;
  --g-300:      #A3CBB5;
  --g-400:      #5FAF8B;
  --g-500:      #2E9E7E;
  --g-600:      #1E6F5C;
  --g-700:      #14503F;
  --g-800:      #0E3A2C;
  --g-900:      #0B2A20;

  /* grays */
  --white:      #FFFFFF;
  --gray-50:    #F7F9F8;
  --gray-100:   #EEF1EF;
  --gray-200:   #E0E4E2;
  --gray-300:   #C9CFCC;
  --gray-400:   #9AA29D;
  --gray-500:   #6B7571;
  --gray-600:   #4B5551;
  --gray-700:   #3B4441;
  --gray-800:   #262D2A;
  --gray-900:   #1A1F1D;

  /* semantic */
  --brand:      var(--g-600);
  --brand-soft: var(--g-100);
  --accent:     var(--g-500);
  --ink:        var(--gray-800);
  --muted:      var(--gray-500);
  --line:       var(--gray-200);
  --line-soft:  var(--gray-100);
  --bg:         var(--white);
  --bg-alt:     var(--gray-50);
  --bg-mint:    var(--g-50);
  --dark:       var(--gray-900);

  --radius:     14px;
  --radius-sm:  8px;
  --shadow-xs:  0 1px 2px rgba(20,31,29,.04);
  --shadow-sm:  0 2px 10px rgba(20,31,29,.05);
  --shadow:     0 10px 30px rgba(20,31,29,.07);
  --shadow-lg:  0 24px 60px rgba(20,31,29,.12);
  --ease:       cubic-bezier(.2,.7,.2,1);
  --container:  1280px;
}

*,*::before,*::after{box-sizing:border-box}
html,body{margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:'Manrope', system-ui, -apple-system, sans-serif;
  color:var(--ink);
  background:var(--bg);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:0;background:transparent}

.container{max-width:var(--container);margin:0 auto;padding:0 32px}
.center{text-align:center}
.mt-24{margin-top:24px}
.mt-40{margin-top:40px}
sup{font-size:.55em;vertical-align:super;font-weight:500;color:var(--brand)}

/* ---------- Typography ---------- */
h1,h2,h3,h4,h5{color:var(--gray-900);margin:0;letter-spacing:-.015em;font-family:'Manrope',sans-serif;font-weight:700}
h1{font-size:clamp(2.6rem,5.2vw,4.6rem);line-height:1.04;letter-spacing:-.03em;font-weight:700}
h2{font-size:clamp(2rem,3.4vw,3rem);line-height:1.12;letter-spacing:-.02em;font-weight:700}
h3{font-size:1.2rem;line-height:1.3;font-weight:700;letter-spacing:-.01em}
h4{font-size:.78rem;color:var(--gray-900);letter-spacing:.2em;text-transform:uppercase;font-weight:700}
h5{font-size:.72rem;color:var(--gray-900);letter-spacing:.22em;text-transform:uppercase;font-weight:700}

.hl{color:var(--brand);font-weight:700;position:relative}
.hl::after{
  content:"";position:absolute;left:0;right:0;bottom:-2px;height:3px;
  background:var(--g-200);border-radius:2px;z-index:-1;opacity:.7;
}
em{font-style:normal;color:var(--brand);font-weight:700}

.eyebrow{
  font-family:'Space Grotesk',sans-serif;
  font-size:.72rem;font-weight:600;
  letter-spacing:.24em;color:var(--brand);
  text-transform:uppercase;display:inline-flex;align-items:center;gap:10px;margin-bottom:18px;
}
.eyebrow::before{content:"";width:24px;height:1px;background:var(--brand)}
.eyebrow.light{color:var(--g-300)}
.eyebrow.light::before{background:var(--g-300)}
.center-eyebrow{display:inline-flex;text-align:center}

.section-head{margin-bottom:64px}
.section-head.center{text-align:center;max-width:720px;margin-inline:auto}
.section-head.center .eyebrow{display:inline-flex;margin-bottom:16px}
.section-head.between{
  display:flex;justify-content:space-between;align-items:flex-end;
  text-align:left;flex-wrap:wrap;gap:24px;
}
.section-sub{color:var(--muted);margin-top:18px;font-size:1rem;line-height:1.7}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:14px 26px;border-radius:10px;border:1px solid transparent;
  font-weight:700;font-size:.84rem;letter-spacing:.04em;
  transition:all .25s var(--ease);font-family:'Manrope',sans-serif;
}
.btn i{font-size:.9em;letter-spacing:0}
.btn-primary{background:var(--brand);color:var(--white);box-shadow:0 4px 14px rgba(30,111,92,.25)}
.btn-primary:hover{background:var(--g-700);transform:translateY(-2px);box-shadow:0 8px 22px rgba(30,111,92,.3)}
.btn-dark{background:var(--gray-900);color:var(--white);padding:12px 18px;font-size:.78rem;border-radius:8px}
.btn-dark:hover{background:var(--brand)}
.btn-outline{background:transparent;border-color:var(--gray-300);color:var(--gray-900)}
.btn-outline:hover{border-color:var(--brand);color:var(--brand);background:var(--g-50)}
.btn-ghost{background:transparent;color:var(--gray-900);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--brand)}
.btn-block{display:flex;width:100%;justify-content:center}

.link-arrow{
  display:inline-flex;align-items:center;gap:8px;
  font-weight:600;font-size:.82rem;color:var(--gray-900);
  border-bottom:1.5px solid var(--gray-900);padding-bottom:3px;
  transition:all .25s var(--ease);
}
.link-arrow:hover{color:var(--brand);border-color:var(--brand);gap:14px}
.link-arrow.sm{font-size:.76rem}

/* ---------- Announcement ---------- */
.announce{background:var(--gray-900);color:var(--white);overflow:hidden}
.announce-track{
  display:flex;gap:56px;white-space:nowrap;padding:10px 0;
  animation:marquee 45s linear infinite;
  font-size:.74rem;font-weight:500;letter-spacing:.02em;
}
.announce-track i{color:var(--g-400);margin-right:6px}
.announce-track span{position:relative;display:inline-flex;align-items:center}
.announce-track span::after{
  content:"";position:absolute;right:-28px;top:50%;transform:translateY(-50%);
  width:4px;height:4px;background:var(--g-500);border-radius:50%;
}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Topbar ---------- */
.topbar{background:var(--white);color:var(--ink);font-size:.78rem;padding:9px 0;border-bottom:1px solid var(--line)}
.topbar-inner{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.topbar-left,.topbar-right{display:flex;gap:26px;align-items:center;flex-wrap:wrap}
.topbar i{color:var(--brand);margin-right:6px}
.topbar-right a:hover{color:var(--brand)}
.locale{position:relative}
.locale-btn{display:inline-flex;align-items:center;gap:6px;font-size:.78rem;color:var(--ink);font-family:inherit}
.locale-btn .flag{font-size:1rem}
.locale-btn i{font-size:.7em;color:var(--muted);margin:0}
.locale-menu{
  position:absolute;top:calc(100% + 10px);right:0;min-width:200px;
  background:var(--white);border:1px solid var(--line);border-radius:12px;
  padding:6px;box-shadow:var(--shadow);
  opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .25s var(--ease);z-index:60;
}
.locale:hover .locale-menu{opacity:1;visibility:visible;transform:translateY(0)}
.locale-menu a{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:8px;font-size:.82rem}
.locale-menu a:hover{background:var(--g-50)}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:50;background:rgba(255,255,255,.96);
  backdrop-filter:blur(16px);border-bottom:1px solid var(--line);
  transition:all .3s var(--ease);
}
.site-header.scrolled{box-shadow:0 2px 12px rgba(20,31,29,.05)}
.header-inner{
  display:grid;grid-template-columns:auto 1fr auto;
  align-items:center;gap:24px;padding:16px 32px;
}
.logo{display:flex;align-items:center;gap:12px;color:var(--brand)}
.logo-mark{
  width:42px;height:42px;display:grid;place-items:center;
}
.logo-mark svg{width:100%;height:100%}
.logo-text{display:flex;flex-direction:column;line-height:1}
.logo-text strong{font-family:'Space Grotesk',sans-serif;font-size:1.35rem;font-weight:700;letter-spacing:.12em;color:var(--gray-900)}
.logo-text em{font-family:'Manrope',sans-serif;font-size:.62rem;letter-spacing:.24em;color:var(--brand);margin-top:4px;text-transform:uppercase;font-style:normal;font-weight:600}

.main-nav{display:flex;justify-content:center;gap:6px}
.main-nav > a,.nav-item > a{
  font-size:.82rem;font-weight:600;letter-spacing:.02em;
  color:var(--gray-700);padding:10px 14px;position:relative;display:inline-flex;align-items:center;gap:6px;
  transition:color .25s var(--ease);border-radius:8px;
}
.main-nav > a:hover,.nav-item:hover > a{color:var(--brand);background:var(--g-50)}
.main-nav > a.active{color:var(--brand)}
.main-nav > a.active::after{
  content:"";position:absolute;left:50%;right:0;bottom:2px;height:2px;
  width:20px;margin-left:-10px;background:var(--brand);border-radius:2px;
}
.nav-item{position:static}
.nav-item > a i{font-size:.6rem;opacity:.6}

/* Mega-menu */
.mega{
  position:absolute;left:0;right:0;top:100%;background:var(--white);
  border-top:1px solid var(--line);box-shadow:var(--shadow-lg);
  padding:40px 32px;opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .3s var(--ease);z-index:40;
}
.nav-item:hover .mega{opacity:1;visibility:visible;transform:translateY(0)}
.mega-grid{max-width:var(--container);margin:0 auto;display:grid;grid-template-columns:repeat(3,1fr) 1.3fr;gap:50px}
.mega h5{margin-bottom:18px;color:var(--brand)}
.mega ul{list-style:none;padding:0;margin:0}
.mega ul li{padding:7px 0}
.mega ul a{font-size:.86rem;color:var(--gray-700);transition:color .2s var(--ease);display:inline-flex;align-items:center;gap:10px}
.mega ul a i{color:var(--g-400);font-size:.82rem;width:14px}
.mega ul a:hover{color:var(--brand)}
.mega-feature{
  background:var(--bg-mint);
  border-radius:var(--radius);padding:22px;
  display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center;position:relative;
  transition:all .3s var(--ease);border:1px solid var(--g-100);
}
.mega-feature:hover{transform:translateY(-3px);box-shadow:var(--shadow);border-color:var(--g-300)}
.mega-feature .tag-green{
  position:absolute;top:12px;right:12px;font-size:.58rem;font-weight:700;letter-spacing:.22em;
  color:var(--white);background:var(--brand);padding:4px 8px;border-radius:4px;
}
.mega-visual{width:70px}
.mega-visual .mini{width:100%;height:auto}
.mega-feature strong{display:block;font-size:1rem;color:var(--gray-900);font-weight:700;margin-bottom:2px}
.mega-feature span{font-size:.76rem;color:var(--muted);display:block;font-family:'Space Grotesk',sans-serif}

.header-actions{display:flex;align-items:center;gap:4px}
.icon-btn{
  width:40px;height:40px;border-radius:10px;
  color:var(--gray-900);position:relative;
  transition:all .25s var(--ease);
}
.icon-btn:hover{background:var(--g-50);color:var(--brand)}
.badge{
  position:absolute;top:4px;right:4px;background:var(--brand);color:var(--white);
  font-size:.6rem;font-weight:700;min-width:17px;height:17px;border-radius:50%;
  display:grid;place-items:center;padding:0 4px;font-family:'Space Grotesk',sans-serif;
}
.burger{display:none;font-size:1.3rem;color:var(--gray-900)}

/* ---------- HERO ---------- */
.hero{
  position:relative;overflow:hidden;background:var(--bg-mint);
  padding:80px 0 100px;min-height:88vh;
}
.hero-bg{position:absolute;inset:0;z-index:0;pointer-events:none}
.bg-blob{position:absolute;border-radius:50%;filter:blur(90px);opacity:.5}
.b1{width:640px;height:640px;background:var(--g-200);top:-180px;right:-180px}
.b2{width:520px;height:520px;background:var(--g-100);bottom:-180px;left:-120px}
.bg-grid{
  position:absolute;inset:0;opacity:.25;
  background-image:
    linear-gradient(var(--g-100) 1px, transparent 1px),
    linear-gradient(90deg, var(--g-100) 1px, transparent 1px);
  background-size:44px 44px;mask-image:radial-gradient(ellipse at center, #000 30%, transparent 75%);
}

.hero-side{
  position:absolute;left:24px;top:50%;transform:translateY(-50%) rotate(-90deg);transform-origin:left center;
  display:flex;gap:14px;font-size:.68rem;letter-spacing:.3em;color:var(--muted);text-transform:uppercase;z-index:2;
  font-family:'Space Grotesk',sans-serif;font-weight:600;
}
.hero-side .dot{color:var(--brand);font-size:.45rem}

.hero-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:50px;align-items:center;position:relative;z-index:2}

.hero-pill{
  display:inline-flex;align-items:center;gap:10px;
  padding:8px 16px;background:var(--white);border:1px solid var(--g-200);border-radius:999px;
  color:var(--brand);font-size:.76rem;font-weight:600;margin-bottom:24px;
}
.pill-dot{
  width:8px;height:8px;border-radius:50%;background:var(--g-500);
  box-shadow:0 0 0 4px rgba(46,158,126,.2);
  animation:pulse-dot 2s ease-in-out infinite;
}
@keyframes pulse-dot{50%{box-shadow:0 0 0 8px rgba(46,158,126,0)}}

.h1-accent{color:var(--brand);font-weight:700}
.lead{font-size:1.05rem;color:var(--gray-600);max-width:560px;margin:24px 0 32px;line-height:1.7}
.lead strong{color:var(--gray-900);font-weight:700}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:48px}

.hero-specs{
  display:grid;grid-template-columns:repeat(3,1fr);gap:28px;
  padding-top:24px;border-top:1px solid var(--line);max-width:600px;
}
.spec strong{
  font-family:'Space Grotesk',sans-serif;font-size:2rem;font-weight:700;
  color:var(--gray-900);display:block;line-height:1;letter-spacing:-.02em;
}
.spec strong em{font-size:.6em;color:var(--muted);font-style:normal;font-weight:500;margin-left:2px}
.spec span{font-size:.76rem;color:var(--muted);line-height:1.45;margin-top:8px;display:block}
.hero-disclaim{font-size:.7rem;color:var(--gray-400);margin-top:14px}

/* Hero visual */
.hero-visual{position:relative;display:grid;place-items:center;min-height:560px}
.hero-frame{
  position:relative;width:100%;max-width:460px;aspect-ratio:3/4;
  border-radius:var(--radius);background:
    radial-gradient(circle at 30% 30%, var(--white), var(--g-50)),
    var(--g-100);
  border:1px solid var(--g-200);
  box-shadow:var(--shadow-lg);
}
.hero-frame::before{
  content:"";position:absolute;inset:0;border-radius:var(--radius);
  background:
    radial-gradient(circle at 20% 10%, rgba(46,158,126,.08), transparent 50%),
    radial-gradient(circle at 80% 90%, rgba(46,158,126,.06), transparent 50%);
}
.bottle-hero{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-52%);width:68%;
  filter:drop-shadow(0 30px 30px rgba(20,31,29,.15));
}

.badge-float{
  position:absolute;background:var(--white);border:1px solid var(--line);border-radius:12px;
  padding:10px 14px;box-shadow:var(--shadow);display:flex;align-items:center;gap:10px;
}
.badge-float strong{display:block;font-size:.88rem;color:var(--gray-900);font-weight:700;font-family:'Space Grotesk',sans-serif}
.badge-float span{font-size:.68rem;color:var(--muted);display:block}
.badge-float i{color:var(--brand);font-size:1.3rem}
.bf-1{top:18%;left:-8%}
.bf-2{top:50%;right:-10%}

.price-tag{
  position:absolute;bottom:18px;left:18px;right:18px;
  background:var(--white);border:1px solid var(--line);border-radius:12px;
  padding:14px 18px;display:flex;align-items:center;gap:14px;justify-content:space-between;
  box-shadow:var(--shadow);
}
.price-tag .small{font-size:.62rem;letter-spacing:.2em;color:var(--brand);text-transform:uppercase;font-weight:700;display:block;font-family:'Space Grotesk',sans-serif}
.price-tag strong{font-family:'Space Grotesk',sans-serif;font-size:1.3rem;color:var(--gray-900);display:block;margin-top:3px;font-weight:700}
.price-tag a{
  font-size:.76rem;font-weight:700;color:var(--white);
  background:var(--gray-900);padding:10px 16px;border-radius:8px;
  transition:background .25s var(--ease);
}
.price-tag a:hover{background:var(--brand)}
.price-tag a i{margin-right:6px}

.hero-scroll{
  position:absolute;bottom:30px;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:6px;
  font-size:.66rem;letter-spacing:.28em;color:var(--muted);text-transform:uppercase;z-index:3;
  animation:bob 2.2s ease-in-out infinite;font-family:'Space Grotesk',sans-serif;font-weight:600;
}
.hero-scroll i{color:var(--brand)}
@keyframes bob{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(6px)}}

/* ---------- Certification strip ---------- */
.certstrip{background:var(--white);padding:36px 0;border-bottom:1px solid var(--line)}
.certstrip ul{
  list-style:none;padding:0;margin:0;display:grid;
  grid-template-columns:repeat(6,1fr);gap:24px;
}
.certstrip li{display:flex;align-items:center;gap:12px}
.certstrip i{
  width:44px;height:44px;border-radius:10px;background:var(--g-50);color:var(--brand);
  display:grid;place-items:center;font-size:1.1rem;flex-shrink:0;
}
.certstrip span{display:flex;flex-direction:column;font-size:.82rem;font-weight:700;color:var(--gray-900);line-height:1.3}
.certstrip small{font-size:.68rem;color:var(--muted);font-weight:500;margin-top:2px;letter-spacing:.01em}

/* ---------- Statement ---------- */
.statement{padding:120px 0;background:var(--bg-mint);text-align:center}
.statement-head{
  font-family:'Manrope',sans-serif;font-size:clamp(1.6rem,2.8vw,2.6rem);
  max-width:960px;margin:0 auto;line-height:1.4;color:var(--gray-900);font-weight:500;
  letter-spacing:-.015em;
}
.statement-head .hl::after{background:var(--g-200)}
.statement-sign{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:36px;color:var(--muted);font-size:.8rem;font-weight:500}
.sig-line{width:36px;height:1px;background:var(--brand)}

/* ---------- Skin Finder ---------- */
.finder{padding:120px 0;background:var(--white)}
.finder-grid{display:grid;grid-template-columns:1fr 1.2fr;gap:60px;align-items:center}
.finder-copy .lead{margin:18px 0 28px}
.finder-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.finder-card{
  background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);
  padding:26px 16px;display:flex;flex-direction:column;align-items:center;gap:12px;
  color:var(--gray-900);font-weight:600;font-size:.9rem;
  transition:all .3s var(--ease);cursor:pointer;font-family:inherit;
}
.finder-card:hover{background:var(--brand);color:var(--white);transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--brand)}
.finder-card i{font-size:1.8rem;color:var(--brand);transition:color .3s var(--ease)}
.finder-card:hover i{color:var(--white)}

/* ---------- Categories ---------- */
.categories{padding:120px 0;background:var(--bg-alt)}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.cat-card{
  background:var(--white);border-radius:var(--radius);overflow:hidden;
  transition:all .35s var(--ease);display:flex;flex-direction:column;
  border:1px solid var(--line);
}
.cat-card:hover{transform:translateY(-6px);border-color:var(--brand);box-shadow:var(--shadow)}
.cat-visual{
  aspect-ratio:4/3;position:relative;display:grid;place-items:center;
  background:var(--bg-mint);color:var(--g-300);font-size:3.4rem;
}
.cat-visual::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 30% 30%,rgba(255,255,255,.8),transparent 60%);
}
.cat-card:hover .cat-visual{background:var(--g-100);color:var(--brand)}
.cat-n{
  position:absolute;top:18px;left:18px;font-family:'Space Grotesk',sans-serif;font-size:.82rem;letter-spacing:.2em;
  color:var(--brand);font-weight:700;
}
.cat-visual i{position:relative;z-index:1;transition:transform .4s var(--ease)}
.cat-card:hover .cat-visual i{transform:scale(1.1)}
.cat-body{padding:24px 24px 26px}
.cat-body h3{font-size:1.3rem;margin-bottom:6px}
.cat-body p{color:var(--muted);font-size:.88rem;margin:0 0 14px;line-height:1.55}
.cat-cta{
  font-size:.76rem;font-weight:700;color:var(--brand);letter-spacing:.04em;
  display:inline-flex;align-items:center;gap:6px;
  transition:gap .25s var(--ease);
}
.cat-card:hover .cat-cta{gap:12px}

/* ---------- Products ---------- */
.products{padding:120px 0;background:var(--white)}
.product-tabs{display:flex;gap:6px;flex-wrap:wrap;background:var(--bg-alt);padding:4px;border-radius:12px}
.tab{
  padding:10px 16px;border-radius:8px;
  background:transparent;font-size:.78rem;font-weight:600;color:var(--gray-600);letter-spacing:.01em;
  transition:all .25s var(--ease);font-family:inherit;
}
.tab:hover{color:var(--gray-900)}
.tab.active{background:var(--white);color:var(--brand);box-shadow:var(--shadow-sm)}

.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);display:flex;flex-direction:column;
}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--g-300)}
.product-media{
  position:relative;padding:36px 20px 24px;display:grid;place-items:center;min-height:320px;
  background:var(--bg-mint);
}
.bottle-svg{width:130px;height:auto;filter:drop-shadow(0 14px 18px rgba(20,31,29,.1))}

.tag{
  position:absolute;top:14px;left:14px;font-size:.6rem;font-weight:700;
  letter-spacing:.22em;padding:5px 10px;border-radius:4px;color:var(--white);text-transform:uppercase;font-family:'Space Grotesk',sans-serif;
}
.tag-sale{background:var(--gray-900)}
.tag-hot{background:#B9503E}
.tag-new{background:var(--brand)}
.tag-green{background:var(--brand)}

.wish{
  position:absolute;top:10px;right:10px;width:34px;height:34px;border-radius:50%;background:var(--white);color:var(--gray-900);
  border:1px solid var(--line);transition:all .25s var(--ease);display:grid;place-items:center;font-size:.86rem;
}
.wish:hover{background:var(--brand);color:var(--white);border-color:var(--brand)}

.quick{
  position:absolute;bottom:16px;left:50%;transform:translate(-50%,8px);
  opacity:0;background:var(--gray-900);color:var(--white);
  padding:9px 18px;border-radius:999px;font-size:.68rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;
  transition:all .3s var(--ease);
}
.product-card:hover .quick{opacity:1;transform:translate(-50%,0)}

.active-ingr{
  position:absolute;bottom:12px;right:12px;
  background:var(--white);border:1px solid var(--line);border-radius:999px;
  padding:5px 12px;font-size:.66rem;font-weight:700;color:var(--brand);letter-spacing:.04em;
  font-family:'Space Grotesk',sans-serif;
}

.product-body{padding:22px 22px 26px;display:flex;flex-direction:column;gap:10px;flex:1}
.product-body .cat{font-size:.68rem;letter-spacing:.16em;color:var(--brand);font-weight:700;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px;font-family:'Space Grotesk',sans-serif}
.product-body .cat i{font-size:.72rem}
.product-body h3{font-size:1rem;font-weight:700;color:var(--gray-900);line-height:1.35;min-height:44px;letter-spacing:-.005em}
.spec-bullets{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:4px}
.spec-bullets li{font-size:.78rem;color:var(--gray-600);display:flex;align-items:center;gap:8px;line-height:1.4}
.spec-bullets i{color:var(--brand);font-size:.68rem}
.stars{color:#E4A93C;font-size:.78rem;display:flex;align-items:center;gap:2px}
.stars small{color:var(--muted);margin-left:6px;font-size:.72rem;font-weight:500}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:auto}
.price{font-family:'Space Grotesk',sans-serif;font-size:1.25rem;font-weight:700;color:var(--gray-900);letter-spacing:-.01em}
.price-old{font-size:.82rem;color:var(--muted);text-decoration:line-through}

/* ---------- Ingredient ---------- */
.ingredient{padding:120px 0;background:var(--bg-mint)}
.ing-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:80px;align-items:center}
.ing-visual{position:relative;aspect-ratio:1/1;display:grid;place-items:center}
.molecule{width:90%;height:90%;display:grid;place-items:center;animation:moleculeRotate 40s linear infinite}
.molecule svg{width:100%;height:100%;filter:drop-shadow(0 20px 40px rgba(30,111,92,.15))}
@keyframes moleculeRotate{to{transform:rotate(360deg)}}
.ing-callout{
  position:absolute;right:2%;bottom:4%;background:var(--gray-900);color:var(--white);
  padding:16px 22px;border-radius:12px;box-shadow:var(--shadow-lg);
}
.ing-callout strong{display:block;font-family:'Space Grotesk',sans-serif;font-size:1.1rem;color:var(--g-300);font-weight:700}
.ing-callout span{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.7);font-weight:500}

.ing-lede{color:var(--gray-600);font-size:1.02rem;margin:18px 0 36px;max-width:540px;line-height:1.7}
.ing-list{display:grid;grid-template-columns:1fr 1fr;gap:28px 40px;margin-bottom:32px}
.ing-item{display:flex;gap:16px;align-items:flex-start}
.ing-num{
  font-family:'Space Grotesk',sans-serif;font-size:.86rem;color:var(--brand);font-weight:700;
  letter-spacing:.1em;padding:6px 10px;min-width:36px;background:var(--white);border-radius:8px;
  text-align:center;border:1px solid var(--g-100);
}
.ing-item strong{display:block;color:var(--gray-900);font-weight:700;margin-bottom:4px;font-size:.92rem}
.ing-item strong em{color:var(--brand);font-weight:700;font-family:'Space Grotesk',sans-serif;margin-left:4px}
.ing-item p{font-size:.82rem;color:var(--muted);margin:0;line-height:1.55}

/* ---------- Science ---------- */
.science{padding:120px 0;background:var(--white)}
.sci-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-bottom:40px}
.sci-stat{
  background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);
  padding:36px 26px;text-align:center;position:relative;overflow:hidden;
  transition:all .35s var(--ease);
}
.sci-stat:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--g-300)}
.sci-stat::before{
  content:"";position:absolute;top:0;left:0;right:0;height:3px;background:var(--brand);
}
.sci-num{font-family:'Space Grotesk',sans-serif;font-size:4.4rem;color:var(--gray-900);line-height:1;letter-spacing:-.03em;font-weight:700}
.sci-pct{font-family:'Space Grotesk',sans-serif;font-size:1.8rem;color:var(--brand);margin-left:4px;vertical-align:top;font-weight:700}
.sci-stat p{margin:14px 0 0;font-size:.86rem;color:var(--muted);line-height:1.5}
.sci-stat p strong{color:var(--gray-900);font-weight:700}

.sci-note{
  text-align:center;font-size:.82rem;color:var(--muted);
  padding:16px 24px;background:var(--bg-mint);border-radius:10px;max-width:620px;margin:0 auto;
}
.sci-note i{color:var(--brand);margin-right:8px}
.sci-note strong{color:var(--gray-900)}

/* ---------- Ritual ---------- */
.ritual{padding:120px 0;background:var(--bg-alt)}
.ritual-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;position:relative}
.ritual-steps::before{
  content:"";position:absolute;top:100px;left:13%;right:13%;height:1px;
  background:repeating-linear-gradient(90deg,var(--g-300) 0 6px, transparent 6px 12px);
  z-index:0;
}
.ritual-step{
  background:var(--white);border-radius:var(--radius);padding:36px 26px;
  text-align:center;border:1px solid var(--line);transition:all .35s var(--ease);position:relative;z-index:1;
}
.ritual-step:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--brand)}
.step-num{
  font-family:'Space Grotesk',sans-serif;font-size:.84rem;color:var(--brand);font-weight:700;
  letter-spacing:.12em;display:inline-block;padding:4px 12px;background:var(--g-50);border-radius:20px;
}
.step-icon{
  width:72px;height:72px;border-radius:50%;
  background:var(--bg-mint);color:var(--brand);border:1px solid var(--g-200);
  display:grid;place-items:center;font-size:1.5rem;margin:18px auto 20px;
  transition:all .35s var(--ease);
}
.ritual-step:hover .step-icon{background:var(--brand);color:var(--white);border-color:var(--brand)}
.ritual-step h3{font-size:1.2rem;margin-bottom:8px}
.ritual-step p{color:var(--muted);font-size:.86rem;margin:0 0 18px;line-height:1.55}

/* ---------- Before / After ---------- */
.ba{padding:120px 0;background:var(--white)}
.ba-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:70px;align-items:center}
.ba-points{list-style:none;padding:0;margin:18px 0 30px}
.ba-points li{padding:10px 0;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;font-size:.9rem;color:var(--gray-700)}
.ba-points i{color:var(--brand);background:var(--g-50);width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:.68rem}
.ba-slider{
  position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;
  box-shadow:var(--shadow-lg);cursor:ew-resize;user-select:none;border:1px solid var(--line);
}
.ba-img{position:absolute;inset:0;background-size:cover;background-position:center}
.ba-before{
  background:
    radial-gradient(circle at 50% 55%,#e2b8a5 0%,#b78878 35%,#8c5f52 70%);
  clip-path:inset(0 50% 0 0);
}
.ba-before::after{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 42% 48%,rgba(90,50,35,.5) 2%, transparent 8%),
    radial-gradient(circle at 55% 52%,rgba(90,50,35,.5) 2%, transparent 7%),
    radial-gradient(circle at 48% 60%,rgba(90,50,35,.45) 2%, transparent 6%),
    radial-gradient(circle at 60% 45%,rgba(90,50,35,.4) 2%, transparent 5%),
    radial-gradient(circle at 40% 65%,rgba(90,50,35,.35) 2%, transparent 5%);
  mix-blend-mode:multiply;
}
.ba-after{
  background:radial-gradient(circle at 50% 55%,#fadcc8 0%,#e8bfa4 40%,#b38870 80%);
}
.ba-label{
  position:absolute;top:18px;padding:6px 14px;background:var(--white);
  font-size:.68rem;letter-spacing:.22em;text-transform:uppercase;font-weight:700;color:var(--gray-900);border-radius:999px;
  z-index:3;pointer-events:none;font-family:'Space Grotesk',sans-serif;box-shadow:var(--shadow-sm);
}
.ba-label-before{left:18px;background:var(--gray-900);color:var(--white)}
.ba-label-after{right:18px;background:var(--brand);color:var(--white)}
.ba-handle{
  position:absolute;top:0;bottom:0;left:50%;width:2px;background:var(--white);z-index:4;
  cursor:ew-resize;box-shadow:0 0 0 1px rgba(0,0,0,.1);
}
.ba-knob{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:46px;height:46px;border-radius:50%;background:var(--white);color:var(--brand);
  display:grid;grid-template-columns:1fr 1fr;place-items:center;gap:4px;padding:0 6px;
  box-shadow:0 6px 18px rgba(0,0,0,.2);font-size:.7rem;border:1px solid var(--line);
}

/* ---------- Story ---------- */
.story{padding:130px 0;background:var(--bg-mint)}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.story-visual{position:relative;display:grid;grid-template-columns:1.2fr 1fr;grid-template-rows:1fr 1fr;gap:16px;aspect-ratio:1/1.1}
.story-img{border-radius:var(--radius);overflow:hidden;background-size:cover;background-position:center;border:1px solid var(--g-100)}
.img-lab{grid-row:1/3;background:var(--white);position:relative}
.img-lab svg{width:100%;height:100%;object-fit:cover}
.img-leaf{
  background:
    radial-gradient(circle at 30% 30%,var(--g-200),var(--g-400) 70%);
  position:relative;
}
.img-leaf::before{
  content:"\f06c";font-family:"Font Awesome 6 Free";font-weight:900;
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  font-size:4rem;color:rgba(255,255,255,.8);
}
.img-drops{
  background:linear-gradient(135deg,var(--gray-100),var(--gray-300));
  position:relative;
}
.img-drops::before{
  content:"\f043";font-family:"Font Awesome 6 Free";font-weight:900;
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  font-size:3.6rem;color:var(--brand);
}
.story-badge{
  position:absolute;bottom:-28px;left:-28px;background:var(--gray-900);
  color:var(--white);padding:22px 26px;border-radius:var(--radius);
  display:flex;align-items:center;gap:14px;box-shadow:var(--shadow-lg);
}
.story-badge strong{font-family:'Space Grotesk',sans-serif;font-size:2.2rem;color:var(--g-300);line-height:1;letter-spacing:-.02em;font-weight:700}
.story-badge span{font-size:.72rem;line-height:1.45;color:rgba(255,255,255,.85)}

.story-copy p{color:var(--gray-600);margin:18px 0;line-height:1.8}
.story-copy p strong{color:var(--gray-900)}
.story-copy p em{color:var(--brand);font-style:normal}
.story-quote{
  margin:28px 0;padding:22px 26px;border-left:3px solid var(--brand);
  background:var(--white);border-radius:0 12px 12px 0;
  font-size:1.06rem;color:var(--gray-900);font-weight:500;line-height:1.55;
}

/* ---------- Values ---------- */
.values{padding:120px 0;background:var(--white)}
.values-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.value-card{
  padding:36px 26px;text-align:center;border-radius:var(--radius);
  background:var(--bg-mint);border:1px solid var(--g-100);transition:all .35s var(--ease);
}
.value-card:hover{transform:translateY(-4px);border-color:var(--brand);box-shadow:var(--shadow);background:var(--white)}
.value-icon{
  width:64px;height:64px;border-radius:14px;
  background:var(--white);color:var(--brand);border:1px solid var(--g-200);
  display:grid;place-items:center;font-size:1.4rem;margin:0 auto 20px;
  transition:all .35s var(--ease);
}
.value-card:hover .value-icon{background:var(--brand);color:var(--white);border-color:var(--brand)}
.value-card h3{font-size:1.1rem;margin-bottom:8px}
.value-card p{font-size:.86rem;color:var(--muted);margin:0;line-height:1.55}

/* ---------- Auth ---------- */
.auth{padding:100px 0;background:var(--bg-alt)}
.auth-card{
  background:
    radial-gradient(circle at 80% 20%,rgba(46,158,126,.2),transparent 50%),
    radial-gradient(circle at 10% 90%,rgba(46,158,126,.1),transparent 45%),
    linear-gradient(135deg,var(--gray-900) 0%,var(--g-900) 100%);
  color:var(--white);border-radius:calc(var(--radius) + 8px);
  padding:80px 70px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;
  position:relative;overflow:hidden;
}
.auth-copy h2{color:var(--white)}
.auth-copy h2 .hl{color:var(--g-300)}
.auth-copy h2 .hl::after{background:rgba(95,175,139,.3)}
.auth-copy p{color:rgba(255,255,255,.75);margin:18px 0 30px;max-width:480px;line-height:1.7}
.auth-copy p strong{color:var(--g-300)}
.store-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}
.store-btn{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--white);color:var(--gray-900);padding:10px 18px;border-radius:10px;
  transition:all .25s var(--ease);
}
.store-btn:hover{transform:translateY(-2px)}
.store-btn i{font-size:1.6rem}
.store-btn span{display:flex;flex-direction:column;line-height:1.1;font-size:.92rem;font-weight:700}
.store-btn small{font-size:.6rem;font-weight:500;color:var(--muted);letter-spacing:.06em}
.store-btns.sm .store-btn{padding:8px 14px;background:transparent;color:var(--white);border:1px solid rgba(255,255,255,.2)}
.store-btns.sm .store-btn small{color:rgba(255,255,255,.5)}
.auth-copy .link-arrow{color:var(--g-300);border-color:var(--g-300)}
.auth-copy .link-arrow:hover{color:var(--white);border-color:var(--white)}

.auth-visual{position:relative;display:grid;place-items:center}
.qr-frame{text-align:center;color:var(--white)}
.qr-mock{
  width:240px;height:240px;background:var(--white);border-radius:20px;
  padding:24px;position:relative;margin:0 auto 16px;
  box-shadow:0 30px 60px rgba(0,0,0,.4);
}
.qr-dot{position:absolute;width:46px;height:46px;border:7px solid var(--gray-900);border-radius:8px}
.qr-dot.tl{top:20px;left:20px}
.qr-dot.tr{top:20px;right:20px}
.qr-dot.bl{bottom:20px;left:20px}
.qr-inner{
  position:absolute;inset:28px;
  background-image:
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900));
  background-size:12px 12px,18px 18px,24px 12px,12px 24px,15px 15px,20px 14px,14px 20px,22px 22px;
  background-position:80px 26px,28px 92px,100px 80px,160px 100px,70px 140px,140px 150px,108px 180px,34px 160px;
  background-repeat:no-repeat;
}
.qr-logo{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:56px;height:56px;border-radius:50%;background:var(--white);
  display:grid;place-items:center;
  box-shadow:0 4px 10px rgba(0,0,0,.2),inset 0 0 0 2px var(--brand);
}
.qr-logo svg{width:70%;height:70%}
.qr-frame p{font-size:.74rem;letter-spacing:.22em;color:var(--g-300);text-transform:uppercase;font-weight:700;font-family:'Space Grotesk',sans-serif}

/* ---------- Testimonials ---------- */
.testimonials{padding:120px 0;background:var(--bg-mint)}
.tm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.tm-card{
  background:var(--white);border-radius:var(--radius);padding:34px 30px;
  margin:0;border:1px solid var(--g-100);position:relative;display:flex;flex-direction:column;gap:18px;
  transition:all .3s var(--ease);
}
.tm-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--g-300)}
.tm-card.featured{background:var(--gray-900);color:var(--white);border-color:var(--gray-900)}
.tm-card.featured h3,.tm-card.featured p{color:var(--white)}
.tm-card.featured footer{border-color:rgba(255,255,255,.1)}
.tm-card.featured footer strong{color:var(--white)}
.tm-card.featured footer span{color:rgba(255,255,255,.65)}
.tm-badge{
  display:inline-flex;align-items:center;gap:6px;
  background:var(--g-700);color:var(--g-300);padding:4px 10px;border-radius:6px;
  font-size:.66rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;font-family:'Space Grotesk',sans-serif;
  align-self:flex-start;
}
.tm-card p{font-size:1rem;line-height:1.55;color:var(--gray-900);margin:0;font-weight:500}
.tm-card footer{display:flex;align-items:center;gap:12px;margin-top:auto;border-top:1px solid var(--line);padding-top:18px}
.avatar{
  width:44px;height:44px;border-radius:50%;
  background:var(--brand);
  display:grid;place-items:center;color:var(--white);font-weight:700;font-size:.86rem;font-family:'Space Grotesk',sans-serif;
}
.tm-card.featured .avatar{background:var(--g-500)}
.tm-card footer strong{display:block;font-size:.9rem;color:var(--gray-900);font-weight:700}
.tm-card footer span{font-size:.74rem;color:var(--muted)}

/* ---------- Dealer ---------- */
.dealer{padding:120px 0;background:var(--white);position:relative;overflow:hidden}
.dealer::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 85% 15%,rgba(46,158,126,.06),transparent 50%);
  pointer-events:none;
}
.dealer-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;position:relative}
.dealer p{color:var(--gray-600);margin:18px 0 30px;max-width:480px;line-height:1.7}
.dealer-points{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.dealer-points li{
  background:var(--bg-mint);padding:24px 20px;border-radius:12px;border:1px solid var(--g-100);
}
.dealer-points strong{display:block;font-family:'Space Grotesk',sans-serif;font-size:2rem;color:var(--brand);line-height:1;letter-spacing:-.02em;font-weight:700}
.dealer-points span{font-size:.74rem;letter-spacing:.06em;color:var(--muted);margin-top:8px;display:block;font-weight:500}

.dealer-form{
  background:var(--bg-mint);color:var(--gray-900);
  padding:40px 36px;border-radius:var(--radius);border:1px solid var(--g-100);
}
.dealer-form h3{font-size:1.3rem;margin-bottom:22px;font-weight:700}
.dealer-form label{display:block;font-size:.74rem;font-weight:700;color:var(--gray-900);margin-bottom:14px;letter-spacing:.08em;text-transform:uppercase}
.dealer-form input,.dealer-form textarea,.dealer-form select{
  width:100%;padding:12px 14px;margin-top:8px;
  border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.9rem;background:var(--white);
  transition:border-color .25s var(--ease);
  color:var(--gray-900);text-transform:none;letter-spacing:0;font-weight:400;
}
.dealer-form input:focus,.dealer-form textarea:focus,.dealer-form select:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(46,158,126,.15)}
.form-note{display:block;margin-top:12px;font-size:.74rem;color:var(--muted);text-align:center}
.form-note i{color:var(--brand);margin-right:6px}

/* ---------- Journal ---------- */
.news{padding:120px 0;background:var(--bg-alt)}
.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.news-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
}
.news-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--g-300)}
.news-thumb{height:220px;background-size:cover;background-position:center;position:relative;display:grid;place-items:flex-start}
.thumb-tag{
  margin:16px;padding:5px 10px;background:var(--white);color:var(--brand);
  font-size:.62rem;font-weight:700;letter-spacing:.18em;border-radius:4px;
  font-family:'Space Grotesk',sans-serif;box-shadow:var(--shadow-sm);
}
.thumb-1{background:linear-gradient(135deg,#E8EDE9,#A3CBB5)}
.thumb-2{background:linear-gradient(135deg,#D8E4DD,#5FAF8B)}
.thumb-3{background:linear-gradient(135deg,#E0E4E2,#6B7571)}
.news-body{padding:24px 26px 28px}
.news-meta{font-size:.7rem;color:var(--muted);font-weight:600;letter-spacing:.02em;display:inline-block;margin-bottom:10px;font-family:'Space Grotesk',sans-serif}
.news-card h3{font-size:1.15rem;font-weight:700;margin:0 0 10px;line-height:1.35}
.news-card p{color:var(--muted);font-size:.88rem;margin:0 0 16px;line-height:1.6}

/* ---------- Newsletter ---------- */
.newsletter{background:var(--bg-mint);padding:80px 0;border-top:1px solid var(--g-100);border-bottom:1px solid var(--g-100)}
.news-inner{display:flex;justify-content:space-between;align-items:center;gap:40px;flex-wrap:wrap}
.news-inner h3{font-size:1.8rem;font-weight:700;letter-spacing:-.02em}
.news-inner p{color:var(--gray-600);margin:6px 0 0;max-width:440px;font-size:.94rem}
.news-inner form{display:flex;gap:10px;flex:1;max-width:480px}
.news-inner input{
  flex:1;padding:14px 18px;border-radius:10px;border:1px solid var(--g-200);
  background:var(--white);font-family:inherit;font-size:.9rem;color:var(--gray-900);
}
.news-inner input:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(46,158,126,.15)}

/* ---------- Footer ---------- */
.site-footer{background:var(--gray-900);color:rgba(255,255,255,.7);padding:80px 0 0}
.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1.2fr;gap:40px}
.logo-light{color:var(--g-300)}
.logo-light .logo-text strong{color:var(--white)}
.logo-light .logo-text em{color:var(--g-300)}
.footer-about{font-size:.86rem;line-height:1.75;margin:22px 0;color:rgba(255,255,255,.6)}
.footer-contact{list-style:none;padding:0;margin:0 0 22px}
.footer-contact li{padding:5px 0;font-size:.86rem}
.footer-contact i{color:var(--g-400);width:20px}
.footer-contact a:hover{color:var(--g-300)}
.footer-app{font-size:.82rem;color:rgba(255,255,255,.55);margin:0 0 14px;line-height:1.6}
.site-footer h4{color:var(--white);font-size:.76rem;letter-spacing:.2em;margin-bottom:20px}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer ul li{padding:5px 0;font-size:.86rem}
.site-footer ul a{transition:color .2s var(--ease)}
.site-footer ul a:hover{color:var(--g-300)}
.socials{display:flex;gap:8px}
.socials a{
  width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.08);display:grid;place-items:center;
  color:var(--white);font-size:.88rem;transition:all .25s var(--ease);
}
.socials a:hover{background:var(--brand);border-color:var(--brand)}

.pay-row{display:flex;gap:6px;flex-wrap:wrap}
.pay{
  background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.85);
  padding:4px 10px;border-radius:6px;font-size:.66rem;letter-spacing:.14em;font-weight:700;font-family:'Space Grotesk',sans-serif;
}

.copyright{margin-top:70px;border-top:1px solid rgba(255,255,255,.06);padding:22px 0;font-size:.76rem}
.copyright-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
.copyright .legal{display:flex;gap:22px}
.copyright .legal a{color:rgba(255,255,255,.5)}
.copyright .legal a:hover{color:var(--g-300)}

/* ---------- Floating ---------- */
.floating{position:fixed;right:20px;bottom:24px;display:flex;flex-direction:column;gap:10px;z-index:60}
.fab{
  width:52px;height:52px;border-radius:50%;display:grid;place-items:center;
  color:var(--white);box-shadow:var(--shadow);position:relative;
  transition:all .25s var(--ease);
}
.fab:hover{transform:translateY(-3px)}
.fab-call{background:var(--brand);animation:pulseG 2.2s infinite}
.tip{
  position:absolute;right:60px;background:var(--gray-900);color:var(--white);
  padding:5px 12px;border-radius:999px;font-size:.72rem;white-space:nowrap;
  opacity:0;transform:translateX(8px);transition:all .25s var(--ease);pointer-events:none;font-weight:600;
}
.fab:hover .tip{opacity:1;transform:translateX(0)}
.fab-zalo{background:#0084ff}
.fab-label{font-weight:800;font-size:.68rem;letter-spacing:.02em}
.fab-fb{background:#0078ff}
.fab-top{background:var(--gray-900);opacity:0;pointer-events:none;transform:translateY(12px);transition:all .25s var(--ease)}
.fab-top.show{opacity:1;pointer-events:auto;transform:none}
@keyframes pulseG{
  0%{box-shadow:0 0 0 0 rgba(46,158,126,.55)}
  70%{box-shadow:0 0 0 18px rgba(46,158,126,0)}
  100%{box-shadow:0 0 0 0 rgba(46,158,126,0)}
}

/* ---------- Reveal ---------- */
.reveal{opacity:0;transform:translateY(24px);transition:opacity .8s var(--ease),transform .8s var(--ease)}
.reveal.in{opacity:1;transform:none}

/* ---------- Responsive ---------- */
@media (max-width: 1200px){
  .product-grid,.cat-grid,.values-grid,.ritual-steps,.sci-grid,.finder-cards{grid-template-columns:repeat(2,1fr)}
  .ritual-steps::before{display:none}
  .certstrip ul{grid-template-columns:repeat(3,1fr)}
  .footer-grid{grid-template-columns:1fr 1fr 1fr;gap:40px}
  .footer-grid > *:nth-child(1){grid-column:1/-1}
}
@media (max-width: 1080px){
  .main-nav{display:none}
  .burger{display:inline-block}
  .header-inner{grid-template-columns:auto 1fr auto;gap:12px}
  .topbar-left{display:none}
  .topbar-right{gap:16px}
  .hero-grid,.story-grid,.auth-card,.dealer-grid,.ing-grid,.ba-grid,.finder-grid{grid-template-columns:1fr;gap:50px}
  .auth-card{padding:50px 30px}
  .hero-side{display:none}
  .story-visual,.ing-visual{max-width:480px;margin:0 auto}
  .badge-float{display:none}
  .hero-specs{grid-template-columns:repeat(3,1fr);gap:14px}
  .spec strong{font-size:1.5rem}
}
@media (max-width: 640px){
  .topbar-right a:not(.locale-btn):not(.locale-menu *){display:none}
  .topbar-right .locale{display:block}
  .topbar{padding:6px 0}
  .announce-track{font-size:.66rem;gap:40px}
  .hero{padding:50px 0 70px;min-height:auto}
  .hero-specs{grid-template-columns:1fr 1fr}
  .product-grid,.cat-grid,.news-grid,.tm-grid,.values-grid,.ritual-steps,.sci-grid,.finder-cards{grid-template-columns:1fr}
  .certstrip ul{grid-template-columns:1fr 1fr}
  .ing-list{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .section-head.between{flex-direction:column;align-items:flex-start}
  .dealer-points{grid-template-columns:1fr}
  .auth-card{padding:40px 24px}
  .copyright-inner{flex-direction:column;text-align:center}
  .container{padding:0 20px}
  .logo-text em{display:none}
}

toolUseResult.content:
/* =========================================================
   DETOXBLANC — Dermatological Skincare
   Clinical tone: Green · Gray · White
   Type: Manrope (body) + Space Grotesk (display/numbers)
   ========================================================= */

:root{
  /* greens */
  --g-50:       #F2F8F5;
  --g-100:      #E2EFE8;
  --g-200:      #C8DFD2;
  --g-300:      #A3CBB5;
  --g-400:      #5FAF8B;
  --g-500:      #2E9E7E;
  --g-600:      #1E6F5C;
  --g-700:      #14503F;
  --g-800:      #0E3A2C;
  --g-900:      #0B2A20;

  /* grays */
  --white:      #FFFFFF;
  --gray-50:    #F7F9F8;
  --gray-100:   #EEF1EF;
  --gray-200:   #E0E4E2;
  --gray-300:   #C9CFCC;
  --gray-400:   #9AA29D;
  --gray-500:   #6B7571;
  --gray-600:   #4B5551;
  --gray-700:   #3B4441;
  --gray-800:   #262D2A;
  --gray-900:   #1A1F1D;

  /* semantic */
  --brand:      var(--g-600);
  --brand-soft: var(--g-100);
  --accent:     var(--g-500);
  --ink:        var(--gray-800);
  --muted:      var(--gray-500);
  --line:       var(--gray-200);
  --line-soft:  var(--gray-100);
  --bg:         var(--white);
  --bg-alt:     var(--gray-50);
  --bg-mint:    var(--g-50);
  --dark:       var(--gray-900);

  --radius:     14px;
  --radius-sm:  8px;
  --shadow-xs:  0 1px 2px rgba(20,31,29,.04);
  --shadow-sm:  0 2px 10px rgba(20,31,29,.05);
  --shadow:     0 10px 30px rgba(20,31,29,.07);
  --shadow-lg:  0 24px 60px rgba(20,31,29,.12);
  --ease:       cubic-bezier(.2,.7,.2,1);
  --container:  1280px;
}

*,*::before,*::after{box-sizing:border-box}
html,body{margin:0;padding:0}
html{scroll-behavior:smooth}
body{
  font-family:'Manrope', system-ui, -apple-system, sans-serif;
  color:var(--ink);
  background:var(--bg);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  overflow-x:hidden;
}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
button{font-family:inherit;cursor:pointer;border:0;background:transparent}

.container{max-width:var(--container);margin:0 auto;padding:0 32px}
.center{text-align:center}
.mt-24{margin-top:24px}
.mt-40{margin-top:40px}
sup{font-size:.55em;vertical-align:super;font-weight:500;color:var(--brand)}

/* ---------- Typography ---------- */
h1,h2,h3,h4,h5{color:var(--gray-900);margin:0;letter-spacing:-.015em;font-family:'Manrope',sans-serif;font-weight:700}
h1{font-size:clamp(2.6rem,5.2vw,4.6rem);line-height:1.04;letter-spacing:-.03em;font-weight:700}
h2{font-size:clamp(2rem,3.4vw,3rem);line-height:1.12;letter-spacing:-.02em;font-weight:700}
h3{font-size:1.2rem;line-height:1.3;font-weight:700;letter-spacing:-.01em}
h4{font-size:.78rem;color:var(--gray-900);letter-spacing:.2em;text-transform:uppercase;font-weight:700}
h5{font-size:.72rem;color:var(--gray-900);letter-spacing:.22em;text-transform:uppercase;font-weight:700}

.hl{color:var(--brand);font-weight:700;position:relative}
.hl::after{
  content:"";position:absolute;left:0;right:0;bottom:-2px;height:3px;
  background:var(--g-200);border-radius:2px;z-index:-1;opacity:.7;
}
em{font-style:normal;color:var(--brand);font-weight:700}

.eyebrow{
  font-family:'Space Grotesk',sans-serif;
  font-size:.72rem;font-weight:600;
  letter-spacing:.24em;color:var(--brand);
  text-transform:uppercase;display:inline-flex;align-items:center;gap:10px;margin-bottom:18px;
}
.eyebrow::before{content:"";width:24px;height:1px;background:var(--brand)}
.eyebrow.light{color:var(--g-300)}
.eyebrow.light::before{background:var(--g-300)}
.center-eyebrow{display:inline-flex;text-align:center}

.section-head{margin-bottom:64px}
.section-head.center{text-align:center;max-width:720px;margin-inline:auto}
.section-head.center .eyebrow{display:inline-flex;margin-bottom:16px}
.section-head.between{
  display:flex;justify-content:space-between;align-items:flex-end;
  text-align:left;flex-wrap:wrap;gap:24px;
}
.section-sub{color:var(--muted);margin-top:18px;font-size:1rem;line-height:1.7}

/* ---------- Buttons ---------- */
.btn{
  display:inline-flex;align-items:center;gap:10px;
  padding:14px 26px;border-radius:10px;border:1px solid transparent;
  font-weight:700;font-size:.84rem;letter-spacing:.04em;
  transition:all .25s var(--ease);font-family:'Manrope',sans-serif;
}
.btn i{font-size:.9em;letter-spacing:0}
.btn-primary{background:var(--brand);color:var(--white);box-shadow:0 4px 14px rgba(30,111,92,.25)}
.btn-primary:hover{background:var(--g-700);transform:translateY(-2px);box-shadow:0 8px 22px rgba(30,111,92,.3)}
.btn-dark{background:var(--gray-900);color:var(--white);padding:12px 18px;font-size:.78rem;border-radius:8px}
.btn-dark:hover{background:var(--brand)}
.btn-outline{background:transparent;border-color:var(--gray-300);color:var(--gray-900)}
.btn-outline:hover{border-color:var(--brand);color:var(--brand);background:var(--g-50)}
.btn-ghost{background:transparent;color:var(--gray-900);border:1px solid var(--line)}
.btn-ghost:hover{border-color:var(--brand)}
.btn-block{display:flex;width:100%;justify-content:center}

.link-arrow{
  display:inline-flex;align-items:center;gap:8px;
  font-weight:600;font-size:.82rem;color:var(--gray-900);
  border-bottom:1.5px solid var(--gray-900);padding-bottom:3px;
  transition:all .25s var(--ease);
}
.link-arrow:hover{color:var(--brand);border-color:var(--brand);gap:14px}
.link-arrow.sm{font-size:.76rem}

/* ---------- Announcement ---------- */
.announce{background:var(--gray-900);color:var(--white);overflow:hidden}
.announce-track{
  display:flex;gap:56px;white-space:nowrap;padding:10px 0;
  animation:marquee 45s linear infinite;
  font-size:.74rem;font-weight:500;letter-spacing:.02em;
}
.announce-track i{color:var(--g-400);margin-right:6px}
.announce-track span{position:relative;display:inline-flex;align-items:center}
.announce-track span::after{
  content:"";position:absolute;right:-28px;top:50%;transform:translateY(-50%);
  width:4px;height:4px;background:var(--g-500);border-radius:50%;
}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* ---------- Topbar ---------- */
.topbar{background:var(--white);color:var(--ink);font-size:.78rem;padding:9px 0;border-bottom:1px solid var(--line)}
.topbar-inner{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap}
.topbar-left,.topbar-right{display:flex;gap:26px;align-items:center;flex-wrap:wrap}
.topbar i{color:var(--brand);margin-right:6px}
.topbar-right a:hover{color:var(--brand)}
.locale{position:relative}
.locale-btn{display:inline-flex;align-items:center;gap:6px;font-size:.78rem;color:var(--ink);font-family:inherit}
.locale-btn .flag{font-size:1rem}
.locale-btn i{font-size:.7em;color:var(--muted);margin:0}
.locale-menu{
  position:absolute;top:calc(100% + 10px);right:0;min-width:200px;
  background:var(--white);border:1px solid var(--line);border-radius:12px;
  padding:6px;box-shadow:var(--shadow);
  opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .25s var(--ease);z-index:60;
}
.locale:hover .locale-menu{opacity:1;visibility:visible;transform:translateY(0)}
.locale-menu a{display:flex;align-items:center;gap:10px;padding:9px 12px;border-radius:8px;font-size:.82rem}
.locale-menu a:hover{background:var(--g-50)}

/* ---------- Header ---------- */
.site-header{
  position:sticky;top:0;z-index:50;background:rgba(255,255,255,.96);
  backdrop-filter:blur(16px);border-bottom:1px solid var(--line);
  transition:all .3s var(--ease);
}
.site-header.scrolled{box-shadow:0 2px 12px rgba(20,31,29,.05)}
.header-inner{
  display:grid;grid-template-columns:auto 1fr auto;
  align-items:center;gap:24px;padding:16px 32px;
}
.logo{display:flex;align-items:center;gap:12px;color:var(--brand)}
.logo-mark{
  width:42px;height:42px;display:grid;place-items:center;
}
.logo-mark svg{width:100%;height:100%}
.logo-text{display:flex;flex-direction:column;line-height:1}
.logo-text strong{font-family:'Space Grotesk',sans-serif;font-size:1.35rem;font-weight:700;letter-spacing:.12em;color:var(--gray-900)}
.logo-text em{font-family:'Manrope',sans-serif;font-size:.62rem;letter-spacing:.24em;color:var(--brand);margin-top:4px;text-transform:uppercase;font-style:normal;font-weight:600}

.main-nav{display:flex;justify-content:center;gap:6px}
.main-nav > a,.nav-item > a{
  font-size:.82rem;font-weight:600;letter-spacing:.02em;
  color:var(--gray-700);padding:10px 14px;position:relative;display:inline-flex;align-items:center;gap:6px;
  transition:color .25s var(--ease);border-radius:8px;
}
.main-nav > a:hover,.nav-item:hover > a{color:var(--brand);background:var(--g-50)}
.main-nav > a.active{color:var(--brand)}
.main-nav > a.active::after{
  content:"";position:absolute;left:50%;right:0;bottom:2px;height:2px;
  width:20px;margin-left:-10px;background:var(--brand);border-radius:2px;
}
.nav-item{position:static}
.nav-item > a i{font-size:.6rem;opacity:.6}

/* Mega-menu */
.mega{
  position:absolute;left:0;right:0;top:100%;background:var(--white);
  border-top:1px solid var(--line);box-shadow:var(--shadow-lg);
  padding:40px 32px;opacity:0;visibility:hidden;transform:translateY(-6px);
  transition:all .3s var(--ease);z-index:40;
}
.nav-item:hover .mega{opacity:1;visibility:visible;transform:translateY(0)}
.mega-grid{max-width:var(--container);margin:0 auto;display:grid;grid-template-columns:repeat(3,1fr) 1.3fr;gap:50px}
.mega h5{margin-bottom:18px;color:var(--brand)}
.mega ul{list-style:none;padding:0;margin:0}
.mega ul li{padding:7px 0}
.mega ul a{font-size:.86rem;color:var(--gray-700);transition:color .2s var(--ease);display:inline-flex;align-items:center;gap:10px}
.mega ul a i{color:var(--g-400);font-size:.82rem;width:14px}
.mega ul a:hover{color:var(--brand)}
.mega-feature{
  background:var(--bg-mint);
  border-radius:var(--radius);padding:22px;
  display:grid;grid-template-columns:auto 1fr;gap:18px;align-items:center;position:relative;
  transition:all .3s var(--ease);border:1px solid var(--g-100);
}
.mega-feature:hover{transform:translateY(-3px);box-shadow:var(--shadow);border-color:var(--g-300)}
.mega-feature .tag-green{
  position:absolute;top:12px;right:12px;font-size:.58rem;font-weight:700;letter-spacing:.22em;
  color:var(--white);background:var(--brand);padding:4px 8px;border-radius:4px;
}
.mega-visual{width:70px}
.mega-visual .mini{width:100%;height:auto}
.mega-feature strong{display:block;font-size:1rem;color:var(--gray-900);font-weight:700;margin-bottom:2px}
.mega-feature span{font-size:.76rem;color:var(--muted);display:block;font-family:'Space Grotesk',sans-serif}

.header-actions{display:flex;align-items:center;gap:4px}
.icon-btn{
  width:40px;height:40px;border-radius:10px;
  color:var(--gray-900);position:relative;
  transition:all .25s var(--ease);
}
.icon-btn:hover{background:var(--g-50);color:var(--brand)}
.badge{
  position:absolute;top:4px;right:4px;background:var(--brand);color:var(--white);
  font-size:.6rem;font-weight:700;min-width:17px;height:17px;border-radius:50%;
  display:grid;place-items:center;padding:0 4px;font-family:'Space Grotesk',sans-serif;
}
.burger{display:none;font-size:1.3rem;color:var(--gray-900)}

/* ---------- HERO ---------- */
.hero{
  position:relative;overflow:hidden;background:var(--bg-mint);
  padding:80px 0 100px;min-height:88vh;
}
.hero-bg{position:absolute;inset:0;z-index:0;pointer-events:none}
.bg-blob{position:absolute;border-radius:50%;filter:blur(90px);opacity:.5}
.b1{width:640px;height:640px;background:var(--g-200);top:-180px;right:-180px}
.b2{width:520px;height:520px;background:var(--g-100);bottom:-180px;left:-120px}
.bg-grid{
  position:absolute;inset:0;opacity:.25;
  background-image:
    linear-gradient(var(--g-100) 1px, transparent 1px),
    linear-gradient(90deg, var(--g-100) 1px, transparent 1px);
  background-size:44px 44px;mask-image:radial-gradient(ellipse at center, #000 30%, transparent 75%);
}

.hero-side{
  position:absolute;left:24px;top:50%;transform:translateY(-50%) rotate(-90deg);transform-origin:left center;
  display:flex;gap:14px;font-size:.68rem;letter-spacing:.3em;color:var(--muted);text-transform:uppercase;z-index:2;
  font-family:'Space Grotesk',sans-serif;font-weight:600;
}
.hero-side .dot{color:var(--brand);font-size:.45rem}

.hero-grid{display:grid;grid-template-columns:1.15fr 1fr;gap:50px;align-items:center;position:relative;z-index:2}

.hero-pill{
  display:inline-flex;align-items:center;gap:10px;
  padding:8px 16px;background:var(--white);border:1px solid var(--g-200);border-radius:999px;
  color:var(--brand);font-size:.76rem;font-weight:600;margin-bottom:24px;
}
.pill-dot{
  width:8px;height:8px;border-radius:50%;background:var(--g-500);
  box-shadow:0 0 0 4px rgba(46,158,126,.2);
  animation:pulse-dot 2s ease-in-out infinite;
}
@keyframes pulse-dot{50%{box-shadow:0 0 0 8px rgba(46,158,126,0)}}

.h1-accent{color:var(--brand);font-weight:700}
.lead{font-size:1.05rem;color:var(--gray-600);max-width:560px;margin:24px 0 32px;line-height:1.7}
.lead strong{color:var(--gray-900);font-weight:700}
.hero-ctas{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:48px}

.hero-specs{
  display:grid;grid-template-columns:repeat(3,1fr);gap:28px;
  padding-top:24px;border-top:1px solid var(--line);max-width:600px;
}
.spec strong{
  font-family:'Space Grotesk',sans-serif;font-size:2rem;font-weight:700;
  color:var(--gray-900);display:block;line-height:1;letter-spacing:-.02em;
}
.spec strong em{font-size:.6em;color:var(--muted);font-style:normal;font-weight:500;margin-left:2px}
.spec span{font-size:.76rem;color:var(--muted);line-height:1.45;margin-top:8px;display:block}
.hero-disclaim{font-size:.7rem;color:var(--gray-400);margin-top:14px}

/* Hero visual */
.hero-visual{position:relative;display:grid;place-items:center;min-height:560px}
.hero-frame{
  position:relative;width:100%;max-width:460px;aspect-ratio:3/4;
  border-radius:var(--radius);background:
    radial-gradient(circle at 30% 30%, var(--white), var(--g-50)),
    var(--g-100);
  border:1px solid var(--g-200);
  box-shadow:var(--shadow-lg);
}
.hero-frame::before{
  content:"";position:absolute;inset:0;border-radius:var(--radius);
  background:
    radial-gradient(circle at 20% 10%, rgba(46,158,126,.08), transparent 50%),
    radial-gradient(circle at 80% 90%, rgba(46,158,126,.06), transparent 50%);
}
.bottle-hero{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-52%);width:68%;
  filter:drop-shadow(0 30px 30px rgba(20,31,29,.15));
}

.badge-float{
  position:absolute;background:var(--white);border:1px solid var(--line);border-radius:12px;
  padding:10px 14px;box-shadow:var(--shadow);display:flex;align-items:center;gap:10px;
}
.badge-float strong{display:block;font-size:.88rem;color:var(--gray-900);font-weight:700;font-family:'Space Grotesk',sans-serif}
.badge-float span{font-size:.68rem;color:var(--muted);display:block}
.badge-float i{color:var(--brand);font-size:1.3rem}
.bf-1{top:18%;left:-8%}
.bf-2{top:50%;right:-10%}

.price-tag{
  position:absolute;bottom:18px;left:18px;right:18px;
  background:var(--white);border:1px solid var(--line);border-radius:12px;
  padding:14px 18px;display:flex;align-items:center;gap:14px;justify-content:space-between;
  box-shadow:var(--shadow);
}
.price-tag .small{font-size:.62rem;letter-spacing:.2em;color:var(--brand);text-transform:uppercase;font-weight:700;display:block;font-family:'Space Grotesk',sans-serif}
.price-tag strong{font-family:'Space Grotesk',sans-serif;font-size:1.3rem;color:var(--gray-900);display:block;margin-top:3px;font-weight:700}
.price-tag a{
  font-size:.76rem;font-weight:700;color:var(--white);
  background:var(--gray-900);padding:10px 16px;border-radius:8px;
  transition:background .25s var(--ease);
}
.price-tag a:hover{background:var(--brand)}
.price-tag a i{margin-right:6px}

.hero-scroll{
  position:absolute;bottom:30px;left:50%;transform:translateX(-50%);
  display:flex;flex-direction:column;align-items:center;gap:6px;
  font-size:.66rem;letter-spacing:.28em;color:var(--muted);text-transform:uppercase;z-index:3;
  animation:bob 2.2s ease-in-out infinite;font-family:'Space Grotesk',sans-serif;font-weight:600;
}
.hero-scroll i{color:var(--brand)}
@keyframes bob{0%,100%{transform:translateX(-50%) translateY(0)}50%{transform:translateX(-50%) translateY(6px)}}

/* ---------- Certification strip ---------- */
.certstrip{background:var(--white);padding:36px 0;border-bottom:1px solid var(--line)}
.certstrip ul{
  list-style:none;padding:0;margin:0;display:grid;
  grid-template-columns:repeat(6,1fr);gap:24px;
}
.certstrip li{display:flex;align-items:center;gap:12px}
.certstrip i{
  width:44px;height:44px;border-radius:10px;background:var(--g-50);color:var(--brand);
  display:grid;place-items:center;font-size:1.1rem;flex-shrink:0;
}
.certstrip span{display:flex;flex-direction:column;font-size:.82rem;font-weight:700;color:var(--gray-900);line-height:1.3}
.certstrip small{font-size:.68rem;color:var(--muted);font-weight:500;margin-top:2px;letter-spacing:.01em}

/* ---------- Statement ---------- */
.statement{padding:120px 0;background:var(--bg-mint);text-align:center}
.statement-head{
  font-family:'Manrope',sans-serif;font-size:clamp(1.6rem,2.8vw,2.6rem);
  max-width:960px;margin:0 auto;line-height:1.4;color:var(--gray-900);font-weight:500;
  letter-spacing:-.015em;
}
.statement-head .hl::after{background:var(--g-200)}
.statement-sign{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:36px;color:var(--muted);font-size:.8rem;font-weight:500}
.sig-line{width:36px;height:1px;background:var(--brand)}

/* ---------- Skin Finder ---------- */
.finder{padding:120px 0;background:var(--white)}
.finder-grid{display:grid;grid-template-columns:1fr 1.2fr;gap:60px;align-items:center}
.finder-copy .lead{margin:18px 0 28px}
.finder-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.finder-card{
  background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);
  padding:26px 16px;display:flex;flex-direction:column;align-items:center;gap:12px;
  color:var(--gray-900);font-weight:600;font-size:.9rem;
  transition:all .3s var(--ease);cursor:pointer;font-family:inherit;
}
.finder-card:hover{background:var(--brand);color:var(--white);transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--brand)}
.finder-card i{font-size:1.8rem;color:var(--brand);transition:color .3s var(--ease)}
.finder-card:hover i{color:var(--white)}

/* ---------- Categories ---------- */
.categories{padding:120px 0;background:var(--bg-alt)}
.cat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.cat-card{
  background:var(--white);border-radius:var(--radius);overflow:hidden;
  transition:all .35s var(--ease);display:flex;flex-direction:column;
  border:1px solid var(--line);
}
.cat-card:hover{transform:translateY(-6px);border-color:var(--brand);box-shadow:var(--shadow)}
.cat-visual{
  aspect-ratio:4/3;position:relative;display:grid;place-items:center;
  background:var(--bg-mint);color:var(--g-300);font-size:3.4rem;
}
.cat-visual::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 30% 30%,rgba(255,255,255,.8),transparent 60%);
}
.cat-card:hover .cat-visual{background:var(--g-100);color:var(--brand)}
.cat-n{
  position:absolute;top:18px;left:18px;font-family:'Space Grotesk',sans-serif;font-size:.82rem;letter-spacing:.2em;
  color:var(--brand);font-weight:700;
}
.cat-visual i{position:relative;z-index:1;transition:transform .4s var(--ease)}
.cat-card:hover .cat-visual i{transform:scale(1.1)}
.cat-body{padding:24px 24px 26px}
.cat-body h3{font-size:1.3rem;margin-bottom:6px}
.cat-body p{color:var(--muted);font-size:.88rem;margin:0 0 14px;line-height:1.55}
.cat-cta{
  font-size:.76rem;font-weight:700;color:var(--brand);letter-spacing:.04em;
  display:inline-flex;align-items:center;gap:6px;
  transition:gap .25s var(--ease);
}
.cat-card:hover .cat-cta{gap:12px}

/* ---------- Products ---------- */
.products{padding:120px 0;background:var(--white)}
.product-tabs{display:flex;gap:6px;flex-wrap:wrap;background:var(--bg-alt);padding:4px;border-radius:12px}
.tab{
  padding:10px 16px;border-radius:8px;
  background:transparent;font-size:.78rem;font-weight:600;color:var(--gray-600);letter-spacing:.01em;
  transition:all .25s var(--ease);font-family:inherit;
}
.tab:hover{color:var(--gray-900)}
.tab.active{background:var(--white);color:var(--brand);box-shadow:var(--shadow-sm)}

.product-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}
.product-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);display:flex;flex-direction:column;
}
.product-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--g-300)}
.product-media{
  position:relative;padding:36px 20px 24px;display:grid;place-items:center;min-height:320px;
  background:var(--bg-mint);
}
.bottle-svg{width:130px;height:auto;filter:drop-shadow(0 14px 18px rgba(20,31,29,.1))}

.tag{
  position:absolute;top:14px;left:14px;font-size:.6rem;font-weight:700;
  letter-spacing:.22em;padding:5px 10px;border-radius:4px;color:var(--white);text-transform:uppercase;font-family:'Space Grotesk',sans-serif;
}
.tag-sale{background:var(--gray-900)}
.tag-hot{background:#B9503E}
.tag-new{background:var(--brand)}
.tag-green{background:var(--brand)}

.wish{
  position:absolute;top:10px;right:10px;width:34px;height:34px;border-radius:50%;background:var(--white);color:var(--gray-900);
  border:1px solid var(--line);transition:all .25s var(--ease);display:grid;place-items:center;font-size:.86rem;
}
.wish:hover{background:var(--brand);color:var(--white);border-color:var(--brand)}

.quick{
  position:absolute;bottom:16px;left:50%;transform:translate(-50%,8px);
  opacity:0;background:var(--gray-900);color:var(--white);
  padding:9px 18px;border-radius:999px;font-size:.68rem;font-weight:700;letter-spacing:.2em;text-transform:uppercase;
  transition:all .3s var(--ease);
}
.product-card:hover .quick{opacity:1;transform:translate(-50%,0)}

.active-ingr{
  position:absolute;bottom:12px;right:12px;
  background:var(--white);border:1px solid var(--line);border-radius:999px;
  padding:5px 12px;font-size:.66rem;font-weight:700;color:var(--brand);letter-spacing:.04em;
  font-family:'Space Grotesk',sans-serif;
}

.product-body{padding:22px 22px 26px;display:flex;flex-direction:column;gap:10px;flex:1}
.product-body .cat{font-size:.68rem;letter-spacing:.16em;color:var(--brand);font-weight:700;text-transform:uppercase;display:inline-flex;align-items:center;gap:6px;font-family:'Space Grotesk',sans-serif}
.product-body .cat i{font-size:.72rem}
.product-body h3{font-size:1rem;font-weight:700;color:var(--gray-900);line-height:1.35;min-height:44px;letter-spacing:-.005em}
.spec-bullets{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:4px}
.spec-bullets li{font-size:.78rem;color:var(--gray-600);display:flex;align-items:center;gap:8px;line-height:1.4}
.spec-bullets i{color:var(--brand);font-size:.68rem}
.stars{color:#E4A93C;font-size:.78rem;display:flex;align-items:center;gap:2px}
.stars small{color:var(--muted);margin-left:6px;font-size:.72rem;font-weight:500}
.price-row{display:flex;align-items:baseline;gap:10px;margin-top:auto}
.price{font-family:'Space Grotesk',sans-serif;font-size:1.25rem;font-weight:700;color:var(--gray-900);letter-spacing:-.01em}
.price-old{font-size:.82rem;color:var(--muted);text-decoration:line-through}

/* ---------- Ingredient ---------- */
.ingredient{padding:120px 0;background:var(--bg-mint)}
.ing-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:80px;align-items:center}
.ing-visual{position:relative;aspect-ratio:1/1;display:grid;place-items:center}
.molecule{width:90%;height:90%;display:grid;place-items:center;animation:moleculeRotate 40s linear infinite}
.molecule svg{width:100%;height:100%;filter:drop-shadow(0 20px 40px rgba(30,111,92,.15))}
@keyframes moleculeRotate{to{transform:rotate(360deg)}}
.ing-callout{
  position:absolute;right:2%;bottom:4%;background:var(--gray-900);color:var(--white);
  padding:16px 22px;border-radius:12px;box-shadow:var(--shadow-lg);
}
.ing-callout strong{display:block;font-family:'Space Grotesk',sans-serif;font-size:1.1rem;color:var(--g-300);font-weight:700}
.ing-callout span{font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;color:rgba(255,255,255,.7);font-weight:500}

.ing-lede{color:var(--gray-600);font-size:1.02rem;margin:18px 0 36px;max-width:540px;line-height:1.7}
.ing-list{display:grid;grid-template-columns:1fr 1fr;gap:28px 40px;margin-bottom:32px}
.ing-item{display:flex;gap:16px;align-items:flex-start}
.ing-num{
  font-family:'Space Grotesk',sans-serif;font-size:.86rem;color:var(--brand);font-weight:700;
  letter-spacing:.1em;padding:6px 10px;min-width:36px;background:var(--white);border-radius:8px;
  text-align:center;border:1px solid var(--g-100);
}
.ing-item strong{display:block;color:var(--gray-900);font-weight:700;margin-bottom:4px;font-size:.92rem}
.ing-item strong em{color:var(--brand);font-weight:700;font-family:'Space Grotesk',sans-serif;margin-left:4px}
.ing-item p{font-size:.82rem;color:var(--muted);margin:0;line-height:1.55}

/* ---------- Science ---------- */
.science{padding:120px 0;background:var(--white)}
.sci-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;margin-bottom:40px}
.sci-stat{
  background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);
  padding:36px 26px;text-align:center;position:relative;overflow:hidden;
  transition:all .35s var(--ease);
}
.sci-stat:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--g-300)}
.sci-stat::before{
  content:"";position:absolute;top:0;left:0;right:0;height:3px;background:var(--brand);
}
.sci-num{font-family:'Space Grotesk',sans-serif;font-size:4.4rem;color:var(--gray-900);line-height:1;letter-spacing:-.03em;font-weight:700}
.sci-pct{font-family:'Space Grotesk',sans-serif;font-size:1.8rem;color:var(--brand);margin-left:4px;vertical-align:top;font-weight:700}
.sci-stat p{margin:14px 0 0;font-size:.86rem;color:var(--muted);line-height:1.5}
.sci-stat p strong{color:var(--gray-900);font-weight:700}

.sci-note{
  text-align:center;font-size:.82rem;color:var(--muted);
  padding:16px 24px;background:var(--bg-mint);border-radius:10px;max-width:620px;margin:0 auto;
}
.sci-note i{color:var(--brand);margin-right:8px}
.sci-note strong{color:var(--gray-900)}

/* ---------- Ritual ---------- */
.ritual{padding:120px 0;background:var(--bg-alt)}
.ritual-steps{display:grid;grid-template-columns:repeat(4,1fr);gap:20px;position:relative}
.ritual-steps::before{
  content:"";position:absolute;top:100px;left:13%;right:13%;height:1px;
  background:repeating-linear-gradient(90deg,var(--g-300) 0 6px, transparent 6px 12px);
  z-index:0;
}
.ritual-step{
  background:var(--white);border-radius:var(--radius);padding:36px 26px;
  text-align:center;border:1px solid var(--line);transition:all .35s var(--ease);position:relative;z-index:1;
}
.ritual-step:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--brand)}
.step-num{
  font-family:'Space Grotesk',sans-serif;font-size:.84rem;color:var(--brand);font-weight:700;
  letter-spacing:.12em;display:inline-block;padding:4px 12px;background:var(--g-50);border-radius:20px;
}
.step-icon{
  width:72px;height:72px;border-radius:50%;
  background:var(--bg-mint);color:var(--brand);border:1px solid var(--g-200);
  display:grid;place-items:center;font-size:1.5rem;margin:18px auto 20px;
  transition:all .35s var(--ease);
}
.ritual-step:hover .step-icon{background:var(--brand);color:var(--white);border-color:var(--brand)}
.ritual-step h3{font-size:1.2rem;margin-bottom:8px}
.ritual-step p{color:var(--muted);font-size:.86rem;margin:0 0 18px;line-height:1.55}

/* ---------- Before / After ---------- */
.ba{padding:120px 0;background:var(--white)}
.ba-grid{display:grid;grid-template-columns:1fr 1.1fr;gap:70px;align-items:center}
.ba-points{list-style:none;padding:0;margin:18px 0 30px}
.ba-points li{padding:10px 0;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;font-size:.9rem;color:var(--gray-700)}
.ba-points i{color:var(--brand);background:var(--g-50);width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:.68rem}
.ba-slider{
  position:relative;aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;
  box-shadow:var(--shadow-lg);cursor:ew-resize;user-select:none;border:1px solid var(--line);
}
.ba-img{position:absolute;inset:0;background-size:cover;background-position:center}
.ba-before{
  background:
    radial-gradient(circle at 50% 55%,#e2b8a5 0%,#b78878 35%,#8c5f52 70%);
  clip-path:inset(0 50% 0 0);
}
.ba-before::after{
  content:"";position:absolute;inset:0;
  background:
    radial-gradient(circle at 42% 48%,rgba(90,50,35,.5) 2%, transparent 8%),
    radial-gradient(circle at 55% 52%,rgba(90,50,35,.5) 2%, transparent 7%),
    radial-gradient(circle at 48% 60%,rgba(90,50,35,.45) 2%, transparent 6%),
    radial-gradient(circle at 60% 45%,rgba(90,50,35,.4) 2%, transparent 5%),
    radial-gradient(circle at 40% 65%,rgba(90,50,35,.35) 2%, transparent 5%);
  mix-blend-mode:multiply;
}
.ba-after{
  background:radial-gradient(circle at 50% 55%,#fadcc8 0%,#e8bfa4 40%,#b38870 80%);
}
.ba-label{
  position:absolute;top:18px;padding:6px 14px;background:var(--white);
  font-size:.68rem;letter-spacing:.22em;text-transform:uppercase;font-weight:700;color:var(--gray-900);border-radius:999px;
  z-index:3;pointer-events:none;font-family:'Space Grotesk',sans-serif;box-shadow:var(--shadow-sm);
}
.ba-label-before{left:18px;background:var(--gray-900);color:var(--white)}
.ba-label-after{right:18px;background:var(--brand);color:var(--white)}
.ba-handle{
  position:absolute;top:0;bottom:0;left:50%;width:2px;background:var(--white);z-index:4;
  cursor:ew-resize;box-shadow:0 0 0 1px rgba(0,0,0,.1);
}
.ba-knob{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:46px;height:46px;border-radius:50%;background:var(--white);color:var(--brand);
  display:grid;grid-template-columns:1fr 1fr;place-items:center;gap:4px;padding:0 6px;
  box-shadow:0 6px 18px rgba(0,0,0,.2);font-size:.7rem;border:1px solid var(--line);
}

/* ---------- Story ---------- */
.story{padding:130px 0;background:var(--bg-mint)}
.story-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.story-visual{position:relative;display:grid;grid-template-columns:1.2fr 1fr;grid-template-rows:1fr 1fr;gap:16px;aspect-ratio:1/1.1}
.story-img{border-radius:var(--radius);overflow:hidden;background-size:cover;background-position:center;border:1px solid var(--g-100)}
.img-lab{grid-row:1/3;background:var(--white);position:relative}
.img-lab svg{width:100%;height:100%;object-fit:cover}
.img-leaf{
  background:
    radial-gradient(circle at 30% 30%,var(--g-200),var(--g-400) 70%);
  position:relative;
}
.img-leaf::before{
  content:"\f06c";font-family:"Font Awesome 6 Free";font-weight:900;
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  font-size:4rem;color:rgba(255,255,255,.8);
}
.img-drops{
  background:linear-gradient(135deg,var(--gray-100),var(--gray-300));
  position:relative;
}
.img-drops::before{
  content:"\f043";font-family:"Font Awesome 6 Free";font-weight:900;
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  font-size:3.6rem;color:var(--brand);
}
.story-badge{
  position:absolute;bottom:-28px;left:-28px;background:var(--gray-900);
  color:var(--white);padding:22px 26px;border-radius:var(--radius);
  display:flex;align-items:center;gap:14px;box-shadow:var(--shadow-lg);
}
.story-badge strong{font-family:'Space Grotesk',sans-serif;font-size:2.2rem;color:var(--g-300);line-height:1;letter-spacing:-.02em;font-weight:700}
.story-badge span{font-size:.72rem;line-height:1.45;color:rgba(255,255,255,.85)}

.story-copy p{color:var(--gray-600);margin:18px 0;line-height:1.8}
.story-copy p strong{color:var(--gray-900)}
.story-copy p em{color:var(--brand);font-style:normal}
.story-quote{
  margin:28px 0;padding:22px 26px;border-left:3px solid var(--brand);
  background:var(--white);border-radius:0 12px 12px 0;
  font-size:1.06rem;color:var(--gray-900);font-weight:500;line-height:1.55;
}

/* ---------- Values ---------- */
.values{padding:120px 0;background:var(--white)}
.values-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.value-card{
  padding:36px 26px;text-align:center;border-radius:var(--radius);
  background:var(--bg-mint);border:1px solid var(--g-100);transition:all .35s var(--ease);
}
.value-card:hover{transform:translateY(-4px);border-color:var(--brand);box-shadow:var(--shadow);background:var(--white)}
.value-icon{
  width:64px;height:64px;border-radius:14px;
  background:var(--white);color:var(--brand);border:1px solid var(--g-200);
  display:grid;place-items:center;font-size:1.4rem;margin:0 auto 20px;
  transition:all .35s var(--ease);
}
.value-card:hover .value-icon{background:var(--brand);color:var(--white);border-color:var(--brand)}
.value-card h3{font-size:1.1rem;margin-bottom:8px}
.value-card p{font-size:.86rem;color:var(--muted);margin:0;line-height:1.55}

/* ---------- Auth ---------- */
.auth{padding:100px 0;background:var(--bg-alt)}
.auth-card{
  background:
    radial-gradient(circle at 80% 20%,rgba(46,158,126,.2),transparent 50%),
    radial-gradient(circle at 10% 90%,rgba(46,158,126,.1),transparent 45%),
    linear-gradient(135deg,var(--gray-900) 0%,var(--g-900) 100%);
  color:var(--white);border-radius:calc(var(--radius) + 8px);
  padding:80px 70px;display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;
  position:relative;overflow:hidden;
}
.auth-copy h2{color:var(--white)}
.auth-copy h2 .hl{color:var(--g-300)}
.auth-copy h2 .hl::after{background:rgba(95,175,139,.3)}
.auth-copy p{color:rgba(255,255,255,.75);margin:18px 0 30px;max-width:480px;line-height:1.7}
.auth-copy p strong{color:var(--g-300)}
.store-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:22px}
.store-btn{
  display:inline-flex;align-items:center;gap:12px;
  background:var(--white);color:var(--gray-900);padding:10px 18px;border-radius:10px;
  transition:all .25s var(--ease);
}
.store-btn:hover{transform:translateY(-2px)}
.store-btn i{font-size:1.6rem}
.store-btn span{display:flex;flex-direction:column;line-height:1.1;font-size:.92rem;font-weight:700}
.store-btn small{font-size:.6rem;font-weight:500;color:var(--muted);letter-spacing:.06em}
.store-btns.sm .store-btn{padding:8px 14px;background:transparent;color:var(--white);border:1px solid rgba(255,255,255,.2)}
.store-btns.sm .store-btn small{color:rgba(255,255,255,.5)}
.auth-copy .link-arrow{color:var(--g-300);border-color:var(--g-300)}
.auth-copy .link-arrow:hover{color:var(--white);border-color:var(--white)}

.auth-visual{position:relative;display:grid;place-items:center}
.qr-frame{text-align:center;color:var(--white)}
.qr-mock{
  width:240px;height:240px;background:var(--white);border-radius:20px;
  padding:24px;position:relative;margin:0 auto 16px;
  box-shadow:0 30px 60px rgba(0,0,0,.4);
}
.qr-dot{position:absolute;width:46px;height:46px;border:7px solid var(--gray-900);border-radius:8px}
.qr-dot.tl{top:20px;left:20px}
.qr-dot.tr{top:20px;right:20px}
.qr-dot.bl{bottom:20px;left:20px}
.qr-inner{
  position:absolute;inset:28px;
  background-image:
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900)),
    linear-gradient(var(--gray-900),var(--gray-900));
  background-size:12px 12px,18px 18px,24px 12px,12px 24px,15px 15px,20px 14px,14px 20px,22px 22px;
  background-position:80px 26px,28px 92px,100px 80px,160px 100px,70px 140px,140px 150px,108px 180px,34px 160px;
  background-repeat:no-repeat;
}
.qr-logo{
  position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);
  width:56px;height:56px;border-radius:50%;background:var(--white);
  display:grid;place-items:center;
  box-shadow:0 4px 10px rgba(0,0,0,.2),inset 0 0 0 2px var(--brand);
}
.qr-logo svg{width:70%;height:70%}
.qr-frame p{font-size:.74rem;letter-spacing:.22em;color:var(--g-300);text-transform:uppercase;font-weight:700;font-family:'Space Grotesk',sans-serif}

/* ---------- Testimonials ---------- */
.testimonials{padding:120px 0;background:var(--bg-mint)}
.tm-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.tm-card{
  background:var(--white);border-radius:var(--radius);padding:34px 30px;
  margin:0;border:1px solid var(--g-100);position:relative;display:flex;flex-direction:column;gap:18px;
  transition:all .3s var(--ease);
}
.tm-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--g-300)}
.tm-card.featured{background:var(--gray-900);color:var(--white);border-color:var(--gray-900)}
.tm-card.featured h3,.tm-card.featured p{color:var(--white)}
.tm-card.featured footer{border-color:rgba(255,255,255,.1)}
.tm-card.featured footer strong{color:var(--white)}
.tm-card.featured footer span{color:rgba(255,255,255,.65)}
.tm-badge{
  display:inline-flex;align-items:center;gap:6px;
  background:var(--g-700);color:var(--g-300);padding:4px 10px;border-radius:6px;
  font-size:.66rem;letter-spacing:.18em;text-transform:uppercase;font-weight:700;font-family:'Space Grotesk',sans-serif;
  align-self:flex-start;
}
.tm-card p{font-size:1rem;line-height:1.55;color:var(--gray-900);margin:0;font-weight:500}
.tm-card footer{display:flex;align-items:center;gap:12px;margin-top:auto;border-top:1px solid var(--line);padding-top:18px}
.avatar{
  width:44px;height:44px;border-radius:50%;
  background:var(--brand);
  display:grid;place-items:center;color:var(--white);font-weight:700;font-size:.86rem;font-family:'Space Grotesk',sans-serif;
}
.tm-card.featured .avatar{background:var(--g-500)}
.tm-card footer strong{display:block;font-size:.9rem;color:var(--gray-900);font-weight:700}
.tm-card footer span{font-size:.74rem;color:var(--muted)}

/* ---------- Dealer ---------- */
.dealer{padding:120px 0;background:var(--white);position:relative;overflow:hidden}
.dealer::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 85% 15%,rgba(46,158,126,.06),transparent 50%);
  pointer-events:none;
}
.dealer-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center;position:relative}
.dealer p{color:var(--gray-600);margin:18px 0 30px;max-width:480px;line-height:1.7}
.dealer-points{list-style:none;padding:0;margin:0;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.dealer-points li{
  background:var(--bg-mint);padding:24px 20px;border-radius:12px;border:1px solid var(--g-100);
}
.dealer-points strong{display:block;font-family:'Space Grotesk',sans-serif;font-size:2rem;color:var(--brand);line-height:1;letter-spacing:-.02em;font-weight:700}
.dealer-points span{font-size:.74rem;letter-spacing:.06em;color:var(--muted);margin-top:8px;display:block;font-weight:500}

.dealer-form{
  background:var(--bg-mint);color:var(--gray-900);
  padding:40px 36px;border-radius:var(--radius);border:1px solid var(--g-100);
}
.dealer-form h3{font-size:1.3rem;margin-bottom:22px;font-weight:700}
.dealer-form label{display:block;font-size:.74rem;font-weight:700;color:var(--gray-900);margin-bottom:14px;letter-spacing:.08em;text-transform:uppercase}
.dealer-form input,.dealer-form textarea,.dealer-form select{
  width:100%;padding:12px 14px;margin-top:8px;
  border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.9rem;background:var(--white);
  transition:border-color .25s var(--ease);
  color:var(--gray-900);text-transform:none;letter-spacing:0;font-weight:400;
}
.dealer-form input:focus,.dealer-form textarea:focus,.dealer-form select:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(46,158,126,.15)}
.form-note{display:block;margin-top:12px;font-size:.74rem;color:var(--muted);text-align:center}
.form-note i{color:var(--brand);margin-right:6px}

/* ---------- Journal ---------- */
.news{padding:120px 0;background:var(--bg-alt)}
.news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.news-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);
  overflow:hidden;transition:all .35s var(--ease);
}
.news-card:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--g-300)}
.news-thumb{height:220px;background-size:cover;background-position:center;position:relative;display:grid;place-items:flex-start}
.thumb-tag{
  margin:16px;padding:5px 10px;background:var(--white);color:var(--brand);
  font-size:.62rem;font-weight:700;letter-spacing:.18em;border-radius:4px;
  font-family:'Space Grotesk',sans-serif;box-shadow:var(--shadow-sm);
}
.thumb-1{background:linear-gradient(135deg,#E8EDE9,#A3CBB5)}
.thumb-2{background:linear-gradient(135deg,#D8E4DD,#5FAF8B)}
.thumb-3{background:linear-gradient(135deg,#E0E4E2,#6B7571)}
.news-body{padding:24px 26px 28px}
.news-meta{font-size:.7rem;color:var(--muted);font-weight:600;letter-spacing:.02em;display:inline-block;margin-bottom:10px;font-family:'Space Grotesk',sans-serif}
.news-card h3{font-size:1.15rem;font-weight:700;margin:0 0 10px;line-height:1.35}
.news-card p{color:var(--muted);font-size:.88rem;margin:0 0 16px;line-height:1.6}

/* ---------- Newsletter ---------- */
.newsletter{background:var(--bg-mint);padding:80px 0;border-top:1px solid var(--g-100);border-bottom:1px solid var(--g-100)}
.news-inner{display:flex;justify-content:space-between;align-items:center;gap:40px;flex-wrap:wrap}
.news-inner h3{font-size:1.8rem;font-weight:700;letter-spacing:-.02em}
.news-inner p{color:var(--gray-600);margin:6px 0 0;max-width:440px;font-size:.94rem}
.news-inner form{display:flex;gap:10px;flex:1;max-width:480px}
.news-inner input{
  flex:1;padding:14px 18px;border-radius:10px;border:1px solid var(--g-200);
  background:var(--white);font-family:inherit;font-size:.9rem;color:var(--gray-900);
}
.news-inner input:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(46,158,126,.15)}

/* ---------- Footer ---------- */
.site-footer{background:var(--gray-900);color:rgba(255,255,255,.7);padding:80px 0 0}
.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr 1.2fr;gap:40px}
.logo-light{color:var(--g-300)}
.logo-light .logo-text strong{color:var(--white)}
.logo-light .logo-text em{color:var(--g-300)}
.footer-about{font-size:.86rem;line-height:1.75;margin:22px 0;color:rgba(255,255,255,.6)}
.footer-contact{list-style:none;padding:0;margin:0 0 22px}
.footer-contact li{padding:5px 0;font-size:.86rem}
.footer-contact i{color:var(--g-400);width:20px}
.footer-contact a:hover{color:var(--g-300)}
.footer-app{font-size:.82rem;color:rgba(255,255,255,.55);margin:0 0 14px;line-height:1.6}
.site-footer h4{color:var(--white);font-size:.76rem;letter-spacing:.2em;margin-bottom:20px}
.site-footer ul{list-style:none;padding:0;margin:0}
.site-footer ul li{padding:5px 0;font-size:.86rem}
.site-footer ul a{transition:color .2s var(--ease)}
.site-footer ul a:hover{color:var(--g-300)}
.socials{display:flex;gap:8px}
.socials a{
  width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,.05);
  border:1px solid rgba(255,255,255,.08);display:grid;place-items:center;
  color:var(--white);font-size:.88rem;transition:all .25s var(--ease);
}
.socials a:hover{background:var(--brand);border-color:var(--brand)}

.pay-row{display:flex;gap:6px;flex-wrap:wrap}
.pay{
  background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.85);
  padding:4px 10px;border-radius:6px;font-size:.66rem;letter-spacing:.14em;font-weight:700;font-family:'Space Grotesk',sans-serif;
}

.copyright{margin-top:70px;border-top:1px solid rgba(255,255,255,.06);padding:22px 0;font-size:.76rem}
.copyright-inner{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:center}
.copyright .legal{display:flex;gap:22px}
.copyright .legal a{color:rgba(255,255,255,.5)}
.copyright .legal a:hover{color:var(--g-300)}

/* ---------- Floating ---------- */
.floating{position:fixed;right:20px;bottom:24px;display:flex;flex-direction:column;gap:10px;z-index:60}
.fab{
  width:52px;height:52px;border-radius:50%;display:grid;place-items:center;
  color:var(--white);box-shadow:var(--shadow);position:relative;
  transition:all .25s var(--ease);
}
.fab:hover{transform:translateY(-3px)}
.fab-call{background:var(--brand);animation:pulseG 2.2s infinite}
.tip{
  position:absolute;right:60px;background:var(--gray-900);color:var(--white);
  padding:5px 12px;border-radius:999px;font-size:.72rem;white-space:nowrap;
  opacity:0;transform:translateX(8px);transition:all .25s var(--ease);pointer-events:none;font-weight:600;
}
.fab:hover .tip{opacity:1;transform:translateX(0)}
.fab-zalo{background:#0084ff}
.fab-label{font-weight:800;font-size:.68rem;letter-spacing:.02em}
.fab-fb{background:#0078ff}
.fab-top{background:var(--gray-900);opacity:0;pointer-events:none;transform:translateY(12px);transition:all .25s var(--ease)}
.fab-top.show{opacity:1;pointer-events:auto;transform:none}
@keyframes pulseG{
  0%{box-shadow:0 0 0 0 rgba(46,158,126,.55)}
  70%{box-shadow:0 0 0 18px rgba(46,158,126,0)}
  100%{box-shadow:0 0 0 0 rgba(46,158,126,0)}
}

/* ---------- Reveal ---------- */
.reveal{opacity:0;transform:translateY(24px);transition:opacity .8s var(--ease),transform .8s var(--ease)}
.reveal.in{opacity:1;transform:none}

/* ---------- Responsive ---------- */
@media (max-width: 1200px){
  .product-grid,.cat-grid,.values-grid,.ritual-steps,.sci-grid,.finder-cards{grid-template-columns:repeat(2,1fr)}
  .ritual-steps::before{display:none}
  .certstrip ul{grid-template-columns:repeat(3,1fr)}
  .footer-grid{grid-template-columns:1fr 1fr 1fr;gap:40px}
  .footer-grid > *:nth-child(1){grid-column:1/-1}
}
@media (max-width: 1080px){
  .main-nav{display:none}
  .burger{display:inline-block}
  .header-inner{grid-template-columns:auto 1fr auto;gap:12px}
  .topbar-left{display:none}
  .topbar-right{gap:16px}
  .hero-grid,.story-grid,.auth-card,.dealer-grid,.ing-grid,.ba-grid,.finder-grid{grid-template-columns:1fr;gap:50px}
  .auth-card{padding:50px 30px}
  .hero-side{display:none}
  .story-visual,.ing-visual{max-width:480px;margin:0 auto}
  .badge-float{display:none}
  .hero-specs{grid-template-columns:repeat(3,1fr);gap:14px}
  .spec strong{font-size:1.5rem}
}
@media (max-width: 640px){
  .topbar-right a:not(.locale-btn):not(.locale-menu *){display:none}
  .topbar-right .locale{display:block}
  .topbar{padding:6px 0}
  .announce-track{font-size:.66rem;gap:40px}
  .hero{padding:50px 0 70px;min-height:auto}
  .hero-specs{grid-template-columns:1fr 1fr}
  .product-grid,.cat-grid,.news-grid,.tm-grid,.values-grid,.ritual-steps,.sci-grid,.finder-cards{grid-template-columns:1fr}
  .certstrip ul{grid-template-columns:1fr 1fr}
  .ing-list{grid-template-columns:1fr}
  .footer-grid{grid-template-columns:1fr}
  .section-head.between{flex-direction:column;align-items:flex-start}
  .dealer-points{grid-template-columns:1fr}
  .auth-card{padding:40px 24px}
  .copyright-inner{flex-direction:column;text-align:center}
  .container{padding:0 20px}
  .logo-text em{display:none}
}

