/* =========================================================
   DETOXBLANC — pages.css
   Các component riêng cho PDP · Ritual · Article · Checkout
   Kế thừa biến & typography từ styles.css
   ========================================================= */

/* ---------- Shared page header ---------- */
.page-hero{padding:40px 0 60px;background:var(--bg-mint);border-bottom:1px solid var(--g-100)}
.breadcrumb{
  display:flex;gap:8px;align-items:center;flex-wrap:wrap;
  font-size:.78rem;color:var(--muted);margin-bottom:20px;
}
.breadcrumb a{color:var(--muted);transition:color .2s var(--ease)}
.breadcrumb a:hover{color:var(--brand)}
.breadcrumb i{font-size:.6rem;color:var(--gray-300)}
.breadcrumb span{color:var(--gray-900);font-weight:600}

/* ===============  PRODUCT DETAIL  =============== */
.pdp{padding:30px 0 100px;background:var(--white)}
.pdp-grid{display:grid;grid-template-columns:1.05fr 1fr;gap:70px;align-items:flex-start}

/* Gallery */
.pdp-gallery{position:sticky;top:110px}
.pdp-main{
  background:var(--bg-mint);border-radius:var(--radius);
  aspect-ratio:1;display:grid;place-items:center;position:relative;
  border:1px solid var(--g-100);overflow:hidden;
}
.pdp-main::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 30% 20%,rgba(255,255,255,.8),transparent 55%);
}
.pdp-main .bottle-svg{width:48%;filter:drop-shadow(0 30px 40px rgba(20,31,29,.15));position:relative;z-index:1}
.pdp-main .tag{top:22px;left:22px}
.pdp-360{
  position:absolute;right:20px;bottom:20px;background:var(--white);border:1px solid var(--line);
  padding:8px 14px;border-radius:999px;font-size:.72rem;font-weight:700;color:var(--gray-900);
  letter-spacing:.1em;display:inline-flex;align-items:center;gap:6px;cursor:pointer;
  font-family:'Space Grotesk',sans-serif;
}
.pdp-360 i{color:var(--brand)}
.pdp-thumbs{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:14px}
.pdp-thumb{
  background:var(--bg-mint);border:1px solid var(--g-100);border-radius:10px;
  aspect-ratio:1;display:grid;place-items:center;cursor:pointer;
  transition:all .25s var(--ease);position:relative;
}
.pdp-thumb .bottle-svg{width:55%}
.pdp-thumb.active,.pdp-thumb:hover{border-color:var(--brand);transform:translateY(-2px)}
.pdp-thumb.video::after{
  content:"\f04b";font-family:"Font Awesome 6 Free";font-weight:900;
  position:absolute;inset:0;display:grid;place-items:center;
  color:var(--white);background:rgba(20,31,29,.4);border-radius:10px;font-size:1.2rem;
}

/* Info */
.pdp-info{padding-top:10px}
.pdp-badges{display:flex;gap:8px;margin-bottom:14px;flex-wrap:wrap}
.pdp-badges span{
  background:var(--bg-mint);border:1px solid var(--g-100);color:var(--brand);
  padding:5px 12px;border-radius:999px;font-size:.7rem;font-weight:700;
  letter-spacing:.08em;font-family:'Space Grotesk',sans-serif;
}
.pdp-cat{
  display:inline-flex;align-items:center;gap:6px;font-size:.72rem;color:var(--brand);
  font-weight:700;letter-spacing:.16em;text-transform:uppercase;font-family:'Space Grotesk',sans-serif;
}
.pdp-title{font-size:clamp(1.8rem,3vw,2.4rem);line-height:1.15;margin:10px 0 12px;letter-spacing:-.02em}
.pdp-sub{font-size:1rem;color:var(--gray-600);margin:0 0 18px}
.pdp-rating{display:flex;align-items:center;gap:14px;padding:14px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.pdp-rating .stars{font-size:.9rem}
.pdp-rating a{color:var(--gray-700);font-size:.82rem;text-decoration:underline;text-underline-offset:3px}
.pdp-rating a:hover{color:var(--brand)}
.pdp-rating .sep{color:var(--gray-300)}

.pdp-price{display:flex;align-items:baseline;gap:14px;margin:24px 0 14px}
.pdp-price .price{font-family:'Space Grotesk',sans-serif;font-size:2rem;font-weight:700;color:var(--gray-900);letter-spacing:-.02em}
.pdp-price .price-old{font-size:1rem;color:var(--muted);text-decoration:line-through}
.pdp-price .save{
  background:#FEEDEA;color:#B9503E;font-size:.72rem;font-weight:700;padding:4px 10px;border-radius:4px;
  letter-spacing:.05em;font-family:'Space Grotesk',sans-serif;
}
.pdp-stock{font-size:.82rem;color:var(--brand);margin-bottom:26px;display:flex;align-items:center;gap:8px;font-weight:600}
.pdp-stock::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--brand);box-shadow:0 0 0 4px rgba(99,193,187,.2)}

/* Option groups */
.pdp-opts{display:flex;flex-direction:column;gap:22px;margin-bottom:28px}
.opt-label{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px;font-size:.78rem;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--gray-900)}
.opt-label small{color:var(--muted);font-weight:500;letter-spacing:.02em;text-transform:none;font-size:.8rem}
.opt-row{display:flex;gap:10px;flex-wrap:wrap}
.size-opt{
  border:1px solid var(--line);border-radius:10px;padding:12px 18px;background:var(--white);
  cursor:pointer;font-family:inherit;display:flex;flex-direction:column;align-items:flex-start;
  transition:all .25s var(--ease);min-width:120px;
}
.size-opt:hover{border-color:var(--gray-700)}
.size-opt.active{border:2px solid var(--brand);padding:11px 17px;background:var(--bg-mint)}
.size-opt strong{font-size:.92rem;color:var(--gray-900);font-weight:700}
.size-opt span{font-size:.78rem;color:var(--muted);margin-top:3px;font-family:'Space Grotesk',sans-serif}

.qty-row{display:flex;align-items:center;gap:16px}
.qty-input{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:10px;overflow:hidden}
.qty-input button{
  width:42px;height:46px;background:var(--white);color:var(--gray-700);font-size:1rem;
  transition:background .2s var(--ease);
}
.qty-input button:hover{background:var(--bg-mint)}
.qty-input input{
  width:48px;height:46px;border:0;text-align:center;font-weight:700;font-size:1rem;
  color:var(--gray-900);background:var(--white);font-family:'Space Grotesk',sans-serif;
}
.qty-input input:focus{outline:0}

/* CTA row */
.pdp-cta{display:grid;grid-template-columns:1fr auto auto;gap:10px;margin-bottom:24px}
.pdp-cta .btn{padding:15px 20px;border-radius:10px;justify-content:center}
.wish-btn,.compare-btn{
  width:52px;height:52px;border-radius:10px;border:1px solid var(--line);background:var(--white);color:var(--gray-900);
  font-size:1rem;transition:all .25s var(--ease);
}
.wish-btn:hover,.compare-btn:hover{border-color:var(--brand);color:var(--brand);background:var(--bg-mint)}

/* Trust info */
.pdp-trust{display:grid;grid-template-columns:repeat(2,1fr);gap:12px;margin-bottom:28px}
.trust-item{
  display:flex;align-items:center;gap:12px;padding:14px 16px;background:var(--bg-alt);border:1px solid var(--line);
  border-radius:10px;
}
.trust-item i{color:var(--brand);font-size:1.1rem}
.trust-item strong{display:block;font-size:.84rem;color:var(--gray-900);font-weight:700}
.trust-item span{font-size:.72rem;color:var(--muted)}

/* Key benefits */
.pdp-benefits{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;padding:20px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:22px}
.benefit{
  text-align:center;padding:6px;
}
.benefit i{
  width:40px;height:40px;border-radius:50%;background:var(--bg-mint);color:var(--brand);
  display:grid;place-items:center;font-size:.9rem;margin:0 auto 8px;
}
.benefit span{font-size:.72rem;color:var(--gray-700);font-weight:600;line-height:1.35;display:block}

/* ---------- PDP tabs ---------- */
.pdp-detail{padding:80px 0;background:var(--bg-alt)}
.pdp-tabs{display:flex;gap:4px;border-bottom:1px solid var(--line);margin-bottom:40px;overflow-x:auto}
.pdp-tab{
  padding:14px 22px;font-size:.9rem;font-weight:600;color:var(--gray-600);background:transparent;
  border-bottom:2px solid transparent;margin-bottom:-1px;transition:all .2s var(--ease);
  white-space:nowrap;font-family:inherit;
}
.pdp-tab:hover{color:var(--gray-900)}
.pdp-tab.active{color:var(--brand);border-color:var(--brand)}
.pdp-panel{display:none}
.pdp-panel.active{display:block}

.panel-grid{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:flex-start}
.panel-grid h3{font-size:1.4rem;margin-bottom:16px}
.panel-grid p{color:var(--gray-700);margin:0 0 14px;line-height:1.75}

/* Ingredients table */
.ing-table{
  width:100%;border-collapse:collapse;background:var(--white);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden;
}
.ing-table th,.ing-table td{padding:14px 18px;text-align:left;border-bottom:1px solid var(--line);font-size:.88rem}
.ing-table th{font-size:.72rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--gray-600);background:var(--bg-alt)}
.ing-table tr:last-child td{border-bottom:0}
.ing-table td strong{color:var(--gray-900);font-weight:700}
.ing-table td em{color:var(--brand);font-weight:700;font-style:normal;font-family:'Space Grotesk',sans-serif}
.ing-safe{
  display:inline-flex;align-items:center;gap:6px;color:var(--brand);
  font-size:.74rem;font-weight:700;font-family:'Space Grotesk',sans-serif;
}

/* How-to steps */
.howto{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.howto-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:28px 22px;
  text-align:center;
}
.howto-card .num{
  font-family:'Space Grotesk',sans-serif;font-size:.78rem;color:var(--brand);font-weight:700;
  letter-spacing:.1em;padding:4px 10px;background:var(--bg-mint);border-radius:16px;display:inline-block;
}
.howto-card i{font-size:1.6rem;color:var(--brand);margin:16px 0 12px;display:block}
.howto-card h4{font-family:'Manrope',sans-serif;font-size:1rem;color:var(--gray-900);font-weight:700;text-transform:none;letter-spacing:-.005em;margin-bottom:6px}
.howto-card p{font-size:.82rem;color:var(--muted);margin:0;line-height:1.55}

/* FAQ */
.faq{max-width:860px;margin:0 auto}
.faq-item{
  background:var(--white);border:1px solid var(--line);border-radius:12px;margin-bottom:10px;overflow:hidden;
}
.faq-q{
  width:100%;display:flex;justify-content:space-between;align-items:center;gap:16px;
  padding:18px 22px;background:transparent;text-align:left;font-family:inherit;
  font-size:.96rem;color:var(--gray-900);font-weight:700;transition:background .2s var(--ease);
}
.faq-q:hover{background:var(--bg-alt)}
.faq-q i{font-size:.9rem;color:var(--brand);transition:transform .25s var(--ease)}
.faq-item.open .faq-q i{transform:rotate(45deg)}
.faq-a{max-height:0;overflow:hidden;transition:max-height .3s var(--ease)}
.faq-item.open .faq-a{max-height:300px}
.faq-a-inner{padding:0 22px 22px;color:var(--gray-700);line-height:1.7}

/* Reviews */
.rv-summary{display:grid;grid-template-columns:1fr 2fr;gap:60px;margin-bottom:40px;padding:30px;background:var(--white);border:1px solid var(--line);border-radius:var(--radius)}
.rv-score{text-align:center}
.rv-score strong{font-family:'Space Grotesk',sans-serif;font-size:4rem;color:var(--gray-900);line-height:1;font-weight:700;letter-spacing:-.03em;display:block}
.rv-score .stars{justify-content:center;margin:10px 0 6px;font-size:1.1rem}
.rv-score small{font-size:.82rem;color:var(--muted)}
.rv-bars{display:flex;flex-direction:column;gap:8px}
.rv-bar{display:grid;grid-template-columns:40px 1fr 50px;align-items:center;gap:12px;font-size:.82rem}
.rv-bar-track{height:8px;background:var(--bg-alt);border-radius:4px;overflow:hidden}
.rv-bar-fill{height:100%;background:var(--brand);border-radius:4px}
.rv-bar span{color:var(--muted);text-align:right;font-family:'Space Grotesk',sans-serif;font-weight:600}
.rv-list{display:flex;flex-direction:column;gap:14px}
.rv-item{background:var(--white);border:1px solid var(--line);border-radius:12px;padding:22px 26px}
.rv-head{display:flex;gap:12px;align-items:center;margin-bottom:10px}
.rv-head .avatar{width:40px;height:40px;font-size:.8rem}
.rv-head strong{font-size:.9rem}
.rv-head time{font-size:.74rem;color:var(--muted);margin-left:auto;font-family:'Space Grotesk',sans-serif}
.rv-verified{display:inline-flex;align-items:center;gap:4px;font-size:.68rem;color:var(--brand);font-weight:700}
.rv-item .stars{font-size:.78rem;margin-bottom:8px}
.rv-item p{color:var(--gray-700);margin:0;font-size:.92rem;line-height:1.6}

/* Related */
.related{padding:100px 0;background:var(--white)}

/* ===============  RITUAL DETAIL  =============== */
.ritual-hero{
  background:
    radial-gradient(circle at 80% 20%,rgba(99,193,187,.18),transparent 50%),
    radial-gradient(circle at 20% 80%,rgba(99,193,187,.1),transparent 50%),
    var(--bg-mint);
  padding:70px 0 80px;border-bottom:1px solid var(--g-100);
}
.ritual-hero-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center}
.ritual-meta{display:flex;gap:24px;margin-top:24px;padding-top:24px;border-top:1px solid var(--g-200);flex-wrap:wrap}
.ritual-meta > div{display:flex;flex-direction:column}
.ritual-meta strong{font-family:'Space Grotesk',sans-serif;font-size:1.3rem;color:var(--gray-900);font-weight:700}
.ritual-meta span{font-size:.74rem;color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-top:4px;font-weight:500}
.ritual-products{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.ritual-prod{background:var(--white);border:1px solid var(--g-100);border-radius:var(--radius);padding:20px;text-align:center}
.ritual-prod .bottle-svg{width:70%;margin:0 auto}
.ritual-prod span{display:block;font-size:.74rem;color:var(--brand);font-weight:700;letter-spacing:.1em;margin-top:10px;font-family:'Space Grotesk',sans-serif}

/* Timeline */
.timeline{padding:100px 0;background:var(--white)}
.timeline-wrap{max-width:900px;margin:0 auto;position:relative;padding-left:60px}
.timeline-wrap::before{
  content:"";position:absolute;left:24px;top:12px;bottom:12px;width:2px;
  background:repeating-linear-gradient(to bottom, var(--g-300) 0 6px, transparent 6px 12px);
}
.tl-item{position:relative;padding-bottom:60px}
.tl-item:last-child{padding-bottom:0}
.tl-dot{
  position:absolute;left:-60px;top:0;width:50px;height:50px;border-radius:50%;
  background:var(--white);border:2px solid var(--brand);color:var(--brand);
  display:grid;place-items:center;font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:.9rem;
  box-shadow:0 0 0 6px var(--bg-mint);
}
.tl-item.done .tl-dot{background:var(--brand);color:var(--white)}
.tl-dur{
  display:inline-flex;align-items:center;gap:6px;font-size:.74rem;
  color:var(--brand);font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  margin-bottom:6px;font-family:'Space Grotesk',sans-serif;
}
.tl-item h3{font-size:1.6rem;margin-bottom:8px;letter-spacing:-.01em}
.tl-item > p{color:var(--gray-600);margin:0 0 18px;line-height:1.75}
.tl-card{
  display:grid;grid-template-columns:auto 1fr auto;gap:20px;align-items:center;
  background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);padding:22px 26px;
}
.tl-card .bottle-svg{width:80px}
.tl-card strong{display:block;font-size:1rem;color:var(--gray-900);font-weight:700;margin-bottom:4px}
.tl-card span{font-size:.82rem;color:var(--muted)}
.tl-card .price{font-family:'Space Grotesk',sans-serif;font-size:1.1rem;font-weight:700;color:var(--gray-900);display:block;margin-bottom:8px;text-align:right}

/* Bundle */
.bundle{padding:100px 0;background:var(--bg-alt)}
.bundle-card{
  background:var(--white);border:1px solid var(--line);border-radius:calc(var(--radius) + 4px);
  padding:50px;display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:center;
  box-shadow:var(--shadow);
}
.bundle-visual{display:flex;gap:-20px;justify-content:center;align-items:flex-end;position:relative;min-height:260px}
.bundle-visual .bottle-svg{width:120px}
.bundle-visual .bottle-svg:nth-child(2){margin:0 -20px;z-index:2;transform:scale(1.15)}
.bundle-visual .bottle-svg:nth-child(odd){opacity:.9}
.bundle-price{display:flex;align-items:baseline;gap:14px;margin:16px 0 20px}
.bundle-price .now{font-family:'Space Grotesk',sans-serif;font-size:2.4rem;font-weight:700;color:var(--gray-900);letter-spacing:-.02em}
.bundle-price .was{color:var(--muted);text-decoration:line-through;font-size:1rem}
.bundle-price .save{background:var(--brand);color:var(--white);font-size:.76rem;font-weight:700;padding:4px 10px;border-radius:4px;letter-spacing:.05em;font-family:'Space Grotesk',sans-serif}
.bundle-list{list-style:none;padding:0;margin:0 0 24px;display:flex;flex-direction:column;gap:8px}
.bundle-list li{display:flex;justify-content:space-between;font-size:.9rem;padding:8px 0;border-bottom:1px solid var(--line)}
.bundle-list li span{color:var(--gray-700)}
.bundle-list li strong{color:var(--gray-900);font-family:'Space Grotesk',sans-serif}

/* ===============  ARTICLE DETAIL  =============== */
.article-hero{
  padding:50px 0 60px;background:var(--white);border-bottom:1px solid var(--line);
}
.article-hero .container{max-width:820px}
.article-cat{display:inline-block;font-size:.7rem;letter-spacing:.22em;color:var(--brand);font-weight:700;text-transform:uppercase;margin-bottom:18px;font-family:'Space Grotesk',sans-serif}
.article-title{font-size:clamp(2rem,3.6vw,3.4rem);line-height:1.15;margin:0 0 20px;letter-spacing:-.02em}
.article-excerpt{font-size:1.15rem;color:var(--gray-600);line-height:1.65;margin:0 0 28px}
.article-meta{display:flex;gap:20px;align-items:center;flex-wrap:wrap;padding:18px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);font-size:.84rem;color:var(--muted)}
.article-meta .author{display:flex;align-items:center;gap:10px}
.article-meta .avatar{width:40px;height:40px;font-size:.8rem}
.article-meta strong{color:var(--gray-900);font-size:.86rem;font-weight:700}
.article-meta span{display:block;font-size:.74rem;color:var(--muted);font-family:'Space Grotesk',sans-serif}
.article-meta .share{margin-left:auto;display:flex;gap:6px}
.article-meta .share a{
  width:34px;height:34px;border-radius:50%;border:1px solid var(--line);
  display:grid;place-items:center;color:var(--gray-700);transition:all .2s var(--ease);
}
.article-meta .share a:hover{border-color:var(--brand);color:var(--brand);background:var(--bg-mint)}

.article-cover{
  height:440px;
  background:
    radial-gradient(circle at 30% 30%,rgba(255,255,255,.5),transparent 50%),
    linear-gradient(135deg,var(--g-200),var(--brand));
  border-radius:var(--radius);margin-bottom:20px;
}

.article-body{padding:70px 0 100px;background:var(--white)}
.article-layout{display:grid;grid-template-columns:240px 1fr;gap:60px;max-width:1100px;margin:0 auto}
.toc{position:sticky;top:110px;align-self:flex-start;font-size:.88rem}
.toc h5{margin-bottom:14px}
.toc ul{list-style:none;padding:0;margin:0;border-left:1px solid var(--line)}
.toc ul li{padding:6px 0 6px 14px;margin-left:-1px;border-left:2px solid transparent;transition:all .2s var(--ease)}
.toc ul li.active,.toc ul li:hover{border-color:var(--brand)}
.toc ul a{color:var(--gray-600);font-size:.86rem;transition:color .2s var(--ease)}
.toc ul li.active a,.toc ul a:hover{color:var(--brand);font-weight:600}

.article-content h2{font-size:1.8rem;margin:44px 0 16px;letter-spacing:-.02em}
.article-content h3{font-size:1.3rem;margin:32px 0 14px;font-family:'Manrope',sans-serif;font-weight:700}
.article-content p{color:var(--gray-700);font-size:1rem;margin:0 0 18px;line-height:1.85}
.article-content p strong{color:var(--gray-900)}
.article-content ul,.article-content ol{color:var(--gray-700);padding-left:22px;margin:0 0 20px;line-height:1.85}
.article-content li{padding:3px 0}
.article-content li::marker{color:var(--brand)}
.article-content blockquote{
  margin:28px 0;padding:22px 28px;border-left:3px solid var(--brand);
  background:var(--bg-mint);border-radius:0 12px 12px 0;font-size:1.12rem;color:var(--gray-900);font-weight:500;line-height:1.6;
}
.callout{
  margin:28px 0;padding:22px 26px;background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);
  display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:flex-start;
}
.callout i{color:var(--brand);font-size:1.4rem;padding-top:4px}
.callout strong{display:block;color:var(--gray-900);font-size:1rem;font-weight:700;margin-bottom:4px}
.callout p{margin:0;color:var(--gray-700);font-size:.92rem;line-height:1.7}

.article-fig{margin:36px 0;border-radius:var(--radius);overflow:hidden;background:var(--bg-mint);aspect-ratio:16/9;display:grid;place-items:center;color:var(--g-300);font-size:3rem;position:relative}
.article-fig figcaption{position:absolute;bottom:0;left:0;right:0;background:linear-gradient(transparent,rgba(0,0,0,.7));color:var(--white);padding:40px 24px 20px;font-size:.82rem}

.author-box{
  margin-top:70px;padding:30px;background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);
  display:grid;grid-template-columns:auto 1fr;gap:24px;align-items:center;
}
.author-box .avatar{width:72px;height:72px;font-size:1.3rem}
.author-box strong{display:block;font-size:1.1rem;color:var(--gray-900);font-weight:700;margin-bottom:4px}
.author-box small{display:block;font-size:.82rem;color:var(--brand);font-weight:600;margin-bottom:10px;letter-spacing:.08em;text-transform:uppercase;font-family:'Space Grotesk',sans-serif}
.author-box p{margin:0;font-size:.9rem;color:var(--gray-700);line-height:1.65}

.article-cta{margin:60px 0 0;padding:40px;background:var(--gray-900);color:var(--white);border-radius:var(--radius);text-align:center}
.article-cta h3{color:var(--white);font-size:1.4rem;margin-bottom:10px}
.article-cta p{color:rgba(255,255,255,.7);font-size:.94rem;margin:0 0 20px;max-width:500px;margin-inline:auto}

/* ===============  CHECKOUT  =============== */
.co-wrap{padding:40px 0 100px;background:var(--bg-alt)}
.co-progress{display:flex;justify-content:center;align-items:center;gap:8px;margin-bottom:40px;flex-wrap:wrap}
.co-step{display:flex;align-items:center;gap:10px;color:var(--muted);font-size:.86rem;font-weight:600}
.co-step .n{
  width:32px;height:32px;border-radius:50%;background:var(--white);border:2px solid var(--line);
  display:grid;place-items:center;font-family:'Space Grotesk',sans-serif;font-size:.82rem;color:var(--muted);font-weight:700;
}
.co-step.active{color:var(--gray-900)}
.co-step.active .n{background:var(--brand);color:var(--white);border-color:var(--brand)}
.co-step.done .n{background:var(--bg-mint);border-color:var(--brand);color:var(--brand)}
.co-step-sep{width:40px;height:2px;background:var(--line)}

.co-grid{display:grid;grid-template-columns:1.5fr 1fr;gap:40px;align-items:flex-start}

/* Left: steps */
.co-section{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:32px;margin-bottom:20px;
}
.co-section h3{font-size:1.2rem;margin-bottom:20px;display:flex;align-items:center;gap:10px}
.co-section h3 .n{
  width:28px;height:28px;border-radius:50%;background:var(--brand);color:var(--white);
  display:inline-grid;place-items:center;font-size:.82rem;font-family:'Space Grotesk',sans-serif;font-weight:700;
}

/* Cart item */
.cart-item{display:grid;grid-template-columns:100px 1fr auto;gap:20px;padding:20px 0;border-bottom:1px solid var(--line);align-items:center}
.cart-item:last-of-type{border-bottom:0;padding-bottom:0}
.cart-item-media{background:var(--bg-mint);border-radius:12px;aspect-ratio:1;display:grid;place-items:center;border:1px solid var(--g-100)}
.cart-item-media .bottle-svg{width:75%}
.cart-item-body strong{display:block;font-size:.96rem;color:var(--gray-900);font-weight:700;line-height:1.4}
.cart-item-body .meta{font-size:.78rem;color:var(--muted);margin:4px 0}
.cart-item-body .actions{display:flex;gap:14px;margin-top:6px;font-size:.8rem}
.cart-item-body .actions a{color:var(--gray-700)}
.cart-item-body .actions a:hover{color:var(--brand)}
.cart-item-body .actions a i{margin-right:4px}
.cart-item-right{text-align:right;display:flex;flex-direction:column;align-items:flex-end;gap:10px}
.cart-item-right .price{font-family:'Space Grotesk',sans-serif;font-size:1.1rem;font-weight:700}

/* Form fields */
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px}
.form-row.one{grid-template-columns:1fr}
.field{display:block}
.field label{font-size:.74rem;font-weight:700;color:var(--gray-900);letter-spacing:.08em;text-transform:uppercase;margin-bottom:8px;display:block}
.field input,.field select,.field textarea{
  width:100%;padding:13px 14px;border:1px solid var(--line);border-radius:10px;
  font-family:inherit;font-size:.94rem;background:var(--white);color:var(--gray-900);
  transition:all .2s var(--ease);
}
.field input:focus,.field select:focus,.field textarea:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(99,193,187,.2)}

/* Shipping methods */
.ship-methods,.pay-methods{display:flex;flex-direction:column;gap:10px}
.method{
  display:grid;grid-template-columns:auto 1fr auto;gap:14px;align-items:center;
  padding:16px 20px;border:1px solid var(--line);border-radius:12px;background:var(--white);
  cursor:pointer;transition:all .2s var(--ease);
}
.method:hover{border-color:var(--gray-400)}
.method.active{border:2px solid var(--brand);padding:15px 19px;background:var(--bg-mint)}
.method input{appearance:none;width:18px;height:18px;border:2px solid var(--gray-300);border-radius:50%;position:relative;cursor:pointer;margin:0}
.method.active input{border-color:var(--brand)}
.method.active input::after{content:"";position:absolute;inset:3px;border-radius:50%;background:var(--brand)}
.method strong{display:block;font-size:.92rem;color:var(--gray-900);font-weight:700}
.method small{display:block;font-size:.78rem;color:var(--muted);margin-top:2px}
.method .fee{font-family:'Space Grotesk',sans-serif;font-weight:700;color:var(--gray-900)}
.method i{color:var(--brand);font-size:1.3rem;width:28px;text-align:center}

/* Summary sidebar */
.co-summary{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:32px;
  position:sticky;top:110px;
}
.co-summary h3{font-size:1.1rem;margin-bottom:20px}
.co-summary .mini-item{display:grid;grid-template-columns:64px 1fr auto;gap:12px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:.86rem}
.co-summary .mini-item:last-of-type{border-bottom:0}
.co-summary .mini-media{background:var(--bg-mint);border-radius:8px;aspect-ratio:1;display:grid;place-items:center;border:1px solid var(--g-100);position:relative}
.co-summary .mini-media .bottle-svg{width:80%}
.co-summary .mini-media .qty{
  position:absolute;top:-8px;right:-8px;background:var(--gray-900);color:var(--white);
  width:22px;height:22px;border-radius:50%;font-family:'Space Grotesk',sans-serif;font-size:.68rem;font-weight:700;
  display:grid;place-items:center;
}
.co-summary .mini-item strong{display:block;font-size:.88rem;color:var(--gray-900);font-weight:700;line-height:1.3}
.co-summary .mini-item span{font-size:.72rem;color:var(--muted)}
.co-summary .mini-item .price{font-family:'Space Grotesk',sans-serif;font-weight:700;color:var(--gray-900)}

.promo{display:flex;gap:8px;margin:20px 0}
.promo input{flex:1;padding:12px 14px;border:1px solid var(--line);border-radius:10px;font-family:inherit;font-size:.88rem;background:var(--bg-alt)}
.promo input:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(99,193,187,.2)}
.promo button{padding:12px 18px;background:var(--gray-900);color:var(--white);border-radius:10px;font-weight:700;font-size:.82rem;font-family:inherit;letter-spacing:.04em}
.promo button:hover{background:var(--brand)}

.totals{border-top:1px solid var(--line);padding-top:20px}
.totals .row{display:flex;justify-content:space-between;padding:6px 0;font-size:.9rem;color:var(--gray-700)}
.totals .row.free{color:var(--brand)}
.totals .row.total{border-top:1px solid var(--line);padding-top:16px;margin-top:10px;font-size:1.15rem;font-weight:700;color:var(--gray-900)}
.totals .row.total strong{font-family:'Space Grotesk',sans-serif}

.co-foot-trust{display:flex;flex-direction:column;gap:8px;margin-top:20px;font-size:.78rem;color:var(--muted)}
.co-foot-trust i{color:var(--brand);margin-right:8px}

/* ---------- Related products ---------- */

/* ---------- Responsive ---------- */
@media (max-width: 1080px){
  .pdp-grid,.ritual-hero-grid,.bundle-card,.co-grid,.article-layout,.panel-grid,.rv-summary{grid-template-columns:1fr;gap:40px}
  .pdp-gallery,.co-summary,.toc{position:static;top:auto}
  .pdp-cta{grid-template-columns:1fr}
  .pdp-trust,.pdp-benefits,.howto{grid-template-columns:repeat(2,1fr)}
  .form-row{grid-template-columns:1fr}
  .ritual-products{grid-template-columns:1fr 1fr}
  .timeline-wrap{padding-left:50px}
  .tl-dot{left:-50px;width:40px;height:40px;font-size:.8rem}
  .tl-card{grid-template-columns:1fr;text-align:left}
}
@media (max-width: 640px){
  .pdp-thumbs{grid-template-columns:repeat(4,1fr)}
  .pdp-benefits,.pdp-trust,.howto{grid-template-columns:1fr 1fr}
  .cart-item{grid-template-columns:72px 1fr;gap:12px}
  .cart-item-right{grid-column:1/-1;flex-direction:row;justify-content:space-between;align-items:center}
  .bundle-card{padding:30px 22px}
  .co-section{padding:22px}
}

