/* ===============  CATEGORY / COLLECTION  =============== */
.cat-hero{
  padding:60px 0 70px;
  background:
    radial-gradient(circle at 85% 15%,rgba(99,193,187,.18),transparent 50%),
    radial-gradient(circle at 15% 85%,rgba(99,193,187,.1),transparent 45%),
    var(--bg-mint);
  border-bottom:1px solid var(--g-100);
}
.cat-hero-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:60px;align-items:center}
.cat-hero-copy h1{font-size:clamp(2.4rem,4.5vw,3.8rem);line-height:1.1;margin:10px 0 18px;letter-spacing:-.02em}
.cat-hero-copy .lead{margin:0 0 24px;max-width:560px}
.cat-hero-stats{display:flex;gap:32px;flex-wrap:wrap;padding-top:20px;border-top:1px solid var(--g-200)}
.cat-hero-stats strong{font-family:'Space Grotesk',sans-serif;font-size:1.7rem;color:var(--gray-900);display:block;line-height:1;letter-spacing:-.02em;font-weight:700}
.cat-hero-stats span{font-size:.72rem;color:var(--muted);letter-spacing:.08em;text-transform:uppercase;margin-top:6px;display:block;font-weight:500}
.cat-hero-visual{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.cat-hero-visual .mini{background:var(--white);border:1px solid var(--g-100);border-radius:var(--radius);padding:20px;aspect-ratio:1;display:grid;place-items:center;position:relative}
.cat-hero-visual .mini .bottle-svg{width:65%}
.cat-hero-visual .mini:nth-child(odd){transform:translateY(12px)}

/* Filter bar */
.cat-toolbar{
  background:var(--white);border-bottom:1px solid var(--line);padding:16px 0;
  position:sticky;top:70px;z-index:20;
}
.cat-toolbar-inner{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}
.cat-filters-trig{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.cat-chip{
  display:inline-flex;align-items:center;gap:6px;
  padding:8px 14px;background:var(--bg-alt);border:1px solid var(--line);border-radius:999px;
  font-size:.82rem;color:var(--gray-700);font-weight:600;cursor:pointer;transition:all .2s var(--ease);
  font-family:inherit;
}
.cat-chip:hover{border-color:var(--brand)}
.cat-chip.active{background:var(--brand);color:var(--white);border-color:var(--brand)}
.cat-chip i{font-size:.72rem}
.cat-sort{display:flex;gap:12px;align-items:center;font-size:.84rem;color:var(--muted)}
.cat-sort select{
  padding:8px 30px 8px 12px;border:1px solid var(--line);border-radius:8px;background:var(--white);
  font-family:inherit;font-size:.84rem;color:var(--gray-900);appearance:none;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='10' viewBox='0 0 10 10'><path d='M5 7L1 3h8z' fill='%232E857F'/></svg>");
  background-repeat:no-repeat;background-position:right 10px center;cursor:pointer;
}
.cat-count{color:var(--muted);font-size:.84rem;font-family:'Space Grotesk',sans-serif;font-weight:500}
.cat-view{display:flex;gap:2px;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.cat-view button{width:36px;height:36px;background:var(--white);color:var(--gray-500);font-size:.9rem;transition:background .2s}
.cat-view button.active{background:var(--gray-900);color:var(--white)}

/* Listing */
.cat-list{padding:60px 0 80px;background:var(--bg-alt)}
.cat-layout{display:grid;grid-template-columns:260px 1fr;gap:40px;align-items:flex-start}
.cat-sidebar{
  position:sticky;top:140px;background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:26px;
}
.filter-group{padding:16px 0;border-bottom:1px solid var(--line)}
.filter-group:first-child{padding-top:0}
.filter-group:last-child{border-bottom:0;padding-bottom:0}
.filter-group h5{margin-bottom:14px;font-size:.74rem}
.filter-group ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:10px}
.filter-check{display:flex;align-items:center;gap:10px;cursor:pointer;font-size:.86rem;color:var(--gray-700);transition:color .2s var(--ease)}
.filter-check:hover{color:var(--brand)}
.filter-check input{appearance:none;width:18px;height:18px;border:1.5px solid var(--gray-300);border-radius:5px;position:relative;cursor:pointer;margin:0;transition:all .2s var(--ease)}
.filter-check input:checked{background:var(--brand);border-color:var(--brand)}
.filter-check input:checked::after{content:"\f00c";font-family:"Font Awesome 6 Free";font-weight:900;position:absolute;inset:0;display:grid;place-items:center;color:var(--white);font-size:.66rem}
.filter-check small{color:var(--muted);margin-left:auto;font-family:'Space Grotesk',sans-serif;font-weight:500}
.filter-price{display:flex;gap:8px;margin-top:8px}
.filter-price input{flex:1;padding:8px 10px;border:1px solid var(--line);border-radius:8px;font-family:inherit;font-size:.82rem;background:var(--bg-alt);color:var(--gray-900)}
.filter-price input:focus{outline:0;border-color:var(--brand)}

/* Pagination */
.pagination{display:flex;justify-content:center;gap:6px;margin-top:50px;flex-wrap:wrap}
.pagination button,.pagination a{
  min-width:40px;height:40px;border-radius:10px;border:1px solid var(--line);background:var(--white);
  color:var(--gray-700);font-family:'Space Grotesk',sans-serif;font-size:.86rem;font-weight:600;
  transition:all .2s var(--ease);padding:0 12px;display:inline-flex;align-items:center;justify-content:center;
}
.pagination button:hover,.pagination a:hover{border-color:var(--brand);color:var(--brand)}
.pagination .active{background:var(--brand);color:var(--white);border-color:var(--brand)}
.pagination .sep{border:0;background:transparent}

/* ===============  ABOUT  =============== */
.ab-hero{
  padding:80px 0 100px;background:var(--bg-mint);border-bottom:1px solid var(--g-100);text-align:center;
  position:relative;overflow:hidden;
}
.ab-hero::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:
    radial-gradient(circle at 20% 20%,rgba(99,193,187,.2),transparent 40%),
    radial-gradient(circle at 80% 80%,rgba(99,193,187,.15),transparent 40%);
}
.ab-hero .container{max-width:900px;position:relative}
.ab-hero h1{font-size:clamp(2.6rem,5vw,4.4rem);line-height:1.08;margin:12px 0 22px;letter-spacing:-.02em}
.ab-hero p{font-size:1.15rem;color:var(--gray-600);max-width:700px;margin:0 auto;line-height:1.7}

/* Mission section */
.ab-mission{padding:120px 0;background:var(--white)}
.ab-mission-grid{display:grid;grid-template-columns:1fr 1.2fr;gap:80px;align-items:center}
.ab-visual{
  aspect-ratio:4/5;border-radius:var(--radius);overflow:hidden;background:var(--bg-mint);
  border:1px solid var(--g-100);display:grid;place-items:center;position:relative;
}
.ab-visual svg{width:90%;height:90%}

/* Values */
.ab-values{padding:120px 0;background:var(--bg-alt)}
.ab-v-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.ab-v{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:40px 30px;transition:all .35s var(--ease)}
.ab-v:hover{transform:translateY(-4px);border-color:var(--brand);box-shadow:var(--shadow)}
.ab-v .num{font-family:'Space Grotesk',sans-serif;font-size:.8rem;color:var(--brand);letter-spacing:.16em;font-weight:700}
.ab-v h3{font-size:1.5rem;margin:10px 0 10px;font-family:'Manrope',sans-serif;letter-spacing:-.01em}
.ab-v p{color:var(--muted);margin:0;font-size:.92rem;line-height:1.65}

/* Timeline */
.ab-timeline{padding:120px 0;background:var(--white)}
.ab-tl{max-width:880px;margin:0 auto;display:flex;flex-direction:column;gap:44px}
.ab-tl-item{display:grid;grid-template-columns:140px 1fr;gap:36px;align-items:flex-start}
.ab-tl-year{
  font-family:'Space Grotesk',sans-serif;font-size:2.2rem;color:var(--brand);font-weight:700;line-height:1;
  letter-spacing:-.02em;position:relative;padding-right:36px;
}
.ab-tl-year::after{content:"";position:absolute;right:0;top:10px;bottom:-10px;width:2px;background:var(--g-200)}
.ab-tl-item:last-child .ab-tl-year::after{display:none}
.ab-tl-body h3{font-size:1.3rem;margin-bottom:8px;font-family:'Manrope',sans-serif}
