  display:grid;place-items:center;font-size:1.2rem;box-shadow:0 10px 30px rgba(46,133,127,.4);
  animation:bounce 2s ease-in-out infinite;
}
.ct-map-pin::after{
  content:"";position:absolute;top:100%;left:50%;transform:translateX(-50%);
  border:10px solid transparent;border-top-color:var(--brand);
}
@keyframes bounce{0%,100%{transform:translate(-50%,-100%)}50%{transform:translate(-50%,-110%)}}
.ct-map-badge{
  position:absolute;bottom:20px;left:20px;background:var(--white);border:1px solid var(--line);
