/* ===============  POLICY / LEGAL SHARED LAYOUT  =============== */
.policy-hero{padding:50px 0 30px;background:var(--bg-mint);border-bottom:1px solid var(--g-100)}
.policy-hero h1{font-size:clamp(2rem,3.6vw,3rem);margin:10px 0 12px}
.policy-hero p{color:var(--gray-600);max-width:720px;margin:0;line-height:1.7}
.policy-hero .updated{display:inline-flex;align-items:center;gap:8px;margin-top:16px;font-size:.8rem;color:var(--muted);font-family:'Space Grotesk',sans-serif}
.policy-hero .updated i{color:var(--brand)}

.policy-wrap{padding:50px 0 100px;background:var(--white)}
.policy-layout{display:grid;grid-template-columns:280px 1fr;gap:50px;align-items:flex-start;max-width:1180px;margin:0 auto}
.policy-side{
  position:sticky;top:140px;background:var(--bg-alt);border:1px solid var(--line);border-radius:var(--radius);padding:22px;
}
.policy-side h5{margin-bottom:14px;color:var(--brand)}
.policy-side nav ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:2px}
.policy-side nav a{
  display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:8px;
  font-size:.88rem;color:var(--gray-700);transition:all .2s var(--ease);
}
.policy-side nav a:hover{background:var(--white);color:var(--brand)}
.policy-side nav a.active{background:var(--brand);color:var(--white);font-weight:600}
.policy-side nav a i{font-size:.82rem;width:16px;text-align:center}
.policy-help{margin-top:20px;padding:20px;background:var(--gray-900);color:var(--white);border-radius:12px}
.policy-help strong{color:var(--white);display:block;margin-bottom:6px;font-size:.96rem}
.policy-help p{color:rgba(255,255,255,.7);font-size:.82rem;margin:0 0 12px;line-height:1.5}
.policy-help a{color:var(--g-300);font-weight:700;font-size:.86rem}

.policy-content{padding:0 10px 0 0}
.policy-content h2{font-size:1.6rem;margin:40px 0 14px;padding-top:20px;border-top:1px solid var(--line);letter-spacing:-.01em}
.policy-content h2:first-child{margin-top:0;padding-top:0;border-top:0}
.policy-content h3{font-size:1.1rem;margin:24px 0 10px;font-family:'Manrope',sans-serif;font-weight:700}
.policy-content p{color:var(--gray-700);line-height:1.85;margin:0 0 14px;font-size:.96rem}
.policy-content p strong{color:var(--gray-900)}
.policy-content ul,.policy-content ol{color:var(--gray-700);padding-left:22px;margin:0 0 16px;line-height:1.85}
.policy-content li{padding:3px 0}
.policy-content li::marker{color:var(--brand)}
.policy-content table{width:100%;border-collapse:collapse;margin:16px 0 24px;border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}
.policy-content th,.policy-content td{padding:14px 18px;text-align:left;border-bottom:1px solid var(--line);font-size:.9rem;color:var(--gray-700)}
.policy-content th{font-size:.74rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--gray-600);background:var(--bg-alt)}
.policy-content tr:last-child td{border-bottom:0}
.policy-content .alert{
  margin:18px 0 24px;padding:18px 22px;background:var(--bg-mint);border-left:3px solid var(--brand);border-radius:0 10px 10px 0;
  display:grid;grid-template-columns:auto 1fr;gap:14px;align-items:flex-start;
}
.policy-content .alert i{color:var(--brand);font-size:1.2rem;padding-top:2px}
.policy-content .alert strong{display:block;margin-bottom:4px;color:var(--gray-900);font-size:.94rem}
.policy-content .alert p{margin:0;font-size:.88rem}

/* ===============  SCIENCE (knowledge-heavy)  =============== */
.sci-hero{padding:70px 0 80px;background:var(--bg-mint);border-bottom:1px solid var(--g-100);position:relative;overflow:hidden}
.sci-hero::before{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:radial-gradient(circle at 80% 20%,rgba(99,193,187,.2),transparent 50%);
}
.sci-hero-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;position:relative}
.sci-method{padding:100px 0;background:var(--white)}
.sci-method-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}
.method-card{background:var(--bg-mint);border:1px solid var(--g-100);border-radius:var(--radius);padding:38px 28px;transition:all .3s var(--ease)}
.method-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--brand)}
.method-card .phase{font-family:'Space Grotesk',sans-serif;font-size:.72rem;color:var(--brand);letter-spacing:.2em;font-weight:700;text-transform:uppercase}
.method-card h3{font-size:1.3rem;margin:8px 0 10px}
.method-card p{color:var(--gray-600);margin:0;font-size:.9rem;line-height:1.65}

/* Actives grid (dược chất) */
.actives{padding:100px 0;background:var(--bg-alt)}
.actives-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.active-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:26px 24px;
  display:flex;flex-direction:column;gap:10px;transition:all .3s var(--ease);
}
.active-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--brand)}
.active-card .pct{
  display:inline-block;align-self:flex-start;font-family:'Space Grotesk',sans-serif;
  background:var(--bg-mint);color:var(--brand);font-size:.78rem;font-weight:700;
  padding:4px 10px;border-radius:6px;letter-spacing:.06em;
}
.active-card strong{font-size:1.05rem;color:var(--gray-900);font-weight:700;letter-spacing:-.005em}
.active-card em{color:var(--muted);font-style:normal;font-size:.78rem;font-family:'Space Grotesk',sans-serif}
.active-card p{color:var(--gray-600);font-size:.86rem;line-height:1.55;margin:0}

/* ===============  SAFETY PILLARS EXPANDED  =============== */
.safety-blacklist{padding:100px 0;background:var(--white)}
.blacklist-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}
.blist-item{
  background:var(--bg-alt);border:1px solid var(--line);border-radius:10px;padding:16px 18px;
  display:flex;align-items:center;gap:12px;
}
.blist-item i{color:#C04A3C;width:20px;font-size:.92rem}
.blist-item strong{font-size:.88rem;color:var(--gray-900);font-weight:700;display:block}
.blist-item small{color:var(--muted);font-size:.74rem}

.safety-commit{padding:100px 0;background:var(--bg-alt)}
.commit-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}
.commit-card{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:36px;display:grid;grid-template-columns:72px 1fr;gap:24px;align-items:flex-start;transition:all .3s var(--ease)}
.commit-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:var(--brand)}
.commit-card .c-icon{width:72px;height:72px;border-radius:50%;background:var(--bg-mint);color:var(--brand);display:grid;place-items:center;font-size:1.6rem;border:1px solid var(--g-100)}
.commit-card h3{font-size:1.25rem;margin-bottom:10px}
.commit-card p{color:var(--gray-600);margin:0 0 10px;line-height:1.7;font-size:.92rem}
.commit-card ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:6px}
.commit-card ul li{font-size:.86rem;color:var(--gray-700);display:flex;align-items:center;gap:10px}
.commit-card ul li i{color:var(--brand);font-size:.72rem}

/* ===============  CAREERS  =============== */
.careers-hero{padding:60px 0 70px;background:var(--bg-mint);border-bottom:1px solid var(--g-100)}
.careers-hero-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center}
.careers-stats{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:24px}
.careers-stats > div{background:var(--white);border:1px solid var(--g-100);border-radius:12px;padding:20px;text-align:center}
.careers-stats strong{font-family:'Space Grotesk',sans-serif;font-size:1.8rem;color:var(--brand);display:block;line-height:1;font-weight:700;letter-spacing:-.02em}
.careers-stats span{font-size:.78rem;color:var(--muted);margin-top:6px;display:block}

.careers-values{padding:100px 0;background:var(--white)}
.careers-vals{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}
.cv{text-align:center;padding:28px 20px;border-radius:12px;background:var(--bg-mint);border:1px solid var(--g-100);transition:all .3s var(--ease)}
.cv:hover{background:var(--white);border-color:var(--brand);transform:translateY(-4px);box-shadow:var(--shadow)}
.cv i{font-size:2rem;color:var(--brand);margin-bottom:12px}
.cv strong{display:block;font-size:.98rem;color:var(--gray-900);margin-bottom:4px}
.cv span{font-size:.82rem;color:var(--muted);line-height:1.5}

.jobs{padding:100px 0;background:var(--bg-alt)}
.jobs-filter{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-bottom:40px}
.job-list{display:flex;flex-direction:column;gap:14px;max-width:960px;margin:0 auto}
.job-card{
  background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:26px 30px;
  display:grid;grid-template-columns:1fr auto auto auto;gap:24px;align-items:center;transition:all .3s var(--ease);
}
.job-card:hover{border-color:var(--brand);box-shadow:var(--shadow);transform:translateX(4px)}
.job-card h3{font-size:1.1rem;margin-bottom:4px;font-weight:700}
.job-card .meta{display:flex;gap:18px;flex-wrap:wrap;color:var(--muted);font-size:.82rem}
