.job-dept{font-family:'Space Grotesk',sans-serif;font-size:.72rem;letter-spacing:.12em;color:var(--brand);font-weight:700;text-transform:uppercase}
.job-salary{font-family:'Space Grotesk',sans-serif;font-weight:700;color:var(--gray-900)}
.job-apply{font-size:.78rem;font-weight:700;color:var(--brand);display:inline-flex;align-items:center;gap:6px;transition:gap .2s var(--ease)}
.job-card:hover .job-apply{gap:12px}

