.gift-hero{padding:60px 0 70px;background:var(--bg-mint);border-bottom:1px solid var(--g-100);text-align:center}
.gift-hero h1{font-size:clamp(2.4rem,4.5vw,3.6rem);margin:10px 0 16px}
.gift-hero p{max-width:680px;margin:0 auto 26px;color:var(--gray-600);line-height:1.7}
.gift-occasions{display:flex;gap:10px;flex-wrap:wrap;justify-content:center}
