.gift-body{padding:26px 26px 28px;display:flex;flex-direction:column;gap:10px;flex:1}
.gift-body h3{font-size:1.2rem;line-height:1.3}
.gift-items{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:4px;color:var(--gray-600);font-size:.84rem}
.gift-items li{display:flex;align-items:center;gap:8px}
.gift-items li i{color:var(--brand);font-size:.7rem}
.gift-body .price-row{margin-top:auto}

/* ===============  DEALER  =============== */
.dealer-hero{
  padding:80px 0 100px;
  background:linear-gradient(135deg,var(--gray-900) 0%,var(--g-900) 100%);
  color:var(--white);border-bottom:3px solid var(--brand);position:relative;overflow:hidden;
}
.dealer-hero::before{
  content:"";position:absolute;inset:0;
  background:radial-gradient(circle at 80% 20%,rgba(99,193,187,.2),transparent 50%);pointer-events:none;
}
.dealer-hero-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center;position:relative}
.dealer-hero h1{color:var(--white);font-size:clamp(2.4rem,4.5vw,3.8rem);margin:10px 0 16px}
.dealer-hero h1 .hl{color:var(--g-300)}
.dealer-hero h1 .hl::after{background:rgba(99,193,187,.3)}
.dealer-hero p{color:rgba(255,255,255,.75);font-size:1.05rem;max-width:560px;margin:0 0 30px;line-height:1.7}
.dealer-hero-stats{display:flex;gap:30px;flex-wrap:wrap;padding-top:24px;border-top:1px solid rgba(255,255,255,.15)}
.dealer-hero-stats strong{font-family:'Space Grotesk',sans-serif;font-size:2rem;color:var(--g-300);line-height:1;font-weight:700;display:block;letter-spacing:-.02em}
.dealer-hero-stats span{font-size:.74rem;letter-spacing:.08em;color:rgba(255,255,255,.6);text-transform:uppercase;margin-top:6px;display:block}

.dealer-tiers{padding:100px 0;background:var(--white)}
.tier-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.tier-pane{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:40px 30px;transition:all .3s var(--ease)}
.tier-pane:hover{transform:translateY(-6px);box-shadow:var(--shadow);border-color:var(--brand)}
.tier-pane.featured{background:var(--gray-900);color:var(--white);border-color:var(--gray-900);position:relative}
.tier-pane.featured::before{content:"PHỔ BIẾN NHẤT";position:absolute;top:-12px;left:50%;transform:translateX(-50%);background:var(--brand);color:var(--white);font-family:'Space Grotesk',sans-serif;font-size:.68rem;letter-spacing:.2em;font-weight:700;padding:5px 14px;border-radius:999px}
.tier-pane h3{font-size:1.4rem;margin-bottom:6px}
.tier-pane.featured h3{color:var(--white)}
.tier-level{font-family:'Space Grotesk',sans-serif;font-size:.76rem;letter-spacing:.2em;color:var(--brand);font-weight:700;text-transform:uppercase}
.tier-pane.featured .tier-level{color:var(--g-300)}
.tier-disc{font-family:'Space Grotesk',sans-serif;font-size:3rem;color:var(--gray-900);font-weight:700;letter-spacing:-.03em;margin:14px 0 4px;line-height:1}
.tier-pane.featured .tier-disc{color:var(--g-300)}
.tier-min{font-size:.82rem;color:var(--muted);margin-bottom:24px}
.tier-pane.featured .tier-min{color:rgba(255,255,255,.6)}
.tier-pane ul{list-style:none;padding:0;margin:0 0 24px;display:flex;flex-direction:column;gap:10px}
.tier-pane ul li{display:flex;align-items:flex-start;gap:10px;font-size:.88rem;color:var(--gray-700)}
.tier-pane.featured ul li{color:rgba(255,255,255,.85)}
.tier-pane ul li i{color:var(--brand);font-size:.8rem;padding-top:4px}
.tier-pane.featured ul li i{color:var(--g-300)}

.dealer-benefits{padding:100px 0;background:var(--bg-alt)}
.db-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.db-card{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:30px 28px;transition:all .3s var(--ease)}
.db-card:hover{border-color:var(--brand);transform:translateY(-4px);box-shadow:var(--shadow)}
.db-card .db-icon{width:56px;height:56px;border-radius:12px;background:var(--bg-mint);color:var(--brand);display:grid;place-items:center;font-size:1.3rem;margin-bottom:18px;border:1px solid var(--g-100)}
.db-card h3{font-size:1.1rem;margin-bottom:8px}
.db-card p{color:var(--gray-600);margin:0;font-size:.9rem;line-height:1.65}

/* ===============  FAQ page  =============== */
.faq-hero{padding:60px 0 40px;background:var(--bg-mint);border-bottom:1px solid var(--g-100);text-align:center}
.faq-hero h1{font-size:clamp(2rem,3.6vw,3rem);margin:10px 0 16px}
.faq-hero p{max-width:620px;margin:0 auto;color:var(--gray-600);line-height:1.7}
.faq-search{max-width:560px;margin:24px auto 0;position:relative}
.faq-search input{
  width:100%;padding:16px 52px 16px 20px;border:1px solid var(--g-200);border-radius:12px;
  background:var(--white);font-family:inherit;font-size:.96rem;color:var(--gray-900);box-shadow:var(--shadow-sm);
}
.faq-search input:focus{outline:0;border-color:var(--brand);box-shadow:0 0 0 3px rgba(99,193,187,.2)}
.faq-search i{position:absolute;right:20px;top:50%;transform:translateY(-50%);color:var(--brand)}

.faq-body{padding:80px 0 100px;background:var(--white)}
.faq-layout{display:grid;grid-template-columns:260px 1fr;gap:50px;max-width:1180px;margin:0 auto}
.faq-side{position:sticky;top:140px;align-self:flex-start}
.faq-side nav ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:2px}
.faq-side nav a{display:flex;align-items:center;justify-content:space-between;padding:12px 16px;border-radius:10px;font-size:.88rem;color:var(--gray-700);transition:all .2s var(--ease)}
.faq-side nav a:hover{background:var(--bg-mint);color:var(--brand)}
.faq-side nav a.active{background:var(--brand);color:var(--white);font-weight:600}
.faq-side nav a small{font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:.8rem;opacity:.7}
.faq-cat-block{margin-bottom:40px}
.faq-cat-block h2{font-size:1.4rem;margin-bottom:18px;padding-bottom:10px;border-bottom:2px solid var(--brand);display:inline-block}

/* ===============  TRACK ORDER  =============== */
.track-hero{
  padding:70px 0 90px;
  background:
    radial-gradient(circle at 50% 100%,rgba(99,193,187,.2),transparent 60%),
    var(--bg-mint);
  border-bottom:1px solid var(--g-100);text-align:center;
}
.track-hero h1{font-size:clamp(2rem,3.6vw,3rem);margin:10px 0 14px}
.track-hero p{color:var(--gray-600);max-width:620px;margin:0 auto 34px;line-height:1.7}
.track-form{
  max-width:640px;margin:0 auto;display:grid;grid-template-columns:1fr 1fr auto;gap:10px;
  background:var(--white);padding:10px;border-radius:14px;box-shadow:var(--shadow);
  border:1px solid var(--line);
}
.track-form input{
  padding:14px 18px;border:1px solid var(--line);border-radius:10px;font-family:inherit;font-size:.92rem;
  background:var(--bg-alt);color:var(--gray-900);
}
.track-form input:focus{outline:0;border-color:var(--brand);background:var(--white);box-shadow:0 0 0 3px rgba(99,193,187,.2)}
.track-form button{background:var(--brand);color:var(--white);border-radius:10px;padding:0 26px;font-weight:700;font-family:inherit;font-size:.84rem;letter-spacing:.04em}
.track-form button:hover{background:var(--g-700)}

/* Order result */
.track-result{padding:70px 0;background:var(--white)}
.order-card{
  background:var(--white);border:1px solid var(--line);border-radius:calc(var(--radius) + 4px);
  max-width:960px;margin:0 auto;overflow:hidden;box-shadow:var(--shadow-sm);
}
.order-head{padding:26px 32px;background:var(--gray-900);color:var(--white);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:20px}
.order-head strong{font-family:'Space Grotesk',sans-serif;font-size:1.2rem;font-weight:700}
.order-head span{font-size:.82rem;color:rgba(255,255,255,.65);display:block;margin-top:2px}
.order-status{display:inline-flex;align-items:center;gap:8px;padding:8px 16px;background:var(--brand);border-radius:999px;color:var(--white);font-size:.8rem;font-weight:700}
.order-status::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--white);animation:blink 1.5s infinite}
@keyframes blink{50%{opacity:.3}}

.order-steps{padding:40px 32px;background:var(--bg-mint)}
.order-timeline{display:flex;justify-content:space-between;position:relative}
.order-timeline::before{content:"";position:absolute;top:20px;left:10%;right:10%;height:2px;background:var(--g-200);z-index:0}
.order-timeline .done-line{position:absolute;top:20px;left:10%;height:2px;background:var(--brand);z-index:1;transition:width .5s ease}
.ot-step{position:relative;z-index:2;display:flex;flex-direction:column;align-items:center;gap:8px;text-align:center;flex:1}
.ot-step .o-dot{width:42px;height:42px;border-radius:50%;background:var(--white);border:2px solid var(--g-200);color:var(--muted);display:grid;place-items:center;font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:.88rem}
.ot-step.done .o-dot,.ot-step.active .o-dot{background:var(--brand);border-color:var(--brand);color:var(--white)}
.ot-step.active .o-dot{box-shadow:0 0 0 6px rgba(99,193,187,.25)}
.ot-step strong{font-size:.82rem;color:var(--gray-900);font-weight:700}
.ot-step span{font-size:.7rem;color:var(--muted);font-family:'Space Grotesk',sans-serif}
.ot-step.done strong,.ot-step.active strong{color:var(--brand)}

.order-body{display:grid;grid-template-columns:1.4fr 1fr;gap:40px;padding:32px;background:var(--white)}
.order-items{display:flex;flex-direction:column;gap:14px}
.order-addr h4,.order-items-head{font-size:.8rem;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin-bottom:10px;font-weight:700;font-family:'Space Grotesk',sans-serif}
.order-item{display:grid;grid-template-columns:60px 1fr auto;gap:14px;align-items:center;padding:12px 0;border-bottom:1px dashed var(--line)}
.order-item:last-child{border-bottom:0}
.order-item .bottle-svg{width:100%}
.order-item-media{background:var(--bg-mint);border:1px solid var(--g-100);border-radius:8px;aspect-ratio:1;display:grid;place-items:center;padding:4px}
.order-item strong{display:block;font-size:.9rem}
.order-item span{font-size:.78rem;color:var(--muted)}
.order-item .price{font-family:'Space Grotesk',sans-serif;font-weight:700}

.order-addr{padding:20px;background:var(--bg-alt);border-radius:12px}
.order-addr p{margin:0 0 6px;font-size:.9rem;color:var(--gray-700);line-height:1.55}
.order-addr p strong{color:var(--gray-900);font-weight:700}
.order-addr .row{display:flex;justify-content:space-between;padding:6px 0;font-size:.88rem}
.order-addr .row.total{border-top:1px solid var(--line);margin-top:10px;padding-top:14px;font-weight:700}

/* ===============  FAKE REPORT  =============== */
.fake-hero{
  padding:60px 0 70px;
  background:linear-gradient(135deg,#2E1413 0%,var(--gray-900) 100%);
  color:var(--white);border-bottom:3px solid var(--brand);
}
.fake-hero-grid{display:grid;grid-template-columns:1.2fr 1fr;gap:60px;align-items:center}
.fake-hero h1{color:var(--white);font-size:clamp(2rem,3.8vw,3.2rem);margin:10px 0 14px}
.fake-hero h1 .hl{color:var(--g-300)}
.fake-hero h1 .hl::after{background:rgba(99,193,187,.3)}
.fake-hero p{color:rgba(255,255,255,.75);margin:0 0 24px;line-height:1.7}
.fake-check{
  background:var(--white);color:var(--gray-900);border-radius:calc(var(--radius) + 4px);padding:40px;
  box-shadow:var(--shadow-lg);
}
.fake-check h3{margin-bottom:8px;font-size:1.3rem}
.fake-check p{color:var(--muted);font-size:.9rem;margin:0 0 20px}
.fake-check input{
  width:100%;padding:14px 18px;border:1px solid var(--line);border-radius:10px;
  font-family:'Space Grotesk',sans-serif;font-size:1rem;letter-spacing:.1em;text-transform:uppercase;
  background:var(--bg-alt);color:var(--gray-900);margin-bottom:12px;
}
.fake-check input:focus{outline:0;border-color:var(--brand);background:var(--white);box-shadow:0 0 0 3px rgba(99,193,187,.2)}

.fake-signs{padding:80px 0;background:var(--bg-alt)}
.fake-signs-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.sign-card{background:var(--white);border:1px solid var(--line);border-radius:var(--radius);padding:26px;text-align:center}
.sign-card i{width:48px;height:48px;border-radius:50%;background:#FDE7E2;color:#B9503E;display:grid;place-items:center;font-size:1.3rem;margin:0 auto 14px}
.sign-card strong{display:block;font-size:1rem;color:var(--gray-900);margin-bottom:6px}
.sign-card p{color:var(--muted);font-size:.82rem;margin:0;line-height:1.55}

/* ===============  responsive additions ============ */
@media (max-width: 1080px){
  .sci-hero-grid,.careers-hero-grid,.dealer-hero-grid,.fake-hero-grid{grid-template-columns:1fr;gap:40px}
  .sci-method-grid,.actives-grid,.careers-vals,.tier-grid,.db-grid,.blacklist-grid,.gift-grid,.fake-signs-grid{grid-template-columns:repeat(2,1fr)}
  .commit-grid{grid-template-columns:1fr}
  .policy-layout,.faq-layout{grid-template-columns:1fr}
  .policy-side,.faq-side{position:static}
  .track-form{grid-template-columns:1fr;padding:14px}
  .job-card{grid-template-columns:1fr 1fr;gap:10px}
  .order-body{grid-template-columns:1fr}
}
@media (max-width: 640px){
  .sci-method-grid,.actives-grid,.careers-vals,.tier-grid,.db-grid,.blacklist-grid,.gift-grid,.fake-signs-grid{grid-template-columns:1fr}
  .order-timeline{flex-direction:column;gap:16px}
  .order-timeline::before,.order-timeline .done-line{display:none}
  .order-head,.order-steps,.order-body{padding:22px}
}

