/* Detoxblanc — unified header/footer loader
   Tự động thay thế announce/topbar/header + newsletter/footer/floating
   bằng partials chuẩn, để layout đồng nhất trên mọi trang.                */

(async function(){
  // Chỉ chạy khi serve qua HTTP (fetch cần origin)
  if (location.protocol === 'file:') return;

  const [headHtml, footHtml] = await Promise.all([
    fetch('assets/partials/header.html').then(r => r.ok ? r.text() : ''),
    fetch('assets/partials/footer.html').then(r => r.ok ? r.text() : '')
  ]);

  // ===== SWAP HEADER =====
  const announce = document.querySelector('body > .announce');
  const topbar   = document.querySelector('body > .topbar');
  const header   = document.querySelector('body > header.site-header');
  if (headHtml && announce && header) {
    // Remove topbar và header hiện tại (announce sẽ được thay)
    topbar?.remove();
    header.remove();
    const wrap = document.createElement('template');
    wrap.innerHTML = headHtml.trim();
    announce.replaceWith(wrap.content);
  } else if (headHtml && !announce) {
    // Page không có header — chèn vào đầu body
    const tpl = document.createElement('template');
    tpl.innerHTML = headHtml.trim();
    document.body.prepend(tpl.content);
  }

  // ===== SWAP FOOTER =====
  const existingNewsletter = document.querySelector('body > .newsletter');
  const footer             = document.querySelector('body > footer.site-footer');
  const floating           = document.querySelector('body > .floating');
  if (footHtml && footer) {
    existingNewsletter?.remove();
    floating?.remove();
    const tpl = document.createElement('template');
    tpl.innerHTML = footHtml.trim();
    footer.replaceWith(tpl.content);
  } else if (footHtml) {
    const tpl = document.createElement('template');
    tpl.innerHTML = footHtml.trim();
    document.body.append(tpl.content);
  }

  // ===== MARK ACTIVE NAV =====
  const page = (location.pathname.split('/').pop() || 'index.html').toLowerCase();
  const map = {
    'index.html':   'index',
    '':             'index',
    'category.html':'category',
    'product.html': 'category',
    'about.html':   'about',
    'science.html': 'science',
    'safety.html':  'about',
    'careers.html': 'about',
    'ritual.html':  'ritual',
    'article.html': 'article',
    'journal.html': 'article',
    'contact.html': 'contact',
    'dealer.html':  'contact',
    'gift.html':    'category',
  };
  const active = map[page] || null;
  if (active) {
    document.querySelectorAll('.main-nav [data-nav="'+ active +'"]').forEach(a => {
      a.classList.add('active');
    });
  }

  // ===== RE-ATTACH behaviors that depend on injected DOM =====
  reinitHeader();
  reinitFooter();
  // Nếu app.js đã chạy rồi — các event delegation trong nó sẽ tự hoạt động.
  // Reinit các handler cụ thể cần query-selector ngay bây giờ:
  reinitScrollStateAndAnchors();
})();

function reinitHeader(){
  // Burger mở/đóng main-nav trên mobile
  document.querySelector('.burger')?.addEventListener('click', () => {
    document.querySelector('.main-nav')?.classList.toggle('open');
  });
}

function reinitFooter(){
  // Back to top
  document.getElementById('toTop')?.addEventListener('click', () => {
    window.scrollTo({ top:0, behavior:'smooth' });
  });
}

function reinitScrollStateAndAnchors(){
  const header = document.querySelector('.site-header');
  const toTop  = document.getElementById('toTop');
  const onScroll = () => {
    header?.classList.toggle('scrolled', window.scrollY > 20);
    toTop?.classList.toggle('show', window.scrollY > 500);
  };
  window.addEventListener('scroll', onScroll, { passive:true });
  onScroll();

  // Smooth anchor
  document.querySelectorAll('a[href^="#"]').forEach(a => {
    a.addEventListener('click', e => {
      const id = a.getAttribute('href');
      if (id && id.length > 1) {
        const el = document.querySelector(id);
        if (el){ e.preventDefault(); el.scrollIntoView({ behavior:'smooth', block:'start' }); }
      }
    });
  });
}

