});

// Nav scroll-active + header scrolled state + back-to-top
const sections = document.querySelectorAll('section[id], header[id]');
const navLinks = document.querySelectorAll('.main-nav > a, .nav-item > a');
const header  = document.querySelector('.site-header');
const toTop   = document.getElementById('toTop');

function onScroll(){
  const y = window.scrollY + 160;
  let current = 'home';
  sections.forEach(s => { if (s.offsetTop <= y) current = s.id; });
  navLinks.forEach(l => {
    const href = l.getAttribute('href') || '';
    l.classList.toggle('active', href === '#' + current);
  });
  header?.classList.toggle('scrolled', window.scrollY > 20);
  toTop?.classList.toggle('show', window.scrollY > 500);
}
window.addEventListener('scroll', onScroll, { passive:true });
onScroll();

// Smooth anchor
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', e => {
    const id = a.getAttribute('href');
    if (id.length > 1) {
      const el = document.querySelector(id);
      if (el){ e.preventDefault(); el.scrollIntoView({ behavior:'smooth', block:'start' }); }
    }
  });
});
toTop?.addEventListener('click', () => window.scrollTo({ top:0, behavior:'smooth' }));

// Burger (mobile)
document.querySelector('.burger')?.addEventListener('click', () => {
  document.querySelector('.main-nav')?.classList.toggle('open');
});

// Reveal on scroll
const io = new IntersectionObserver((entries) => {
  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('in'); });
}, { threshold: 0.12 });
document.querySelectorAll(`
  .cat-card,.product-card,.tm-card,.news-card,
  .hero-copy,.hero-visual,.story-copy,.story-visual,
  .ing-visual,.ing-copy,.sci-stat,.ritual-step,.value-card,
  .statement-head,.ba-slider,.ba-copy,.finder-card,.certstrip li
`).forEach(el => { el.classList.add('reveal'); io.observe(el); });

