@media (max-width: 640px){
  .pdp-thumbs{grid-template-columns:repeat(4,1fr)}
  .pdp-benefits,.pdp-trust,.howto{grid-template-columns:1fr 1fr}
  .cart-item{grid-template-columns:72px 1fr;gap:12px}
  .cart-item-right{grid-column:1/-1;flex-direction:row;justify-content:space-between;align-items:center}
  .bundle-card{padding:30px 22px}
  .co-section{padding:22px}
}

/* =========================================================
   SPRINT 1 — Login · Account · Wishlist · Search · Journal
              Terms · Cookie · Sitemap
   ========================================================= */

/* ---------- Auth (login + register) ---------- */
.auth-wrap{padding:40px 0 80px;background:var(--bg-mint)}
.auth-grid{
  display:grid;grid-template-columns:1fr 1.1fr;gap:0;
  max-width:1080px;margin:0 auto;background:var(--white);
  border:1px solid var(--g-100);border-radius:22px;overflow:hidden;
  box-shadow:0 20px 60px rgba(31,102,97,.08);
}
.auth-side{
  padding:48px 40px;color:#fff;position:relative;
  background:linear-gradient(160deg,var(--g-700) 0%,var(--g-900) 100%);
  display:flex;flex-direction:column;justify-content:space-between;gap:28px;
}
.auth-side .eyebrow{color:var(--g-200)}
.auth-side h2{font-family:'Space Grotesk',sans-serif;font-size:2rem;line-height:1.15;margin:10px 0 16px;color:#fff}
.auth-side p{color:var(--g-100);line-height:1.7}
.auth-perks{display:grid;gap:14px;margin-top:22px}
.auth-perks li{display:flex;gap:12px;align-items:flex-start;list-style:none;color:var(--g-100)}
.auth-perks i{color:var(--g-300);margin-top:3px}
.auth-brand-mark{font-family:'Space Grotesk',sans-serif;letter-spacing:.18em;font-size:.8rem;color:var(--g-300)}
.auth-main{padding:48px 44px;display:flex;flex-direction:column;gap:22px}
.auth-tabs{display:flex;gap:4px;background:var(--g-50);padding:4px;border-radius:12px;width:fit-content}
.auth-tabs button{
  border:0;background:transparent;padding:10px 22px;border-radius:10px;
  font-weight:600;color:var(--ink-soft);cursor:pointer;font-family:inherit;
}
.auth-tabs button.active{background:var(--white);color:var(--g-700);box-shadow:0 2px 10px rgba(31,102,97,.08)}
.auth-panel{display:none;flex-direction:column;gap:16px}
.auth-panel.active{display:flex}
.auth-panel h3{font-family:'Space Grotesk',sans-serif;font-size:1.6rem;margin:0;color:var(--ink)}
.auth-field{display:flex;flex-direction:column;gap:6px}
.auth-field label{font-size:.85rem;font-weight:600;color:var(--ink-soft)}
.auth-field input{
  padding:13px 14px;border:1px solid var(--g-200);border-radius:10px;
  font-family:inherit;font-size:.95rem;background:var(--white);
}
.auth-field input:focus{outline:none;border-color:var(--g-500);box-shadow:0 0 0 4px rgba(99,193,187,.15)}
.auth-row{display:flex;justify-content:space-between;align-items:center;font-size:.88rem;color:var(--ink-soft)}
.auth-row a{color:var(--g-700);text-decoration:none;font-weight:600}
.auth-check{display:flex;gap:8px;align-items:flex-start;font-size:.85rem;color:var(--ink-soft);line-height:1.5}
.auth-check input{margin-top:4px}
.auth-submit{width:100%;padding:14px;font-weight:700}
.auth-divider{text-align:center;font-size:.82rem;color:var(--ink-soft);position:relative;margin:4px 0}
.auth-divider::before,.auth-divider::after{
  content:'';height:1px;background:var(--g-100);width:40%;position:absolute;top:50%;
}
.auth-divider::before{left:0}.auth-divider::after{right:0}
.auth-social{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.auth-social button{
  display:flex;align-items:center;justify-content:center;gap:10px;
  padding:12px;background:var(--white);border:1px solid var(--g-100);
  border-radius:10px;cursor:pointer;font-family:inherit;font-weight:600;
  color:var(--ink);transition:border-color .18s;
}
.auth-social button:hover{border-color:var(--g-400)}
.auth-social .fa-google{color:#ea4335}
.auth-social .fa-facebook-f{color:#1877f2}
.auth-foot{font-size:.86rem;color:var(--ink-soft);text-align:center}
.auth-foot a{color:var(--g-700);font-weight:600;text-decoration:none}

/* ---------- Account dashboard ---------- */
.acc-wrap{padding:40px 0 80px;background:var(--bg-mint)}
.acc-header{
  background:var(--white);border:1px solid var(--g-100);border-radius:16px;
  padding:26px 28px;display:flex;gap:22px;align-items:center;margin-bottom:22px;
}
.acc-avatar{
  width:64px;height:64px;border-radius:50%;
  background:linear-gradient(140deg,var(--g-500),var(--g-700));
  display:flex;align-items:center;justify-content:center;color:#fff;
  font-family:'Space Grotesk',sans-serif;font-size:1.4rem;font-weight:700;flex-shrink:0;
}
.acc-greet{flex:1}
.acc-greet h2{font-family:'Space Grotesk',sans-serif;font-size:1.3rem;margin:0 0 4px;color:var(--ink)}
.acc-greet span{color:var(--ink-soft);font-size:.9rem}
.acc-tier{
  padding:8px 16px;background:var(--g-50);color:var(--g-700);
  border-radius:100px;font-weight:700;font-size:.85rem;
  display:inline-flex;gap:8px;align-items:center;
}
.acc-tier i{color:var(--g-500)}
.acc-layout{display:grid;grid-template-columns:260px 1fr;gap:22px;align-items:start}
.acc-side{
  background:var(--white);border:1px solid var(--g-100);border-radius:16px;
  padding:16px;display:flex;flex-direction:column;gap:4px;
  position:sticky;top:90px;
}
.acc-side a{
  display:flex;gap:12px;align-items:center;padding:12px 14px;
  text-decoration:none;color:var(--ink-soft);border-radius:10px;
  font-size:.95rem;transition:background .18s,color .18s;
}
.acc-side a i{width:18px;text-align:center;color:var(--ink-soft)}
.acc-side a:hover{background:var(--g-50);color:var(--g-700)}
.acc-side a.active{background:var(--g-50);color:var(--g-700);font-weight:700}
.acc-side a.active i{color:var(--g-600)}
