.wl-header p{color:var(--ink-soft);margin:0}
.wl-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}
.wl-empty{
  padding:80px 30px;text-align:center;background:var(--white);
  border:1px dashed var(--g-200);border-radius:16px;
}
.wl-empty i{font-size:3rem;color:var(--g-300);margin-bottom:18px}
.wl-empty h3{font-family:'Space Grotesk',sans-serif;margin:0 0 8px;color:var(--ink)}
.wl-empty p{color:var(--ink-soft);margin:0 0 20px}

/* ---------- Search ---------- */
.search-hero{
  padding:50px 0 30px;background:linear-gradient(180deg,var(--bg-mint),var(--white));
  border-bottom:1px solid var(--g-100);
}
.search-form{
  display:flex;max-width:720px;margin:20px auto 0;gap:8px;
  background:var(--white);border:1px solid var(--g-200);
  border-radius:14px;padding:8px;box-shadow:0 10px 30px rgba(31,102,97,.06);
}
.search-form input{
  flex:1;border:0;background:transparent;padding:12px 14px;
  font-family:inherit;font-size:1rem;
}
.search-form input:focus{outline:none}
.search-form button{padding:12px 24px}
.search-suggest{
  display:flex;gap:10px;justify-content:center;flex-wrap:wrap;
  margin-top:16px;font-size:.88rem;color:var(--ink-soft);
}
.search-suggest a{
  color:var(--g-700);text-decoration:none;padding:6px 12px;
  background:var(--white);border:1px solid var(--g-100);border-radius:100px;
}
.search-results{padding:40px 0 80px}
.search-stat{margin-bottom:20px;color:var(--ink-soft)}
.search-stat strong{color:var(--ink)}
.search-section{margin-bottom:40px}
.search-section h3{
  font-family:'Space Grotesk',sans-serif;font-size:1.15rem;margin:0 0 16px;
  padding-bottom:10px;border-bottom:1px solid var(--g-100);
  display:flex;justify-content:space-between;align-items:baseline;
}
.search-section h3 a{font-size:.82rem;color:var(--g-700);text-decoration:none;font-weight:600}
.search-article-row{
  display:grid;grid-template-columns:120px 1fr;gap:16px;padding:16px 0;
  border-bottom:1px solid var(--g-100);text-decoration:none;color:inherit;
}
.search-article-row:last-child{border-bottom:0}
.search-article-row .sa-img{
  aspect-ratio:16/10;background:var(--g-100);border-radius:8px;overflow:hidden;
  display:flex;align-items:center;justify-content:center;color:var(--g-500);font-size:1.4rem;
}
.search-article-row h4{font-family:'Space Grotesk',sans-serif;margin:0 0 6px;font-size:1.05rem;color:var(--ink)}
.search-article-row p{color:var(--ink-soft);font-size:.88rem;margin:0;line-height:1.6}
.search-article-row .sa-meta{font-size:.78rem;color:var(--ink-soft);margin-top:8px}

/* ---------- Journal index ---------- */
.journal-hero{padding:60px 0 30px;text-align:center;background:var(--bg-mint);border-bottom:1px solid var(--g-100)}
.journal-hero h1{font-family:'Space Grotesk',sans-serif;font-size:2.4rem;margin:8px 0 12px;color:var(--ink)}
.journal-hero p{color:var(--ink-soft);max-width:640px;margin:0 auto}
.journal-filter{
  display:flex;gap:10px;justify-content:center;flex-wrap:wrap;
  margin-top:26px;padding-bottom:10px;
}
.journal-filter .cat-chip{cursor:pointer}
.journal-featured{
  display:grid;grid-template-columns:1.3fr 1fr;gap:30px;
  padding:50px 0;align-items:center;
}
.journal-featured .jf-img{
  aspect-ratio:16/10;background:var(--g-100);border-radius:16px;
  display:flex;align-items:center;justify-content:center;color:var(--g-500);font-size:3rem;
}
.journal-featured .jf-copy .tag{margin-bottom:14px;display:inline-block}
.journal-featured h2{font-family:'Space Grotesk',sans-serif;font-size:2rem;margin:0 0 14px;line-height:1.2;color:var(--ink)}
.journal-featured .jf-excerpt{color:var(--ink-soft);line-height:1.8;margin-bottom:18px}
.journal-featured .jf-meta{display:flex;gap:16px;color:var(--ink-soft);font-size:.85rem;margin-bottom:22px}
.journal-grid{
  display:grid;grid-template-columns:repeat(3,1fr);gap:26px;
  padding-bottom:40px;
}
.journal-card{
  background:var(--white);border:1px solid var(--g-100);border-radius:14px;overflow:hidden;
  transition:transform .2s,box-shadow .2s;text-decoration:none;color:inherit;
  display:flex;flex-direction:column;
}
.journal-card:hover{transform:translateY(-4px);box-shadow:0 14px 40px rgba(31,102,97,.08)}
.journal-card .jc-img{
  aspect-ratio:16/10;background:var(--g-50);
  display:flex;align-items:center;justify-content:center;color:var(--g-500);font-size:2rem;
}
.journal-card .jc-body{padding:20px;display:flex;flex-direction:column;gap:10px;flex:1}
.journal-card .jc-tag{font-size:.72rem;letter-spacing:.14em;color:var(--g-700);font-weight:700;text-transform:uppercase}
.journal-card h3{font-family:'Space Grotesk',sans-serif;font-size:1.05rem;margin:0;line-height:1.35;color:var(--ink)}
.journal-card .jc-excerpt{color:var(--ink-soft);font-size:.88rem;line-height:1.6;margin:0;flex:1}
.journal-card .jc-meta{font-size:.78rem;color:var(--ink-soft);margin-top:4px}
.journal-pagi{
  display:flex;gap:6px;justify-content:center;align-items:center;
  padding:20px 0 60px;
}
.journal-pagi button,.journal-pagi a{
  width:40px;height:40px;border-radius:10px;border:1px solid var(--g-100);
  background:var(--white);color:var(--ink-soft);display:flex;align-items:center;
  justify-content:center;cursor:pointer;font-family:inherit;font-weight:600;
  text-decoration:none;transition:all .18s;
}
.journal-pagi a:hover{border-color:var(--g-400);color:var(--g-700)}
.journal-pagi .active{background:var(--g-700);color:#fff;border-color:var(--g-700)}

/* ---------- Sitemap ---------- */
.sitemap-wrap{padding:50px 0 80px}
.sitemap-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:30px}
.sitemap-col h4{
  font-family:'Space Grotesk',sans-serif;font-size:1rem;margin:0 0 14px;
  padding-bottom:10px;border-bottom:2px solid var(--g-400);color:var(--ink);
}
.sitemap-col ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:8px}
.sitemap-col a{color:var(--ink-soft);text-decoration:none;font-size:.92rem;transition:color .18s}
.sitemap-col a:hover{color:var(--g-700)}

/* ---------- Sprint 1 responsive ---------- */
@media (max-width: 1080px){
  .auth-grid{grid-template-columns:1fr}
  .auth-side{padding:36px 28px}
  .auth-main{padding:36px 28px}
  .acc-layout{grid-template-columns:1fr}
  .acc-side{position:static;flex-direction:row;flex-wrap:wrap;overflow-x:auto}
  .acc-side a{flex-shrink:0}
  .acc-stats{grid-template-columns:repeat(2,1fr)}
  .wl-grid,.journal-grid{grid-template-columns:repeat(2,1fr)}
  .journal-featured{grid-template-columns:1fr;gap:20px}
  .sitemap-grid{grid-template-columns:repeat(2,1fr)}
  .order-row{grid-template-columns:1fr;gap:8px}
  .order-row .btn{justify-self:start}
  .addr-grid{grid-template-columns:1fr}
}
@media (max-width: 640px){
  .wl-grid,.journal-grid{grid-template-columns:1fr}
  .acc-stats{grid-template-columns:1fr 1fr}
  .sitemap-grid{grid-template-columns:1fr}
  .auth-social{grid-template-columns:1fr}
  .search-article-row{grid-template-columns:80px 1fr}
}

