/* =========================================================
   DETOXBLANC — Dermatological Skincare
   Clinical tone: Green · Gray · White
   Type: Manrope (body) + Space Grotesk (display/numbers)
   ========================================================= */

:root{
  /* teals (signature #63C1BB) */
  --g-50:       #F2FAF9;
  --g-100:      #DFF4F2;
  --g-200:      #BFE7E3;
  --g-300:      #9DD8D3;
  --g-400:      #80CAC4;
  --g-500:      #63C1BB;   /* signature */
  --g-600:      #45A9A3;
  --g-700:      #2E857F;
  --g-800:      #1F6661;
  --g-900:      #144A46;

  /* grays */
  --white:      #FFFFFF;
  --gray-50:    #F7F9F8;
  --gray-100:   #EEF1EF;
  --gray-200:   #E0E4E2;
  --gray-300:   #C9CFCC;
  --gray-400:   #9AA29D;
  --gray-500:   #6B7571;
  --gray-600:   #4B5551;
  --gray-700:   #3B4441;
  --gray-800:   #262D2A;
  --gray-900:   #1A1F1D;

  /* semantic */
  --brand:      var(--g-600);
  --brand-soft: var(--g-100);
  --accent:     var(--g-500);
  --ink:        var(--gray-800);
  --muted:      var(--gray-500);
  --line:       var(--gray-200);
  --line-soft:  var(--gray-100);
  --bg:         var(--white);
  --bg-alt:     var(--gray-50);
  --bg-mint:    var(--g-50);
  --dark:       var(--gray-900);

  --radius:     14px;
  --radius-sm:  8px;
  --shadow-xs:  0 1px 2px rgba(20,31,29,.04);
  --shadow-sm:  0 2px 10px rgba(20,31,29,.05);
  --shadow:     0 10px 30px rgba(20,31,29,.07);
  --shadow-lg:  0 24px 60px rgba(20,31,29,.12);
  --ease:       cubic-bezier(.2,.7,.2,1);
  --container:  1280px;
}

