/* =========================================================================
   Detoxblanc Admin Console — shared design system
   Dùng cho admin.html, admin-products.html, admin-product-edit.html, …
   ========================================================================= */

/* ========== DESIGN TOKENS ========== */
:root{
  --a-n50:#F7F9FA; --a-n100:#EEF2F2; --a-n200:#E4EAE8; --a-n300:#CFD7D4;
  --a-n400:#A9B4B1; --a-n500:#7B8784; --a-n600:#5B6E69; --a-n700:#3D4D48;
  --a-n800:#263531; --a-n900:#0F1F1C; --a-n1000:#05100D;

  --a-brand:#63C1BB; --a-brand-2:#3AA39C; --a-brand-soft:#E4F4F2; --a-brand-ink:#0F3B37;

  --a-success:#1F9D6C; --a-success-soft:#E3F5EC;
  --a-warn:#B87B15;    --a-warn-soft:#FAECCF;
  --a-danger:#C93A3A;  --a-danger-soft:#FBE5E5;
  --a-info:#2C6BD4;    --a-info-soft:#E3ECFB;

  --a-bg:var(--a-n50); --a-surface:#FFFFFF; --a-surface-2:var(--a-n50);
  --a-line:var(--a-n200); --a-line-soft:var(--a-n100);

  --a-ink:var(--a-n900); --a-ink-2:var(--a-n600); --a-ink-3:var(--a-n500); --a-ink-4:var(--a-n400);

  --a-shadow-sm:0 1px 2px rgba(15,31,28,.04), 0 0 0 1px rgba(15,31,28,.04);
  --a-shadow-md:0 4px 14px rgba(15,31,28,.06), 0 0 0 1px rgba(15,31,28,.05);
  --a-shadow-lg:0 12px 30px rgba(15,31,28,.10), 0 0 0 1px rgba(15,31,28,.06);

  --a-r-sm:6px; --a-r:10px; --a-r-lg:14px; --a-r-xl:18px;

  --a-sidebar:256px;
  --a-topbar:60px;
}
@media (prefers-color-scheme: dark){
  :root{
    --a-bg:#0C1618; --a-surface:#121E20; --a-surface-2:#0E181A;
    --a-line:#1F2C2E; --a-line-soft:#18262A;
    --a-ink:#E9F0EE; --a-ink-2:#A9BDB8; --a-ink-3:#7B8F8A; --a-ink-4:#5A6F6A;
    --a-brand-soft:#13332E; --a-brand-ink:#BBEEE8;
    --a-success-soft:#0F2A1E; --a-warn-soft:#2C1F0C; --a-danger-soft:#2C1212; --a-info-soft:#121E36;
    --a-shadow-sm:0 1px 2px rgba(0,0,0,.25), 0 0 0 1px rgba(255,255,255,.03);
    --a-shadow-md:0 4px 14px rgba(0,0,0,.35), 0 0 0 1px rgba(255,255,255,.04);
    --a-shadow-lg:0 12px 30px rgba(0,0,0,.45), 0 0 0 1px rgba(255,255,255,.05);
  }
}
html[data-theme="dark"]{ color-scheme:dark }
html[data-theme="dark"]:root,
html[data-theme="dark"]{
  --a-bg:#0C1618; --a-surface:#121E20; --a-surface-2:#0E181A;
  --a-line:#1F2C2E; --a-line-soft:#18262A;
  --a-ink:#E9F0EE; --a-ink-2:#A9BDB8; --a-ink-3:#7B8F8A; --a-ink-4:#5A6F6A;
  --a-brand-soft:#13332E; --a-brand-ink:#BBEEE8;
  --a-success-soft:#0F2A1E; --a-warn-soft:#2C1F0C; --a-danger-soft:#2C1212; --a-info-soft:#121E36;
}
html[data-theme="light"]{ color-scheme:light }

/* ========== RESET ========== */
*,*::before,*::after{ box-sizing:border-box }
html,body{ margin:0;padding:0 }
body{
  font-family:'Inter', 'Manrope', system-ui, sans-serif;
  background:var(--a-bg);color:var(--a-ink);
  font-size:14px;line-height:1.5;
  -webkit-font-smoothing:antialiased;
  min-height:100vh;
}
a{ color:inherit;text-decoration:none }
button{ font-family:inherit;cursor:pointer;border:0;background:none;color:inherit }
:focus{ outline:none }
:focus-visible{ outline:2px solid var(--a-brand);outline-offset:2px;border-radius:var(--a-r-sm) }
::selection{ background:var(--a-brand-soft);color:var(--a-brand-ink) }
.skip-link{position:absolute;left:-9999px;top:0;z-index:1000;background:var(--a-n900);color:#fff;padding:10px 16px;border-radius:0 0 6px 0;font-weight:600}
.skip-link:focus{left:0}

/* ========== LAYOUT ========== */
.adm-app{ display:grid;grid-template-columns:var(--a-sidebar) 1fr;min-height:100vh }
@media (max-width:1080px){
  .adm-app{ grid-template-columns:1fr }
  .adm-sidebar{ position:fixed;inset:0 auto 0 0;transform:translateX(-100%);transition:transform .25s ease;z-index:90 }
  .adm-sidebar.open{ transform:translateX(0);box-shadow:var(--a-shadow-lg) }
}

/* ========== SIDEBAR ========== */
.adm-sidebar{
  background:var(--a-surface);border-right:1px solid var(--a-line);
  display:flex;flex-direction:column;width:var(--a-sidebar);
  height:100vh;position:sticky;top:0;
}
.adm-brand{
  display:flex;align-items:center;gap:12px;padding:18px 20px;
  border-bottom:1px solid var(--a-line);
}
.adm-brand .mark{
  width:32px;height:32px;border-radius:8px;
  background:linear-gradient(135deg, var(--a-brand) 0%, var(--a-brand-2) 100%);
  color:#fff;display:grid;place-items:center;font-weight:700;font-family:'JetBrains Mono';font-size:13px;
}
.adm-brand strong{ font-size:14px;letter-spacing:.01em }
.adm-brand small{ display:block;font-size:11px;color:var(--a-ink-3);letter-spacing:.12em;text-transform:uppercase;margin-top:1px }

.adm-ws{
  margin:14px 14px 6px;display:flex;align-items:center;gap:10px;
  padding:10px 12px;border:1px solid var(--a-line);border-radius:var(--a-r);
  background:var(--a-surface);cursor:pointer;font-size:13px;
  transition:border-color .15s ease;width:calc(100% - 28px);
}
.adm-ws:hover{ border-color:var(--a-brand) }
.adm-ws .ws-flag{
  width:26px;height:26px;border-radius:6px;background:var(--a-brand-soft);color:var(--a-brand-ink);
  display:grid;place-items:center;font-size:11px;font-weight:700;flex:0 0 26px;
}
.adm-ws .ws-meta{ flex:1;min-width:0;text-align:left }
.adm-ws .ws-meta strong{ display:block;font-size:13px;color:var(--a-ink);line-height:1.2 }
.adm-ws .ws-meta span{ display:block;font-size:11px;color:var(--a-ink-3) }
.adm-ws i.chev{ color:var(--a-ink-3);font-size:11px }

.adm-nav{ padding:14px 10px;overflow-y:auto;flex:1;scrollbar-width:thin }
.adm-nav-group{ margin-bottom:18px }
.adm-nav-group h6{
  margin:6px 10px 6px;padding:0;font-size:10.5px;color:var(--a-ink-4);
  letter-spacing:.16em;text-transform:uppercase;font-weight:600;
}
.adm-nav a, .adm-nav button.navitem{
  display:flex;align-items:center;gap:11px;width:100%;
  padding:8px 12px;margin-bottom:1px;
  border-radius:var(--a-r-sm);
  color:var(--a-ink-2);font-size:13.5px;font-weight:500;
  transition:background .12s ease, color .12s ease;
  text-align:left;
}
.adm-nav a:hover, .adm-nav button.navitem:hover{ background:var(--a-n100);color:var(--a-ink) }
html[data-theme="dark"] .adm-nav a:hover, html[data-theme="dark"] .adm-nav button.navitem:hover{ background:rgba(255,255,255,.04) }
.adm-nav a.active{ background:var(--a-brand-soft);color:var(--a-brand-ink);font-weight:600 }
.adm-nav a i, .adm-nav button.navitem i{ width:16px;flex:0 0 16px;font-size:14px;color:var(--a-ink-3);text-align:center }
.adm-nav a.active i{ color:var(--a-brand-2) }
.adm-nav a .count{
  margin-left:auto;font-family:'JetBrains Mono';font-size:11px;
  padding:2px 7px;border-radius:999px;background:var(--a-n100);color:var(--a-ink-2);font-weight:500;
}
.adm-nav a.active .count{ background:var(--a-brand);color:#fff }
.adm-nav a .dot-new{ margin-left:auto;width:6px;height:6px;border-radius:50%;background:var(--a-danger) }

.adm-side-foot{ border-top:1px solid var(--a-line);padding:12px 14px }
.adm-quota{ margin-bottom:10px;font-size:12px;color:var(--a-ink-3) }
.adm-quota .bar{ height:4px;background:var(--a-n100);border-radius:999px;overflow:hidden;margin-top:5px }
.adm-quota .bar i{ display:block;height:100%;background:linear-gradient(90deg, var(--a-brand), var(--a-brand-2));width:62% }
html[data-theme="dark"] .adm-quota .bar{ background:rgba(255,255,255,.08) }
.adm-user{
  display:flex;align-items:center;gap:10px;padding:6px;border-radius:var(--a-r);cursor:pointer;width:100%;
}
.adm-user:hover{ background:var(--a-n100) }
html[data-theme="dark"] .adm-user:hover{ background:rgba(255,255,255,.04) }
.adm-user .avatar{
  width:32px;height:32px;border-radius:50%;background:var(--a-brand);color:#fff;
  display:grid;place-items:center;font-weight:600;font-size:13px;flex:0 0 32px;
}
.adm-user .uinfo{ flex:1;min-width:0;text-align:left }
.adm-user .uinfo strong{ display:block;font-size:13px;color:var(--a-ink);line-height:1.2 }
.adm-user .uinfo span{ display:block;font-size:11px;color:var(--a-ink-3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap }
.adm-user i.fa-ellipsis-vertical{ color:var(--a-ink-3) }

/* ========== MAIN CANVAS + TOPBAR ========== */
.adm-canvas{ display:flex;flex-direction:column;min-width:0 }
.adm-topbar{
  position:sticky;top:0;z-index:40;
  background:var(--a-surface);border-bottom:1px solid var(--a-line);
  height:var(--a-topbar);display:flex;align-items:center;gap:14px;padding:0 24px;
  backdrop-filter:saturate(1.3) blur(6px);
}
.adm-burger{
  display:none;width:34px;height:34px;border-radius:8px;
  align-items:center;justify-content:center;color:var(--a-ink-2);
}
.adm-burger:hover{ background:var(--a-n100) }
@media (max-width:1080px){ .adm-burger{ display:inline-flex } }

.adm-crumbs{ display:flex;align-items:center;gap:8px;font-size:13px;color:var(--a-ink-3);flex:0 0 auto }
.adm-crumbs a{ color:var(--a-ink-3) }
.adm-crumbs a:hover{ color:var(--a-ink) }
.adm-crumbs i{ font-size:9px;color:var(--a-ink-4) }
.adm-crumbs span.cur{ color:var(--a-ink);font-weight:600 }

.adm-search{ flex:1;max-width:420px;margin:0 auto;position:relative }
.adm-search input{
  width:100%;height:36px;border-radius:var(--a-r);
  border:1px solid var(--a-line);background:var(--a-bg);color:var(--a-ink);
  padding:0 36px 0 38px;font-family:inherit;font-size:13px;
  transition:border-color .15s ease, background .15s ease;
}
.adm-search input:hover{ border-color:var(--a-n300) }
.adm-search input:focus{ outline:none;border-color:var(--a-brand);background:var(--a-surface);box-shadow:0 0 0 3px var(--a-brand-soft) }
.adm-search i.sic{ position:absolute;left:13px;top:11px;color:var(--a-ink-3);font-size:13px }
.adm-search .kbd{
  position:absolute;right:8px;top:7px;padding:2px 6px;border:1px solid var(--a-line);
  border-radius:5px;font-family:'JetBrains Mono';font-size:10.5px;color:var(--a-ink-3);background:var(--a-surface);
}

.adm-topbar-actions{ display:flex;align-items:center;gap:6px;margin-left:auto }
.adm-iconbtn{
  width:34px;height:34px;border-radius:8px;display:inline-flex;align-items:center;justify-content:center;
  color:var(--a-ink-2);position:relative;
}
.adm-iconbtn:hover{ background:var(--a-n100);color:var(--a-ink) }
html[data-theme="dark"] .adm-iconbtn:hover{ background:rgba(255,255,255,.05) }
.adm-iconbtn .badge{
  position:absolute;top:4px;right:4px;min-width:16px;height:16px;padding:0 4px;
  border-radius:999px;background:var(--a-danger);color:#fff;font-size:10px;font-weight:700;
  display:inline-flex;align-items:center;justify-content:center;
}

/* ========== PAGE WRAPPER ========== */
.adm-page{ padding:24px 28px 96px;max-width:1440px;margin:0 auto;width:100% }
@media (max-width:720px){ .adm-page{ padding:20px 16px 40px } }

.adm-page-head{
  display:flex;justify-content:space-between;align-items:flex-start;gap:16px;
  margin-bottom:22px;flex-wrap:wrap;
}
.adm-page-head h1{ margin:0;font-size:22px;font-weight:600;letter-spacing:-.01em;color:var(--a-ink) }
.adm-page-head p{ margin:4px 0 0;color:var(--a-ink-2);font-size:13.5px }
.adm-head-actions{ display:flex;gap:8px;align-items:center;flex-wrap:wrap }

/* ========== BUTTONS ========== */
.adm-btn{
  display:inline-flex;align-items:center;gap:8px;
  height:36px;padding:0 14px;border-radius:var(--a-r);
  font-size:13px;font-weight:600;color:var(--a-ink);
  border:1px solid var(--a-line);background:var(--a-surface);
  transition:all .12s ease;white-space:nowrap;
}
.adm-btn:hover{ border-color:var(--a-n300);background:var(--a-n50) }
html[data-theme="dark"] .adm-btn:hover{ background:rgba(255,255,255,.04) }
.adm-btn:disabled{ opacity:.5;cursor:not-allowed }
.adm-btn.primary{ background:var(--a-n900);border-color:var(--a-n900);color:#fff }
.adm-btn.primary:hover{ background:var(--a-n800);border-color:var(--a-n800) }
.adm-btn.brand{ background:var(--a-brand-2);border-color:var(--a-brand-2);color:#fff }
.adm-btn.brand:hover{ filter:brightness(1.05) }
.adm-btn.danger{ background:var(--a-danger);border-color:var(--a-danger);color:#fff }
.adm-btn.danger:hover{ filter:brightness(1.05) }
.adm-btn.ghost-danger{ color:var(--a-danger);border-color:var(--a-danger-soft) }
.adm-btn.ghost-danger:hover{ background:var(--a-danger-soft);border-color:var(--a-danger) }
.adm-btn.sm{ height:28px;padding:0 10px;font-size:12px }
.adm-btn.lg{ height:42px;padding:0 18px;font-size:14px }
.adm-btn i{ font-size:12px }

.adm-datepick{
  display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 12px;
  border-radius:var(--a-r);border:1px solid var(--a-line);background:var(--a-surface);
  font-size:13px;font-weight:500;color:var(--a-ink-2);
}
.adm-datepick i{ color:var(--a-ink-3);font-size:12px }

/* ========== CARD ========== */
.card{
  background:var(--a-surface);border:1px solid var(--a-line);border-radius:var(--a-r-lg);
  padding:20px 22px;
}
.card .chead{
  display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:14px;
}
.card h3{ margin:0;font-size:15px;font-weight:600;color:var(--a-ink);letter-spacing:-.005em }
.card h3 small{ font-weight:400;color:var(--a-ink-3);font-size:12.5px;margin-left:6px }
.card .seg{
  display:inline-flex;border:1px solid var(--a-line);border-radius:var(--a-r-sm);padding:2px;background:var(--a-bg);
}
.card .seg button{ padding:4px 10px;font-size:12px;font-weight:600;color:var(--a-ink-3);border-radius:5px }
.card .seg button.on{ background:var(--a-surface);color:var(--a-ink);box-shadow:var(--a-shadow-sm) }

/* ========== KPI ========== */
.kpi-row{ display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:22px }
@media (max-width:1080px){ .kpi-row{ grid-template-columns:repeat(2,1fr) } }
@media (max-width:560px){ .kpi-row{ grid-template-columns:1fr } }
.kpi{ background:var(--a-surface);border:1px solid var(--a-line);border-radius:var(--a-r-lg);padding:18px 20px;position:relative;overflow:hidden }
.kpi .label{ font-size:12px;color:var(--a-ink-3);letter-spacing:.04em;font-weight:500;display:flex;align-items:center;gap:6px }
.kpi .label i{ font-size:11px;color:var(--a-ink-4) }
.kpi .value{ font-size:28px;font-weight:600;letter-spacing:-.015em;color:var(--a-ink);margin:10px 0 6px;font-family:'Inter';line-height:1.1 }
.kpi .delta{ display:inline-flex;align-items:center;gap:5px;font-size:12px;font-weight:600;padding:3px 8px;border-radius:999px }
.kpi .delta.up{ background:var(--a-success-soft);color:var(--a-success) }
.kpi .delta.down{ background:var(--a-danger-soft);color:var(--a-danger) }
.kpi .trend{ position:absolute;right:16px;bottom:16px;width:80px;height:32px;opacity:.85 }
.kpi .trend path{ fill:none;stroke:var(--a-brand);stroke-width:1.8 }
.kpi .sub{ font-size:11.5px;color:var(--a-ink-3);margin-left:6px }

/* ========== GRIDS ========== */
.dash-grid{ display:grid;grid-template-columns:2fr 1fr;gap:18px;margin-bottom:22px }
@media (max-width:1080px){ .dash-grid{ grid-template-columns:1fr } }
.row-2{ display:grid;grid-template-columns:1.5fr 1fr;gap:18px;margin-bottom:22px }
@media (max-width:1080px){ .row-2{ grid-template-columns:1fr } }

/* ========== CHART / BARS ========== */
.chart-wrap{ position:relative;height:240px }
.chart-wrap svg{ width:100%;height:100%;display:block }
.chart-legend{ display:flex;gap:16px;margin-top:10px;font-size:12px;color:var(--a-ink-3) }
.chart-legend span{ display:inline-flex;align-items:center;gap:6px }
.chart-legend i.dot{ width:8px;height:8px;border-radius:50%;display:inline-block }

.bar-list{ display:grid;gap:10px }
.bar-row{ display:grid;grid-template-columns:100px 1fr 60px;gap:12px;align-items:center;font-size:12.5px }
.bar-row .n{ color:var(--a-ink);font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap }
.bar-row .bar{ height:8px;border-radius:4px;background:var(--a-n100);overflow:hidden }
html[data-theme="dark"] .bar-row .bar{ background:rgba(255,255,255,.06) }
.bar-row .bar i{ display:block;height:100%;background:linear-gradient(90deg, var(--a-brand-2), var(--a-brand)) }
.bar-row .v{ font-family:'JetBrains Mono';font-size:11.5px;color:var(--a-ink-2);text-align:right }

/* ========== TABLE ========== */
.tbl{ width:100%;border-collapse:collapse }
.tbl th,.tbl td{
  padding:11px 12px;text-align:left;font-size:13px;border-bottom:1px solid var(--a-line-soft);vertical-align:middle;
}
.tbl th{
  font-weight:500;color:var(--a-ink-3);font-size:11.5px;letter-spacing:.06em;text-transform:uppercase;
  background:var(--a-bg);position:sticky;top:0;z-index:1;
}
.tbl tr:last-child td{ border-bottom:0 }
.tbl tr:hover td{ background:var(--a-n50) }
html[data-theme="dark"] .tbl tr:hover td{ background:rgba(255,255,255,.02) }
.tbl tr.selected td{ background:var(--a-brand-soft) }
.tbl td.id{ font-family:'JetBrains Mono';font-size:12px;color:var(--a-ink-2) }
.tbl .ucell{ display:flex;align-items:center;gap:10px }
.tbl .ucell .avatar{
  width:28px;height:28px;border-radius:50%;background:var(--a-brand-soft);color:var(--a-brand-ink);
  display:grid;place-items:center;font-weight:600;font-size:11px;flex:0 0 28px;
}
.tbl .ucell .meta strong{ display:block;font-size:13px;color:var(--a-ink);line-height:1.2 }
.tbl .ucell .meta span{ display:block;font-size:11.5px;color:var(--a-ink-3) }
.tbl td.amt{ font-family:'JetBrains Mono';font-size:13px;text-align:right;color:var(--a-ink) }
.tbl td.actions{ text-align:right;white-space:nowrap }
.tbl td.actions .adm-iconbtn{ width:28px;height:28px }

/* ========== CHIPS ========== */
.chip{
  display:inline-flex;align-items:center;gap:5px;
  padding:3px 9px;border-radius:999px;font-size:11.5px;font-weight:600;white-space:nowrap;
}
.chip .dot{ width:6px;height:6px;border-radius:50%;background:currentColor }
.chip.ok{ background:var(--a-success-soft);color:var(--a-success) }
.chip.warn{ background:var(--a-warn-soft);color:var(--a-warn) }
.chip.info{ background:var(--a-info-soft);color:var(--a-info) }
.chip.err{ background:var(--a-danger-soft);color:var(--a-danger) }
.chip.muted{ background:var(--a-n100);color:var(--a-ink-2) }
html[data-theme="dark"] .chip.muted{ background:rgba(255,255,255,.05);color:var(--a-ink-2) }
.chip.brand{ background:var(--a-brand-soft);color:var(--a-brand-ink) }

/* ========== ACTIVITY / QUICK / SYS ========== */
.activity{ display:flex;flex-direction:column;gap:12px;max-height:420px;overflow-y:auto;padding-right:4px;scrollbar-width:thin }
.act-row{ display:flex;gap:12px;align-items:flex-start }
.act-icon{
  width:28px;height:28px;border-radius:50%;background:var(--a-brand-soft);color:var(--a-brand-2);
  display:grid;place-items:center;font-size:12px;flex:0 0 28px;
}
.act-icon.warn{ background:var(--a-warn-soft);color:var(--a-warn) }
.act-icon.err{ background:var(--a-danger-soft);color:var(--a-danger) }
.act-icon.ok{ background:var(--a-success-soft);color:var(--a-success) }
.act-body{ flex:1;min-width:0;font-size:13px;color:var(--a-ink-2);line-height:1.5 }
.act-body strong{ color:var(--a-ink);font-weight:600 }
.act-body .time{ display:block;font-size:11.5px;color:var(--a-ink-4);margin-top:2px }
.act-body code{ background:var(--a-n100);padding:1px 5px;border-radius:4px;font-family:'JetBrains Mono';font-size:11.5px;color:var(--a-ink) }
html[data-theme="dark"] .act-body code{ background:rgba(255,255,255,.06) }

.quick-grid{ display:grid;grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));gap:10px }
.quick-card{
  padding:14px;border:1px solid var(--a-line);border-radius:var(--a-r);background:var(--a-surface);
  text-decoration:none;color:var(--a-ink);display:flex;align-items:flex-start;gap:12px;
  transition:border-color .12s ease, transform .12s ease;
}
.quick-card:hover{ border-color:var(--a-brand);transform:translateY(-1px) }
.quick-card .qico{
  width:32px;height:32px;border-radius:8px;background:var(--a-brand-soft);color:var(--a-brand-2);
  display:grid;place-items:center;font-size:14px;flex:0 0 32px;
}
.quick-card strong{ display:block;font-size:13px;font-weight:600;color:var(--a-ink);line-height:1.3 }
.quick-card span{ display:block;font-size:11.5px;color:var(--a-ink-3);margin-top:3px }

.sys-grid{ display:grid;gap:10px }
.sys-row{
  display:grid;grid-template-columns:1fr auto;align-items:center;gap:10px;
  padding:10px 12px;border:1px solid var(--a-line-soft);border-radius:var(--a-r);
}
.sys-row .sname{ display:flex;align-items:center;gap:10px;font-size:13px;color:var(--a-ink) }
.sys-row .sname i{ font-size:12px;color:var(--a-ink-3);width:14px }
.sys-row .slatency{ font-family:'JetBrains Mono';font-size:11.5px;color:var(--a-ink-3) }

.adm-alert{
  display:flex;align-items:center;gap:12px;padding:10px 16px;
  background:var(--a-warn-soft);border-bottom:1px solid var(--a-line);
  color:var(--a-warn);font-size:13px;
}
.adm-alert i{ font-size:13px }
.adm-alert strong{ font-weight:600 }
.adm-alert a{ margin-left:auto;color:var(--a-warn);text-decoration:underline;font-weight:600 }
.adm-alert button.close{ color:var(--a-warn) }

.flex-g{ flex:1 }
.tabular{ font-variant-numeric:tabular-nums }

/* =========================================================================
   FORM CONTROLS (product editor + settings)
   ========================================================================= */
.form-grid{ display:grid;grid-template-columns:2fr 1fr;gap:18px;align-items:start }
@media (max-width:1080px){ .form-grid{ grid-template-columns:1fr } }
.form-col{ display:flex;flex-direction:column;gap:18px;min-width:0 }

.field{ margin-bottom:14px }
.field:last-child{ margin-bottom:0 }
.field > label{
  display:block;font-size:12.5px;color:var(--a-ink-2);margin-bottom:6px;font-weight:600;letter-spacing:.01em;
}
.field > label .req{ color:var(--a-danger);margin-left:3px }
.field > label .hint{ color:var(--a-ink-4);font-weight:400;margin-left:6px;font-size:11.5px }

.input, .textarea, .select{
  width:100%;box-sizing:border-box;font-family:inherit;font-size:13.5px;color:var(--a-ink);
  background:var(--a-surface);border:1px solid var(--a-line);border-radius:var(--a-r);
  padding:10px 12px;transition:border-color .12s ease, box-shadow .12s ease, background .12s ease;
}
.input:hover, .textarea:hover, .select:hover{ border-color:var(--a-n300) }
.input:focus, .textarea:focus, .select:focus{
  outline:none;border-color:var(--a-brand);box-shadow:0 0 0 3px var(--a-brand-soft);
}
.input::placeholder, .textarea::placeholder{ color:var(--a-ink-4) }
.input.error, .textarea.error, .select.error{ border-color:var(--a-danger);box-shadow:0 0 0 3px var(--a-danger-soft) }
.textarea{ resize:vertical;min-height:90px;line-height:1.6 }
.select{ appearance:none;-webkit-appearance:none;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path d='M1 1l4 4 4-4' fill='none' stroke='%237B8784' stroke-width='1.4'/></svg>");background-repeat:no-repeat;background-position:right 12px center;padding-right:32px }

.input-group{ position:relative }
.input-group .prefix, .input-group .suffix{
  position:absolute;top:0;bottom:0;display:flex;align-items:center;color:var(--a-ink-3);font-size:12.5px;pointer-events:none;
}
.input-group .prefix{ left:12px }
.input-group .suffix{ right:12px }
.input-group .input.has-prefix{ padding-left:36px }
.input-group .input.has-suffix{ padding-right:48px }

.form-row{ display:grid;gap:12px }
.form-row.cols-2{ grid-template-columns:1fr 1fr }
.form-row.cols-3{ grid-template-columns:1fr 1fr 1fr }
@media (max-width:640px){ .form-row.cols-2, .form-row.cols-3{ grid-template-columns:1fr } }

/* Toggle switch */
.switch{ display:inline-flex;align-items:center;gap:10px;cursor:pointer;user-select:none }
.switch input{ position:absolute;opacity:0;pointer-events:none }
.switch .track{
  width:36px;height:20px;border-radius:999px;background:var(--a-n200);position:relative;transition:background .15s ease;
}
.switch .track::after{
  content:"";position:absolute;left:2px;top:2px;width:16px;height:16px;border-radius:50%;
  background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.18);transition:transform .15s ease;
}
.switch input:checked ~ .track{ background:var(--a-brand-2) }
.switch input:checked ~ .track::after{ transform:translateX(16px) }
.switch input:focus-visible ~ .track{ box-shadow:0 0 0 3px var(--a-brand-soft) }
.switch .lbl{ font-size:13px;color:var(--a-ink);font-weight:500 }
.switch .lbl small{ display:block;color:var(--a-ink-3);font-size:11.5px;font-weight:400;margin-top:1px }

/* Checkbox */
.cbox{ display:inline-flex;align-items:center;gap:8px;font-size:13px;color:var(--a-ink);cursor:pointer;user-select:none }
.cbox input{ accent-color:var(--a-brand-2);width:16px;height:16px }

/* Tag input */
.tag-input{
  display:flex;flex-wrap:wrap;gap:6px;align-items:center;
  padding:8px 10px;border:1px solid var(--a-line);border-radius:var(--a-r);background:var(--a-surface);
  min-height:42px;
}
.tag-input:focus-within{ border-color:var(--a-brand);box-shadow:0 0 0 3px var(--a-brand-soft) }
.tag-input .pill{
  display:inline-flex;align-items:center;gap:6px;
  padding:3px 4px 3px 10px;border-radius:999px;background:var(--a-brand-soft);color:var(--a-brand-ink);
  font-size:12px;font-weight:500;
}
.tag-input .pill button{ width:18px;height:18px;border-radius:50%;display:grid;place-items:center;color:var(--a-brand-ink);opacity:.7 }
.tag-input .pill button:hover{ background:rgba(0,0,0,.1);opacity:1 }
.tag-input input{ flex:1;min-width:80px;border:0;outline:none;font-family:inherit;font-size:13px;background:transparent;color:var(--a-ink);padding:4px 0 }

/* Image drop */
.img-drop{
  border:1.5px dashed var(--a-line);border-radius:var(--a-r-lg);padding:26px;text-align:center;
  color:var(--a-ink-3);background:var(--a-bg);transition:border-color .15s ease, background .15s ease;
  cursor:pointer;
}
.img-drop:hover, .img-drop.drag{ border-color:var(--a-brand);background:var(--a-brand-soft) }
.img-drop i.big{ font-size:22px;color:var(--a-brand-2);margin-bottom:6px }
.img-drop strong{ display:block;color:var(--a-ink);font-weight:600;font-size:13.5px;margin-bottom:2px }
.img-drop span{ display:block;font-size:11.5px }

.img-grid{ display:grid;grid-template-columns:repeat(auto-fill, minmax(110px, 1fr));gap:10px;margin-top:14px }
.img-tile{
  aspect-ratio:1/1;border:1px solid var(--a-line);border-radius:var(--a-r);overflow:hidden;position:relative;
  background:var(--a-bg);display:grid;place-items:center;
}
.img-tile svg, .img-tile img{ width:100%;height:100%;object-fit:cover }
.img-tile .primary-badge{
  position:absolute;top:6px;left:6px;padding:2px 7px;border-radius:999px;background:var(--a-n900);color:#fff;font-size:10px;font-weight:600;letter-spacing:.04em;
}
.img-tile .rm{
  position:absolute;top:6px;right:6px;width:22px;height:22px;border-radius:50%;background:rgba(0,0,0,.6);color:#fff;
  display:grid;place-items:center;font-size:10px;cursor:pointer;
}
.img-tile .rm:hover{ background:var(--a-danger) }

/* Variants table (inline small) */
.var-tbl{
  display:grid;border:1px solid var(--a-line);border-radius:var(--a-r);overflow:hidden;
}
.var-head, .var-row{
  display:grid;grid-template-columns:1.3fr 1fr 1fr 80px 36px;gap:10px;padding:10px 12px;align-items:center;
}
.var-head{ background:var(--a-bg);font-size:11.5px;letter-spacing:.06em;color:var(--a-ink-3);font-weight:600;text-transform:uppercase }
.var-row{ border-top:1px solid var(--a-line-soft) }
.var-row:first-of-type{ border-top:0 }
.var-row .input{ padding:7px 10px;font-size:12.5px }

/* Filter bar (product list) */
.pr-filter-bar{
  display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px;
  padding:12px 14px;background:var(--a-surface);border:1px solid var(--a-line);border-radius:var(--a-r-lg);
}
.pr-filter-bar .search{ flex:1;min-width:220px;position:relative }
.pr-filter-bar .search input{
  width:100%;height:36px;padding:0 12px 0 36px;border-radius:var(--a-r);border:1px solid var(--a-line);
  background:var(--a-bg);color:var(--a-ink);font-family:inherit;font-size:13px;
}
.pr-filter-bar .search input:focus{ outline:none;border-color:var(--a-brand);background:var(--a-surface);box-shadow:0 0 0 3px var(--a-brand-soft) }
.pr-filter-bar .search i{ position:absolute;left:12px;top:11px;color:var(--a-ink-3);font-size:13px }
.pr-filter-bar .select, .pr-filter-bar .input{ height:36px;padding:0 28px 0 12px;font-size:13px;width:auto;min-width:140px }

/* Bulk action bar */
.bulk-bar{
  display:flex;align-items:center;gap:10px;padding:10px 14px;
  background:var(--a-brand-soft);border:1px solid var(--a-brand);border-radius:var(--a-r-lg);
  color:var(--a-brand-ink);font-size:13px;margin-bottom:14px;
}
.bulk-bar strong{ font-weight:600 }
.bulk-bar .spacer{ flex:1 }
.bulk-bar button{
  padding:5px 12px;border-radius:var(--a-r-sm);font-size:12.5px;font-weight:600;
  background:var(--a-surface);color:var(--a-ink);border:1px solid var(--a-line);
}
.bulk-bar button:hover{ border-color:var(--a-brand-2) }
.bulk-bar button.danger{ color:var(--a-danger);border-color:var(--a-danger-soft) }

/* Bottle mini (product thumb) */
.pr-thumb{
  width:44px;height:44px;border-radius:var(--a-r-sm);background:var(--a-brand-soft);
  display:grid;place-items:center;overflow:hidden;flex:0 0 44px;
}
.pr-thumb svg{ width:32px;height:32px }

/* Pagination */
.pagi{
  display:flex;justify-content:center;align-items:center;gap:4px;padding:14px 0;margin-top:10px;
  font-size:13px;color:var(--a-ink-2);
}
.pagi button, .pagi .info{
  min-width:32px;height:32px;padding:0 10px;border-radius:var(--a-r-sm);
  border:1px solid transparent;background:transparent;color:var(--a-ink-2);font-weight:500;
}
.pagi button:hover{ border-color:var(--a-line);background:var(--a-surface) }
.pagi button.on{ background:var(--a-n900);color:#fff;border-color:var(--a-n900) }

/* Sticky save bar at bottom of editor */
.save-bar{
  position:sticky;bottom:0;z-index:30;
  margin:22px -28px -96px;padding:14px 28px;
  background:var(--a-surface);border-top:1px solid var(--a-line);
  display:flex;align-items:center;gap:10px;
  box-shadow:0 -6px 18px rgba(15,31,28,.05);
}
@media (max-width:720px){ .save-bar{ margin:22px -16px -40px;padding:12px 16px } }
.save-bar .status{ font-size:12.5px;color:var(--a-ink-3);display:inline-flex;align-items:center;gap:6px }
.save-bar .status i{ font-size:11px }
.save-bar .status.dirty{ color:var(--a-warn) }
.save-bar .status.saved{ color:var(--a-success) }

/* Toast */
.toast-wrap{ position:fixed;right:22px;bottom:22px;z-index:200;display:flex;flex-direction:column;gap:8px }
.toast{
  min-width:280px;max-width:360px;padding:12px 14px;
  background:var(--a-n900);color:#fff;border-radius:var(--a-r);
  box-shadow:0 8px 24px rgba(0,0,0,.2);
  display:flex;align-items:center;gap:10px;font-size:13px;
  animation:tsl .25s ease;
}
@keyframes tsl{ from{ transform:translateY(8px);opacity:0 } to{ transform:translateY(0);opacity:1 } }
.toast i{ color:var(--a-brand) }
.toast.ok i{ color:var(--a-success) }
.toast.err i{ color:var(--a-danger) }
.toast button{ margin-left:auto;color:rgba(255,255,255,.6) }
.toast button:hover{ color:#fff }

