656	    const cur = document.documentElement.getAttribute('data-theme') ||
657	                (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
658	    const next = cur === 'dark' ? 'light' : 'dark';
659	    document.documentElement.setAttribute('data-theme', next);
660	    localStorage.setItem('dtx_admin_theme', next);
