664	    const icon = document.getElementById('themeIcon');
665	    if (!icon) return;
666	    const effective = document.documentElement.getAttribute('data-theme') ||
667	                      (matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
668	    icon.className = effective === 'dark' ? 'fa-solid fa-sun' : 'fa-solid fa-moon';
