330:.chip{
334:.chip .dot{ width:6px;height:6px;border-radius:50%;background:currentColor }
335:.chip.ok{ background:var(--a-success-soft);color:var(--a-success) }
336:.chip.warn{ background:var(--a-warn-soft);color:var(--a-warn) }
337:.chip.info{ background:var(--a-info-soft);color:var(--a-info) }
338:.chip.err{ background:var(--a-danger-soft);color:var(--a-danger) }
339:.chip.muted{ background:var(--a-n100);color:var(--a-ink-2) }
341:.chip.brand{ background:var(--a-brand-soft);color:var(--a-brand-ink) }
393:.tabular{ font-variant-numeric:tabular-nums }
402:.field{ margin-bottom:14px }
403:.field:last-child{ margin-bottom:0 }
404:.field > label{
407:.field > label .req{ color:var(--a-danger);margin-left:3px }
408:.field > label .hint{ color:var(--a-ink-4);font-weight:400;margin-left:6px;font-size:11.5px }
513:.pr-filter-bar{
517:.pr-filter-bar .search{ flex:1;min-width:220px;position:relative }
518:.pr-filter-bar .search input{
522:.pr-filter-bar .search input:focus{ outline:none;border-color:var(--a-brand);background:var(--a-surface);box-shadow:0 0 0 3px var(--a-brand-soft) }
523:.pr-filter-bar .search i{ position:absolute;left:12px;top:11px;color:var(--a-ink-3);font-size:13px }
524:.pr-filter-bar .select, .pr-filter-bar .input{ height:36px;padding:0 28px 0 12px;font-size:13px;width:auto;min-width:140px }
527:.bulk-bar{
532:.bulk-bar strong{ font-weight:600 }
533:.bulk-bar .spacer{ flex:1 }
534:.bulk-bar button{
538:.bulk-bar button:hover{ border-color:var(--a-brand-2) }
539:.bulk-bar button.danger{ color:var(--a-danger);border-color:var(--a-danger-soft) }
542:.pr-thumb{
546:.pr-thumb svg{ width:32px;height:32px }
549:.pagi{
