cat >> "/Users/tranquy/Downloads/thư mục không có tiêu đề/detoxblanc-clone/assets/admin.css" << 'EOF'

/* =========================================================================
   Additions for admin-products / admin-product-edit pages
   ========================================================================= */

/* Chip aliases to match JS usage */
.chip.success{ background:var(--a-success-soft);color:var(--a-success) }
.chip.danger { background:var(--a-danger-soft);color:var(--a-danger) }
html[data-theme="dark"] .chip.success{ background:rgba(56,176,103,.12) }
html[data-theme="dark"] .chip.danger{ background:rgba(208,59,59,.12) }

/* Generic helpers */
.muted{ color:var(--a-ink-3) }
.num{ text-align:right }
th.num, td.num{ text-align:right }

/* Card head (alias of .card .chead, flush with card padding) */
.card > .card-head{
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  padding:14px 18px;border-bottom:1px solid var(--a-line);
}
.card > .card-head h3{ margin:0;font-size:15px;font-weight:600;color:var(--a-ink);letter-spacing:-.005em }
.card > .card-head h3 .muted{ font-weight:400;font-size:12.5px }
.card > .card-head .seg{
  display:inline-flex;gap:2px;padding:3px;background:var(--a-n100);border-radius:8px;
}
html[data-theme="dark"] .card > .card-head .seg{ background:rgba(255,255,255,.05) }
.card > .card-head .seg button{
  padding:5px 10px;font-size:12px;font-weight:600;color:var(--a-ink-3);border-radius:5px;
  background:transparent;border:0;cursor:pointer;display:inline-flex;align-items:center;gap:6px;
}
.card > .card-head .seg button.on{
  background:var(--a-surface);color:var(--a-ink);box-shadow:var(--a-shadow-sm);
}

/* Filter bar */
.pr-filter-bar{
  display:flex;flex-wrap:wrap;gap:10px;align-items:center;
  padding:12px;margin-bottom:14px;
}
.pr-filter-bar .field{
  margin:0;flex:0 0 auto;
}
.pr-filter-bar .field.search{ flex:1 1 260px;position:relative }
.pr-filter-bar .field.search input{
  width:100%;height:38px;padding:0 12px 0 36px;font-size:13px;
  background:var(--a-surface);border:1px solid var(--a-line);border-radius:8px;
  color:var(--a-ink);
}
.pr-filter-bar .field.search input:focus{
  outline:none;border-color:var(--a-brand);
  box-shadow:0 0 0 3px var(--a-brand-soft);
}
.pr-filter-bar .field.search i{
  position:absolute;left:12px;top:50%;transform:translateY(-50%);
  color:var(--a-ink-3);font-size:13px;pointer-events:none;
}
.pr-filter-bar .field select{
  height:38px;padding:0 28px 0 12px;font-size:13px;
  background:var(--a-surface);border:1px solid var(--a-line);border-radius:8px;
  color:var(--a-ink);min-width:150px;
  appearance:none;-webkit-appearance:none;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path fill='%238A9592' d='M0 0l5 6 5-6z'/></svg>");
  background-repeat:no-repeat;background-position:right 10px center;
}

/* Bulk bar */
.bulk-bar{
  display:flex;align-items:center;gap:8px;
  padding:10px 14px;margin-bottom:14px;
  background:var(--a-brand-soft);color:var(--a-brand-ink);
  border:1px solid color-mix(in srgb, var(--a-brand) 20%, transparent);
  border-radius:var(--a-r);
  font-size:13px;
}
.bulk-bar strong{ font-weight:600;color:var(--a-ink) }

/* Products table */
.adm-tbl{
  width:100%;border-collapse:separate;border-spacing:0;font-size:13px;
}
.adm-tbl thead th{
  text-align:left;padding:10px 14px;font-weight:600;font-size:11.5px;
  color:var(--a-ink-3);text-transform:uppercase;letter-spacing:.04em;
  border-bottom:1px solid var(--a-line);
  background:var(--a-n50);
  white-space:nowrap;
}
html[data-theme="dark"] .adm-tbl thead th{ background:rgba(255,255,255,.02) }
.adm-tbl tbody td{
  padding:12px 14px;border-bottom:1px solid var(--a-line);
  color:var(--a-ink-2);vertical-align:middle;
}
.adm-tbl tbody tr:hover td{ background:var(--a-n50) }
html[data-theme="dark"] .adm-tbl tbody tr:hover td{ background:rgba(255,255,255,.02) }
.adm-tbl tbody tr:last-child td{ border-bottom:0 }
.adm-tbl input[type="checkbox"]{ accent-color:var(--a-brand);cursor:pointer }

/* Product cell (table) */
.pr-cell{ display:flex;align-items:center;gap:12px;min-width:280px }
.pr-thumb{
  width:38px;height:38px;flex:0 0 38px;border-radius:8px;
  display:inline-flex;align-items:center;justify-content:center;
  color:#fff;font-weight:700;font-size:10px;letter-spacing:.02em;
  font-family:'JetBrains Mono', ui-monospace, monospace;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.08);
}
.pr-meta{ display:flex;flex-direction:column;gap:2px;min-width:0 }
.pr-name{
  color:var(--a-ink);font-weight:600;font-size:13px;text-decoration:none;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:42ch;
}
.pr-name:hover{ color:var(--a-brand) }
.pr-meta small{ color:var(--a-ink-3);font-size:11.5px }

/* Row actions */
.row-actions{ display:flex;gap:4px;justify-content:flex-end }
.adm-iconbtn.sm{ width:28px;height:28px;font-size:12px;border-radius:6px }

/* Empty state */
.empty-state{
  padding:56px 24px;text-align:center;color:var(--a-ink-3);
}
.empty-state i{ font-size:32px;margin-bottom:10px;color:var(--a-ink-4) }
.empty-state h4{ margin:0 0 6px;color:var(--a-ink);font-size:15px;font-weight:600 }
.empty-state p{ margin:0;font-size:13px }
.empty-state a{ color:var(--a-brand);text-decoration:none;font-weight:500 }
.empty-state a:hover{ text-decoration:underline }

/* Grid view */
.pr-grid{
  display:grid;grid-template-columns:repeat(auto-fill, minmax(220px, 1fr));
  gap:14px;padding:14px;
}
.pr-card{
  position:relative;background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:var(--a-r);overflow:hidden;transition:border-color .15s, box-shadow .15s;
}
.pr-card:hover{ border-color:var(--a-brand-2);box-shadow:var(--a-shadow-sm) }
.pr-card-chk{
  position:absolute;top:8px;left:8px;z-index:2;
  background:rgba(255,255,255,.92);backdrop-filter:blur(4px);
  padding:2px 4px;border-radius:5px;
}
.pr-card-img{
  aspect-ratio:16/10;display:flex;align-items:flex-end;justify-content:flex-start;
  padding:10px;color:#fff;
}
.pr-card-code{
  font-family:'JetBrains Mono', ui-monospace, monospace;
  font-size:11px;font-weight:600;letter-spacing:.02em;
  background:rgba(0,0,0,.28);backdrop-filter:blur(6px);
  padding:3px 7px;border-radius:5px;
}
.pr-card-body{ padding:12px 14px;display:flex;flex-direction:column;gap:6px }
.pr-card-name{
  color:var(--a-ink);font-weight:600;font-size:13px;text-decoration:none;
  display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;
  line-height:1.35;
}
.pr-card-name:hover{ color:var(--a-brand) }
.pr-card-row{ display:flex;justify-content:space-between;align-items:center;font-size:12px }
EOF
echo "✓ appended product-page styles"

