407	  // Hiện/ẩn mật khẩu
408	  function admToggleEye(btn){
409	    const input = btn.parentElement.querySelector('input');
410	    const icon = btn.querySelector('i');
411	    const showing = input.type === 'text';
412	    input.type = showing ? 'password' : 'text';
413	    icon.className = showing ? 'fa-regular fa-eye' : 'fa-regular fa-eye-slash';
414	  }
415	
416	  // OTP: tự động nhảy ô + paste 6 số
417	  (function(){
418	    const boxes = document.querySelectorAll('.adm-otp input');
419	    boxes.forEach((b, i) => {
420	      b.addEventListener('input', e => {
421	        e.target.value = e.target.value.replace(/\D/g,'').slice(0,1);
422	        if (e.target.value && boxes[i+1]) boxes[i+1].focus();
423	      });
424	      b.addEventListener('keydown', e => {
425	        if (e.key === 'Backspace' && !b.value && boxes[i-1]) boxes[i-1].focus();
426	      });
427	      b.addEventListener('paste', e => {
428	        const txt = (e.clipboardData || window.clipboardData).getData('text').replace(/\D/g,'').slice(0,6);
429	        if (txt.length){
430	          e.preventDefault();
431	          [...txt].forEach((ch, j) => { if (boxes[j]) boxes[j].value = ch; });
432	          boxes[Math.min(txt.length, boxes.length-1)].focus();
433	        }
434	      });
435	    });
436	  })();
