/**
 * Prisma seed — tạo role, permission, owner mặc định, vài SKU mẫu.
 *
 * Chạy: pnpm --filter api run prisma:seed
 * Idempotent: chạy lại nhiều lần vẫn ra cùng kết quả.
 */

import { PrismaClient, ProductStatus } from '@prisma/client';
import { hash } from '@node-rs/argon2';

const prisma = new PrismaClient();

// ──────────────── RBAC seed ─────────────────────────────────────

const ROLES = [
  { key: 'owner',     name: 'Owner',     description: 'Toàn quyền, không thể bị revoke bởi ai khác' },
  { key: 'admin',     name: 'Admin',     description: 'Quản trị chung trừ billing + user management' },
  { key: 'editor',    name: 'Editor',    description: 'Chỉnh catalog, content, không xem doanh thu' },
  { key: 'support',   name: 'Support',   description: 'Xem đơn + cập nhật trạng thái, không sửa catalog' },
  { key: 'accountant',name: 'Accountant',description: 'Xem doanh thu, xuất báo cáo, không sửa catalog' },
];

const PERMISSIONS = [
  'products:read', 'products:write',
  'orders:read',   'orders:write',
  'customers:read','customers:write',
  'inventory:read','inventory:write',
  'vouchers:read', 'vouchers:write',
  'articles:read', 'articles:write',
  'users:read',    'users:write',
  'audit:read',
  'reports:read',
  'settings:read', 'settings:write',
];

const ROLE_PERMS: Record<string, string[]> = {
  owner: PERMISSIONS,                          // all
  admin: PERMISSIONS.filter(p => !p.startsWith('users:') && p !== 'settings:write'),
  editor: [
    'products:read','products:write',
    'inventory:read',
    'articles:read','articles:write',
    'vouchers:read',
    'customers:read',
  ],
  support: [
    'products:read',
    'orders:read','orders:write',
    'customers:read','customers:write',
    'inventory:read',
  ],
  accountant: [
    'products:read',
    'orders:read',
    'customers:read',
    'reports:read',
    'audit:read',
  ],
};

// ──────────────── Categories ───────────────────────────────────

const CATEGORIES = [
  { slug: 'serum',      name: 'Serum',        position: 1 },
  { slug: 'sua-rua-mat',name: 'Sữa rửa mặt',  position: 2 },
  { slug: 'kem-duong',  name: 'Kem dưỡng',    position: 3 },
  { slug: 'chong-nang', name: 'Chống nắng',   position: 4 },
  { slug: 'toner',      name: 'Toner',        position: 5 },
];

// ──────────────── Products mẫu (3 SKU để smoke test) ───────────

const PRODUCTS = [
  {
    code: 'DTX-SER-01',
    slug: 'serum-vitamin-c-10',
    name: 'Serum Vitamin C 10%',
    categorySlug: 'serum',
    shortDesc: 'Làm sáng da, giảm thâm sau mụn',
    description: '## Công dụng\n\nSerum Vitamin C 10% stabilized giúp làm sáng da.',
    price: 485_000n,
    compareAtPrice: 580_000n,
    cost: 180_000n,
    status: ProductStatus.active,
    lowStockThreshold: 10,
    ratingAvg: 4.7,
    ratingCount: 128,
    seoTitle: 'Serum Vitamin C 10% Detoxblanc',
    seoDesc: 'Serum làm sáng da Vitamin C 10% stabilized, không gây kích ứng',
  },
  {
    code: 'DTX-CLE-01',
    slug: 'sua-rua-mat-dju',
    name: 'Sữa rửa mặt dịu nhẹ',
    categorySlug: 'sua-rua-mat',
    shortDesc: 'pH 5.5, phù hợp da nhạy cảm',
    price: 265_000n,
    cost: 95_000n,
    status: ProductStatus.active,
    lowStockThreshold: 15,
  },
  {
    code: 'DTX-SUN-01',
    slug: 'kem-chong-nang-spf50',
    name: 'Kem chống nắng SPF50+ PA++++',
    categorySlug: 'chong-nang',
    shortDesc: 'Finish trong suốt, không gây bết dính',
    price: 395_000n,
    cost: 150_000n,
    status: ProductStatus.draft,
    lowStockThreshold: 20,
  },
];

async function seedRbac() {
  for (const r of ROLES) {
    await prisma.role.upsert({
      where: { key: r.key },
      update: { name: r.name, description: r.description, isSystem: true },
      create: { ...r, isSystem: true },
    });
  }
  for (const key of PERMISSIONS) {
    await prisma.permission.upsert({
      where: { key },
      update: {},
      create: { key, description: key },
    });
  }
  for (const [roleKey, perms] of Object.entries(ROLE_PERMS)) {
    const role = await prisma.role.findUniqueOrThrow({ where: { key: roleKey } });
    for (const permKey of perms) {
      const perm = await prisma.permission.findUniqueOrThrow({ where: { key: permKey } });
      await prisma.rolePermission.upsert({
        where: { roleId_permissionId: { roleId: role.id, permissionId: perm.id } },
        update: {},
        create: { roleId: role.id, permissionId: perm.id },
      });
    }
  }
  console.log('✔ Seeded roles + permissions');
}

async function seedOwner() {
  const ownerEmail = 'owner@detoxblanc.com';
  const ownerPassword = 'ChangeMe123456!'; // ops đổi ngay lần đăng nhập đầu
  const passwordHash = await hash(ownerPassword, {
    memoryCost: 65536,
    timeCost: 3,
    parallelism: 4,
  });
  const owner = await prisma.user.upsert({
    where: { email: ownerEmail },
    update: {},
    create: {
      email: ownerEmail,
      name: 'Owner',
      passwordHash,
      status: 'active',
    },
  });
  const role = await prisma.role.findUniqueOrThrow({ where: { key: 'owner' } });
  await prisma.userRole.upsert({
    where: { userId_roleId: { userId: owner.id, roleId: role.id } },
    update: {},
    create: { userId: owner.id, roleId: role.id },
  });
  console.log(`✔ Owner seeded: ${ownerEmail} / ${ownerPassword} (ĐỔI NGAY!)`);
}

async function seedCatalog() {
  for (const c of CATEGORIES) {
    await prisma.category.upsert({
      where: { slug: c.slug },
      update: { name: c.name, position: c.position },
      create: c,
    });
  }
  for (const p of PRODUCTS) {
    const cat = await prisma.category.findUnique({ where: { slug: p.categorySlug } });
    const { categorySlug, ...data } = p;
    await prisma.product.upsert({
      where: { code: p.code },
      update: { ...data, categoryId: cat?.id ?? null },
      create: { ...data, categoryId: cat?.id ?? null },
    });
  }
  console.log(`✔ Seeded ${CATEGORIES.length} categories + ${PRODUCTS.length} products`);
}

async function main() {
  console.log('🌱 Seeding database...');
  await seedRbac();
  await seedOwner();
  await seedCatalog();
  console.log('✅ Seed complete');
}

main()
  .catch(e => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

