/**
 * TOTP helper — RFC 6238, 6 số, 30 giây, SHA-1 (chuẩn tương thích Google Authenticator).
 * Secret lưu DB đã được mã hoá bằng libsodium secretbox qua lib/crypto-box.ts.
 */

import { TOTP, Secret } from 'otpauth';

const DIGITS = 6;
const PERIOD = 30;
const WINDOW = 1; // cho phép ±1 period để chịu drift đồng hồ

export function generateSecret(): string {
  return new Secret({ size: 20 }).base32;
}

export function otpauthUrl(args: { issuer: string; account: string; secret: string }): string {
  return new TOTP({
    issuer: args.issuer,
    label: args.account,
    secret: Secret.fromBase32(args.secret),
    digits: DIGITS,
    period: PERIOD,
    algorithm: 'SHA1',
  }).toString();
}

export function verifyTotp(secret: string, code: string): boolean {
  const totp = new TOTP({
    secret: Secret.fromBase32(secret),
    digits: DIGITS,
    period: PERIOD,
    algorithm: 'SHA1',
  });
  const delta = totp.validate({ token: code, window: WINDOW });
  return delta !== null;
}

