/**
 * Session store — opaque random ID (KHÔNG dùng JWT), DB + Redis cache.
 *
 * Flow:
 *  - create(): insert DB + SET Redis với TTL → trả session ID
 *  - resolve(): GET Redis (hit 95%) → fallback DB → verify chưa revoke/expired
 *  - revoke(): DELETE Redis + set revokedAt DB
 *
 * Cookie: HttpOnly; Secure; SameSite=Strict; Domain=admin.detoxblanc.com; Path=/
 */

import { randomBytes } from 'node:crypto';
import { prisma } from './prisma.js';
import { redis, REDIS_KEYS } from './redis.js';
import { config } from '../config.js';

export type SessionRecord = {
  id: string;
  userId: string;
  ip: string | null;
  userAgent: string | null;
  createdAt: Date;
  expiresAt: Date;
};

const TTL_SEC = config.SESSION_TTL_HOURS * 3600;

export function newSessionId(): string {
  return randomBytes(32).toString('base64url');
}

export async function createSession(args: {
  userId: string;
  ip?: string | null;
  userAgent?: string | null;
}): Promise<SessionRecord> {
  const id = newSessionId();
  const expiresAt = new Date(Date.now() + TTL_SEC * 1000);
  const row = await prisma.session.create({
    data: {
      id,
      userId: args.userId,
      ip: args.ip ?? null,
      userAgent: args.userAgent ?? null,
      expiresAt,
    },
  });
  await redis.setex(REDIS_KEYS.session(id), TTL_SEC, JSON.stringify(toCache(row)));
  return row as SessionRecord;
}

export async function resolveSession(id: string): Promise<SessionRecord | null> {
  if (!id) return null;
  const cached = await redis.get(REDIS_KEYS.session(id));
  if (cached) {
    const rec = fromCache(cached);
    if (rec.expiresAt > new Date()) return rec;
    await redis.del(REDIS_KEYS.session(id));
  }
  const row = await prisma.session.findUnique({ where: { id } });
  if (!row || row.revokedAt || row.expiresAt <= new Date()) return null;
  // Backfill cache
  const remainingSec = Math.max(60, Math.floor((row.expiresAt.getTime() - Date.now()) / 1000));
  await redis.setex(REDIS_KEYS.session(id), remainingSec, JSON.stringify(toCache(row)));
  return row as SessionRecord;
}

export async function revokeSession(id: string): Promise<void> {
  await redis.del(REDIS_KEYS.session(id));
  await prisma.session.update({
    where: { id },
    data: { revokedAt: new Date() },
  }).catch(() => { /* already gone */ });
}

export async function revokeAllForUser(userId: string): Promise<void> {
  const rows = await prisma.session.findMany({
    where: { userId, revokedAt: null },
    select: { id: true },
  });
  await Promise.all(rows.map(r => redis.del(REDIS_KEYS.session(r.id))));
  await prisma.session.updateMany({
    where: { userId, revokedAt: null },
    data: { revokedAt: new Date() },
  });
}

function toCache(r: { id: string; userId: string; ip: string | null; userAgent: string | null; createdAt: Date; expiresAt: Date }) {
  return {
    id: r.id,
    userId: r.userId,
    ip: r.ip,
    userAgent: r.userAgent,
    createdAt: r.createdAt.toISOString(),
    expiresAt: r.expiresAt.toISOString(),
  };
}

function fromCache(raw: string): SessionRecord {
  const obj = JSON.parse(raw);
  return {
    ...obj,
    createdAt: new Date(obj.createdAt),
    expiresAt: new Date(obj.expiresAt),
  };
}

export const SESSION_COOKIE = 'session';
export const CSRF_HEADER = 'x-csrf-token';

