  const row = await prisma.session.findUnique({ where: { id } });
  if (!row || row.revokedAt || row.expiresAt <= new Date()) return null;
  // Backfill cache
  const remainingSec = Math.max(60, Math.floor((row.expiresAt.getTime() - Date.now()) / 1000));
  await redis.setex(REDIS_KEYS.session(id), remainingSec, JSON.stringify(toCache(row)));
  return row as SessionRecord;
}

export async function revokeSession(id: string): Promise<void> {
  await redis.del(REDIS_KEYS.session(id));
  await prisma.session.update({
    where: { id },
    data: { revokedAt: new Date() },
  }).catch(() => { /* already gone */ });
}

export async function revokeAllForUser(userId: string): Promise<void> {
  const rows = await prisma.session.findMany({
    where: { userId, revokedAt: null },
    select: { id: true },
  });
  await Promise.all(rows.map(r => redis.del(REDIS_KEYS.session(r.id))));
  await prisma.session.updateMany({
    where: { userId, revokedAt: null },
    data: { revokedAt: new Date() },
  });
}

function toCache(r: { id: string; userId: string; ip: string | null; userAgent: string | null; createdAt: Date; expiresAt: Date }) {
  return {
    id: r.id,
    userId: r.userId,
    ip: r.ip,
    userAgent: r.userAgent,
    createdAt: r.createdAt.toISOString(),
    expiresAt: r.expiresAt.toISOString(),
  };
}

function fromCache(raw: string): SessionRecord {
  const obj = JSON.parse(raw);
  return {
    ...obj,
    createdAt: new Date(obj.createdAt),
    expiresAt: new Date(obj.expiresAt),
  };
}

export const SESSION_COOKIE = 'session';
export const CSRF_HEADER = 'x-csrf-token';

