/**
 * Double-submit CSRF — cookie `csrf_token` + header `X-CSRF-Token` phải khớp.
 * Check cho mọi POST/PUT/PATCH/DELETE từ browser. Bỏ qua /auth/login để bootstrap.
 */

import type { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { randomBytes } from 'node:crypto';
import { CSRF_HEADER } from '../lib/session.js';
import { config } from '../config.js';

const CSRF_COOKIE = 'csrf_token';
const MUTATION_METHODS = new Set(['POST', 'PUT', 'PATCH', 'DELETE']);
const EXEMPT_ROUTES = [/^\/v1\/auth\/login$/, /^\/v1\/health$/];

export function registerCsrf(app: FastifyInstance) {
  // Phát token nếu thiếu — BE cho phép FE đọc qua /auth/me
  app.addHook('onRequest', async (req, reply) => {
    const existing = req.cookies[CSRF_COOKIE];
    if (!existing) {
      const token = randomBytes(32).toString('base64url');
      reply.setCookie(CSRF_COOKIE, token, {
        path: '/',
        httpOnly: false,     // FE cần đọc để đặt header
        secure: config.isProd,
        sameSite: 'strict',
      });
    }
  });

  app.addHook('preHandler', async (req: FastifyRequest, reply: FastifyReply) => {
    if (!MUTATION_METHODS.has(req.method)) return;
    if (EXEMPT_ROUTES.some(re => re.test(req.url))) return;

    const cookieTok = req.cookies[CSRF_COOKIE];
    const headerTok = req.headers[CSRF_HEADER] as string | undefined;
    if (!cookieTok || !headerTok || cookieTok !== headerTok) {
      reply.code(403).send({
        error: 'csrf_invalid',
        message: 'CSRF token mismatch',
        requestId: req.id,
      });
      throw reply;
    }
  });
}

