/**
 * Auth routes — email + password + TOTP (2 bước).
 *
 * Flow:
 *   POST /auth/login  { email, password }   → { challenge_id, require_totp: true }
 *   POST /auth/totp   { challenge_id, code } → set session cookie
 *   POST /auth/logout                        → revoke session
 *   GET  /auth/me                            → user + permission
 *
 * Sai password:
 *  - Tăng failed_logins; ≥5 → lock 30 phút
 *  - Response time đồng nhất ~200ms để chống enumeration email
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { randomBytes, randomUUID } from 'node:crypto';
import { prisma } from '../lib/prisma.js';
import { redis, REDIS_KEYS } from '../lib/redis.js';
import { verifyPassword } from '../lib/password.js';
import { verifyTotp } from '../lib/totp.js';
import { createSession, resolveSession, revokeSession, SESSION_COOKIE } from '../lib/session.js';
import { permissionsForUser } from '../lib/rbac.js';
import { writeAudit } from '../lib/audit.js';
import { config } from '../config.js';

const LoginBody = z.object({
  email: z.string().email().max(255),
  password: z.string().min(1).max(256),
});

const TotpBody = z.object({
  challenge_id: z.string().min(10).max(128),
  code: z.string().regex(/^[0-9]{6}$/),
  trust_device: z.boolean().optional().default(false),
});

const LOCK_THRESHOLD = 5;
const LOCK_DURATION_MIN = 30;
const CHALLENGE_TTL_SEC = 300;

async function delayUniform() {
  const jitter = 180 + Math.floor(Math.random() * 40);
  await new Promise(r => setTimeout(r, jitter));
}

export const authRoutes: FastifyPluginAsync = async app => {
  app.post('/auth/login', async (req, reply) => {
    const body = LoginBody.parse(req.body);
    const started = Date.now();

    const user = await prisma.user.findUnique({ where: { email: body.email } });

    // Check lockout
    if (user?.lockedUntil && user.lockedUntil > new Date()) {
      await delayUniform();
      return reply.code(423).send({
        error: 'locked',
        message: 'Tài khoản bị khoá tạm thời, thử lại sau',
        requestId: req.id,
      });
    }

    const ok = user ? await verifyPassword(body.password, user.passwordHash) : false;

    if (!user || !ok) {
      if (user) {
        const failed = user.failedLogins + 1;
        const shouldLock = failed >= LOCK_THRESHOLD;
        await prisma.user.update({
          where: { id: user.id },
          data: {
            failedLogins: failed,
            lockedUntil: shouldLock ? new Date(Date.now() + LOCK_DURATION_MIN * 60_000) : user.lockedUntil,
          },
        });
        await writeAudit({
          action: 'auth.login.failed',
          actorEmail: user.email,
          actorIp: req.ip,
          userAgent: req.headers['user-agent'] ?? null,
          requestId: req.id,
        });
      }
      // Đồng nhất thời gian response ~200ms
      const elapsed = Date.now() - started;
      if (elapsed < 200) await new Promise(r => setTimeout(r, 200 - elapsed));
      return reply.code(401).send({
        error: 'invalid_credentials',
        message: 'Email hoặc mật khẩu sai',
        requestId: req.id,
      });
    }

    if (user.status !== 'active') {
      return reply.code(403).send({ error: 'account_disabled', requestId: req.id });
    }

    // Nếu user bật TOTP → yêu cầu bước 2
    if (user.totpEnabled && user.totpSecretEnc) {
      const challengeId = randomBytes(24).toString('base64url');
      await redis.setex(
        REDIS_KEYS.challenge(challengeId),
        CHALLENGE_TTL_SEC,
        JSON.stringify({ userId: user.id, at: Date.now() }),
      );
      return { challenge_id: challengeId, require_totp: true };
    }

    // Không bật TOTP → tạo session ngay (cảnh báo banner cho user bật sau)
    const session = await createSession({
      userId: user.id,
      ip: req.ip,
      userAgent: req.headers['user-agent'] ?? null,
    });
    setSessionCookie(reply, session.id, session.expiresAt);
    await prisma.user.update({
      where: { id: user.id },
      data: { lastLoginAt: new Date(), lastLoginIp: req.ip, failedLogins: 0, lockedUntil: null },
    });
    await writeAudit({
      action: 'auth.login.success',
      actorId: user.id,
      actorEmail: user.email,
      actorIp: req.ip,
      userAgent: req.headers['user-agent'] ?? null,
      requestId: req.id,
    });

    const permissions = await permissionsForUser(user.id);
    return {
      user: publicUser(user),
      permissions: [...permissions],
      session: { id: session.id, expires_at: session.expiresAt.toISOString() },
      warning: 'totp_not_enabled',
    };
  });

  app.post('/auth/totp', async (req, reply) => {
    const body = TotpBody.parse(req.body);
    const raw = await redis.get(REDIS_KEYS.challenge(body.challenge_id));
    if (!raw) {
      return reply.code(401).send({ error: 'challenge_expired', requestId: req.id });
    }
    const { userId } = JSON.parse(raw) as { userId: string };
    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user || !user.totpSecretEnc) {
      return reply.code(401).send({ error: 'invalid_state', requestId: req.id });
    }

    // TODO: giải mã secret qua libsodium secretbox. Hiện tại giả định plain base32 trong dev.
    const secret = user.totpSecretEnc;
    if (!verifyTotp(secret, body.code)) {
      await writeAudit({
        action: 'auth.totp.failed',
        actorId: user.id,
        actorEmail: user.email,
        actorIp: req.ip,
        userAgent: req.headers['user-agent'] ?? null,
        requestId: req.id,
      });
      return reply.code(401).send({ error: 'invalid_totp', requestId: req.id });
    }

    await redis.del(REDIS_KEYS.challenge(body.challenge_id));

    const session = await createSession({
      userId: user.id,
      ip: req.ip,
      userAgent: req.headers['user-agent'] ?? null,
    });
    setSessionCookie(reply, session.id, session.expiresAt);
    await prisma.user.update({
      where: { id: user.id },
      data: { lastLoginAt: new Date(), lastLoginIp: req.ip, failedLogins: 0, lockedUntil: null },
    });
    await writeAudit({
      action: 'auth.login.success',
      actorId: user.id,
      actorEmail: user.email,
      actorIp: req.ip,
      userAgent: req.headers['user-agent'] ?? null,
      requestId: req.id,
    });

    const permissions = await permissionsForUser(user.id);
    return {
      user: publicUser(user),
      permissions: [...permissions],
      session: { id: session.id, expires_at: session.expiresAt.toISOString() },
    };
  });

  app.post('/auth/logout', async (req, reply) => {
    const sid = req.cookies[SESSION_COOKIE];
    if (sid) {
      await revokeSession(sid);
      await writeAudit({
        action: 'auth.logout',
        actorId: req.auth?.user.id ?? null,
        actorEmail: req.auth?.user.email ?? null,
        actorIp: req.ip,
        requestId: req.id,
      });
    }
    reply.clearCookie(SESSION_COOKIE, { path: '/' });
    reply.code(204).send();
  });

  app.get('/auth/me', async (req, reply) => {
    if (!req.auth) {
      return reply.code(401).send({ error: 'unauthorized', requestId: req.id });
    }
    const user = await prisma.user.findUnique({ where: { id: req.auth.user.id } });
    if (!user) return reply.code(401).send({ error: 'unauthorized', requestId: req.id });
    const session = await resolveSession(req.auth.sessionId);
    return {
      user: publicUser(user),
      permissions: [...req.auth.permissions],
      session: session
        ? { id: session.id, expires_at: session.expiresAt.toISOString() }
        : null,
    };
  });
};

function setSessionCookie(reply: import('fastify').FastifyReply, id: string, expiresAt: Date) {
  reply.setCookie(SESSION_COOKIE, id, {
    path: '/',
    httpOnly: true,
    secure: config.isProd,
    sameSite: 'strict',
    expires: expiresAt,
  });
}

function publicUser(u: { id: string; email: string; name: string; avatarUrl: string | null; status: string; totpEnabled: boolean; lastLoginAt: Date | null; createdAt: Date }) {
  return {
    id: u.id,
    email: u.email,
    name: u.name,
    avatar_url: u.avatarUrl,
    status: u.status,
    totp_enabled: u.totpEnabled,
    last_login_at: u.lastLoginAt?.toISOString() ?? null,
    created_at: u.createdAt.toISOString(),
  };
}

