/**
 * Products routes — implement OpenAPI spec docs/api/openapi.yaml.
 * Đổi gì ở đây, nhớ sync lại YAML.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { slugify } from '../lib/slug.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';

// ─── Schemas ────────────────────────────────────────────────────

const ListQuery = z.object({
  q:        z.string().max(200).optional(),
  category: z.string().optional(),
  status:   z.enum(['active', 'draft', 'archived']).optional(),
  stock:    z.enum(['low', 'out', 'ok']).optional(),
  sort:     z.enum(['updated', 'created', 'name', 'price-asc', 'price-desc', 'stock-asc']).default('updated'),
  page:     z.coerce.number().int().min(1).default(1),
  limit:    z.coerce.number().int().min(1).max(100).default(20),
});

const VariantInput = z.object({
  id: z.string().uuid().optional(),
  skuSuffix: z.string().min(1).max(32),
  size: z.string().max(32).optional(),
  price: z.coerce.number().int().nonnegative().nullable().optional(),
  cost: z.coerce.number().int().nonnegative().nullable().optional(),
  stock: z.coerce.number().int().nonnegative().default(0),
  lowStockThreshold: z.coerce.number().int().nonnegative().optional(),
  position: z.coerce.number().int().nonnegative().optional(),
});

const ProductCreateBody = z.object({
  code: z.string().min(1).max(64).transform(s => s.trim().toUpperCase()),
  name: z.string().min(1).max(255),
  slug: z.string().min(1).max(120).optional(),
  categoryId: z.string().uuid().nullable().optional(),
  shortDesc: z.string().max(500).nullable().optional(),
  description: z.string().max(20_000).nullable().optional(),
  ingredients: z.string().max(5_000).nullable().optional(),
  highlights: z.array(z.string().max(200)).max(20).optional(),
  price: z.coerce.number().int().positive(),
  compareAtPrice: z.coerce.number().int().nonnegative().nullable().optional(),
  cost: z.coerce.number().int().nonnegative().nullable().optional(),
  tag: z.string().max(50).nullable().optional(),
  tagClass: z.string().max(50).nullable().optional(),
  status: z.enum(['active', 'draft', 'archived']).default('draft'),
  lowStockThreshold: z.coerce.number().int().nonnegative().default(5),
  seoTitle: z.string().max(120).nullable().optional(),
  seoDesc: z.string().max(200).nullable().optional(),
  variants: z.array(VariantInput).max(50).optional(),
}).strict();

const ProductUpdateBody = ProductCreateBody.partial().strict();

const BulkBody = z.object({
  ids: z.array(z.string().uuid()).min(1).max(500),
  action: z.enum(['setStatus', 'delete']),
  status: z.enum(['active', 'draft', 'archived']).optional(),
}).strict();

// ─── Helpers ────────────────────────────────────────────────────

function serialize(p: ProductWithRelations) {
  return {
    id: p.id,
    code: p.code,
    slug: p.slug,
    name: p.name,
    category_id: p.categoryId,
    short_desc: p.shortDesc,
    description: p.description,
    ingredients: p.ingredients,
    highlights: p.highlights,
    price: Number(p.price),
    compare_at_price: p.compareAtPrice !== null ? Number(p.compareAtPrice) : null,
    cost: p.cost !== null ? Number(p.cost) : null,
    tag: p.tag,
    tag_class: p.tagClass,
    status: p.status,
    rating_avg: p.ratingAvg,
    rating_count: p.ratingCount,
    low_stock_threshold: p.lowStockThreshold,
    seo_title: p.seoTitle,
    seo_desc: p.seoDesc,
    stock: p.variants.reduce((s, v) => s + v.stock, 0),
    variants: p.variants.map(v => ({
      id: v.id,
      sku_suffix: v.skuSuffix,
      size: v.size,
      price: v.price !== null ? Number(v.price) : null,
      stock: v.stock,
      low_stock_threshold: v.lowStockThreshold,
    })),
    images: p.images.map(i => ({
      id: i.id,
      cdn_url: i.media.cdnUrl,
      alt: i.alt,
      is_primary: i.isPrimary,
    })),
    created_at: p.createdAt.toISOString(),
    updated_at: p.updatedAt.toISOString(),
  };
}

type ProductWithRelations = Prisma.ProductGetPayload<{
  include: {
    variants: true;
    images: { include: { media: true } };
  };
}>;

async function ensureUniqueSlug(base: string, excludeId?: string): Promise<string> {
  let slug = base;
  for (let i = 2; i <= 100; i++) {
    const conflict = await prisma.product.findFirst({
      where: { slug, ...(excludeId ? { NOT: { id: excludeId } } : {}) },
      select: { id: true },
    });
    if (!conflict) return slug;
    slug = `${base}-${i}`;
  }
  throw new Error('Không thể tạo slug duy nhất sau 100 lần thử');
}

// ─── Plugin ─────────────────────────────────────────────────────

export const productRoutes: FastifyPluginAsync = async app => {
  // GET /products
  app.get('/products', { preHandler: [requireAuth, requirePermission('products:read')] }, async req => {
    const q = ListQuery.parse(req.query);

    const where: Prisma.ProductWhereInput = {
      deletedAt: null,
      ...(q.q && {
        OR: [
          { name: { contains: q.q, mode: 'insensitive' } },
          { code: { contains: q.q, mode: 'insensitive' } },
          { shortDesc: { contains: q.q, mode: 'insensitive' } },
        ],
      }),
      ...(q.category && { category: { slug: q.category } }),
      ...(q.status && { status: q.status }),
    };

    const orderBy: Prisma.ProductOrderByWithRelationInput = (() => {
      switch (q.sort) {
        case 'created':    return { createdAt: 'desc' };
        case 'name':       return { name: 'asc' };
        case 'price-asc':  return { price: 'asc' };
        case 'price-desc': return { price: 'desc' };
        default:           return { updatedAt: 'desc' };
      }
    })();

    const [total, data] = await Promise.all([
      prisma.product.count({ where }),
      prisma.product.findMany({
        where,
        orderBy,
        skip: (q.page - 1) * q.limit,
        take: q.limit,
        include: { variants: true, images: { include: { media: true }, orderBy: { position: 'asc' } } },
      }),
    ]);

    // Filter stock sau query (vì cần sum variants). Nếu perf thành vấn đề → materialized view.
    const filtered = data.filter(p => {
      if (!q.stock) return true;
      const total = p.variants.reduce((s, v) => s + v.stock, 0);
      if (q.stock === 'out') return total === 0;
      if (q.stock === 'low') return total > 0 && total <= p.lowStockThreshold;
      return total > p.lowStockThreshold;
    });

    return {
      data: filtered.map(serialize),
      total,
      page: q.page,
      pageSize: q.limit,
    };
  });

  // GET /products/:id
  app.get<{ Params: { id: string } }>('/products/:id', {
    preHandler: [requireAuth, requirePermission('products:read')],
  }, async (req, reply) => {
    const p = await prisma.product.findFirst({
      where: { id: req.params.id, deletedAt: null },
      include: { variants: true, images: { include: { media: true }, orderBy: { position: 'asc' } } },
    });
    if (!p) return reply.code(404).send({ error: 'not_found', requestId: req.id });
    return serialize(p);
  });

  // POST /products
  app.post('/products', { preHandler: [requireAuth, requirePermission('products:write')] }, async (req, reply) => {
    const body = ProductCreateBody.parse(req.body);
    const slugBase = slugify(body.slug ?? body.name);
    const slug = await ensureUniqueSlug(slugBase);

    const created = await prisma.$transaction(async tx => {
      const existing = await tx.product.findUnique({ where: { code: body.code } });
      if (existing) {
        reply.code(409);
        throw new Error(`Mã SKU ${body.code} đã tồn tại`);
      }
      const p = await tx.product.create({
        data: {
          code: body.code,
          slug,
          name: body.name,
          categoryId: body.categoryId ?? null,
          shortDesc: body.shortDesc ?? null,
          description: body.description ?? null,
          ingredients: body.ingredients ?? null,
          highlights: body.highlights ?? [],
          price: BigInt(body.price),
          compareAtPrice: body.compareAtPrice != null ? BigInt(body.compareAtPrice) : null,
          cost: body.cost != null ? BigInt(body.cost) : null,
          tag: body.tag ?? null,
          tagClass: body.tagClass ?? null,
          status: body.status,
          lowStockThreshold: body.lowStockThreshold,
          seoTitle: body.seoTitle ?? null,
          seoDesc: body.seoDesc ?? null,
          variants: body.variants
            ? {
                create: body.variants.map(v => ({
                  skuSuffix: v.skuSuffix,
                  size: v.size ?? null,
                  price: v.price != null ? BigInt(v.price) : null,
                  cost: v.cost != null ? BigInt(v.cost) : null,
                  stock: v.stock,
                  lowStockThreshold: v.lowStockThreshold ?? 5,
                  position: v.position ?? 0,
                })),
              }
            : undefined,
        },
        include: { variants: true, images: { include: { media: true } } },
      });
      await writeAudit({
        action: 'product.create',
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        actorIp: req.ip,
        userAgent: req.headers['user-agent'] ?? null,
        entity: 'product',
        entityId: p.id,
        diff: { after: { code: p.code, name: p.name, price: Number(p.price) } },
        requestId: req.id,
      }, tx);
      return p;
    });

    reply.code(201);
    return serialize(created);
  });

  // PATCH /products/:id
  app.patch<{ Params: { id: string } }>('/products/:id', {
    preHandler: [requireAuth, requirePermission('products:write')],
  }, async (req, reply) => {
    const body = ProductUpdateBody.parse(req.body);
    const updated = await prisma.$transaction(async tx => {
      const existing = await tx.product.findFirst({
        where: { id: req.params.id, deletedAt: null },
        include: { variants: true },
      });
      if (!existing) {
        reply.code(404);
        throw new Error('not_found');
      }

      const data: Prisma.ProductUpdateInput = {};
      const changed: Record<string, { before: unknown; after: unknown }> = {};

      const updatableFields: Array<keyof typeof body> = [
        'name', 'shortDesc', 'description', 'ingredients', 'tag', 'tagClass',
        'status', 'lowStockThreshold', 'seoTitle', 'seoDesc',
      ];
      for (const f of updatableFields) {
        if (body[f] !== undefined && body[f] !== (existing as Record<string, unknown>)[f]) {
          (data as Record<string, unknown>)[f] = body[f];
          changed[f] = { before: (existing as Record<string, unknown>)[f], after: body[f] };
        }
      }
      if (body.highlights !== undefined) {
        data.highlights = body.highlights;
        changed.highlights = { before: existing.highlights, after: body.highlights };
      }
      if (body.price !== undefined) {
        data.price = BigInt(body.price);
        changed.price = { before: Number(existing.price), after: body.price };
      }
      if (body.compareAtPrice !== undefined) {
        data.compareAtPrice = body.compareAtPrice != null ? BigInt(body.compareAtPrice) : null;
      }
      if (body.cost !== undefined) {
        data.cost = body.cost != null ? BigInt(body.cost) : null;
      }
      if (body.slug !== undefined) {
        const slugBase = slugify(body.slug);
        data.slug = await ensureUniqueSlug(slugBase, existing.id);
      }
      if (body.categoryId !== undefined) {
        data.category = body.categoryId
          ? { connect: { id: body.categoryId } }
          : { disconnect: true };
      }

      const p = await tx.product.update({
        where: { id: existing.id },
        data,
        include: { variants: true, images: { include: { media: true } } },
      });

      if (Object.keys(changed).length) {
        await writeAudit({
          action: 'product.update',
          actorId: req.auth!.user.id,
          actorEmail: req.auth!.user.email,
          actorIp: req.ip,
          userAgent: req.headers['user-agent'] ?? null,
          entity: 'product',
          entityId: p.id,
          diff: changed,
          requestId: req.id,
        }, tx);
      }
      return p;
    });

    return serialize(updated);
  });

  // DELETE /products/:id (soft delete)
  app.delete<{ Params: { id: string } }>('/products/:id', {
    preHandler: [requireAuth, requirePermission('products:write')],
  }, async (req, reply) => {
    await prisma.$transaction(async tx => {
      const existing = await tx.product.findFirst({ where: { id: req.params.id, deletedAt: null } });
      if (!existing) {
        reply.code(404);
        throw new Error('not_found');
      }
      await tx.product.update({
        where: { id: existing.id },
        data: { deletedAt: new Date(), status: 'archived' },
      });
      await writeAudit({
        action: 'product.delete',
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        actorIp: req.ip,
        userAgent: req.headers['user-agent'] ?? null,
        entity: 'product',
        entityId: existing.id,
        diff: { before: { code: existing.code, name: existing.name } },
        requestId: req.id,
      }, tx);
    });
    reply.code(204);
  });

  // POST /products/bulk
  app.post('/products/bulk', { preHandler: [requireAuth, requirePermission('products:write')] }, async req => {
    const body = BulkBody.parse(req.body);
    let affected = 0;
    await prisma.$transaction(async tx => {
      if (body.action === 'setStatus') {
        if (!body.status) throw new Error('status required');
        const res = await tx.product.updateMany({
          where: { id: { in: body.ids }, deletedAt: null },
          data: { status: body.status },
        });
        affected = res.count;
      } else {
        const res = await tx.product.updateMany({
          where: { id: { in: body.ids }, deletedAt: null },
          data: { deletedAt: new Date(), status: 'archived' },
        });
        affected = res.count;
      }
      await writeAudit({
        action: `product.bulk.${body.action}`,
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        actorIp: req.ip,
        userAgent: req.headers['user-agent'] ?? null,
        entity: 'product',
        entityId: null,
        diff: { after: { ids: body.ids, action: body.action, status: body.status ?? null, affected } },
        requestId: req.id,
      }, tx);
    });
    return { affected };
  });
};

