/**
 * Media routes — presigned upload lên Cloudflare R2.
 * FE gọi POST /media/presign → nhận uploadUrl → PUT trực tiếp lên R2 → gọi POST /media/confirm.
 *
 * Lý do không proxy qua BE: tránh chiếm RAM/băng thông, 10MB/file × N user ≈ disk IO kiểu.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { randomUUID, createHash } from 'node:crypto';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { prisma } from '../lib/prisma.js';
import { config } from '../config.js';

const ALLOWED_MIME = new Set([
  'image/webp', 'image/jpeg', 'image/png', 'image/avif',
  'application/pdf',
]);

const PresignBody = z.object({
  mime: z.string().max(80).refine(m => ALLOWED_MIME.has(m), 'MIME không hỗ trợ'),
  size: z.coerce.number().int().positive().max(10 * 1024 * 1024, 'Tối đa 10MB'),
  scope: z.enum(['product', 'article', 'avatar']),
  sha256: z.string().regex(/^[a-f0-9]{64}$/).optional(),
}).strict();

const ConfirmBody = z.object({
  fileKey: z.string().max(300),
  mime: z.string().max(80),
  size: z.coerce.number().int().positive(),
  sha256: z.string().regex(/^[a-f0-9]{64}$/),
  scope: z.enum(['product', 'article', 'avatar']),
  width: z.coerce.number().int().positive().optional(),
  height: z.coerce.number().int().positive().optional(),
}).strict();

export const mediaRoutes: FastifyPluginAsync = async app => {
  app.post('/media/presign', {
    preHandler: [requireAuth, requirePermission('products:write')],
  }, async req => {
    const body = PresignBody.parse(req.body);

    // Dedupe theo sha256 — nếu đã upload trước đó, trả luôn URL cũ
    if (body.sha256) {
      const existing = await prisma.media.findFirst({ where: { sha256: body.sha256 } });
      if (existing) {
        return {
          deduped: true,
          fileKey: existing.r2Key,
          cdnUrl: existing.cdnUrl,
        };
      }
    }

    const ext = extFromMime(body.mime);
    const id = randomUUID();
    const fileKey = `media/${body.scope}/${id.slice(0, 2)}/${id}${ext}`;

    // TODO: sign URL thật bằng AWS SigV4 cho R2. Hiện stub endpoint.
    const uploadUrl = `https://${config.R2_BUCKET}.${config.R2_ACCOUNT_ID ?? 'dev'}.r2.cloudflarestorage.com/${fileKey}?X-Amz-Expires=900&stub=1`;
    const cdnUrl = `${config.R2_PUBLIC_BASE ?? 'https://media.detoxblanc.com'}/${fileKey}`;

    return {
      uploadUrl,
      fileKey,
      cdnUrl,
      expiresAt: new Date(Date.now() + 15 * 60_000).toISOString(),
    };
  });

  app.post('/media/confirm', {
    preHandler: [requireAuth, requirePermission('products:write')],
  }, async req => {
    const body = ConfirmBody.parse(req.body);
    const cdnUrl = `${config.R2_PUBLIC_BASE ?? 'https://media.detoxblanc.com'}/${body.fileKey}`;
    const m = await prisma.media.create({
      data: {
        r2Key: body.fileKey,
        cdnUrl,
        mime: body.mime,
        size: body.size,
        width: body.width ?? null,
        height: body.height ?? null,
        sha256: body.sha256,
        scope: body.scope,
        uploadedBy: req.auth!.user.id,
      },
    });
    return { id: m.id, cdnUrl: m.cdnUrl };
  });
};

function extFromMime(mime: string): string {
  switch (mime) {
    case 'image/webp': return '.webp';
    case 'image/jpeg': return '.jpg';
    case 'image/png':  return '.png';
    case 'image/avif': return '.avif';
    case 'application/pdf': return '.pdf';
    default: return '';
  }
}

