/**
 * Users management — chỉ owner/admin có quyền users:write.
 * Phase 1 stub: list + invite. Accept/activate flow Phase 1.5.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { writeAudit } from '../lib/audit.js';
import { hashPassword } from '../lib/password.js';
import { randomBytes } from 'node:crypto';

const InviteBody = z.object({
  email: z.string().email().max(255),
  name: z.string().min(1).max(120),
  roles: z.array(z.string().min(1)).min(1).max(5),
}).strict();

export const userRoutes: FastifyPluginAsync = async app => {
  app.get('/users', { preHandler: [requireAuth, requirePermission('users:read')] }, async () => {
    const users = await prisma.user.findMany({
      where: { status: { not: 'deleted' } },
      include: { roles: { include: { role: true } } },
      orderBy: { createdAt: 'desc' },
    });
    return users.map(u => ({
      id: u.id,
      email: u.email,
      name: u.name,
      avatar_url: u.avatarUrl,
      status: u.status,
      roles: u.roles.map(r => r.role.key),
      totp_enabled: u.totpEnabled,
      last_login_at: u.lastLoginAt?.toISOString() ?? null,
      created_at: u.createdAt.toISOString(),
    }));
  });

  app.post('/users', { preHandler: [requireAuth, requirePermission('users:write')] }, async (req, reply) => {
    const body = InviteBody.parse(req.body);

    // Reject nếu cố promote sang 'owner' không phải chính owner hiện tại (cần approve riêng)
    if (body.roles.includes('owner') && !req.auth!.permissions.has('users:write')) {
      return reply.code(403).send({ error: 'forbidden', message: 'Cấp owner cần quy trình riêng' });
    }

    const existing = await prisma.user.findUnique({ where: { email: body.email } });
    if (existing) return reply.code(409).send({ error: 'email_taken' });

    // Generate temp password, yêu cầu đổi lần đầu đăng nhập. Phase 1.5: email invite token magic link.
    const tempPassword = randomBytes(12).toString('base64url');
    const hash = await hashPassword(tempPassword);

    const user = await prisma.$transaction(async tx => {
      const u = await tx.user.create({
        data: {
          email: body.email,
          name: body.name,
          passwordHash: hash,
          status: 'active',
        },
      });
      for (const roleKey of body.roles) {
        const role = await tx.role.findUnique({ where: { key: roleKey } });
        if (!role) continue;
        await tx.userRole.create({ data: { userId: u.id, roleId: role.id, grantedBy: req.auth!.user.id } });
      }
      await writeAudit({
        action: 'user.invite',
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        actorIp: req.ip,
        entity: 'user',
        entityId: u.id,
        diff: { after: { email: body.email, name: body.name, roles: body.roles } },
        requestId: req.id,
      }, tx);
      return u;
    });

    reply.code(201);
    return {
      id: user.id,
      email: user.email,
      name: user.name,
      // TODO Phase 1.5: gửi email invite có magic link thay vì trả temp password về client
      _dev_temp_password: tempPassword,
    };
  });
};

