-- Chạy SAU khi prisma migrate deploy ở production.
-- Tạo role ứng dụng, grant tối thiểu, REVOKE quyền xoá audit_logs.

-- 1. Tạo role ứng dụng (nếu chưa có)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'detox_app') THEN
    CREATE ROLE detox_app LOGIN PASSWORD :'APP_PASSWORD';
  END IF;
END$$;

-- 2. Cấp quyền schema + bảng
GRANT USAGE ON SCHEMA public TO detox_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO detox_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO detox_app;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO detox_app;
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  GRANT USAGE, SELECT ON SEQUENCES TO detox_app;

-- 3. Audit log — KHÔNG cho phép UPDATE/DELETE
REVOKE UPDATE, DELETE ON audit_logs FROM detox_app, PUBLIC;
GRANT INSERT, SELECT ON audit_logs TO detox_app;
GRANT USAGE, SELECT ON SEQUENCE audit_logs_id_seq TO detox_app;

-- 4. Optional: constraint DB-level để chặn luôn ở mức statement
-- (Rule DO INSTEAD NOTHING cho UPDATE/DELETE sẽ block cả superuser nếu chạy app)
-- CREATE RULE audit_logs_no_update AS ON UPDATE TO audit_logs DO INSTEAD NOTHING;
-- CREATE RULE audit_logs_no_delete AS ON DELETE TO audit_logs DO INSTEAD NOTHING;

