import { describe, it, expect } from 'vitest';
import { createHash } from 'node:crypto';

// Scrub logic inline để test không cần mock Prisma
function scrub(value: unknown): unknown {
  const SENSITIVE = new Set(['password', 'token', 'secret', 'totp']);
  if (value === null || value === undefined) return value;
  if (Array.isArray(value)) return value.map(scrub);
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = SENSITIVE.has(k) ? '[REDACTED]' : scrub(v);
    }
    return out;
  }
  return value;
}

describe('audit diff scrubber', () => {
  it('redact password + token + secret nested', () => {
    const input = {
      before: { name: 'Alice', password: 'x', token: 'y', meta: { secret: 's' } },
      after:  { name: 'Bob' },
    };
    const out = scrub(input) as Record<string, Record<string, unknown>>;
    expect(out.before.password).toBe('[REDACTED]');
    expect(out.before.token).toBe('[REDACTED]');
    expect((out.before.meta as Record<string, unknown>).secret).toBe('[REDACTED]');
    expect(out.before.name).toBe('Alice');
  });

  it('không đụng field thường', () => {
    expect(scrub({ email: 'a@b.com', price: 1000 })).toEqual({ email: 'a@b.com', price: 1000 });
  });
});

describe('hash chain', () => {
  it('computeHash deterministic + phụ thuộc prev', () => {
    const row = { action: 'x', entity: 'y' };
    const h1 = createHash('sha256').update('').update(JSON.stringify(row)).digest('hex');
    const h2 = createHash('sha256').update(h1).update(JSON.stringify(row)).digest('hex');
    expect(h1).not.toBe(h2);
    // Same input + same prev → same hash
    const h1b = createHash('sha256').update('').update(JSON.stringify(row)).digest('hex');
    expect(h1).toBe(h1b);
  });
});

