  function slug(s){
    return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')
      .replace(/đ/g,'d').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80);
  }

  function normalize(p, i){
    const now = new Date().toISOString();
    const id = p.id || ('sku_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,7));
    return {
      id,
      code: p.code || ('SKU-' + (i+1)),
      name: p.name || 'Sản phẩm chưa đặt tên',
      category: p.category || 'Chưa phân loại',
      ingr: p.ingr || '',
      bullets: p.bullets || [p.b1, p.b2].filter(Boolean),
      tag: p.tag || null,
      tagCls: p.tagCls || p.cls || 'tag-green',
      rating: Number(p.rating || 4.8),
      reviews: Number(String(p.reviews || 0).replace(/[^\d]/g,'') || 0),
      price: Number(p.price || 0),
      old: p.old ? Number(String(p.old).replace(/[^\d]/g,'')) : null,
      stock: Number(p.stock != null ? p.stock : 100),
      lowStock: Number(p.lowStock || 30),
      status: p.status || 'active',
      slug: p.slug || slug(p.name || p.code || id),
      seoTitle: p.seoTitle || '',
      seoDesc: p.seoDesc || '',
      description: p.description || '',
      tags: Array.isArray(p.tags) ? p.tags : [],
      grad: p.grad || '#63C1BB',
      variants: Array.isArray(p.variants) ? p.variants : [],
      createdAt: p.createdAt || now,
      updatedAt: now,
    };
  }

  function load(){
    try {
      const raw = localStorage.getItem(KEY);
      if (raw) return JSON.parse(raw);
    } catch(_){}
    return null;
  }

  function save(list){
    localStorage.setItem(KEY, JSON.stringify(list));
    window.dispatchEvent(new CustomEvent('dtx:products-updated', { detail:{ count:list.length } }));
  }

  function seedIfNeeded(){
    if (localStorage.getItem(SEED_KEY)) return load() || [];
    const seeded = SEED.map((p, i) => normalize(p, i));
    save(seeded);
    localStorage.setItem(SEED_KEY, '1');
    return seeded;
  }

  const API = {
    all(){ return load() || seedIfNeeded() },
    get(id){ return (this.all()).find(p => p.id === id) || null },
    create(partial){
      const list = this.all();
      const p = normalize({ ...partial, createdAt: new Date().toISOString() }, list.length);
      list.unshift(p);
      save(list);
      return p;
    },
    update(id, patch){
      const list = this.all();
      const idx = list.findIndex(p => p.id === id);
      if (idx < 0) return null;
      list[idx] = normalize({ ...list[idx], ...patch, id }, idx);
      save(list);
      return list[idx];
    },
    remove(id){
      const list = this.all().filter(p => p.id !== id);
      save(list);
    },
    removeMany(ids){
      const set = new Set(ids);
      save(this.all().filter(p => !set.has(p.id)));
    },
    setStatus(ids, status){
      const set = new Set(ids);
      const list = this.all().map(p => set.has(p.id) ? { ...p, status, updatedAt: new Date().toISOString() } : p);
      save(list);
    },
    reset(){
      localStorage.removeItem(KEY);
      localStorage.removeItem(SEED_KEY);
      return this.all();
    },
    formatVND(n){
      if (n == null) return '';
      return Number(n).toLocaleString('vi-VN') + '₫';
    },
    slug,
  };

  window.DTX_ADMIN = API;
})();

/* =========================================================================
   Detoxblanc Admin — shared shell (sidebar + topbar) injector.

   Usage in any admin page:
     <body data-adm-page="products">
       <a class="skip-link" href="#adm-content">Đi tới nội dung chính</a>
       <div class="adm-app">
         <div data-adm-shell
              data-crumbs='[{"label":"Admin","href":"admin.html"},{"label":"Sản phẩm"}]'
              data-title="Sản phẩm">
         </div>
         <div class="adm-canvas">
           <!-- topbar + page content rendered by shell -->
         </div>
       </div>
       <script src="assets/admin-shell.js"></script>

   The shell reads:
     body[data-adm-page]       — key matched against nav items (active state)
     [data-adm-shell]          — mount point (replaced by sidebar)
     [data-crumbs]             — JSON array of {label,href?} for breadcrumbs
     [data-title]              — topbar page title (optional)
   ========================================================================= */
(function(){
  'use strict';

  /* ---------------- Navigation config ---------------- */
  const NAV = [
    { group: 'Tổng quan', items: [
      { key:'dashboard', href:'admin.html',            icon:'gauge-high',    label:'Dashboard' },
      { key:'analytics', href:'#',                      icon:'chart-line',    label:'Phân tích' },
      { key:'reports',   href:'#',                      icon:'file-invoice',  label:'Báo cáo' },
    ]},
    { group: 'Bán hàng', items: [
      { key:'orders',    href:'#',                      icon:'cart-shopping', label:'Đơn hàng',    count:24 },
      { key:'returns',   href:'#',                      icon:'arrow-rotate-left', label:'Đổi / trả', count:3 },
      { key:'vouchers',  href:'#',                      icon:'ticket',        label:'Voucher' },
      { key:'customers', href:'#',                      icon:'users',         label:'Khách hàng' },
    ]},
    { group: 'Sản phẩm', items: [
      { key:'products',  href:'admin-products.html',   icon:'box-archive',   label:'Catalog', dynamicCount:true },
      { key:'inventory', href:'#',                      icon:'warehouse',     label:'Kho hàng', dotNew:true },
      { key:'collections', href:'#',                    icon:'layer-group',   label:'Bộ sưu tập' },
      { key:'qr',        href:'#',                      icon:'qrcode',        label:'QR chính hãng' },
    ]},
    { group: 'Nội dung', items: [
      { key:'articles',  href:'#',                      icon:'newspaper',     label:'Bài viết' },
      { key:'pages',     href:'#',                      icon:'file-lines',    label:'Trang tĩnh' },
      { key:'reviews',   href:'#',                      icon:'comments',      label:'Đánh giá' },
      { key:'newsletter',href:'#',                      icon:'envelope-open-text', label:'Newsletter' },
    ]},
    { group: 'Hệ thống', items: [
      { key:'users',     href:'#',                      icon:'user-shield',   label:'Người dùng · RBAC' },
      { key:'logs',      href:'#',                      icon:'clipboard-list', label:'Nhật ký' },
      { key:'integrations', href:'#',                   icon:'plug',          label:'Tích hợp' },
      { key:'settings',  href:'#',                      icon:'gear',          label:'Cài đặt' },
    ]},
  ];

  /* ---------------- Helpers ---------------- */
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

  function productCount(){
    try { return (window.DTX_ADMIN?.all()?.length) ?? 34; } catch(_) { return 34; }
  }

  /* ---------------- Sidebar HTML ---------------- */
  function sidebarHTML(activeKey){
    const groupsHTML = NAV.map(g => {
      const itemsHTML = g.items.map(it => {
        const active = it.key === activeKey ? ' class="active"' : '';
        const count = it.dynamicCount
          ? `<span class="count" data-count="products">${productCount()}</span>`
          : (it.count != null ? `<span class="count">${it.count}</span>` : '');
        const dot = it.dotNew ? '<span class="dot-new" aria-label="Thông báo mới"></span>' : '';
        return `<a href="${it.href}"${active} data-nav="${it.key}">
          <i class="fa-solid fa-${it.icon}" aria-hidden="true"></i> ${esc(it.label)}
          ${count}${dot}
        </a>`;
      }).join('');
      return `<div class="adm-nav-group">
        <h6>${esc(g.group)}</h6>
        ${itemsHTML}
      </div>`;
    }).join('');

    return `
      <a class="adm-brand" href="admin.html">
        <span class="mark" aria-hidden="true">DB</span>
        <span>
          <strong>Detoxblanc</strong>
          <small>Admin Console</small>
        </span>
      </a>

      <button class="adm-ws" aria-haspopup="menu" aria-expanded="false" aria-label="Chọn workspace">
        <span class="ws-flag">VN</span>
        <span class="ws-meta">
          <strong>Detoxblanc · Việt Nam</strong>
          <span>Production · Primary</span>
        </span>
        <i class="fa-solid fa-chevron-down chev" aria-hidden="true"></i>
      </button>

      <nav class="adm-nav">${groupsHTML}</nav>

      <div class="adm-side-foot">
        <div class="adm-quota">
          <span>Dung lượng media</span>
          <strong style="color:var(--a-ink);margin-left:6px">6.2 / 10 GB</strong>
          <div class="bar"><i></i></div>
        </div>
        <button class="adm-user" aria-haspopup="menu" aria-expanded="false" aria-label="Menu tài khoản">
          <span class="avatar">MA</span>
          <span class="uinfo">
            <strong>Trần Mai Anh</strong>
            <span>mai.anh@detoxblanc.com</span>
          </span>
          <i class="fa-solid fa-ellipsis-vertical" aria-hidden="true"></i>
        </button>
      </div>
    `;
