  /* ───────────────── Customers ────────────────────────────────── */

  function seedCustomers() {
    const base = [
      { name: 'Nguyễn Mai Anh',   email: 'maianh@example.com',   phone: '0901234567', province: 'TP. Hồ Chí Minh', tags: ['VIP'], spend: 12_480_000, orders: 18 },
