/* --- user cell (customers, users) --- */
.user-cell{ display:flex;align-items:center;gap:10px }
.user-cell .avatar-sm,
.avatar-sm{
  width:34px;height:34px;border-radius:50%;
  background:var(--a-brand-soft);color:var(--a-brand-ink);
  font-weight:700;font-size:13px;
  display:inline-flex;align-items:center;justify-content:center;
  flex:0 0 34px;border:1px solid var(--a-line);
}
.user-cell small{ display:block;color:var(--a-ink-3);font-size:11.5px;margin-top:1px }

/* --- inventory quick adjust --- */
.stock-adjust{
  display:flex;align-items:center;gap:4px;
}
.stock-adjust input{
  width:72px;height:30px;text-align:right;padding:0 6px;
  border:1px solid var(--a-line);border-radius:var(--a-r-sm);
  background:var(--a-surface);color:var(--a-ink);font-weight:600;
}
.stock-adjust .icon-btn{ width:30px;height:30px }
.stock-adjust .adm-btn.sm{ padding:0 8px;height:30px;font-size:12px }

/* --- article card grid --- */
.art-grid{
  display:grid;gap:14px;
  grid-template-columns:repeat(auto-fill, minmax(280px, 1fr));
  margin-top:14px;
}
.art-card{
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:var(--a-r-lg);padding:16px;
  display:flex;flex-direction:column;gap:8px;
  box-shadow:var(--a-shadow-sm);
}
.art-card header{ display:flex;justify-content:space-between;align-items:center;gap:8px }
.art-card h3{ margin:0;font-size:15.5px;line-height:1.35 }
.art-card p{ color:var(--a-ink-2);font-size:13px;margin:0;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;
}
.art-card footer{
  display:flex;justify-content:space-between;align-items:center;gap:8px;
  border-top:1px solid var(--a-line-soft);padding-top:8px;margin-top:auto;
}
.art-card footer small{ color:var(--a-ink-3);font-size:11.5px }

/* --- empty state --- */
.empty-state{
  text-align:center;padding:48px 24px;color:var(--a-ink-3);
}
.empty-state i{ font-size:32px;display:block;margin-bottom:8px;color:var(--a-ink-4) }

/* --- pager --- */
.pager{
  display:flex;justify-content:center;gap:4px;margin-top:16px;flex-wrap:wrap;align-items:center;
}
.pager button{
  min-width:34px;height:34px;padding:0 10px;
  border:1px solid var(--a-line);border-radius:var(--a-r-sm);
  background:var(--a-surface);color:var(--a-ink);cursor:pointer;
  font-weight:500;font-size:13px;
}
.pager button:hover:not(:disabled){ background:var(--a-surface-2) }
.pager button.active{ background:var(--a-brand);color:#fff;border-color:var(--a-brand) }
.pager button:disabled{ opacity:.4;cursor:not-allowed }
.pager .dots{ color:var(--a-ink-4);padding:0 4px }

/* --- chip & badge modifiers --- */
.chip.accent{ background:var(--a-brand-soft);color:var(--a-brand-ink);border-color:transparent }
.chip.info{ background:var(--a-info-soft);color:var(--a-info);border-color:transparent }
.chip.ok{ background:var(--a-success-soft);color:var(--a-success);border-color:transparent }
.chip.warn{ background:var(--a-warn-soft);color:var(--a-warn);border-color:transparent }
.chip.muted{ background:var(--a-surface-2);color:var(--a-ink-3);border-color:var(--a-line) }
.badge i{ margin-right:4px }

/* --- role picker (users) --- */
.role-grid{
  border:1px solid var(--a-line);border-radius:var(--a-r);
  padding:8px;display:grid;gap:6px;grid-template-columns:repeat(auto-fill, minmax(220px, 1fr));
}
.role-grid legend{ padding:0 6px;font-weight:600;color:var(--a-ink-2);font-size:12px }
.role-opt{
  display:flex;gap:8px;align-items:flex-start;padding:8px 10px;
  border:1px solid var(--a-line);border-radius:var(--a-r-sm);
  cursor:pointer;background:var(--a-surface);
}
.role-opt:hover{ border-color:var(--a-brand) }
.role-opt input{ margin-top:3px }
.role-opt strong{ display:block;color:var(--a-ink) }
.role-opt small{ display:block;color:var(--a-ink-3);font-size:11.5px;line-height:1.35 }

.role-perms-preview{
  margin-top:8px;padding:10px;
  background:var(--a-surface-2);border:1px dashed var(--a-line);
  border-radius:var(--a-r-sm);
}
.role-perms-preview code{
  display:inline-block;margin:2px 4px 2px 0;padding:1px 6px;
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:4px;font-size:11px;
}

/* --- matrix (role × permission) --- */
.matrix-wrap{ overflow:auto;border:1px solid var(--a-line);border-radius:var(--a-r) }
.matrix-tbl{ min-width:640px }
.matrix-tbl th.rot{
  writing-mode:vertical-rl;transform:rotate(180deg);
  font-size:11px;padding:8px 4px;vertical-align:bottom;text-align:center;
}
.matrix-tbl td{ text-align:center }
.matrix-tbl td.cell-on{ color:var(--a-success);background:var(--a-success-soft) }
.matrix-tbl td.cell-off{ color:var(--a-ink-4) }

/* --- audit diff modal --- */
.kv-grid{
  display:grid;grid-template-columns:140px 1fr;gap:6px 16px;margin:0;
}
.kv-grid dt{ color:var(--a-ink-3);font-size:12px;font-weight:500 }
.kv-grid dd{ margin:0;color:var(--a-ink);font-size:13px;word-break:break-word }

.diff-wrap{
  display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:8px;
}
.diff-wrap h5{ margin:0 0 6px;font-size:12px;color:var(--a-ink-3);text-transform:uppercase;letter-spacing:.04em }
.diff-wrap pre{
  background:var(--a-surface-2);border:1px solid var(--a-line);
  border-radius:var(--a-r-sm);padding:10px;margin:0;
  font-size:12px;max-height:260px;overflow:auto;
  white-space:pre-wrap;word-break:break-word;
}
@media (max-width:720px){ .diff-wrap{ grid-template-columns:1fr } }

/* --- settings layout --- */
.settings-layout{
  display:grid;grid-template-columns:240px 1fr;gap:14px;margin-top:14px;align-items:flex-start;
}
.settings-nav{ padding:8px;display:flex;flex-direction:column;gap:2px;position:sticky;top:calc(var(--a-topbar) + 12px) }
.settings-tab{
  text-align:left;padding:10px 12px;border:0;background:transparent;
  color:var(--a-ink-2);border-radius:var(--a-r-sm);cursor:pointer;
  font-size:13.5px;display:flex;align-items:center;gap:10px;font-weight:500;
}
.settings-tab:hover{ background:var(--a-surface-2);color:var(--a-ink) }
.settings-tab.active{ background:var(--a-brand-soft);color:var(--a-brand-ink);font-weight:600 }
.settings-tab i{ width:18px;text-align:center }

.settings-pane{ padding:22px }
.settings-panel{ display:none }
.settings-panel.active{ display:block }
.settings-panel h2{ margin:0 0 14px;font-size:18px }
.settings-panel h3{ font-size:14px;color:var(--a-ink-2);margin:18px 0 8px;text-transform:uppercase;letter-spacing:.04em }

.payment-block{
  border:1px solid var(--a-line);border-radius:var(--a-r);
  padding:12px 14px;margin:10px 0;background:var(--a-surface-2);
}
.payment-block legend{ padding:0 6px;font-size:13px }
.payment-block legend .chk{ display:inline-flex;align-items:center;gap:6px }

.settings-foot{
  display:flex;justify-content:space-between;align-items:center;
