  padding:8px 0;color:var(--a-ink-2);
}
label.chk input[type=checkbox]{ width:16px;height:16px;accent-color:var(--a-brand) }

/* --- modal wide variant --- */
.modal.wide{ max-width:960px;width:calc(100% - 32px) }
.modal .modal-body h4{ margin:14px 0 6px;font-size:13px;color:var(--a-ink-2);text-transform:uppercase;letter-spacing:.04em }

/* --- row-2 grid shared --- */
.row-2{ display:grid;grid-template-columns:1fr 1fr;gap:12px }
@media (max-width:560px){ .row-2{ grid-template-columns:1fr } }

/* --- .badge status refinements --- */
.badge.bad{ background:var(--a-danger-soft);color:var(--a-danger) }
.badge.muted{ background:var(--a-surface-2);color:var(--a-ink-3);border:1px solid var(--a-line) }

