/**
 * Vouchers — CRUD + validate + apply.
 * validate(code, orderTotal) dùng khi checkout để tính discount.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';

const VoucherBody = z.object({
  code: z.string().min(3).max(30).regex(/^[A-Z0-9_-]+$/).transform(s => s.toUpperCase()),
  type: z.enum(['percent', 'amount', 'shipping']),
  value: z.coerce.number().int().nonnegative().default(0),
  minOrder: z.coerce.number().int().nonnegative().default(0),
  startAt: z.coerce.date().nullable().optional(),
  endAt:   z.coerce.date().nullable().optional(),
  usageLimit: z.coerce.number().int().nonnegative().nullable().optional(),
  status: z.enum(['active', 'scheduled', 'paused', 'expired']).default('active'),
  description: z.string().max(500).nullable().optional(),
}).strict();

const VoucherUpdate = VoucherBody.partial().strict();

const ListQuery = z.object({
  q: z.string().max(200).optional(),
  status: z.enum(['active', 'scheduled', 'paused', 'expired']).optional(),
  type: z.enum(['percent', 'amount', 'shipping']).optional(),
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(50),
});

const ValidateBody = z.object({
  code: z.string().min(1).max(30),
  orderTotal: z.coerce.number().int().nonnegative(),
}).strict();

function serialize(v: Prisma.VoucherGetPayload<{}>) {
  return {
    id: v.id,
    code: v.code,
    type: v.type,
    value: Number(v.value),
    min_order: Number(v.minOrder),
    start_at: v.startAt?.toISOString() ?? null,
    end_at: v.endAt?.toISOString() ?? null,
    usage_limit: v.usageLimit,
    used_count: v.usedCount,
    status: v.status,
    description: v.description,
    created_at: v.createdAt.toISOString(),
    updated_at: v.updatedAt.toISOString(),
  };
}

export const voucherRoutes: FastifyPluginAsync = async app => {
  // GET /vouchers
  app.get('/vouchers', { preHandler: [requireAuth, requirePermission('vouchers:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where: Prisma.VoucherWhereInput = {
      ...(q.q && {
        OR: [
          { code: { contains: q.q, mode: 'insensitive' } },
          { description: { contains: q.q, mode: 'insensitive' } },
        ],
      }),
      ...(q.status && { status: q.status }),
      ...(q.type && { type: q.type }),
    };
    const [total, data] = await Promise.all([
      prisma.voucher.count({ where }),
      prisma.voucher.findMany({
        where, orderBy: { createdAt: 'desc' },
        skip: (q.page - 1) * q.limit, take: q.limit,
      }),
    ]);
    return { data: data.map(serialize), total, page: q.page, pageSize: q.limit };
  });

  // GET /vouchers/:id
  app.get<{ Params: { id: string } }>('/vouchers/:id', {
    preHandler: [requireAuth, requirePermission('vouchers:read')],
  }, async (req, reply) => {
    const v = await prisma.voucher.findUnique({ where: { id: req.params.id } });
    if (!v) return reply.code(404).send({ error: 'not_found', requestId: req.id });
    return serialize(v);
  });

  // POST /vouchers
  app.post('/vouchers', { preHandler: [requireAuth, requirePermission('vouchers:write')] }, async (req, reply) => {
    const body = VoucherBody.parse(req.body);

    const v = await prisma.$transaction(async tx => {
      const existing = await tx.voucher.findUnique({ where: { code: body.code } });
      if (existing) { reply.code(409); throw new Error(`Voucher ${body.code} đã tồn tại`); }
      const created = await tx.voucher.create({
        data: {
          code: body.code, type: body.type,
          value: BigInt(body.value),
          minOrder: BigInt(body.minOrder),
          startAt: body.startAt ?? null,
          endAt: body.endAt ?? null,
          usageLimit: body.usageLimit ?? null,
          status: body.status,
          description: body.description ?? null,
        },
      });
      await writeAudit({
        action: 'voucher.create',
