/**
 * Articles (journal) — CRUD, publish, scheduled publish.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { slugify } from '../lib/slug.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';

const ArticleBody = z.object({
  title: z.string().min(1).max(200),
  slug: z.string().max(120).optional(),
  author: z.string().max(80).nullable().optional(),
  category: z.string().max(60).nullable().optional(),
  excerpt: z.string().max(500).nullable().optional(),
  body: z.string().max(100_000).default(''),
  coverUrl: z.string().url().max(500).nullable().optional(),
  tags: z.array(z.string().max(30)).max(20).default([]),
  status: z.enum(['draft', 'scheduled', 'published', 'archived']).default('draft'),
  seoTitle: z.string().max(120).nullable().optional(),
  seoDesc:  z.string().max(200).nullable().optional(),
  publishedAt: z.coerce.date().nullable().optional(),
}).strict();

const ArticleUpdate = ArticleBody.partial().strict();

const ListQuery = z.object({
  q: z.string().max(200).optional(),
  status: z.enum(['draft', 'scheduled', 'published', 'archived']).optional(),
  category: z.string().max(60).optional(),
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

function serialize(a: Prisma.ArticleGetPayload<{}>) {
  return {
    id: a.id,
    slug: a.slug,
    title: a.title,
    author: a.author,
    category: a.category,
    excerpt: a.excerpt,
    body: a.body,
    cover_url: a.coverUrl,
    tags: a.tags,
    status: a.status,
    views: a.views,
    seo_title: a.seoTitle,
    seo_desc: a.seoDesc,
    published_at: a.publishedAt?.toISOString() ?? null,
    created_at: a.createdAt.toISOString(),
    updated_at: a.updatedAt.toISOString(),
  };
}

async function ensureUniqueSlug(base: string, excludeId?: string): Promise<string> {
  let slug = base;
  for (let i = 2; i <= 100; i++) {
    const conflict = await prisma.article.findFirst({
      where: { slug, ...(excludeId ? { NOT: { id: excludeId } } : {}) },
      select: { id: true },
    });
    if (!conflict) return slug;
    slug = `${base}-${i}`;
  }
  throw new Error('Không thể tạo slug duy nhất');
}

export const articleRoutes: FastifyPluginAsync = async app => {
  app.get('/articles', { preHandler: [requireAuth, requirePermission('articles:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where: Prisma.ArticleWhereInput = {
      ...(q.q && {
        OR: [
          { title: { contains: q.q, mode: 'insensitive' } },
          { excerpt: { contains: q.q, mode: 'insensitive' } },
          { author: { contains: q.q, mode: 'insensitive' } },
        ],
      }),
      ...(q.status && { status: q.status }),
      ...(q.category && { category: q.category }),
    };
    const [total, data] = await Promise.all([
      prisma.article.count({ where }),
      prisma.article.findMany({
        where, orderBy: { updatedAt: 'desc' },
        skip: (q.page - 1) * q.limit, take: q.limit,
      }),
    ]);
    return { data: data.map(serialize), total, page: q.page, pageSize: q.limit };
  });

  app.get<{ Params: { id: string } }>('/articles/:id', {
    preHandler: [requireAuth, requirePermission('articles:read')],
  }, async (req, reply) => {
    const a = await prisma.article.findUnique({ where: { id: req.params.id } });
    if (!a) return reply.code(404).send({ error: 'not_found', requestId: req.id });
    return serialize(a);
  });

  app.post('/articles', { preHandler: [requireAuth, requirePermission('articles:write')] }, async (req, reply) => {
    const body = ArticleBody.parse(req.body);
    const slugBase = slugify(body.slug ?? body.title);
    const slug = await ensureUniqueSlug(slugBase);

    const a = await prisma.$transaction(async tx => {
      const created = await tx.article.create({
        data: {
          slug,
          title: body.title,
          author: body.author ?? null,
          category: body.category ?? null,
          excerpt: body.excerpt ?? null,
          body: body.body,
          coverUrl: body.coverUrl ?? null,
          tags: body.tags,
          status: body.status,
          seoTitle: body.seoTitle ?? null,
          seoDesc: body.seoDesc ?? null,
          publishedAt: body.status === 'published' ? (body.publishedAt ?? new Date()) : body.publishedAt ?? null,
        },
      });
      await writeAudit({
        action: 'article.create',
        actorId: req.auth!.userId, actorEmail: req.auth!.email, actorIp: req.ip,
        entity: 'article', entityId: created.id,
        diff: { after: { title: created.title, status: created.status } },
        requestId: req.id,
      }, tx);
      return created;
    });
    reply.code(201);
    return serialize(a);
  });

  app.patch<{ Params: { id: string } }>('/articles/:id', {
    preHandler: [requireAuth, requirePermission('articles:write')],
  }, async (req, reply) => {
    const body = ArticleUpdate.parse(req.body);
    const id = req.params.id;
    const a = await prisma.$transaction(async tx => {
      const existing = await tx.article.findUnique({ where: { id } });
      if (!existing) { reply.code(404); throw new Error('Article not found'); }
      const patch: Prisma.ArticleUpdateInput = {};
      if (body.title !== undefined) patch.title = body.title;
      if (body.slug !== undefined) patch.slug = await ensureUniqueSlug(slugify(body.slug || existing.title), id);
      if (body.author !== undefined) patch.author = body.author;
      if (body.category !== undefined) patch.category = body.category;
      if (body.excerpt !== undefined) patch.excerpt = body.excerpt;
      if (body.body !== undefined) patch.body = body.body;
      if (body.coverUrl !== undefined) patch.coverUrl = body.coverUrl;
      if (body.tags !== undefined) patch.tags = body.tags;
      if (body.status !== undefined) {
        patch.status = body.status;
        if (body.status === 'published' && !existing.publishedAt) patch.publishedAt = new Date();
      }
      if (body.seoTitle !== undefined) patch.seoTitle = body.seoTitle;
      if (body.seoDesc !== undefined) patch.seoDesc = body.seoDesc;
      if (body.publishedAt !== undefined) patch.publishedAt = body.publishedAt;

      const updated = await tx.article.update({ where: { id }, data: patch });
      await writeAudit({
        action: body.status === 'published' ? 'article.publish' : 'article.update',
        actorId: req.auth!.userId, actorEmail: req.auth!.email, actorIp: req.ip,
        entity: 'article', entityId: id,
        diff: { before: { status: existing.status }, after: { status: updated.status } },
        requestId: req.id,
      }, tx);
      return updated;
    });
    return serialize(a);
  });

  app.delete<{ Params: { id: string } }>('/articles/:id', {
    preHandler: [requireAuth, requirePermission('articles:write')],
  }, async (req, reply) => {
    const id = req.params.id;
    await prisma.$transaction(async tx => {
      const a = await tx.article.findUnique({ where: { id } });
      if (!a) { reply.code(404); throw new Error('Article not found'); }
      await tx.article.delete({ where: { id } });
      await writeAudit({
        action: 'article.delete',
        actorId: req.auth!.userId, actorEmail: req.auth!.email, actorIp: req.ip,
        entity: 'article', entityId: id,
        requestId: req.id,
      }, tx);
    });
    reply.code(204);
  });
};

