const SETTING_KEY = 'app';

const SECRET_KEYS = ['secret', 'accessKey', 'apiKey', 'token', 'password'];

function scrub(value: unknown): unknown {
  if (value == null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(scrub);
  const out: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
    if (SECRET_KEYS.includes(k) && typeof v === 'string' && v.length > 0) out[k] = '[REDACTED]';
    else out[k] = scrub(v);
  }
  return out;
}

// Sync-merge patch: nếu patch.key là object, merge recursive; ngược lại overwrite.
function deepMerge<T extends Record<string, any>>(base: T, patch: Partial<T>): T {
  const out: any = { ...base };
  for (const [k, v] of Object.entries(patch)) {
    if (v && typeof v === 'object' && !Array.isArray(v) && out[k] && typeof out[k] === 'object' && !Array.isArray(out[k])) {
      out[k] = deepMerge(out[k], v as any);
    } else {
      out[k] = v;
    }
  }
  return out;
}

