/**
 * Reports — overview KPIs, revenue time-series, top products, cohort.
 * Số liệu lấy từ Orders đã paid/delivered; placedAt làm pivot.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';

const RangeQuery = z.object({
  from: z.coerce.date().optional(),
  to:   z.coerce.date().optional(),
  granularity: z.enum(['day', 'week', 'month']).default('day'),
});

function startOfDay(d: Date): Date {
  const x = new Date(d); x.setHours(0,0,0,0); return x;
}

function bucketKey(d: Date, gran: 'day' | 'week' | 'month'): string {
  if (gran === 'month') return d.toISOString().slice(0, 7);
  if (gran === 'week') {
    const tmp = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
    tmp.setUTCDate(tmp.getUTCDate() - ((tmp.getUTCDay() + 6) % 7)); // ISO Monday
    return tmp.toISOString().slice(0, 10);
  }
  return d.toISOString().slice(0, 10);
}

export const reportRoutes: FastifyPluginAsync = async app => {
  // GET /reports/overview
  app.get('/reports/overview', { preHandler: [requireAuth, requirePermission('reports:read')] }, async () => {
    const now = new Date();
    const d7  = new Date(now.getTime() - 7 * 86400_000);
    const d30 = new Date(now.getTime() - 30 * 86400_000);

    const [orders7, orders30, pending, packing, lowStock, totalCust, vipCust] = await Promise.all([
      prisma.order.aggregate({
        where: { placedAt: { gte: d7 } },
        _sum: { total: true }, _count: { _all: true },
      }),
      prisma.order.aggregate({
        where: { placedAt: { gte: d30 } },
        _sum: { total: true }, _count: { _all: true },
      }),
      prisma.order.count({ where: { status: 'pending' } }),
      prisma.order.count({ where: { status: 'packing' } }),
      prisma.product.count({
        where: { deletedAt: null, variants: { some: { stock: { lte: 5 } } } },
      }),
      prisma.customer.count({ where: { deletedAt: null } }),
      prisma.customer.count({ where: { deletedAt: null, tags: { has: 'VIP' } } }),
    ]);

    const gmv7 = Number(orders7._sum.total ?? 0n);
    const gmv30 = Number(orders30._sum.total ?? 0n);
    const count7 = orders7._count._all;
    const count30 = orders30._count._all;

    return {
      orders_7d: count7,
      orders_30d: count30,
      gmv_7d: gmv7,
      gmv_30d: gmv30,
      aov_7d:  count7 ? Math.round(gmv7 / count7) : 0,
      aov_30d: count30 ? Math.round(gmv30 / count30) : 0,
      pending_orders: pending,
      packing_orders: packing,
      low_stock_skus: lowStock,
      customers_total: totalCust,
      customers_vip: vipCust,
    };
  });

  // GET /reports/revenue?from=&to=&granularity=
  app.get('/reports/revenue', { preHandler: [requireAuth, requirePermission('reports:read')] }, async req => {
    const q = RangeQuery.parse(req.query);
    const to = q.to ?? new Date();
    const from = q.from ?? new Date(to.getTime() - 30 * 86400_000);

    const rows = await prisma.order.findMany({
      where: { placedAt: { gte: startOfDay(from), lte: to }, status: { notIn: ['cancelled'] } },
      select: { placedAt: true, total: true, status: true },
    });

    const buckets = new Map<string, { revenue: number; orders: number }>();
    for (const r of rows) {
      const k = bucketKey(r.placedAt, q.granularity);
      const cur = buckets.get(k) ?? { revenue: 0, orders: 0 };
      cur.revenue += Number(r.total);
      cur.orders += 1;
      buckets.set(k, cur);
    }
    const series = [...buckets.entries()]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([date, v]) => ({ date, revenue: v.revenue, orders: v.orders }));

    return {
      from: from.toISOString(),
      to: to.toISOString(),
      granularity: q.granularity,
      series,
      totals: {
        revenue: series.reduce((s, x) => s + x.revenue, 0),
        orders: series.reduce((s, x) => s + x.orders, 0),
      },
    };
  });

  // GET /reports/top-products?limit=10
  app.get('/reports/top-products', { preHandler: [requireAuth, requirePermission('reports:read')] }, async req => {
    const q = z.object({
      limit: z.coerce.number().int().min(1).max(50).default(10),
      from: z.coerce.date().optional(),
    }).parse(req.query);
    const from = q.from ?? new Date(Date.now() - 30 * 86400_000);

    const agg = await prisma.orderItem.groupBy({
      by: ['productId'],
      where: {
        order: { placedAt: { gte: from }, status: { notIn: ['cancelled'] } },
      },
      _sum: { qty: true, subtotal: true },
      orderBy: { _sum: { subtotal: 'desc' } },
      take: q.limit,
    });

    const ids = agg.map(a => a.productId);
    const products = await prisma.product.findMany({
      where: { id: { in: ids } },
      select: { id: true, code: true, name: true, price: true },
    });
    const byId = new Map(products.map(p => [p.id, p]));

    return {
      data: agg.map(a => ({
        product_id: a.productId,
        code: byId.get(a.productId)?.code ?? null,
        name: byId.get(a.productId)?.name ?? '(deleted)',
        qty: a._sum.qty ?? 0,
        revenue: Number(a._sum.subtotal ?? 0n),
      })),
    };
  });

  // GET /reports/customers/cohort — đơn giản: khách hàng tạo theo tháng, giữ lại mấy người mua tháng sau
  app.get('/reports/customers/cohort', { preHandler: [requireAuth, requirePermission('reports:read')] }, async () => {
    const since = new Date();
    since.setMonth(since.getMonth() - 6);
    const customers = await prisma.customer.findMany({
      where: { deletedAt: null, createdAt: { gte: since } },
      select: { id: true, createdAt: true },
    });
    const orders = await prisma.order.findMany({
      where: { customerId: { in: customers.map(c => c.id) }, status: { notIn: ['cancelled'] } },
      select: { customerId: true, placedAt: true },
    });

    const buckets = new Map<string, { size: number; retained: Record<string, Set<string>> }>();
    for (const c of customers) {
      const k = c.createdAt.toISOString().slice(0, 7);
      const b = buckets.get(k) ?? { size: 0, retained: {} };
      b.size += 1;
      buckets.set(k, b);
    }
    for (const o of orders) {
      if (!o.customerId) continue;
      const c = customers.find(x => x.id === o.customerId);
      if (!c) continue;
      const cohortK = c.createdAt.toISOString().slice(0, 7);
      const orderK  = o.placedAt.toISOString().slice(0, 7);
      const b = buckets.get(cohortK);
      if (!b) continue;
      b.retained[orderK] = (b.retained[orderK] ?? new Set()).add(o.customerId);
    }

    const data = [...buckets.entries()].map(([cohort, b]) => ({
      cohort,
      size: b.size,
      retained: Object.fromEntries(Object.entries(b.retained).map(([k, set]) => [k, set.size])),
    })).sort((a, b) => a.cohort.localeCompare(b.cohort));

    return { data };
  });
};

