/* ═══════════════════════════════════════════════════════════════════
   REPORTS (admin-reports.html)
   ─────────────────────────────────────────────────────────────────── */
.chart-bars{
  display:flex;align-items:flex-end;gap:6px;
  height:180px;padding:12px 6px 6px;overflow-x:auto;
}
.chart-bars .bar-col{
  flex:0 0 24px;display:flex;flex-direction:column;align-items:center;
  gap:4px;height:100%;
}
.chart-bars .bar-col .bar{
  width:100%;min-height:2px;border-radius:4px 4px 0 0;
  background:linear-gradient(180deg,var(--a-brand) 0%,var(--a-brand-soft) 100%);
  transition:filter .15s ease;
}
.chart-bars .bar-col:hover .bar{ filter:brightness(1.1) }
.chart-bars .bar-col small{
  font-size:10px;color:var(--a-ink-3);
  writing-mode:vertical-rl;transform:rotate(180deg);
  white-space:nowrap;
}

.report-grid{
  display:grid;gap:14px;margin-top:14px;
  grid-template-columns:1fr 1fr;
}
@media (max-width:960px){ .report-grid{ grid-template-columns:1fr } }

.status-bars{ display:flex;flex-direction:column;gap:10px;padding:6px 0 }
.sbar{ display:flex;flex-direction:column;gap:4px }
.sbar-label{
  display:flex;justify-content:space-between;align-items:baseline;
  font-size:13px;color:var(--a-ink-2);
}
.sbar-label strong{ color:var(--a-ink);font-weight:600 }
.sbar-track{
  height:8px;border-radius:999px;background:var(--a-surface-2);
  overflow:hidden;
}
.sbar-fill{
  height:100%;border-radius:999px;
  background:var(--a-brand);
  transition:width .3s ease;
}
.sbar-fill.state-pending{   background:#D97706 }
.sbar-fill.state-confirmed{ background:#2563EB }
.sbar-fill.state-packing{   background:#7C3AED }
.sbar-fill.state-shipping{  background:#0891B2 }
.sbar-fill.state-delivered{ background:#0F766E }
.sbar-fill.state-cancelled{ background:#C0392B }
.sbar-fill.state-returned{  background:#78716C }

/* ═══════════════════════════════════════════════════════════════════
   REVIEWS (admin-reviews.html)
   ─────────────────────────────────────────────────────────────────── */
.review-list{
  display:grid;gap:12px;margin-top:12px;
  grid-template-columns:repeat(auto-fill,minmax(320px,1fr));
}
.review-card{
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:12px;padding:14px 16px;
  display:flex;flex-direction:column;gap:8px;
  box-shadow:var(--a-shadow-sm);
}
.review-card header{
  display:flex;justify-content:space-between;align-items:flex-start;gap:10px;
}
.review-card .user-cell{ display:flex;gap:10px;align-items:center }
.review-card .avatar-sm{
  width:36px;height:36px;border-radius:50%;flex:0 0 36px;
  background:var(--a-brand-soft);color:var(--a-brand-ink);
  display:grid;place-items:center;font-weight:600;font-size:12px;
}
.review-card h4{ margin:2px 0 0;font-size:14px;font-weight:600;color:var(--a-ink) }
.review-card p{ margin:0;font-size:13px;color:var(--a-ink-2);line-height:1.5 }
.review-card footer{
  display:flex;gap:6px;align-items:center;flex-wrap:wrap;
  margin-top:4px;padding-top:8px;border-top:1px dashed var(--a-line);
}
.rv-stars{ color:#F59E0B;font-size:14px;letter-spacing:1px }
.rv-stars .fa-regular{ color:var(--a-ink-4) }

/* ═══════════════════════════════════════════════════════════════════
   RETURNS (admin-returns.html)
   ─────────────────────────────────────────────────────────────────── */
.ret-tbl td.actions{ display:flex;gap:4px;flex-wrap:wrap;align-items:center }
.ret-tbl code{
  font-family:'JetBrains Mono',monospace;font-size:12px;
  background:var(--a-surface-2);padding:2px 6px;border-radius:4px;
  color:var(--a-ink-2);
}
.badge.accent{ background:var(--a-brand-soft);color:var(--a-brand-ink) }
.badge.info{   background:#E0F2FE;color:#075985 }

/* Modal generic (dùng cho returns + collections) */
.adm-modal{
  position:fixed;inset:0;z-index:100;
  background:rgba(15,23,42,.45);backdrop-filter:blur(2px);
  display:grid;place-items:center;padding:20px;
}
.adm-modal[hidden]{ display:none }
.adm-modal-card{
  background:var(--a-surface);border-radius:14px;
  width:min(520px,100%);max-height:90vh;overflow:hidden;
  display:flex;flex-direction:column;
  box-shadow:0 20px 60px rgba(15,23,42,.25);
}
.adm-modal-card.adm-modal-lg{ width:min(860px,100%) }
.adm-modal-card > header{
  display:flex;justify-content:space-between;align-items:center;
  padding:14px 18px;border-bottom:1px solid var(--a-line);
}
.adm-modal-card > header h3{ margin:0;font-size:15px;font-weight:600 }
.adm-modal-body{ padding:16px 18px;overflow:auto;flex:1 }

.kv{
  display:grid;grid-template-columns:120px 1fr;gap:8px 14px;
  margin:0 0 14px;font-size:13px;
}
.kv dt{ color:var(--a-ink-3);font-weight:500 }
.kv dd{ margin:0;color:var(--a-ink) }
.modal-actions{
