1	/**
2	 * Server bootstrap — Fastify 5 + plugins + routes.
3	 *
4	 * Khởi động:  pnpm --filter api dev
5	 * Production: pnpm --filter api build && pnpm --filter api start
6	 */
7	
8	import 'dotenv/config';
9	import Fastify from 'fastify';
10	import cookie from '@fastify/cookie';
11	import cors from '@fastify/cors';
12	import helmet from '@fastify/helmet';
13	import rateLimit from '@fastify/rate-limit';
14	import sensible from '@fastify/sensible';
15	import { config } from './config.js';
16	import { redis } from './lib/redis.js';
17	import { registerAuthHooks } from './middleware/auth.js';
18	import { registerCsrf } from './middleware/csrf.js';
19	import { registerErrorHandler } from './plugins/error-handler.js';
20	import { healthRoutes } from './routes/health.js';
21	import { authRoutes } from './routes/auth.js';
22	import { productRoutes } from './routes/products.js';
23	import { mediaRoutes } from './routes/media.js';
24	import { auditRoutes } from './routes/audit.js';
25	import { userRoutes } from './routes/users.js';
26	import { orderRoutes } from './routes/orders.js';
27	import { customerRoutes } from './routes/customers.js';
28	import { voucherRoutes } from './routes/vouchers.js';
29	import { articleRoutes } from './routes/articles.js';
30	import { inventoryRoutes } from './routes/inventory.js';
31	import { settingsRoutes } from './routes/settings.js';
32	import { reportRoutes } from './routes/reports.js';
33	
34	export async function build() {
35	  const app = Fastify({
36	    logger: {
37	      level: config.LOG_LEVEL,
38	      redact: {
39	        paths: [
40	          'req.headers.authorization',
41	          'req.headers.cookie',
42	          '*.password',
43	          '*.passwordHash',
44	          '*.totp',
45	          '*.totpSecret',
46	          '*.secret',
47	        ],
48	        censor: '[REDACTED]',
49	      },
50	      ...(config.isDev && {
51	        transport: { target: 'pino-pretty', options: { colorize: true, singleLine: true } },
52	      }),
53	    },
54	    trustProxy: config.isProd,
55	    genReqId: () => crypto.randomUUID(),
56	    bodyLimit: 2 * 1024 * 1024,      // 2MB JSON body
57	    connectionTimeout: 30_000,
58	    keepAliveTimeout: 65_000,
59	    // BigInt serialize — prisma trả bigint cho VND
60	    ajv: { customOptions: { removeAdditional: false } },
61	  });
62	
63	  // BigInt → string trong JSON (FE parse về number an toàn vì < 2^53)
64	  app.addHook('onSend', async (_req, reply, payload) => {
65	    if (typeof payload === 'string') return payload;
66	    return payload;
67	  });
68	
69	  // ─ Security plugins ─
70	  await app.register(helmet, {
71	    contentSecurityPolicy: false,  // API-only, CSP set trên FE
72	    crossOriginResourcePolicy: { policy: 'same-site' },
73	  });
74	
75	  await app.register(cors, {
76	    origin: (origin, cb) => {
77	      if (!origin) return cb(null, true); // curl, server-to-server
78	      if (config.corsOrigins.includes(origin)) return cb(null, true);
79	      return cb(new Error('CORS denied'), false);
80	    },
