/**
 * Server bootstrap — Fastify 5 + plugins + routes.
 *
 * Khởi động:  pnpm --filter api dev
 * Production: pnpm --filter api build && pnpm --filter api start
 */

import 'dotenv/config';
import Fastify from 'fastify';
import cookie from '@fastify/cookie';
import cors from '@fastify/cors';
import helmet from '@fastify/helmet';
import rateLimit from '@fastify/rate-limit';
import sensible from '@fastify/sensible';
import { config } from './config.js';
import { redis } from './lib/redis.js';
import { registerAuthHooks } from './middleware/auth.js';
import { registerCsrf } from './middleware/csrf.js';
import { registerErrorHandler } from './plugins/error-handler.js';
import { healthRoutes } from './routes/health.js';
import { authRoutes } from './routes/auth.js';
import { productRoutes } from './routes/products.js';
import { mediaRoutes } from './routes/media.js';
import { auditRoutes } from './routes/audit.js';
import { userRoutes } from './routes/users.js';
import { orderRoutes } from './routes/orders.js';
import { customerRoutes } from './routes/customers.js';
import { voucherRoutes } from './routes/vouchers.js';
import { articleRoutes } from './routes/articles.js';
import { inventoryRoutes } from './routes/inventory.js';
import { settingsRoutes } from './routes/settings.js';
import { reportRoutes } from './routes/reports.js';

export async function build() {
  const app = Fastify({
    logger: {
      level: config.LOG_LEVEL,
      redact: {
        paths: [
          'req.headers.authorization',
          'req.headers.cookie',
          '*.password',
          '*.passwordHash',
          '*.totp',
          '*.totpSecret',
          '*.secret',
        ],
        censor: '[REDACTED]',
      },
      ...(config.isDev && {
        transport: { target: 'pino-pretty', options: { colorize: true, singleLine: true } },
      }),
    },
    trustProxy: config.isProd,
    genReqId: () => crypto.randomUUID(),
    bodyLimit: 2 * 1024 * 1024,      // 2MB JSON body
    connectionTimeout: 30_000,
    keepAliveTimeout: 65_000,
    // BigInt serialize — prisma trả bigint cho VND
    ajv: { customOptions: { removeAdditional: false } },
  });

  // BigInt → string trong JSON (FE parse về number an toàn vì < 2^53)
  app.addHook('onSend', async (_req, reply, payload) => {
    if (typeof payload === 'string') return payload;
    return payload;
  });

  // ─ Security plugins ─
  await app.register(helmet, {
    contentSecurityPolicy: false,  // API-only, CSP set trên FE
    crossOriginResourcePolicy: { policy: 'same-site' },
  });

  await app.register(cors, {
    origin: (origin, cb) => {
      if (!origin) return cb(null, true); // curl, server-to-server
      if (config.corsOrigins.includes(origin)) return cb(null, true);
      return cb(new Error('CORS denied'), false);
    },
    credentials: true,
    methods: ['GET', 'POST', 'PATCH', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'X-CSRF-Token', 'X-Request-Id'],
    exposedHeaders: ['X-Request-Id'],
    maxAge: 600,
  });

  await app.register(cookie, {
    secret: config.SESSION_SECRET,
    parseOptions: {},
  });

  await app.register(rateLimit, {
    global: true,
    max: config.RATE_LIMIT_MAX,
    timeWindow: config.RATE_LIMIT_WINDOW_MS,
    redis,
    keyGenerator: req => req.ip,
    allowList: (req) => req.url === '/v1/health',
    addHeadersOnExceeding: { 'x-ratelimit-limit': true, 'x-ratelimit-remaining': true },
    errorResponseBuilder: (req, ctx) => ({
      error: 'rate_limited',
      message: `Quá nhanh. Thử lại sau ${Math.ceil(ctx.ttl / 1000)} giây`,
      requestId: req.id,
    }),
  });

  await app.register(sensible);

  // ─ Custom hooks ─
  registerErrorHandler(app);
  registerCsrf(app);
  registerAuthHooks(app);

  // ─ Versioned API ─
  await app.register(async v1 => {
    await v1.register(healthRoutes);
    await v1.register(authRoutes);
    await v1.register(productRoutes);
    await v1.register(mediaRoutes);
    await v1.register(auditRoutes);
    await v1.register(userRoutes);
    await v1.register(orderRoutes);
    await v1.register(customerRoutes);
    await v1.register(voucherRoutes);
    await v1.register(articleRoutes);
    await v1.register(inventoryRoutes);
    await v1.register(settingsRoutes);
    await v1.register(reportRoutes);
  }, { prefix: '/v1' });

  return app;
}

async function main() {
  const app = await build();
  try {
    await app.listen({ port: config.PORT, host: config.HOST });
    app.log.info(
      { env: config.NODE_ENV, version: process.env.npm_package_version },
      `🚀 API ready at http://${config.HOST}:${config.PORT}`,
    );
  } catch (err) {
    app.log.fatal({ err }, 'Failed to start');
    process.exit(1);
  }

  // Graceful shutdown
  const shutdown = async (signal: string) => {
    app.log.info(`Received ${signal}, shutting down...`);
    await app.close();
    await redis.quit().catch(() => undefined);
    process.exit(0);
  };
  process.on('SIGTERM', () => void shutdown('SIGTERM'));
  process.on('SIGINT', () => void shutdown('SIGINT'));
}

// JSON bigint support — Postgres bigint đến từ Prisma
// eslint-disable-next-line @typescript-eslint/no-explicit-any
(BigInt.prototype as any).toJSON = function () { return this.toString(); };

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

