/**
 * Audit logger — ghi mọi mutation vào bảng audit_logs.
 *
 * Invariant:
 *  - Append-only (DB grant đã REVOKE UPDATE/DELETE cho role app)
 *  - Hash chain để detect tampering (prevHash = hash của record trước)
 *  - Không bao giờ ghi PII thô (password, totp) — sẽ scrub ở diff
 */

import { createHash } from 'node:crypto';
import type { Prisma } from '@prisma/client';
import { prisma } from './prisma.js';

type AuditInput = {
  action: string;         // "product.update", "auth.login.success", ...
  actorId?: string | null;
  actorEmail?: string | null;
  actorIp?: string | null;
  userAgent?: string | null;
  entity?: string | null;
  entityId?: string | null;
  diff?: { before?: unknown; after?: unknown } | null;
  requestId?: string | null;
};

const SENSITIVE_KEYS = new Set([
  'password', 'passwordHash', 'password_hash',
  'totp', 'totpSecret', 'totp_secret', 'totpSecretEnc', 'totp_secret_enc',
  'secret', 'token', 'cookie', 'authorization',
]);

function scrub(value: unknown): unknown {
  if (value === null || value === undefined) return value;
  if (Array.isArray(value)) return value.map(scrub);
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = SENSITIVE_KEYS.has(k) ? '[REDACTED]' : scrub(v);
    }
    return out;
  }
  return value;
}

function computeHash(row: Record<string, unknown>, prev: string | null): string {
  const h = createHash('sha256');
  h.update(prev ?? '');
  h.update(JSON.stringify(row));
  return h.digest('hex');
}

export async function writeAudit(input: AuditInput, tx: Prisma.TransactionClient = prisma) {
  const cleanDiff = input.diff ? scrub(input.diff) as Prisma.InputJsonValue : undefined;

  // Lấy hash gần nhất để chain. Không cần lock — nếu race thì hash sẽ dựa trên state thực.
  const prev = await tx.auditLog.findFirst({
    orderBy: { id: 'desc' },
    select: { hash: true },
  });

  const payload = {
    action: input.action,
    actorId: input.actorId ?? null,
    actorEmail: input.actorEmail ?? null,
    actorIp: input.actorIp ?? null,
    userAgent: input.userAgent ?? null,
    entity: input.entity ?? null,
    entityId: input.entityId ?? null,
    diff: cleanDiff ?? null,
    requestId: input.requestId ?? null,
    prevHash: prev?.hash ?? null,
  };

  const hash = computeHash(payload as Record<string, unknown>, prev?.hash ?? null);

  await tx.auditLog.create({
    data: { ...payload, hash } as Prisma.AuditLogUncheckedCreateInput,
  });
}

