import { prisma } from './prisma.js';

/**
 * Resolve permissions của user. Union qua tất cả roles user có.
 * Cache Redis vài phút ở production (TODO).
 */
export async function permissionsForUser(userId: string): Promise<Set<string>> {
  const rows = await prisma.userRole.findMany({
    where: { userId },
    select: {
      role: {
        select: {
          permissions: { select: { permission: { select: { key: true } } } },
        },
      },
    },
  });
  const set = new Set<string>();
  for (const ur of rows) {
    for (const rp of ur.role.permissions) set.add(rp.permission.key);
  }
  return set;
}

