/**
 * Runtime config — validate env với Zod. Fail-fast nếu thiếu/sai format.
 */

import { z } from 'zod';

const EnvSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'staging', 'production']).default('development'),
  PORT: z.coerce.number().int().positive().default(3000),
  HOST: z.string().default('0.0.0.0'),
  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace']).default('info'),

  DATABASE_URL: z.string().url(),
  REDIS_URL: z.string().url(),

  MEILI_HOST: z.string().url().optional(),
  MEILI_MASTER_KEY: z.string().optional(),

  R2_ACCOUNT_ID: z.string().optional(),
  R2_ACCESS_KEY_ID: z.string().optional(),
  R2_SECRET_ACCESS_KEY: z.string().optional(),
  R2_BUCKET: z.string().default('detoxblanc-media'),
  R2_PUBLIC_BASE: z.string().url().optional(),

  SESSION_SECRET: z.string().min(32, 'SESSION_SECRET phải ≥ 32 ký tự'),
  TOTP_ENC_KEY: z.string().min(32, 'TOTP_ENC_KEY phải ≥ 32 ký tự'),
  SESSION_TTL_HOURS: z.coerce.number().positive().default(8),
  CORS_ORIGINS: z.string().default('http://localhost:5173'),

  RATE_LIMIT_WINDOW_MS: z.coerce.number().int().positive().default(10_000),
  RATE_LIMIT_MAX: z.coerce.number().int().positive().default(100),
  AUTH_RATE_LIMIT_MAX: z.coerce.number().int().positive().default(20),

  SENTRY_DSN: z.string().optional().default(''),

  EMAIL_PROVIDER: z.string().default('resend'),
  EMAIL_API_KEY: z.string().optional().default(''),
  EMAIL_FROM: z.string().default('Detoxblanc <noreply@detoxblanc.com>'),

  FEATURE_PAYMENT_VNPAY: z.enum(['on', 'off']).default('off'),
  FEATURE_PAYMENT_MOMO: z.enum(['on', 'off']).default('off'),
  FEATURE_SHIPPING_GHN: z.enum(['on', 'off']).default('off'),
});

export type AppConfig = z.infer<typeof EnvSchema> & {
  isProd: boolean;
  isDev: boolean;
  isTest: boolean;
  corsOrigins: string[];
};

function build(): AppConfig {
  const parsed = EnvSchema.safeParse(process.env);
  if (!parsed.success) {
    console.error('❌ Invalid environment variables:');
    for (const issue of parsed.error.issues) {
      console.error(`   · ${issue.path.join('.')}: ${issue.message}`);
    }
    process.exit(1);
  }
  const env = parsed.data;
  return {
    ...env,
    isProd: env.NODE_ENV === 'production',
    isDev: env.NODE_ENV === 'development',
    isTest: env.NODE_ENV === 'test',
    corsOrigins: env.CORS_ORIGINS.split(',').map(s => s.trim()).filter(Boolean),
  };
}

export const config: AppConfig = build();

