/**
 * Payment provider contract.
 *
 * Một "intent" = ý định thanh toán cho 1 order. Provider chịu trách nhiệm:
 *  - createIntent(): tạo session bên phía cổng + trả redirectUrl
 *  - verifyReturn(): xác thực chữ ký query string (khi khách redirect về)
 *  - verifyWebhook(): xác thực IPN / webhook (server-to-server)
 *  - parseOutcome(): trả về kết quả chuẩn hoá { status, providerTxnId, raw }
 *  - refund() (optional): hoàn tiền
 *
 * Invariant:
 *  - KHÔNG tự mutate DB trong provider. Chỉ parse + verify signature.
 *  - KHÔNG log rawResponse chứa secret key. Scrub trong service layer.
 */

import type { PaymentIntentStatus, PaymentProvider } from '@prisma/client';

export type PaymentAmount = number | bigint;

export interface CreateIntentInput {
  /** Payment.id — dùng làm orderInfo ref bên phía cổng */
  paymentId: string;
  /** Order.code — hiển thị cho user */
  orderCode: string;
  /** VNĐ, integer */
  amount: PaymentAmount;
  currency?: string;        // default 'VND'
  customerName?: string;
  customerEmail?: string | null;
  customerPhone?: string | null;
  /** URL FE redirect về sau khi thanh toán (per-request override) */
  returnUrl?: string;
  /** IPN URL server-to-server (provider cần biết để callback) */
  ipnUrl?: string;
  /** Locale cho trang thanh toán */
  locale?: 'vi' | 'en';
  /** Request meta để debug */
  clientIp?: string;
}

export interface CreateIntentResult {
  /** URL redirect cho browser (vnpay/momo), hoặc null cho manual */
  redirectUrl: string | null;
  /** Mã giao dịch phía cổng nếu có (momo sync response) */
  providerTxnId?: string | null;
  /** Trạng thái sau khi createIntent */
  status: PaymentIntentStatus;
  /** Full response để lưu vào payments.raw_response */
  raw: Record<string, unknown>;
}

export interface VerifyInput {
  /** Raw query (vnpay) hoặc parsed JSON body (momo) */
