    return {
      signatureValid: false,
      status: 'pending',
      raw: { error: 'manual provider has no return flow' },
    };
  },

  async verifyWebhook() {
    return {
      signatureValid: false,
      status: 'pending',
      raw: { error: 'manual provider has no webhook' },
    };
  },
};

