/**
 * VNPay adapter — chuẩn VNPay v2.1.0 (sandbox + production).
 *
 * Flow:
 *   1. createIntent → sinh URL vpcpay.html?<query>&vnp_SecureHash=<hmac>
 *   2. Khách paid → redirect về vnp_ReturnUrl kèm query → verifyReturn()
 *   3. Song song VNPay gọi IPN URL (server-to-server) → verifyWebhook()
 *
 * Ký: HMAC-SHA512 trên query đã sort alphabet + rawUrl-encode.
 *
 * Docs: https://sandbox.vnpayment.vn/apis/docs/huong-dan-tich-hop/
 *
 * Note: Triển khai này đủ dùng với sandbox. Trong production cần:
 *  - Logic retry khi VNPay timeout
 *  - IP allowlist cho IPN
 *  - Đối soát cuối ngày (qry API)
 */

import { createHmac } from 'node:crypto';
import { config } from '../config.js';
import type {
  PaymentProviderAdapter,
  CreateIntentInput,
  CreateIntentResult,
  VerifyInput,
  VerifyOutcome,
} from './types.js';

// Map mã response code → trạng thái chuẩn hoá
const RESP_MAP: Record<string, 'succeeded' | 'failed' | 'cancelled'> = {
  '00': 'succeeded',
  '24': 'cancelled',  // Khách huỷ
};
function mapRespCode(code?: string | null) {
  if (!code) return 'failed' as const;
  return RESP_MAP[code] ?? 'failed';
}

/** Ký hmac-sha512 theo spec VNPay */
function signParams(params: Record<string, string | number>, secret: string): string {
  const sorted = Object.keys(params)
    .filter(k => params[k] !== '' && params[k] !== undefined && params[k] !== null && k !== 'vnp_SecureHash' && k !== 'vnp_SecureHashType')
    .sort()
    .map(k => `${k}=${encodeURIComponent(String(params[k])).replace(/%20/g, '+')}`)
    .join('&');
  return createHmac('sha512', secret).update(sorted, 'utf8').digest('hex');
}

function buildPayUrl(params: Record<string, string | number>, secret: string, base: string): string {
  const hash = signParams(params, secret);
  const sorted = Object.keys(params)
    .filter(k => params[k] !== '' && params[k] !== undefined && params[k] !== null)
    .sort()
    .map(k => `${k}=${encodeURIComponent(String(params[k])).replace(/%20/g, '+')}`)
    .join('&');
  return `${base}?${sorted}&vnp_SecureHash=${hash}`;
}

function fmtDate(d: Date): string {
  // VNPay yyyyMMddHHmmss (giờ VN)
  const pad = (n: number) => String(n).padStart(2, '0');
  return (
    d.getFullYear().toString() +
    pad(d.getMonth() + 1) + pad(d.getDate()) +
    pad(d.getHours()) + pad(d.getMinutes()) + pad(d.getSeconds())
  );
}

export const vnpayProvider: PaymentProviderAdapter = {
  key: 'vnpay',

  isAvailable() {
    return (
      config.FEATURE_PAYMENT_VNPAY === 'on' &&
      !!config.VNPAY_TMN_CODE &&
      !!config.VNPAY_HASH_SECRET
    );
  },

  async createIntent(input: CreateIntentInput): Promise<CreateIntentResult> {
    if (!this.isAvailable()) {
      throw new Error('VNPay chưa được cấu hình (VNPAY_TMN_CODE / VNPAY_HASH_SECRET).');
    }
    const now = new Date();
    const expire = new Date(now.getTime() + 15 * 60_000); // 15 phút
    const params: Record<string, string | number> = {
      vnp_Version: '2.1.0',
      vnp_Command: 'pay',
      vnp_TmnCode: config.VNPAY_TMN_CODE,
      vnp_Amount: Number(input.amount) * 100, // VNPay tính theo đơn vị * 100
      vnp_CurrCode: input.currency || 'VND',
      vnp_TxnRef: input.paymentId, // đây là ID để match về
      vnp_OrderInfo: `Thanh toan don ${input.orderCode}`,
      vnp_OrderType: 'other',
      vnp_Locale: input.locale || 'vn',
      vnp_ReturnUrl: input.returnUrl || config.VNPAY_RETURN_URL || '',
      vnp_IpAddr: input.clientIp || '127.0.0.1',
      vnp_CreateDate: fmtDate(now),
      vnp_ExpireDate: fmtDate(expire),
    };
    if (input.ipnUrl) params.vnp_IpnUrl = input.ipnUrl;

    const redirectUrl = buildPayUrl(params, config.VNPAY_HASH_SECRET, config.VNPAY_PAY_URL);
    return {
      redirectUrl,
      providerTxnId: null,
      status: 'pending',
      raw: { request: params },
    };
  },

  async verifyReturn(input: VerifyInput): Promise<VerifyOutcome> {
    return verifyHash(input);
  },

  async verifyWebhook(input: VerifyInput): Promise<VerifyOutcome> {
    return verifyHash(input);
  },
};

function verifyHash(input: VerifyInput): VerifyOutcome {
  const payload = { ...input.payload } as Record<string, string | undefined>;
  const received = payload.vnp_SecureHash;
  const paymentId = payload.vnp_TxnRef || null;
  const respCode = payload.vnp_ResponseCode;
  const amountRaw = payload.vnp_Amount;
  const amount = amountRaw ? Number(amountRaw) / 100 : null;
  const providerTxnId = payload.vnp_TransactionNo || null;

  delete payload.vnp_SecureHash;
  delete payload.vnp_SecureHashType;

  const expected = signParams(payload as Record<string, string>, config.VNPAY_HASH_SECRET);
  const signatureValid = !!received && expected === received;

  const status = mapRespCode(respCode);
  return {
    signatureValid,
    status,
    providerTxnId,
    paymentId,
    amount,
    errorCode: respCode ?? null,
    errorMessage: status === 'succeeded' ? null : `VNPay responseCode=${respCode}`,
    raw: { ...input.payload },
  };
}

