/**
 * MoMo adapter — MoMo Payment Gateway v2.
 *
 * Flow:
 *   1. createIntent → POST tới MOMO_ENDPOINT, nhận payUrl → redirect khách
 *   2. Khách redirect về returnUrl → verifyReturn()
 *   3. Server-to-server IPN → verifyWebhook()
 *
 * Ký: HMAC-SHA256 trên rawSignature có thứ tự field cố định theo docs.
 *
 * Docs: https://developers.momo.vn/v3/docs/payment/api/payment-method/onetime/
 */

import { createHmac } from 'node:crypto';
import { config } from '../config.js';
import type {
  PaymentProviderAdapter,
  CreateIntentInput,
  CreateIntentResult,
  VerifyInput,
  VerifyOutcome,
} from './types.js';

function hmacSha256(secret: string, data: string): string {
  return createHmac('sha256', secret).update(data, 'utf8').digest('hex');
}

// MoMo resultCode: 0 = success; 9000 = pending; 1000 = pending user auth
function mapResultCode(code: number | string | undefined) {
  const n = Number(code);
  if (n === 0) return 'succeeded' as const;
  if (n === 9000 || n === 1000) return 'pending' as const;
  if (n === 1006) return 'cancelled' as const; // khách từ chối
  return 'failed' as const;
}

export const momoProvider: PaymentProviderAdapter = {
  key: 'momo',

  isAvailable() {
    return (
      config.FEATURE_PAYMENT_MOMO === 'on' &&
      !!config.MOMO_PARTNER_CODE &&
      !!config.MOMO_ACCESS_KEY &&
      !!config.MOMO_SECRET_KEY
    );
  },

  async createIntent(input: CreateIntentInput): Promise<CreateIntentResult> {
    if (!this.isAvailable()) {
      throw new Error('MoMo chưa được cấu hình (MOMO_*).');
    }
    const requestId = `${input.paymentId}-${Date.now()}`;
    const orderId = input.paymentId;
    const redirectUrl = input.returnUrl || config.MOMO_RETURN_URL || '';
    const ipnUrl = input.ipnUrl || '';
    const orderInfo = `Thanh toan ${input.orderCode}`;
    const amount = String(Number(input.amount));
    const requestType = 'captureWallet';
    const extraData = '';

    const rawSig =
      `accessKey=${config.MOMO_ACCESS_KEY}` +
      `&amount=${amount}` +
      `&extraData=${extraData}` +
      `&ipnUrl=${ipnUrl}` +
      `&orderId=${orderId}` +
      `&orderInfo=${orderInfo}` +
      `&partnerCode=${config.MOMO_PARTNER_CODE}` +
      `&redirectUrl=${redirectUrl}` +
      `&requestId=${requestId}` +
      `&requestType=${requestType}`;
    const signature = hmacSha256(config.MOMO_SECRET_KEY, rawSig);

    const body = {
      partnerCode: config.MOMO_PARTNER_CODE,
      accessKey:   config.MOMO_ACCESS_KEY,
      requestId, orderId, orderInfo, amount,
      redirectUrl, ipnUrl, extraData, requestType, signature,
      lang: input.locale === 'en' ? 'en' : 'vi',
    };

    // Thực hiện POST — dùng fetch (Node 22). Nếu MoMo timeout thì throw.
    const ac = AbortSignal.timeout(15_000);
    let respJson: Record<string, unknown> = {};
    let httpStatus = 0;
    try {
      const res = await fetch(config.MOMO_ENDPOINT, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(body),
        signal: ac,
      });
      httpStatus = res.status;
      respJson = (await res.json().catch(() => ({}))) as Record<string, unknown>;
    } catch (err) {
      return {
        redirectUrl: null, providerTxnId: null, status: 'failed',
        raw: { request: body, error: (err as Error).message },
      };
    }

    const resultCode = respJson.resultCode as number | undefined;
    const payUrl = respJson.payUrl as string | undefined;
    const status = mapResultCode(resultCode);

    return {
      redirectUrl: payUrl || null,
      providerTxnId: (respJson.transId as string) || null,
      status,
      raw: { request: body, httpStatus, response: respJson },
    };
  },

  async verifyReturn(input: VerifyInput): Promise<VerifyOutcome> {
    return verifySig(input.payload as Record<string, string>);
  },

  async verifyWebhook(input: VerifyInput): Promise<VerifyOutcome> {
    return verifySig(input.payload as Record<string, unknown>);
  },
};

function verifySig(payload: Record<string, unknown>): VerifyOutcome {
  const received = String(payload.signature || '');
  const resultCode = payload.resultCode as number | string | undefined;
  const amount = payload.amount ? Number(payload.amount) : null;
  const orderId = String(payload.orderId || '') || null;
  const providerTxnId = String(payload.transId || '') || null;

  const rawSig =
    `accessKey=${config.MOMO_ACCESS_KEY}` +
    `&amount=${payload.amount ?? ''}` +
    `&extraData=${payload.extraData ?? ''}` +
    `&message=${payload.message ?? ''}` +
    `&orderId=${payload.orderId ?? ''}` +
    `&orderInfo=${payload.orderInfo ?? ''}` +
    `&orderType=${payload.orderType ?? ''}` +
    `&partnerCode=${payload.partnerCode ?? ''}` +
    `&payType=${payload.payType ?? ''}` +
    `&requestId=${payload.requestId ?? ''}` +
    `&responseTime=${payload.responseTime ?? ''}` +
    `&resultCode=${payload.resultCode ?? ''}` +
    `&transId=${payload.transId ?? ''}`;

  const expected = hmacSha256(config.MOMO_SECRET_KEY, rawSig);
  const signatureValid = !!received && expected === received;
  const status = mapResultCode(resultCode);

  return {
    signatureValid,
    status,
    paymentId: orderId,
    providerTxnId,
    amount,
    errorCode: resultCode != null ? String(resultCode) : null,
    errorMessage: (payload.message as string) || null,
    raw: payload,
  };
}

