/**
 * Registry map PaymentMethod (order-level) → PaymentProvider adapter.
 *
 * PaymentMethod được chọn bởi customer ở FE; provider là implementation.
 * Với COD và bank_transfer → dùng manualProvider.
 */

import type { PaymentMethod, PaymentProvider } from '@prisma/client';
import type { PaymentProviderAdapter } from './types.js';
import { manualProvider } from './manual.js';
import { vnpayProvider } from './vnpay.js';
import { momoProvider } from './momo.js';

const ADAPTERS: Record<PaymentProvider, PaymentProviderAdapter> = {
  manual: manualProvider,
  vnpay:  vnpayProvider,
  momo:   momoProvider,
  stripe: manualProvider, // TODO: stripe chưa implement — placeholder
};

/** Order.paymentMethod → Provider */
export const METHOD_TO_PROVIDER: Record<PaymentMethod, PaymentProvider> = {
  cod:           'manual',
  bank_transfer: 'manual',
  vnpay:         'vnpay',
  momo:          'momo',
};

export function getProvider(provider: PaymentProvider): PaymentProviderAdapter {
  const adapter = ADAPTERS[provider];
  if (!adapter) throw new Error(`Unknown payment provider: ${provider}`);
  return adapter;
}

export function getProviderForMethod(method: PaymentMethod): PaymentProviderAdapter {
  return getProvider(METHOD_TO_PROVIDER[method]);
}

export function availableProviders(): PaymentProvider[] {
  return (Object.keys(ADAPTERS) as PaymentProvider[]).filter(k => ADAPTERS[k].isAvailable());
}

