/**
 * Payment service layer — orchestrator giữa provider adapter và DB.
 *
 * Invariants:
 *  - Tất cả mutation Payment + Order + OrderEvent + AuditLog chạy trong 1 $transaction
 *  - Không bao giờ ghi raw request/response chứa secret key (provider không đưa vào raw)
 *  - Idempotent: verifyAndApply gọi 2 lần trên cùng payment "succeeded" không đổi state
 */

import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { enqueueEmail } from '../email/index.js';
import { getProviderForMethod, getProvider, METHOD_TO_PROVIDER } from './registry.js';
import type { VerifyInput, VerifyOutcome } from './types.js';
import type { PaymentIntentStatus, PaymentProvider } from '@prisma/client';

interface CreatePaymentInput {
  orderId: string;
  /** Override provider (nếu không set lấy theo Order.paymentMethod) */
  provider?: PaymentProvider;
  returnUrl?: string;
  ipnUrl?: string;
  clientIp?: string;
  idempotencyKey?: string;
  actor?: { id: string | null; email: string | null; ip: string | null; ua: string | null };
  requestId?: string;
}

export async function createPaymentIntent(input: CreatePaymentInput) {
  // Load order
  const order = await prisma.order.findUnique({
    where: { id: input.orderId },
    include: { customer: true },
  });
  if (!order) throw new Error('Order not found');
  if (order.paymentStatus === 'paid') throw new Error('Order đã thanh toán');

  // Idempotency check: nếu client gửi cùng key → trả lại payment cũ
  if (input.idempotencyKey) {
    const existing = await prisma.payment.findUnique({ where: { idempotencyKey: input.idempotencyKey } });
    if (existing) {
      return { payment: existing, redirectUrl: existing.redirectUrl ?? null, reused: true };
    }
  }

  const providerKey = input.provider ?? METHOD_TO_PROVIDER[order.paymentMethod];
  const adapter = getProvider(providerKey);

  // Tạo bản ghi Payment trước (status=created), sau đó gọi adapter
  const payment = await prisma.payment.create({
    data: {
      orderId: order.id,
      provider: providerKey,
      amount: order.total,
      currency: 'VND',
      status: 'created',
      returnUrl: input.returnUrl ?? null,
      idempotencyKey: input.idempotencyKey ?? null,
    },
  });

  // Gọi provider
  let result;
  try {
    result = await adapter.createIntent({
      paymentId: payment.id,
      orderCode: order.code,
      amount: Number(order.total),
      currency: 'VND',
      customerName: order.customer?.name ?? undefined,
      customerEmail: order.customer?.email ?? undefined,
      customerPhone: order.customer?.phone ?? undefined,
      returnUrl: input.returnUrl,
      ipnUrl: input.ipnUrl,
      clientIp: input.clientIp,
    });
  } catch (err) {
    // Fail closed — đánh dấu payment failed, giữ order nguyên
    const updated = await prisma.payment.update({
      where: { id: payment.id },
      data: {
        status: 'failed',
        errorMessage: (err as Error).message,
      },
    });
    return { payment: updated, redirectUrl: null, reused: false };
  }

  const updated = await prisma.$transaction(async tx => {
    const p = await tx.payment.update({
      where: { id: payment.id },
      data: {
        status: result.status,
        providerTxnId: result.providerTxnId ?? null,
        redirectUrl: result.redirectUrl ?? null,
        rawResponse: scrubRaw(result.raw) as Prisma.InputJsonValue,
      },
    });
    await tx.paymentEvent.create({
      data: {
        paymentId: p.id,
        kind: 'status_change',
        fromStatus: 'created',
        toStatus: result.status,
        payload: { action: 'createIntent' },
      },
    });
    await writeAudit({
      action: 'payment.create_intent',
      actorId: input.actor?.id ?? null,
      actorEmail: input.actor?.email ?? null,
      actorIp: input.actor?.ip ?? null,
      userAgent: input.actor?.ua ?? null,
      entity: 'payment',
      entityId: p.id,
      diff: { after: { status: p.status, provider: p.provider } },
      requestId: input.requestId ?? null,
    }, tx);
    return p;
  });

  return { payment: updated, redirectUrl: result.redirectUrl, reused: false };
}

/**
 * Xác thực webhook hoặc return URL, rồi apply vào DB nếu chữ ký hợp lệ.
 * Trả về outcome để route trả JSON/redirect tương ứng.
 */
export async function verifyAndApply(provider: PaymentProvider, kind: 'return' | 'webhook', input: VerifyInput, requestId?: string) {
  const adapter = getProvider(provider);
  const outcome: VerifyOutcome = kind === 'return'
    ? await adapter.verifyReturn(input)
    : await adapter.verifyWebhook(input);

  if (!outcome.signatureValid) {
    return { ok: false, outcome, payment: null, order: null };
  }
  if (!outcome.paymentId) {
    return { ok: false, outcome, payment: null, order: null };
  }

  const payment = await prisma.payment.findUnique({ where: { id: outcome.paymentId } });
  if (!payment) return { ok: false, outcome, payment: null, order: null };

  // Idempotent: payment đã succeeded rồi → skip
  if (payment.status === 'succeeded' && outcome.status === 'succeeded') {
    return { ok: true, outcome, payment, order: null, alreadyApplied: true };
  }

  const from = payment.status;
  const to = outcome.status;

  const { payment: updatedPayment, order } = await prisma.$transaction(async tx => {
    const p = await tx.payment.update({
      where: { id: payment.id },
      data: {
        status: to,
        providerTxnId: outcome.providerTxnId ?? payment.providerTxnId,
        errorCode: outcome.errorCode ?? null,
        errorMessage: outcome.errorMessage ?? null,
        rawResponse: scrubRaw({ ...(payment.rawResponse as object ?? {}), [kind]: outcome.raw }) as Prisma.InputJsonValue,
        paidAt: to === 'succeeded' ? new Date() : payment.paidAt,
      },
    });
    await tx.paymentEvent.create({
      data: {
        paymentId: p.id,
        kind: kind === 'return' ? 'webhook' : 'webhook',
        fromStatus: from,
        toStatus: to,
        payload: { kind, errorCode: outcome.errorCode, errorMessage: outcome.errorMessage },
      },
    });

    // Sync Order.paymentStatus nếu cần
    let orderUpdated = null;
    if (to === 'succeeded') {
      orderUpdated = await tx.order.update({
        where: { id: p.orderId },
        data: { paymentStatus: 'paid', paidAt: new Date() },
      });
      await tx.orderEvent.create({
        data: {
          orderId: p.orderId,
          kind: 'payment',
          note: `Đã thanh toán qua ${p.provider} — ${p.providerTxnId ?? ''}`,
          metadata: { paymentId: p.id, provider: p.provider, amount: Number(p.amount) },
        },
      });
    } else if (to === 'failed' || to === 'cancelled') {
      // Không thay đổi order.paymentStatus — vẫn pending để user retry
      await tx.orderEvent.create({
        data: {
          orderId: p.orderId,
          kind: 'payment',
          note: `Thanh toán ${to} qua ${p.provider}${outcome.errorMessage ? ` — ${outcome.errorMessage}` : ''}`,
          metadata: { paymentId: p.id, errorCode: outcome.errorCode },
        },
      });
    }

    await writeAudit({
      action: `payment.${kind}.${to}`,
      entity: 'payment',
      entityId: p.id,
      diff: { before: { status: from }, after: { status: to } },
      requestId: requestId ?? null,
    }, tx);

    return { payment: p, order: orderUpdated };
  });

  // Side-effect: enqueue email khi thanh toán thành công
  if (to === 'succeeded' && order) {
    try {
      const orderFull = await prisma.order.findUnique({
        where: { id: order.id },
        include: { customer: true, items: true },
      });
      if (orderFull?.customer?.email) {
        await enqueueEmail({
          template: 'order.paid',
          toEmail: orderFull.customer.email,
          toName: orderFull.customer.name,
          data: {
            orderCode: orderFull.code,
            total: Number(orderFull.total),
            provider: updatedPayment.provider,
            providerTxnId: updatedPayment.providerTxnId,
          },
          refType: 'order',
          refId: orderFull.id,
        });
      }
    } catch (err) {
      // Không fail payment nếu email enqueue fail
      // eslint-disable-next-line no-console
      console.warn('[payments] enqueue email failed', (err as Error).message);
    }
  }

  return { ok: true, outcome, payment: updatedPayment, order };
}

/**
 * Manual update (cho COD / bank_transfer): admin xác nhận đã nhận tiền.
 */
export async function manualMarkPaid(paymentId: string, actor?: { id?: string; email?: string; ip?: string | null; ua?: string | null }, requestId?: string) {
  const payment = await prisma.payment.findUnique({ where: { id: paymentId } });
  if (!payment) throw new Error('Payment not found');
  if (payment.status === 'succeeded') return payment;

  return await prisma.$transaction(async tx => {
    const p = await tx.payment.update({
      where: { id: paymentId },
      data: { status: 'succeeded', paidAt: new Date() },
    });
    await tx.paymentEvent.create({
      data: {
        paymentId, kind: 'status_change',
        fromStatus: payment.status, toStatus: 'succeeded',
        payload: { manual: true, actor: actor?.email ?? null },
      },
    });
    await tx.order.update({
      where: { id: payment.orderId },
      data: { paymentStatus: 'paid', paidAt: new Date() },
    });
    await tx.orderEvent.create({
      data: {
        orderId: payment.orderId,
        kind: 'payment',
        note: `Xác nhận thanh toán thủ công qua ${payment.provider}`,
        metadata: { paymentId, actor: actor?.email ?? null },
      },
    });
    await writeAudit({
      action: 'payment.manual_mark_paid',
      actorId: actor?.id ?? null,
      actorEmail: actor?.email ?? null,
      actorIp: actor?.ip ?? null,
      userAgent: actor?.ua ?? null,
      entity: 'payment',
      entityId: paymentId,
      diff: { before: { status: payment.status }, after: { status: 'succeeded' } },
      requestId: requestId ?? null,
    }, tx);
    return p;
  });
}

/**
 * Scrub các field có thể chứa secret trong raw payload (access_key, secret, signature).
 */
const SECRET_FIELDS = new Set(['accessKey', 'access_key', 'secret', 'secret_key', 'signature', 'vnp_SecureHash', 'token', 'api_key']);
function scrubRaw(value: unknown): unknown {
  if (value === null || value === undefined) return value;
  if (Array.isArray(value)) return value.map(scrubRaw);
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = SECRET_FIELDS.has(k) ? '[REDACTED]' : scrubRaw(v);
    }
    return out;
  }
  return value;
}

