/**
 * Payment routes.
 *
 * Public (no auth):
 *   GET  /payments/return/:provider   — redirect từ cổng về FE, verify chữ ký
 *   POST /payments/webhook/:provider  — IPN server-to-server
 *
 * Authenticated:
 *   GET   /payments                   — list (admin)
 *   GET   /payments/:id               — detail
 *   POST  /payments                   — create intent cho 1 order
 *   POST  /payments/:id/mark-paid     — admin xác nhận COD/bank_transfer
 *   GET   /payments/providers         — list provider khả dụng
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { createPaymentIntent, verifyAndApply, manualMarkPaid } from '../payments/service.js';
import { availableProviders, getProvider } from '../payments/registry.js';

// ─── Schemas ────────────────────────────────────────────────────

const ListQuery = z.object({
  orderId: z.string().uuid().optional(),
  status:  z.enum(['created','pending','succeeded','failed','cancelled','refunded']).optional(),
  provider: z.enum(['manual','vnpay','momo','stripe']).optional(),
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

const CreateBody = z.object({
  orderId:  z.string().uuid(),
  provider: z.enum(['manual','vnpay','momo','stripe']).optional(),
  returnUrl: z.string().url().optional(),
  ipnUrl:    z.string().url().optional(),
  idempotencyKey: z.string().min(4).max(120).optional(),
}).strict();

// ─── Helpers ────────────────────────────────────────────────────

function serialize(p: Awaited<ReturnType<typeof prisma.payment.findFirst>>) {
  if (!p) return null;
  return {
    id: p.id,
    order_id: p.orderId,
    provider: p.provider,
    provider_txn_id: p.providerTxnId,
    amount: Number(p.amount),
    currency: p.currency,
    status: p.status,
    redirect_url: p.redirectUrl,
    return_url: p.returnUrl,
    error_code: p.errorCode,
    error_message: p.errorMessage,
    idempotency_key: p.idempotencyKey,
    paid_at: p.paidAt?.toISOString() ?? null,
    created_at: p.createdAt.toISOString(),
    updated_at: p.updatedAt.toISOString(),
  };
}

// ─── Plugin ─────────────────────────────────────────────────────

export const paymentRoutes: FastifyPluginAsync = async app => {

  // GET /payments/providers (public — FE cần biết cổng nào đang on)
  app.get('/payments/providers', async () => ({ available: availableProviders() }));

  // ─── Public: return URL ──
  app.get<{ Params: { provider: string } }>('/payments/return/:provider', async (req, reply) => {
    const providerKey = req.params.provider as 'vnpay' | 'momo' | 'manual' | 'stripe';
    if (!['vnpay','momo'].includes(providerKey)) {
      return reply.code(400).send({ error: 'invalid_provider' });
    }
    try { getProvider(providerKey); } catch { return reply.code(404).send({ error: 'unknown_provider' }); }

    const result = await verifyAndApply(providerKey, 'return',
      { payload: req.query as Record<string, string | undefined> }, req.id);

    if (!result.ok) {
      return reply.code(400).send({
        error: 'verify_failed',
        reason: !result.outcome.signatureValid ? 'bad_signature' : 'unknown_payment',
      });
    }
    return {
      payment_id: result.payment?.id,
      status: result.outcome.status,
      order_id: result.payment?.orderId ?? null,
      provider_txn_id: result.outcome.providerTxnId,
    };
  });

  // ─── Public: webhook (IPN) ──
  app.post<{ Params: { provider: string } }>('/payments/webhook/:provider', async (req, reply) => {
    const providerKey = req.params.provider as 'vnpay' | 'momo';
    if (!['vnpay','momo'].includes(providerKey)) {
      return reply.code(400).send({ error: 'invalid_provider' });
    }

    // VNPay gửi query string, MoMo gửi JSON body
    const payload = providerKey === 'vnpay'
      ? (req.query as Record<string, string | undefined>)
      : (req.body as Record<string, unknown>);

    const result = await verifyAndApply(providerKey, 'webhook',
      { payload, headers: req.headers as Record<string, string | undefined> }, req.id);

    // VNPay spec yêu cầu trả JSON { RspCode, Message }
    if (providerKey === 'vnpay') {
      if (!result.outcome.signatureValid) return reply.send({ RspCode: '97', Message: 'Invalid signature' });
      if (!result.payment) return reply.send({ RspCode: '01', Message: 'Order not found' });
      if (result.alreadyApplied) return reply.send({ RspCode: '02', Message: 'Order already confirmed' });
      return reply.send({ RspCode: '00', Message: 'Confirm Success' });
    }

    // MoMo — trả 204 nếu OK, 400 nếu invalid
    if (!result.ok) return reply.code(400).send({ error: 'verify_failed' });
    return reply.code(204).send();
  });

  // ─── Authenticated: list ──
  app.get('/payments', { preHandler: [requireAuth, requirePermission('orders:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where = {
      ...(q.orderId  && { orderId: q.orderId }),
      ...(q.status   && { status: q.status }),
      ...(q.provider && { provider: q.provider }),
    };
    const [total, data] = await Promise.all([
      prisma.payment.count({ where }),
      prisma.payment.findMany({
        where, orderBy: { createdAt: 'desc' },
        skip: (q.page - 1) * q.limit, take: q.limit,
      }),
    ]);
    return { data: data.map(serialize), total, page: q.page, pageSize: q.limit };
  });

  // ─── Authenticated: detail ──
  app.get<{ Params: { id: string } }>('/payments/:id', {
    preHandler: [requireAuth, requirePermission('orders:read')],
  }, async (req, reply) => {
    const p = await prisma.payment.findUnique({
      where: { id: req.params.id },
      include: { events: { orderBy: { createdAt: 'asc' } } },
    });
    if (!p) return reply.code(404).send({ error: 'not_found' });
    return {
      ...serialize(p),
      events: p.events.map(e => ({
        id: e.id, kind: e.kind,
        from_status: e.fromStatus, to_status: e.toStatus,
        payload: e.payload, created_at: e.createdAt.toISOString(),
      })),
    };
  });

  // ─── Authenticated: create intent ──
  app.post('/payments', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = CreateBody.parse(req.body);
    try {
      const r = await createPaymentIntent({
        orderId: body.orderId,
        provider: body.provider,
        returnUrl: body.returnUrl,
        ipnUrl: body.ipnUrl,
        clientIp: req.ip,
        idempotencyKey: body.idempotencyKey,
        actor: { id: req.user?.id ?? null, email: req.user?.email ?? null, ip: req.ip, ua: req.headers['user-agent'] ?? null },
        requestId: req.id,
      });
      return {
        payment: serialize(r.payment),
        redirect_url: r.redirectUrl,
        reused: r.reused,
      };
    } catch (err) {
      reply.code(400);
      return { error: 'create_failed', message: (err as Error).message };
    }
  });

  // ─── Authenticated: mark paid (manual) ──
  app.post<{ Params: { id: string } }>('/payments/:id/mark-paid', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    try {
      const p = await manualMarkPaid(req.params.id, {
        id: req.user?.id, email: req.user?.email, ip: req.ip, ua: req.headers['user-agent'] ?? null,
      }, req.id);
      return { payment: serialize(p) };
    } catch (err) {
      reply.code(400);
      return { error: 'failed', message: (err as Error).message };
    }
  });
};

