import type { FastifyInstance, FastifyRequest, FastifyReply } from 'fastify';
import { resolveSession, SESSION_COOKIE } from '../lib/session.js';
import { permissionsForUser } from '../lib/rbac.js';
import { prisma } from '../lib/prisma.js';

declare module 'fastify' {
  interface FastifyRequest {
    auth: {
      user: { id: string; email: string; name: string };
      sessionId: string;
      permissions: Set<string>;
    } | null;
  }
}

export function registerAuthHooks(app: FastifyInstance) {
  app.decorateRequest('auth', null);

  app.addHook('preHandler', async (req: FastifyRequest) => {
    const sid = req.cookies[SESSION_COOKIE];
    if (!sid) {
      req.auth = null;
      return;
    }
    const session = await resolveSession(sid);
    if (!session) {
      req.auth = null;
      return;
    }
    const user = await prisma.user.findUnique({
      where: { id: session.userId },
      select: { id: true, email: true, name: true, status: true },
    });
    if (!user || user.status !== 'active') {
      req.auth = null;
      return;
    }
    const permissions = await permissionsForUser(user.id);
    req.auth = {
      user: { id: user.id, email: user.email, name: user.name },
      sessionId: session.id,
      permissions,
    };
  });
}

export function requireAuth(req: FastifyRequest, reply: FastifyReply): void {
  if (!req.auth) {
    reply.code(401).send({ error: 'unauthorized', message: 'Cần đăng nhập', requestId: req.id });
    throw reply;

