/**
 * Shipping provider contract.
 *
 * Nhiệm vụ:
 *  - createShipment(): tạo đơn phía carrier + nhận trackingCode + labelUrl
 *  - track(): query tracking (ad-hoc)
 *  - cancel(): huỷ đơn
 *  - parseWebhook(): verify + chuẩn hoá webhook status update
 */

import type { ShippingProvider, ShipmentStatus } from '@prisma/client';

export interface Address {
  fullName: string;
  phone: string;
  line1: string;
  ward?: string;
  district?: string;
  province: string;
  postalCode?: string;
}

export interface CreateShipmentInput {
  shipmentId: string;       // Prisma Shipment.id — dùng làm client_order_code
  orderCode: string;
  shipAddress: Address;
  pickupAddress?: Address;
  items: Array<{ name: string; qty: number; price: number; weight?: number }>;
  weightGram: number;
  lengthCm?: number;
  widthCm?: number;
  heightCm?: number;
  /** cash on delivery amount (nếu COD) */
  codAmount?: number;
  note?: string;
}

export interface CreateShipmentResult {
  trackingCode: string | null;
  labelUrl: string | null;
  shippingFee: number;      // VND
  status: ShipmentStatus;
  raw: Record<string, unknown>;
}

export interface TrackResult {
  status: ShipmentStatus;
  location?: string | null;
  raw: Record<string, unknown>;
}

export interface WebhookInput {
  payload: Record<string, unknown>;
  headers?: Record<string, string | undefined>;
  bodyRaw?: string;
}

export interface WebhookOutcome {
  signatureValid: boolean;
  status: ShipmentStatus;
  trackingCode: string | null;
  shipmentId?: string | null;
  location?: string | null;
  raw: Record<string, unknown>;
}

export interface ShippingProviderAdapter {
  readonly key: ShippingProvider;
  isAvailable(): boolean;
  createShipment(input: CreateShipmentInput): Promise<CreateShipmentResult>;
  track(trackingCode: string): Promise<TrackResult>;
  cancel?(trackingCode: string): Promise<{ ok: boolean; raw: Record<string, unknown> }>;
  verifyWebhook(input: WebhookInput): Promise<WebhookOutcome>;
  /** Lấy phí vận chuyển trước khi tạo đơn (quote) */
  quote?(input: CreateShipmentInput): Promise<{ fee: number; raw: Record<string, unknown> }>;
}

