/**
 * Manual shipping — tự in label, nhân viên tự đưa đi. Không gọi API.
 * Dùng cho đơn nội thành self-ship hoặc shipper riêng.
 */

import { customAlphabet } from 'nanoid';
import type { ShippingProviderAdapter } from './types.js';

const genCode = customAlphabet('0123456789ABCDEFGHJKMNPQRSTVWXYZ', 10);

export const manualShipping: ShippingProviderAdapter = {
  key: 'manual',
  isAvailable() { return true; },

  async createShipment(input) {
    return {
      trackingCode: 'DTX-' + genCode(),
      labelUrl: null,
      shippingFee: 0, // không tính phí phía FE, admin tự nhập
      status: 'created',
      raw: { provider: 'manual', shipmentId: input.shipmentId, orderCode: input.orderCode },
    };
  },

  async track(trackingCode) {
    return { status: 'created', raw: { trackingCode, note: 'manual — check with staff' } };
  },

  async verifyWebhook() {
    return {
      signatureValid: false, status: 'created', trackingCode: null,
      raw: { error: 'manual has no webhook' },
    };
  },
};

