export const ghnShipping: ShippingProviderAdapter = {
  key: 'ghn',
  isAvailable() {
    return config.FEATURE_SHIPPING_GHN === 'on' && !!config.GHN_TOKEN && !!config.GHN_SHOP_ID;
  },

  async quote(input: CreateShipmentInput) {
    const body = {
      service_type_id: 2, // standard
      to_ward_code: input.shipAddress.ward,
      to_district_id: input.shipAddress.district,
      weight: input.weightGram,
      length: input.lengthCm ?? 20,
      width:  input.widthCm  ?? 20,
      height: input.heightCm ?? 10,
      insurance_value: 0,
    };
    const r = await ghnFetch<{ total: number }>('/v2/shipping-order/fee', body);
    return { fee: r.data?.total ?? 0, raw: r.raw as Record<string, unknown> };
  },

  async createShipment(input: CreateShipmentInput): Promise<CreateShipmentResult> {
    if (!this.isAvailable()) {
      throw new Error('GHN chưa được cấu hình (GHN_TOKEN / GHN_SHOP_ID / FEATURE_SHIPPING_GHN).');
    }
    const body = {
      payment_type_id: 2, // người nhận trả
      note: input.note ?? '',
      client_order_code: input.shipmentId,
      required_note: 'KHONGCHOXEMHANG',
      // To address
      to_name:    input.shipAddress.fullName,
      to_phone:   input.shipAddress.phone,
      to_address: input.shipAddress.line1,
      to_ward_name:     input.shipAddress.ward,
      to_district_name: input.shipAddress.district,
      to_province_name: input.shipAddress.province,
      // Parcel
      cod_amount: input.codAmount ?? 0,
      weight: input.weightGram,
      length: input.lengthCm ?? 20,
      width:  input.widthCm  ?? 20,
      height: input.heightCm ?? 10,
      service_type_id: 2,
      items: input.items.map(i => ({
        name: i.name, quantity: i.qty, price: i.price, weight: i.weight ?? 100,
      })),
    };
    const r = await ghnFetch<{ order_code: string; total_fee: number; expected_delivery_time: string }>(
      '/v2/shipping-order/create',
      body,
    );

    if (!r.ok) {
      // Dry-run fallback khi chưa có mapping địa chỉ
      return {
        trackingCode: 'GHN-DRY-' + genCode(),
        labelUrl: null,
        shippingFee: 0,
        status: 'created',
        raw: { dryRun: true, message: r.message, request: body, response: r.raw },
      };
    }
    return {
      trackingCode: r.data?.order_code ?? null,
      labelUrl: null, // GHN có API in label riêng: POST /v2/a5/gen-token
      shippingFee: r.data?.total_fee ?? 0,
      status: 'created',
      raw: r.raw as Record<string, unknown>,
    };
  },

  async track(trackingCode: string): Promise<TrackResult> {
    const r = await ghnFetch<{ status: string; log?: Array<{ status: string; updated_date: string }> }>(
      '/v2/shipping-order/detail',
      { order_code: trackingCode },
    );
    return {
      status: mapStatus(r.data?.status),
      location: null,
      raw: r.raw as Record<string, unknown>,
    };
  },

  async cancel(trackingCode: string) {
    const r = await ghnFetch('/v2/switch-status/cancel', { order_codes: [trackingCode] });
    return { ok: r.ok, raw: r.raw as Record<string, unknown> };
  },

  async verifyWebhook(input: WebhookInput): Promise<WebhookOutcome> {
    // GHN webhook KHÔNG có chữ ký — bảo mật bằng cách IP allowlist + kiểm tra order_code có tồn tại.
    // Service layer sẽ check shipment exists trước khi apply.
    const p = input.payload as { OrderCode?: string; Status?: string; ClientOrderCode?: string; Description?: string };
    return {
      signatureValid: true, // không có chữ ký để verify
      status: mapStatus(p.Status),
      trackingCode: p.OrderCode ?? null,
      shipmentId: p.ClientOrderCode ?? null,
      location: p.Description ?? null,
      raw: p as Record<string, unknown>,
    };
  },
};

