/**
 * GHTK (Giao Hàng Tiết Kiệm) adapter — REST API v1.
 *
 * Auth: header 'Token' = GHTK_TOKEN
 * Docs: https://docs.giaohangtietkiem.vn/
 *
 * Note: Giống GHN, mapping địa chỉ cần extra service. Chưa có mapping → dry-run.
 */

import { customAlphabet } from 'nanoid';
import { config } from '../config.js';
import type {
  ShippingProviderAdapter,
  CreateShipmentInput,
  CreateShipmentResult,
  TrackResult,
  WebhookInput,
  WebhookOutcome,
} from './types.js';
import type { ShipmentStatus } from '@prisma/client';

const genCode = customAlphabet('0123456789ABCDEFGHJKMNPQRSTVWXYZ', 10);

// GHTK status_id → internal
// -1 huỷ; 1 chưa tiếp nhận; 2 đã tiếp nhận; 3 đã lấy; 4 đã điều phối; 5 đã giao; 6 đã đối soát; 7 không lấy; 9 không giao
const GHTK_MAP: Record<string, ShipmentStatus> = {
  '-1': 'cancelled',
  '1':  'created',
  '2':  'ready_to_pick',
  '3':  'picked',
  '4':  'in_transit',
  '5':  'delivered',
  '6':  'delivered',
  '7':  'failed',
  '9':  'failed',
  '11': 'returning',
  '13': 'returned',
};
function mapStatus(id?: string | number): ShipmentStatus {
  if (id == null) return 'created';
  return GHTK_MAP[String(id)] ?? 'in_transit';
}

async function ghtkFetch<T = unknown>(path: string, method: 'GET' | 'POST', body?: unknown) {
  try {
    const res = await fetch(config.GHTK_ENDPOINT + path, {
      method,
      headers: {
        'content-type': 'application/json',
        Token: config.GHTK_TOKEN,
      },
      body: body ? JSON.stringify(body) : undefined,
      signal: AbortSignal.timeout(20_000),
    });
    const json = (await res.json().catch(() => ({}))) as { success?: boolean; message?: string; order?: T; fee?: { fee: number } };
    return { ok: !!json.success, data: (json.order ?? json.fee ?? json) as T, message: json.message, raw: json };
  } catch (err) {
    return { ok: false, message: (err as Error).message, raw: { error: (err as Error).message } as unknown };
  }
}

export const ghtkShipping: ShippingProviderAdapter = {
  key: 'ghtk',
  isAvailable() {
    return config.FEATURE_SHIPPING_GHTK === 'on' && !!config.GHTK_TOKEN;
  },

  async quote(input) {
    const qs = new URLSearchParams({
      pick_province: input.pickupAddress?.province ?? 'Hà Nội',
      pick_district: input.pickupAddress?.district ?? '',
      province: input.shipAddress.province,
      district: input.shipAddress.district ?? '',
      weight:  String(input.weightGram),
      value:   String(input.items.reduce((s, i) => s + i.price * i.qty, 0)),
      transport: 'road',
    });
    const r = await ghtkFetch<{ fee: number }>(`/services/shipment/fee?${qs.toString()}`, 'GET');
    return { fee: (r.data as { fee?: number })?.fee ?? 0, raw: r.raw as Record<string, unknown> };
  },

  async createShipment(input: CreateShipmentInput): Promise<CreateShipmentResult> {
    if (!this.isAvailable()) {
      throw new Error('GHTK chưa được cấu hình (GHTK_TOKEN / FEATURE_SHIPPING_GHTK).');
    }
    const body = {
      products: input.items.map(i => ({
        name: i.name, price: i.price, weight: i.weight ?? 0.1, quantity: i.qty,
      })),
      order: {
        id: input.shipmentId,
        pick_name:    input.pickupAddress?.fullName ?? 'Detoxblanc',
        pick_address: input.pickupAddress?.line1    ?? '',
        pick_province: input.pickupAddress?.province ?? 'Hà Nội',
        pick_district: input.pickupAddress?.district ?? '',
        pick_tel:     input.pickupAddress?.phone    ?? '',
        tel:        input.shipAddress.phone,
        name:       input.shipAddress.fullName,
        address:    input.shipAddress.line1,
        province:   input.shipAddress.province,
        district:   input.shipAddress.district ?? '',
        ward:       input.shipAddress.ward ?? '',
        hamlet:     'Khác',
        is_freeship: '0',
        pick_money: input.codAmount ?? 0,
        note:       input.note ?? '',
        value:      input.items.reduce((s, i) => s + i.price * i.qty, 0),
        transport:  'road',
        deliver_option: 'xteam',
      },
    };
    const r = await ghtkFetch<{ label: string; tracking_id: string; fee: number }>('/services/shipment/order', 'POST', body);

    if (!r.ok) {
      return {
        trackingCode: 'GHTK-DRY-' + genCode(),
        labelUrl: null,
        shippingFee: 0,
        status: 'created',
        raw: { dryRun: true, message: r.message, request: body, response: r.raw },
      };
    }
    return {
      trackingCode: (r.data as { label?: string })?.label ?? null,
      labelUrl: null,
      shippingFee: (r.data as { fee?: number })?.fee ?? 0,
      status: 'created',
      raw: r.raw as Record<string, unknown>,
    };
  },

  async track(trackingCode: string): Promise<TrackResult> {
    const r = await ghtkFetch<{ status_id: string }>(`/services/shipment/v2/${encodeURIComponent(trackingCode)}`, 'GET');
    const data = r.data as { status_id?: string; status?: string } | undefined;
    return {
      status: mapStatus(data?.status_id),
      location: data?.status ?? null,
      raw: r.raw as Record<string, unknown>,
    };
  },

  async cancel(trackingCode: string) {
    const r = await ghtkFetch(`/services/shipment/cancel/${encodeURIComponent(trackingCode)}`, 'POST');
    return { ok: r.ok, raw: r.raw as Record<string, unknown> };
  },

  async verifyWebhook(input: WebhookInput): Promise<WebhookOutcome> {
    // GHTK webhook có sign HMAC SHA256 với GHTK_TOKEN (nếu bật). MVP: skip verify.
    const p = input.payload as { label_id?: string; status_id?: string | number; partner_id?: string; action_time?: string; reason?: string };
    return {
      signatureValid: true,
      status: mapStatus(p.status_id),
      trackingCode: p.label_id ?? null,
      shipmentId: p.partner_id ?? null,
      location: p.reason ?? null,
      raw: p as Record<string, unknown>,
    };
  },
};

