/**
 * Shipment routes.
 *
 * Public:
 *   POST /shipments/webhook/:provider    — IPN từ carrier
 *   GET  /shipments/track/:trackingCode  — public track (không cần auth, rate-limited global)
 *
 * Authenticated:
 *   GET   /shipments                 — list (admin)
 *   GET   /shipments/:id             — detail
 *   POST  /shipments                 — create shipment cho 1 order
 *   POST  /shipments/:id/cancel      — huỷ
 *   GET   /shipping/providers        — list provider khả dụng
 *   POST  /shipping/quote            — quote phí (không tạo đơn)
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { availableShippingProviders, getShippingProvider } from '../shipping/registry.js';
import { createShipment, applyWebhook, validNextStatuses } from '../shipping/service.js';

const ListQuery = z.object({
  orderId: z.string().uuid().optional(),
  status:  z.enum(['created','ready_to_pick','picked','in_transit','delivered','failed','returning','returned','cancelled']).optional(),
