/**
 * BullMQ queue cho email.
 *
 * Dùng Redis riêng (không share với rate-limit/session) vì BullMQ yêu cầu
 * maxRetriesPerRequest = null. Tái sử dụng REDIS_URL.
 */

import { Queue } from 'bullmq';
import IORedis from 'ioredis';
import { config } from '../config.js';

export const QUEUE_NAME = 'email';

// BullMQ cần connection riêng với maxRetriesPerRequest=null
export const emailQueueConnection = new IORedis(config.REDIS_URL, {
  maxRetriesPerRequest: null,
  enableReadyCheck: false,
  lazyConnect: true,
});

// Kết nối lazy — chỉ open khi enqueue/worker cần
emailQueueConnection.on('error', err => {
  // eslint-disable-next-line no-console
  console.error('[email-queue] redis error', err.message);
});

export const emailQueue = new Queue(QUEUE_NAME, {
  connection: emailQueueConnection,
  defaultJobOptions: {
    attempts: 5,
    backoff: { type: 'exponential', delay: 10_000 },
    removeOnComplete: { age: 7 * 24 * 3600, count: 5000 },
    removeOnFail: { age: 30 * 24 * 3600, count: 2000 },
  },
});

export type EmailJobData = {
  /** EmailJob.id — worker dùng để update status */
  emailJobId: string;
};

