/**
 * Template registry — mỗi template export { subject(data), html(data), text(data) }.
 *
 * Không dùng Handlebars/MJML để tránh thêm dep — template là pure functions.
 * Khi cần thiết kế đẹp hơn, port sang React Email hoặc MJML ở task riêng.
 *
 * Invariant:
 *  - Subject ngắn gọn, KHÔNG chứa PII (chỉ mã đơn, tên khách thì OK)
 *  - Body plain text = fallback cho client không render HTML
 */

type Templater = {
  subject: (data: Record<string, unknown>) => string;
  html:    (data: Record<string, unknown>) => string;
  text:    (data: Record<string, unknown>) => string;
};

function escape(s: unknown): string {
  return String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

function wrapHtml(title: string, body: string): string {
  return `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${escape(title)}</title></head>
<body style="margin:0;padding:0;background:#F7F9F8;font-family:'Inter',Arial,sans-serif;color:#0F1F1C">
  <div style="max-width:560px;margin:0 auto;padding:24px 16px">
    <div style="background:#fff;border-radius:12px;padding:28px 24px;box-shadow:0 2px 12px rgba(15,31,28,.06)">
      <h1 style="margin:0 0 12px;font-size:20px;color:#0F3B37">Detoxblanc</h1>
      ${body}
    </div>
    <p style="margin:18px 12px 0;font-size:11px;color:#7B8F8A;text-align:center">
      Email này được gửi tự động — vui lòng không trả lời trực tiếp.<br>
      © ${new Date().getFullYear()} Detoxblanc · detoxblanc.com
    </p>
  </div>
</body></html>`;
}

const T: Record<string, Templater> = {
  /* ─── Order lifecycle ─── */

  'order.confirmation': {
    subject: d => `Đã nhận đơn ${d.orderCode ?? ''} — Detoxblanc`,
    html: d => wrapHtml('Đã nhận đơn', `
      <p>Chào <strong>${escape(d.customerName) || 'bạn'}</strong>,</p>
      <p>Detoxblanc đã nhận đơn hàng <strong>${escape(d.orderCode)}</strong>. Chúng tôi sẽ xác nhận và đóng gói trong 2 giờ làm việc.</p>
      <p style="padding:12px 14px;background:#E4F4F2;border-radius:8px;margin:14px 0;color:#0F3B37">
        <strong>Tổng giá trị:</strong> ${escape(Number(d.total || 0).toLocaleString('vi-VN'))} ₫<br>
        <strong>Phương thức TT:</strong> ${escape(d.paymentMethod) || '—'}
      </p>
      <p>Theo dõi đơn tại: <a href="${escape(d.trackingUrl) || '#'}">${escape(d.trackingUrl) || 'detoxblanc.com/track'}</a></p>`),
    text: d => `Detoxblanc đã nhận đơn ${d.orderCode}. Tổng: ${Number(d.total || 0).toLocaleString('vi-VN')} ₫.`,
  },

  'order.paid': {
    subject: d => `Đã nhận thanh toán — đơn ${d.orderCode ?? ''}`,
    html: d => wrapHtml('Đã nhận thanh toán', `
      <p>Đơn hàng <strong>${escape(d.orderCode)}</strong> đã được thanh toán thành công qua <strong>${escape(d.provider)}</strong>.</p>
      <p>Mã giao dịch: <code style="background:#F7F9F8;padding:2px 6px;border-radius:4px">${escape(d.providerTxnId) || '—'}</code></p>
      <p>Chúng tôi sẽ đóng gói và gửi đi trong 24h làm việc.</p>`),
    text: d => `Đơn ${d.orderCode} đã thanh toán thành công qua ${d.provider}.`,
  },

  'order.shipped': {
