/**
 * Email transport providers.
 *
 * Strategy:
 *  - console: dev-friendly, in ra stdout. Không cần setup.
 *  - resend: production default (REST API).
 *  - postmark: alt.
 *  - mailhog: local SMTP catcher (via fetch-based stub — không dùng nodemailer để giữ dep nhỏ).
 *
 * Chọn provider qua EMAIL_PROVIDER env. Nếu thiếu API key → fallback về console.
 */

import { config } from '../config.js';

export interface SendInput {
  to: string;
  toName?: string | null;
  from?: string;
  subject: string;
  html: string;
  text: string;
  tag?: string;
  idempotencyKey?: string;
}

export interface SendResult {
  provider: string;
  providerId: string | null;
  ok: boolean;
  error?: string;
}

// ─── console (dev) ──
const consoleProvider = {
  async send(input: SendInput): Promise<SendResult> {
    const lines = [
      '━━━━━━━━━━━━━━━ 📧 EMAIL ━━━━━━━━━━━━━━━',
      `To:      ${input.toName ? `${input.toName} <${input.to}>` : input.to}`,
      `From:    ${input.from || config.EMAIL_FROM}`,
      `Subject: ${input.subject}`,
      input.tag ? `Tag:     ${input.tag}` : '',
      '───────────────────────────────────────',
      input.text,
      '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
    ].filter(Boolean);
    // eslint-disable-next-line no-console
    console.log(lines.join('\n'));
    return { provider: 'console', providerId: `console-${Date.now()}`, ok: true };
  },
};

// ─── Resend ──
const resendProvider = {
  async send(input: SendInput): Promise<SendResult> {
    if (!config.EMAIL_API_KEY) {
      return consoleProvider.send(input).then(r => ({ ...r, provider: 'console-fallback' }));
    }
    try {
      const res = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${config.EMAIL_API_KEY}`,
          ...(input.idempotencyKey ? { 'Idempotency-Key': input.idempotencyKey } : {}),
        },
        body: JSON.stringify({
          from: input.from || config.EMAIL_FROM,
          to: [input.to],
          subject: input.subject,
          html: input.html,
          text: input.text,
          tags: input.tag ? [{ name: 'template', value: input.tag }] : undefined,
        }),
        signal: AbortSignal.timeout(15_000),
      });
      const json = (await res.json().catch(() => ({}))) as { id?: string; message?: string };
      if (!res.ok) return { provider: 'resend', providerId: null, ok: false, error: json.message || `HTTP ${res.status}` };
      return { provider: 'resend', providerId: json.id ?? null, ok: true };
    } catch (err) {
      return { provider: 'resend', providerId: null, ok: false, error: (err as Error).message };
    }
  },
};

// ─── Postmark ──
const postmarkProvider = {
  async send(input: SendInput): Promise<SendResult> {
    if (!config.EMAIL_API_KEY) return consoleProvider.send(input);
    try {
      const res = await fetch('https://api.postmarkapp.com/email', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          accept: 'application/json',
          'X-Postmark-Server-Token': config.EMAIL_API_KEY,
        },
        body: JSON.stringify({
          From: input.from || config.EMAIL_FROM,
          To: input.to,
          Subject: input.subject,
          HtmlBody: input.html,
          TextBody: input.text,
          Tag: input.tag,
          MessageStream: 'outbound',
        }),
        signal: AbortSignal.timeout(15_000),
      });
      const json = (await res.json().catch(() => ({}))) as { MessageID?: string; Message?: string };
      if (!res.ok) return { provider: 'postmark', providerId: null, ok: false, error: json.Message || `HTTP ${res.status}` };
      return { provider: 'postmark', providerId: json.MessageID ?? null, ok: true };
    } catch (err) {
      return { provider: 'postmark', providerId: null, ok: false, error: (err as Error).message };
    }
  },
};

export function getProvider(name?: string) {
  const key = (name || config.EMAIL_PROVIDER || 'console').toLowerCase();
  switch (key) {
    case 'resend':   return resendProvider;
    case 'postmark': return postmarkProvider;
    case 'console':  return consoleProvider;
    default:         return consoleProvider;
  }
}

