/**
 * BullMQ worker — process EmailJob queue.
 *
 * Flow:
 *   enqueueEmail() → tạo bản ghi EmailJob(status=queued) + push job có { emailJobId }
 *   Worker nhận job → load EmailJob → render template → gọi provider → cập nhật status
 *
 * Retries:
 *   BullMQ tự retry (5 attempts, exponential backoff). EmailJob.attempt ghi nhận số lần.
 *   Sau attempts hết → status=failed, giữ để admin xử lý thủ công.
 */

import { Worker, type Job } from 'bullmq';
import { config } from '../config.js';
import { prisma } from '../lib/prisma.js';
import { QUEUE_NAME, emailQueueConnection, type EmailJobData } from './queue.js';
import { render } from './templates.js';
import { getProvider } from './providers.js';

async function process(job: Job<EmailJobData>) {
  const { emailJobId } = job.data;
  const record = await prisma.emailJob.findUnique({ where: { id: emailJobId } });
  if (!record) {
    // eslint-disable-next-line no-console
    console.warn('[email-worker] job record missing, skipping', emailJobId);
    return { ok: false, reason: 'record_missing' };
  }
  if (record.status === 'sent') return { ok: true, skipped: true }; // idempotent

  await prisma.emailJob.update({
    where: { id: emailJobId },
    data: { status: 'sending', attempt: { increment: 1 } },
  });

  let rendered;
  try {
    rendered = render(record.template, (record.data as Record<string, unknown>) ?? {});
  } catch (err) {
    await prisma.emailJob.update({
      where: { id: emailJobId },
      data: { status: 'failed', lastError: `render: ${(err as Error).message}` },
    });
    // render lỗi = permanent fail, không cần retry
    return { ok: false, reason: 'render_failed' };
  }

  const provider = getProvider();
  const result = await provider.send({
    to: record.toEmail,
    toName: record.toName,
    subject: record.subject || rendered.subject,
    html: rendered.html,
