/**
 * Email jobs admin routes — xem lịch sử, retry failed jobs, preview template.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { retryEmailJob } from '../email/index.js';
import { allTemplates, render, getTemplate } from '../email/templates.js';

const ListQuery = z.object({
  q: z.string().max(200).optional(),
  status: z.enum(['queued','sending','sent','failed','skipped']).optional(),
  template: z.string().max(80).optional(),
  refType: z.string().max(32).optional(),
  refId:   z.string().uuid().optional(),
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

function serialize(j: Awaited<ReturnType<typeof prisma.emailJob.findFirst>>) {
  if (!j) return null;
  return {
    id: j.id,
    template: j.template,
    to_email: j.toEmail,
    to_name: j.toName,
    subject: j.subject,
    status: j.status,
    provider: j.provider,
    provider_id: j.providerId,
    attempt: j.attempt,
    last_error: j.lastError,
    sent_at: j.sentAt?.toISOString() ?? null,
    scheduled_at: j.scheduledAt?.toISOString() ?? null,
    ref_type: j.refType,
    ref_id: j.refId,
    created_at: j.createdAt.toISOString(),
    updated_at: j.updatedAt.toISOString(),
  };
}

export const emailJobRoutes: FastifyPluginAsync = async app => {

  app.get('/email-jobs', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async req => {
    const q = ListQuery.parse(req.query);
    const where = {
      ...(q.status && { status: q.status }),
      ...(q.template && { template: q.template }),
      ...(q.refType && { refType: q.refType }),
      ...(q.refId && { refId: q.refId }),
      ...(q.q && {
        OR: [
          { toEmail: { contains: q.q, mode: 'insensitive' as const } },
          { subject: { contains: q.q, mode: 'insensitive' as const } },
        ],
      }),
    };
    const [total, data] = await Promise.all([
      prisma.emailJob.count({ where }),
      prisma.emailJob.findMany({
        where, orderBy: { createdAt: 'desc' },
        skip: (q.page - 1) * q.limit, take: q.limit,
      }),
    ]);
    return { data: data.map(serialize), total, page: q.page, pageSize: q.limit };
  });

  app.get<{ Params: { id: string } }>('/email-jobs/:id', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async (req, reply) => {
    const j = await prisma.emailJob.findUnique({ where: { id: req.params.id } });
    if (!j) return reply.code(404).send({ error: 'not_found' });
    return { ...serialize(j), data: j.data };
  });

  app.post<{ Params: { id: string } }>('/email-jobs/:id/retry', {
    preHandler: [requireAuth, requirePermission('settings:write')],
  }, async (req, reply) => {
    try {
      const j = await retryEmailJob(req.params.id);
      return { job: serialize(j) };
    } catch (err) {
      reply.code(400);
      return { error: 'retry_failed', message: (err as Error).message };
    }
  });

  // Preview template với sample data — tiện cho email designer
  app.get('/email-templates', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async () => {
    return { templates: allTemplates() };
  });

  app.post<{ Params: { key: string } }>('/email-templates/:key/preview', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async (req, reply) => {
    const tpl = getTemplate(req.params.key);
    if (!tpl) return reply.code(404).send({ error: 'unknown_template' });
    const body = (req.body as Record<string, unknown>) || {};
    return render(req.params.key, body);
  });
};

