  const providerKey = req.params.provider as 'vnpay' | 'momo';
  if (!['vnpay','momo'].includes(providerKey)) {
    return reply.code(400).send({ error: 'invalid_provider' });
  }

  // VNPay gửi query string, MoMo gửi JSON body
  const payload = providerKey === 'vnpay'
    ? (req.query as Record<string, string | undefined>)
    : (req.body as Record<string, unknown>);

  const result = await verifyAndApply(providerKey, 'webhook',
    { payload, headers: req.headers as Record<string, string | undefined> }, req.id);

  // VNPay spec yêu cầu trả JSON { RspCode, Message }
  if (providerKey === 'vnpay') {
    if (!result.outcome.signatureValid) return reply.send({ RspCode: '97', Message: 'Invalid signature' });
    if (!result.payment) return reply.send({ RspCode: '01', Message: 'Order not found' });
    if (result.alreadyApplied) return reply.send({ RspCode: '02', Message: 'Order already confirmed' });
    return reply.send({ RspCode: '00', Message: 'Confirm Success' });
  }

/**
 * Shipping service — orchestrator cho Shipment DB state + provider API.
 */

import type { Prisma, ShipmentStatus, ShippingProvider } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { enqueueEmail } from '../email/index.js';
import { getShippingProvider } from './registry.js';
import type { WebhookInput } from './types.js';

interface CreateShipmentArgs {
  orderId: string;
  provider: ShippingProvider;
  weightGram?: number;
  lengthCm?: number;
  widthCm?: number;
  heightCm?: number;
  codAmount?: number;
  note?: string;
  actor?: { id: string | null; email: string | null; ip: string | null; ua: string | null };
  requestId?: string;
}

// Chuyển trạng thái hợp lệ (soft guard — carrier có thể skip step)
const TRANSITIONS: Record<ShipmentStatus, ShipmentStatus[]> = {
  created:       ['ready_to_pick', 'cancelled'],
  ready_to_pick: ['picked', 'cancelled'],
  picked:        ['in_transit', 'returning'],
  in_transit:    ['delivered', 'failed', 'returning'],
  delivered:     ['returning'],
  failed:        ['returning', 'in_transit'],
  returning:     ['returned', 'in_transit'],
  returned:      [],
  cancelled:     [],
};

export async function createShipment(args: CreateShipmentArgs) {
  const order = await prisma.order.findUnique({
    where: { id: args.orderId },
    include: { items: true, customer: true },
  });
  if (!order) throw new Error('Order not found');
  if (order.status === 'cancelled' || order.status === 'returned') {
    throw new Error('Không thể tạo vận đơn cho đơn đã huỷ/hoàn');
  }

  // Chỉ cho 1 shipment active / order (MVP). Nếu cần nhiều package → bỏ guard này.
  const existing = await prisma.shipment.findFirst({
    where: {
      orderId: order.id,
      status: { notIn: ['cancelled', 'returned', 'failed'] },
    },
  });
  if (existing) throw new Error('Order đã có shipment đang hoạt động');

  const adapter = getShippingProvider(args.provider);
  const shipAddr = order.shippingAddress as {
    fullName: string; phone: string; line1: string; province: string;
    ward?: string; district?: string; postalCode?: string;
  };

  // Tạo bản ghi Shipment trước (status=created) để có id
  const shipment = await prisma.shipment.create({
    data: {
      orderId: order.id,
      provider: args.provider,
      status: 'created',
      shippingFee: order.shippingFee,
      weightGram: args.weightGram ?? null,
      lengthCm: args.lengthCm ?? null,
      widthCm:  args.widthCm ?? null,
      heightCm: args.heightCm ?? null,
      shipAddress: shipAddr as unknown as Prisma.InputJsonValue,
    },
  });

  let result;
  try {
    result = await adapter.createShipment({
      shipmentId: shipment.id,
      orderCode: order.code,
      shipAddress: shipAddr,
      items: order.items.map(i => ({
        name: i.nameSnapshot, qty: i.qty, price: Number(i.priceUnit),
      })),
      weightGram: args.weightGram ?? order.items.reduce((s, i) => s + i.qty * 100, 0),
      lengthCm: args.lengthCm, widthCm: args.widthCm, heightCm: args.heightCm,
      codAmount: args.codAmount ?? (order.paymentMethod === 'cod' ? Number(order.total) : 0),
      note: args.note,
    });
  } catch (err) {
    const failed = await prisma.shipment.update({
      where: { id: shipment.id },
      data: { status: 'failed', errorMessage: (err as Error).message },
    });
    return { shipment: failed, order };
  }

  const updated = await prisma.$transaction(async tx => {
    const s = await tx.shipment.update({
      where: { id: shipment.id },
      data: {
        trackingCode: result.trackingCode,
        labelUrl: result.labelUrl,
        shippingFee: BigInt(result.shippingFee || 0),
        status: result.status,
        rawResponse: result.raw as Prisma.InputJsonValue,
      },
    });
    await tx.shipmentEvent.create({
      data: {
        shipmentId: s.id,
        kind: 'status_change',
        fromStatus: 'created',
        toStatus: result.status,
        payload: { action: 'createShipment', trackingCode: result.trackingCode },
      },
    });
    // Link vào order events
    await tx.orderEvent.create({
      data: {
        orderId: order.id,
        kind: 'shipping',
        note: `Đã tạo vận đơn ${args.provider}${result.trackingCode ? ` (${result.trackingCode})` : ''}`,
        metadata: { shipmentId: s.id, trackingCode: result.trackingCode },
      },
    });
    // Nếu cấu hình auto-move order → shipping khi shipment ready
    if (order.status === 'packing') {
      await tx.order.update({
        where: { id: order.id },
        data: { status: 'shipping', shippedAt: new Date() },
      });
    }
    await writeAudit({
      action: 'shipment.create',
      actorId: args.actor?.id ?? null,
      actorEmail: args.actor?.email ?? null,
      actorIp: args.actor?.ip ?? null,
      userAgent: args.actor?.ua ?? null,
      entity: 'shipment',
      entityId: s.id,
      diff: { after: { trackingCode: s.trackingCode, provider: s.provider } },
      requestId: args.requestId ?? null,
    }, tx);
    return s;
  });

  // Enqueue email "đơn đã đóng gói & gửi đi"
  if (order.customer?.email) {
    try {
      await enqueueEmail({
        template: 'order.shipped',
        toEmail: order.customer.email,
        toName: order.customer.name,
        data: {
          orderCode: order.code,
          trackingCode: updated.trackingCode,
          provider: updated.provider,
        },
        refType: 'order',
        refId: order.id,
      });
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[shipping] enqueue email failed', (err as Error).message);
    }
  }

  return { shipment: updated, order };
}

export async function applyWebhook(provider: ShippingProvider, input: WebhookInput, requestId?: string) {
  const adapter = getShippingProvider(provider);
  const outcome = await adapter.verifyWebhook(input);

  if (!outcome.signatureValid) return { ok: false as const, outcome };

  // Match bằng trackingCode hoặc shipmentId (client_order_code)
  type ShipmentRow = Awaited<ReturnType<typeof prisma.shipment.findUnique>>;
  let shipment: ShipmentRow = null;
  if (outcome.shipmentId) {
    shipment = await prisma.shipment.findUnique({ where: { id: outcome.shipmentId } });
  }
  if (!shipment && outcome.trackingCode) {
    shipment = await prisma.shipment.findFirst({ where: { trackingCode: outcome.trackingCode } });
  }
  if (!shipment) return { ok: false as const, outcome, error: 'shipment_not_found' as const };
  const sh = shipment; // giữ narrow

  const from = sh.status;
  const to = outcome.status;

  if (from === to) {
    // No-op — vẫn ghi event để audit
    await prisma.shipmentEvent.create({
      data: {
        shipmentId: sh.id, kind: 'webhook',
        fromStatus: from, toStatus: to,
        location: outcome.location ?? null,
        payload: outcome.raw as Prisma.InputJsonValue,
      },
    });
    return { ok: true as const, outcome, shipment: sh, alreadyApplied: true };
  }

  const updated = await prisma.$transaction(async tx => {
    const s = await tx.shipment.update({
      where: { id: sh.id },
      data: {
        status: to,
        pickedAt: to === 'picked' ? new Date() : sh.pickedAt,
        deliveredAt: to === 'delivered' ? new Date() : sh.deliveredAt,
      },
    });
    await tx.shipmentEvent.create({
      data: {
        shipmentId: s.id, kind: 'webhook',
        fromStatus: from, toStatus: to,
        location: outcome.location ?? null,
        payload: outcome.raw as Prisma.InputJsonValue,
      },
    });
    // Sync Order.status theo shipping milestone
    if (to === 'delivered') {
      await tx.order.update({
        where: { id: s.orderId },
        data: { status: 'delivered', deliveredAt: new Date() },
      });
      await tx.orderEvent.create({
        data: { orderId: s.orderId, kind: 'status_change', fromState: 'shipping', toState: 'delivered', note: `Giao thành công — ${provider}` },
      });
    } else if (to === 'in_transit' || to === 'picked') {
      await tx.order.updateMany({
        where: { id: s.orderId, status: { in: ['packing', 'confirmed'] } },
        data: { status: 'shipping', shippedAt: new Date() },
      });
    }
    await writeAudit({
      action: `shipment.webhook.${to}`,
      entity: 'shipment', entityId: s.id,
      diff: { before: { status: from }, after: { status: to } },
      requestId: requestId ?? null,
    }, tx);
    return s;
  });

  // Email khi delivered
  if (to === 'delivered') {
    const order = await prisma.order.findUnique({ where: { id: updated.orderId }, include: { customer: true } });
    if (order?.customer?.email) {
      try {
        await enqueueEmail({
          template: 'order.delivered',
          toEmail: order.customer.email,
          toName: order.customer.name,
          data: { orderCode: order.code, trackingCode: updated.trackingCode },
          refType: 'order', refId: order.id,
        });
      } catch { /* ignore */ }
    }
  }

  return { ok: true, outcome, shipment: updated };
}

/** Bảng NEXT để FE hiển thị action hợp lệ */
export function validNextStatuses(s: ShipmentStatus): ShipmentStatus[] {
  return TRANSITIONS[s] ?? [];
}

/**
 * Server bootstrap — Fastify 5 + plugins + routes.
 *
 * Khởi động:  pnpm --filter api dev
 * Production: pnpm --filter api build && pnpm --filter api start
 */

import 'dotenv/config';
import Fastify from 'fastify';
import cookie from '@fastify/cookie';
import cors from '@fastify/cors';
import helmet from '@fastify/helmet';
import rateLimit from '@fastify/rate-limit';
import sensible from '@fastify/sensible';
import { config } from './config.js';
import { redis } from './lib/redis.js';
import { registerAuthHooks } from './middleware/auth.js';
import { registerCsrf } from './middleware/csrf.js';
import { registerErrorHandler } from './plugins/error-handler.js';
import { healthRoutes } from './routes/health.js';
import { authRoutes } from './routes/auth.js';
import { productRoutes } from './routes/products.js';
import { mediaRoutes } from './routes/media.js';
import { auditRoutes } from './routes/audit.js';
import { userRoutes } from './routes/users.js';
import { orderRoutes } from './routes/orders.js';
import { customerRoutes } from './routes/customers.js';
import { voucherRoutes } from './routes/vouchers.js';
import { articleRoutes } from './routes/articles.js';
import { inventoryRoutes } from './routes/inventory.js';
import { settingsRoutes } from './routes/settings.js';
import { reportRoutes } from './routes/reports.js';
import { paymentRoutes } from './routes/payments.js';
import { shipmentRoutes } from './routes/shipments.js';
import { emailJobRoutes } from './routes/email-jobs.js';
import { startEmailWorker, stopEmailWorker } from './email/index.js';

export async function build() {
  const app = Fastify({
    logger: {
      level: config.LOG_LEVEL,
      redact: {
        paths: [
          'req.headers.authorization',
          'req.headers.cookie',
          '*.password',
          '*.passwordHash',
          '*.totp',
          '*.totpSecret',
          '*.secret',
        ],
        censor: '[REDACTED]',
      },
      ...(config.isDev && {
        transport: { target: 'pino-pretty', options: { colorize: true, singleLine: true } },
      }),
    },
    trustProxy: config.isProd,
    genReqId: () => crypto.randomUUID(),
    bodyLimit: 2 * 1024 * 1024,      // 2MB JSON body
    connectionTimeout: 30_000,
    keepAliveTimeout: 65_000,
    // BigInt serialize — prisma trả bigint cho VND
    ajv: { customOptions: { removeAdditional: false } },
  });

  // BigInt → string trong JSON (FE parse về number an toàn vì < 2^53)
  app.addHook('onSend', async (_req, reply, payload) => {
    if (typeof payload === 'string') return payload;
    return payload;
  });

  // ─ Security plugins ─
  await app.register(helmet, {
    contentSecurityPolicy: false,  // API-only, CSP set trên FE
    crossOriginResourcePolicy: { policy: 'same-site' },
  });

  await app.register(cors, {
    origin: (origin, cb) => {
      if (!origin) return cb(null, true); // curl, server-to-server
      if (config.corsOrigins.includes(origin)) return cb(null, true);
      return cb(new Error('CORS denied'), false);
    },
    credentials: true,
    methods: ['GET', 'POST', 'PATCH', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'X-CSRF-Token', 'X-Request-Id'],
    exposedHeaders: ['X-Request-Id'],
    maxAge: 600,
  });

  await app.register(cookie, {
    secret: config.SESSION_SECRET,
    parseOptions: {},
  });

  await app.register(rateLimit, {
    global: true,
    max: config.RATE_LIMIT_MAX,
    timeWindow: config.RATE_LIMIT_WINDOW_MS,
    redis,
    keyGenerator: req => req.ip,
    allowList: (req) => req.url === '/v1/health',
    addHeadersOnExceeding: { 'x-ratelimit-limit': true, 'x-ratelimit-remaining': true },
    errorResponseBuilder: (req, ctx) => ({
      error: 'rate_limited',
      message: `Quá nhanh. Thử lại sau ${Math.ceil(ctx.ttl / 1000)} giây`,
      requestId: req.id,
    }),
  });

  await app.register(sensible);

  // ─ Custom hooks ─
  registerErrorHandler(app);
  registerCsrf(app);
  registerAuthHooks(app);

  // ─ Versioned API ─
  await app.register(async v1 => {
    await v1.register(healthRoutes);
    await v1.register(authRoutes);
    await v1.register(productRoutes);
    await v1.register(mediaRoutes);
    await v1.register(auditRoutes);
    await v1.register(userRoutes);
    await v1.register(orderRoutes);
    await v1.register(customerRoutes);
    await v1.register(voucherRoutes);
    await v1.register(articleRoutes);
    await v1.register(inventoryRoutes);
    await v1.register(settingsRoutes);
    await v1.register(reportRoutes);
    await v1.register(paymentRoutes);
    await v1.register(shipmentRoutes);
    await v1.register(emailJobRoutes);
  }, { prefix: '/v1' });

  return app;
}

async function main() {
  const app = await build();
  try {
    await app.listen({ port: config.PORT, host: config.HOST });
    app.log.info(
      { env: config.NODE_ENV, version: process.env.npm_package_version },
      `🚀 API ready at http://${config.HOST}:${config.PORT}`,
    );
  } catch (err) {
    app.log.fatal({ err }, 'Failed to start');
    process.exit(1);
  }

  // Start email worker (sau khi API đã listen)
  startEmailWorker();

  // Graceful shutdown
  const shutdown = async (signal: string) => {
    app.log.info(`Received ${signal}, shutting down...`);
    await stopEmailWorker().catch(() => undefined);
    await app.close();
    await redis.quit().catch(() => undefined);
    process.exit(0);
  };
  process.on('SIGTERM', () => void shutdown('SIGTERM'));
  process.on('SIGINT', () => void shutdown('SIGINT'));
}

// JSON bigint support — Postgres bigint đến từ Prisma
// eslint-disable-next-line @typescript-eslint/no-explicit-any
(BigInt.prototype as any).toJSON = function () { return this.toString(); };

if (import.meta.url === `file://${process.argv[1]}`) {
  main();
}

/**
 * Email jobs admin routes — xem lịch sử, retry failed jobs, preview template.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { retryEmailJob } from '../email/index.js';
import { allTemplates, render, getTemplate } from '../email/templates.js';

const ListQuery = z.object({
  q: z.string().max(200).optional(),
  status: z.enum(['queued','sending','sent','failed','skipped']).optional(),
  template: z.string().max(80).optional(),
  refType: z.string().max(32).optional(),
  refId:   z.string().uuid().optional(),
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

function serialize(j: Awaited<ReturnType<typeof prisma.emailJob.findFirst>>) {
  if (!j) return null;
  return {
    id: j.id,
    template: j.template,
    to_email: j.toEmail,
    to_name: j.toName,
    subject: j.subject,
    status: j.status,
    provider: j.provider,
    provider_id: j.providerId,
    attempt: j.attempt,
    last_error: j.lastError,
    sent_at: j.sentAt?.toISOString() ?? null,
    scheduled_at: j.scheduledAt?.toISOString() ?? null,
    ref_type: j.refType,
    ref_id: j.refId,
    created_at: j.createdAt.toISOString(),
    updated_at: j.updatedAt.toISOString(),
  };
}

export const emailJobRoutes: FastifyPluginAsync = async app => {

  app.get('/email-jobs', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async req => {
    const q = ListQuery.parse(req.query);
    const where = {
      ...(q.status && { status: q.status }),
      ...(q.template && { template: q.template }),
      ...(q.refType && { refType: q.refType }),
      ...(q.refId && { refId: q.refId }),
      ...(q.q && {
        OR: [
          { toEmail: { contains: q.q, mode: 'insensitive' as const } },
          { subject: { contains: q.q, mode: 'insensitive' as const } },
        ],
      }),
    };
    const [total, data] = await Promise.all([
      prisma.emailJob.count({ where }),
      prisma.emailJob.findMany({
        where, orderBy: { createdAt: 'desc' },
        skip: (q.page - 1) * q.limit, take: q.limit,
      }),
    ]);
    return { data: data.map(serialize), total, page: q.page, pageSize: q.limit };
  });

  app.get<{ Params: { id: string } }>('/email-jobs/:id', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async (req, reply) => {
    const j = await prisma.emailJob.findUnique({ where: { id: req.params.id } });
    if (!j) return reply.code(404).send({ error: 'not_found' });
    return { ...serialize(j), data: j.data };
  });

  app.post<{ Params: { id: string } }>('/email-jobs/:id/retry', {
    preHandler: [requireAuth, requirePermission('settings:write')],
  }, async (req, reply) => {
    try {
      const j = await retryEmailJob(req.params.id);
      return { job: serialize(j) };
    } catch (err) {
      reply.code(400);
      return { error: 'retry_failed', message: (err as Error).message };
    }
  });

  // Preview template với sample data — tiện cho email designer
  app.get('/email-templates', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async () => {
    return { templates: allTemplates() };
  });

  app.post<{ Params: { key: string } }>('/email-templates/:key/preview', {
    preHandler: [requireAuth, requirePermission('settings:read')],
  }, async (req, reply) => {
    const tpl = getTemplate(req.params.key);
    if (!tpl) return reply.code(404).send({ error: 'unknown_template' });
    const body = (req.body as Record<string, unknown>) || {};
    return render(req.params.key, body);
  });
};

/**
 * Public API của email module — các nơi khác chỉ import từ đây.
 *
 * Flow điển hình:
 *   await enqueueEmail({
 *     template: 'order.confirmation',
 *     toEmail: customer.email,
 *     data: { orderCode, total, ... },
 *     refType: 'order',
 *     refId: order.id,
 *   });
 */

import { prisma } from '../lib/prisma.js';
import { emailQueue } from './queue.js';
import { getTemplate } from './templates.js';

export { startEmailWorker, stopEmailWorker } from './worker.js';

interface EnqueueInput {
  template: string;
  toEmail: string;
  toName?: string | null;
  /** override subject nếu không muốn dùng template.subject() */
  subject?: string;
  data: Record<string, unknown>;
  /** delay ms trước khi gửi */
  delayMs?: number;
  /** link với entity (order, user, etc.) — để UI xem được lịch sử */
  refType?: string;
  refId?: string | null;
  /** idempotency key — nếu có cùng key, không enqueue lại */
  idempotencyKey?: string;
}

export async function enqueueEmail(input: EnqueueInput) {
  const tpl = getTemplate(input.template);
  if (!tpl) throw new Error(`Unknown email template: ${input.template}`);

  // Idempotency: nếu có key + đã sent trong 24h → skip
  if (input.idempotencyKey) {
    const existing = await prisma.emailJob.findFirst({
      where: { refType: input.refType, refId: input.refId, template: input.template },
      orderBy: { createdAt: 'desc' },
    });
    if (existing && existing.status === 'sent') return existing;
  }

  const subject = input.subject || tpl.subject(input.data);
  const record = await prisma.emailJob.create({
    data: {
      template: input.template,
      toEmail: input.toEmail,
      toName: input.toName ?? null,
      subject,
      data: (input.data ?? {}) as object,
      status: 'queued',
      scheduledAt: input.delayMs ? new Date(Date.now() + input.delayMs) : null,
      refType: input.refType ?? null,
      refId: input.refId ?? null,
    },
  });

  try {
    await emailQueue.add(
      `email:${input.template}`,
      { emailJobId: record.id },
      { delay: input.delayMs ?? 0 },
    );
  } catch (err) {
    // Nếu enqueue thất bại (Redis down) → đánh dấu failed để admin retry
    await prisma.emailJob.update({
      where: { id: record.id },
      data: { status: 'failed', lastError: `enqueue: ${(err as Error).message}` },
    });
    throw err;
  }

  return record;
}

/** Manual retry — push lại job vào queue */
export async function retryEmailJob(jobId: string) {
  const job = await prisma.emailJob.findUnique({ where: { id: jobId } });
  if (!job) throw new Error('EmailJob not found');
  if (job.status === 'sent') return job;

  await prisma.emailJob.update({
    where: { id: jobId },
    data: { status: 'queued', lastError: null },
  });
  await emailQueue.add(`email:${job.template}:retry`, { emailJobId: job.id });
  return job;
}

