/**
 * Shipment routes.
 *
 * Public:
 *   POST /shipments/webhook/:provider    — IPN từ carrier
 *   GET  /shipments/track/:trackingCode  — public track (không cần auth, rate-limited global)
 *
 * Authenticated:
 *   GET   /shipments                 — list (admin)
 *   GET   /shipments/:id             — detail
 *   POST  /shipments                 — create shipment cho 1 order
 *   POST  /shipments/:id/cancel      — huỷ
 *   GET   /shipping/providers        — list provider khả dụng
 *   POST  /shipping/quote            — quote phí (không tạo đơn)
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import { prisma } from '../lib/prisma.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { availableShippingProviders, getShippingProvider } from '../shipping/registry.js';
import { createShipment, applyWebhook, validNextStatuses } from '../shipping/service.js';

const ListQuery = z.object({
  orderId: z.string().uuid().optional(),
  status:  z.enum(['created','ready_to_pick','picked','in_transit','delivered','failed','returning','returned','cancelled']).optional(),
  provider: z.enum(['manual','ghn','ghtk','vnpost']).optional(),
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

const CreateBody = z.object({
  orderId:  z.string().uuid(),
  provider: z.enum(['manual','ghn','ghtk','vnpost']),
  weightGram: z.coerce.number().int().positive().optional(),
  lengthCm: z.coerce.number().int().positive().optional(),
  widthCm:  z.coerce.number().int().positive().optional(),
  heightCm: z.coerce.number().int().positive().optional(),
  codAmount: z.coerce.number().int().nonnegative().optional(),
  note: z.string().max(500).optional(),
}).strict();

const QuoteBody = CreateBody.omit({ orderId: true, note: true }).extend({
  shipAddress: z.object({
    province: z.string(), district: z.string().optional(), ward: z.string().optional(),
  }),
  pickupAddress: z.object({
    province: z.string().optional(), district: z.string().optional(),
  }).optional(),
  items: z.array(z.object({
    name: z.string(), qty: z.coerce.number().int().positive(), price: z.coerce.number().int().nonnegative(),
  })).min(1),
});

function serialize(s: Awaited<ReturnType<typeof prisma.shipment.findFirst>>) {
  if (!s) return null;
  return {
    id: s.id,
    order_id: s.orderId,
    provider: s.provider,
    tracking_code: s.trackingCode,
    status: s.status,
    shipping_fee: Number(s.shippingFee),
    weight_gram: s.weightGram,
    length_cm: s.lengthCm, width_cm: s.widthCm, height_cm: s.heightCm,
    label_url: s.labelUrl,
    picked_at: s.pickedAt?.toISOString() ?? null,
    delivered_at: s.deliveredAt?.toISOString() ?? null,
    error_code: s.errorCode, error_message: s.errorMessage,
    created_at: s.createdAt.toISOString(),
    updated_at: s.updatedAt.toISOString(),
    valid_next: validNextStatuses(s.status),
  };
}

export const shipmentRoutes: FastifyPluginAsync = async app => {

  // ─── Public: providers ─
  app.get('/shipping/providers', async () => ({ available: availableShippingProviders() }));

  // ─── Public: quote (không cần auth để FE checkout tính phí) ─
  app.post('/shipping/quote', async req => {
    const body = QuoteBody.parse(req.body);
    const adapter = getShippingProvider(body.provider);
    if (!adapter.quote) return { fee: 0, raw: { error: 'provider không hỗ trợ quote' } };
    const r = await adapter.quote({
      shipmentId: 'quote-only',
      orderCode: 'quote-only',
      shipAddress: {
        fullName: '', phone: '', line1: '',
        province: body.shipAddress.province,
        district: body.shipAddress.district,
        ward: body.shipAddress.ward,
      },
      pickupAddress: body.pickupAddress
        ? { fullName: '', phone: '', line1: '', province: body.pickupAddress.province ?? '', district: body.pickupAddress.district }
        : undefined,
      items: body.items.map(i => ({ name: i.name, qty: i.qty, price: i.price })),
      weightGram: body.weightGram ?? 500,
      lengthCm: body.lengthCm, widthCm: body.widthCm, heightCm: body.heightCm,
    });
    return r;
  });

  // ─── Public: track ─
  app.get<{ Params: { trackingCode: string } }>('/shipments/track/:trackingCode', async (req, reply) => {
    const s = await prisma.shipment.findFirst({
      where: { trackingCode: req.params.trackingCode },
      include: { events: { orderBy: { createdAt: 'desc' }, take: 20 } },
    });
    if (!s) return reply.code(404).send({ error: 'not_found' });
    return {
      tracking_code: s.trackingCode,
      provider: s.provider,
      status: s.status,
      events: s.events.map(e => ({
        status: e.toStatus, from: e.fromStatus, location: e.location, at: e.createdAt.toISOString(),
      })),
    };
  });

  // ─── Public: webhook ─
  app.post<{ Params: { provider: string } }>('/shipments/webhook/:provider', async (req, reply) => {
    const providerKey = req.params.provider as 'ghn' | 'ghtk' | 'manual' | 'vnpost';
    if (!['ghn','ghtk','vnpost'].includes(providerKey)) {
      return reply.code(400).send({ error: 'invalid_provider' });
    }
    const result = await applyWebhook(providerKey, {
      payload: (req.body ?? req.query) as Record<string, unknown>,
      headers: req.headers as Record<string, string | undefined>,
    }, req.id);
    if (!result.ok) return reply.code(400).send({ error: 'verify_failed', reason: result.error ?? 'unknown' });
    return reply.code(204).send();
  });

  // ─── Authenticated: list ─
  app.get('/shipments', { preHandler: [requireAuth, requirePermission('orders:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where = {
      ...(q.orderId  && { orderId: q.orderId }),
      ...(q.status   && { status: q.status }),
      ...(q.provider && { provider: q.provider }),
    };
    const [total, data] = await Promise.all([
      prisma.shipment.count({ where }),
      prisma.shipment.findMany({
        where, orderBy: { createdAt: 'desc' },
        skip: (q.page - 1) * q.limit, take: q.limit,
      }),
    ]);
    return { data: data.map(serialize), total, page: q.page, pageSize: q.limit };
  });

  // ─── Authenticated: detail ─
  app.get<{ Params: { id: string } }>('/shipments/:id', {
    preHandler: [requireAuth, requirePermission('orders:read')],
  }, async (req, reply) => {
    const s = await prisma.shipment.findUnique({
      where: { id: req.params.id },
      include: { events: { orderBy: { createdAt: 'asc' } } },
    });
    if (!s) return reply.code(404).send({ error: 'not_found' });
    return {
      ...serialize(s),
      events: s.events.map(e => ({
        id: e.id, kind: e.kind,
        from_status: e.fromStatus, to_status: e.toStatus,
        location: e.location, payload: e.payload,
        created_at: e.createdAt.toISOString(),
      })),
    };
  });

  // ─── Authenticated: create ─
  app.post('/shipments', { preHandler: [requireAuth, requirePermission('orders:write')] }, async (req, reply) => {
    const body = CreateBody.parse(req.body);
    try {
      const r = await createShipment({
        ...body,
        actor: { id: req.auth?.user.id ?? null, email: req.auth?.user.email ?? null, ip: req.ip, ua: req.headers['user-agent'] ?? null },
        requestId: req.id,
      });
      return { shipment: serialize(r.shipment) };
    } catch (err) {
      reply.code(400);
      return { error: 'create_failed', message: (err as Error).message };
    }
  });

  // ─── Authenticated: cancel ─
  app.post<{ Params: { id: string } }>('/shipments/:id/cancel', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const s = await prisma.shipment.findUnique({ where: { id: req.params.id } });
    if (!s) return reply.code(404).send({ error: 'not_found' });
    if (!validNextStatuses(s.status).includes('cancelled')) {
      return reply.code(400).send({ error: 'invalid_transition', from: s.status });
    }
    const adapter = getShippingProvider(s.provider);
    if (adapter.cancel && s.trackingCode) {
      try { await adapter.cancel(s.trackingCode); } catch { /* ignore carrier fail */ }
    }
    const updated = await prisma.$transaction(async tx => {
      const u = await tx.shipment.update({
        where: { id: s.id }, data: { status: 'cancelled' },
      });
      await tx.shipmentEvent.create({
        data: {
          shipmentId: s.id, kind: 'status_change',
          fromStatus: s.status, toStatus: 'cancelled',
          payload: { by: req.auth?.user.email ?? null },
        },
      });
      return u;
    });
    return { shipment: serialize(updated) };
  });
};

