/**
 * Shipping service — orchestrator cho Shipment DB state + provider API.
 */

import type { Prisma, ShipmentStatus, ShippingProvider } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { enqueueEmail } from '../email/index.js';
import { getShippingProvider } from './registry.js';
import type { WebhookInput } from './types.js';

interface CreateShipmentArgs {
  orderId: string;
  provider: ShippingProvider;
  weightGram?: number;
  lengthCm?: number;
  widthCm?: number;
  heightCm?: number;
  codAmount?: number;
  note?: string;
  actor?: { id: string | null; email: string | null; ip: string | null; ua: string | null };
  requestId?: string;
}

// Chuyển trạng thái hợp lệ (soft guard — carrier có thể skip step)
const TRANSITIONS: Record<ShipmentStatus, ShipmentStatus[]> = {
  created:       ['ready_to_pick', 'cancelled'],
  ready_to_pick: ['picked', 'cancelled'],
  picked:        ['in_transit', 'returning'],
  in_transit:    ['delivered', 'failed', 'returning'],
  delivered:     ['returning'],
  failed:        ['returning', 'in_transit'],
  returning:     ['returned', 'in_transit'],
  returned:      [],
  cancelled:     [],
};

export async function createShipment(args: CreateShipmentArgs) {
  const order = await prisma.order.findUnique({
    where: { id: args.orderId },
    include: { items: true, customer: true },
  });
  if (!order) throw new Error('Order not found');
  if (order.status === 'cancelled' || order.status === 'returned') {
    throw new Error('Không thể tạo vận đơn cho đơn đã huỷ/hoàn');
  }

  // Chỉ cho 1 shipment active / order (MVP). Nếu cần nhiều package → bỏ guard này.
  const existing = await prisma.shipment.findFirst({
    where: {
      orderId: order.id,
      status: { notIn: ['cancelled', 'returned', 'failed'] },
    },
  });
  if (existing) throw new Error('Order đã có shipment đang hoạt động');

  const adapter = getShippingProvider(args.provider);
  const shipAddr = order.shippingAddress as {
    fullName: string; phone: string; line1: string; province: string;
    ward?: string; district?: string; postalCode?: string;
  };

  // Tạo bản ghi Shipment trước (status=created) để có id
  const shipment = await prisma.shipment.create({
    data: {
      orderId: order.id,
      provider: args.provider,
      status: 'created',
      shippingFee: order.shippingFee,
      weightGram: args.weightGram ?? null,
      lengthCm: args.lengthCm ?? null,
      widthCm:  args.widthCm ?? null,
      heightCm: args.heightCm ?? null,
      shipAddress: shipAddr as unknown as Prisma.InputJsonValue,
    },
  });

  let result;
  try {
    result = await adapter.createShipment({
      shipmentId: shipment.id,
      orderCode: order.code,
      shipAddress: shipAddr,
      items: order.items.map(i => ({
        name: i.nameSnapshot, qty: i.qty, price: Number(i.priceUnit),
      })),
      weightGram: args.weightGram ?? order.items.reduce((s, i) => s + i.qty * 100, 0),
      lengthCm: args.lengthCm, widthCm: args.widthCm, heightCm: args.heightCm,
      codAmount: args.codAmount ?? (order.paymentMethod === 'cod' ? Number(order.total) : 0),
      note: args.note,
    });
  } catch (err) {
    const failed = await prisma.shipment.update({
      where: { id: shipment.id },
      data: { status: 'failed', errorMessage: (err as Error).message },
    });
    return { shipment: failed, order };
  }

  const updated = await prisma.$transaction(async tx => {
    const s = await tx.shipment.update({
      where: { id: shipment.id },
      data: {
        trackingCode: result.trackingCode,
        labelUrl: result.labelUrl,
        shippingFee: BigInt(result.shippingFee || 0),
        status: result.status,
        rawResponse: result.raw as Prisma.InputJsonValue,
      },
    });
    await tx.shipmentEvent.create({
      data: {
        shipmentId: s.id,
        kind: 'status_change',
        fromStatus: 'created',
        toStatus: result.status,
        payload: { action: 'createShipment', trackingCode: result.trackingCode },
      },
    });
    // Link vào order events
    await tx.orderEvent.create({
      data: {
        orderId: order.id,
        kind: 'shipping',
        note: `Đã tạo vận đơn ${args.provider}${result.trackingCode ? ` (${result.trackingCode})` : ''}`,
        metadata: { shipmentId: s.id, trackingCode: result.trackingCode },
      },
    });
    // Nếu cấu hình auto-move order → shipping khi shipment ready
    if (order.status === 'packing') {
      await tx.order.update({
        where: { id: order.id },
        data: { status: 'shipping', shippedAt: new Date() },
      });
    }
    await writeAudit({
      action: 'shipment.create',
      actorId: args.actor?.id ?? null,
      actorEmail: args.actor?.email ?? null,
      actorIp: args.actor?.ip ?? null,
      userAgent: args.actor?.ua ?? null,
      entity: 'shipment',
      entityId: s.id,
      diff: { after: { trackingCode: s.trackingCode, provider: s.provider } },
      requestId: args.requestId ?? null,
    }, tx);
    return s;
  });

  // Enqueue email "đơn đã đóng gói & gửi đi"
  if (order.customer?.email) {
    try {
      await enqueueEmail({
        template: 'order.shipped',
        toEmail: order.customer.email,
        toName: order.customer.name,
        data: {
          orderCode: order.code,
          trackingCode: updated.trackingCode,
          provider: updated.provider,
        },
        refType: 'order',
        refId: order.id,
      });
    } catch (err) {
      // eslint-disable-next-line no-console
      console.warn('[shipping] enqueue email failed', (err as Error).message);
    }
  }

  return { shipment: updated, order };
}

export async function applyWebhook(provider: ShippingProvider, input: WebhookInput, requestId?: string) {
  const adapter = getShippingProvider(provider);
  const outcome = await adapter.verifyWebhook(input);

  if (!outcome.signatureValid) return { ok: false as const, outcome };

  // Match bằng trackingCode hoặc shipmentId (client_order_code)
  type ShipmentRow = Awaited<ReturnType<typeof prisma.shipment.findUnique>>;
  let shipment: ShipmentRow = null;
  if (outcome.shipmentId) {
    shipment = await prisma.shipment.findUnique({ where: { id: outcome.shipmentId } });
  }
  if (!shipment && outcome.trackingCode) {
    shipment = await prisma.shipment.findFirst({ where: { trackingCode: outcome.trackingCode } });
  }
  if (!shipment) return { ok: false as const, outcome, error: 'shipment_not_found' as const };
  const sh = shipment; // giữ narrow

  const from = sh.status;
  const to = outcome.status;

  if (from === to) {
    // No-op — vẫn ghi event để audit
    await prisma.shipmentEvent.create({
      data: {
        shipmentId: sh.id, kind: 'webhook',
        fromStatus: from, toStatus: to,
        location: outcome.location ?? null,
        payload: outcome.raw as Prisma.InputJsonValue,
      },
    });
    return { ok: true as const, outcome, shipment: sh, alreadyApplied: true };
  }

  const updated = await prisma.$transaction(async tx => {
    const s = await tx.shipment.update({
      where: { id: sh.id },
      data: {
        status: to,
        pickedAt: to === 'picked' ? new Date() : sh.pickedAt,
        deliveredAt: to === 'delivered' ? new Date() : sh.deliveredAt,
      },
    });
    await tx.shipmentEvent.create({
      data: {
        shipmentId: s.id, kind: 'webhook',
        fromStatus: from, toStatus: to,
        location: outcome.location ?? null,
        payload: outcome.raw as Prisma.InputJsonValue,
      },
    });
    // Sync Order.status theo shipping milestone
    if (to === 'delivered') {
      await tx.order.update({
        where: { id: s.orderId },
        data: { status: 'delivered', deliveredAt: new Date() },
      });
      await tx.orderEvent.create({
        data: { orderId: s.orderId, kind: 'status_change', fromState: 'shipping', toState: 'delivered', note: `Giao thành công — ${provider}` },
      });
    } else if (to === 'in_transit' || to === 'picked') {
      await tx.order.updateMany({
        where: { id: s.orderId, status: { in: ['packing', 'confirmed'] } },
        data: { status: 'shipping', shippedAt: new Date() },
      });
    }
    await writeAudit({
      action: `shipment.webhook.${to}`,
      entity: 'shipment', entityId: s.id,
      diff: { before: { status: from }, after: { status: to } },
      requestId: requestId ?? null,
    }, tx);
    return s;
  });

  // Email khi delivered
  if (to === 'delivered') {
    const order = await prisma.order.findUnique({ where: { id: updated.orderId }, include: { customer: true } });
    if (order?.customer?.email) {
      try {
        await enqueueEmail({
          template: 'order.delivered',
          toEmail: order.customer.email,
          toName: order.customer.name,
          data: { orderCode: order.code, trackingCode: updated.trackingCode },
          refType: 'order', refId: order.id,
        });
      } catch { /* ignore */ }
    }
  }

  return { ok: true, outcome, shipment: updated };
}

/** Bảng NEXT để FE hiển thị action hợp lệ */
export function validNextStatuses(s: ShipmentStatus): ShipmentStatus[] {
  return TRANSITIONS[s] ?? [];
}

