/**
 * Inventory — cái nhìn tồn kho gộp variant + adjust endpoint ghi InventoryMovement.
 * Read: overview per-product tính state out/low/ok.
 * Write: adjust(productId, variantId?, delta, reason, note)
 *        set(productId, variantId, stock)
 *        bulk restock cộng N vào toàn bộ SKU.
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';

const ListQuery = z.object({
  q: z.string().max(200).optional(),
  state: z.enum(['out', 'low', 'ok']).optional(),
  category: z.string().max(60).optional(),
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(200).default(50),
});

const AdjustBody = z.object({
  productId: z.string().uuid(),
  variantId: z.string().uuid().nullable().optional(),
  delta: z.coerce.number().int(),
  reason: z.enum(['sale', 'return', 'adjust', 'restock', 'transfer', 'damage']).default('adjust'),
  note: z.string().max(500).optional(),
}).strict();

const SetBody = z.object({
  productId: z.string().uuid(),
  variantId: z.string().uuid().nullable().optional(),
  stock: z.coerce.number().int().nonnegative(),
  reason: z.enum(['sale', 'return', 'adjust', 'restock', 'transfer', 'damage']).default('adjust'),
  note: z.string().max(500).optional(),
}).strict();

const BulkRestockBody = z.object({
  qty: z.coerce.number().int().positive(),
  categoryId: z.string().uuid().optional(),
}).strict();

// Map reason → Prisma enum (vì 'return' clash keyword JS)
function mapReason(r: string): 'sale' | 'return_' | 'adjust' | 'restock' | 'transfer' | 'damage' {
  return r === 'return' ? 'return_' : (r as any);
}

export const inventoryRoutes: FastifyPluginAsync = async app => {
  // GET /inventory — overview
  app.get('/inventory', { preHandler: [requireAuth, requirePermission('inventory:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where: Prisma.ProductWhereInput = {
      deletedAt: null,
      ...(q.q && {
        OR: [
          { name: { contains: q.q, mode: 'insensitive' } },
          { code: { contains: q.q, mode: 'insensitive' } },
        ],
      }),
      ...(q.category && { category: { slug: q.category } }),
    };
    const products = await prisma.product.findMany({
      where,
      include: { variants: true, category: true },
      orderBy: { updatedAt: 'desc' },
    });

    let items = products.map(p => {
      const stock = p.variants.reduce((s, v) => s + v.stock, 0);
      const state: 'ok' | 'low' | 'out' = stock === 0 ? 'out' : stock <= p.lowStockThreshold ? 'low' : 'ok';
      return {
        id: p.id,
        code: p.code,
        name: p.name,
        category: p.category?.name ?? null,
        stock,
        low_stock: p.lowStockThreshold,
        state,
        status: p.status,
        variants: p.variants.map(v => ({ id: v.id, sku_suffix: v.skuSuffix, stock: v.stock })),
      };
    });
    if (q.state) items = items.filter(x => x.state === q.state);

    const summary = {
      total: items.length,
      out: items.filter(x => x.state === 'out').length,
      low: items.filter(x => x.state === 'low').length,
      ok:  items.filter(x => x.state === 'ok').length,
      stock_total: items.reduce((s, x) => s + x.stock, 0),
    };

    const start = (q.page - 1) * q.limit;
    const slice = items.slice(start, start + q.limit);
    return { data: slice, total: items.length, page: q.page, pageSize: q.limit, summary };
  });

  // POST /inventory/adjust
  app.post('/inventory/adjust', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req, reply) => {
    const body = AdjustBody.parse(req.body);
    const res = await prisma.$transaction(async tx => {
      // Nếu có variantId, cập nhật variant; nếu không, cập nhật variant đầu tiên.
      let variant;
      if (body.variantId) {
        variant = await tx.productVariant.findFirst({ where: { id: body.variantId, productId: body.productId } });
      } else {
        variant = await tx.productVariant.findFirst({ where: { productId: body.productId }, orderBy: { position: 'asc' } });
      }
      if (!variant) { reply.code(404); throw new Error('Variant not found'); }

      const before = variant.stock;
      const after = Math.max(0, before + body.delta);

      await tx.productVariant.update({ where: { id: variant.id }, data: { stock: after } });

      await tx.inventoryMovement.create({
        data: {
          productId: body.productId,
          variantId: variant.id,
          delta: after - before,
          reason: mapReason(body.reason),
          note: body.note ?? null,
          actorId: req.auth!.user.id,
        },
      });

      await writeAudit({
        action: 'inventory.adjust',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'product', entityId: body.productId,
        diff: { before: { stock: before }, after: { stock: after }, reason: body.reason, note: body.note },
        requestId: req.id,
      }, tx);

      return { before, after, variant_id: variant.id };
    });
    return res;
  });

  // POST /inventory/set
  app.post('/inventory/set', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req, reply) => {
    const body = SetBody.parse(req.body);
    const res = await prisma.$transaction(async tx => {
      let variant;
      if (body.variantId) variant = await tx.productVariant.findFirst({ where: { id: body.variantId, productId: body.productId } });
      else variant = await tx.productVariant.findFirst({ where: { productId: body.productId }, orderBy: { position: 'asc' } });
      if (!variant) { reply.code(404); throw new Error('Variant not found'); }

      const before = variant.stock;
      const after = body.stock;
      await tx.productVariant.update({ where: { id: variant.id }, data: { stock: after } });
      await tx.inventoryMovement.create({
        data: {
          productId: body.productId, variantId: variant.id,
          delta: after - before, reason: mapReason(body.reason),
          note: body.note ?? `set to ${after}`,
          actorId: req.auth!.user.id,
        },
      });
      await writeAudit({
        action: 'inventory.set',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'product', entityId: body.productId,
        diff: { before: { stock: before }, after: { stock: after } },
        requestId: req.id,
      }, tx);
      return { before, after, variant_id: variant.id };
    });
    return res;
  });

  // POST /inventory/restock-bulk — cộng N cho MỌI variant
  app.post('/inventory/restock-bulk', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req) => {
    const body = BulkRestockBody.parse(req.body);
    const variants = await prisma.productVariant.findMany({
      where: body.categoryId ? { product: { categoryId: body.categoryId } } : {},
      select: { id: true, productId: true },
    });

    await prisma.$transaction(async tx => {
      for (const v of variants) {
        await tx.productVariant.update({ where: { id: v.id }, data: { stock: { increment: body.qty } } });
        await tx.inventoryMovement.create({
          data: {
            productId: v.productId, variantId: v.id,
            delta: body.qty, reason: 'restock',
            note: `Bulk restock +${body.qty}`, actorId: req.auth!.user.id,
          },
        });
      }
      await writeAudit({
        action: 'inventory.bulk.restock',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'product',
        diff: { after: { qtyAdded: body.qty, variantCount: variants.length } },
        requestId: req.id,
      }, tx);
    });

    return { affected: variants.length, qty_added: body.qty };
  });

  // GET /inventory/movements?productId=
  app.get('/inventory/movements', { preHandler: [requireAuth, requirePermission('inventory:read')] }, async req => {
    const q = z.object({
      productId: z.string().uuid().optional(),
      limit: z.coerce.number().int().min(1).max(200).default(50),
    }).parse(req.query);
    const rows = await prisma.inventoryMovement.findMany({
      where: q.productId ? { productId: q.productId } : {},
      orderBy: { createdAt: 'desc' },
      take: q.limit,
    });
    return {
      data: rows.map(r => ({
        id: r.id, product_id: r.productId, variant_id: r.variantId,
        delta: r.delta, reason: r.reason, note: r.note,
        actor_id: r.actorId, order_id: r.orderId,
        created_at: r.createdAt.toISOString(),
      })),
    };
  });
};

