  // GET /inventory/movements?productId=&reason=&refType=&from=&to=
  app.get('/inventory/movements', { preHandler: [requireAuth, requirePermission('inventory:read')] }, async req => {
    const q = z.object({
      productId: z.string().uuid().optional(),
      variantId: z.string().uuid().optional(),
      reason: z.string().optional(),
      refType: z.string().optional(),
      from: z.coerce.date().optional(),
      to: z.coerce.date().optional(),
      page: z.coerce.number().int().min(1).default(1),
      limit: z.coerce.number().int().min(1).max(200).default(50),
    }).parse(req.query);

    const where: Prisma.InventoryMovementWhereInput = {
      ...(q.productId && { productId: q.productId }),
      ...(q.variantId && { variantId: q.variantId }),
      ...(q.reason && { reason: mapReason(q.reason) }),
      ...(q.refType && { refType: q.refType }),
      ...((q.from || q.to) && {
        createdAt: { ...(q.from && { gte: q.from }), ...(q.to && { lte: q.to }) },
      }),
    };
    const [total, rows] = await Promise.all([
      prisma.inventoryMovement.count({ where }),
      prisma.inventoryMovement.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        skip: (q.page - 1) * q.limit,
        take: q.limit,
        include: { product: { select: { code: true, name: true } }, variant: { select: { skuSuffix: true } } },
      }),
    ]);
    return {
      data: rows.map(r => ({
        id: r.id,
        product_id: r.productId, product_code: r.product?.code, product_name: r.product?.name,
        variant_id: r.variantId, sku_suffix: r.variant?.skuSuffix ?? null,
        delta: r.delta, reason: r.reason, note: r.note,
        unit_cost: r.unitCost !== null && r.unitCost !== undefined ? Number(r.unitCost) : null,
        ref_type: r.refType, ref_id: r.refId,
        actor_id: r.actorId, order_id: r.orderId,
        created_at: r.createdAt.toISOString(),
      })),
      total, page: q.page, pageSize: q.limit,
    };
  });

  // POST /inventory/receive — nhập 1 line (hoặc 1 SKU)
  app.post('/inventory/receive', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req, reply) => {
    const body = ReceiveBody.parse(req.body);
    const refId = body.poNumber ?? null;

    const result = await prisma.$transaction(async tx => {
      // Xác định variant
      let variant;
      if (body.variantId) {
        variant = await tx.productVariant.findFirst({ where: { id: body.variantId, productId: body.productId } });
      } else {
        variant = await tx.productVariant.findFirst({ where: { productId: body.productId }, orderBy: { position: 'asc' } });
      }
      if (!variant) { reply.code(404); throw new Error('Variant not found'); }

      await receiveStock({
        productId: body.productId,
        variantId: variant.id,
        qty: body.qty,
        unitCost: BigInt(body.unitCost),
        note: body.note ?? `Nhập ${body.qty} @ ${body.unitCost}/sp${body.supplier ? ` từ ${body.supplier}` : ''}`,
        refType: 'po',
        refId,
        actorId: req.auth!.user.id,
      }, tx);

      await writeAudit({
        action: 'inventory.receive',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'product', entityId: body.productId,
        diff: { after: { qty: body.qty, unitCost: body.unitCost, poNumber: body.poNumber, supplier: body.supplier } },
        requestId: req.id,
      }, tx);

      const after = await tx.productVariant.findUnique({ where: { id: variant.id } });
      return { variant_id: variant.id, stock: after?.stock ?? 0, avg_cost: after?.avgCost ? Number(after.avgCost) : null };
    });
    return result;
  });

  // POST /inventory/receive-bulk — nhập nhiều SKU trong 1 PO
  app.post('/inventory/receive-bulk', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req, reply) => {
    const body = ReceiveBulkBody.parse(req.body);
    const refId = body.poNumber ?? null;
    let affected = 0;

    await prisma.$transaction(async tx => {
      for (const line of body.lines) {
        let variant;
        if (line.variantId) {
          variant = await tx.productVariant.findFirst({ where: { id: line.variantId, productId: line.productId } });
        } else {
          variant = await tx.productVariant.findFirst({ where: { productId: line.productId }, orderBy: { position: 'asc' } });
        }
        if (!variant) continue;
        await receiveStock({
          productId: line.productId,
          variantId: variant.id,
          qty: line.qty,
          unitCost: BigInt(line.unitCost),
          note: body.note ?? `PO ${body.poNumber ?? ''} nhập ${line.qty}`,
          refType: 'po',
          refId,
          actorId: req.auth!.user.id,
        }, tx);
        affected++;
      }
      await writeAudit({
        action: 'inventory.receive.bulk',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'product',
        diff: { after: { affected, poNumber: body.poNumber, supplier: body.supplier } },
        requestId: req.id,
      }, tx);
    });
    if (affected === 0) { reply.code(400); return { error: 'no_lines_matched' }; }
    return { affected, po_number: body.poNumber };
  });

  // POST /inventory/count — kiểm kê thực tế, tạo movement bù chênh lệch
  app.post('/inventory/count', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req, reply) => {
    const body = CountBody.parse(req.body);
    const res = await prisma.$transaction(async tx => {
      let variant;
      if (body.variantId) {
        variant = await tx.productVariant.findFirst({ where: { id: body.variantId, productId: body.productId } });
      } else {
        variant = await tx.productVariant.findFirst({ where: { productId: body.productId }, orderBy: { position: 'asc' } });
      }
      if (!variant) { reply.code(404); throw new Error('Variant not found'); }

      const before = variant.stock;
      const after = body.counted;
      const delta = after - before;
      if (delta === 0) return { before, after, delta, variant_id: variant.id };

      await tx.productVariant.update({ where: { id: variant.id }, data: { stock: after } });
      await tx.inventoryMovement.create({
        data: {
          productId: body.productId, variantId: variant.id,
          delta, reason: 'count',
          note: body.note ?? `Kiểm kê: ${before} → ${after}`,
          actorId: req.auth!.user.id,
          refType: 'count',
        },
      });
      await writeAudit({
        action: 'inventory.count',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'product', entityId: body.productId,
        diff: { before: { stock: before }, after: { stock: after }, delta },
        requestId: req.id,
      }, tx);
      return { before, after, delta, variant_id: variant.id };
    });
    return res;
  });
};

