/**
 * Orders — list, detail, create, admin-create (full), update status, payment, event, quote/draft.
 *
 * State machine:
 *   draft → quote → pending → confirmed → packing → shipping → delivered
 *   any (≠ delivered) → cancelled
 *   delivered → returned (qua flow Returns)
 *
 * Inventory:
 *   pending|confirmed: reserve stock (khi order chuyển VÀO confirmed)
 *   shipping:          commit (stock -= qty, reserved -= qty)
 *   cancelled:         release (nếu đã reserve)
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { enqueueEmail } from '../email/index.js';
import { reserveStock, releaseStock, commitStock } from '../inventory/reservation.js';
import { recomputeCustomer, pointsEarnedFor } from '../customers/loyalty.js';

// ─── State machine ──────────────────────────────────────────────

const ORDER_STATUSES = [
  'draft', 'quote', 'pending', 'confirmed',
  'packing', 'shipping', 'delivered', 'returned', 'cancelled',
] as const;
type OrderStatus = typeof ORDER_STATUSES[number];

const TRANSITIONS: Record<OrderStatus, OrderStatus[]> = {
  draft:     ['quote', 'pending', 'cancelled'],
  quote:     ['pending', 'cancelled'],
  pending:   ['confirmed', 'cancelled'],
  confirmed: ['packing', 'cancelled'],
  packing:   ['shipping', 'cancelled'],
  shipping:  ['delivered', 'cancelled'],
  delivered: ['returned'],
  returned:  [],
  cancelled: [],
};

const SHIPPING_METHODS = ['standard','express','same_day','pickup'] as const;
const ORDER_SOURCES = ['web','admin','pos','phone','zalo','fb','tiktok','marketplace'] as const;

// ─── Schemas ────────────────────────────────────────────────────

const ListQuery = z.object({
  q:        z.string().max(200).optional(),
  status:   z.enum(ORDER_STATUSES).optional(),
  paymentStatus: z.enum(['pending', 'paid', 'refunded', 'failed']).optional(),
  paymentMethod: z.enum(['cod', 'vnpay', 'momo', 'bank_transfer']).optional(),
  source: z.enum(ORDER_SOURCES).optional(),
  customerId: z.string().uuid().optional(),
  from: z.coerce.date().optional(),
  to:   z.coerce.date().optional(),
  sort: z.enum(['placed-desc', 'placed-asc', 'total-desc', 'total-asc']).default('placed-desc'),
  page:  z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

const AddressSchema = z.object({
  fullName: z.string().min(1).max(120),
  phone:    z.string().min(6).max(20),
  line1:    z.string().min(1).max(200),
  ward:     z.string().max(100).optional(),
  district: z.string().max(100).optional(),
  province: z.string().min(1).max(100),
  postalCode: z.string().max(20).optional(),
  recipientName:  z.string().max(120).optional(),
  recipientPhone: z.string().max(20).optional(),
}).strict();

const OrderItemInput = z.object({
  productId: z.string().uuid(),
  variantId: z.string().uuid().nullable().optional(),
  qty: z.coerce.number().int().positive(),
  priceUnit: z.coerce.number().int().nonnegative(), // snapshot
  nameSnapshot: z.string().min(1).max(255),
}).strict();

const OrderCreateBody = z.object({
  customerId: z.string().uuid().nullable().optional(),
  paymentMethod: z.enum(['cod', 'vnpay', 'momo', 'bank_transfer']),
  items: z.array(OrderItemInput).min(1).max(200),
  shippingAddress: AddressSchema,
  billingAddress: AddressSchema.optional(),
  voucherCode: z.string().max(30).nullable().optional(),
  discountTotal: z.coerce.number().int().nonnegative().default(0),
  shippingFee: z.coerce.number().int().nonnegative().default(0),
  tax: z.coerce.number().int().nonnegative().default(0),
  shippingMethod: z.enum(SHIPPING_METHODS).default('standard'),
  giftWrap: z.boolean().default(false),
  giftWrapFee: z.coerce.number().int().nonnegative().default(0),
  giftMessage: z.string().max(500).optional(),
  notes: z.string().max(1000).nullable().optional(),           // customer-facing
  internalNote: z.string().max(2000).nullable().optional(),    // internal
  source: z.enum(ORDER_SOURCES).default('web'),
  channel: z.string().max(60).optional(),
  pointsUsed: z.coerce.number().int().nonnegative().default(0),
  status: z.enum(['draft','quote','pending']).default('pending'),   // cho phép tạo ở draft/quote
}).strict();

const CustomerInlineSchema = z.object({
  name:  z.string().min(1).max(120),
  phone: z.string().min(6).max(20),
  email: z.string().email().nullable().optional(),
}).strict();

// Admin-create: cho phép tạo customer inline (nếu không có customerId)
const AdminCreateBody = OrderCreateBody.omit({ source: true }).extend({
  customer: CustomerInlineSchema.optional(),  // tạo mới nếu customerId null
  saveAsAddress: z.boolean().default(true),   // có lưu shippingAddress vào CustomerAddress không
});

const StatusUpdateBody = z.object({
  status: z.enum(ORDER_STATUSES),
  note: z.string().max(500).optional(),
}).strict();

const PaymentUpdateBody = z.object({
  paymentStatus: z.enum(['pending', 'paid', 'refunded', 'failed']),
  note: z.string().max(500).optional(),
}).strict();

const EventBody = z.object({
  kind: z.enum(['note', 'payment', 'shipping', 'status_change', 'internal']),
  note: z.string().min(1).max(2000),
  metadata: z.record(z.unknown()).optional(),
}).strict();

// ─── Helpers ────────────────────────────────────────────────────

type OrderWithRelations = Prisma.OrderGetPayload<{
  include: {
    items: true;
    events: { orderBy: { createdAt: 'asc' } };
    customer: true;
  };
}>;

function serialize(o: OrderWithRelations) {
  return {
    id: o.id,
    code: o.code,
    customer_id: o.customerId,
    customer: o.customer ? {
      id: o.customer.id, name: o.customer.name,
      email: o.customer.email, phone: o.customer.phone,
      loyalty_tier: o.customer.loyaltyTier,
      segment: o.customer.segment,
    } : null,
    status: o.status,
    payment_status: o.paymentStatus,
    payment_method: o.paymentMethod,
    shipping_method: o.shippingMethod,
    source: o.source,
    channel: o.channel,
    subtotal: Number(o.subtotal),
    discount_total: Number(o.discountTotal),
    shipping_fee: Number(o.shippingFee),
    gift_wrap: o.giftWrap,
    gift_wrap_fee: Number(o.giftWrapFee),
    gift_message: o.giftMessage,
    tax: Number(o.tax),
    total: Number(o.total),
    shipping_address: o.shippingAddress,
    billing_address: o.billingAddress,
    voucher_code: o.voucherCode,
    notes: o.notes,
    internal_note: o.internalNote,
    points_earned: o.pointsEarned,
    points_used: o.pointsUsed,
    reserved_at: o.reservedAt?.toISOString() ?? null,
    placed_at: o.placedAt.toISOString(),
    paid_at: o.paidAt?.toISOString() ?? null,
    shipped_at: o.shippedAt?.toISOString() ?? null,
    delivered_at: o.deliveredAt?.toISOString() ?? null,
    cancelled_at: o.cancelledAt?.toISOString() ?? null,
    items: o.items.map(i => ({
      id: i.id,
      product_id: i.productId,
      variant_id: i.variantId,
      name_snapshot: i.nameSnapshot,
      price_unit: Number(i.priceUnit),
      qty: i.qty,
      subtotal: Number(i.subtotal),
    })),
    events: o.events.map(e => ({
      id: e.id, kind: e.kind,
      from_state: e.fromState, to_state: e.toState,
      note: e.note, actor_id: e.actorId, metadata: e.metadata,
      created_at: e.createdAt.toISOString(),
    })),
    valid_next: TRANSITIONS[o.status as OrderStatus] ?? [],
    created_at: o.createdAt.toISOString(),
    updated_at: o.updatedAt.toISOString(),
  };
}

function nextOrderCode(lastCode: string | null): string {
  const year = String(new Date().getFullYear()).slice(-2);
  if (!lastCode) return `DTX-${year}-00001`;
  const m = lastCode.match(/-(\d+)$/);
  const n = m ? Number(m[1]) + 1 : 1;
  return `DTX-${year}-${String(n).padStart(5, '0')}`;
}

/**
 * Tính lại totals từ voucher. Trả về discount absolute (VND).
 * Dùng cho cả web checkout và admin create.
 */
async function applyVoucher(code: string | null | undefined, subtotal: number, shippingFee: number, tx: Prisma.TransactionClient): Promise<{ discount: number; voucher: { code: string; type: string; value: number } | null; error: string | null }> {
  if (!code) return { discount: 0, voucher: null, error: null };
  const v = await tx.voucher.findUnique({ where: { code: code.toUpperCase() } });
  if (!v) return { discount: 0, voucher: null, error: 'voucher_not_found' };
  if (v.status !== 'active') return { discount: 0, voucher: null, error: `voucher_${v.status}` };
  if (v.startAt && v.startAt > new Date()) return { discount: 0, voucher: null, error: 'voucher_not_started' };
  if (v.endAt && v.endAt < new Date()) return { discount: 0, voucher: null, error: 'voucher_expired' };
  if (v.usageLimit && v.usedCount >= v.usageLimit) return { discount: 0, voucher: null, error: 'voucher_exhausted' };
  if (subtotal < Number(v.minOrder)) return { discount: 0, voucher: null, error: 'voucher_min_order_not_met' };

  let discount = 0;
  if (v.type === 'percent')  discount = Math.floor((subtotal * Number(v.value)) / 100);
  else if (v.type === 'amount')   discount = Number(v.value);
  else if (v.type === 'shipping') discount = Math.min(shippingFee, Number(v.value) || shippingFee);

  return {
    discount,
    voucher: { code: v.code, type: v.type, value: Number(v.value) },
    error: null,
  };
}

// ─── Plugin ─────────────────────────────────────────────────────

export const orderRoutes: FastifyPluginAsync = async app => {
  // GET /orders
  app.get('/orders', { preHandler: [requireAuth, requirePermission('orders:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where: Prisma.OrderWhereInput = {
      ...(q.q && {
        OR: [
          { code: { contains: q.q, mode: 'insensitive' } },
          { customer: { name: { contains: q.q, mode: 'insensitive' } } },
          { customer: { phone: { contains: q.q } } },
          { customer: { email: { contains: q.q, mode: 'insensitive' } } },
        ],
      }),
      ...(q.status && { status: q.status }),
      ...(q.paymentStatus && { paymentStatus: q.paymentStatus }),
      ...(q.paymentMethod && { paymentMethod: q.paymentMethod }),
      ...(q.source && { source: q.source }),
      ...(q.customerId && { customerId: q.customerId }),
      ...((q.from || q.to) && {
        placedAt: {
          ...(q.from && { gte: q.from }),
          ...(q.to   && { lte: q.to }),
        },
      }),
    };

    const orderBy: Prisma.OrderOrderByWithRelationInput = (() => {
      switch (q.sort) {
        case 'placed-asc':  return { placedAt: 'asc' };
        case 'total-desc':  return { total: 'desc' };
        case 'total-asc':   return { total: 'asc' };
        default:            return { placedAt: 'desc' };
      }
    })();

    const [total, data] = await Promise.all([
      prisma.order.count({ where }),
      prisma.order.findMany({
        where, orderBy,
        skip: (q.page - 1) * q.limit,
        take: q.limit,
        include: { items: true, events: { orderBy: { createdAt: 'asc' } }, customer: true },
      }),
    ]);

    return {
      data: data.map(serialize),
      total, page: q.page, pageSize: q.limit,
    };
  });

  // GET /orders/:id
  app.get<{ Params: { id: string } }>('/orders/:id', {
    preHandler: [requireAuth, requirePermission('orders:read')],
  }, async (req, reply) => {
    const o = await prisma.order.findUnique({
      where: { id: req.params.id },
      include: { items: true, events: { orderBy: { createdAt: 'asc' } }, customer: true },
    });
    if (!o) return reply.code(404).send({ error: 'not_found', requestId: req.id });
    return serialize(o);
  });

  // POST /orders — web checkout (giữ như cũ, có thêm field mới)
  app.post('/orders', { preHandler: [requireAuth, requirePermission('orders:write')] }, async (req, reply) => {
    const body = OrderCreateBody.parse(req.body);

    const created = await prisma.$transaction(async tx => {
      const subtotal = body.items.reduce((s, i) => s + i.priceUnit * i.qty, 0);
      const voucherApply = await applyVoucher(body.voucherCode, subtotal, body.shippingFee, tx);
      if (voucherApply.error) {
        reply.code(400);
        throw new Error(`Voucher: ${voucherApply.error}`);
      }
      const discount = Math.max(body.discountTotal, voucherApply.discount);
      const giftFee = body.giftWrap ? body.giftWrapFee : 0;
      const total = subtotal - discount + body.shippingFee + giftFee + body.tax;
      if (total < 0) {
        reply.code(400);
        throw new Error('Tổng đơn âm — kiểm tra giảm giá');
      }

      const last = await tx.order.findFirst({ orderBy: { createdAt: 'desc' }, select: { code: true } });
      const code = nextOrderCode(last?.code ?? null);

      const o = await tx.order.create({
        data: {
          code,
          customerId: body.customerId ?? null,
          paymentMethod: body.paymentMethod,
          status: body.status,
          subtotal: BigInt(subtotal),
          discountTotal: BigInt(discount),
          shippingFee: BigInt(body.shippingFee),
          giftWrapFee: BigInt(giftFee),
          tax: BigInt(body.tax),
          total: BigInt(total),
          shippingAddress: body.shippingAddress,
          billingAddress: body.billingAddress ?? null,
          voucherCode: voucherApply.voucher?.code ?? null,
          shippingMethod: body.shippingMethod,
          giftWrap: body.giftWrap,
          giftMessage: body.giftMessage ?? null,
          source: body.source,
          channel: body.channel ?? null,
          notes: body.notes ?? null,
          internalNote: body.internalNote ?? null,
          pointsUsed: body.pointsUsed,
          items: {
            create: body.items.map(i => ({
              productId: i.productId,
              variantId: i.variantId ?? null,
              nameSnapshot: i.nameSnapshot,
              priceUnit: BigInt(i.priceUnit),
              qty: i.qty,
              subtotal: BigInt(i.priceUnit * i.qty),
            })),
          },
          events: {
            create: [{
              kind: 'status_change', toState: body.status, actorId: req.auth!.user.id,
              note: 'Đơn được tạo',
            }],
          },
        },
        include: { items: true, events: true, customer: true },
      });

      // Nếu voucher áp dụng → tăng usedCount
      if (voucherApply.voucher) {
        await tx.voucher.update({
          where: { code: voucherApply.voucher.code },
          data: { usedCount: { increment: 1 } },
        });
      }

      await writeAudit({
        action: 'order.create',
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        actorIp: req.ip,
        entity: 'order', entityId: o.id,
        diff: { after: { code: o.code, total: Number(o.total), source: body.source } },
        requestId: req.id,
      }, tx);

      return o;
    });

    if (created.customer?.email && created.status !== 'draft' && created.status !== 'quote') {
      enqueueEmail({
        template: 'order.confirmation',
        toEmail: created.customer.email,
        toName: created.customer.name,
        data: {
          orderCode: created.code,
          customerName: created.customer.name,
          total: Number(created.total),
          paymentMethod: created.paymentMethod,
          trackingUrl: `https://detoxblanc.com/track?code=${created.code}`,
        },
        refType: 'order',
        refId: created.id,
      }).catch(err => req.log.warn({ err: err.message }, 'order.confirmation email enqueue failed'));
    }

    reply.code(201);
    return serialize(created);
  });

  // POST /orders/admin-create — tạo đơn thủ công (chuẩn POS/OMS)
  app.post('/orders/admin-create', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = AdminCreateBody.parse(req.body);

    const created = await prisma.$transaction(async tx => {
      // 1. Resolve customer
      let customerId = body.customerId ?? null;
      if (!customerId && body.customer) {
        // Tìm theo phone hoặc email — upsert
        const found = await tx.customer.findFirst({
          where: {
            OR: [
              ...(body.customer.phone ? [{ phone: body.customer.phone }] : []),
              ...(body.customer.email ? [{ email: body.customer.email }] : []),
            ],
          },
        });
        if (found) {
          customerId = found.id;
        } else {
          const fresh = await tx.customer.create({
            data: {
              name: body.customer.name,
              phone: body.customer.phone,
              email: body.customer.email ?? null,
              source: 'offline',
              segment: 'new_cus',
            },
          });
          customerId = fresh.id;
        }
      }

      // 2. Save address nếu bật
      if (customerId && body.saveAsAddress) {
        const already = await tx.customerAddress.findFirst({
          where: {
            customerId,
            phone: body.shippingAddress.phone,
            line1: body.shippingAddress.line1,
            province: body.shippingAddress.province,
          },
        });
        if (!already) {
          await tx.customerAddress.create({
            data: {
              customerId,
              fullName: body.shippingAddress.fullName,
              phone: body.shippingAddress.phone,
              recipientName: body.shippingAddress.recipientName ?? null,
              recipientPhone: body.shippingAddress.recipientPhone ?? null,
              line1: body.shippingAddress.line1,
              ward: body.shippingAddress.ward ?? null,
              district: body.shippingAddress.district ?? null,
              province: body.shippingAddress.province,
              postalCode: body.shippingAddress.postalCode ?? null,
              isDefault: false,
            },
          });
        }
      }

      // 3. Validate items — lấy giá hiện tại từ catalog nếu priceUnit == 0
      const enrichedItems = [];
      for (const i of body.items) {
        let price = i.priceUnit;
        let name  = i.nameSnapshot;
        if (!price || !name) {
          const v = i.variantId ? await tx.productVariant.findUnique({ where: { id: i.variantId }, include: { product: true } }) : null;
          const p = v?.product ?? await tx.product.findUnique({ where: { id: i.productId } });
          if (!p) throw new Error(`Product ${i.productId} không tồn tại`);
          price = price || Number(v?.price ?? p.price);
          name  = name  || p.name + (v?.size ? ` · ${v.size}` : '');
        }
        enrichedItems.push({ ...i, priceUnit: price, nameSnapshot: name });
      }

      const subtotal = enrichedItems.reduce((s, i) => s + i.priceUnit * i.qty, 0);
      const voucherApply = await applyVoucher(body.voucherCode, subtotal, body.shippingFee, tx);
      if (voucherApply.error) {
        reply.code(400);
        throw new Error(`Voucher: ${voucherApply.error}`);
      }
      const discount = Math.max(body.discountTotal, voucherApply.discount);
      const giftFee = body.giftWrap ? body.giftWrapFee : 0;
      const total = subtotal - discount + body.shippingFee + giftFee + body.tax;
      if (total < 0) {
        reply.code(400);
        throw new Error('Tổng đơn âm — kiểm tra giảm giá');
      }

      // 4. Generate code
      const last = await tx.order.findFirst({ orderBy: { createdAt: 'desc' }, select: { code: true } });
      const code = nextOrderCode(last?.code ?? null);

      // 5. Create order
      const o = await tx.order.create({
        data: {
          code,
          customerId,
          paymentMethod: body.paymentMethod,
          status: body.status,
          subtotal: BigInt(subtotal),
          discountTotal: BigInt(discount),
          shippingFee: BigInt(body.shippingFee),
          giftWrapFee: BigInt(giftFee),
          tax: BigInt(body.tax),
          total: BigInt(total),
          shippingAddress: body.shippingAddress,
          billingAddress: body.billingAddress ?? null,
          voucherCode: voucherApply.voucher?.code ?? null,
          shippingMethod: body.shippingMethod,
          giftWrap: body.giftWrap,
          giftMessage: body.giftMessage ?? null,
          source: 'admin',
          channel: body.channel ?? null,
          notes: body.notes ?? null,
          internalNote: body.internalNote ?? null,
          pointsUsed: body.pointsUsed,
          items: {
            create: enrichedItems.map(i => ({
              productId: i.productId,
              variantId: i.variantId ?? null,
              nameSnapshot: i.nameSnapshot,
              priceUnit: BigInt(i.priceUnit),
              qty: i.qty,
              subtotal: BigInt(i.priceUnit * i.qty),
            })),
          },
          events: {
            create: [{
              kind: 'status_change', toState: body.status, actorId: req.auth!.user.id,
              note: `Admin tạo đơn (${body.channel ?? 'direct'})`,
            }],
          },
        },
        include: { items: true, events: true, customer: true },
      });

      if (voucherApply.voucher) {
        await tx.voucher.update({
          where: { code: voucherApply.voucher.code },
          data: { usedCount: { increment: 1 } },
        });
      }

      await writeAudit({
        action: 'order.admin_create',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: o.id,
        diff: { after: { code: o.code, total: Number(o.total), customerId, status: o.status } },
        requestId: req.id,
      }, tx);

      return o;
    });

    // Email không gửi với draft/quote
    if (created.customer?.email && created.status === 'pending') {
      enqueueEmail({
        template: 'order.confirmation',
        toEmail: created.customer.email,
        toName: created.customer.name,
        data: {
          orderCode: created.code,
          customerName: created.customer.name,
          total: Number(created.total),
          paymentMethod: created.paymentMethod,
          trackingUrl: `https://detoxblanc.com/track?code=${created.code}`,
        },
        refType: 'order',
        refId: created.id,
      }).catch(err => req.log.warn({ err: err.message }, 'order.confirmation email enqueue failed'));
    }

    reply.code(201);
    return serialize(created);
  });

  // PATCH /orders/:id/status — có hook reservation/commit/release
  app.patch<{ Params: { id: string } }>('/orders/:id/status', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = StatusUpdateBody.parse(req.body);
    const id = req.params.id;
    const actorId = req.auth!.user.id;

    const { next, customerIdForRecompute } = await prisma.$transaction(async tx => {
      const o = await tx.order.findUnique({ where: { id }, include: { items: true } });
      if (!o) { reply.code(404); throw new Error('Order not found'); }

      const allowed = TRANSITIONS[o.status as OrderStatus] || [];
      if (o.status !== body.status && !allowed.includes(body.status)) {
        reply.code(409);
        throw new Error(`Không thể chuyển từ ${o.status} → ${body.status}`);
      }

      // Inventory side-effects
      const lines = o.items.map(i => ({
        productId: i.productId, variantId: i.variantId, qty: i.qty, orderId: o.id,
      }));

      // pending/draft/quote → confirmed: reserve
      if (body.status === 'confirmed' && !o.reservedAt) {
        await reserveStock(lines, actorId, tx);
      }
      // confirmed/packing → shipping: commit (stock -= qty, reserved -= qty)
      if (body.status === 'shipping' && o.reservedAt) {
        await commitStock(lines, actorId, tx);
      }
      // any reserved → cancelled: release
      if (body.status === 'cancelled' && o.reservedAt && !o.shippedAt) {
        await releaseStock(lines, actorId, tx);
      }

      const patch: Prisma.OrderUpdateInput = { status: body.status };
      if (body.status === 'confirmed' && !o.reservedAt)  patch.reservedAt  = new Date();
      if (body.status === 'shipping'  && !o.shippedAt)   patch.shippedAt   = new Date();
      if (body.status === 'delivered' && !o.deliveredAt) patch.deliveredAt = new Date();
      if (body.status === 'cancelled' && !o.cancelledAt) patch.cancelledAt = new Date();

      // Khi delivered → earn loyalty points
      let pointsEarnedPatch: number | undefined;
      if (body.status === 'delivered' && o.customerId && o.pointsEarned === 0) {
        pointsEarnedPatch = pointsEarnedFor(o.total);
        patch.pointsEarned = pointsEarnedPatch;
      }

      const next = await tx.order.update({
        where: { id },
        data: {
          ...patch,
          events: {
            create: {
              kind: 'status_change',
              fromState: o.status,
              toState: body.status,
              actorId,
              note: body.note ?? null,
            },
          },
        },
        include: { items: true, events: { orderBy: { createdAt: 'asc' } }, customer: true },
      });

      await writeAudit({
        action: `order.status.${body.status}`,
        actorId, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: id,
        diff: { before: { status: o.status }, after: { status: body.status } },
        requestId: req.id,
      }, tx);

      return { next, customerIdForRecompute: body.status === 'delivered' || body.status === 'cancelled' ? o.customerId : null };
    });

    // Recompute loyalty sau transaction
    if (customerIdForRecompute) {
      recomputeCustomer(customerIdForRecompute).catch(err => {
        req.log.warn({ err: err.message, customerId: customerIdForRecompute }, 'loyalty recompute failed');
      });
    }

    // Email
    const EMAIL_TEMPLATE: Record<string, string> = {
      shipping:  'order.shipped',
      delivered: 'order.delivered',
    };
    const tpl = EMAIL_TEMPLATE[body.status];
    if (tpl && next.customer?.email) {
      enqueueEmail({
        template: tpl,
        toEmail: next.customer.email,
        toName: next.customer.name,
        data: {
          orderCode: next.code,
          status: body.status,
          note: body.note ?? '',
          provider: 'Detoxblanc',
          trackingCode: null,
        },
        refType: 'order', refId: next.id,
      }).catch(err => req.log.warn({ err: err.message }, `${tpl} email enqueue failed`));
    }

    return serialize(next);
  });

  // PATCH /orders/:id/payment
  app.patch<{ Params: { id: string } }>('/orders/:id/payment', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = PaymentUpdateBody.parse(req.body);
    const id = req.params.id;

    const updated = await prisma.$transaction(async tx => {
      const o = await tx.order.findUnique({ where: { id } });
      if (!o) { reply.code(404); throw new Error('Order not found'); }

      const patch: Prisma.OrderUpdateInput = { paymentStatus: body.paymentStatus };
      if (body.paymentStatus === 'paid' && !o.paidAt) patch.paidAt = new Date();

      const next = await tx.order.update({
        where: { id },
        data: {
          ...patch,
          events: { create: { kind: 'payment', actorId: req.auth!.user.id, note: body.note ?? `payment → ${body.paymentStatus}` } },
        },
        include: { items: true, events: { orderBy: { createdAt: 'asc' } }, customer: true },
      });

      await writeAudit({
        action: `order.payment.${body.paymentStatus}`,
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: id,
        diff: { before: { paymentStatus: o.paymentStatus }, after: { paymentStatus: body.paymentStatus } },
        requestId: req.id,
      }, tx);

      return next;
    });

    return serialize(updated);
  });

  // POST /orders/:id/events — note/internal/payment/shipping
  app.post<{ Params: { id: string } }>('/orders/:id/events', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = EventBody.parse(req.body);
    const id = req.params.id;

    const order = await prisma.order.findUnique({ where: { id }, select: { id: true } });
    if (!order) return reply.code(404).send({ error: 'not_found', requestId: req.id });

    const ev = await prisma.orderEvent.create({
      data: {
        orderId: id,
        kind: body.kind,
        note: body.note,
        actorId: req.auth!.user.id,
        metadata: (body.metadata ?? undefined) as Prisma.InputJsonValue | undefined,
      },
    });

    await writeAudit({
      action: `order.event.${body.kind}`,
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'order', entityId: id,
      diff: { after: { kind: body.kind, note: body.note } },
      requestId: req.id,
    });

    reply.code(201);
    return {
      id: ev.id, kind: ev.kind, note: ev.note,
      created_at: ev.createdAt.toISOString(),
    };
  });

  // POST /orders/validate-voucher — FE preview trước khi submit
  app.post('/orders/validate-voucher', {
    preHandler: [requireAuth, requirePermission('orders:read')],
  }, async req => {
    const body = z.object({
      code: z.string().max(30),
      subtotal: z.coerce.number().int().nonnegative(),
      shippingFee: z.coerce.number().int().nonnegative().default(0),
    }).parse(req.body);
    const result = await applyVoucher(body.code, body.subtotal, body.shippingFee, prisma as unknown as Prisma.TransactionClient);
    return result;
  });
};

