1	/**
2	 * Customers — CRUD với tags, addresses, aggregated spend/orders.
3	 * Soft-delete qua deletedAt (vì customer gắn với order, không xoá cứng).
4	 */
5	
6	import type { FastifyPluginAsync } from 'fastify';
7	import { z } from 'zod';
8	import type { Prisma } from '@prisma/client';
9	import { prisma } from '../lib/prisma.js';
10	import { writeAudit } from '../lib/audit.js';
11	import { requireAuth, requirePermission } from '../middleware/auth.js';
12	
13	// ─── Schemas ────────────────────────────────────────────────────
14	
15	const ListQuery = z.object({
16	  q:        z.string().max(200).optional(),
17	  tag:      z.string().max(50).optional(),
18	  province: z.string().max(100).optional(),
19	  sort:     z.enum(['new', 'spend-desc', 'orders-desc', 'name']).default('new'),
20	  page:     z.coerce.number().int().min(1).default(1),
21	  limit:    z.coerce.number().int().min(1).max(100).default(20),
22	});
23	
