/**
 * Customers — full CRM module:
 *  - CRUD + segmentation (VIP/AtRisk/Churn) + loyalty tier & points
 *  - Multi-address với recipient (người nhận ≠ người mua)
 *  - Marketing consent (email/SMS/call)
 *  - Communication log (call/email/note timeline)
 *  - CSV import (upsert theo email/phone)
 *  - Merge duplicate (primary ← secondary)
 *  - Recompute loyalty (manual trigger)
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { recomputeCustomer, recomputeAll } from '../customers/loyalty.js';

// ─── Schemas ────────────────────────────────────────────────────

const SEGMENTS = ['new_cus','active','vip','at_risk','churn','blacklist'] as const;
const TIERS = ['bronze','silver','gold','platinum'] as const;

const ListQuery = z.object({
  q:        z.string().max(200).optional(),
  tag:      z.string().max(50).optional(),
  segment:  z.enum(SEGMENTS).optional(),
  tier:     z.enum(TIERS).optional(),
  consentEmail: z.coerce.boolean().optional(),
  province: z.string().max(100).optional(),
  source:   z.string().max(40).optional(),
  sort:     z.enum(['new', 'spend-desc', 'orders-desc', 'name', 'last-order']).default('new'),
  page:     z.coerce.number().int().min(1).default(1),
  limit:    z.coerce.number().int().min(1).max(100).default(20),
});

const AddressSchema = z.object({
  label: z.string().max(40).optional(),
  fullName: z.string().min(1).max(120),
  phone:    z.string().min(6).max(20),
  recipientName:  z.string().max(120).optional(),
  recipientPhone: z.string().max(20).optional(),
  line1:    z.string().min(1).max(200),
  ward:     z.string().max(100).optional(),
  district: z.string().max(100).optional(),
  province: z.string().min(1).max(100),
  postalCode: z.string().max(20).optional(),
  isDefault: z.boolean().optional(),
  isBilling: z.boolean().optional(),
}).strict();

const ConsentSchema = z.object({
  consentEmail: z.boolean().optional(),
  consentSms:   z.boolean().optional(),
  consentCall:  z.boolean().optional(),
}).strict();

const CustomerCreateBody = z.object({
  name: z.string().min(1).max(120),
  email: z.string().email().max(120).nullable().optional(),
  phone: z.string().min(6).max(20).nullable().optional(),
  dob: z.coerce.date().nullable().optional(),
  gender: z.enum(['male','female','other']).nullable().optional(),
  tags: z.array(z.string().max(30)).max(20).default([]),
  notes: z.string().max(2000).nullable().optional(),
  source: z.string().max(40).nullable().optional(),
  segment: z.enum(SEGMENTS).optional(),
  consentEmail: z.boolean().optional(),
  consentSms:   z.boolean().optional(),
  consentCall:  z.boolean().optional(),
  addresses: z.array(AddressSchema).max(10).optional(),
}).strict();

const CustomerUpdateBody = CustomerCreateBody.partial().strict();

const CommunicationBody = z.object({
  channel: z.enum(['email','sms','call','chat','note']),
  direction: z.enum(['in','out']).default('out'),
  subject: z.string().max(200).optional(),
  body:    z.string().max(4000).optional(),
  outcome: z.string().max(60).optional(),
  refType: z.string().max(32).optional(),
  refId:   z.string().max(60).optional(),
}).strict();

const ImportBody = z.object({
  rows: z.array(z.object({
    name: z.string().min(1).max(120),
    email: z.string().email().nullable().optional(),
    phone: z.string().nullable().optional(),
    source: z.string().nullable().optional(),
    tags: z.array(z.string()).optional(),
    province: z.string().nullable().optional(),
    line1: z.string().nullable().optional(),
  })).min(1).max(5000),
  strategy: z.enum(['upsert','skip','overwrite']).default('upsert'),
}).strict();

const MergeBody = z.object({
  primaryId: z.string().uuid(),
  secondaryId: z.string().uuid(),
}).strict();

const PointsBody = z.object({
  delta: z.coerce.number().int(),   // +N earn, -N adjust
  note: z.string().max(500).optional(),
}).strict();

// ─── Helpers ────────────────────────────────────────────────────

type CustomerWithAddr = Prisma.CustomerGetPayload<{
  include: { addresses: true };
}>;

function serialize(c: CustomerWithAddr) {
  return {
    id: c.id,
    name: c.name,
    email: c.email,
    phone: c.phone,
    dob: c.dob ? c.dob.toISOString().slice(0, 10) : null,
    gender: c.gender,
    tags: c.tags,
    notes: c.notes,
    source: c.source,
    // Loyalty + CRM
    loyalty_tier: c.loyaltyTier,
    loyalty_points: c.loyaltyPoints,
    segment: c.segment,
    total_spent: Number(c.totalSpent ?? 0n),
    order_count: c.orderCount,
    last_order_at: c.lastOrderAt?.toISOString() ?? null,
    // Consent
    consent_email: c.consentEmail,
    consent_sms:   c.consentSms,
    consent_call:  c.consentCall,
    consent_updated_at: c.consentUpdatedAt?.toISOString() ?? null,
    // Addresses
    addresses: c.addresses.map(a => ({
      id: a.id, label: a.label,
      full_name: a.fullName, phone: a.phone,
      recipient_name: a.recipientName, recipient_phone: a.recipientPhone,
      line1: a.line1, ward: a.ward, district: a.district, province: a.province,
      postal_code: a.postalCode,
      is_default: a.isDefault, is_billing: a.isBilling,
    })),
    province: c.addresses.find(a => a.isDefault)?.province ?? c.addresses[0]?.province ?? null,
    created_at: c.createdAt.toISOString(),
    updated_at: c.updatedAt.toISOString(),
  };
}

// ─── Plugin ─────────────────────────────────────────────────────

export const customerRoutes: FastifyPluginAsync = async app => {

  // GET /customers
  app.get('/customers', { preHandler: [requireAuth, requirePermission('customers:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where: Prisma.CustomerWhereInput = {
      deletedAt: null,
      ...(q.q && {
        OR: [
          { name:  { contains: q.q, mode: 'insensitive' } },
          { email: { contains: q.q, mode: 'insensitive' } },
          { phone: { contains: q.q } },
        ],
      }),
      ...(q.tag && { tags: { has: q.tag } }),
      ...(q.segment && { segment: q.segment }),
      ...(q.tier && { loyaltyTier: q.tier }),
      ...(q.consentEmail !== undefined && { consentEmail: q.consentEmail }),
      ...(q.source && { source: q.source }),
      ...(q.province && { addresses: { some: { province: q.province } } }),
    };

    const orderBy: Prisma.CustomerOrderByWithRelationInput = (() => {
      switch (q.sort) {
        case 'spend-desc':  return { totalSpent: 'desc' };
        case 'orders-desc': return { orderCount: 'desc' };
        case 'name':        return { name: 'asc' };
        case 'last-order':  return { lastOrderAt: 'desc' };
        default:            return { createdAt: 'desc' };
      }
    })();

    const [total, rows, segmentStats] = await Promise.all([
      prisma.customer.count({ where }),
      prisma.customer.findMany({
        where,
        include: { addresses: true },
        orderBy,
        skip: (q.page - 1) * q.limit,
        take: q.limit,
      }),
      prisma.customer.groupBy({
        by: ['segment'],
        where: { deletedAt: null },
        _count: { _all: true },
      }),
    ]);

    const summary = {
      total,
      segments: segmentStats.reduce((acc: Record<string, number>, s) => {
        acc[s.segment] = s._count._all;
        return acc;
      }, {}),
    };

    return { data: rows.map(serialize), total, page: q.page, pageSize: q.limit, summary };
  });

  // GET /customers/:id — với orders recent + communications
  app.get<{ Params: { id: string } }>('/customers/:id', {
    preHandler: [requireAuth, requirePermission('customers:read')],
  }, async (req, reply) => {
    const c = await prisma.customer.findFirst({
      where: { id: req.params.id, deletedAt: null },
      include: { addresses: true },
    });
    if (!c) return reply.code(404).send({ error: 'not_found', requestId: req.id });

    const [orders, comms] = await Promise.all([
      prisma.order.findMany({
        where: { customerId: c.id },
        orderBy: { placedAt: 'desc' },
        take: 20,
        select: {
          id: true, code: true, status: true, paymentStatus: true,
          total: true, placedAt: true, deliveredAt: true,
        },
      }),
      prisma.customerCommunication.findMany({
        where: { customerId: c.id },
        orderBy: { createdAt: 'desc' },
        take: 50,
      }),
    ]);

    return {
      ...serialize(c),
      recent_orders: orders.map(o => ({
        id: o.id, code: o.code, status: o.status,
        payment_status: o.paymentStatus, total: Number(o.total),
        placed_at: o.placedAt.toISOString(),
        delivered_at: o.deliveredAt?.toISOString() ?? null,
      })),
      communications: comms.map(m => ({
        id: m.id, channel: m.channel, direction: m.direction,
        subject: m.subject, body: m.body, outcome: m.outcome,
        actor_email: m.actorEmail, ref_type: m.refType, ref_id: m.refId,
        created_at: m.createdAt.toISOString(),
      })),
    };
  });

  // POST /customers
  app.post('/customers', { preHandler: [requireAuth, requirePermission('customers:write')] }, async (req, reply) => {
    const body = CustomerCreateBody.parse(req.body);

    const c = await prisma.$transaction(async tx => {
      if (body.email) {
        const existing = await tx.customer.findUnique({ where: { email: body.email } });
        if (existing) { reply.code(409); throw new Error('Email đã tồn tại'); }
      }
      const consentUpdatedAt = (body.consentEmail !== undefined || body.consentSms !== undefined || body.consentCall !== undefined)
        ? new Date() : null;
      const created = await tx.customer.create({
        data: {
          name: body.name,
          email: body.email ?? null,
          phone: body.phone ?? null,
          dob: body.dob ?? null,
          gender: body.gender ?? null,
          tags: body.tags ?? [],
          notes: body.notes ?? null,
          source: body.source ?? null,
          segment: body.segment ?? 'new_cus',
          consentEmail: body.consentEmail ?? false,
          consentSms:   body.consentSms ?? false,
          consentCall:  body.consentCall ?? true,
          consentUpdatedAt,
          addresses: body.addresses ? { create: body.addresses.map(a => ({
            label: a.label ?? null,
            fullName: a.fullName, phone: a.phone,
            recipientName: a.recipientName ?? null, recipientPhone: a.recipientPhone ?? null,
            line1: a.line1,
            ward: a.ward ?? null, district: a.district ?? null,
            province: a.province, postalCode: a.postalCode ?? null,
            isDefault: a.isDefault ?? false,
            isBilling: a.isBilling ?? false,
          })) } : undefined,
        },
        include: { addresses: true },
      });
      await writeAudit({
        action: 'customer.create',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: created.id,
        diff: { after: { name: created.name, email: created.email } },
        requestId: req.id,
      }, tx);
      return created;
    });

    reply.code(201);
    return serialize(c);
  });

  // PATCH /customers/:id
  app.patch<{ Params: { id: string } }>('/customers/:id', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = CustomerUpdateBody.parse(req.body);
    const id = req.params.id;

    const c = await prisma.$transaction(async tx => {
      const existing = await tx.customer.findFirst({ where: { id, deletedAt: null } });
      if (!existing) { reply.code(404); throw new Error('Customer not found'); }

      const consentChanged = body.consentEmail !== undefined || body.consentSms !== undefined || body.consentCall !== undefined;
      const updated = await tx.customer.update({
        where: { id },
        data: {
          ...(body.name !== undefined && { name: body.name }),
          ...(body.email !== undefined && { email: body.email }),
          ...(body.phone !== undefined && { phone: body.phone }),
          ...(body.dob !== undefined && { dob: body.dob }),
          ...(body.gender !== undefined && { gender: body.gender }),
          ...(body.tags !== undefined && { tags: body.tags }),
          ...(body.notes !== undefined && { notes: body.notes }),
          ...(body.source !== undefined && { source: body.source }),
          ...(body.segment !== undefined && { segment: body.segment }),
          ...(body.consentEmail !== undefined && { consentEmail: body.consentEmail }),
          ...(body.consentSms !== undefined && { consentSms: body.consentSms }),
          ...(body.consentCall !== undefined && { consentCall: body.consentCall }),
          ...(consentChanged && { consentUpdatedAt: new Date() }),
        },
        include: { addresses: true },
      });
      await writeAudit({
        action: 'customer.update',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: id,
        diff: {
          before: { tags: existing.tags, segment: existing.segment, consentEmail: existing.consentEmail },
          after: { tags: updated.tags, segment: updated.segment, consentEmail: updated.consentEmail },
        },
        requestId: req.id,
      }, tx);
      return updated;
    });

    return serialize(c);
  });

  // DELETE /customers/:id — soft delete
  app.delete<{ Params: { id: string } }>('/customers/:id', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const id = req.params.id;
    await prisma.$transaction(async tx => {
      const existing = await tx.customer.findFirst({ where: { id, deletedAt: null } });
      if (!existing) { reply.code(404); throw new Error('Customer not found'); }
      await tx.customer.update({ where: { id }, data: { deletedAt: new Date() } });
      await writeAudit({
        action: 'customer.delete',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: id,
        requestId: req.id,
      }, tx);
    });
    reply.code(204);
  });

  // ─── Addresses ───
  app.post<{ Params: { id: string } }>('/customers/:id/addresses', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = AddressSchema.parse(req.body);
    const customerId = req.params.id;
    const cust = await prisma.customer.findFirst({ where: { id: customerId, deletedAt: null } });
    if (!cust) return reply.code(404).send({ error: 'not_found' });

    const addr = await prisma.$transaction(async tx => {
      if (body.isDefault) {
        await tx.customerAddress.updateMany({
          where: { customerId },
          data: { isDefault: false },
        });
      }
      return tx.customerAddress.create({
        data: {
          customerId,
          label: body.label ?? null,
          fullName: body.fullName, phone: body.phone,
          recipientName: body.recipientName ?? null, recipientPhone: body.recipientPhone ?? null,
          line1: body.line1,
          ward: body.ward ?? null, district: body.district ?? null,
          province: body.province, postalCode: body.postalCode ?? null,
          isDefault: body.isDefault ?? false,
          isBilling: body.isBilling ?? false,
        },
      });
    });
    reply.code(201);
    return { id: addr.id };
  });

  app.patch<{ Params: { id: string; addrId: string } }>('/customers/:id/addresses/:addrId', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = AddressSchema.partial().strict().parse(req.body);
    const { id: customerId, addrId } = req.params;

    const updated = await prisma.$transaction(async tx => {
      if (body.isDefault) {
        await tx.customerAddress.updateMany({
          where: { customerId, NOT: { id: addrId } },
          data: { isDefault: false },
        });
      }
      return tx.customerAddress.update({
        where: { id: addrId },
        data: {
          ...(body.label !== undefined && { label: body.label }),
          ...(body.fullName && { fullName: body.fullName }),
          ...(body.phone && { phone: body.phone }),
          ...(body.recipientName !== undefined && { recipientName: body.recipientName }),
          ...(body.recipientPhone !== undefined && { recipientPhone: body.recipientPhone }),
          ...(body.line1 && { line1: body.line1 }),
          ...(body.ward !== undefined && { ward: body.ward }),
          ...(body.district !== undefined && { district: body.district }),
          ...(body.province && { province: body.province }),
          ...(body.postalCode !== undefined && { postalCode: body.postalCode }),
          ...(body.isDefault !== undefined && { isDefault: body.isDefault }),
          ...(body.isBilling !== undefined && { isBilling: body.isBilling }),
        },
      });
    });
    return { id: updated.id };
  });

  app.delete<{ Params: { id: string; addrId: string } }>('/customers/:id/addresses/:addrId', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    await prisma.customerAddress.delete({ where: { id: req.params.addrId } });
    reply.code(204);
  });

  // ─── Communication log ───
  app.get<{ Params: { id: string } }>('/customers/:id/communications', {
    preHandler: [requireAuth, requirePermission('customers:read')],
  }, async req => {
    const rows = await prisma.customerCommunication.findMany({
      where: { customerId: req.params.id },
      orderBy: { createdAt: 'desc' },
      take: 100,
    });
    return {
      data: rows.map(m => ({
        id: m.id, channel: m.channel, direction: m.direction,
        subject: m.subject, body: m.body, outcome: m.outcome,
        actor_email: m.actorEmail, created_at: m.createdAt.toISOString(),
      })),
    };
  });

  app.post<{ Params: { id: string } }>('/customers/:id/communications', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = CommunicationBody.parse(req.body);
    const customerId = req.params.id;
    const cust = await prisma.customer.findFirst({ where: { id: customerId, deletedAt: null } });
    if (!cust) return reply.code(404).send({ error: 'not_found' });

    const row = await prisma.customerCommunication.create({
      data: {
        customerId,
        channel: body.channel,
        direction: body.direction,
        subject: body.subject ?? null,
        body: body.body ?? null,
        outcome: body.outcome ?? null,
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        refType: body.refType ?? null,
        refId: body.refId ?? null,
      },
    });
    reply.code(201);
    return { id: row.id, created_at: row.createdAt.toISOString() };
  });

  // ─── Consent update (shortcut) ───
  app.patch<{ Params: { id: string } }>('/customers/:id/consent', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = ConsentSchema.parse(req.body);
    const id = req.params.id;
    const c = await prisma.customer.update({
      where: { id },
      data: {
        ...(body.consentEmail !== undefined && { consentEmail: body.consentEmail }),
        ...(body.consentSms !== undefined && { consentSms: body.consentSms }),
        ...(body.consentCall !== undefined && { consentCall: body.consentCall }),
        consentUpdatedAt: new Date(),
      },
    });
    await writeAudit({
      action: 'customer.consent.update',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'customer', entityId: id,
      diff: { after: body },
      requestId: req.id,
    });
    return { consent_email: c.consentEmail, consent_sms: c.consentSms, consent_call: c.consentCall };
  });

  // ─── Loyalty ───
  app.post<{ Params: { id: string } }>('/customers/:id/recompute-loyalty', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    await recomputeCustomer(req.params.id);
    const c = await prisma.customer.findUnique({ where: { id: req.params.id }, include: { addresses: true } });
    if (!c) return reply.code(404).send({ error: 'not_found' });
    return serialize(c);
  });

  app.post('/customers/recompute-all', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async () => {
    const r = await recomputeAll();
    return r;
  });

  app.post<{ Params: { id: string } }>('/customers/:id/points', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = PointsBody.parse(req.body);
    const c = await prisma.customer.findFirst({ where: { id: req.params.id, deletedAt: null } });
    if (!c) return reply.code(404).send({ error: 'not_found' });
    const newBal = Math.max(0, c.loyaltyPoints + body.delta);
    const u = await prisma.customer.update({ where: { id: c.id }, data: { loyaltyPoints: newBal } });
    await prisma.customerCommunication.create({
      data: {
        customerId: c.id,
        channel: 'note',
        direction: 'out',
        subject: 'Loyalty points adjustment',
        body: `${body.delta >= 0 ? '+' : ''}${body.delta} điểm — ${body.note ?? '(no note)'}`,
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
      },
    });
    await writeAudit({
      action: 'customer.loyalty.adjust',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'customer', entityId: c.id,
      diff: { before: { points: c.loyaltyPoints }, after: { points: newBal }, delta: body.delta },
      requestId: req.id,
    });
    return { loyalty_points: u.loyaltyPoints };
  });

  // ─── Import CSV (JSON payload) ───
  app.post('/customers/import', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = ImportBody.parse(req.body);
    let created = 0, updated = 0, skipped = 0;
    const errors: Array<{ row: number; error: string }> = [];

    for (let i = 0; i < body.rows.length; i++) {
      const r = body.rows[i];
      try {
        const existing = await prisma.customer.findFirst({
          where: {
            OR: [
              ...(r.email ? [{ email: r.email }] : []),
              ...(r.phone ? [{ phone: r.phone }] : []),
            ],
            deletedAt: null,
          },
        });
        if (existing) {
          if (body.strategy === 'skip') { skipped++; continue; }
          if (body.strategy === 'overwrite' || body.strategy === 'upsert') {
            await prisma.customer.update({
              where: { id: existing.id },
              data: {
                name: r.name,
                email: r.email ?? existing.email,
                phone: r.phone ?? existing.phone,
                source: r.source ?? existing.source,
                tags: r.tags && r.tags.length ? r.tags : existing.tags,
              },
            });
            updated++;
            continue;
          }
        }
        await prisma.customer.create({
          data: {
            name: r.name,
            email: r.email ?? null,
            phone: r.phone ?? null,
            source: r.source ?? null,
            tags: r.tags ?? [],
            segment: 'new_cus',
            addresses: r.line1 || r.province ? {
              create: [{
                fullName: r.name,
                phone: r.phone ?? '',
                line1: r.line1 ?? '',
                province: r.province ?? '',
                isDefault: true,
              }],
            } : undefined,
          },
        });
        created++;
      } catch (err) {
        errors.push({ row: i + 1, error: (err as Error).message });
      }
    }

    await writeAudit({
      action: 'customer.import',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'customer',
      diff: { after: { created, updated, skipped, errors: errors.length, strategy: body.strategy } },
      requestId: req.id,
    });

    if (errors.length > 0 && created === 0 && updated === 0) reply.code(400);
    return { created, updated, skipped, errors };
  });

  // ─── Merge duplicate ───
  app.post('/customers/merge', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = MergeBody.parse(req.body);
    if (body.primaryId === body.secondaryId) {
      return reply.code(400).send({ error: 'same_id' });
    }

    const merged = await prisma.$transaction(async tx => {
      const [primary, secondary] = await Promise.all([
        tx.customer.findFirst({ where: { id: body.primaryId, deletedAt: null } }),
        tx.customer.findFirst({ where: { id: body.secondaryId, deletedAt: null } }),
      ]);
      if (!primary || !secondary) throw new Error('Một trong hai khách không tồn tại');

      // Move addresses, orders, communications
      await tx.customerAddress.updateMany({
        where: { customerId: secondary.id },
        data: { customerId: primary.id, isDefault: false },
      });
      await tx.order.updateMany({
        where: { customerId: secondary.id },
        data: { customerId: primary.id },
      });
      await tx.customerCommunication.updateMany({
        where: { customerId: secondary.id },
        data: { customerId: primary.id },
      });

      // Merge tags (union)
      const tags = Array.from(new Set([...(primary.tags || []), ...(secondary.tags || [])]));
      const notes = [primary.notes, secondary.notes && `[Merged from ${secondary.email ?? secondary.phone}] ${secondary.notes}`]
        .filter(Boolean).join('\n\n');

      const updated = await tx.customer.update({
        where: { id: primary.id },
        data: {
          tags,
          notes,
          email: primary.email ?? secondary.email,
          phone: primary.phone ?? secondary.phone,
        },
        include: { addresses: true },
      });

      await tx.customer.update({
        where: { id: secondary.id },
        data: { deletedAt: new Date(), notes: `[MERGED INTO ${primary.id}]` },
      });

      await writeAudit({
        action: 'customer.merge',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: primary.id,
        diff: { before: { secondaryId: secondary.id }, after: { primaryId: primary.id } },
        requestId: req.id,
      }, tx);

      return updated;
    });

    // Recompute loyalty
    await recomputeCustomer(merged.id).catch(() => undefined);

    return serialize(merged);
  });
};

toolUseResult.content:
/**
 * Customers — full CRM module:
 *  - CRUD + segmentation (VIP/AtRisk/Churn) + loyalty tier & points
 *  - Multi-address với recipient (người nhận ≠ người mua)
 *  - Marketing consent (email/SMS/call)
 *  - Communication log (call/email/note timeline)
 *  - CSV import (upsert theo email/phone)
 *  - Merge duplicate (primary ← secondary)
 *  - Recompute loyalty (manual trigger)
 */

import type { FastifyPluginAsync } from 'fastify';
import { z } from 'zod';
import type { Prisma } from '@prisma/client';
import { prisma } from '../lib/prisma.js';
import { writeAudit } from '../lib/audit.js';
import { requireAuth, requirePermission } from '../middleware/auth.js';
import { recomputeCustomer, recomputeAll } from '../customers/loyalty.js';

// ─── Schemas ────────────────────────────────────────────────────

const SEGMENTS = ['new_cus','active','vip','at_risk','churn','blacklist'] as const;
const TIERS = ['bronze','silver','gold','platinum'] as const;

const ListQuery = z.object({
  q:        z.string().max(200).optional(),
  tag:      z.string().max(50).optional(),
  segment:  z.enum(SEGMENTS).optional(),
  tier:     z.enum(TIERS).optional(),
  consentEmail: z.coerce.boolean().optional(),
  province: z.string().max(100).optional(),
  source:   z.string().max(40).optional(),
  sort:     z.enum(['new', 'spend-desc', 'orders-desc', 'name', 'last-order']).default('new'),
  page:     z.coerce.number().int().min(1).default(1),
  limit:    z.coerce.number().int().min(1).max(100).default(20),
});

const AddressSchema = z.object({
  label: z.string().max(40).optional(),
  fullName: z.string().min(1).max(120),
  phone:    z.string().min(6).max(20),
  recipientName:  z.string().max(120).optional(),
  recipientPhone: z.string().max(20).optional(),
  line1:    z.string().min(1).max(200),
  ward:     z.string().max(100).optional(),
  district: z.string().max(100).optional(),
  province: z.string().min(1).max(100),
  postalCode: z.string().max(20).optional(),
  isDefault: z.boolean().optional(),
  isBilling: z.boolean().optional(),
}).strict();

const ConsentSchema = z.object({
  consentEmail: z.boolean().optional(),
  consentSms:   z.boolean().optional(),
  consentCall:  z.boolean().optional(),
}).strict();

const CustomerCreateBody = z.object({
  name: z.string().min(1).max(120),
  email: z.string().email().max(120).nullable().optional(),
  phone: z.string().min(6).max(20).nullable().optional(),
  dob: z.coerce.date().nullable().optional(),
  gender: z.enum(['male','female','other']).nullable().optional(),
  tags: z.array(z.string().max(30)).max(20).default([]),
  notes: z.string().max(2000).nullable().optional(),
  source: z.string().max(40).nullable().optional(),
  segment: z.enum(SEGMENTS).optional(),
  consentEmail: z.boolean().optional(),
  consentSms:   z.boolean().optional(),
  consentCall:  z.boolean().optional(),
  addresses: z.array(AddressSchema).max(10).optional(),
}).strict();

const CustomerUpdateBody = CustomerCreateBody.partial().strict();

const CommunicationBody = z.object({
  channel: z.enum(['email','sms','call','chat','note']),
  direction: z.enum(['in','out']).default('out'),
  subject: z.string().max(200).optional(),
  body:    z.string().max(4000).optional(),
  outcome: z.string().max(60).optional(),
  refType: z.string().max(32).optional(),
  refId:   z.string().max(60).optional(),
}).strict();

const ImportBody = z.object({
  rows: z.array(z.object({
    name: z.string().min(1).max(120),
    email: z.string().email().nullable().optional(),
    phone: z.string().nullable().optional(),
    source: z.string().nullable().optional(),
    tags: z.array(z.string()).optional(),
    province: z.string().nullable().optional(),
    line1: z.string().nullable().optional(),
  })).min(1).max(5000),
  strategy: z.enum(['upsert','skip','overwrite']).default('upsert'),
}).strict();

const MergeBody = z.object({
  primaryId: z.string().uuid(),
  secondaryId: z.string().uuid(),
}).strict();

const PointsBody = z.object({
  delta: z.coerce.number().int(),   // +N earn, -N adjust
  note: z.string().max(500).optional(),
}).strict();

// ─── Helpers ────────────────────────────────────────────────────

type CustomerWithAddr = Prisma.CustomerGetPayload<{
  include: { addresses: true };
}>;

function serialize(c: CustomerWithAddr) {
  return {
    id: c.id,
    name: c.name,
    email: c.email,
    phone: c.phone,
    dob: c.dob ? c.dob.toISOString().slice(0, 10) : null,
    gender: c.gender,
    tags: c.tags,
    notes: c.notes,
    source: c.source,
    // Loyalty + CRM
    loyalty_tier: c.loyaltyTier,
    loyalty_points: c.loyaltyPoints,
    segment: c.segment,
    total_spent: Number(c.totalSpent ?? 0n),
    order_count: c.orderCount,
    last_order_at: c.lastOrderAt?.toISOString() ?? null,
    // Consent
    consent_email: c.consentEmail,
    consent_sms:   c.consentSms,
    consent_call:  c.consentCall,
    consent_updated_at: c.consentUpdatedAt?.toISOString() ?? null,
    // Addresses
    addresses: c.addresses.map(a => ({
      id: a.id, label: a.label,
      full_name: a.fullName, phone: a.phone,
      recipient_name: a.recipientName, recipient_phone: a.recipientPhone,
      line1: a.line1, ward: a.ward, district: a.district, province: a.province,
      postal_code: a.postalCode,
      is_default: a.isDefault, is_billing: a.isBilling,
    })),
    province: c.addresses.find(a => a.isDefault)?.province ?? c.addresses[0]?.province ?? null,
    created_at: c.createdAt.toISOString(),
    updated_at: c.updatedAt.toISOString(),
  };
}

// ─── Plugin ─────────────────────────────────────────────────────

export const customerRoutes: FastifyPluginAsync = async app => {

  // GET /customers
  app.get('/customers', { preHandler: [requireAuth, requirePermission('customers:read')] }, async req => {
    const q = ListQuery.parse(req.query);
    const where: Prisma.CustomerWhereInput = {
      deletedAt: null,
      ...(q.q && {
        OR: [
          { name:  { contains: q.q, mode: 'insensitive' } },
          { email: { contains: q.q, mode: 'insensitive' } },
          { phone: { contains: q.q } },
        ],
      }),
      ...(q.tag && { tags: { has: q.tag } }),
      ...(q.segment && { segment: q.segment }),
      ...(q.tier && { loyaltyTier: q.tier }),
      ...(q.consentEmail !== undefined && { consentEmail: q.consentEmail }),
      ...(q.source && { source: q.source }),
      ...(q.province && { addresses: { some: { province: q.province } } }),
    };

    const orderBy: Prisma.CustomerOrderByWithRelationInput = (() => {
      switch (q.sort) {
        case 'spend-desc':  return { totalSpent: 'desc' };
        case 'orders-desc': return { orderCount: 'desc' };
        case 'name':        return { name: 'asc' };
        case 'last-order':  return { lastOrderAt: 'desc' };
        default:            return { createdAt: 'desc' };
      }
    })();

    const [total, rows, segmentStats] = await Promise.all([
      prisma.customer.count({ where }),
      prisma.customer.findMany({
        where,
        include: { addresses: true },
        orderBy,
        skip: (q.page - 1) * q.limit,
        take: q.limit,
      }),
      prisma.customer.groupBy({
        by: ['segment'],
        where: { deletedAt: null },
        _count: { _all: true },
      }),
    ]);

    const summary = {
      total,
      segments: segmentStats.reduce((acc: Record<string, number>, s) => {
        acc[s.segment] = s._count._all;
        return acc;
      }, {}),
    };

    return { data: rows.map(serialize), total, page: q.page, pageSize: q.limit, summary };
  });

  // GET /customers/:id — với orders recent + communications
  app.get<{ Params: { id: string } }>('/customers/:id', {
    preHandler: [requireAuth, requirePermission('customers:read')],
  }, async (req, reply) => {
    const c = await prisma.customer.findFirst({
      where: { id: req.params.id, deletedAt: null },
      include: { addresses: true },
    });
    if (!c) return reply.code(404).send({ error: 'not_found', requestId: req.id });

    const [orders, comms] = await Promise.all([
      prisma.order.findMany({
        where: { customerId: c.id },
        orderBy: { placedAt: 'desc' },
        take: 20,
        select: {
          id: true, code: true, status: true, paymentStatus: true,
          total: true, placedAt: true, deliveredAt: true,
        },
      }),
      prisma.customerCommunication.findMany({
        where: { customerId: c.id },
        orderBy: { createdAt: 'desc' },
        take: 50,
      }),
    ]);

    return {
      ...serialize(c),
      recent_orders: orders.map(o => ({
        id: o.id, code: o.code, status: o.status,
        payment_status: o.paymentStatus, total: Number(o.total),
        placed_at: o.placedAt.toISOString(),
        delivered_at: o.deliveredAt?.toISOString() ?? null,
      })),
      communications: comms.map(m => ({
        id: m.id, channel: m.channel, direction: m.direction,
        subject: m.subject, body: m.body, outcome: m.outcome,
        actor_email: m.actorEmail, ref_type: m.refType, ref_id: m.refId,
        created_at: m.createdAt.toISOString(),
      })),
    };
  });

  // POST /customers
  app.post('/customers', { preHandler: [requireAuth, requirePermission('customers:write')] }, async (req, reply) => {
    const body = CustomerCreateBody.parse(req.body);

    const c = await prisma.$transaction(async tx => {
      if (body.email) {
        const existing = await tx.customer.findUnique({ where: { email: body.email } });
        if (existing) { reply.code(409); throw new Error('Email đã tồn tại'); }
      }
      const consentUpdatedAt = (body.consentEmail !== undefined || body.consentSms !== undefined || body.consentCall !== undefined)
        ? new Date() : null;
      const created = await tx.customer.create({
        data: {
          name: body.name,
          email: body.email ?? null,
          phone: body.phone ?? null,
          dob: body.dob ?? null,
          gender: body.gender ?? null,
          tags: body.tags ?? [],
          notes: body.notes ?? null,
          source: body.source ?? null,
          segment: body.segment ?? 'new_cus',
          consentEmail: body.consentEmail ?? false,
          consentSms:   body.consentSms ?? false,
          consentCall:  body.consentCall ?? true,
          consentUpdatedAt,
          addresses: body.addresses ? { create: body.addresses.map(a => ({
            label: a.label ?? null,
            fullName: a.fullName, phone: a.phone,
            recipientName: a.recipientName ?? null, recipientPhone: a.recipientPhone ?? null,
            line1: a.line1,
            ward: a.ward ?? null, district: a.district ?? null,
            province: a.province, postalCode: a.postalCode ?? null,
            isDefault: a.isDefault ?? false,
            isBilling: a.isBilling ?? false,
          })) } : undefined,
        },
        include: { addresses: true },
      });
      await writeAudit({
        action: 'customer.create',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: created.id,
        diff: { after: { name: created.name, email: created.email } },
        requestId: req.id,
      }, tx);
      return created;
    });

    reply.code(201);
    return serialize(c);
  });

  // PATCH /customers/:id
  app.patch<{ Params: { id: string } }>('/customers/:id', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = CustomerUpdateBody.parse(req.body);
    const id = req.params.id;

    const c = await prisma.$transaction(async tx => {
      const existing = await tx.customer.findFirst({ where: { id, deletedAt: null } });
      if (!existing) { reply.code(404); throw new Error('Customer not found'); }

      const consentChanged = body.consentEmail !== undefined || body.consentSms !== undefined || body.consentCall !== undefined;
      const updated = await tx.customer.update({
        where: { id },
        data: {
          ...(body.name !== undefined && { name: body.name }),
          ...(body.email !== undefined && { email: body.email }),
          ...(body.phone !== undefined && { phone: body.phone }),
          ...(body.dob !== undefined && { dob: body.dob }),
          ...(body.gender !== undefined && { gender: body.gender }),
          ...(body.tags !== undefined && { tags: body.tags }),
          ...(body.notes !== undefined && { notes: body.notes }),
          ...(body.source !== undefined && { source: body.source }),
          ...(body.segment !== undefined && { segment: body.segment }),
          ...(body.consentEmail !== undefined && { consentEmail: body.consentEmail }),
          ...(body.consentSms !== undefined && { consentSms: body.consentSms }),
          ...(body.consentCall !== undefined && { consentCall: body.consentCall }),
          ...(consentChanged && { consentUpdatedAt: new Date() }),
        },
        include: { addresses: true },
      });
      await writeAudit({
        action: 'customer.update',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: id,
        diff: {
          before: { tags: existing.tags, segment: existing.segment, consentEmail: existing.consentEmail },
          after: { tags: updated.tags, segment: updated.segment, consentEmail: updated.consentEmail },
        },
        requestId: req.id,
      }, tx);
      return updated;
    });

    return serialize(c);
  });

  // DELETE /customers/:id — soft delete
  app.delete<{ Params: { id: string } }>('/customers/:id', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const id = req.params.id;
    await prisma.$transaction(async tx => {
      const existing = await tx.customer.findFirst({ where: { id, deletedAt: null } });
      if (!existing) { reply.code(404); throw new Error('Customer not found'); }
      await tx.customer.update({ where: { id }, data: { deletedAt: new Date() } });
      await writeAudit({
        action: 'customer.delete',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: id,
        requestId: req.id,
      }, tx);
    });
    reply.code(204);
  });

  // ─── Addresses ───
  app.post<{ Params: { id: string } }>('/customers/:id/addresses', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = AddressSchema.parse(req.body);
    const customerId = req.params.id;
    const cust = await prisma.customer.findFirst({ where: { id: customerId, deletedAt: null } });
    if (!cust) return reply.code(404).send({ error: 'not_found' });

    const addr = await prisma.$transaction(async tx => {
      if (body.isDefault) {
        await tx.customerAddress.updateMany({
          where: { customerId },
          data: { isDefault: false },
        });
      }
      return tx.customerAddress.create({
        data: {
          customerId,
          label: body.label ?? null,
          fullName: body.fullName, phone: body.phone,
          recipientName: body.recipientName ?? null, recipientPhone: body.recipientPhone ?? null,
          line1: body.line1,
          ward: body.ward ?? null, district: body.district ?? null,
          province: body.province, postalCode: body.postalCode ?? null,
          isDefault: body.isDefault ?? false,
          isBilling: body.isBilling ?? false,
        },
      });
    });
    reply.code(201);
    return { id: addr.id };
  });

  app.patch<{ Params: { id: string; addrId: string } }>('/customers/:id/addresses/:addrId', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = AddressSchema.partial().strict().parse(req.body);
    const { id: customerId, addrId } = req.params;

    const updated = await prisma.$transaction(async tx => {
      if (body.isDefault) {
        await tx.customerAddress.updateMany({
          where: { customerId, NOT: { id: addrId } },
          data: { isDefault: false },
        });
      }
      return tx.customerAddress.update({
        where: { id: addrId },
        data: {
          ...(body.label !== undefined && { label: body.label }),
          ...(body.fullName && { fullName: body.fullName }),
          ...(body.phone && { phone: body.phone }),
          ...(body.recipientName !== undefined && { recipientName: body.recipientName }),
          ...(body.recipientPhone !== undefined && { recipientPhone: body.recipientPhone }),
          ...(body.line1 && { line1: body.line1 }),
          ...(body.ward !== undefined && { ward: body.ward }),
          ...(body.district !== undefined && { district: body.district }),
          ...(body.province && { province: body.province }),
          ...(body.postalCode !== undefined && { postalCode: body.postalCode }),
          ...(body.isDefault !== undefined && { isDefault: body.isDefault }),
          ...(body.isBilling !== undefined && { isBilling: body.isBilling }),
        },
      });
    });
    return { id: updated.id };
  });

  app.delete<{ Params: { id: string; addrId: string } }>('/customers/:id/addresses/:addrId', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    await prisma.customerAddress.delete({ where: { id: req.params.addrId } });
    reply.code(204);
  });

  // ─── Communication log ───
  app.get<{ Params: { id: string } }>('/customers/:id/communications', {
    preHandler: [requireAuth, requirePermission('customers:read')],
  }, async req => {
    const rows = await prisma.customerCommunication.findMany({
      where: { customerId: req.params.id },
      orderBy: { createdAt: 'desc' },
      take: 100,
    });
    return {
      data: rows.map(m => ({
        id: m.id, channel: m.channel, direction: m.direction,
        subject: m.subject, body: m.body, outcome: m.outcome,
        actor_email: m.actorEmail, created_at: m.createdAt.toISOString(),
      })),
    };
  });

  app.post<{ Params: { id: string } }>('/customers/:id/communications', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = CommunicationBody.parse(req.body);
    const customerId = req.params.id;
    const cust = await prisma.customer.findFirst({ where: { id: customerId, deletedAt: null } });
    if (!cust) return reply.code(404).send({ error: 'not_found' });

    const row = await prisma.customerCommunication.create({
      data: {
        customerId,
        channel: body.channel,
        direction: body.direction,
        subject: body.subject ?? null,
        body: body.body ?? null,
        outcome: body.outcome ?? null,
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
        refType: body.refType ?? null,
        refId: body.refId ?? null,
      },
    });
    reply.code(201);
    return { id: row.id, created_at: row.createdAt.toISOString() };
  });

  // ─── Consent update (shortcut) ───
  app.patch<{ Params: { id: string } }>('/customers/:id/consent', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = ConsentSchema.parse(req.body);
    const id = req.params.id;
    const c = await prisma.customer.update({
      where: { id },
      data: {
        ...(body.consentEmail !== undefined && { consentEmail: body.consentEmail }),
        ...(body.consentSms !== undefined && { consentSms: body.consentSms }),
        ...(body.consentCall !== undefined && { consentCall: body.consentCall }),
        consentUpdatedAt: new Date(),
      },
    });
    await writeAudit({
      action: 'customer.consent.update',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'customer', entityId: id,
      diff: { after: body },
      requestId: req.id,
    });
    return { consent_email: c.consentEmail, consent_sms: c.consentSms, consent_call: c.consentCall };
  });

  // ─── Loyalty ───
  app.post<{ Params: { id: string } }>('/customers/:id/recompute-loyalty', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    await recomputeCustomer(req.params.id);
    const c = await prisma.customer.findUnique({ where: { id: req.params.id }, include: { addresses: true } });
    if (!c) return reply.code(404).send({ error: 'not_found' });
    return serialize(c);
  });

  app.post('/customers/recompute-all', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async () => {
    const r = await recomputeAll();
    return r;
  });

  app.post<{ Params: { id: string } }>('/customers/:id/points', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = PointsBody.parse(req.body);
    const c = await prisma.customer.findFirst({ where: { id: req.params.id, deletedAt: null } });
    if (!c) return reply.code(404).send({ error: 'not_found' });
    const newBal = Math.max(0, c.loyaltyPoints + body.delta);
    const u = await prisma.customer.update({ where: { id: c.id }, data: { loyaltyPoints: newBal } });
    await prisma.customerCommunication.create({
      data: {
        customerId: c.id,
        channel: 'note',
        direction: 'out',
        subject: 'Loyalty points adjustment',
        body: `${body.delta >= 0 ? '+' : ''}${body.delta} điểm — ${body.note ?? '(no note)'}`,
        actorId: req.auth!.user.id,
        actorEmail: req.auth!.user.email,
      },
    });
    await writeAudit({
      action: 'customer.loyalty.adjust',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'customer', entityId: c.id,
      diff: { before: { points: c.loyaltyPoints }, after: { points: newBal }, delta: body.delta },
      requestId: req.id,
    });
    return { loyalty_points: u.loyaltyPoints };
  });

  // ─── Import CSV (JSON payload) ───
  app.post('/customers/import', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = ImportBody.parse(req.body);
    let created = 0, updated = 0, skipped = 0;
    const errors: Array<{ row: number; error: string }> = [];

    for (let i = 0; i < body.rows.length; i++) {
      const r = body.rows[i];
      try {
        const existing = await prisma.customer.findFirst({
          where: {
            OR: [
              ...(r.email ? [{ email: r.email }] : []),
              ...(r.phone ? [{ phone: r.phone }] : []),
            ],
            deletedAt: null,
          },
        });
        if (existing) {
          if (body.strategy === 'skip') { skipped++; continue; }
          if (body.strategy === 'overwrite' || body.strategy === 'upsert') {
            await prisma.customer.update({
              where: { id: existing.id },
              data: {
                name: r.name,
                email: r.email ?? existing.email,
                phone: r.phone ?? existing.phone,
                source: r.source ?? existing.source,
                tags: r.tags && r.tags.length ? r.tags : existing.tags,
              },
            });
            updated++;
            continue;
          }
        }
        await prisma.customer.create({
          data: {
            name: r.name,
            email: r.email ?? null,
            phone: r.phone ?? null,
            source: r.source ?? null,
            tags: r.tags ?? [],
            segment: 'new_cus',
            addresses: r.line1 || r.province ? {
              create: [{
                fullName: r.name,
                phone: r.phone ?? '',
                line1: r.line1 ?? '',
                province: r.province ?? '',
                isDefault: true,
              }],
            } : undefined,
          },
        });
        created++;
      } catch (err) {
        errors.push({ row: i + 1, error: (err as Error).message });
      }
    }

    await writeAudit({
      action: 'customer.import',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'customer',
      diff: { after: { created, updated, skipped, errors: errors.length, strategy: body.strategy } },
      requestId: req.id,
    });

    if (errors.length > 0 && created === 0 && updated === 0) reply.code(400);
    return { created, updated, skipped, errors };
  });

  // ─── Merge duplicate ───
  app.post('/customers/merge', {
    preHandler: [requireAuth, requirePermission('customers:write')],
  }, async (req, reply) => {
    const body = MergeBody.parse(req.body);
    if (body.primaryId === body.secondaryId) {
      return reply.code(400).send({ error: 'same_id' });
    }

    const merged = await prisma.$transaction(async tx => {
      const [primary, secondary] = await Promise.all([
        tx.customer.findFirst({ where: { id: body.primaryId, deletedAt: null } }),
        tx.customer.findFirst({ where: { id: body.secondaryId, deletedAt: null } }),
      ]);
      if (!primary || !secondary) throw new Error('Một trong hai khách không tồn tại');

      // Move addresses, orders, communications
      await tx.customerAddress.updateMany({
        where: { customerId: secondary.id },
        data: { customerId: primary.id, isDefault: false },
      });
      await tx.order.updateMany({
        where: { customerId: secondary.id },
        data: { customerId: primary.id },
      });
      await tx.customerCommunication.updateMany({
        where: { customerId: secondary.id },
        data: { customerId: primary.id },
      });

      // Merge tags (union)
      const tags = Array.from(new Set([...(primary.tags || []), ...(secondary.tags || [])]));
      const notes = [primary.notes, secondary.notes && `[Merged from ${secondary.email ?? secondary.phone}] ${secondary.notes}`]
        .filter(Boolean).join('\n\n');

      const updated = await tx.customer.update({
        where: { id: primary.id },
        data: {
          tags,
          notes,
          email: primary.email ?? secondary.email,
          phone: primary.phone ?? secondary.phone,
        },
        include: { addresses: true },
      });

      await tx.customer.update({
        where: { id: secondary.id },
        data: { deletedAt: new Date(), notes: `[MERGED INTO ${primary.id}]` },
      });

      await writeAudit({
        action: 'customer.merge',
        actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'customer', entityId: primary.id,
        diff: { before: { secondaryId: secondary.id }, after: { primaryId: primary.id } },
        requestId: req.id,
      }, tx);

      return updated;
    });

    // Recompute loyalty
    await recomputeCustomer(merged.id).catch(() => undefined);

    return serialize(merged);
  });
};

