/**
 * Customer loyalty & RFM segmentation.
 *
 * Chạy:
 *  - Sau mỗi order delivered → recomputeCustomer(id) (trigger từ order state change)
 *  - Cron hằng ngày → recomputeAll() để update segment (vì segment phụ thuộc recency)
 *
 * Quy tắc tier (totalSpent, VND):
 *   bronze   : 0 .. 2_000_000
 *   silver   : 2_000_000 .. 10_000_000
 *   gold     : 10_000_000 .. 50_000_000
 *   platinum : > 50_000_000
 *
 * Quy tắc segment (RFM simplified):
 *   new_cus   : createdAt trong 30 ngày & orderCount ≤ 1
 *   vip       : totalSpent >= 10_000_000 hoặc orderCount >= 10
 *   at_risk   : lastOrderAt > 60 ngày & orderCount >= 2
 *   churn     : lastOrderAt > 180 ngày
 *   active    : còn lại
 *   blacklist : không auto — chỉ set manual
 *
 * Points rule:
 *   1 point / 10_000 VND chi tiêu
 *   1 point = 1_000 VND khi redeem (tối đa 20% order total)
 */

import type { Prisma, PrismaClient } from '@prisma/client';
import { prisma } from '../lib/prisma.js';

type Tx = Prisma.TransactionClient | PrismaClient;

export const POINTS_PER_VND = 10_000n;         // 1 điểm / 10k
export const POINTS_VALUE_VND = 1_000n;        // 1 điểm = 1k khi redeem
export const MAX_POINTS_DISCOUNT_PCT = 20;     // tối đa 20% order total

export function computeTier(totalSpent: bigint): 'bronze' | 'silver' | 'gold' | 'platinum' {
  if (totalSpent >= 50_000_000n) return 'platinum';
  if (totalSpent >= 10_000_000n) return 'gold';
  if (totalSpent >=  2_000_000n) return 'silver';
  return 'bronze';
}

export function computeSegment(args: {
  createdAt: Date;
  orderCount: number;
  totalSpent: bigint;
  lastOrderAt: Date | null;
  currentSegment?: string;
}): 'new_cus' | 'active' | 'vip' | 'at_risk' | 'churn' {
  // Không override blacklist auto — caller kiểm tra
  const now = Date.now();
  const daysSinceCreate = (now - args.createdAt.getTime()) / 86_400_000;
  const daysSinceOrder = args.lastOrderAt
    ? (now - args.lastOrderAt.getTime()) / 86_400_000
    : Infinity;

  if (args.totalSpent >= 10_000_000n || args.orderCount >= 10) return 'vip';
  if (daysSinceOrder > 180) return 'churn';
  if (daysSinceOrder > 60 && args.orderCount >= 2) return 'at_risk';
  if (daysSinceCreate <= 30 && args.orderCount <= 1) return 'new_cus';
  return 'active';
}

/** Điểm thưởng kiếm được từ 1 order */
export function pointsEarnedFor(orderTotal: bigint): number {
  return Number(orderTotal / POINTS_PER_VND);
}

/** Giá trị VND từ N điểm */
export function pointsToVnd(points: number): bigint {
  return BigInt(points) * POINTS_VALUE_VND;
}

/** Max VND có thể redeem trên 1 order */
export function maxRedeemVnd(orderTotal: bigint, pointsBalance: number): bigint {
  const cap = (orderTotal * BigInt(MAX_POINTS_DISCOUNT_PCT)) / 100n;
  const byPoints = pointsToVnd(pointsBalance);
  return cap < byPoints ? cap : byPoints;
}

/**
 * Tính lại tier + segment + totalSpent + orderCount cho 1 khách dựa trên orders thực tế.
 * Dùng khi đơn hàng chuyển trạng thái (delivered/cancelled) hoặc khi admin force refresh.
 */
export async function recomputeCustomer(customerId: string, tx: Tx = prisma): Promise<void> {
  const customer = await tx.customer.findUnique({ where: { id: customerId } });
  if (!customer) return;
  if (customer.segment === 'blacklist') return; // tôn trọng manual flag

  const orders = await tx.order.findMany({
    where: {
      customerId,
      status: { in: ['delivered', 'returned'] }, // chỉ tính đơn thành công
    },
    select: { total: true, placedAt: true, status: true, pointsEarned: true, pointsUsed: true },
  });

  const realized = orders.filter(o => o.status === 'delivered');
  const totalSpent = realized.reduce((s, o) => s + o.total, 0n);
  const orderCount = realized.length;
  const lastOrderAt = realized.length
    ? realized.reduce((d, o) => (o.placedAt > d ? o.placedAt : d), realized[0].placedAt)
    : null;

  // Tổng điểm = earned - used (cập nhật lại để tránh drift)
  const pointsNet = orders.reduce((s, o) => s + (o.pointsEarned ?? 0) - (o.pointsUsed ?? 0), 0);

  const tier = computeTier(totalSpent);
  const segment = computeSegment({
    createdAt: customer.createdAt,
    orderCount,
    totalSpent,
    lastOrderAt,
  });

  await tx.customer.update({
    where: { id: customerId },
    data: {
      totalSpent,
      orderCount,
      lastOrderAt,
      loyaltyTier: tier,
      loyaltyPoints: Math.max(0, pointsNet),
      segment,
    },
  });
}

/**
 * Batch recompute — chạy trong cron. Có thể scale lên bằng queue sau.
 */
export async function recomputeAll(batchSize = 200): Promise<{ total: number }> {
  let cursor: string | undefined;
  let total = 0;
  for (;;) {
    const batch = await prisma.customer.findMany({
      where: { deletedAt: null },
      take: batchSize,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      orderBy: { id: 'asc' },
      select: { id: true },
    });
    if (batch.length === 0) break;
    for (const c of batch) {
      await recomputeCustomer(c.id);
      total++;
    }
    cursor = batch[batch.length - 1].id;
    if (batch.length < batchSize) break;
  }
  return { total };
}

