/* ═════════════════════════ CREATE-ORDER MODAL ═════════════════════════
   Flow: pick customer (existing or new) → pick items → enter address &
   shipping → voucher/discount/gift wrap → confirm. All state in `oc`,
   summary recomputes on every change.
   ═══════════════════════════════════════════════════════════════════════ */
const GIFT_WRAP_FEE = 20000;
const SHIP_FEE_BY_METHOD = { standard: 30000, express: 55000, same_day: 85000, pickup: 0 };
const PROVINCE_DEFAULT = 'TP. Hồ Chí Minh';

const oc = {
  customer: null,       // {id,name,phone,email,tier?} | null
  newCust: false,
  items: [],            // [{productId, variantId?, name, priceUnit, qty}]
  voucher: null,        // resolved voucher object or null
  voucherError: '',
};

const modal = document.getElementById('ordCreateModal');
const $ = (id) => document.getElementById(id);

function openCreateModal(){
  // reset state
  oc.customer = null; oc.newCust = false; oc.items = []; oc.voucher = null; oc.voucherError = '';
  // reset inputs
  $('ocCustSearch').value = ''; $('ocCustResults').hidden = true; $('ocCustResults').innerHTML = '';
  $('ocNewCust').checked = false; $('ocCustNew').hidden = true;
  ['ocCustName','ocCustPhone','ocCustEmail'].forEach(id => $(id).value = '');
  $('ocCustSelected').hidden = true;
  $('ocProdSearch').value = ''; $('ocProdResults').hidden = true; $('ocProdResults').innerHTML = '';
  $('ocNoteCust').value = ''; $('ocNoteInt').value = '';
  ['ocShipName','ocShipPhone','ocShipLine1','ocShipWard','ocShipDistrict','ocRecipName','ocRecipPhone'].forEach(id => $(id).value = '');
  $('ocShipProvince').value = PROVINCE_DEFAULT;
  $('ocShipMethod').value = 'standard'; $('ocShipFee').value = String(SHIP_FEE_BY_METHOD.standard);
  $('ocPayMethod').value = 'cod'; $('ocChannel').value = '';
  $('ocVoucher').value = ''; $('ocVoucherStatus').textContent = ''; $('ocVoucherStatus').style.color = '';
  $('ocDiscountExtra').value = '0';
  $('ocGiftWrap').checked = false; $('ocGiftMsg').value = ''; $('ocGiftMsgWrap').hidden = true;
  document.querySelector('input[name="ocStatus"][value="pending"]').checked = true;
  renderItems(); renderSummary();
  modal.hidden = false; modal.setAttribute('aria-hidden','false');
  setTimeout(() => $('ocCustSearch').focus(), 30);
}
function closeCreateModal(){ modal.hidden = true; modal.setAttribute('aria-hidden','true'); }
modal.addEventListener('click', e => { if (e.target.matches('[data-close-create]')) closeCreateModal(); });

/* ---- Customer picker ------------------------------------------------ */
let custTimer = null;
$('ocCustSearch').addEventListener('input', e => {
  clearTimeout(custTimer);
  const q = e.target.value.trim().toLowerCase();
  if (!q) { $('ocCustResults').hidden = true; return; }
  custTimer = setTimeout(() => {
    const all = (window.DTX_ADMIN_CUSTOMERS?.all() || []);
    const results = all.filter(c =>
      (c.name || '').toLowerCase().includes(q) ||
      (c.phone || '').includes(q) ||
      (c.email || '').toLowerCase().includes(q)
    ).slice(0, 10);
    const box = $('ocCustResults');
    if (!results.length) {
      box.innerHTML = `<div class="cust-result muted">Không có KH khớp · tích "Khách mới" để nhập tay</div>`;
    } else {
      box.innerHTML = results.map(c => `
        <div class="cust-result" data-cust="${c.id}">
          <strong>${c.name}</strong>
          <small>${c.phone || ''} · ${c.email || ''} · ${c.province || ''}</small>
          ${c.tags?.includes('VIP') ? '<span class="pill pill-vip">VIP</span>' : ''}
        </div>`).join('');
    }
    box.hidden = false;
  }, 160);
});
$('ocCustResults').addEventListener('click', e => {
  const row = e.target.closest('[data-cust]'); if (!row) return;
  const c = window.DTX_ADMIN_CUSTOMERS.get(row.dataset.cust); if (!c) return;
  selectCustomer(c);
});
function selectCustomer(c){
  oc.customer = c;
  $('ocCustSelected').hidden = false;
  $('ocCustSelName').textContent = c.name;
  $('ocCustSelMeta').textContent = `· ${c.phone || '—'} · ${c.email || '—'}`;
  const tierEl = $('ocCustTier');
  if (c.tags?.includes('VIP')) { tierEl.textContent = 'VIP'; tierEl.hidden = false; }
  else tierEl.hidden = true;
  $('ocCustSearch').value = ''; $('ocCustResults').hidden = true;
  $('ocNewCust').checked = false; $('ocCustNew').hidden = true;
  // pre-fill shipping from customer
  if (!$('ocShipName').value) $('ocShipName').value = c.name || '';
  if (!$('ocShipPhone').value) $('ocShipPhone').value = c.phone || '';
  if (!$('ocShipProvince').value || $('ocShipProvince').value === PROVINCE_DEFAULT)
    $('ocShipProvince').value = c.province || PROVINCE_DEFAULT;
}
$('ocCustClear').addEventListener('click', e => {
  e.preventDefault();
  oc.customer = null; $('ocCustSelected').hidden = true;
  $('ocCustSearch').focus();
});
$('ocNewCust').addEventListener('change', e => {
  oc.newCust = e.target.checked;
  $('ocCustNew').hidden = !oc.newCust;
  if (oc.newCust) { oc.customer = null; $('ocCustSelected').hidden = true; }
});

/* ---- Product picker ------------------------------------------------ */
let prodTimer = null;
$('ocProdSearch').addEventListener('input', e => {
  clearTimeout(prodTimer);
  const q = e.target.value.trim().toLowerCase();
  if (!q) { $('ocProdResults').hidden = true; return; }
  prodTimer = setTimeout(() => {
    const all = (window.DTX_ADMIN?.all() || []);
    const results = all.filter(p =>
      p.status === 'active' &&
      ((p.name || '').toLowerCase().includes(q) ||
       (p.code || '').toLowerCase().includes(q) ||
       (p.category || '').toLowerCase().includes(q))
    ).slice(0, 10);
    const box = $('ocProdResults');
    if (!results.length) {
      box.innerHTML = `<div class="prod-result muted">Không có SP khớp</div>`;
    } else {
      box.innerHTML = results.map(p => `
        <div class="prod-result" data-prod="${p.id}">
          <strong>${p.name}</strong>
          <small>${p.code} · ${F.vnd(p.price)} · Tồn ${p.stock}</small>
        </div>`).join('');
    }
    box.hidden = false;
  }, 160);
});
$('ocProdResults').addEventListener('click', e => {
  const row = e.target.closest('[data-prod]'); if (!row) return;
  const p = window.DTX_ADMIN.get(row.dataset.prod); if (!p) return;
  addItem(p);
  $('ocProdSearch').value = ''; $('ocProdResults').hidden = true; $('ocProdSearch').focus();
});
function addItem(p){
  const existing = oc.items.find(x => x.productId === p.id);
  if (existing) { existing.qty += 1; }
  else { oc.items.push({ productId: p.id, name: p.name, priceUnit: Number(p.price || 0), qty: 1 }); }
  renderItems(); renderSummary();
}
function renderItems(){
  const body = $('ocItemBody');
  if (!oc.items.length) {
    body.innerHTML = `<tr><td colspan="5" class="muted" style="text-align:center;padding:16px">Chưa có sản phẩm</td></tr>`;
    return;
  }
  body.innerHTML = oc.items.map((it, idx) => `
    <tr>
      <td><strong>${it.name}</strong></td>
      <td style="text-align:right">${F.vnd(it.priceUnit)}</td>
      <td>
        <div style="display:flex;gap:4px;align-items:center">
          <button class="icon-btn" data-qty="-1" data-idx="${idx}">−</button>
          <input type="number" min="1" value="${it.qty}" data-qty-input="${idx}" style="width:50px;text-align:center" />
          <button class="icon-btn" data-qty="1" data-idx="${idx}">+</button>
        </div>
      </td>
      <td style="text-align:right"><strong>${F.vnd(it.priceUnit * it.qty)}</strong></td>
      <td><button class="icon-btn" data-rm="${idx}" title="Xoá"><i class="fa-solid fa-trash"></i></button></td>
    </tr>`).join('');
}
$('ocItemBody').addEventListener('click', e => {
  const q = e.target.closest('[data-qty]');
  if (q) {
    const idx = Number(q.dataset.idx); const d = Number(q.dataset.qty);
    oc.items[idx].qty = Math.max(1, oc.items[idx].qty + d);
    renderItems(); renderSummary();
    return;
  }
  const rm = e.target.closest('[data-rm]');
  if (rm) {
    oc.items.splice(Number(rm.dataset.rm), 1); renderItems(); renderSummary();
  }
});
$('ocItemBody').addEventListener('change', e => {
  const inp = e.target.closest('[data-qty-input]');
  if (inp) {
    const idx = Number(inp.dataset.qtyInput);
    const v = Math.max(1, Number(inp.value) || 1);
    oc.items[idx].qty = v; renderItems(); renderSummary();
  }
});

/* ---- Shipping / gift / voucher ------------------------------------- */
$('ocShipMethod').addEventListener('change', e => {
  const fee = SHIP_FEE_BY_METHOD[e.target.value] ?? 30000;
  $('ocShipFee').value = String(fee);
  renderSummary();
});
$('ocShipFee').addEventListener('input', renderSummary);
$('ocDiscountExtra').addEventListener('input', renderSummary);
$('ocGiftWrap').addEventListener('change', e => {
  $('ocGiftMsgWrap').hidden = !e.target.checked;
  renderSummary();
});

$('ocVoucherCheck').addEventListener('click', () => {
  const code = $('ocVoucher').value.trim().toUpperCase();
  const status = $('ocVoucherStatus');
  oc.voucher = null; oc.voucherError = '';
  if (!code) { status.textContent = 'Chưa nhập mã voucher.'; status.style.color = ''; renderSummary(); return; }
  const all = (window.DTX_ADMIN_VOUCHERS?.all() || []);
  const v = all.find(x => x.code === code);
  if (!v) { oc.voucherError = 'Voucher không tồn tại.'; }
  else if (v.status !== 'active') { oc.voucherError = `Voucher ${v.status === 'scheduled' ? 'chưa tới ngày áp dụng' : 'đã hết hạn/bị khoá'}.`; }
  else {
    const now = new Date();
    if (v.startAt && new Date(v.startAt) > now) { oc.voucherError = 'Voucher chưa tới ngày áp dụng.'; }
    else if (v.endAt && new Date(v.endAt) < now) { oc.voucherError = 'Voucher đã hết hạn.'; }
    else if (v.usageLimit != null && v.usedCount >= v.usageLimit) { oc.voucherError = 'Voucher đã hết lượt dùng.'; }
    else {
      const sub = oc.items.reduce((s,i)=>s + i.priceUnit * i.qty, 0);
      if (v.minOrder && sub < v.minOrder) { oc.voucherError = `Đơn tối thiểu ${F.vnd(v.minOrder)}, hiện ${F.vnd(sub)}.`; }
      else { oc.voucher = v; }
    }
  }
  if (oc.voucher) {
    status.textContent = `✓ ${oc.voucher.description || oc.voucher.code} — đã áp dụng.`;
    status.style.color = 'var(--a-ok, #15803d)';
  } else {
    status.textContent = '✗ ' + oc.voucherError;
    status.style.color = 'var(--a-bad, #b91c1c)';
  }
  renderSummary();
});

function computeTotals(){
  const subtotal = oc.items.reduce((s, i) => s + i.priceUnit * i.qty, 0);
  const shippingFee = Math.max(0, Number($('ocShipFee').value) || 0);
  const giftWrapFee = $('ocGiftWrap').checked ? GIFT_WRAP_FEE : 0;
  const extra = Math.max(0, Number($('ocDiscountExtra').value) || 0);
  let voucherDisc = 0; let voucherShip = 0;
  if (oc.voucher) {
    if (oc.voucher.type === 'percent') voucherDisc = Math.floor(subtotal * oc.voucher.value / 100);
    else if (oc.voucher.type === 'amount') voucherDisc = Number(oc.voucher.value || 0);
    else if (oc.voucher.type === 'shipping') voucherShip = shippingFee;
  }
  const discountTotal = Math.min(subtotal, voucherDisc + extra);
  const realShip = Math.max(0, shippingFee - voucherShip);
  const total = Math.max(0, subtotal - discountTotal + realShip + giftWrapFee);
  return { subtotal, discountTotal, shippingFee: realShip, giftWrapFee, total };
}

function renderSummary(){
  const t = computeTotals();
  $('ocSumSub').textContent = F.vnd(t.subtotal);
  $('ocSumDisc').textContent = '−' + F.vnd(t.discountTotal);
  $('ocSumShip').textContent = F.vnd(t.shippingFee);
  $('ocSumGift').textContent = F.vnd(t.giftWrapFee);
  $('ocSumTotal').textContent = F.vnd(t.total);
}

/* ---- Submit -------------------------------------------------------- */
$('ocSubmit').addEventListener('click', () => {
  // Validate
  let customer = null;
  if (oc.customer) customer = oc.customer;
  else if (oc.newCust) {
    const name = $('ocCustName').value.trim();
    const phone = $('ocCustPhone').value.trim();
    if (!name || !phone) { window.admToast?.('Nhập họ tên + SĐT khách mới', 'bad'); return; }
    customer = { name, phone, email: $('ocCustEmail').value.trim() || null };
  } else {
    window.admToast?.('Chọn khách hoặc tích "Khách mới"', 'bad'); return;
  }
  if (!oc.items.length) { window.admToast?.('Thêm ít nhất 1 sản phẩm', 'bad'); return; }
  const shipName = $('ocShipName').value.trim();
  const shipPhone = $('ocShipPhone').value.trim();
  const shipLine1 = $('ocShipLine1').value.trim();
  const shipProvince = $('ocShipProvince').value.trim();
  if (!shipName || !shipPhone || !shipLine1 || !shipProvince) {
    window.admToast?.('Điền đủ địa chỉ giao (người nhận, SĐT, địa chỉ, tỉnh)', 'bad'); return;
  }

  const t = computeTotals();
  const status = document.querySelector('input[name="ocStatus"]:checked')?.value || 'pending';
  const recipName = $('ocRecipName').value.trim();
  const recipPhone = $('ocRecipPhone').value.trim();

  const items = oc.items.map(i => ({
    productId: i.productId,
    name: i.name,
    priceUnit: i.priceUnit,
    qty: i.qty,
    subtotal: i.priceUnit * i.qty,
  }));

  const orderPayload = {
    customer: {
      id: customer.id || undefined,
      name: customer.name,
      phone: customer.phone,
      email: customer.email || null,
      province: shipProvince,
    },
    items,
    subtotal: t.subtotal,
    discountTotal: t.discountTotal,
    shippingFee: t.shippingFee,
    giftWrapFee: t.giftWrapFee,
    total: t.total,
    status,
    paymentStatus: 'pending',
    paymentMethod: $('ocPayMethod').value,
    shippingMethod: $('ocShipMethod').value,
    shippingAddress: {
      fullName: shipName,
      phone: shipPhone,
      province: shipProvince,
      district: $('ocShipDistrict').value.trim(),
      ward: $('ocShipWard').value.trim(),
      line1: shipLine1,
      recipientName: recipName || null,
      recipientPhone: recipPhone || null,
    },
    voucherCode: oc.voucher?.code || null,
    notes: $('ocNoteCust').value.trim(),
    internalNote: $('ocNoteInt').value.trim(),
    giftWrap: $('ocGiftWrap').checked,
    giftMessage: $('ocGiftMsg').value.trim() || null,
    source: 'admin',
    channel: $('ocChannel').value || null,
  };

  // Create customer if new + persist
  if (oc.newCust && window.DTX_ADMIN_CUSTOMERS) {
    const existing = window.DTX_ADMIN_CUSTOMERS.all().find(c =>
      (customer.phone && c.phone === customer.phone) ||
      (customer.email && c.email === customer.email)
    );
    if (!existing) {
      const created = window.DTX_ADMIN_CUSTOMERS.create({
        name: customer.name, phone: customer.phone, email: customer.email,
        province: shipProvince,
      });
      orderPayload.customer.id = created.id;
    } else {
      orderPayload.customer.id = existing.id;
    }
  }

  // Increment voucher usage (local simulation)
  if (oc.voucher && window.DTX_ADMIN_VOUCHERS) {
    window.DTX_ADMIN_VOUCHERS.update(oc.voucher.id, { usedCount: (oc.voucher.usedCount || 0) + 1 });
  }

  const created = S.create(orderPayload);
  closeCreateModal();
  render();
  window.admToast?.(`Đã tạo đơn ${created.code} (${S.statusLabel(status)})`, 'ok');
});

document.getElementById('btnOrderCreate').addEventListener('click', openCreateModal);
document.addEventListener('keydown', e => {
  if (e.key === 'Escape' && !modal.hidden) closeCreateModal();
});

