/* ═══════════════════════════════════════════════════════════════════
   ORDER CREATE-MODAL (admin-orders.html)
   ─────────────────────────────────────────────────────────────────── */
.adm-modal-card.adm-modal-lg{ width:min(1120px,100%) }
.adm-modal-foot{
  display:flex;justify-content:flex-end;gap:8px;
  padding:12px 18px;border-top:1px solid var(--a-line);background:var(--a-surface-2);
}
.create-grid{
  display:grid;gap:20px;
  grid-template-columns:1.1fr 1fr;
}
@media (max-width:860px){ .create-grid{ grid-template-columns:1fr } }
.create-col{ display:flex;flex-direction:column;gap:10px }
.create-col h4{
  margin:6px 0 2px;font-size:12.5px;font-weight:600;color:var(--a-ink);
  text-transform:uppercase;letter-spacing:.4px;
  border-bottom:1px dashed var(--a-line);padding-bottom:4px;
}
.create-col label{
  display:flex;flex-direction:column;gap:3px;
  font-size:12px;color:var(--a-ink-3);font-weight:500;
}
.create-col label > input,
.create-col label > select,
.create-col label > textarea,
.create-col > input,
.create-col > select,
.create-col > textarea{
  height:36px;padding:0 11px;font-size:13px;
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:8px;color:var(--a-ink);font-family:inherit;
}
.create-col textarea{ height:auto;min-height:56px;padding:8px 11px;resize:vertical }
.create-col input:focus, .create-col select:focus, .create-col textarea:focus{
  outline:none;border-color:var(--a-brand);box-shadow:0 0 0 3px var(--a-brand-soft);
}

/* Customer picker */
.cust-picker{ position:relative;display:flex;flex-direction:column;gap:6px }
.cust-picker .field.search{ position:relative }
.cust-picker .field.search i{
  position:absolute;left:10px;top:50%;transform:translateY(-50%);
  color:var(--a-ink-3);font-size:12px;pointer-events:none;
}
.cust-picker .field.search input{
  width:100%;height:36px;padding:0 12px 0 30px;font-size:13px;
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:8px;color:var(--a-ink);font-family:inherit;
}
.cust-picker .field.search input:focus{
  outline:none;border-color:var(--a-brand);box-shadow:0 0 0 3px var(--a-brand-soft);
}
.cust-results, .prod-results{
  background:var(--a-surface);border:1px solid var(--a-line);border-radius:8px;
  max-height:220px;overflow:auto;box-shadow:var(--a-shadow-sm);
}
.cust-result, .prod-result{
  padding:8px 10px;font-size:12.5px;cursor:pointer;
  border-bottom:1px solid var(--a-line);display:flex;flex-direction:column;gap:2px;
}
.cust-result:last-child, .prod-result:last-child{ border-bottom:none }
.cust-result:hover, .prod-result:hover{ background:var(--a-brand-soft) }
.cust-result.muted, .prod-result.muted{ color:var(--a-ink-3);font-style:italic;cursor:default;text-align:center }
.cust-result strong, .prod-result strong{ font-size:13px;color:var(--a-ink) }
.cust-result small, .prod-result small{ color:var(--a-ink-3);font-size:11.5px }
.cust-new-toggle{
  flex-direction:row !important;align-items:center;gap:6px;
  font-size:12px;color:var(--a-ink-2);cursor:pointer;
}
.cust-new{
  border:1px dashed var(--a-brand);background:var(--a-brand-soft);
  border-radius:8px;padding:10px;display:flex;flex-direction:column;gap:8px;
}
.cust-selected{
  display:flex;align-items:center;gap:8px;flex-wrap:wrap;
  padding:8px 10px;border:1px solid var(--a-line);border-radius:8px;
  background:var(--a-surface-2);font-size:13px;
}
.cust-selected strong{ color:var(--a-ink) }
.cust-selected .muted{ color:var(--a-ink-3);font-size:12px }
.cust-selected .pill{ padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600;background:var(--a-brand);color:#fff }
.pill.pill-vip{ background:linear-gradient(90deg,#f59e0b,#d97706);color:#fff }
.linkish{
  background:none;border:none;color:var(--a-brand);cursor:pointer;
  font-size:12px;text-decoration:underline;padding:0;margin-left:auto;
}
.linkish:hover{ color:var(--a-brand-ink) }

/* Product picker */
.prod-picker{ position:relative;display:flex;flex-direction:column;gap:6px }
.prod-picker .field.search{ position:relative }
.prod-picker .field.search i{
  position:absolute;left:10px;top:50%;transform:translateY(-50%);
  color:var(--a-ink-3);font-size:12px;pointer-events:none;
}
.prod-picker .field.search input{
  width:100%;height:36px;padding:0 12px 0 30px;font-size:13px;
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:8px;color:var(--a-ink);font-family:inherit;
}
.prod-picker .field.search input:focus{
  outline:none;border-color:var(--a-brand);box-shadow:0 0 0 3px var(--a-brand-soft);
}

/* Item table */
.adm-tbl.item-tbl{ font-size:12.5px }
.adm-tbl.item-tbl th{ padding:6px 8px;font-size:11px }
.adm-tbl.item-tbl td{ padding:6px 8px;vertical-align:middle }
.adm-tbl.item-tbl .icon-btn{
  width:26px;height:26px;border-radius:6px;
  background:var(--a-surface-2);border:1px solid var(--a-line);
  color:var(--a-ink-2);cursor:pointer;font-size:11px;
  display:inline-grid;place-items:center;
}
.adm-tbl.item-tbl .icon-btn:hover{ background:var(--a-brand-soft);color:var(--a-brand-ink);border-color:var(--a-brand) }

/* Alt recipient */
.alt-recipient summary{
  cursor:pointer;font-size:12px;color:var(--a-ink-2);padding:4px 0;
  list-style:none;display:flex;align-items:center;gap:6px;
}
.alt-recipient summary::before{ content:'▶';font-size:9px;transition:transform .2s }
.alt-recipient[open] summary::before{ transform:rotate(90deg) }
.alt-recipient[open]{ padding:8px 10px;background:var(--a-surface-2);border:1px solid var(--a-line);border-radius:8px }

/* Radio group (status picker) */
.radio-group{
  display:flex;flex-direction:column;gap:6px;
  padding:8px 10px;background:var(--a-surface-2);border:1px solid var(--a-line);
  border-radius:8px;
}
.radio-group label{
  flex-direction:row !important;align-items:center;gap:8px;
  font-size:12.5px;color:var(--a-ink-2);cursor:pointer;
}
.radio-group input[type="radio"]{ margin:0;cursor:pointer }
.radio-group b{ color:var(--a-ink);font-weight:600 }

/* Checkbox wrapper */
.chk{
  flex-direction:row !important;align-items:center;gap:8px;
  font-size:13px;color:var(--a-ink-2);cursor:pointer;padding:4px 0;
}
.chk input{ margin:0;cursor:pointer }

/* Summary box */
.summary-box{
  background:var(--a-surface-2);border:1px solid var(--a-line);
  border-radius:10px;padding:12px 14px;
  display:flex;flex-direction:column;gap:6px;font-size:13px;
  margin-top:6px;
}
.summary-box > div{
  display:flex;justify-content:space-between;align-items:center;
  color:var(--a-ink-2);
}
.summary-box > div strong{ color:var(--a-ink);font-weight:600 }
.summary-box > div.total{
  margin-top:4px;padding-top:8px;border-top:1px dashed var(--a-line);
  font-size:15px;
}
.summary-box > div.total span{ color:var(--a-ink);font-weight:600 }
.summary-box > div.total strong{ color:var(--a-brand);font-weight:700;font-size:17px }

