1	<!DOCTYPE html>
2	<html lang="vi">
3	<head>
4	<meta charset="UTF-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1.0" />
6	<title>Khách hàng — Detoxblanc Admin</title>
7	<meta name="description" content="Danh sách khách hàng Detoxblanc — phân khúc, tag, xuất CSV." />
8	<meta name="robots" content="noindex,nofollow,noarchive,nosnippet" />
9	<meta http-equiv="X-Frame-Options" content="DENY" />
10	<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
11	<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" />
12	<link rel="stylesheet" href="assets/admin.css" />
13	</head>
14	
15	<body data-adm-page="customers">
16	<a class="skip-link" href="#adm-content">Đi tới nội dung chính</a>
17	
18	<div class="adm-app">
19	  <div data-adm-shell
20	       data-crumbs='[{"label":"Admin","href":"admin.html"},{"label":"Bán hàng"},{"label":"Khách hàng"}]'
21	       data-title="Khách hàng"></div>
22	
23	  <div class="adm-canvas">
24	    <main class="adm-page" id="adm-content">
25	
26	      <div class="adm-page-head">
27	        <div>
28	          <h1>Khách hàng</h1>
29	          <p>Quản lý <strong id="cusCount">—</strong> khách hàng. Phân khúc theo tag, chi tiêu, số đơn.</p>
30	        </div>
31	        <div class="adm-head-actions">
32	          <button class="adm-btn" id="btnCusReset"><i class="fa-solid fa-rotate-left"></i> Đặt lại</button>
33	          <button class="adm-btn" id="btnCusExport"><i class="fa-solid fa-file-export"></i> Xuất CSV</button>
34	          <button class="adm-btn primary" id="btnCusCreate"><i class="fa-solid fa-plus"></i> Thêm khách hàng</button>
35	        </div>
36	      </div>
37	
38	      <div class="stat-grid">
39	        <div class="stat-card"><span class="lbl">Tổng khách</span><strong id="statCusTotal">0</strong></div>
40	        <div class="stat-card"><span class="lbl">VIP</span><strong id="statCusVip">0</strong></div>
41	        <div class="stat-card"><span class="lbl">Newsletter</span><strong id="statCusNl">0</strong></div>
42	        <div class="stat-card"><span class="lbl">CLV trung bình</span><strong id="statCusClv">—</strong></div>
43	      </div>
44	
45	      <div class="pr-filter-bar card" role="search">
46	        <div class="field search">
47	          <i class="fa-solid fa-magnifying-glass"></i>
48	          <input type="search" id="cusQ" placeholder="Tên, email, SĐT…" aria-label="Tìm khách hàng" />
49	        </div>
50	        <div class="field"><select id="cusTag"><option value="">Tất cả tag</option></select></div>
51	        <div class="field"><select id="cusProv"><option value="">Tất cả tỉnh/TP</option></select></div>
52	        <div class="field"><select id="cusSort">
53	          <option value="new">Khách mới nhất</option>
54	          <option value="spend-desc">Chi tiêu cao → thấp</option>
55	          <option value="orders-desc">Đơn nhiều → ít</option>
56	          <option value="name">Tên A→Z</option>
57	        </select></div>
58	      </div>
59	
60	      <div class="card">
61	        <table class="adm-tbl" id="cusTable">
62	          <thead>
63	            <tr>
64	              <th>Tên</th><th>Email / SĐT</th><th>Tỉnh/TP</th><th>Tags</th>
65	              <th style="text-align:right">Chi tiêu</th><th style="text-align:right">Đơn</th>
66	              <th>Tạo lúc</th><th></th>
67	            </tr>
68	          </thead>
69	          <tbody id="cusTbody"></tbody>
70	        </table>
71	        <div class="empty-state" id="cusEmpty" hidden>
72	          <i class="fa-solid fa-user-slash"></i>
73	          <p>Không có khách hàng nào khớp bộ lọc.</p>
74	        </div>
75	      </div>
76	
77	      <div class="pager" id="cusPager"></div>
78	    </main>
79	  </div>
80	</div>
81	
82	<script src="assets/admin-data.js"></script>
83	<script src="assets/admin-data-ext.js"></script>
84	<script src="assets/admin-shell.js"></script>
85	<script>
86	(function(){
87	  const S = window.DTX_ADMIN_CUSTOMERS;
88	  const F = window.DTX_ADMIN_FMT;
89	  const state = { page:1, q:'', tag:'', province:'', sort:'new', perPage:20 };
90	
91	  function render(){
92	    const all = S.all();
93	    // populate selects with distinct tags + provinces
94	    const tags = new Set(), provs = new Set();
95	    all.forEach(c => { (c.tags||[]).forEach(t => tags.add(t)); if (c.province) provs.add(c.province); });
96	    syncSelect('cusTag', tags, state.tag);
97	    syncSelect('cusProv', provs, state.province);
98	
99	    const q = state.q.trim().toLowerCase();
100	    let list = all.filter(c => {
101	      if (q && !(c.name.toLowerCase().includes(q) || (c.email||'').toLowerCase().includes(q) || (c.phone||'').includes(q))) return false;
102	      if (state.tag && !c.tags.includes(state.tag)) return false;
103	      if (state.province && c.province !== state.province) return false;
104	      return true;
105	    });
106	    list.sort((a,b) => {
107	      switch(state.sort){
108	        case 'spend-desc': return b.spend - a.spend;
109	        case 'orders-desc': return b.orders - a.orders;
110	        case 'name': return a.name.localeCompare(b.name, 'vi');
111	        default: return new Date(b.createdAt) - new Date(a.createdAt);
112	      }
113	    });
114	
115	    document.getElementById('cusCount').textContent = all.length.toLocaleString('vi-VN');
116	    document.getElementById('statCusTotal').textContent = all.length;
117	    document.getElementById('statCusVip').textContent = all.filter(c=>c.tags.includes('VIP')).length;
118	    document.getElementById('statCusNl').textContent = all.filter(c=>c.tags.includes('Newsletter')).length;
119	    const clv = all.length ? Math.round(all.reduce((s,c)=>s+c.spend,0)/all.length) : 0;
120	    document.getElementById('statCusClv').textContent = F.vnd(clv);
121	
122	    const totalPages = Math.max(1, Math.ceil(list.length / state.perPage));
123	    if (state.page > totalPages) state.page = totalPages;
124	    const slice = list.slice((state.page-1)*state.perPage, state.page*state.perPage);
125	
126	    const tbody = document.getElementById('cusTbody');
127	    const empty = document.getElementById('cusEmpty');
128	    if (!slice.length) { tbody.innerHTML=''; empty.hidden=false; }
129	    else {
130	      empty.hidden = true;
131	      tbody.innerHTML = slice.map(c => {
132	        const initials = c.name.split(' ').slice(-2).map(w=>w[0]).join('').toUpperCase();
133	        return `<tr data-id="${c.id}">
134	          <td><div class="user-cell"><span class="avatar-sm">${initials}</span><div><strong>${c.name}</strong><small class="muted">${c.dob ? 'DOB: '+c.dob : 'Khách từ '+F.date(c.createdAt)}</small></div></div></td>
135	          <td><small>${c.email || '—'}<br><span class="muted">${c.phone || ''}</span></small></td>
136	          <td>${c.province || '—'}</td>
137	          <td>${(c.tags||[]).map(t=>`<span class="chip ${t==='VIP'?'accent':''}">${t}</span>`).join(' ') || '—'}</td>
138	          <td style="text-align:right"><strong>${F.vnd(c.spend)}</strong></td>
139	          <td style="text-align:right">${c.orders}</td>
140	          <td><small>${F.date(c.createdAt)}</small></td>
141	          <td style="text-align:right">
142	            <button class="icon-btn" data-edit="${c.id}" title="Sửa"><i class="fa-solid fa-pen"></i></button>
143	            <button class="icon-btn" data-del="${c.id}" title="Xoá"><i class="fa-solid fa-trash"></i></button>
144	          </td>
145	        </tr>`;
146	      }).join('');
147	    }
148	
149	    const pager = document.getElementById('cusPager');
150	    if (totalPages>1) {
151	      let h=''; for (let p=1;p<=totalPages;p++) h += `<button class="${p===state.page?'active':''}" data-page="${p}">${p}</button>`;
152	      pager.innerHTML = h;
153	    } else pager.innerHTML='';
154	  }
155	
156	  function syncSelect(id, values, current){
157	    const el = document.getElementById(id);
158	    const first = el.querySelector('option'); el.innerHTML = ''; el.appendChild(first);
159	    [...values].sort().forEach(v => {
160	      const o = document.createElement('option'); o.value = v; o.textContent = v;
161	      if (v === current) o.selected = true;
162	      el.appendChild(o);
163	    });
164	  }
165	
166	  document.getElementById('cusQ').addEventListener('input', e => { state.q = e.target.value; state.page=1; render(); });
167	  document.getElementById('cusTag').addEventListener('change', e => { state.tag = e.target.value; state.page=1; render(); });
168	  document.getElementById('cusProv').addEventListener('change', e => { state.province = e.target.value; state.page=1; render(); });
169	  document.getElementById('cusSort').addEventListener('change', e => { state.sort = e.target.value; render(); });
170	  document.getElementById('cusPager').addEventListener('click', e => {
171	    const b = e.target.closest('[data-page]'); if (b) { state.page = +b.dataset.page; render(); }
172	  });
173	
174	  document.getElementById('cusTbody').addEventListener('click', e => {
175	    const edit = e.target.closest('[data-edit]');
176	    if (edit) {
177	      const c = S.get(edit.dataset.edit); if (!c) return;
178	      const name = prompt('Tên:', c.name); if (name == null) return;
179	      const phone = prompt('SĐT:', c.phone || '');
180	      const email = prompt('Email:', c.email || '');
181	      const tagsStr = prompt('Tags (phân cách bằng dấu phẩy):', (c.tags||[]).join(', '));
182	      S.update(c.id, { name, phone, email, tags: (tagsStr||'').split(',').map(s=>s.trim()).filter(Boolean) });
183	      render();
184	      window.admToast?.('Đã cập nhật khách hàng', 'ok');
185	    }
186	    const del = e.target.closest('[data-del]');
187	    if (del) {
188	      const c = S.get(del.dataset.del);
189	      if (c && confirm(`Xoá khách ${c.name}?`)) { S.remove(c.id); render(); window.admToast?.('Đã xoá', 'ok'); }
190	    }
191	  });
192	
193	  document.getElementById('btnCusReset').addEventListener('click', () => {
194	    if (confirm('Đặt lại dữ liệu khách hàng?')) { S.reset(); render(); window.admToast?.('Reset OK', 'ok'); }
195	  });
196	  document.getElementById('btnCusCreate').addEventListener('click', () => {
197	    const name = prompt('Tên khách:'); if (!name) return;
198	    const phone = prompt('SĐT:') || '';
199	    const email = prompt('Email:') || '';
200	    const province = prompt('Tỉnh/TP:') || '';
201	    S.create({ name, phone, email, province });
202	    render();
203	    window.admToast?.('Đã thêm khách', 'ok');
204	  });
205	  document.getElementById('btnCusExport').addEventListener('click', () => {
206	    const all = S.all();
207	    const esc = s => '"'+String(s??'').replace(/"/g,'""')+'"';
208	    const rows = all.map(c => [c.name,c.email,c.phone,c.province,(c.tags||[]).join('|'),c.spend,c.orders,c.createdAt].map(esc).join(','));
209	    const csv = '\ufeff' + ['Tên,Email,SĐT,Tỉnh,Tags,ChiTiêu,Đơn,TạoLúc', ...rows].join('\n');
210	    const url = URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
211	    const a = document.createElement('a'); a.href=url; a.download=`customers-${new Date().toISOString().slice(0,10)}.csv`; a.click();
212	    URL.revokeObjectURL(url);
213	  });
214	
215	  window.addEventListener('dtx:customers-updated', render);
216	  window.addEventListener('storage', e => { if (e.key?.startsWith('dtx_admin_customers')) render(); });
217	  render();
218	})();
219	</script>
220	</body></html>
