/* ═══════════════════════════════════════════════════════════════════
   RIGHT-SIDE DRAWER (orders + customers detail)
   ─────────────────────────────────────────────────────────────────── */
.drawer{
  position:fixed;inset:0;z-index:100;
  display:flex;justify-content:flex-end;
}
.drawer[hidden]{ display:none }
.drawer-backdrop{
  position:absolute;inset:0;
  background:rgba(15,23,42,.45);backdrop-filter:blur(2px);
}
.drawer-panel{
  position:relative;z-index:1;
  width:min(580px,100%);height:100%;
  background:var(--a-surface);
  display:flex;flex-direction:column;
  box-shadow:-20px 0 60px rgba(15,23,42,.18);
  animation:drawerIn .22s ease-out;
}
.drawer.drawer-wide .drawer-panel{ width:min(760px,100%) }
@keyframes drawerIn{ from{ transform:translateX(20px);opacity:.6 } to{ transform:none;opacity:1 } }
.drawer-panel > header{
  display:flex;justify-content:space-between;align-items:center;gap:10px;
  padding:14px 18px;border-bottom:1px solid var(--a-line);
}
.drawer-panel > header h3{ margin:0;font-size:15px;font-weight:600;display:flex;align-items:center;gap:6px;flex-wrap:wrap }
.drawer-close{
  background:none;border:1px solid var(--a-line);border-radius:8px;
  width:32px;height:32px;display:grid;place-items:center;cursor:pointer;
  color:var(--a-ink-2);
}
.drawer-close:hover{ background:var(--a-brand-soft);color:var(--a-brand-ink);border-color:var(--a-brand) }

.drawer-tabs{
  display:flex;gap:0;border-bottom:1px solid var(--a-line);
  background:var(--a-surface-2);overflow-x:auto;
}
.drawer-tab{
  background:none;border:none;cursor:pointer;
  padding:10px 14px;font-size:12.5px;color:var(--a-ink-3);
  border-bottom:2px solid transparent;white-space:nowrap;
  display:inline-flex;align-items:center;gap:6px;
}
.drawer-tab:hover{ color:var(--a-ink-2) }
.drawer-tab.active{
  color:var(--a-brand-ink);border-bottom-color:var(--a-brand);
  background:var(--a-surface);font-weight:600;
}
.drawer-body{
  padding:16px 18px;overflow:auto;flex:1;
  display:flex;flex-direction:column;gap:16px;
}
.drawer-section{
  display:flex;flex-direction:column;gap:10px;
  padding-bottom:14px;border-bottom:1px dashed var(--a-line);
}
.drawer-section:last-child{ border-bottom:none }
.drawer-section h4{
  margin:0 0 2px;font-size:12.5px;font-weight:600;color:var(--a-ink);
  text-transform:uppercase;letter-spacing:.4px;
}
.drawer-section label{
  display:flex;flex-direction:column;gap:3px;
  font-size:12px;color:var(--a-ink-3);font-weight:500;
}
.drawer-section label.chk{ flex-direction:row;align-items:center;gap:8px;color:var(--a-ink-2);font-size:13px }
.drawer-section label > input,
.drawer-section label > select,
.drawer-section label > textarea{
  height:36px;padding:0 11px;font-size:13px;
  background:var(--a-surface);border:1px solid var(--a-line);
  border-radius:8px;color:var(--a-ink);font-family:inherit;
}
.drawer-section label > textarea{ height:auto;min-height:60px;padding:8px 11px;resize:vertical }
.drawer-section label > input:focus,
.drawer-section label > select:focus,
.drawer-section label > textarea:focus{
  outline:none;border-color:var(--a-brand);box-shadow:0 0 0 3px var(--a-brand-soft);
}
.drawer-section .row-2{
  display:grid;grid-template-columns:1fr 1fr;gap:10px;
}
.adm-tbl.mini{ font-size:12.5px }
.adm-tbl.mini th{ padding:6px 8px;font-size:11px;font-weight:600;color:var(--a-ink-3) }
.adm-tbl.mini td{ padding:6px 8px }
.meta-list{
  display:grid;grid-template-columns:120px 1fr;gap:6px 12px;margin:0;font-size:12.5px;
}
.meta-list dt{ color:var(--a-ink-3) }
.meta-list dd{ margin:0;color:var(--a-ink) }

