.adm-tbl.mini th{ padding:6px 8px;font-size:11px;font-weight:600;color:var(--a-ink-3) }
.adm-tbl.mini td{ padding:6px 8px }
.meta-list{
  display:grid;grid-template-columns:120px 1fr;gap:6px 12px;margin:0;font-size:12.5px;
}
.meta-list dt{ color:var(--a-ink-3) }
.meta-list dd{ margin:0;color:var(--a-ink) }

/* ═══════════════════════════════════════════════════════════════════
   CUSTOMER-SPECIFIC: tier pills, addresses, timeline, loyalty box
   ─────────────────────────────────────────────────────────────────── */
.tier-pill{
  display:inline-flex;align-items:center;gap:4px;
  padding:2px 9px;border-radius:999px;font-size:11px;font-weight:600;
  background:#e7e5e4;color:#57534e;
}
.tier-pill.tier-bronze{ background:#fef3c7;color:#92400e }
.tier-pill.tier-silver{ background:#e5e7eb;color:#374151 }
.tier-pill.tier-gold{ background:linear-gradient(90deg,#fde68a,#fbbf24);color:#78350f }
.tier-pill.tier-plat{ background:linear-gradient(90deg,#dbeafe,#93c5fd);color:#1e3a8a }

.addr-list{
  list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px;
}
.addr-list li{
  display:flex;justify-content:space-between;align-items:flex-start;gap:10px;
  padding:10px 12px;border:1px solid var(--a-line);border-radius:10px;
  background:var(--a-surface-2);font-size:13px;
}
.addr-list li.muted{ color:var(--a-ink-3);font-style:italic;justify-content:center }
.addr-list li strong{ color:var(--a-ink) }
.addr-list li .badge{ margin-left:6px;font-size:10px;padding:1px 6px;border-radius:999px }
.addr-actions{ display:flex;gap:4px }

.comm-list{
  list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px;
}
.comm-list li.muted{ color:var(--a-ink-3);font-style:italic;padding:10px;text-align:center }
.comm-item{
  border-left:3px solid var(--a-brand);
  background:var(--a-surface-2);
  border-radius:0 10px 10px 0;
  padding:10px 12px;
}
.comm-item.comm-email{ border-left-color:#3b82f6 }
.comm-item.comm-sms{ border-left-color:#10b981 }
.comm-item.comm-call{ border-left-color:#f59e0b }
.comm-item.comm-chat{ border-left-color:#8b5cf6 }
.comm-item.comm-note{ border-left-color:#64748b }
.comm-head{
  display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12.5px;
}
.comm-head strong{ color:var(--a-ink);font-weight:600 }
.comm-head .muted{ color:var(--a-ink-3);font-size:11.5px }
.comm-body{
  margin-top:6px;color:var(--a-ink-2);font-size:13px;white-space:pre-wrap;line-height:1.5;
}

.loyalty-box{
  background:var(--a-surface-2);border:1px solid var(--a-line);
  border-radius:10px;padding:14px;
  display:flex;flex-direction:column;gap:8px;
}
.loyalty-top{ display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px }
.loyalty-bar{
  height:8px;border-radius:4px;background:#e5e7eb;overflow:hidden;
}
.loyalty-bar-fill{
  height:100%;background:linear-gradient(90deg,var(--a-brand),#fbbf24);
  transition:width .4s ease;
}
.consent-list{ list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:6px }
.consent-list li{ padding:8px 10px;border:1px solid var(--a-line);border-radius:8px;background:var(--a-surface-2) }

.user-cell{ display:flex;align-items:center;gap:8px }
.avatar-sm{
  width:32px;height:32px;border-radius:50%;
  background:var(--a-brand-soft);color:var(--a-brand-ink);
  display:grid;place-items:center;font-size:11px;font-weight:600;flex-shrink:0;
}
.user-cell small{ display:block;font-size:11px }
.user-cell a{ color:var(--a-ink);text-decoration:none;font-weight:600 }
.user-cell a:hover{ color:var(--a-brand);text-decoration:underline }

