2	<html lang="vi">
3	<head>
4	<meta charset="UTF-8" />
5	<meta name="viewport" content="width=device-width, initial-scale=1.0" />
6	<title>Kho hàng — Detoxblanc Admin</title>
7	<meta name="description" content="Theo dõi tồn kho Detoxblanc, cảnh báo ngưỡng an toàn, điều chỉnh thủ công." />
