9	<meta http-equiv="X-Frame-Options" content="DENY" />
10	<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet" />
11	<link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" />
12	<link rel="stylesheet" href="assets/admin.css" />
13	</head>
14	
15	<body data-adm-page="inventory">
16	<a class="skip-link" href="#adm-content">Đi tới nội dung chính</a>
17	
18	<div class="adm-app">
19	  <div data-adm-shell
20	       data-crumbs='[{"label":"Admin","href":"admin.html"},{"label":"Sản phẩm"},{"label":"Kho hàng"}]'
21	       data-title="Kho hàng"></div>
22	
23	  <div class="adm-canvas">
24	    <main class="adm-page" id="adm-content">
25	
26	      <div class="adm-page-head">
27	        <div>
28	          <h1>Kho hàng</h1>
29	          <p>Tồn kho theo SKU, cảnh báo thấp ngưỡng, điều chỉnh bằng phiếu nhập/xuất.</p>
30	        </div>
31	        <div class="adm-head-actions">
32	          <button class="adm-btn" id="btnInvExport"><i class="fa-solid fa-file-export"></i> Xuất tồn kho</button>
33	          <button class="adm-btn primary" id="btnInvRestock"><i class="fa-solid fa-truck-ramp-box"></i> Nhập kho hàng loạt</button>
34	        </div>
35	      </div>
36	
37	      <div class="stat-grid">
38	        <div class="stat-card"><span class="lbl">Tổng SKU</span><strong id="invTotal">0</strong></div>
39	        <div class="stat-card"><span class="lbl">Hết hàng</span><strong id="invOut" style="color:#C0392B">0</strong></div>
40	        <div class="stat-card"><span class="lbl">Thấp ngưỡng</span><strong id="invLow" style="color:#D97706">0</strong></div>
41	        <div class="stat-card"><span class="lbl">Tổng số lượng</span><strong id="invSum">0</strong></div>
42	      </div>
43	
44	      <div class="pr-filter-bar card">
45	        <div class="field search">
46	          <i class="fa-solid fa-magnifying-glass"></i>
47	          <input type="search" id="invQ" placeholder="Mã SKU, tên sản phẩm…" />
48	        </div>
49	        <div class="field"><select id="invState">
50	          <option value="">Tất cả trạng thái</option>
51	          <option value="out">Hết hàng</option>
52	          <option value="low">Thấp ngưỡng</option>
53	          <option value="ok">Còn hàng</option>
54	        </select></div>
55	        <div class="field"><select id="invCat"><option value="">Tất cả danh mục</option></select></div>
56	      </div>
57	
58	      <div class="card">
59	        <table class="adm-tbl" id="invTbl">
60	          <thead>
61	            <tr>
62	              <th>SKU</th><th>Sản phẩm</th><th>Danh mục</th>
63	              <th style="text-align:right">Ngưỡng</th>
64	              <th style="text-align:right">Tồn</th>
65	              <th>Trạng thái</th>
66	              <th style="width:260px">Điều chỉnh</th>
67	            </tr>
68	          </thead>
69	          <tbody id="invTbody"></tbody>
70	        </table>
71	        <div class="empty-state" id="invEmpty" hidden>
72	          <i class="fa-solid fa-box-open"></i><p>Không có SKU khớp bộ lọc.</p>
73	        </div>
74	      </div>
75	    </main>
76	  </div>
77	</div>
78	
79	<script src="assets/admin-data.js"></script>
80	<script src="assets/admin-data-ext.js"></script>
81	<script src="assets/admin-shell.js"></script>
82	<script>
83	(function(){
84	  const PR = window.DTX_ADMIN;
85	  const INV = window.DTX_ADMIN_INVENTORY;
86	  const state = { q:'', invState:'', cat:'' };
87	
88	  function render(){
89	    const products = PR.all();
90	    const summary = INV.summary(products);
91	    document.getElementById('invTotal').textContent = summary.total;
92	    document.getElementById('invOut').textContent = summary.out;
93	    document.getElementById('invLow').textContent = summary.low;
94	    document.getElementById('invSum').textContent = summary.stockTotal.toLocaleString('vi-VN');
95	
96	    // categories select
97	    const cats = new Set();
98	    products.forEach(p => p.category && cats.add(p.category));
99	    const catSel = document.getElementById('invCat');
100	    const first = catSel.querySelector('option'); catSel.innerHTML=''; catSel.appendChild(first);
101	    [...cats].sort().forEach(c => {
102	      const o = document.createElement('option'); o.value=c; o.textContent=c;
103	      if (c===state.cat) o.selected=true; catSel.appendChild(o);
104	    });
105	
106	    const q = state.q.trim().toLowerCase();
107	    let items = INV.forProducts(products);
108	    items = items.filter(x => {
109	      if (q && !(x.code.toLowerCase().includes(q) || x.name.toLowerCase().includes(q))) return false;
110	      if (state.invState && x.state !== state.invState) return false;
111	      if (state.cat && x.category !== state.cat) return false;
112	      return true;
113	    });
114	    items.sort((a,b) => (a.state==='out'?-2:a.state==='low'?-1:0) - (b.state==='out'?-2:b.state==='low'?-1:0));
115	
116	    const tbody = document.getElementById('invTbody');
117	    const empty = document.getElementById('invEmpty');
118	    if (!items.length) { tbody.innerHTML=''; empty.hidden=false; return; }
119	    empty.hidden = true;
120	    tbody.innerHTML = items.map(it => {
121	      const cls = it.state==='out' ? 'bad' : it.state==='low' ? 'warn' : 'ok';
122	      const label = it.state==='out' ? 'Hết hàng' : it.state==='low' ? 'Thấp ngưỡng' : 'Đủ hàng';
123	      return `<tr data-id="${it.id}">
124	        <td><code class="mono">${it.code}</code></td>
125	        <td><strong>${it.name}</strong></td>
126	        <td>${it.category || '—'}</td>
127	        <td style="text-align:right">${it.lowStock}</td>
128	        <td style="text-align:right"><strong>${it.stock}</strong></td>
129	        <td><span class="badge ${cls}">${label}</span></td>
130	        <td>
131	          <div class="stock-adjust">
132	            <button class="icon-btn" data-adj="${it.id}" data-delta="-1" title="−1"><i class="fa-solid fa-minus"></i></button>
133	            <input type="number" data-inp="${it.id}" value="${it.stock}" min="0" aria-label="Tồn kho mới" />
134	            <button class="icon-btn" data-adj="${it.id}" data-delta="1" title="+1"><i class="fa-solid fa-plus"></i></button>
135	            <button class="adm-btn sm" data-set="${it.id}"><i class="fa-solid fa-check"></i></button>
136	          </div>
137	        </td>
138	      </tr>`;
139	    }).join('');
140	  }
141	
142	  document.getElementById('invQ').addEventListener('input', e => { state.q = e.target.value; render(); });
143	  document.getElementById('invState').addEventListener('change', e => { state.invState = e.target.value; render(); });
144	  document.getElementById('invCat').addEventListener('change', e => { state.cat = e.target.value; render(); });
145	
146	  document.getElementById('invTbody').addEventListener('click', e => {
147	    const adj = e.target.closest('[data-adj]');
148	    if (adj) {
149	      const id = adj.dataset.adj;
150	      const delta = +adj.dataset.delta;
151	      const res = INV.adjust(id, delta, 'manual', 'Quick +/- button');
152	      if (res) window.admToast?.(`${res.before} → ${res.after}`, 'ok');
153	      render();
154	    }
155	    const set = e.target.closest('[data-set]');
156	    if (set) {
157	      const id = set.dataset.set;
158	      const inp = document.querySelector(`[data-inp="${id}"]`);
159	      const target = Math.max(0, +inp.value);
160	      const p = PR.get(id); if (!p) return;
161	      const delta = target - p.stock;
162	      const res = INV.adjust(id, delta, 'set', `Set to ${target}`);
163	      if (res) window.admToast?.(`Đặt tồn = ${res.after}`, 'ok');
164	      render();
165	    }
166	  });
167	
168	  document.getElementById('btnInvRestock').addEventListener('click', () => {
169	    const qty = Number(prompt('Nhập kho hàng loạt — cộng thêm cho MỌI SKU (số lượng):', '10'));
170	    if (!qty || qty <= 0) return;
171	    const prods = PR.all();
172	    prods.forEach(p => PR.update(p.id, { stock: p.stock + qty }));
173	    try { window.DTX_ADMIN_AUDIT.create({
174	      action: 'inventory.bulk.restock',
175	      actorEmail: 'admin@detoxblanc.com',
176	      entity: 'product', entityId: null,
177	      diff: { after: { qtyAdded: qty, skuCount: prods.length } },
178	    }); } catch(_){}
179	    render();
180	    window.admToast?.(`Đã +${qty} cho ${prods.length} SKU`, 'ok');
181	  });
182	
183	  document.getElementById('btnInvExport').addEventListener('click', () => {
184	    const items = INV.forProducts(PR.all());
185	    const esc = s => '"'+String(s??'').replace(/"/g,'""')+'"';
186	    const rows = items.map(x => [x.code,x.name,x.category,x.lowStock,x.stock,x.state].map(esc).join(','));
187	    const csv = '\ufeff' + ['SKU,Tên,DanhMục,Ngưỡng,Tồn,Trạng thái', ...rows].join('\n');
188	    const url = URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
189	    const a = document.createElement('a'); a.href=url; a.download=`inventory-${new Date().toISOString().slice(0,10)}.csv`; a.click();
190	    URL.revokeObjectURL(url);
191	  });
192	
193	  window.addEventListener('dtx:products-updated', render);
194	  window.addEventListener('storage', e => { if (e.key?.startsWith('dtx_admin_products')) render(); });
195	  render();
196	})();
197	</script>
198	</body></html>
