558	  const Settings = {
559	    KEY: 'dtx_admin_settings',
560	    defaults() { return JSON.parse(JSON.stringify(DEFAULT_SETTINGS)); },
561	    load() {
562	      try {
563	        const raw = localStorage.getItem(this.KEY);
564	        if (raw) return { ...this.defaults(), ...JSON.parse(raw) };
565	      } catch (_) {}
566	      return this.defaults();
567	    },
568	    save(patch) {
569	      const current = this.load();
570	      const merged = { ...current, ...patch, updatedAt: nowISO() };
571	      localStorage.setItem(this.KEY, JSON.stringify(merged));
572	      window.dispatchEvent(new CustomEvent('dtx:settings-updated'));
573	      return merged;
574	    },
575	    reset() {
576	      localStorage.removeItem(this.KEY);
577	      window.dispatchEvent(new CustomEvent('dtx:settings-updated'));
578	      return this.defaults();
579	    },
580	  };
581	
582	  /* ───────────────── Inventory helpers ────────────────────────── */
583	
584	  const Inventory = {
585	    STATUSES: ['ok', 'low', 'out'],
586	    forProducts(products) {
587	      return products.map(p => ({
588	        id: p.id, code: p.code, name: p.name, category: p.category, stock: p.stock,
589	        lowStock: p.lowStock, status: p.status,
590	        state: p.stock === 0 ? 'out' : p.stock <= p.lowStock ? 'low' : 'ok',
591	      }));
592	    },
593	    summary(products) {
594	      const items = this.forProducts(products);
595	      return {
596	        total: items.length,
597	        out: items.filter(x => x.state === 'out').length,
598	        low: items.filter(x => x.state === 'low').length,
599	        ok: items.filter(x => x.state === 'ok').length,
600	        stockTotal: items.reduce((s, x) => s + x.stock, 0),
601	      };
602	    },
603	    adjust(productId, delta, reason, note) {
604	      if (!window.DTX_ADMIN) return null;
605	      const p = window.DTX_ADMIN.get(productId);
606	      if (!p) return null;
607	      const next = Math.max(0, p.stock + delta);
608	      window.DTX_ADMIN.update(productId, { stock: next });
609	      // ghi vào audit local
610	      try {
611	        Audit.create({
612	          action: 'inventory.adjust',
613	          actorEmail: (window.DTX_ADMIN_ACTOR || 'admin@detoxblanc.com'),
614	          entity: 'product',
615	          entityId: productId,
616	          diff: { before: { stock: p.stock }, after: { stock: next }, reason, note },
617	        });
618	      } catch (_) {}
619	      return { before: p.stock, after: next };
620	    },
621	  };
622	
623	  /* ───────────────── Reviews ──────────────────────────────────── */
624	
625	  function seedReviews() {
626	    const names = ['Minh Anh', 'Thu Trang', 'Quốc Bảo', 'Thanh Thảo', 'Hải Yến', 'Khánh Linh', 'Đức Anh', 'Ngọc Hân', 'Phương Thảo', 'Quang Huy'];
627	    const bodies = [
628	      'Da mình dịu hẳn sau 2 tuần. Đóng gói chỉn chu, có thư cảm ơn viết tay.',
629	      'Texture mỏng nhẹ, thấm nhanh, không bí da. Sẽ mua lại.',
630	      'Giá hơi cao nhưng chất lượng xứng đáng.',
631	      'Sản phẩm tốt nhưng mùi hơi nồng với mình.',
632	      'Tư vấn viên rất tận tâm, freeship HCM là điểm cộng.',
633	      'Hiệu quả rõ rệt sau 1 tháng dùng đều đặn.',
634	    ];
635	    const out = [];
636	    for (let i = 0; i < 32; i++) {
637	      out.push({
638	        id: uid('rv'),
639	        productId: 'prd_' + (1 + (i % 6)),
640	        productName: ['Tẩy trang dịu nhẹ','Gel rửa mặt PHA','Toner niacinamide','Serum B5','Kem chống nắng SPF50','Dưỡng ẩm cấp ẩm'][i % 6],
641	        rating: 3 + (i % 3), // 3-5 sao
642	        title: ['Rất tốt!','Đáng tiền','Sẽ mua lại','Ổn áp','Tuyệt vời'][i % 5],
643	        body: bodies[i % bodies.length],
644	        status: i % 7 === 0 ? 'pending' : i % 11 === 0 ? 'rejected' : 'approved',
645	        authorName: names[i % names.length],
646	        verified: i % 3 !== 0,
647	        createdAt: new Date(Date.now() - i * 4 * 3600_000).toISOString(),
648	      });
649	    }
650	    return out;
651	  }
652	
653	  function normalizeReview(r, i) {
654	    return {
655	      id: r.id || uid('rv'),
656	      productId: r.productId || 'prd_0',
657	      productName: r.productName || 'Sản phẩm',
658	      rating: Math.max(1, Math.min(5, Number(r.rating || 5))),
659	      title: r.title || '',
660	      body: r.body || '',
661	      status: r.status || 'pending',
662	      authorName: r.authorName || 'Khách',
663	      verified: !!r.verified,
664	      createdAt: r.createdAt || nowISO(),
665	    };
666	  }
667	
668	  const Reviews = makeStore('dtx_admin_reviews', 'dtx_admin_reviews_seeded_v1', seedReviews, {
669	    eventName: 'dtx:reviews-updated',
670	    normalize: normalizeReview,
671	  });
672	
673	  /* ───────────────── Returns (RMA) ─────────────────────────────── */
674	
675	  function seedReturns() {
676	    const reasons = ['Giao sai sản phẩm', 'Sản phẩm lỗi bao bì', 'Không hợp da', 'Khách đổi ý', 'Hết hạn gần kề'];
677	    const statuses = ['requested', 'approved', 'received', 'refunded', 'rejected'];
678	    const out = [];
679	    for (let i = 0; i < 14; i++) {
680	      out.push({
681	        id: uid('ret'),
682	        code: 'RMA-25-' + String(1000 + i).slice(-4),
683	        orderId: 'ord_' + (i % 48),
684	        orderCode: 'DTX-25-' + String(20000 + i).padStart(5, '0').slice(-5),
685	        customerName: ['Nguyễn Văn A','Trần Thị B','Lê Minh C','Phạm Thu D'][i % 4],
686	        reason: reasons[i % reasons.length],
687	        note: i % 4 === 0 ? 'Khách yêu cầu hoàn tiền qua chuyển khoản.' : '',
688	        amount: 450000 + (i * 35000),
689	        status: statuses[i % statuses.length],
690	        createdAt: new Date(Date.now() - i * 86400_000).toISOString(),
691	        updatedAt: nowISO(),
692	      });
693	    }
694	    return out;
695	  }
696	
697	  function normalizeReturn(r) {
698	    return {
699	      id: r.id || uid('ret'),
700	      code: r.code || ('RMA-' + String(Math.floor(Math.random() * 9999)).padStart(4, '0')),
701	      orderId: r.orderId || null,
702	      orderCode: r.orderCode || '',
703	      customerName: r.customerName || 'Khách',
704	      reason: r.reason || 'Không rõ lý do',
705	      note: r.note || '',
706	      amount: Number(r.amount || 0),
707	      status: r.status || 'requested',
708	      createdAt: r.createdAt || nowISO(),
709	      updatedAt: nowISO(),
710	    };
711	  }
712	
713	  const Returns = makeStore('dtx_admin_returns', 'dtx_admin_returns_seeded_v1', seedReturns, {
714	    eventName: 'dtx:returns-updated',
715	    normalize: normalizeReturn,
716	  });
717	
718	  /* ───────────────── Collections ──────────────────────────────── */
719	
