/* ═══════════════════════════════════════════════════════════════════
   LAYOUT GUARDS — chống vỡ bố cục khi admin nhập dữ liệu dài
   (text dài, email/URL không space, table nhiều cột, modal cao …)
   ─────────────────────────────────────────────────────────────────── */

/* 1. Card chứa table luôn cho scroll ngang khi không đủ rộng */
.card{ overflow:hidden }                       /* clip border-radius */
.card > .adm-tbl,
.card table.adm-tbl{ display:block;overflow-x:auto }

/* 2. Table cho phép truncate trong cell — admin có thể hover xem full */
.adm-tbl tbody td{
  max-width:280px;
  overflow:hidden;text-overflow:ellipsis;
}
.adm-tbl tbody td.no-trunc,
.adm-tbl tbody td:has(.stock-adjust),
.adm-tbl tbody td:has(.user-cell),
.adm-tbl tbody td:has(input),
.adm-tbl tbody td:has(button){ overflow:visible;text-overflow:clip }
.adm-tbl tbody td strong,
.adm-tbl tbody td a,
.adm-tbl tbody td small{
  display:inline-block;max-width:100%;
  overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  vertical-align:middle;
}
.adm-tbl tbody td .muted{ display:inline-block;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;vertical-align:middle }
/* Cho phép wrap cell items-summary nhiều SP */
.adm-tbl tbody td small.wrap,
.adm-tbl tbody td .wrap{ white-space:normal;display:block }

/* 3. Email/code cứng (không có khoảng trắng) — break để không tràn */
.adm-tbl .mono,
.adm-tbl code,
.kv dd,
.meta-list dd,
.cust-result small,
.prod-result small{
  word-break:break-all;
  overflow-wrap:anywhere;
}

/* 4. Bảng inventory 10 cột — bắt min-width tránh nén nát */
.adm-tbl#invTbl{ min-width:1100px }
.adm-tbl#ordTable{ min-width:980px }
.adm-tbl#cusTable{ min-width:980px }

/* 5. User cell tên KH dài — giới hạn cứng */
.user-cell{ min-width:0;flex:1 1 auto }
