32	  lines: InventoryLineRef[],
33	  actorId: string | null | undefined,
34	  tx: Tx = prisma,
35	): Promise<void> {
36	  for (const line of lines) {
37	    if (line.qty <= 0) continue;
38	
39	    if (line.variantId) {
40	      const variant = await tx.productVariant.findUnique({ where: { id: line.variantId } });
41	      if (!variant) throw new Error(`Variant ${line.variantId} không tồn tại`);
42	      const available = variant.stock - variant.reserved;
