/**
 * Inventory reservation service.
 *
 * Flow vận hành chuẩn:
 *   - Khi order chuyển từ pending/draft → confirmed:  reserve(qty)   → reserved += qty
 *   - Khi order cancel (từ confirmed/packing/pending): release(qty)  → reserved -= qty
 *   - Khi order chuyển → shipping (handoff cho carrier): commit(qty) → stock -= qty, reserved -= qty
 *
 * Tất cả operations là idempotent (dựa vào Order.reservedAt flag) và transactional.
 * Available = stock - reserved  (đây là số mà FE hiển thị "còn bán được").
 *
 * IMPORTANT - chống oversell (race condition):
 *   reserveStock dùng atomic conditional UPDATE …WHERE stock - reserved >= qty
 *   thay vì findUnique + update (vì giữa 2 query khác có thể bán mất).
 */

import type { Prisma, PrismaClient } from '@prisma/client';
import { prisma } from '../lib/prisma.js';

type Tx = Prisma.TransactionClient | PrismaClient;

export interface InventoryLineRef {
  productId: string;
  variantId?: string | null;
  qty: number;
  /** Để ghi vào InventoryMovement.refId */
  orderId?: string;
  orderItemId?: string;
}

/**
 * Atomic reserve một line. Trả về true nếu reserve thành công, false nếu không đủ tồn.
 * Dùng raw query để đạt atomicity: UPDATE … WHERE (stock - reserved) >= qty.
 * Postgres đảm bảo row-level lock trong transaction → không bị race condition.
 */
async function tryReserveAtomic(
  tx: Tx,
  table: 'product_variants' | 'products',
  id: string,
  qty: number,
): Promise<boolean> {
  const result = await tx.$executeRawUnsafe(
    `UPDATE ${table}
        SET reserved = reserved + $1, updated_at = NOW()
      WHERE id = $2::uuid
        AND (stock - reserved) >= $1`,
    qty,
    id,
  );
  // $executeRawUnsafe returns affected row count
  return Number(result) >= 1;
}

/**
 * Reserve tồn kho cho các line items. Nếu bất kỳ line nào không đủ available → throw.
 * Idempotent nếu caller check `order.reservedAt` trước khi gọi.
 */
export async function reserveStock(
  lines: InventoryLineRef[],
  actorId: string | null | undefined,
  tx: Tx = prisma,
): Promise<void> {
  for (const line of lines) {
    if (line.qty <= 0) continue;

    if (line.variantId) {
      const ok = await tryReserveAtomic(tx, 'product_variants', line.variantId, line.qty);
      if (!ok) {
        // Lấy thêm context để báo lỗi rõ
        const v = await tx.productVariant.findUnique({ where: { id: line.variantId } });
        const available = v ? v.stock - v.reserved : 0;
        const skuLabel = v?.skuSuffix ?? line.variantId;
        throw new Error(`SKU ${skuLabel} không đủ tồn (available=${available}, cần ${line.qty})`);
      }
    } else {
      const ok = await tryReserveAtomic(tx, 'products', line.productId, line.qty);
      if (!ok) {
        const p = await tx.product.findUnique({ where: { id: line.productId } });
        const available = p ? p.stock - p.reserved : 0;
        const label = p?.code ?? line.productId;
        throw new Error(`Sản phẩm ${label} không đủ tồn (available=${available}, cần ${line.qty})`);
      }
    }

    await tx.inventoryMovement.create({
      data: {
        productId: line.productId,
        variantId: line.variantId ?? null,
        delta: 0, // reserve không đổi stock, chỉ đổi reserved
        reason: 'reserve',
        note: `Reserve ${line.qty} cho order ${line.orderId ?? ''}`.trim(),
        actorId: actorId ?? null,
        orderId: line.orderId ?? null,
        refType: 'order',
        refId: line.orderId ?? null,
      },
    });
  }
}

/**
 * Giải phóng reservation (khi cancel, return, hay sửa đơn giảm qty).
 * Dùng atomic conditional để không cho reserved âm.
 */
export async function releaseStock(
  lines: InventoryLineRef[],
  actorId: string | null | undefined,
  tx: Tx = prisma,
): Promise<void> {
  for (const line of lines) {
    if (line.qty <= 0) continue;

    if (line.variantId) {
      // Atomic: chỉ trừ nếu reserved >= qty (chống underflow)
      const affected = await tx.$executeRawUnsafe(
        `UPDATE product_variants
            SET reserved = reserved - $1, updated_at = NOW()
          WHERE id = $2::uuid AND reserved >= $1`,
        line.qty,
        line.variantId,
      );
      if (Number(affected) < 1) {
        // Fallback: clamp về 0 thay vì để âm (idempotent với double-release)
        await tx.productVariant.update({
          where: { id: line.variantId },
          data: { reserved: 0 },
        });
      }
    } else {
      const affected = await tx.$executeRawUnsafe(
        `UPDATE products
            SET reserved = reserved - $1, updated_at = NOW()
          WHERE id = $2::uuid AND reserved >= $1`,
        line.qty,
        line.productId,
      );
      if (Number(affected) < 1) {
        await tx.product.update({
          where: { id: line.productId },
          data: { reserved: 0 },
        });
      }
    }

    await tx.inventoryMovement.create({
      data: {
        productId: line.productId,
        variantId: line.variantId ?? null,
        delta: 0,
        reason: 'release',
        note: `Release ${line.qty} từ order ${line.orderId ?? ''}`.trim(),
        actorId: actorId ?? null,
        orderId: line.orderId ?? null,
        refType: 'order',
        refId: line.orderId ?? null,
      },
    });
  }
}

/**
 * Commit: thực sự trừ stock vật lý khi handoff cho carrier.
 * Trước khi gọi, reservation phải còn (reserved >= qty).
 * Dùng atomic conditional UPDATE để không cho stock/reserved âm.
 */
export async function commitStock(
  lines: InventoryLineRef[],
  actorId: string | null | undefined,
  tx: Tx = prisma,
): Promise<void> {
  for (const line of lines) {
    if (line.qty <= 0) continue;

    if (line.variantId) {
      const affected = await tx.$executeRawUnsafe(
        `UPDATE product_variants
            SET stock = stock - $1, reserved = reserved - $1, updated_at = NOW()
          WHERE id = $2::uuid AND stock >= $1 AND reserved >= $1`,
        line.qty,
        line.variantId,
      );
      if (Number(affected) < 1) {
        const v = await tx.productVariant.findUnique({ where: { id: line.variantId } });
        throw new Error(
          `Commit thất bại cho variant ${v?.skuSuffix ?? line.variantId}: ` +
          `stock=${v?.stock ?? '?'} reserved=${v?.reserved ?? '?'} cần=${line.qty}`,
        );
      }
    } else {
      // FIX: trước đây không trừ Product.stock khi không có variantId → tồn ảo
      const affected = await tx.$executeRawUnsafe(
        `UPDATE products
            SET stock = stock - $1, reserved = reserved - $1, updated_at = NOW()
          WHERE id = $2::uuid AND stock >= $1 AND reserved >= $1`,
        line.qty,
        line.productId,
      );
      if (Number(affected) < 1) {
        const p = await tx.product.findUnique({ where: { id: line.productId } });
        throw new Error(
          `Commit thất bại cho SP ${p?.code ?? line.productId}: ` +
          `stock=${p?.stock ?? '?'} reserved=${p?.reserved ?? '?'} cần=${line.qty}`,
        );
      }
    }

    await tx.inventoryMovement.create({
      data: {
        productId: line.productId,
        variantId: line.variantId ?? null,
        delta: -line.qty,
        reason: 'sale',
        note: `Xuất bán cho order ${line.orderId ?? ''}`.trim(),
        actorId: actorId ?? null,
        orderId: line.orderId ?? null,
        refType: 'order',
        refId: line.orderId ?? null,
      },
    });
  }
}

/**
 * Moving average cost update khi nhập hàng (receiving).
 *   newAvg = (oldStock * oldAvg + receivedQty * unitCost) / (oldStock + receivedQty)
 *
 * FIX: SP không có variantId trước đây không cộng stock — giờ cộng vào Product.stock.
 */
export async function receiveStock(args: {
  productId: string;
  variantId?: string | null;
  qty: number;
  unitCost: bigint;
  note?: string;
  refType?: string;
  refId?: string;
  actorId?: string | null;
}, tx: Tx = prisma): Promise<void> {
  if (args.qty <= 0) throw new Error('qty phải > 0');

  if (args.variantId) {
    const v = await tx.productVariant.findUnique({ where: { id: args.variantId } });
    if (!v) throw new Error('Variant không tồn tại');
    const oldStock = BigInt(v.stock);
    const oldAvg = v.avgCost ?? args.unitCost;
    const totalValue = oldStock * oldAvg + BigInt(args.qty) * args.unitCost;
    const newStock = oldStock + BigInt(args.qty);
    const newAvg = newStock > 0n ? totalValue / newStock : args.unitCost;

    await tx.productVariant.update({
      where: { id: args.variantId },
      data: {
        stock: { increment: args.qty },
        avgCost: newAvg,
      },
    });
  } else {
    // FIX: SP không có variantId — cộng stock vào Product + recompute avgCost ở Product
    const p = await tx.product.findUnique({ where: { id: args.productId } });
    if (!p) throw new Error('Sản phẩm không tồn tại');
    const oldStock = BigInt(p.stock);
    const oldAvg = p.avgCost ?? args.unitCost;
    const totalValue = oldStock * oldAvg + BigInt(args.qty) * args.unitCost;
    const newStock = oldStock + BigInt(args.qty);
    const newAvg = newStock > 0n ? totalValue / newStock : args.unitCost;

    await tx.product.update({
      where: { id: args.productId },
      data: {
        stock: { increment: args.qty },
        avgCost: newAvg,
      },
    });
  }

  await tx.inventoryMovement.create({
    data: {
      productId: args.productId,
      variantId: args.variantId ?? null,
      delta: args.qty,
      reason: 'receive',
      note: args.note ?? `Nhập ${args.qty}`,
      unitCost: args.unitCost,
      actorId: args.actorId ?? null,
      refType: args.refType ?? 'manual',
      refId: args.refId ?? null,
    },
  });
}

