/**
 * Inventory reservation service.
 *
 * Flow vận hành chuẩn:
 *   - Khi order chuyển từ pending/draft → confirmed:  reserve(qty)   → variant.reserved += qty
 *   - Khi order cancel (từ confirmed/packing/pending): release(qty)  → variant.reserved -= qty
 *   - Khi order chuyển → shipping (handoff cho carrier): commit(qty) → stock -= qty, reserved -= qty
 *
 * Tất cả operations là idempotent (dựa vào Order.reservedAt flag) và transactional.
 * Available = stock - reserved  (đây là số mà FE hiển thị "còn bán được").
 */

import type { Prisma, PrismaClient } from '@prisma/client';
import { prisma } from '../lib/prisma.js';

type Tx = Prisma.TransactionClient | PrismaClient;

export interface InventoryLineRef {
  productId: string;
  variantId?: string | null;
  qty: number;
  /** Để ghi vào InventoryMovement.refId */
  orderId?: string;
  orderItemId?: string;
}

/**
 * Reserve tồn kho cho các line items. Nếu bất kỳ line nào không đủ available → throw.
 * Idempotent nếu caller check `order.reservedAt` trước khi gọi.
 */
export async function reserveStock(
  lines: InventoryLineRef[],
  actorId: string | null | undefined,
  tx: Tx = prisma,
): Promise<void> {
  for (const line of lines) {
    if (line.qty <= 0) continue;

    if (line.variantId) {
      const variant = await tx.productVariant.findUnique({ where: { id: line.variantId } });
      if (!variant) throw new Error(`Variant ${line.variantId} không tồn tại`);
      const available = variant.stock - variant.reserved;
      if (available < line.qty) {
        throw new Error(`SKU ${variant.skuSuffix} không đủ tồn (available=${available}, cần ${line.qty})`);
      }
      await tx.productVariant.update({
        where: { id: line.variantId },
        data: { reserved: { increment: line.qty } },
      });
    } else {
      const product = await tx.product.findUnique({ where: { id: line.productId } });
      if (!product) throw new Error(`Product ${line.productId} không tồn tại`);
      // Product-level reservation (khi không có variant)
      await tx.product.update({
        where: { id: line.productId },
        data: { reserved: { increment: line.qty } },
      });
    }

    await tx.inventoryMovement.create({
      data: {
        productId: line.productId,
        variantId: line.variantId ?? null,
        delta: 0, // reserve không đổi stock, chỉ đổi reserved
        reason: 'reserve',
        note: `Reserve ${line.qty} cho order ${line.orderId ?? ''}`.trim(),
        actorId: actorId ?? null,
        orderId: line.orderId ?? null,
        refType: 'order',
        refId: line.orderId ?? null,
      },
    });
  }
}

/**
 * Giải phóng reservation (khi cancel, return, hay sửa đơn giảm qty).
 */
export async function releaseStock(
  lines: InventoryLineRef[],
  actorId: string | null | undefined,
  tx: Tx = prisma,
): Promise<void> {
  for (const line of lines) {
    if (line.qty <= 0) continue;

    if (line.variantId) {
      await tx.productVariant.update({
        where: { id: line.variantId },
        data: { reserved: { decrement: line.qty } },
      });
    } else {
      await tx.product.update({
        where: { id: line.productId },
        data: { reserved: { decrement: line.qty } },
      });
    }

    await tx.inventoryMovement.create({
      data: {
        productId: line.productId,
        variantId: line.variantId ?? null,
        delta: 0,
        reason: 'release',
        note: `Release ${line.qty} từ order ${line.orderId ?? ''}`.trim(),
        actorId: actorId ?? null,
        orderId: line.orderId ?? null,
        refType: 'order',
        refId: line.orderId ?? null,
      },
    });
  }
}

/**
 * Commit: thực sự trừ stock vật lý khi handoff cho carrier.
 * Trước khi gọi, reservation phải còn (reserved >= qty).
 */
export async function commitStock(
  lines: InventoryLineRef[],
  actorId: string | null | undefined,
  tx: Tx = prisma,
): Promise<void> {
  for (const line of lines) {
    if (line.qty <= 0) continue;

    if (line.variantId) {
      await tx.productVariant.update({
        where: { id: line.variantId },
        data: {
          stock: { decrement: line.qty },
          reserved: { decrement: line.qty },
        },
      });
    } else {
      await tx.product.update({
        where: { id: line.productId },
        data: { reserved: { decrement: line.qty } },
      });
    }

    await tx.inventoryMovement.create({
      data: {
        productId: line.productId,
        variantId: line.variantId ?? null,
        delta: -line.qty,
        reason: 'sale',
        note: `Xuất bán cho order ${line.orderId ?? ''}`.trim(),
        actorId: actorId ?? null,
        orderId: line.orderId ?? null,
        refType: 'order',
        refId: line.orderId ?? null,
      },
    });
  }
}

/**
 * Moving average cost update khi nhập hàng (receiving).
 *   newAvg = (oldStock * oldAvg + receivedQty * unitCost) / (oldStock + receivedQty)
 */
export async function receiveStock(args: {
  productId: string;
  variantId?: string | null;
  qty: number;
  unitCost: bigint;
  note?: string;
  refType?: string;
  refId?: string;
  actorId?: string | null;
}, tx: Tx = prisma): Promise<void> {
  if (args.qty <= 0) throw new Error('qty phải > 0');

  if (args.variantId) {
    const v = await tx.productVariant.findUnique({ where: { id: args.variantId } });
    if (!v) throw new Error('Variant không tồn tại');
    const oldStock = BigInt(v.stock);
    const oldAvg = v.avgCost ?? args.unitCost;
    const totalValue = oldStock * oldAvg + BigInt(args.qty) * args.unitCost;
    const newStock = oldStock + BigInt(args.qty);
    const newAvg = newStock > 0n ? totalValue / newStock : args.unitCost;

    await tx.productVariant.update({
      where: { id: args.variantId },
      data: {
        stock: { increment: args.qty },
        avgCost: newAvg,
      },
    });
  } else {
    // Chỉ ghi movement, stock tồn ở level variant
  }

  await tx.inventoryMovement.create({
    data: {
      productId: args.productId,
      variantId: args.variantId ?? null,
      delta: args.qty,
      reason: 'receive',
      note: args.note ?? `Nhập ${args.qty}`,
      unitCost: args.unitCost,
      actorId: args.actorId ?? null,
      refType: args.refType ?? 'manual',
      refId: args.refId ?? null,
    },
  });
}

