      variant = await tx.productVariant.findFirst({ where: { id: line.variantId, productId: line.productId } });
      if (!variant) continue;
    } else {
      variant = await tx.productVariant.findFirst({ where: { productId: line.productId }, orderBy: { position: 'asc' } });
      // null OK → receive vào Product.stock
    }
    // Đảm bảo product tồn tại
    const product = await tx.product.findUnique({ where: { id: line.productId }, select: { id: true } });
    if (!product) continue;

    await receiveStock({
      productId: line.productId,
      variantId: variant?.id ?? null,
      qty: line.qty,
      unitCost: BigInt(line.unitCost),
      note: body.note ?? `PO ${body.poNumber ?? ''} nhập ${line.qty}`,
      refType: 'po',
      refId,
      actorId: req.auth!.user.id,
    }, tx);
    affected++;
  }

