      OR: [
        { name: { contains: q.q, mode: 'insensitive' } },
        { code: { contains: q.q, mode: 'insensitive' } },
      ],
    }),
    ...(q.category && { category: { slug: q.category } }),
  };
  const products = await prisma.product.findMany({
    where,
    include: { variants: true, category: true },
    orderBy: { updatedAt: 'desc' },
  });

  let items = products.map(p => {
    const stock = p.variants.reduce((s, v) => s + v.stock, 0);
    const reserved = p.variants.reduce((s, v) => s + v.reserved, 0);
    const available = stock - reserved;
    const state: 'ok' | 'low' | 'out' = available === 0 ? 'out' : available <= p.lowStockThreshold ? 'low' : 'ok';
    const inventoryValue = p.variants.reduce((s, v) => {
      const cost = v.avgCost ?? v.cost ?? p.avgCost ?? p.cost ?? 0n;
      return s + Number(cost) * v.stock;
    }, 0);
    return {
      id: p.id,
      code: p.code,
      name: p.name,
      category: p.category?.name ?? null,
      stock,
      reserved,
      available,
      inventory_value: inventoryValue,
      low_stock: p.lowStockThreshold,
      state,
      status: p.status,
      variants: p.variants.map(v => ({
        id: v.id, sku_suffix: v.skuSuffix,
        stock: v.stock, reserved: v.reserved, available: v.stock - v.reserved,
        avg_cost: v.avgCost !== null && v.avgCost !== undefined ? Number(v.avgCost) : null,
      })),
    };
  });
  if (q.state === 'out')      items = items.filter(x => x.state === 'out');
  else if (q.state === 'low') items = items.filter(x => x.state === 'low');
  else if (q.state === 'ok')  items = items.filter(x => x.state === 'ok');
  else if (q.state === 'reserved') items = items.filter(x => x.reserved > 0);

  // Sort in-memory sau khi tính
  items.sort((a, b) => {
    switch (q.sort) {
      case 'stock-asc':     return a.stock - b.stock;
      case 'stock-desc':    return b.stock - a.stock;
      case 'reserved-desc': return b.reserved - a.reserved;
      default:              return 0;
    }
  });

  const summary = {
    total: items.length,
    out: items.filter(x => x.state === 'out').length,
    low: items.filter(x => x.state === 'low').length,
    ok:  items.filter(x => x.state === 'ok').length,
    stock_total: items.reduce((s, x) => s + x.stock, 0),
    reserved_total: items.reduce((s, x) => s + x.reserved, 0),
    available_total: items.reduce((s, x) => s + x.available, 0),
    inventory_value: items.reduce((s, x) => s + x.inventory_value, 0),
  };

  const start = (q.page - 1) * q.limit;
  const slice = items.slice(start, start + q.limit);
  return { data: slice, total: items.length, page: q.page, pageSize: q.limit, summary };
});

// GET /inventory/alerts — low-stock + out-of-stock list (for dashboard)
app.get('/inventory/alerts', { preHandler: [requireAuth, requirePermission('inventory:read')] }, async () => {
  const products = await prisma.product.findMany({
    where: { deletedAt: null, status: { not: 'archived' } },
    include: { variants: true, category: true },
  });
  const rows: Array<{
    id: string; code: string; name: string; stock: number; reserved: number;
    available: number; threshold: number; state: 'out' | 'low';
  }> = [];
  for (const p of products) {
    const stock = p.variants.reduce((s, v) => s + v.stock, 0);
    const reserved = p.variants.reduce((s, v) => s + v.reserved, 0);
    const available = stock - reserved;
    if (available === 0 || available <= p.lowStockThreshold) {
      rows.push({
        id: p.id, code: p.code, name: p.name,
        stock, reserved, available,
        threshold: p.lowStockThreshold,
        state: available === 0 ? 'out' : 'low',
      });
    }
  }
  rows.sort((a, b) => a.available - b.available);
  return { data: rows, total: rows.length };
});

// POST /inventory/adjust
app.post('/inventory/adjust', { preHandler: [requireAuth, requirePermission('inventory:write')] }, async (req, reply) => {
  const body = AdjustBody.parse(req.body);
  const res = await prisma.$transaction(async tx => {
    // Nếu có variantId, cập nhật variant; nếu không, cập nhật variant đầu tiên.
    let variant;
    if (body.variantId) {
      variant = await tx.productVariant.findFirst({ where: { id: body.variantId, productId: body.productId } });
    } else {
      variant = await tx.productVariant.findFirst({ where: { productId: body.productId }, orderBy: { position: 'asc' } });
    }
    if (!variant) { reply.code(404); throw new Error('Variant not found'); }

    const before = variant.stock;
    const after = Math.max(0, before + body.delta);

    await tx.productVariant.update({ where: { id: variant.id }, data: { stock: after } });

    await tx.inventoryMovement.create({
      data: {
        productId: body.productId,
        variantId: variant.id,
        delta: after - before,
        reason: mapReason(body.reason),
        note: body.note ?? null,
        actorId: req.auth!.user.id,
      },
    });

    await writeAudit({
      action: 'inventory.adjust',
      actorId: req.auth!.user.id, actorEmail: req.auth!.user.email, actorIp: req.ip,
      entity: 'product', entityId: body.productId,
      diff: { before: { stock: before }, after: { stock: after }, reason: body.reason, note: body.note },
      requestId: req.id,
    }, tx);

    return { before, after, variant_id: variant.id };
  });
  return res;
});

