  // POST /orders/validate-voucher — FE preview trước khi submit
  app.post('/orders/validate-voucher', {
    preHandler: [requireAuth, requirePermission('orders:read')],
  }, async req => {
    const body = z.object({
      code: z.string().max(30),
      subtotal: z.coerce.number().int().nonnegative(),
      shippingFee: z.coerce.number().int().nonnegative().default(0),
    }).parse(req.body);
    const result = await applyVoucher(body.code, body.subtotal, body.shippingFee, prisma as unknown as Prisma.TransactionClient);
    return result;
  });

  // ─── PATCH /orders/:id/tracking — gắn/đổi mã vận đơn + carrier ──
  app.patch<{ Params: { id: string } }>('/orders/:id/tracking', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = z.object({
      carrierName:  z.string().min(1).max(40),
      trackingCode: z.string().min(1).max(80),
      trackingUrl:  z.string().url().max(500).optional().nullable(),
      note:         z.string().max(500).optional(),
    }).parse(req.body);
    const id = req.params.id;
    const actorId = req.auth!.user.id;

    const result = await prisma.$transaction(async tx => {
      const o = await tx.order.findUnique({ where: { id } });
      if (!o) { reply.code(404); throw new Error('Order not found'); }
      // Cho phép gắn/đổi tracking khi đơn đang confirmed/packing/shipping/delivered
      const allowed = ['confirmed', 'packing', 'shipping', 'delivered'];
      if (!allowed.includes(o.status)) {
        reply.code(409);
        throw new Error(`Không gắn tracking khi đơn ở trạng thái ${o.status}`);
      }

      const next = await tx.order.update({
        where: { id },
        data: {
          carrierName: body.carrierName,
          trackingCode: body.trackingCode,
          trackingUrl: body.trackingUrl ?? null,
          events: {
            create: {
              kind: 'shipping',
              actorId,
              note: body.note ?? `Gắn vận đơn ${body.carrierName}: ${body.trackingCode}`,
              metadata: { carrier: body.carrierName, code: body.trackingCode, url: body.trackingUrl ?? null } as Prisma.InputJsonValue,
            },
          },
        },
        include: { items: true, events: { orderBy: { createdAt: 'asc' } }, customer: true },
      });

      await writeAudit({
        action: 'order.tracking.update',
        actorId, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: id,
        diff: {
          before: { carrierName: o.carrierName, trackingCode: o.trackingCode },
          after:  { carrierName: body.carrierName, trackingCode: body.trackingCode },
        },
        requestId: req.id,
      }, tx);

      return next;
    });

    return serialize(result);
  });

  // ─── POST /orders/:id/cancel-after-ship ──────────────────────────
  // Huỷ đơn đã ship/delivered → tạo OrderReturn (status=requested) + đặt order=returned/cancelled
  // Khác với PATCH /status: status đang shipping/delivered KHÔNG cho phép → cancelled qua TRANSITIONS,
  // route này là "hot lane" với reason bắt buộc + tự động tạo case return.
  app.post<{ Params: { id: string } }>('/orders/:id/cancel-after-ship', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = z.object({
      reason:    z.string().min(3).max(500),
      restock:   z.boolean().default(true),
      refundAmount: z.coerce.number().int().nonnegative().optional(), // nếu undefined → mặc định bằng order.total
      note:      z.string().max(500).optional(),
    }).parse(req.body);
    const id = req.params.id;
    const actorId = req.auth!.user.id;

    const { result, customerId } = await prisma.$transaction(async tx => {
      const o = await tx.order.findUnique({ where: { id }, include: { items: true } });
      if (!o) { reply.code(404); throw new Error('Order not found'); }
      if (!['shipping', 'delivered'].includes(o.status)) {
        reply.code(409);
        throw new Error(`Chỉ huỷ-sau-ship được khi đơn đang shipping/delivered (hiện: ${o.status})`);
      }

      // Restock nếu yêu cầu — cộng lại stock cho cả Product và Variant
      if (body.restock) {
        for (const it of o.items) {
          if (it.qty <= 0) continue;
          if (it.variantId) {
            await tx.productVariant.update({
              where: { id: it.variantId },
              data: { stock: { increment: it.qty } },
            });
          } else {
            await tx.product.update({
              where: { id: it.productId },
              data: { stock: { increment: it.qty } },
            });
          }
          await tx.inventoryMovement.create({
            data: {
              productId: it.productId,
              variantId: it.variantId ?? null,
              delta: it.qty,
              reason: 'return_',
              note: `Cancel-after-ship đơn ${o.code}: ${body.reason}`,
              actorId,
              orderId: o.id,
              refType: 'cancel_after_ship',
              refId: o.id,
            },
          });
        }
      }

      // Tạo case return tổng hợp
      const lastReturn = await tx.orderReturn.findFirst({
        orderBy: { createdAt: 'desc' },
        select: { code: true },
      });
      const year = String(new Date().getFullYear()).slice(-2);
      const m = lastReturn?.code.match(/-(\d+)$/);
      const seq = m ? Number(m[1]) + 1 : 1;
      const rtnCode = `RTN-${year}-${String(seq).padStart(5, '0')}`;

      const refundAmount = BigInt(body.refundAmount ?? Number(o.total));
      const ret = await tx.orderReturn.create({
        data: {
          code: rtnCode,
          orderId: o.id,
          status: 'approved',
          reason: body.reason,
          refundAmount,
          restock: body.restock,
          pointsRefund: o.pointsEarned ?? 0,
          actorId,
          approvedAt: new Date(),
          notes: body.note ?? null,
          items: {
            create: o.items.map(it => ({
              orderItemId: it.id,
              productId: it.productId,
              variantId: it.variantId ?? null,
              qty: it.qty,
              unitRefund: it.priceUnit,
              reasonCode: 'cancel_after_ship',
            })),
          },
        },
      });

      // Đổi order status: shipping → cancelled (huỷ trên đường), delivered → returned (đã giao xong)
      const nextStatus: 'cancelled' | 'returned' = o.status === 'shipping' ? 'cancelled' : 'returned';
      const updated = await tx.order.update({
        where: { id },
        data: {
          status: nextStatus,
          cancelReason: body.reason,
          cancelledBy: actorId,
          cancelledAt: nextStatus === 'cancelled' ? new Date() : o.cancelledAt,
          returnedAt:  nextStatus === 'returned'  ? new Date() : o.returnedAt,
          // Refund điểm thưởng đã earn (nếu đã delivered) — set về 0 để recompute không cộng lại
          pointsEarned: 0,
          events: {
            create: {
              kind: 'status_change',
              fromState: o.status,
              toState: nextStatus,
              actorId,
              note: `Huỷ-sau-ship: ${body.reason}`,
              metadata: { returnId: ret.id, returnCode: ret.code, restock: body.restock, refundAmount: Number(refundAmount) } as Prisma.InputJsonValue,
            },
          },
        },
        include: { items: true, events: { orderBy: { createdAt: 'asc' } }, customer: true },
      });

      await writeAudit({
        action: 'order.cancel_after_ship',
        actorId, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: id,
        diff: {
          before: { status: o.status, pointsEarned: o.pointsEarned },
          after:  { status: nextStatus, returnCode: ret.code, refundAmount: Number(refundAmount), restock: body.restock },
        },
        requestId: req.id,
      }, tx);

      return { result: { order: updated, returnRecord: ret }, customerId: o.customerId };
    });

    // Recompute customer ngoài transaction để tier/segment cập nhật
    if (customerId) {
      recomputeCustomer(customerId).catch(err =>
        req.log.warn({ err: err.message, customerId }, 'recompute after cancel-after-ship failed'),
      );
    }

    reply.code(201);
    return {
      order: serialize(result.order),
      return: {
        id: result.returnRecord.id,
        code: result.returnRecord.code,
        status: result.returnRecord.status,
        refund_amount: Number(result.returnRecord.refundAmount),
        restock: result.returnRecord.restock,
      },
    };
  });

  // ─── POST /orders/:id/return — RMA tạo case trả hàng (partial/full) ──
  app.post<{ Params: { id: string } }>('/orders/:id/return', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = z.object({
      reason: z.string().min(3).max(500),
      restock: z.boolean().default(true),
      refundAmount: z.coerce.number().int().nonnegative().optional(),
      autoApprove: z.boolean().default(false),
      notes: z.string().max(500).optional(),
      items: z.array(z.object({
        orderItemId: z.string().uuid(),
        qty:         z.coerce.number().int().positive(),
        unitRefund:  z.coerce.number().int().nonnegative().optional(), // null → dùng priceUnit của orderItem
        reasonCode:  z.enum(['damaged','wrong_item','not_as_described','change_mind','other']).optional(),
      })).min(1).max(50),
    }).parse(req.body);
    const id = req.params.id;
    const actorId = req.auth!.user.id;

    const { rec, customerId } = await prisma.$transaction(async tx => {
      const o = await tx.order.findUnique({ where: { id }, include: { items: true } });
      if (!o) { reply.code(404); throw new Error('Order not found'); }
      if (!['delivered', 'returned'].includes(o.status)) {
        reply.code(409);
        throw new Error(`Chỉ tạo return cho đơn đã giao (hiện: ${o.status})`);
      }

      // Validate từng line: orderItemId phải thuộc đơn này; qty không vượt qty đã mua
      const itemMap = new Map(o.items.map(i => [i.id, i]));
      // Tổng qty đã trả trước đó (của các return record trước, kể cả status != rejected)
      const prevReturns = await tx.orderReturn.findMany({
        where: { orderId: id, status: { not: 'rejected' } },
        include: { items: true },
      });
      const alreadyReturned = new Map<string, number>();
      for (const r of prevReturns) {
        for (const ri of r.items) {
          alreadyReturned.set(ri.orderItemId, (alreadyReturned.get(ri.orderItemId) ?? 0) + ri.qty);
        }
      }

      let computedRefund = 0n;
      const linesPersist: Array<{
        orderItemId: string;
        productId: string;
        variantId: string | null;
        qty: number;
        unitRefund: bigint;
        reasonCode: string | null;
      }> = [];

      for (const ln of body.items) {
        const oi = itemMap.get(ln.orderItemId);
        if (!oi) {
          reply.code(400);
          throw new Error(`OrderItem ${ln.orderItemId} không thuộc đơn ${o.code}`);
        }
        const remain = oi.qty - (alreadyReturned.get(oi.id) ?? 0);
        if (ln.qty > remain) {
          reply.code(400);
          throw new Error(`SP "${oi.nameSnapshot}": chỉ còn ${remain} chưa trả, yêu cầu ${ln.qty}`);
        }
        const unitRefund = ln.unitRefund != null ? BigInt(ln.unitRefund) : oi.priceUnit;
        computedRefund += unitRefund * BigInt(ln.qty);
        linesPersist.push({
          orderItemId: oi.id,
          productId:   oi.productId,
          variantId:   oi.variantId ?? null,
          qty:         ln.qty,
          unitRefund,
          reasonCode:  ln.reasonCode ?? null,
        });
      }

      const refundAmount = body.refundAmount != null ? BigInt(body.refundAmount) : computedRefund;

      // Tạo code RTN-YY-XXXXX
      const lastReturn = await tx.orderReturn.findFirst({ orderBy: { createdAt: 'desc' }, select: { code: true } });
      const year = String(new Date().getFullYear()).slice(-2);
      const m = lastReturn?.code.match(/-(\d+)$/);
      const seq = m ? Number(m[1]) + 1 : 1;
      const rtnCode = `RTN-${year}-${String(seq).padStart(5, '0')}`;

      const status = body.autoApprove ? 'approved' : 'requested';

      const totalQty = linesPersist.reduce((s, l) => s + l.qty, 0);
      const orderQty = o.items.reduce((s, i) => s + i.qty, 0);
      // Refund điểm tỉ lệ với phần trả
      const pointsRefund = orderQty > 0 ? Math.round(((o.pointsEarned ?? 0) * totalQty) / orderQty) : 0;

      const rec = await tx.orderReturn.create({
        data: {
          code: rtnCode,
          orderId: o.id,
          status,
          reason: body.reason,
          refundAmount,
          restock: body.restock,
          pointsRefund,
          notes: body.notes ?? null,
          actorId,
          approvedAt: status === 'approved' ? new Date() : null,
          items: { create: linesPersist },
        },
        include: { items: true },
      });

      // Nếu autoApprove → restock + đặt order=returned (nếu trả toàn bộ) + giảm pointsEarned
      if (status === 'approved') {
        if (body.restock) {
          for (const ln of linesPersist) {
            if (ln.variantId) {
              await tx.productVariant.update({
                where: { id: ln.variantId },
                data: { stock: { increment: ln.qty } },
              });
            } else {
              await tx.product.update({
                where: { id: ln.productId },
                data: { stock: { increment: ln.qty } },
              });
            }
            await tx.inventoryMovement.create({
              data: {
                productId: ln.productId,
                variantId: ln.variantId,
                delta: ln.qty,
                reason: 'return_',
                note: `Return ${rtnCode} cho đơn ${o.code}: ${body.reason}`,
                actorId,
                orderId: o.id,
                refType: 'return',
                refId: rec.id,
              },
            });
          }
        }

        // Cập nhật order: nếu trả toàn bộ → status returned; trả partial → giữ delivered nhưng ghi nhận pointsEarned bị trừ
        const totalReturnedAfter = (alreadyReturned.size === 0 ? 0 : Array.from(alreadyReturned.values()).reduce((a, b) => a + b, 0)) + totalQty;
        const isFullReturn = totalReturnedAfter >= orderQty;
        const newPointsEarned = Math.max(0, (o.pointsEarned ?? 0) - pointsRefund);

        await tx.order.update({
          where: { id: o.id },
          data: {
            status:       isFullReturn ? 'returned' : o.status,
            returnedAt:   isFullReturn ? new Date() : o.returnedAt,
            pointsEarned: newPointsEarned,
            events: {
              create: {
                kind: 'status_change',
                fromState: o.status,
                toState: isFullReturn ? 'returned' : o.status,
                actorId,
                note: `Return ${rtnCode}: ${body.reason}`,
                metadata: {
                  returnId: rec.id, returnCode: rtnCode,
                  refundAmount: Number(refundAmount),
                  pointsRefund, restock: body.restock,
                } as Prisma.InputJsonValue,
              },
            },
          },
        });
      } else {
        await tx.orderEvent.create({
          data: {
            orderId: o.id,
            kind: 'note',
            actorId,
            note: `Yêu cầu trả hàng ${rtnCode}: ${body.reason}`,
            metadata: { returnId: rec.id, returnCode: rtnCode } as Prisma.InputJsonValue,
          },
        });
      }

      await writeAudit({
        action: status === 'approved' ? 'order.return.approved' : 'order.return.requested',
        actorId, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: id,
        diff: { after: { returnId: rec.id, code: rtnCode, refundAmount: Number(refundAmount), restock: body.restock, pointsRefund, items: linesPersist.length } },
        requestId: req.id,
      }, tx);

      return { rec, customerId: o.customerId };
    });

    if (customerId) {
      recomputeCustomer(customerId).catch(err =>
        req.log.warn({ err: err.message, customerId }, 'recompute after return failed'),
      );
    }

    reply.code(201);
    return {
      id: rec.id,
      code: rec.code,
      status: rec.status,
      refund_amount: Number(rec.refundAmount),
      restock: rec.restock,
      points_refund: rec.pointsRefund,
      items: rec.items.map(i => ({
        order_item_id: i.orderItemId,
        product_id: i.productId,
        variant_id: i.variantId,
        qty: i.qty,
        unit_refund: Number(i.unitRefund),
        reason_code: i.reasonCode,
      })),
      created_at: rec.createdAt.toISOString(),
    };
  });

  // ─── PATCH /orders/:id/returns/:returnId — duyệt/từ chối/refund case RMA ──
  app.patch<{ Params: { id: string; returnId: string } }>('/orders/:id/returns/:returnId', {
    preHandler: [requireAuth, requirePermission('orders:write')],
  }, async (req, reply) => {
    const body = z.object({
      status: z.enum(['inspecting', 'approved', 'rejected', 'refunded']),
      note:   z.string().max(500).optional(),
    }).parse(req.body);
    const { id, returnId } = req.params;
    const actorId = req.auth!.user.id;

    const { updated, customerId } = await prisma.$transaction(async tx => {
      const ret = await tx.orderReturn.findFirst({
        where: { id: returnId, orderId: id },
        include: { items: true, order: { include: { items: true } } },
      });
      if (!ret) { reply.code(404); throw new Error('Return not found'); }

      // Guard transitions
      const ALLOWED: Record<string, string[]> = {
        requested:  ['inspecting', 'approved', 'rejected'],
        inspecting: ['approved', 'rejected'],
        approved:   ['refunded'],
        rejected:   [],
        refunded:   [],
      };
      const allowed = ALLOWED[ret.status] ?? [];
      if (!allowed.includes(body.status)) {
        reply.code(409);
        throw new Error(`Không thể chuyển return từ ${ret.status} → ${body.status}`);
      }

      const patch: Prisma.OrderReturnUpdateInput = { status: body.status, notes: body.note ?? ret.notes };

      // Khi vừa approved (lần đầu) → restock + giảm pointsEarned trên order
      if (body.status === 'approved' && ret.status !== 'approved') {
        patch.approvedAt = new Date();

        if (ret.restock) {
          for (const ln of ret.items) {
            if (ln.variantId) {
              await tx.productVariant.update({
                where: { id: ln.variantId },
                data: { stock: { increment: ln.qty } },
              });
            } else {
              await tx.product.update({
                where: { id: ln.productId },
                data: { stock: { increment: ln.qty } },
              });
            }
            await tx.inventoryMovement.create({
              data: {
                productId: ln.productId,
                variantId: ln.variantId,
                delta: ln.qty,
                reason: 'return_',
                note: `Return ${ret.code} approved cho đơn ${ret.order.code}`,
                actorId,
                orderId: ret.orderId,
                refType: 'return',
                refId: ret.id,
              },
            });
          }
        }

        // Recompute totalReturnedQty + isFullReturn + pointsEarned
        const allRets = await tx.orderReturn.findMany({
          where: { orderId: id, status: { in: ['approved', 'refunded'] } },
          include: { items: true },
        });
        const totalReturnedQty = allRets.reduce((s, r) => s + r.items.reduce((s2, i) => s2 + i.qty, 0), 0)
                               + ret.items.reduce((s, i) => s + i.qty, 0); // include current
        const orderQty = ret.order.items.reduce((s, i) => s + i.qty, 0);
        const isFullReturn = totalReturnedQty >= orderQty;
        const newPointsEarned = Math.max(0, (ret.order.pointsEarned ?? 0) - (ret.pointsRefund ?? 0));

        await tx.order.update({
          where: { id: ret.orderId },
          data: {
            status:       isFullReturn ? 'returned' : ret.order.status,
            returnedAt:   isFullReturn ? new Date() : ret.order.returnedAt,
            pointsEarned: newPointsEarned,
            events: {
              create: {
                kind: 'status_change',
                fromState: ret.order.status,
                toState: isFullReturn ? 'returned' : ret.order.status,
                actorId,
                note: `Return ${ret.code} approved`,
                metadata: { returnId: ret.id, pointsRefund: ret.pointsRefund } as Prisma.InputJsonValue,
              },
            },
          },
        });
      }

      if (body.status === 'refunded' && !ret.refundedAt) {
        patch.refundedAt = new Date();
        await tx.orderEvent.create({
          data: {
            orderId: ret.orderId,
            kind: 'payment',
            actorId,
            note: `Đã hoàn tiền cho return ${ret.code}: ${Number(ret.refundAmount)}đ`,
            metadata: { returnId: ret.id, refundAmount: Number(ret.refundAmount) } as Prisma.InputJsonValue,
          },
        });
      }

      const next = await tx.orderReturn.update({
        where: { id: returnId },
        data: patch,
        include: { items: true },
      });

      await writeAudit({
        action: `order.return.${body.status}`,
        actorId, actorEmail: req.auth!.user.email, actorIp: req.ip,
        entity: 'order', entityId: id,
        diff: { before: { status: ret.status }, after: { status: body.status, returnCode: ret.code } },
        requestId: req.id,
      }, tx);

      return { updated: next, customerId: ret.order.customerId };
    });

    if (customerId) {
      recomputeCustomer(customerId).catch(err =>
        req.log.warn({ err: err.message, customerId }, 'recompute after return-update failed'),
      );
    }

    return {
      id: updated.id,
      code: updated.code,
      status: updated.status,
      refund_amount: Number(updated.refundAmount),
      restock: updated.restock,
      points_refund: updated.pointsRefund,
      approved_at: updated.approvedAt?.toISOString() ?? null,
      refunded_at: updated.refundedAt?.toISOString() ?? null,
      updated_at: updated.updatedAt.toISOString(),
    };
  });

  // ─── GET /orders/:id/returns — list cases RMA của 1 đơn ──
  app.get<{ Params: { id: string } }>('/orders/:id/returns', {
    preHandler: [requireAuth, requirePermission('orders:read')],
  }, async (req) => {
    const id = req.params.id;
    const list = await prisma.orderReturn.findMany({
      where: { orderId: id },
      orderBy: { createdAt: 'desc' },
      include: { items: true },
    });
    return {
      data: list.map(r => ({
        id: r.id, code: r.code, status: r.status,
        reason: r.reason,
        refund_amount: Number(r.refundAmount),
        restock: r.restock,
        points_refund: r.pointsRefund,
        items: r.items.map(i => ({
          order_item_id: i.orderItemId,
          product_id: i.productId,
          variant_id: i.variantId,
          qty: i.qty,
          unit_refund: Number(i.unitRefund),
          reason_code: i.reasonCode,
        })),
        approved_at: r.approvedAt?.toISOString() ?? null,
        refunded_at: r.refundedAt?.toISOString() ?? null,
        created_at: r.createdAt.toISOString(),
      })),
      total: list.length,
    };
  });
};

