120	  // ──────────────────────────────────────────────────────────────
121	
122	  function makeRemoteStore(storeName, basePath, toLocal, toRemote) {
123	    // Cache list để .all() đồng bộ được với code cũ.
124	    let cache = [];
125	    let lastFetch = 0;
126	
127	    const emitUpdated = () => {
128	      global.dispatchEvent(new CustomEvent(`dtx:${storeName}-updated`));
129	    };
130	
131	    async function refresh() {
132	      try {
133	        const res = await Api.get(basePath, { limit: 200 });
134	        cache = (res.data || []).map(toLocal);
135	        lastFetch = Date.now();
136	      } catch (_) { /* toast already */ }
137	    }
138	
139	    // Kick off initial load
140	    refresh().then(emitUpdated);
141	
142	    return {
143	      isRemote: true,
144	      basePath,
145	      // Mimic local makeStore:
146	      all() { return cache; },
147	      get(id) { return cache.find(x => x.id === id) || null; },
148	      async reload() { await refresh(); emitUpdated(); return cache; },
149	
150	      async create(patch) {
151	        const payload = toRemote ? toRemote(patch) : patch;
152	        const row = await Api.post(basePath, payload);
153	        const local = toLocal(row);
154	        cache.unshift(local);
155	        emitUpdated();
156	        return local;
157	      },
158	      async update(id, patch) {
159	        const payload = toRemote ? toRemote(patch) : patch;
160	        const row = await Api.patch(`${basePath}/${id}`, payload);
