  { code: 'DTX-MSK-01', slug: 'mat-na-giay-vit-b5', name: 'Mặt nạ giấy Vitamin B5', categorySlug: 'mat-na',
    price: 35_000n, cost: 12_000n, status: ProductStatus.active, baseStock: 800 },
  { code: 'DTX-MSK-02', slug: 'mat-na-ngu-collagen', name: 'Mặt nạ ngủ Collagen', categorySlug: 'mat-na',
    price: 425_000n, cost: 150_000n, status: ProductStatus.active, baseStock: 65 },
  { code: 'DTX-DRAFT-01', slug: 'serum-peptide-test', name: '[Đang chuẩn bị] Serum Peptide', categorySlug: 'serum',
    price: 690_000n, cost: 260_000n, status: ProductStatus.draft, baseStock: 0 },
];

async function seedCategoriesAndProducts() {
  for (const c of CATEGORIES) {
    await prisma.category.upsert({
      where: { slug: c.slug },
      update: { name: c.name, position: c.position },
      create: c,
    });
  }
  const catBySlug = new Map(
    (await prisma.category.findMany()).map(c => [c.slug, c.id]),
  );

  for (const p of PRODUCTS) {
    const product = await prisma.product.upsert({
      where: { code: p.code },
      update: {
        name: p.name, slug: p.slug, price: p.price, cost: p.cost ?? null,
        categoryId: catBySlug.get(p.categorySlug) ?? null,
        status: p.status ?? ProductStatus.active,
        shortDesc: p.shortDesc ?? null,
        lowStockThreshold: p.lowStockThreshold ?? 10,
        ...(p.variants ? {} : { stock: p.baseStock ?? 100, avgCost: p.cost ?? null }),
      },
      create: {
        code: p.code, slug: p.slug, name: p.name, price: p.price,
        cost: p.cost ?? null, categoryId: catBySlug.get(p.categorySlug) ?? null,
        status: p.status ?? ProductStatus.active,
        shortDesc: p.shortDesc ?? null,
        lowStockThreshold: p.lowStockThreshold ?? 10,
        ...(p.variants ? { stock: 0, avgCost: null } : { stock: p.baseStock ?? 100, avgCost: p.cost ?? null }),
      },
    });

    if (p.variants) {
      for (const v of p.variants) {
        await prisma.productVariant.upsert({
          where: { productId_skuSuffix: { productId: product.id, skuSuffix: v.skuSuffix } },
          update: { stock: v.stock, cost: v.cost, avgCost: v.cost,
                    price: v.priceDelta ? p.price + v.priceDelta : null,
                    size: v.size ?? null },
          create: {
            productId: product.id,
            skuSuffix: v.skuSuffix, size: v.size ?? null,
            stock: v.stock, cost: v.cost, avgCost: v.cost,
            price: v.priceDelta ? p.price + v.priceDelta : null,
          },
        });
      }
    }

    // Movement nhập kho khởi tạo
    if (p.variants) {
      for (const v of p.variants) {
        const variant = await prisma.productVariant.findFirst({ where: { productId: product.id, skuSuffix: v.skuSuffix } });
        if (variant) {
          await prisma.inventoryMovement.create({
            data: {
              productId: product.id, variantId: variant.id,
              delta: v.stock, reason: 'receive',
              note: 'Seed nhập kho khởi tạo', refType: 'po', refId: 'PO-INIT',
              unitCost: v.cost,
            },
          });
        }
      }
    } else if (p.baseStock) {
      await prisma.inventoryMovement.create({
        data: {
          productId: product.id,
          delta: p.baseStock, reason: 'receive',
          note: 'Seed nhập kho khởi tạo', refType: 'po', refId: 'PO-INIT',
          unitCost: p.cost ?? null,
        },
      });
    }
  }

  console.log(`✔ Seeded ${CATEGORIES.length} categories + ${PRODUCTS.length} products`);
}

// ─── Customers ─────────────────────────────────────────────────

async function seedCustomers(): Promise<string[]> {
  const provinces = ['Hà Nội', 'TP.HCM', 'Đà Nẵng', 'Hải Phòng', 'Cần Thơ', 'Khánh Hòa', 'Bình Dương'];
  const sources: CustomerSource[] = ['web', 'web', 'web', 'admin', 'pos', 'phone', 'zalo', 'fb', 'tiktok'];
  const ids: string[] = [];

  // 50 KH với mix segment
  const distributions = [
    { segment: CustomerSegment.new_cus,  count: 12, daysAgo: [0, 25],   orders: [0, 1] },
    { segment: CustomerSegment.active,   count: 18, daysAgo: [10, 60],  orders: [1, 5] },
    { segment: CustomerSegment.vip,      count: 8,  daysAgo: [60, 365], orders: [10, 25] },
    { segment: CustomerSegment.at_risk,  count: 6,  daysAgo: [60, 120], orders: [2, 4] },
    { segment: CustomerSegment.churn,    count: 5,  daysAgo: [180, 365],orders: [1, 8] },
    { segment: CustomerSegment.blacklist,count: 1,  daysAgo: [10, 30],  orders: [0, 1] },
  ];

  for (const dist of distributions) {
    for (let i = 0; i < dist.count; i++) {
      const name = nameVN();
      const totalSpentExpected = randint(0, 5_000_000) +
        (dist.segment === CustomerSegment.vip ? 15_000_000 : 0);
      const c = await prisma.customer.upsert({
        where: { email: emailFromName(name) },
        update: {},
        create: {
          name,
          email: emailFromName(name),
          phone: vnPhone(),
          gender: rand(['female', 'male', 'unknown'] as const),
          dob: new Date(randint(1970, 2005), randint(0, 11), randint(1, 28)),
          province: rand(provinces),
          source: rand(sources),
          segment: dist.segment,
          loyaltyTier: totalSpentExpected >= 50_000_000 ? LoyaltyTier.platinum
                     : totalSpentExpected >= 10_000_000 ? LoyaltyTier.gold
                     : totalSpentExpected >=  2_000_000 ? LoyaltyTier.silver
                     : LoyaltyTier.bronze,
          loyaltyPoints: randint(0, 200),
          consentEmail: Math.random() > 0.2,
          consentSms:   Math.random() > 0.4,
          consentCall:  Math.random() > 0.6,
          consentUpdatedAt: randDate(60),
          totalSpent: 0n,           // sẽ được order seed cập nhật + recompute
          orderCount: 0,
          tags: dist.segment === CustomerSegment.vip ? ['VIP'] : [],
          notes: dist.segment === CustomerSegment.blacklist ? 'Đã vào blacklist do hoàn hàng nhiều' : null,
          createdAt: randDate(dist.daysAgo[1], 0),
        },
      });
      ids.push(c.id);
    }
  }
  console.log(`✔ Seeded ${ids.length} customers`);
  return ids;
}

// ─── Vouchers ──────────────────────────────────────────────────

async function seedVouchers() {
  const samples = [
    { code: 'WELCOME10',  type: VoucherType.percent,  value: 10,        minOrder: 200_000n, usageLimit: 1000, status: VoucherStatus.active },
    { code: 'NEW50K',     type: VoucherType.amount,   value: 50_000,    minOrder: 300_000n, usageLimit: 500,  status: VoucherStatus.active },
    { code: 'FREESHIP',   type: VoucherType.shipping, value: 100,       minOrder: 0n,       usageLimit: 2000, status: VoucherStatus.active },
    { code: 'SUMMER25',   type: VoucherType.percent,  value: 25,        minOrder: 500_000n, usageLimit: 200,  status: VoucherStatus.active },
    { code: 'EXPIRED2024',type: VoucherType.percent,  value: 15,        minOrder: 200_000n, usageLimit: 500,  status: VoucherStatus.expired,
      endAt: new Date('2024-12-31') },
    { code: 'PAUSED',     type: VoucherType.amount,   value: 100_000,   minOrder: 800_000n, usageLimit: 100,  status: VoucherStatus.paused },
  ] as const;

  for (const v of samples) {
    await prisma.voucher.upsert({
      where: { code: v.code },
      update: {},
      create: {
        code: v.code,
        type: v.type, value: v.value,
        minOrder: v.minOrder, usageLimit: v.usageLimit, usedCount: 0,
        status: v.status,
        startAt: new Date(Date.now() - 90 * 86_400_000),
        endAt: 'endAt' in v && v.endAt ? v.endAt : new Date(Date.now() + 90 * 86_400_000),
        description: `Voucher seed ${v.code}`,
      },
    });
  }
  console.log(`✔ Seeded ${samples.length} vouchers`);
}

// ─── Orders ────────────────────────────────────────────────────

async function seedOrders(customerIds: string[]) {
  const products = await prisma.product.findMany({ include: { variants: true } });
  const sellable = products.filter(p => p.status === ProductStatus.active);

  const statusMix: Array<{ status: OrderStatus; payment: PaymentStatus; count: number }> = [
    { status: 'delivered',  payment: 'paid',      count: 35 },
    { status: 'shipping',   payment: 'paid',      count: 8 },
    { status: 'packing',    payment: 'paid',      count: 6 },
    { status: 'confirmed',  payment: 'pending',   count: 5 },
    { status: 'pending',    payment: 'pending',   count: 6 },
    { status: 'cancelled',  payment: 'refunded',  count: 4 },
    { status: 'returned',   payment: 'refunded',  count: 2 },
    { status: 'draft',      payment: 'pending',   count: 2 },
    { status: 'quote',      payment: 'pending',   count: 2 },
  ];

  let lastOrderSeq = 0;
  const allOrders = await prisma.order.findMany({ orderBy: { createdAt: 'desc' }, take: 1, select: { code: true } });
  if (allOrders.length) {
    const m = allOrders[0].code.match(/-(\d+)$/);
    lastOrderSeq = m ? Number(m[1]) : 0;
  }

  let total = 0;
  for (const seg of statusMix) {
    for (let i = 0; i < seg.count; i++) {
      const customerId = rand(customerIds);
      const numLines = randint(1, 4);
      const items: Array<{ productId: string; variantId: string | null; nameSnapshot: string; priceUnit: bigint; qty: number; subtotal: bigint }> = [];
      let subtotal = 0n;

      const used = new Set<string>();
      for (let j = 0; j < numLines; j++) {
        const p = rand(sellable);
        if (used.has(p.id)) continue;
        used.add(p.id);
        const v = p.variants.length ? rand(p.variants) : null;
        const qty = randint(1, 3);
        const priceUnit = (v?.price ?? p.price);
        items.push({
          productId: p.id, variantId: v?.id ?? null,
          nameSnapshot: p.name + (v ? ` (${v.size ?? v.skuSuffix})` : ''),
          priceUnit, qty,
          subtotal: priceUnit * BigInt(qty),
        });
        subtotal += priceUnit * BigInt(qty);
      }
      if (items.length === 0) continue;

      const shippingFee = subtotal >= 500_000n ? 0n : 30_000n;
      const giftWrap = Math.random() < 0.05;
      const giftWrapFee = giftWrap ? 20_000n : 0n;
      const tax = 0n;
      const orderTotal = subtotal + shippingFee + giftWrapFee + tax;

      lastOrderSeq++;
      const year = String(new Date().getFullYear()).slice(-2);
      const code = `DTX-${year}-${String(lastOrderSeq).padStart(5, '0')}`;
      const placedAt = randDate(120);
      const paidAt = seg.payment === 'paid' ? new Date(placedAt.getTime() + randint(1, 24) * 3_600_000) : null;
      const shippedAt = ['shipping', 'delivered', 'returned'].includes(seg.status) ? new Date(placedAt.getTime() + randint(1, 4) * 86_400_000) : null;
      const deliveredAt = ['delivered', 'returned'].includes(seg.status) ? new Date(placedAt.getTime() + randint(2, 7) * 86_400_000) : null;
      const cancelledAt = seg.status === 'cancelled' ? new Date(placedAt.getTime() + randint(1, 3) * 86_400_000) : null;
      const returnedAt  = seg.status === 'returned'  ? new Date((deliveredAt ?? placedAt).getTime() + randint(1, 14) * 86_400_000) : null;
      const carrier = ['shipping', 'delivered', 'returned'].includes(seg.status) ? rand(['GHN','GHTK','VTP','J&T']) : null;
      const tracking = carrier ? `${carrier}-${randint(100000000, 999999999)}` : null;

      await prisma.order.create({
        data: {
          code, customerId, status: seg.status, paymentStatus: seg.payment,
          paymentMethod: rand(['cod','vnpay','momo','bank_transfer'] as PaymentMethod[]),
          shippingMethod: rand(['standard','express','same_day','pickup'] as ShippingMethod[]),
          source: 'web' as OrderSource,
          subtotal, discountTotal: 0n, shippingFee, giftWrapFee, tax,
          total: orderTotal,
          giftWrap, giftMessage: giftWrap ? 'Chúc bạn ngày tốt lành!' : null,
          shippingAddress: { name: 'KH seed', phone: vnPhone(), line1: 'Số ' + randint(1, 999) + ' Đường Mẫu', province: 'Hà Nội', district: 'Đống Đa', ward: 'P.Láng Hạ' },
          notes: null,
          carrierName: carrier, trackingCode: tracking, trackingUrl: tracking ? `https://tracking.example/${tracking}` : null,
          placedAt, paidAt, shippedAt, deliveredAt, cancelledAt, returnedAt,
          reservedAt: ['confirmed','packing','shipping','delivered','returned'].includes(seg.status) ? placedAt : null,
          pointsEarned: seg.status === 'delivered' ? Number(orderTotal / 10_000n) : 0,
          items: { create: items },
          events: {
            create: [
              { kind: 'status_change', toState: seg.status, note: 'Seed order' },
            ],
          },
        },
      });
      total++;
    }
  }
  console.log(`✔ Seeded ${total} orders`);
}

// ─── Recompute customers (tier/segment/totalSpent từ orders thực tế) ──

async function recomputeAllCustomers() {
  const ids = await prisma.customer.findMany({ select: { id: true } });
  const { recomputeCustomer } = await import('../src/customers/loyalty.js');
  for (const c of ids) await recomputeCustomer(c.id);
  console.log(`✔ Recomputed ${ids.length} customers`);
}

// ─── Main ─────────────────────────────────────────────────────

async function main() {
  console.log('🌱 Staging seed (rich) bắt đầu...');
  console.log(`   DATABASE_URL=${(process.env.DATABASE_URL ?? '').replace(/:[^@]+@/, ':***@')}`);

  await seedCategoriesAndProducts();
  const customerIds = await seedCustomers();
  await seedVouchers();
  await seedOrders(customerIds);
  await recomputeAllCustomers();

  // Summary
  const counts = {
    products:  await prisma.product.count(),
    variants:  await prisma.productVariant.count(),
    customers: await prisma.customer.count(),
    orders:    await prisma.order.count(),
    vouchers:  await prisma.voucher.count(),
    movements: await prisma.inventoryMovement.count(),
  };
  console.log('\n✅ Seed staging hoàn tất:');
  Object.entries(counts).forEach(([k, v]) => console.log(`   • ${k.padEnd(10)}= ${v}`));
}

main()
  .catch(e => { console.error(e); process.exit(1); })
  .finally(async () => { await prisma.$disconnect(); });

