// ─── Helpers ───────────────────────────────────────────────────

function rand<T>(arr: T[]): T { return arr[Math.floor(Math.random() * arr.length)]; }
function randint(min: number, max: number) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function randDate(daysBack: number, daysForward = 0): Date {
  const now = Date.now();
  return new Date(now - randint(0, daysBack) * 86_400_000 + randint(0, daysForward) * 86_400_000);
}
function vnPhone() { return '09' + String(randint(10000000, 99999999)); }
function nameVN() {
  const first = ['Nguyễn','Trần','Lê','Phạm','Hoàng','Vũ','Đặng','Bùi','Đỗ','Hồ','Ngô','Dương'];
  const mid   = ['Thị','Văn','Hữu','Minh','Anh','Đức','Quốc','Thanh','Hồng','Tuấn'];
  const last  = ['An','Bình','Châu','Dung','Giang','Hà','Khánh','Linh','Mai','Nga','Oanh','Phúc','Quang','Rạng','Sơn','Thảo','Uyên','Vy'];
  return `${rand(first)} ${rand(mid)} ${rand(last)}`;
}
function emailFromName(n: string) {
  return n.normalize('NFD').replace(/[\u0300-\u036f]/g, '')
          .toLowerCase().replace(/\s+/g, '.') + randint(1, 999) + '@example.com';
}

