99	<script src="assets/admin-data.js"></script>
100	<script src="assets/admin-data-ext.js"></script>
101	<script src="assets/admin-shell.js"></script>
102	<script src="assets/admin-rbac.js"></script>
103	<script>
104	(function(){
105	  const S = window.DTX_ADMIN_ARTICLES;
106	  const F = window.DTX_ADMIN_FMT;
107	  const state = { q:'', status:'', cat:'' };
108	
109	  function statusLabel(s){ return { draft:'Bản nháp', scheduled:'Đã lên lịch', published:'Đã publish', archived:'Lưu trữ' }[s] || s; }
110	  function statusClass(s){ return { published:'ok', scheduled:'info', draft:'warn', archived:'muted' }[s] || 'muted'; }
111	
112	  function render(){
113	    const all = S.all();
114	    document.getElementById('artCount').textContent = all.length;
115	    // categories
116	    const cats = new Set();
117	    all.forEach(a => a.category && cats.add(a.category));
118	    const catSel = document.getElementById('artCat');
119	    const first = catSel.querySelector('option'); catSel.innerHTML=''; catSel.appendChild(first);
120	    [...cats].sort().forEach(c => {
121	      const o = document.createElement('option'); o.value=c; o.textContent=c;
122	      if (c===state.cat) o.selected=true; catSel.appendChild(o);
123	    });
124	
125	    const q = state.q.trim().toLowerCase();
126	    const list = all.filter(a => {
127	      if (q && !(a.title.toLowerCase().includes(q) || (a.author||'').toLowerCase().includes(q) || a.category.toLowerCase().includes(q))) return false;
128	      if (state.status && a.status !== state.status) return false;
129	      if (state.cat && a.category !== state.cat) return false;
130	      return true;
131	    });
132	    const grid = document.getElementById('artGrid');
133	    const empty = document.getElementById('artEmpty');
134	    if (!list.length) { grid.innerHTML=''; empty.hidden=false; return; }
135	    empty.hidden = true;
136	    grid.innerHTML = list.map(a => `
137	      <article class="art-card" data-id="${a.id}">
138	        <header>
139	          <span class="chip">${a.category || 'Chưa phân loại'}</span>
140	          <span class="badge ${statusClass(a.status)}">${statusLabel(a.status)}</span>
141	        </header>
142	        <h3>${a.title}</h3>
143	        <p>${a.excerpt || '—'}</p>
144	        <footer>
145	          <small class="muted"><i class="fa-solid fa-user"></i> ${a.author} · ${a.publishedAt ? F.date(a.publishedAt) : 'Chưa publish'} · <i class="fa-solid fa-eye"></i> ${a.views.toLocaleString('vi-VN')}</small>
146	          <div>
147	            <button class="icon-btn" data-edit="${a.id}"><i class="fa-solid fa-pen"></i></button>
148	            <button class="icon-btn" data-del="${a.id}"><i class="fa-solid fa-trash"></i></button>
149	          </div>
150	        </footer>
151	      </article>
152	    `).join('');
153	  }
154	
155	  const modal = document.getElementById('artModal');
156	  const form = document.getElementById('artForm');
157	  function openModal(a){
158	    document.getElementById('artModalTitle').textContent = a ? 'Sửa bài viết' : 'Viết bài mới';
159	    form.reset();
160	    if (a) {
161	      for (const [k,v] of Object.entries(a)) {
162	        if (form[k]) form[k].value = v ?? '';
163	      }
164	    }
165	    modal.hidden = false;
166	    setTimeout(()=>form.title.focus(), 50);
167	  }
168	  function closeModal(){ modal.hidden = true; }
169	  modal.addEventListener('click', e => {
170	    if (e.target.matches('[data-close-modal]') || e.target === modal) closeModal();
171	  });
172	  form.addEventListener('submit', e => {
173	    e.preventDefault();
174	    const data = Object.fromEntries(new FormData(form));
175	    if (!data.slug) {
176	      data.slug = data.title.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'').slice(0,80);
177	    }
178	    if (data.id) { S.update(data.id, data); window.admToast?.('Đã cập nhật bài viết', 'ok'); }
179	    else { delete data.id; S.create(data); window.admToast?.('Đã tạo bài viết', 'ok'); }
180	    closeModal(); render();
181	  });
182	
183	  document.getElementById('btnArtNew').addEventListener('click', () => openModal(null));
184	  document.getElementById('artGrid').addEventListener('click', e => {
185	    const edit = e.target.closest('[data-edit]');
186	    if (edit) { openModal(S.get(edit.dataset.edit)); }
187	    const del = e.target.closest('[data-del]');
188	    if (del) {
189	      const a = S.get(del.dataset.del);
190	      if (a && confirm(`Xoá "${a.title}"?`)) { S.remove(a.id); render(); window.admToast?.('Đã xoá', 'ok'); }
191	    }
192	  });
193	  document.getElementById('btnArtReset').addEventListener('click', () => {
194	    if (confirm('Đặt lại bài viết về seed?')) { S.reset(); render(); window.admToast?.('Reset OK', 'ok'); }
195	  });
196	  document.getElementById('artQ').addEventListener('input', e => { state.q = e.target.value; render(); });
197	  document.getElementById('artStatus').addEventListener('change', e => { state.status = e.target.value; render(); });
198	  document.getElementById('artCat').addEventListener('change', e => { state.cat = e.target.value; render(); });
199	
200	  window.addEventListener('dtx:articles-updated', render);
201	  window.addEventListener('storage', e => { if (e.key?.startsWith('dtx_admin_articles')) render(); });
202	  render();
203	})();
204	</script>
205	</body></html>
