  getItem(k){ return k in this.s ? this.s[k] : null; }
  setItem(k,v){ this.s[k] = String(v); }
  removeItem(k){ delete this.s[k]; }
}
const events = {};
const evTarget = {
  addEventListener: (n, fn) => { (events[n] = events[n]||[]).push(fn); },
  dispatchEvent: ev => { (events[ev.type]||[]).forEach(fn => fn(ev)); return true; },
};

class FakeElement {
  constructor(tag) {
    this.tagName = tag;
    this.children = [];
    this.attrs = {};
    this.style = {};
    this.dataset = {};
    this.classList = { add: ()=>{}, remove: ()=>{}, toggle: ()=>{}, contains: ()=>false };
