// Load admin-articles.html and admin-pages.html via jsdom + report errors
const path = require('path');
const fs = require('fs');
const { JSDOM, ResourceLoader } = require('jsdom');

const ROOT = '/Users/tranquy/Downloads/thư mục không có tiêu đề/detoxblanc-clone';

class FileLoader extends ResourceLoader {
  fetch(url, opts) {
    if (url.startsWith('file://')) {
      const p = decodeURIComponent(url.replace('file://', ''));
      try { return Promise.resolve(Buffer.from(fs.readFileSync(p))); }
      catch (e) { return Promise.reject(e); }
    }
    return super.fetch(url, opts);
  }
}

async function loadPage(name) {
  const file = path.join(ROOT, name);
  const html = fs.readFileSync(file, 'utf8');
  const errors = [];
  const consoleMsgs = [];
  const baseUrl = 'file://' + ROOT.replace(/ /g, '%20').replace(/ư/g,'ư') + '/';

  const dom = new JSDOM(html, {
    url: 'file://' + file,
    runScripts: 'dangerously',
    resources: new FileLoader(),
    pretendToBeVisual: true,
    virtualConsole: (() => {
      const { VirtualConsole } = require('jsdom');
      const vc = new VirtualConsole();
      vc.on('error', e => errors.push('error: ' + (e.message || e)));
      vc.on('warn',  m => consoleMsgs.push('warn: '  + m));
      vc.on('log',   m => consoleMsgs.push('log: '   + m));
      vc.on('jsdomError', e => errors.push('jsdomError: ' + (e.message || e)));
      return vc;
    })(),
  });

  // Wait a bit for async scripts to load and run
  await new Promise(r => setTimeout(r, 800));

  const doc = dom.window.document;
  return {
    name,
    errors,
    consoleMsgs: consoleMsgs.slice(-10),
    bodyHasContent: !!doc.body && doc.body.children.length > 0,
    pageTitle: doc.title,
    h1: doc.querySelector('h1')?.textContent || null,
    grids: {
      pgGrid: doc.getElementById('pgGrid')?.children.length ?? null,
      artGrid: doc.getElementById('artGrid')?.children.length ?? null,
    },
    btns: {
      btnArtNew:  !!doc.getElementById('btnArtNew'),
      btnArtReset:!!doc.getElementById('btnArtReset'),
      btnPgNew:   !!doc.getElementById('btnPgNew'),
      btnPgReset: !!doc.getElementById('btnPgReset'),
    },
    DTX: {
      hasArticles: typeof dom.window.DTX_ADMIN_ARTICLES,
      hasFmt:      typeof dom.window.DTX_ADMIN_FMT,
      hasShell:    !!dom.window.document.querySelector('[data-adm-shell]'),
      shellRendered: dom.window.document.querySelector('[data-adm-shell]')?.children.length || 0,
    },
  };
}

(async () => {
  for (const name of ['admin-articles.html', 'admin-pages.html']) {
    console.log('\n========================');
    console.log('=== ' + name + ' ===');
    console.log('========================');
    try {
      const r = await loadPage(name);
      console.log(JSON.stringify(r, null, 2));
    } catch (e) {
      console.log('FAILED: ' + e.message);
      console.log(e.stack);
    }
  }
})();

