// Load admin-articles.html / admin-pages.html with manual script injection
const path = require('path');
const fs = require('fs');
const { JSDOM, VirtualConsole } = require('jsdom');

const ROOT = '/Users/tranquy/Downloads/thư mục không có tiêu đề/detoxblanc-clone';

async function loadPage(name) {
  const file = path.join(ROOT, name);
  let html = fs.readFileSync(file, 'utf8');

  // Inline external scripts so jsdom can run them without network
  html = html.replace(/<script src="([^"]+)"><\/script>/g, (m, src) => {
    try {
      const code = fs.readFileSync(path.join(ROOT, src), 'utf8');
      return `<script data-from="${src}">${code}</script>`;
    } catch (e) { return `<!-- can't inline ${src}: ${e.message} -->`; }
  });

  const errors = [];
  const logs = [];
  const vc = new VirtualConsole();
  vc.on('error', e => errors.push('error: ' + (e.message || e)));
  vc.on('warn',  m => logs.push('warn: '  + m));
  vc.on('log',   m => logs.push('log: '   + m));
  vc.on('jsdomError', e => errors.push('jsdomError: ' + (e.message || e) + (e.stack ? '\n  ' + e.stack.split('\n').slice(0,4).join('\n  ') : '')));

  const dom = new JSDOM(html, {
    url: 'http://localhost/' + name,
    runScripts: 'dangerously',
    pretendToBeVisual: true,
    virtualConsole: vc,
  });

  // Wait for IIFE / DOMContentLoaded handlers
  await new Promise(r => setTimeout(r, 600));

  const doc = dom.window.document;
  return {
    name,
    errors,
    logs: logs.slice(-15),
    pageTitle: doc.title,
    h1: doc.querySelector('h1')?.textContent || null,
