      btnPgReset:  !!doc.getElementById('btnPgReset'),
    },
    DTX: {
      hasArticles:   typeof dom.window.DTX_ADMIN_ARTICLES,
      hasFmt:        typeof dom.window.DTX_ADMIN_FMT,
      shellMounted:  dom.window.document.querySelector('[data-adm-shell]')?.children.length || 0,
      permsResolved: dom.window.DTX_ADMIN_PERMS?.perms || null,
