const fs = require('fs');
const path = require('path');
const { JSDOM, VirtualConsole } = require('jsdom');

const ROOT = '/Users/tranquy/Downloads/thư mục không có tiêu đề/detoxblanc-clone';

const SCRIPTS = [
  'assets/admin-data.js',
  'assets/admin-data-ext.js',
  'assets/admin-shell.js',
  'assets/admin-rbac.js',
];

async function tryLoad(html, label) {
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => {
    let msg = (e.message || String(e));
    if (e.detail) msg += ' | detail: ' + (e.detail.stack || e.detail.message || e.detail);
    errors.push(msg);
  });
  vc.on('error', e => errors.push('console.error: ' + (e.message || e)));

  const dom = new JSDOM(html, { runScripts: 'dangerously', virtualConsole: vc });
  await new Promise(r => setTimeout(r, 200));
  return { label, errors };
}

(async () => {
  // 1. Load each script individually
  for (const s of SCRIPTS) {
    const code = fs.readFileSync(path.join(ROOT, s), 'utf8');
    const html = `<!doctype html><html><body><script>${code}</script></body></html>`;
    const r = await tryLoad(html, s);
    console.log('--- ' + r.label + ' ---');
    if (r.errors.length) r.errors.forEach(e => console.log('  ✗ ' + e));
    else console.log('  ✓ no errors');
  }

  // 2. Load all 4 in sequence
  console.log('\n--- ALL 4 IN SEQUENCE ---');
  const concat = SCRIPTS.map(s => fs.readFileSync(path.join(ROOT, s), 'utf8')).join('\n;\n');
  const html = `<!doctype html><html><body><div data-adm-shell></div><script>${concat}</script></body></html>`;
  const r = await tryLoad(html, 'concat');
  if (r.errors.length) r.errors.forEach(e => console.log('  ✗ ' + e));
  else console.log('  ✓ no errors');

  // 3. Load each script as <script src=...> (separately, like in browser)
  console.log('\n--- 4 SEPARATE <script> TAGS ---');
  const tags = SCRIPTS.map(s => {
    const code = fs.readFileSync(path.join(ROOT, s), 'utf8');
    return `<script>${code}</script>`;
  }).join('\n');
  const html3 = `<!doctype html><html><body data-adm-page="articles"><div data-adm-shell data-crumbs='[{"label":"Admin"}]'></div>${tags}</body></html>`;
  const r3 = await tryLoad(html3, 'separate-tags');
  if (r3.errors.length) r3.errors.forEach(e => console.log('  ✗ ' + e));
  else console.log('  ✓ no errors');
})();

