// Load page via actual HTTP from Python server on 8080 — true browser-like
const { JSDOM, VirtualConsole } = require('jsdom');

async function loadReal(name) {
  const url = 'http://127.0.0.1:8080/' + name;
  const errors = [];
  const logs = [];
  const vc = new VirtualConsole();
  vc.on('error', e => errors.push('error: ' + (e.message || e) + (e.stack ? '\n  ' + e.stack.split('\n').slice(0,4).join('\n  ') : '')));
  vc.on('warn',  m => logs.push('warn: '  + m));
  vc.on('log',   m => logs.push('log: '   + m));
  vc.on('jsdomError', e => {
    let msg = (e.message || String(e));
    if (e.detail?.stack) msg += '\n  ' + e.detail.stack.split('\n').slice(0,8).join('\n  ');
    errors.push('jsdomError: ' + msg);
  });

  const dom = await JSDOM.fromURL(url, {
    runScripts: 'dangerously',
    pretendToBeVisual: true,
    virtualConsole: vc,
  });

  await new Promise(r => setTimeout(r, 1500));

  const doc = dom.window.document;
  return {
    name, errors, logs: logs.slice(-15),
    h1: doc.querySelector('h1')?.textContent || null,
    sidebar: !!doc.querySelector('.adm-sidebar'),
    sidebarItems: doc.querySelectorAll('.adm-sidebar a').length,
    grids: {
      pgGrid:  doc.getElementById('pgGrid')?.children.length ?? null,
      artGrid: doc.getElementById('artGrid')?.children.length ?? null,
    },
    btns: {
      btnArtNew:   !!doc.getElementById('btnArtNew'),
      btnArtReset: !!doc.getElementById('btnArtReset'),
      btnPgNew:    !!doc.getElementById('btnPgNew'),
      btnPgReset:  !!doc.getElementById('btnPgReset'),
    },
    DTX_ADMIN: typeof dom.window.DTX_ADMIN,
    DTX_ARTICLES: typeof dom.window.DTX_ADMIN_ARTICLES,
    permsResolved: dom.window.DTX_ADMIN_PERMS?.perms || null,
  };
}

(async () => {
  for (const name of ['admin-articles.html', 'admin-pages.html']) {
    console.log('\n===== ' + name + ' =====');
    try {
      const r = await loadReal(name);
      console.log(JSON.stringify(r, null, 2));
    } catch (e) {
      console.log('FAILED: ' + e.message);
    }
  }
})();

