   Dùng bởi: admin-articles, admin-audit, admin-customers, admin-inventory,
             admin-orders, admin-users, admin-vouchers
   (Class system mới hơn .adm-modal/.adm-modal-card có rules riêng)
   ==================================================================== */
.modal-backdrop{
  position:fixed; inset:0; z-index:1000;
  background:rgba(15,23,42,.55); backdrop-filter:blur(2px);
  display:flex; align-items:center; justify-content:center;
  padding:20px; overflow-y:auto;
  animation:modalFadeIn .15s ease-out;
}
.modal-backdrop[hidden]{ display:none }
@keyframes modalFadeIn{ from{ opacity:0 } to{ opacity:1 } }

.modal{
  background:var(--a-card); border-radius:14px;
  border:1px solid var(--a-line);
  box-shadow:0 20px 50px rgba(0,0,0,.18), 0 4px 12px rgba(0,0,0,.06);
  width:560px; max-width:calc(100% - 16px); max-height:calc(100vh - 40px);
  display:flex; flex-direction:column;
  animation:modalSlideIn .18s cubic-bezier(.2,.8,.2,1);
}
@keyframes modalSlideIn{
  from{ transform:translateY(8px) scale(.98); opacity:0 }
  to  { transform:translateY(0) scale(1);     opacity:1 }
}
.modal.wide{ max-width:960px; width:calc(100% - 32px) }
.modal > header{
  display:flex; align-items:center; justify-content:space-between;
  padding:14px 18px; border-bottom:1px solid var(--a-line);
  flex:0 0 auto;
}
.modal > header h3{ margin:0; font-size:15.5px; font-weight:600 }
.modal > footer{
  padding:12px 18px; border-top:1px solid var(--a-line);
  display:flex; gap:8px; justify-content:flex-end;
  flex:0 0 auto; background:var(--a-card);
  position:sticky; bottom:0;
}
.modal .modal-body{
  padding:16px 18px; overflow-y:auto; flex:1 1 auto;
  display:flex; flex-direction:column; gap:12px;
}
.modal .modal-body h4{
  margin:14px 0 6px; font-size:13px; color:var(--a-ink-2);
  text-transform:uppercase; letter-spacing:.04em;
}
.modal label{ display:flex; flex-direction:column; gap:4px; font-size:13.5px }
.modal label > span{ font-size:12.5px; font-weight:500; color:var(--a-ink-2) }
.modal label input[type=text],
.modal label input[type=email],
.modal label input[type=tel],
.modal label input[type=number],
.modal label input[type=date],
.modal label input[type=url],
.modal label input:not([type]),
.modal label textarea,
.modal label select{
  width:100%; padding:8px 10px; border:1px solid var(--a-line);
  border-radius:7px; background:var(--a-surface); color:var(--a-ink);
  font:inherit; font-size:13.5px; transition:border-color .12s, box-shadow .12s;
}
.modal label input:focus, .modal label textarea:focus, .modal label select:focus{
  outline:0; border-color:var(--a-brand); box-shadow:0 0 0 3px var(--a-brand-soft);
}
.modal label textarea{ resize:vertical; min-height:60px }
.modal label input.mono, .modal label textarea.mono{ font-family:'JetBrains Mono', ui-monospace, monospace; font-size:12.5px }

@media (max-width:560px){
  .modal{ width:100%; max-width:none }
  .modal-backdrop{ padding:0; align-items:flex-end }
  .modal{ border-radius:14px 14px 0 0 }
}

/* ====================================================================
   STAT cards (KPI grid trên mỗi page)
   Dùng bởi: 10 trang admin
   ==================================================================== */
.stat-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(180px, 1fr));
  gap:12px;
  margin-bottom:8px;
}
.stat-card{
  background:var(--a-card); border:1px solid var(--a-line);
  border-radius:10px; padding:14px 16px;
  display:flex; flex-direction:column; gap:4px;
  transition:border-color .12s ease, transform .08s ease;
}
.stat-card:hover{ border-color:var(--a-line-strong, var(--a-line)) }
.stat-card .lbl{
  font-size:12px; color:var(--a-ink-3); font-weight:500;
  text-transform:uppercase; letter-spacing:.04em;
}
.stat-card strong{
  font-size:22px; font-weight:700; color:var(--a-ink);
  font-family:'JetBrains Mono', ui-monospace, monospace; letter-spacing:-.01em;
  line-height:1.15;
}
.stat-card small{ font-size:11.5px; color:var(--a-ink-3) }

/* Empty state shared */
.empty.card{
  background:var(--a-card); border:1px dashed var(--a-line);
  border-radius:10px; padding:32px 20px; text-align:center;
  color:var(--a-ink-3);
}

/* Tag pill (used in subscriber/article tag list) */
.tag{
  display:inline-block; padding:2px 8px; border-radius:5px;
  background:var(--a-n100); color:var(--a-ink-2);
  font-size:11.5px; font-weight:500; margin-right:4px;
}
html[data-theme="dark"] .tag{ background:rgba(255,255,255,.06) }

