const { JSDOM, VirtualConsole } = require('jsdom');

async function checkModal(name, openBtnId) {
  const url = 'http://127.0.0.1:8080/' + name;
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('error', e => errors.push('error: ' + (e.message || e)));
  vc.on('jsdomError', e => {
    if (/matchMedia/.test(e.message || '')) return; // jsdom limitation
    errors.push('jsdomError: ' + (e.message || String(e)));
  });

  const dom = await JSDOM.fromURL(url, {
    runScripts: 'dangerously', resources: 'usable',
    pretendToBeVisual: true, virtualConsole: vc,
  });
  await new Promise(r => setTimeout(r, 1500));

  const w = dom.window;
  const d = w.document;

  // Check stat-grid CSS applied (inspect computed style — jsdom limited but checking display works)
  const statGrid = d.querySelector('.stat-grid');
  const statCard = d.querySelector('.stat-card');

  // Check modal markup
  const modal = d.querySelector('.modal-backdrop, .adm-modal');
  const isModalHiddenInitial = modal?.hidden;

  // Click the open button
  const btn = openBtnId ? d.getElementById(openBtnId) : null;
  if (btn) btn.click();
  await new Promise(r => setTimeout(r, 100));
  const isModalOpenedAfterClick = modal && !modal.hidden;

  return {
    name, errors,
    h1: d.querySelector('h1')?.textContent,
    sidebarItems: d.querySelectorAll('.adm-sidebar a').length,
    statCardCount: d.querySelectorAll('.stat-card').length,
    contentRendered: {
      pgGrid:  d.getElementById('pgGrid')?.children.length ?? null,
      artGrid: d.getElementById('artGrid')?.children.length ?? null,
    },
    modalHasBaseClass: !!modal,
    modalHiddenInitial: isModalHiddenInitial,
    modalOpenedAfterClick: isModalOpenedAfterClick,
    btnFound: !!btn,
  };
}

(async () => {
  for (const [name, btnId] of [
    ['admin-articles.html', 'btnArtNew'],
    ['admin-pages.html',    'btnPgNew'],
  ]) {
    console.log('\n===== ' + name + ' =====');
    try {
      const r = await checkModal(name, btnId);
      console.log(JSON.stringify(r, null, 2));
    } catch (e) {
      console.log('FAILED: ' + e.message);
    }
  }
})();
EOF
