const { JSDOM, VirtualConsole } = require('jsdom');

async function check(name) {
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => {
    if (/matchMedia|form\.title\.focus/.test(e.message || '')) return;
    errors.push((e.message || String(e)).slice(0,200));
  });
  const dom = await JSDOM.fromURL('http://127.0.0.1:8080/' + name, {
    runScripts: 'dangerously', resources: 'usable',
    pretendToBeVisual: true, virtualConsole: vc,
  });
  await new Promise(r => setTimeout(r, 1500));
  const d = dom.window.document;
  const modal = d.querySelector('.modal-backdrop, .adm-modal');
  return {
    name,
    errors,
    h1: d.querySelector('h1')?.textContent || null,
    sidebar: d.querySelectorAll('.adm-sidebar a').length,
    statCards: d.querySelectorAll('.stat-card').length,
    modalEl: !!modal,
    modalCSS: modal ? (dom.window.getComputedStyle(modal).position || 'unknown') : '—',
  };
}

(async () => {
  const pages = [
    'admin-articles.html', 'admin-pages.html',
    'admin-audit.html', 'admin-customers.html', 'admin-inventory.html',
    'admin-orders.html', 'admin-users.html', 'admin-vouchers.html',
    'admin-newsletter.html', 'admin-collections.html', 'admin-returns.html',
    'admin-reviews.html', 'admin-reports.html', 'admin-settings.html',
  ];
  for (const p of pages) {
    try {
      const r = await check(p);
      const ok = r.h1 && r.sidebar >= 15 && (!r.errors.length);
      const mark = ok ? '✓' : '✗';
      console.log(`${mark}  ${p.padEnd(28)} h1="${r.h1}" sidebar=${r.sidebar} stat=${r.statCards} modalCSS=${r.modalCSS} errs=${r.errors.length}`);
      if (r.errors.length) r.errors.forEach(e => console.log('     • ' + e));
    } catch (e) {
      console.log(`✗  ${p.padEnd(28)} FAILED: ${e.message}`);
    }
  }
})();
