async function clickFlow(name, openBtnId, fillFn, saveBtnId) {
  const errors = [];
  const vc = new VirtualConsole();
  vc.on('jsdomError', e => {
    if (/matchMedia/.test(e.message || '')) return;
    errors.push((e.message || String(e)).slice(0, 200));
  });
  vc.on('error', e => errors.push('console.error: ' + (e.message || e)));

  const dom = await JSDOM.fromURL('http://127.0.0.1:8080/' + name, {
    runScripts: 'dangerously', resources: 'usable',
    pretendToBeVisual: true, virtualConsole: vc,
  });
  await new Promise(r => setTimeout(r, 1500));
  const w = dom.window, d = w.document;

  const phases = {};

  // Phase 1: initial render
  phases.initial = {
    h1: d.querySelector('h1')?.textContent,
    sidebar: d.querySelectorAll('.adm-sidebar a').length,
    statCards: d.querySelectorAll('.stat-card').length,
    cards: (d.getElementById('artGrid') || d.getElementById('pgGrid'))?.children.length || 0,
    modalHidden: d.getElementById(name === 'admin-articles.html' ? 'artEditor' : 'pgEditor')?.hidden,
  };

  // Phase 2: click "New" button
  const btn = d.getElementById(openBtnId);
  if (btn) btn.click();
  await new Promise(r => setTimeout(r, 100));
  const modalEl = d.getElementById(name === 'admin-articles.html' ? 'artEditor' : 'pgEditor');
  phases.afterClickNew = {
    btnFound: !!btn,
    modalHidden: modalEl?.hidden,
    modalDisplay: modalEl ? w.getComputedStyle(modalEl).display : null,
    inputFocused: d.activeElement?.id || null,
  };

  // Phase 3: fill form + save
  if (fillFn && saveBtnId) {
    fillFn(d);
    const saveBtn = d.getElementById(saveBtnId);
    if (saveBtn) saveBtn.click();
    await new Promise(r => setTimeout(r, 200));
    phases.afterSave = {
      saveBtnFound: !!saveBtn,
      modalHidden: modalEl?.hidden,
      cardsAfter: (d.getElementById('artGrid') || d.getElementById('pgGrid'))?.children.length || 0,
    };
  }

  // Phase 4: click row "edit" button
  const firstCard = d.querySelector('.ar-card, .pg-item');
  if (firstCard) {
    const editBtn = firstCard.querySelector('[data-act="edit"]');
    if (editBtn) editBtn.click();
    await new Promise(r => setTimeout(r, 100));
    phases.afterEdit = {
      cardFound: true,
      editBtnFound: !!editBtn,
      modalAfterEdit: modalEl?.hidden,
    };
  }

  return { name, errors, phases };
}

(async () => {
  console.log('\n===== admin-articles.html =====');
  console.log(JSON.stringify(await clickFlow(
    'admin-articles.html',
    'btnArtNew',
    (d) => {
      d.getElementById('aeTitle').value = 'TEST: Bài viết mới từ click test';
      d.getElementById('aeBody').value  = '# Test\n\nNội dung test';
      d.getElementById('aeAuthor').value = 'Test Bot';
      d.getElementById('aeCategory').value = 'Hướng dẫn';
    },
    'aeSave'
  ), null, 2));

  console.log('\n===== admin-pages.html =====');
  console.log(JSON.stringify(await clickFlow(
    'admin-pages.html',
    'btnPgNew',
    (d) => {
      d.getElementById('peTitle').value = 'TEST: Trang test';
      d.getElementById('peSlug').value  = 'test-page';
      d.getElementById('peBody').value  = '# Test\n\nNội dung';
    },
    'peSave'
  ), null, 2));
})();

