# Nginx config — single-container FE + API reverse proxy
# Vars resolved at startup (envsubst): $PORT, $API_UPSTREAM

server {
    listen ${PORT} default_server;
    listen [::]:${PORT} default_server;
    server_name _;

    root /usr/share/nginx/html;
    index index.html;
    charset utf-8;

    # ─── Security headers (chung cho mọi response) ──
    add_header X-Content-Type-Options "nosniff" always;
    add_header Referrer-Policy "strict-origin-when-cross-origin" always;
    add_header Permissions-Policy "geolocation=(), microphone=(), camera=()" always;

    # Public site CSP nới lỏng (cần inline scripts/styles cho admin)
    add_header Content-Security-Policy "default-src 'self'; script-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://fonts.googleapis.com; style-src 'self' 'unsafe-inline' https://cdnjs.cloudflare.com https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com https://cdnjs.cloudflare.com; img-src 'self' data: https:; connect-src 'self' https:;" always;

    # ─── Healthcheck cho Cloud Run / load balancer ──
    location = /healthz {
        access_log off;
        add_header Content-Type "text/plain";
        return 200 "ok\n";
    }

    # ─── Reverse proxy /v1/* → API service ──
    # API_UPSTREAM ví dụ: http://detoxblanc-api:3000 hoặc URL Cloud Run nội bộ
    location /v1/ {
        proxy_pass         ${API_UPSTREAM}/v1/;
        proxy_http_version 1.1;
        proxy_set_header   Host              $host;
        proxy_set_header   X-Real-IP         $remote_addr;
        proxy_set_header   X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header   X-Forwarded-Proto $scheme;
        proxy_set_header   X-Forwarded-Host  $host;
        proxy_set_header   Connection        "";
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
        proxy_buffering    off;

        # CSRF cookie cần Set-Cookie chuyển đúng
        proxy_cookie_path  /  "/; SameSite=Lax";
    }

    # ─── Admin URL clean rewrites: /admin/orders → /admin-orders.html ──
    # Header bảo mật cho admin paths
    location ^~ /admin/ {
        add_header X-Frame-Options "DENY" always;
        add_header X-Robots-Tag "noindex, nofollow, noarchive, nosnippet" always;
        add_header Cache-Control "no-store, no-cache, must-revalidate" always;

        # Map /admin/<page> → /admin-<page>.html
        rewrite ^/admin/?$                /admin.html              last;
        rewrite ^/admin/login$            /admin-login.html        last;
        rewrite ^/admin/orders$           /admin-orders.html       last;
        rewrite ^/admin/customers$        /admin-customers.html    last;
        rewrite ^/admin/inventory$        /admin-inventory.html    last;
        rewrite ^/admin/products$         /admin-products.html     last;
        rewrite ^/admin/products/edit$    /admin-product-edit.html last;
        rewrite ^/admin/collections$      /admin-collections.html  last;
        rewrite ^/admin/articles$         /admin-articles.html     last;
        rewrite ^/admin/pages$            /admin-pages.html        last;
        rewrite ^/admin/reviews$          /admin-reviews.html      last;
        rewrite ^/admin/newsletter$       /admin-newsletter.html   last;
        rewrite ^/admin/vouchers$         /admin-vouchers.html     last;
        rewrite ^/admin/returns$          /admin-returns.html      last;
        rewrite ^/admin/reports$          /admin-reports.html      last;
        rewrite ^/admin/audit$            /admin-audit.html        last;
        rewrite ^/admin/users$            /admin-users.html        last;
        rewrite ^/admin/settings$         /admin-settings.html     last;
        rewrite ^/admin/dev$              /admin-dev.html          last;
        return 404;
    }

    # ─── Bảo vệ direct file admin-*.html (vẫn cho phép, nhưng add header) ──
    location ~* ^/admin-[a-z0-9-]+\.html$ {
        add_header X-Frame-Options "DENY" always;
        add_header X-Robots-Tag "noindex, nofollow, noarchive, nosnippet" always;
        add_header Cache-Control "no-store, no-cache, must-revalidate" always;
        try_files $uri =404;
    }

    # ─── Static asset cache mạnh ──
    location /assets/ {
        access_log off;
        expires 1y;
        add_header Cache-Control "public, max-age=31536000, immutable";
    }

    location ~* \.(jpg|jpeg|png|webp|svg|ico|woff2|woff|ttf)$ {
        expires 30d;
        add_header Cache-Control "public, max-age=2592000";
    }

    # ─── HTML — cache ngắn để dễ rollout ──
    location ~* \.html$ {
        add_header Cache-Control "public, max-age=300, must-revalidate";
        try_files $uri =404;
    }

    # ─── Clean URL cho public pages: /about → /about.html ──
    location / {
        try_files $uri $uri.html $uri/ /index.html;
    }

    # ─── Lỗi ──
    error_page 404 /404.html;
    location = /404.html { internal; }
}

