        add_header Cache-Control "public, max-age=300, must-revalidate";
        try_files $uri =404;
    }

    # ─── Clean URL cho public pages: /about → /about.html ──
    location / {
        try_files $uri $uri.html $uri/ /index.html;
    }

    # ─── Lỗi ──
    error_page 404 /404.html;
    location = /404.html { internal; }
}

