          alert(msg);
        }
      })();
      return false;
    }

    // ─── Demo / local mode (giữ flow cũ) ───────────────────
    setTimeout(() => {
      try { sessionStorage.setItem('dtx_admin_session', JSON.stringify({ email, at: Date.now() })); } catch(_){}
      btn.innerHTML = '<i class="fa-solid fa-check"></i> Thành công · đang chuyển';
      location.href = 'admin.html';
    }, 1200);
    return false;
  }

  function admSso(provider){
