# Generate scrypt-like password hash via Node
node -e "
const crypto = require('crypto');
const password = '$PWD';
const salt = crypto.randomBytes(8);
// Use simple SHA-256 hash
const hash = crypto.createHash('sha256').update(password + salt.toString('base64')).digest();
console.log('hash:', hash.toString('base64'));
console.log('salt:', salt.toString('base64'));
" > /tmp/_hash.txt
HASH=$(grep "^hash:" /tmp/_hash.txt | cut -d' ' -f2)
SALT=$(grep "^salt:" /tmp/_hash.txt | cut -d' ' -f2)

