// Giả lập đăng nhập
function admLogin(e){
  e.preventDefault();
  const email = document.getElementById('adm-email').value.trim();
  const pass  = document.getElementById('adm-pass').value;
  const otp   = [...document.querySelectorAll('.adm-otp input')].map(i => i.value).join('');

  if (!email.endsWith('@detoxblanc.com')){
    alert('Email phải thuộc miền @detoxblanc.com'); return false;
  }
  if (pass.length < 10){
    alert('Mật khẩu tối thiểu 10 ký tự'); return false;
  }
  if (otp.length !== 6){
    alert('Vui lòng nhập đủ 6 chữ số mã xác thực'); return false;
  }
  const btn = e.target.querySelector('.adm-btn[type="submit"]');
  btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Đang xác thực...';
  btn.disabled = true;

  // ─── Production: Firebase Auth login ───────────────────
  // Khi env-detect bật Firebase mode → dùng Auth thật
  if (window.DTX_AUTH?.isFirestore || window.DTX_FIREBASE?.enabled) {
    (async () => {
      try {
        // OTP bị bỏ qua trong v1.0 — Firebase Auth tự đảm nhiệm 2FA nếu enable
        const wait = () => new Promise(r => {
          if (window.DTX_AUTH?.isFirestore) return r();
          window.addEventListener('dtx:firebase-ready', r, { once: true });
        });

